pub const DaResult = enum(c_int) {
    ok = 0,
    not_found = 1,
    invalid_state = 2,
    invalid_arg = 3,
    internal = 4,
    oom = 5,
    not_implemented = 6,
};

pub const DaOrderStatus = enum(c_int) {
    pending = 0,
    clarifying = 1,
    planned = 2,
    approved = 3,
    running = 4,
    done = 5,
    failed = 6,
    rejected = 7,
    awaiting_approval = 8,
    /// TERMINAL-STATE-DESIGN-2026-07-12: añadido al final — nunca renumerar los
    /// valores anteriores, son parte de la ABI C consumida por la IDE Qt/VSCode.
    /// Sin call-site que lo emita todavía (ver superagent.OrderStatus.cancelled).
    cancelled = 9,
    /// RESUME-INTERRUPTED: hilo vivo al morir el proceso; escrito por la
    /// reconciliación de arranque. Append-only como el resto del enum.
    interrupted = 10,
    /// AUDIT-UNAVAILABLE-P0: la ejecución terminó pero el auditor no produjo
    /// veredicto usable (proveedor agotado/caído). Ni done ni failed — la
    /// entrega sigue bloqueada y el usuario reintenta la auditoría a mano.
    /// Es un estado de espera honesta: sobrevive a reinicios como clarifying.
    audit_unavailable = 11,
    /// E5.18 (D-C5): best-of-N con las candidatas terminadas y rankeadas a la
    /// espera de que el usuario elija ganadora. Append-only como el resto.
    awaiting_best_of_n = 12,
};

fn orderStatusToDa(st: superagent.OrderStatus) DaOrderStatus {
    return switch (st) {
        .pending => .pending,
        .clarifying => .clarifying,
        .planned => .planned,
        .approved => .approved,
        .running => .running,
        .awaiting_approval => .awaiting_approval,
        .done => .done,
        .failed => .failed,
        .rejected => .rejected,
        .cancelled => .cancelled,
        .interrupted => .interrupted,
        .audit_unavailable => .audit_unavailable,
        .awaiting_best_of_n => .awaiting_best_of_n,
    };
}

const MAX_HISTORY_TURNS = 8;
const MAX_TURN_TEXT_BYTES = 2048;

/// FIX-DISPATCH-P0-SAFE: timeout del despacho asíncrono en milisegundos.
/// Si dispatch_poll detecta que el hilo de dispatch no terminó en este tiempo,
/// declara timeout (done=1, ok=0) y marca la orden como failed.
/// El hilo sigue corriendo (no se puede cancelar HTTP/SSE) pero se le hace join en deinit.
/// GOBERNANZA-DESPACHO (2026-07-08): subido de 120_000 a 240_000 — MAX_TOTAL_CANDIDATES
/// pasó de 6 a 12 (ver live_worker.zig), lo que alarga la duración legítima de órdenes
/// sanas que deben probar varios modelos en cascada. Confirmado en vivo: una orden que
/// SÍ terminó bien disparó este timeout a los 120s de todos modos. El extension host ya
/// no trata dispatch_failed como terminal (ver MissionController.ts/ChatPanel.ts), así
/// que subir este valor solo retrasa el aviso de "está tardando" — no oculta fallos reales.
const DISPATCH_TIMEOUT_MS: u64 = 240_000;
// E1.24 (2026-09-17): el techo de 15 min cancelaba órdenes serial-legítimas —
// medido en la orden #595: plan de 14 tareas encadenadas (depends_on) necesitó
// 903 s de reloj y el watchdog la comprometió como order_cancelled estando a
// una ola del final. La fórmula de abajo ya presupuesta 120 s de arranque +
// 180 s por tarea; un techo que contradice la fórmula mata cualquier cadena
// serial de >~6 tareas. 60 min cubre ~19 tareas seriales al timeout completo
// por llamada y sigue acotando órdenes fugadas.
const DISPATCH_TIMEOUT_MAX_MS: u64 = 3_600_000;

/// Presupuesto total de una orden aprobada, guardado al iniciar su despacho.
/// Una tarea conserva 240 s; las órdenes multi-tarea reciben 120 s de arranque
/// más el plazo configurado del modelo por tarea, con límite de 60 minutos.
fn dispatchTimeoutForTaskCount(task_count: usize) u64 {
    if (task_count <= 1) return DISPATCH_TIMEOUT_MS;
    const scaled = 120_000 +| (@as(u64, @intCast(task_count)) *| live_worker.getModelCallTimeoutMs());
    return @max(DISPATCH_TIMEOUT_MS, @min(DISPATCH_TIMEOUT_MAX_MS, scaled));
}

/// E5.18: una orden best-of-N corre el plan entero N veces en SERIE dentro del
/// hilo de la padre — su presupuesto de tiempo escala por N candidatas, no por
/// las tareas del plan solas. Medido en la orden #789: best-of-3 de 1 tarea
/// necesitó ~260 s de torneo y el watchdog de 240 s la marcó timed_out aunque
/// las tres candidatas terminaron bien.
fn dispatchTimeoutForOrder(conn: db.Connection, allocator: std.mem.Allocator, order_db_id: i64, task_count: usize) u64 {
    const cfg = best_of_n.orderConfig(conn, allocator, order_db_id);
    defer if (cfg.members_json) |mj| allocator.free(mj);
    const units = if (cfg.n >= best_of_n.MIN_N and cfg.n <= best_of_n.MAX_N)
        task_count *| @as(usize, @intCast(cfg.n))
    else
        task_count;
    return dispatchTimeoutForTaskCount(units);
}

test "dispatch timeout scales per approved task count with explicit cap" {
    try std.testing.expectEqual(@as(u64, 240_000), dispatchTimeoutForTaskCount(1));
    try std.testing.expectEqual(@as(u64, 1_200_000), dispatchTimeoutForTaskCount(6));
    try std.testing.expectEqual(@as(u64, 3_600_000), dispatchTimeoutForTaskCount(std.math.maxInt(usize)));
}
const AUTO_VERIFY_FAILURE_THRESHOLD: u32 = 3;
const AUTO_VERIFY_MAX_MODELS: usize = 24;
/// el sondeo automático no puede repetirse antes de este intervalo,
/// aunque los fallos de despacho sigan llegando. Sin él, cada racha de 3 fallos
/// lanzaba otra ronda de hasta 24 llamadas y los propios fallos del sondeo
/// (429, timeouts) degradaban la salud que luego realimentaba el router.
const AUTO_VERIFY_MIN_INTERVAL_MS: i64 = 10 * 60 * 1000;
const ACTIVE_PROBE_NOT_FOUND_DISABLE_THRESHOLD: i64 = 2;

/// costura de pruebas del proveedor para el sondeo automático.
/// Misma firma que live_worker.probeModel. En producción es null y se usa el
/// proveedor real; los tests la fijan para no tocar la red (igual patrón que
/// CoreState.test_llm_fn).
const AutoVerifyProbeFn = *const fn (
    allocator: std.mem.Allocator,
    catalog_path: []const u8,
    runtime: db.Connection,
    provider_name: []const u8,
    model_name: []const u8,
    prompt: []const u8,
) ?health.Status;

const CoreState = struct {
    browser_registry: browser_service.Registry = .{},
    browser_workspace_mutex: sync.Mutex = .init(),
    webhook_dispatcher: ?*webhooks.Dispatcher = null,
    arena: std.heap.ArenaAllocator,
    db_conn: db.Connection,
    /// MULTISESSION-P0 (2026-07-12): ruta resuelta (canónica o ":memory:") de
    /// runtime.db, copiada con `aa.dupeZ` en da_core_init — nunca un slice
    /// prestado del buffer del llamador C. El hilo de dispatch la usa para
    /// abrir SU PROPIA Connection en vez de compartir `db_conn`.
    runtime_path: [:0]const u8,
    catalog: model_catalog.ModelCatalog,
    catalog_path: [:0]const u8,
    ledger: db.Connection,
    ledger_path: [:0]const u8,
    orders: std.ArrayListUnmanaged(*OrderRecord),
    orders_mutex: sync.Mutex,
    worker_outputs: std.ArrayListUnmanaged(WorkerOutput),
    last_order_id: i64,
    approvals: std.ArrayListUnmanaged(ApprovalRecord),
    last_approval_id: i64,
    // Secuencia monótona para ts_ms de las salidas de worker: el fork no tiene reloj
    // (std.time no disponible), así que un contador creciente permite que el filtro
    // since_ms de da_worker_output_poll funcione (con ts_ms=0 todo quedaba filtrado).
    output_seq: i64,
    // MEM-01: memoria conversacional de corto plazo (buffer en memoria, por sesión).
    history: planner.ConversationHistory,
    // C3-REGISTRY (2026-07-12): sustituye el single-flight GLOBAL (6 campos
    // escalares + un solo dispatch_mutex) por un registro por order_id — dos
    // órdenes file-backed pueden despachar en paralelo, cada una con su propio
    // hilo/flags/timeout, sin compartirse entre sí. `:memory:` se mantiene
    // serializado dentro del propio registro (memory_dispatch_active).
    dispatch_registry: dispatch_registry.DispatchRegistry,
    dispatch_failure_count: u32,
    /// epoch ms (health.nowMillis) del último sondeo automático.
    /// 0 = nunca se ha sondeado en esta sesión.
    last_auto_verify_ms: i64 = 0,
    /// proveedor inyectable SOLO por tests; null = live_worker.probeModel.
    auto_verify_probe_fn: ?AutoVerifyProbeFn = null,
    /// r2: solo tests — simula que el escenario en memoria no se
    /// puede abrir/inicializar. El sondeo automático debe fallar cerrado
    /// (no sondea y no toca la salud real), no replegarse a la BD real.
    auto_verify_stage_unavailable: bool = false,
    // Phase 4: protege worker_outputs y approvals contra data race GUI<>hilo.
    output_mutex: sync.Mutex,
    // Async plan state (F7-ASYNC-PLAN): evita bloqueo de UI durante LLM calls de planificación.
    plan_mutex: sync.Mutex,
    plan_thread: ?std.Thread,
    plan_done: bool,
    plan_ok: bool,
    plan_order_id: i64,
    // PLAN-CANCEL: token del LLM de planificación en vuelo. tryLlmPlan lo
    // registra mientras dura cada llamada (LlmPlanner.cancel_slot); solo se
    // toca bajo plan_mutex y es null fuera de la llamada.
    plan_cancel_token: ?*live_worker.CancellationToken,
    // PLAN-CANCEL: lo pone da_plan_cancel. Los hilos de planificación lo
    // comprueban al entrar y tras processOrder: una planificación cancelada
    // NUNCA produce plan (ni siquiera el fallback del MockPlanner).
    plan_cancel_requested: bool,
    // F7-MODEL-SELECT: modelo forzado para planificación (null = automático/router).
    // ROLES-MODELO: es además el pin general de la orden — respaldo de exec/audit
    // cuando el usuario no fija un modelo específico para esos roles.
    plan_forced_provider: ?[:0]const u8,
    plan_forced_model: ?[:0]const u8,
    // ROLES-MODELO: pin del EJECUTOR (tareas constructoras y correcciones).
    // null = sigue al pin de la orden (plan_forced_*).
    exec_forced_provider: ?[:0]const u8,
    exec_forced_model: ?[:0]const u8,
    // ROLES-MODELO: pin del AUDITOR (solo tareas .auditar). null = sigue al pin
    // de la orden. NUNCA hereda del ejecutor: un auditor con el modelo
    // constructor no sería una auditoría independiente.
    audit_forced_provider: ?[:0]const u8,
    audit_forced_model: ?[:0]const u8,
    // ENJAMBRE: JSON normalizado `[{provider,model}]` del conjunto elegido por
    // el usuario para las tareas productoras. null = Automático (router decide).
    // Se captura por orden (snapshot), igual que los pines — un cambio posterior
    // no muta una orden en vuelo. Protegido por perm_mutex.
    swarm_models_json: ?[:0]const u8 = null,
    // MODO-DETERMINISTA: con plan_forced_* puesto, prohíbe los respaldos en toda la
    // orden. Sin modelo fijado no tiene efecto. Ver da_set_deterministic_mode.
    plan_deterministic: bool,
    /// modo Directo («un solo modelo, como una CLI»). Con él, la
    /// orden no se planifica: el modelo elegido responde y trabaja con las
    /// herramientas gobernadas (direct_mode.zig).
    plan_direct: bool = false,
    /// USUARIO-NUEVO B: Directo con la herramienta `delegate_tasks`.
    plan_delegate: bool = false,
    // OD-MCP-01: integración con Open Design vía MCP.
    od_mcp_state: od_mcp.OdMcpState,
    /// MCP-AUTH: token de autenticación para el servidor MCP (devagents-mcp).
    /// Persiste en el archivo `mcp_token` junto a runtime.db; lo envía el
    /// cliente MCP interno en `initialize` y lo muestra el panel MCP para que
    /// el usuario configure clientes externos. En ":memory:" es efímero.
    mcp_token: ?[]const u8,
    /// Inventario de herramientas cacheado (SKILLS-RUNTIME-01 / TOOLS-TO-AGENTS-04).
    inventory: ?tool_discovery.Inventory,
    inventory_mutex: sync.Mutex,
    /// Backend de descubrimiento por keywords (vive tanto como CoreState).
    discovery_kw: ?tool_discovery.KeywordDiscovery,
    /// P12-T2: Backend de descubrimiento por LLM (selector agéntico).
    discovery_llm: ?tool_discovery.LlmDiscovery,
    /// PIXEL-DEVTEAM-05: registro unificado de especialistas (nativos + Pixel).
    registry: ?pixel_registry.UnifiedRegistry,
    /// SESSIONS-PERSIST-06: almacén de sesiones (backend SQLite por defecto).
    sessions: ?session_store.SessionStore,
    /// ENGRAM-WIRE-07: backend de memoria (Engram MCP o fallback local persistente).
    memory: engram_memory.MemoryBundle,
    /// P2: configuración de permisos (modo + allow/deny prefix lists).
    perm_mode: superagent.executor.PermissionMode,
    perm_allow: std.ArrayListUnmanaged([]const u8),
    perm_deny: std.ArrayListUnmanaged([]const u8),
    perm_session_allow: std.ArrayListUnmanaged([]const u8),
    perm_mutex: sync.Mutex,
    /// El proceso sirve a un cliente MCP (devagents-mcp). Un token autentica al
    /// cliente pero no es autoridad humana: confirmar/despachar no aprueba
    /// ejecuciones, y relajar permisos, mover la raíz o lanzar procesos
    /// arbitrarios exige la cabina. Solo sube (da_set_mcp_surface).
    mcp_surface: bool,
    /// T12 L1 (auditoría del segundo auditor): aprobaciones que pidió ESTE cliente MCP.
    /// Cada sesión MCP es un proceso devagents-mcp con su propio núcleo, así
    /// que el origen de cada aprobación queda guardado aquí al crearla y
    /// `approval_result` solo devuelve el resultado de las suyas. Protegido
    /// por `output_mutex` (el mismo que `approvals`).
    mcp_owned_approvals: std.ArrayListUnmanaged(i64) = .empty,
    /// T12B B-2: origen de esta sesión MCP (digest de credencial e identidad
    /// de cliente que el servidor pasa con `da_set_mcp_session`). Las tarjetas que
    /// cree quedan marcadas con él en `approvals.origin`, así que su propiedad
    /// sobrevive a reiniciar el proceso. Vacío = sin sesión declarada: una
    /// superficie MCP sin origen solo ve la lista en memoria (M-1), y la
    /// cabina no filtra.
    mcp_origin: []const u8 = "",
    // FIX-ENGINE-8: serializa TODO acceso a ledger.db (lecturas GUI, writes de audit,
    // Router) para evitar deadlock cross-thread bajo journal_mode=DELETE.
    ledger_mutex: sync.Mutex,
    // FIX-ENGINE-9: cola en memoria de entradas de audit pendientes de flush a ledger.db.
    // El hilo de dispatch pushea aquí (mutex corto, sin I/O); el hilo principal
    // drena y escribe a ledger.db via flushAuditQueue (donde el INSERT ya funcionaba).
    audit_queue: std.ArrayListUnmanaged(superagent.AuditEntry),
    audit_queue_mutex: sync.Mutex,
    // GOBERNANZA-HIBRIDO-LEDGER: ids de usage_records ya auditados como
    // ESCALATION — deduplica entre la barrida post-plan y la post-despacho
    // de la misma orden (las llamadas auxiliares no-tarea, p.ej. el selector
    // de herramientas, se registran recién durante el despacho).
    escalated_usage_ids: std.AutoHashMapUnmanaged(i64, void),
    escalated_usage_mutex: sync.Mutex,
    // E5.08 — GOBIERNO ENCIMA: límites de los agentes externos (persisten en
    // el setting `external_agent_limits`, ver da_external_limits_*) y seams de
    // ejecución/detección para los tests (null = seam real por defecto).
    external_limits: external_agents.Limits = .{},
    external_mutex: sync.Mutex = .init(),
    /// Tanda 5: una sola comprobación o descarga del actualizador a la vez
    /// (la de arranque de la cabina y el clic del usuario pueden cruzarse).
    update_mutex: sync.Mutex = .init(),
    /// 10-nov: carpeta de cada orden de Directo (la del proyecto, sin space).
    /// La consultan orderWorktree y el enganche del navegador integrado, para
    /// que el agente de Directo pueda usarlo sin que se cree un space.
    direct_roots_mutex: sync.Mutex = .init(),
    direct_roots: std.AutoHashMapUnmanaged(i64, []u8) = .empty,
    external_detection_thread: ?std.Thread = null,
    external_run_fn: ?external_agents.RunFn = null,
    /// Seam de prueba: sustituye el despacho real de cada hija en el
    /// reintento de auditoría de una vuelta que delegó (retryDelegatedAudits).
    delegate_retry_dispatch_fn: ?*const fn (st: *CoreState, rec: *OrderRecord, conn: db.Connection) DaResult = null,
    external_run_ctx: ?*anyopaque = null,
    external_capture_fn: ?headless_adapter.CaptureFn = null,
    external_getenv_fn: ?headless_adapter.GetEnvFn = null,
    external_resolve_fn: ?external_agents.ResolveFn = null,
    // C3-REGISTRY (2026-07-12): st.memory (MemoryBundle) es COMPARTIDO por todo
    // CoreState — para `.local`, backendForConn liga cada orden a su propia
    // Connection (seguro, ver MULTISESSION-P0); pero para `.engram`, backendForConn
    // devuelve el MISMO backend (mismo McpClient/subprocess) para TODAS las
    // órdenes, porque Engram no usa runtime SQLite y se asumió sin estado
    // compartido peligroso bajo el single-flight global. Con 2+ órdenes file-backed
    // realmente concurrentes eso deja de ser cierto: dos hilos llamando
    // saveFinding/saveSessionSummary a la vez sobre el MISMO McpClient corrompen su
    // buffer de lectura interno (SEGFAULT real, hallado por el test C3-L). Arreglar
    // McpClient/EngramMemory para ser thread-safe es de engram_memory.zig/
    // mcp_client.zig, fuera del ÁREA de este incremento — este mutex serializa
    // las 2 llamadas conocidas en dispatchApprovedOrder como mitigación mínima
    // dentro de alcance (costo aceptable: son escrituras cortas, no el cuello de
    // botella real de un despacho).
    memory_mutex: sync.Mutex,
    /// B3/SHIP-FLOW: hilo del GitHubPoller — sondea `pull_requests` abiertas en
    /// segundo plano (B4 no bloqueante) y NUNCA pisa un merge en vuelo (la
    /// guarda vive en pollOnce). Se abre SU PROPIA Connection sobre
    /// runtime_path; en ":memory:" no se lanza (BD independiente = no veria
    /// nada). Se joinea en deinit.
    ship_poll_thread: ?std.Thread,
    ship_poll_stop: std.atomic.Value(bool),
    /// B3: runner gh/git inyectable para el ship flow. Produccion: null =
    /// runCmdCaptureWin32 real. SOLO tests lo fijan (mismo patron que
    /// executor_spawn_fn).
    gh_capture_fn: ?providers.github.CaptureFn,
    /// variante con stdin+env visibles — permite a un test EXIGIR la
    /// guardia anti-prompt en las llamadas git de red (push/fetch/clone).
    /// Prioriza sobre gh_capture_fn cuando esta fijada.
    gh_capture_full_fn: ?providers.github.CaptureFullFn = null,
    /// T4-GITEA: canal REST inyectable para el conector Gitea. Produccion:
    /// null = http_client real. SOLO tests lo fijan.
    gitea_rest_fn: ?providers.gitea.RestFn = null,
    forge_rest_enabled: bool = true,
    issues_rest_fn: ?providers.gitea.RestFn = null,
    issues_rest_ctx: ?*anyopaque = null,
    /// FASE-AGENTIC-3: tope de iteraciones del loop observe→re-planifica.
    /// DEFAULT 1 = un solo paso (comportamiento de hoy; el loop NO corre). Lo
    /// sube el propietario vía la tool set_agentic_config una vez verificado en vivo.
    agentic_max_iterations: usize = 1,
    /// TEST-LLM-SEAM (AUDIT-UNAVAILABLE-P0): fixture LLM inyectado SOLO por
    /// tests cuando no hay proveedor con clave. Produccion: siempre null —
    /// el despacho sigue por LiveLlm real o cae al MockWorker. Mismo patron
    /// que gh_capture_fn / gitea_rest_fn / executor_spawn_fn. Existe porque
    /// bajo MockWorker la auditoria produce verdict="mock-value" y TODA orden
    /// cierra 'audit_unavailable' — correcto en produccion sin claves, pero
    /// los tests de la via done/checkpoint/ship necesitan un veredicto real.
    test_llm_fn: ?worker_backend.NativeWorker.LlmFn = null,
    test_llm_ctx: ?*anyopaque = null,

    fn deinit(self: *CoreState) void {
        if (self.external_detection_thread) |thread| thread.join();
        if (self.webhook_dispatcher) |dispatcher| dispatcher.deinit();
        // C3-REGISTRY: marca closing (nuevos da_order_dispatch_async se rechazan),
        // joinea TODOS los hilos en vuelo (uno o varios — nunca detach, ver
        // C3-DECISIONS-MULTISESSION-2026-07-12.md punto 3) y libera cada
        // contexto exactamente una vez.
        self.browser_registry.cancelAll();
        self.dispatch_registry.deinit();
        self.browser_registry.deinit(self.arena.child_allocator);
        {
            var it = self.direct_roots.valueIterator();
            while (it.next()) |root| self.arena.child_allocator.free(root.*);
            self.direct_roots.deinit(self.arena.child_allocator);
        }
        // Phase 1: evitar use-after-free si el IDE se cierra con planificación activa.
        if (self.plan_thread) |t| {
            self.plan_mutex.lock();
            const done = self.plan_done;
            self.plan_mutex.unlock();
            if (!done) {
                // El hilo puede estar bloqueado en I/O; join() espera a que termine.
            }
            t.join();
            self.plan_thread = null;
        }
        for (self.orders.items) |r| {
            r.deinit(self.arena.child_allocator);
            self.arena.child_allocator.destroy(r);
        }
        self.orders.deinit(self.arena.child_allocator);
        self.worker_outputs.deinit(self.arena.child_allocator);
        for (self.approvals.items) |*a| a.deinit(self.arena.child_allocator);
        self.approvals.deinit(self.arena.child_allocator);
        self.mcp_owned_approvals.deinit(self.arena.child_allocator);
        if (self.mcp_origin.len > 0) self.arena.child_allocator.free(self.mcp_origin);
        if (self.plan_forced_provider) |p| self.arena.child_allocator.free(p);
        if (self.plan_forced_model) |m| self.arena.child_allocator.free(m);
        if (self.exec_forced_provider) |p| self.arena.child_allocator.free(p);
        if (self.exec_forced_model) |m| self.arena.child_allocator.free(m);
        if (self.audit_forced_provider) |p| self.arena.child_allocator.free(p);
        if (self.audit_forced_model) |m| self.arena.child_allocator.free(m);
        if (self.swarm_models_json) |s| self.arena.child_allocator.free(s);
        self.history.deinit(self.arena.child_allocator);
        if (self.inventory) |*inv| inv.deinit(self.arena.child_allocator);
        if (self.registry) |*reg| reg.deinit();
        if (self.sessions) |s| s.deinitFn(self.arena.child_allocator);
        self.memory.deinit();
        self.od_mcp_state.deinit();
        // FIX-ENGINE-9: liberar entries pendientes en la cola de audit.
        for (self.audit_queue.items) |e| e.deinit(self.arena.child_allocator);
        self.audit_queue.deinit(self.arena.child_allocator);
        self.escalated_usage_ids.deinit(self.arena.child_allocator);
        // B3: el poller de PRs usa su propia Connection — parar y joinear
        // antes de cerrar nada para no soltarle runtime.db debajo.
        self.ship_poll_stop.store(true, .release);
        if (self.ship_poll_thread) |t| {
            t.join();
            self.ship_poll_thread = null;
        }
        // E5.26: the poller borrows the catalog for configured forge hosts.
        self.catalog.deinit();
        self.ledger.close();
        self.db_conn.close();
        // P2: liberar prefix lists de permisos.
        const aa2 = self.arena.child_allocator;
        for (self.perm_allow.items) |s| aa2.free(s);
        self.perm_allow.deinit(aa2);
        for (self.perm_deny.items) |s| aa2.free(s);
        self.perm_deny.deinit(aa2);
        for (self.perm_session_allow.items) |s| aa2.free(s);
        self.perm_session_allow.deinit(aa2);
        self.arena.deinit();
    }
};

const OrderRecord = struct {
    id: i64,
    /// ID real en runtime.db (null solo mientras un submit async aún no recibe
    /// el rowid del INSERT de superagent.processOrder). Para órdenes rehidratas
    /// o sync, id == db_id.
    db_id: ?i64,
    text: []const u8,
    project_id: []const u8,
    status: superagent.OrderStatus,
    wait_for_plan_approval: bool = false,
    plan_json: ?[]const u8,
    outcome: ?superagent.OrderOutcome,
    questions: []const u8,
    created_at: i64,
    /// FASE-AGENTIC-1: hilo de conversación al que pertenece esta orden. Null =
    /// orden sin conversación explícita (cliente viejo que no la envía).
    conversation_id: ?[]const u8 = null,
    /// D8: rondas de clarificación ya consumidas (persistido en orders.clarify_rounds).
    /// Alimenta `llm_planner.clarify_rounds_used` en cada re-plan por respuesta.
    clarify_rounds: i64 = 0,
    /// E2.5: la sesión fue borrada por el usuario (`da_session_delete`). La fila
    /// de runtime.db ya no existe pero el registro se queda vivo por los
    /// handles obsoletos — `da_sessions_json` no la lista: borrada es borrada,
    /// no «rejected» en la barra lateral.
    deleted: bool = false,

    fn deinit(self: *OrderRecord, allocator: std.mem.Allocator) void {
        allocator.free(self.text);
        allocator.free(self.project_id);
        if (self.plan_json) |j| allocator.free(j);
        if (self.outcome) |*o| o.deinit();
        allocator.free(self.questions);
        if (self.conversation_id) |c| allocator.free(c);
    }
};

/// D8: la orden volvió a pedir clarificación — consume una ronda y la persiste.
fn bumpClarifyRounds(st: *CoreState, rec: *OrderRecord) void {
    rec.clarify_rounds += 1;
    const db_id = rec.db_id orelse rec.id;
    const stmt = st.db_conn.prepare("UPDATE orders SET clarify_rounds = ? WHERE id = ?") catch return;
    defer st.db_conn.finalize(stmt);
    db.bindInt(stmt, 1, rec.clarify_rounds) catch return;
    db.bindInt(stmt, 2, db_id) catch return;
    _ = db.c.sqlite3_step(stmt);
}

/// D8: ClarifyRoundsExhausted (o fallo de planner en el hilo async) marca la
/// orden failed en memoria — persistirlo o un reinicio la rehidrata como
/// clarifying y el bucle de preguntas vuelve a abrirse.
fn persistOrderFailed(st: *CoreState, rec: *const OrderRecord) void {
    persistOrderFailedWithReason(st, rec, "order_error");
}

/// 10-nov (órdenes 940 y 942): un error tras planificar dejaba la orden en
/// `pending` para siempre — el UPDATE suelto fallaba sin decirlo y el motivo
/// vivía solo en el error por hilo. Ahora se cierra por el camino terminal
/// normal (estado + evento `order_failed` con la causa), reintentando unos
/// instantes si la base está ocupada, y el UPDATE simple queda de reserva.
fn persistOrderFailedWithReason(st: *CoreState, rec: *const OrderRecord, reason: []const u8) void {
    const db_id = rec.db_id orelse rec.id;
    const a = st.arena.child_allocator;
    const payload = std.json.Stringify.valueAlloc(a, .{ .cause = "order_error", .reason = reason }, .{}) catch null;
    defer if (payload) |p| a.free(p);
    var attempt: usize = 0;
    while (attempt < 5) : (attempt += 1) {
        if (st.db_conn.tryCommitTerminal(db_id, "failed", "order_failed", "motor", payload orelse "{\"cause\":\"order_error\"}", health.nowMillis(st.db_conn))) |_| {
            return;
        } else |e| {
            std.debug.print("persistOrderFailed: intento {d}: {s}\n", .{ attempt + 1, @errorName(e) });
            Sleep(200);
        }
    }
    const stmt = st.db_conn.prepare("UPDATE orders SET status = 'failed' WHERE id = ?") catch return;
    defer st.db_conn.finalize(stmt);
    db.bindInt(stmt, 1, db_id) catch return;
    _ = db.c.sqlite3_step(stmt);
}

/// PLAN-CANCEL: deja la orden en `cancelled` de forma honesta — memoria +
/// DB + evento `order_cancelled` cuando la fila ya existe (una orden cuya
/// planificación se cancela antes de que processOrder inserte su fila no
/// tiene db_id; su estado vive solo en memoria hasta que nazca la fila).
/// Idempotente: tryCommitTerminal es UPDATE condicional, un segundo intento
/// sobre una orden ya terminal es no-op.
fn markPlanCancelled(st: *CoreState, order_id: i64) void {
    const rec = findOrder(st, order_id) orelse return;
    rec.status = .cancelled;
    _ = st.db_conn.tryCommitTerminal(rec.db_id orelse rec.id, "cancelled", "order_cancelled", "usuario", "\"planificacion cancelada por el usuario\"", health.nowMillis(st.db_conn)) catch false;
}

fn captureModelSelection(st: *CoreState, allocator: std.mem.Allocator) !permission_snapshot.OwnedModelSelection {
    st.perm_mutex.lock();
    defer st.perm_mutex.unlock();
    return permission_snapshot.OwnedModelSelection.initCloneRoles(
        allocator,
        st.plan_forced_provider,
        st.plan_forced_model,
        st.exec_forced_provider,
        st.exec_forced_model,
        st.audit_forced_provider,
        st.audit_forced_model,
        st.swarm_models_json,
    );
}

const WorkerOutput = struct {
    worker_id: []const u8,
    stream: []const u8,
    text: []const u8,
    ts_ms: i64,
    /// P05: task_id asociado para consolidar output con shell cards en la UI.
    task_id: []const u8 = "",
};

const ApprovalRecord = struct {
    id: i64,
    task_id: []const u8,
    description: []const u8,
    approved: bool,
    resolved: bool,
    command_prefix: ?[]const u8 = null,
    /// P-EXEC-4: exe + args_json para re-ejecutar al aprobar.
    exe: ?[]const u8 = null,
    args_json: ?[]const u8 = null,
    /// P-EXEC-4: orden vinculada (para avanzar state al resolver).
    order_id: i64 = 0,

    fn deinit(self: *ApprovalRecord, allocator: std.mem.Allocator) void {
        allocator.free(self.task_id);
        allocator.free(self.description);
        if (self.command_prefix) |p| allocator.free(p);
        if (self.exe) |e| allocator.free(e);
        if (self.args_json) |a| allocator.free(a);
    }
};

threadlocal var last_error_buf: [2048]u8 = [_]u8{0} ** 2048;
threadlocal var last_error_len: usize = 0;

fn setLastError(msg: []const u8) void {
    const visible = if (std.mem.eql(u8, msg, "InsecureCredentialTransport")) providers.http_client.SECURITY_MESSAGE else if (std.mem.eql(u8, msg, "RedirectBlocked")) providers.http_client.REDIRECT_MESSAGE else msg;
    const len = @min(visible.len, last_error_buf.len - 1);
    @memcpy(last_error_buf[0..len], visible[0..len]);
    last_error_buf[len] = 0;
    last_error_len = len;
}

fn ok() DaResult {
    last_error_len = 0;
    return .ok;
}

fn err(code: DaResult, msg: []const u8) DaResult {
    setLastError(msg);
    return code;
}

/// Cadena propiedad-DEL-CALLER para la frontera C (corrige F1 fuga + F2 over-read):
/// copia `s` a una cadena terminada en NUL en el **c_allocator**, que es EXACTAMENTE
/// el allocator con el que `da_string_free` la libera. Nunca devuelve literales
/// estáticos (liberarlos con c_allocator sería UB) ni slices sin sentinel (el borde
/// entrega [*:0]u8 y el consumidor lee hasta el NUL). null → OOM: el caller devuelve
/// error y NO fija el puntero de salida; la GUI sólo lee/libera cuando el retorno es
/// DA_OK (qt_main verifica `== DA_OK && ptr`).
fn ownedCStr(s: []const u8) ?[*:0]u8 {
    const z = std.heap.c_allocator.dupeZ(u8, s) catch return null;
    return z.ptr;
}

fn planToJson(allocator: std.mem.Allocator, p: *const planner.Plan) ![]const u8 {
    var out: std.Io.Writer.Allocating = .init(allocator);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    try js.beginObject();
    try js.objectField("understanding");
    try js.write(p.understanding);
    try js.objectField("needs_clarification");
    try js.write(p.needsClarification());
    {
        try js.objectField("questions");
        try js.beginArray();
        for (p.questions) |q| {
            try js.beginObject();
            try js.objectField("id");
            try js.write(q.id);
            try js.objectField("text");
            try js.write(q.text);
            try js.objectField("options");
            try js.beginArray();
            for (q.options) |o| try js.write(o);
            try js.endArray();
            try js.endObject();
        }
        try js.endArray();
    }
    {
        try js.objectField("tasks");
        try js.beginArray();
        for (p.tasks) |t| {
            try js.beginObject();
            try js.objectField("id");
            try js.write(t.id);
            try js.objectField("task_type");
            try js.write(t.task_type.toText());
            try js.objectField("department");
            try js.write(t.department);
            try js.objectField("description");
            try js.write(t.description);
            try js.objectField("needs_vision");
            try js.write(t.needs_vision);
            try js.objectField("depends_on");
            try js.beginArray();
            for (t.depends_on) |d| try js.write(d);
            try js.endArray();
            if (t.owns.len > 0) {
                try js.objectField("owns");
                try js.beginArray();
                for (t.owns) |o| try js.write(o);
                try js.endArray();
            }
            if (t.deliverable) |d| {
                try js.objectField("deliverable");
                try js.write(d);
            }
            try js.objectField("contract_fields");
            try js.beginArray();
            for (t.contract_fields) |f| {
                try js.beginObject();
                try js.objectField("name");
                try js.write(f.name);
                try js.objectField("type");
                try js.write(@tagName(f.field_type));
                try js.objectField("required");
                try js.write(f.required);
                if (f.value) |value| {
                    try js.objectField("value");
                    try js.write(value);
                }
                try js.endObject();
            }
            try js.endArray();
            try js.endObject();
        }
        try js.endArray();
    }
    try js.endObject();
    return allocator.dupe(u8, out.written());
}

const DEPARTMENTS = [_][]const u8{ "programacion", "testing", "auditoria", "correccion", "documentacion", "diseno" };

fn validDepartment(s: []const u8) bool {
    for (DEPARTMENTS) |d| {
        if (std.mem.eql(u8, s, d)) return true;
    }
    return false;
}

fn parseTaskType(s: []const u8) ?model_router.TaskType {
    inline for (@typeInfo(model_router.TaskType).@"enum".fields) |f| {
        const tt = @field(model_router.TaskType, f.name);
        if (std.mem.eql(u8, s, tt.toText())) return tt;
    }
    return null;
}

fn parseFieldType(s: []const u8) contracts.FieldType {
    if (std.mem.eql(u8, s, "integer")) return .integer;
    if (std.mem.eql(u8, s, "boolean")) return .boolean;
    if (std.mem.eql(u8, s, "any")) return .any;
    return .string;
}

fn planFromJson(allocator: std.mem.Allocator, json_str: []const u8) !planner.Plan {
    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    const tmp = arena.child_allocator;

    var parsed = try std.json.parseFromSlice(std.json.Value, tmp, json_str, .{});
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidJson;
    const o = parsed.value.object;

    const understanding_v = o.get("understanding") orelse return error.InvalidJson;
    if (understanding_v != .string) return error.InvalidJson;
    const understanding = try allocator.dupe(u8, understanding_v.string);
    errdefer allocator.free(understanding);

    const tasks_v = o.get("tasks") orelse return error.InvalidJson;
    if (tasks_v != .array) return error.InvalidJson;

    var tasks = std.ArrayList(planner.PlannedTask).empty;
    errdefer {
        for (tasks.items) |t| freePlannedTask(allocator, t);
        tasks.deinit(allocator);
    }
    for (tasks_v.array.items) |tv| {
        const t = try parsePlannedTask(allocator, tv);
        try tasks.append(allocator, t);
    }

    const questions = try allocator.alloc(planner.ClarificationQuestion, 0);
    errdefer allocator.free(questions);

    return planner.Plan{
        .allocator = allocator,
        .understanding = understanding,
        .questions = questions,
        .tasks = try tasks.toOwnedSlice(allocator),
    };
}

fn parsePlannedTask(a: std.mem.Allocator, tv: std.json.Value) !planner.PlannedTask {
    if (tv != .object) return error.InvalidJson;
    const o = tv.object;

    const id_v = o.get("id") orelse return error.InvalidJson;
    const tt_v = o.get("task_type") orelse return error.InvalidJson;
    const dept_v = o.get("department") orelse return error.InvalidJson;
    const desc_v = o.get("description") orelse return error.InvalidJson;
    if (id_v != .string or tt_v != .string or dept_v != .string or desc_v != .string) return error.InvalidJson;

    const task_type = parseTaskType(tt_v.string) orelse return error.InvalidJson;
    if (!validDepartment(dept_v.string)) return error.InvalidJson;

    const id = try a.dupe(u8, id_v.string);
    errdefer a.free(id);
    const department = try a.dupe(u8, dept_v.string);
    errdefer a.free(department);
    const description = try a.dupe(u8, desc_v.string);
    errdefer a.free(description);

    var contract_fields = try parseContractFields(a, o.get("contract_fields"));
    errdefer {
        for (contract_fields) |f| {
            a.free(f.name);
            if (f.value) |value| a.free(value);
        }
        a.free(contract_fields);
    }
    // Una tarea `auditar` sin `verdict` en el contrato acaba siempre en
    // audit_unavailable: el modelo no ve el campo como obligatorio en la tabla
    // CONTRATO y nunca lo emite (medido en vivo — órdenes 739/743). El planner
    // local ya lo inyecta (planner.zig); el plan del LLM se normaliza igual aquí.
    try ensureAuditVerdictField(a, task_type, &contract_fields);
    const depends_on = try parseDependsOn(a, o.get("depends_on"));
    errdefer {
        for (depends_on) |d| a.free(d);
        a.free(depends_on);
    }
    const owns = try parseDependsOn(a, o.get("owns"));
    errdefer {
        for (owns) |o2| a.free(o2);
        if (owns.len > 0) a.free(owns);
    }
    const deliverable: ?[]const u8 = if (o.get("deliverable")) |dv|
        (if (dv == .string and dv.string.len > 0) try a.dupe(u8, dv.string) else null)
    else
        null;

    return planner.PlannedTask{
        .needs_vision = if (o.get("needs_vision")) |v| (if (v == .bool) v.bool else return error.InvalidJson) else false,
        .id = id,
        .task_type = task_type,
        .department = department,
        .description = description,
        .contract_fields = contract_fields,
        .depends_on = depends_on,
        .owns = owns,
        .deliverable = deliverable,
    };
}

fn ensureAuditVerdictField(a: std.mem.Allocator, task_type: model_router.TaskType, fields: *[]planner.ContractField) !void {
    if (task_type != .auditar) return;
    for (fields.*) |f| {
        if (std.ascii.eqlIgnoreCase(f.name, "verdict")) return;
    }
    const verdict_name = try a.dupe(u8, "verdict");
    errdefer a.free(verdict_name);
    const out = try a.alloc(planner.ContractField, fields.len + 1);
    @memcpy(out[0..fields.len], fields.*);
    out[fields.len] = .{ .name = verdict_name, .field_type = .string, .required = true, .value = null };
    a.free(fields.*);
    fields.* = out;
}

fn parseContractFields(a: std.mem.Allocator, v: ?std.json.Value) ![]planner.ContractField {
    var list = std.ArrayList(planner.ContractField).empty;
    errdefer {
        for (list.items) |f| a.free(f.name);
        list.deinit(a);
    }
    if (v) |fields_v| {
        if (fields_v == .array) {
            for (fields_v.array.items) |fv| {
                if (fv != .object) continue;
                const fo = fv.object;
                const name_v = fo.get("name") orelse continue;
                if (name_v != .string) continue;
                const ft = parseFieldType(if (fo.get("type")) |t| (if (t == .string) t.string else "string") else "string");
                const required = if (fo.get("required")) |r| (r == .bool and r.bool) else true;
                const name = try a.dupe(u8, name_v.string);
                errdefer a.free(name);
                const value: ?[]const u8 = if (fo.get("value")) |raw|
                    if (raw == .string) try a.dupe(u8, raw.string) else null
                else
                    null;
                errdefer if (value) |owned| a.free(owned);
                try list.append(a, .{ .name = name, .field_type = ft, .required = required, .value = value });
            }
        }
    }
    return list.toOwnedSlice(a);
}

fn parseDependsOn(a: std.mem.Allocator, v: ?std.json.Value) ![][]const u8 {
    var list = std.ArrayList([]const u8).empty;
    errdefer {
        for (list.items) |d| a.free(d);
        list.deinit(a);
    }
    if (v) |dv| {
        if (dv == .array) {
            for (dv.array.items) |item| {
                if (item != .string) continue;
                const dep = try a.dupe(u8, item.string);
                errdefer a.free(dep);
                try list.append(a, dep);
            }
        }
    }
    return list.toOwnedSlice(a);
}

fn freePlannedTask(a: std.mem.Allocator, t: planner.PlannedTask) void {
    a.free(t.id);
    a.free(t.department);
    a.free(t.description);
    for (t.contract_fields) |f| {
        a.free(f.name);
        if (f.value) |value| a.free(value);
    }
    a.free(t.contract_fields);
    for (t.depends_on) |d| a.free(d);
    a.free(t.depends_on);
    for (t.owns) |o| a.free(o);
    if (t.owns.len > 0) a.free(t.owns);
    if (t.deliverable) |d| a.free(d);
}

fn questionsToJson(allocator: std.mem.Allocator, questions: []const planner.ClarificationQuestion) ![]const u8 {
    // D8: los nombres coinciden con la serialización de preguntas en planToJson
    // (id/text/options) — la UI lee q.id/q.text y un segundo vocabulario aquí
    // dejaba el formulario de clarificación invisible.
    var out: std.Io.Writer.Allocating = .init(allocator);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    try js.beginArray();
    for (questions) |q| {
        try js.beginObject();
        try js.objectField("id");
        try js.write(q.id);
        try js.objectField("text");
        try js.write(q.text);
        try js.objectField("options");
        try js.beginArray();
        for (q.options) |o| try js.write(o);
        try js.endArray();
        try js.endObject();
    }
    try js.endArray();
    return allocator.dupe(u8, out.written());
}

fn parseClarificationAnswers(allocator: std.mem.Allocator, json_str: []const u8) ![]planner.ClarificationAnswer {
    var parsed = std.json.parseFromSlice(std.json.Value, allocator, json_str, .{}) catch return error.InvalidJson;
    defer parsed.deinit();
    if (parsed.value != .array) return error.InvalidJson;
    var list = std.ArrayList(planner.ClarificationAnswer).empty;
    errdefer {
        for (list.items) |a| {
            allocator.free(a.question_id);
            allocator.free(a.answer);
        }
        list.deinit(allocator);
    }
    for (parsed.value.array.items) |item| {
        if (item != .object) return error.InvalidJson;
        const obj = item.object;
        const qid = (obj.get("question_id") orelse return error.InvalidJson);
        const ans = (obj.get("answer") orelse return error.InvalidJson);
        if (qid != .string or ans != .string) return error.InvalidJson;
        try list.append(allocator, .{
            .question_id = try allocator.dupe(u8, qid.string),
            .answer = try allocator.dupe(u8, ans.string),
        });
    }
    return list.toOwnedSlice(allocator);
}

fn findOrder(st: *CoreState, order_id: i64) ?*OrderRecord {
    st.orders_mutex.lock();
    defer st.orders_mutex.unlock();
    for (st.orders.items) |o| {
        // Una orden que pasó por clarificación vive con id interno de la fila
        // `clarifying` pero `db_id` de la fila `planned`/`done` que insertó el
        // outcome. El llamador puede traer cualquiera de los dos: la UI guarda
        // el handle del submit (id) pero el usuario y runtime.db ven el db_id.
        if (o.id == order_id or (o.db_id orelse o.id) == order_id) return o;
    }
    return null;
}

fn orderHandleToId(handle: ?*anyopaque) ?i64 {
    if (handle == null) return null;
    const ptr = @intFromPtr(handle);
    return @intCast(ptr);
}

fn orderIdToHandle(id: i64) *anyopaque {
    return @ptrFromInt(@as(usize, @intCast(id)));
}

/// ¿Hay al menos un modelo disponible en el catálogo? Si no, da_order_approve no
/// arma el router (route() no tendría candidatos) y degrada al comportamiento previo.
fn catalogHasAvailableModels(cat: db.Connection) bool {
    const stmt = cat.prepare("SELECT COUNT(*) FROM models WHERE available = 1") catch return false;
    defer cat.finalize(stmt);
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) return false;
    return db.c.sqlite3_column_int(stmt, 0) > 0;
}

/// Crea un router a partir del catálogo+runtime+ledger del CoreState.
/// Devuelve null si no hay modelos disponibles (degrada a sin-router).
/// El router vive en el stack del llamador (router_storage); el puntero
/// retornado apunta a él.
/// `conn`: MULTISESSION-P0 — Connection de runtime.db a usar para health/now.
/// Los llamadores de planificación (hilo plan_thread) pasan `st.db_conn`; el
/// llamador de despacho (dispatchApprovedOrder) pasa la Connection propia del
/// hilo de dispatch.
fn makeRouter(st: *CoreState, aa: std.mem.Allocator, router_storage: *model_router.Router, conn: db.Connection) ?*model_router.Router {
    if (!catalogHasAvailableModels(st.catalog.db)) return null;
    const now = health.nowSeconds(conn);
    // FIX-ENGINE-8: pasar null para ledger → Router no escribe audit_entries
    // (recordFallback/recordEscalation son no-ops). Los writes de audit se serializan
    // via ledger_mutex en persistAuditEntries. Evita contention cross-thread.
    router_storage.* = model_router.Router.init(aa, st.catalog.db, null, now);
    router_storage.setHealthConn(conn);
    return router_storage;
}

/// copia una petición de aprobación del despacho a un registro que
/// posee TODAS sus cadenas. La petición vive dentro del resultado del
/// despacho y se libera con él; el registro vive en `st.approvals` hasta que
/// se resuelve, así que no puede apuntar a ella.
fn aprobacionDesdePeticion(aa: std.mem.Allocator, id: i64, req: superagent.ApprovalRequest, order_id: i64) !ApprovalRecord {
    const task_id = try aa.dupe(u8, req.task_id);
    errdefer aa.free(task_id);
    const description = try aa.dupe(u8, req.description);
    errdefer aa.free(description);
    const command_prefix: ?[]const u8 = if (req.command_prefix) |v| try aa.dupe(u8, v) else null;
    errdefer if (command_prefix) |v| aa.free(v);
    const exe: ?[]const u8 = if (req.exe) |v| try aa.dupe(u8, v) else null;
    errdefer if (exe) |v| aa.free(v);
    const args_json: ?[]const u8 = if (req.args_json) |v| try aa.dupe(u8, v) else null;
    return .{
        .id = id,
        .task_id = task_id,
        .description = description,
        .approved = false,
        .resolved = false,
        .command_prefix = command_prefix,
        .exe = exe,
        .args_json = args_json,
        .order_id = order_id,
    };
}

test "E-103: el registro de aprobación es propietario de sus cadenas, no apunta a la petición" {
    const a = std.testing.allocator;
    // La petición, tal como sale del despacho: todo en el heap y liberado
    // por `dr.deinit` al terminar el bloque que registra las aprobaciones.
    const req = superagent.ApprovalRequest{
        .task_id = try a.dupe(u8, "t1"),
        .description = try a.dupe(u8, "Ejecutar zig requiere aprobación: ExeNotResolved"),
        .command_prefix = try a.dupe(u8, "zig"),
        .exe = try a.dupe(u8, "zig"),
        .args_json = try a.dupe(u8, "[\"build-exe\",\"build.zig\"]"),
    };
    var rec = try aprobacionDesdePeticion(a, 4, req, 748);
    defer rec.deinit(a);
    // Ningún campo comparte memoria con la petición...
    try std.testing.expect(rec.task_id.ptr != req.task_id.ptr);
    try std.testing.expect(rec.command_prefix.?.ptr != req.command_prefix.?.ptr);
    try std.testing.expect(rec.exe.?.ptr != req.exe.?.ptr);
    try std.testing.expect(rec.args_json.?.ptr != req.args_json.?.ptr);
    // ...así que liberar la petición (lo que hace dr.deinit) deja el registro
    // intacto. Con el código anterior esto era un doble liberado, que el
    // asignador de pruebas detecta.
    req.deinit(a);
    try std.testing.expectEqualStrings("zig", rec.command_prefix.?);
    try std.testing.expectEqualStrings("zig", rec.exe.?);
    try std.testing.expectEqualStrings("[\"build-exe\",\"build.zig\"]", rec.args_json.?);
    try std.testing.expectEqual(@as(i64, 748), rec.order_id);
    try std.testing.expect(!rec.resolved);
}

test "E5.05: aprobación worktree_script solo-DB se lista y resuelve por la API pública" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle));

    // La preparación del worktree inserta la fila directamente en la tabla —
    // st.approvals queda vacío. Antes del fix, approvals_list devolvía [] y
    // approvals_resolve la ignoraba (medido en vivo sobre orden #1-#4).
    const args_json =
        "{\"project_id\":\"proj-x\",\"script_sha256\":\"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\",\"script\":\"setup.cmd\"}";
    const ins = st.db_conn.prepare(
        "INSERT INTO approvals (task_id, description, approved, resolved, created_at, command_prefix, exe, args_json, order_id) VALUES ('worktree_setup', 'worktree setup setup.cmd (sha256 aaaaaaaaaaaa)', 0, 0, 1, 'worktree_script', NULL, ?, 999)",
    ) catch return error.ExecFailed;
    db.bindText(ins, 1, args_json) catch return error.ExecFailed;
    try std.testing.expectEqual(db.c.SQLITE_DONE, db.c.sqlite3_step(ins));
    st.db_conn.finalize(ins);
    const approval_id = db.c.sqlite3_last_insert_rowid(st.db_conn.db);

    // 1) La lista pública debe incluirla, con args_json para la tarjeta.
    var out: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_approval_pending_json(handle, &out));
    const listed = std.mem.span(out);
    defer da_string_free(out);
    try std.testing.expect(std.mem.indexOf(u8, listed, "worktree_script") != null);
    try std.testing.expect(std.mem.indexOf(u8, listed, "setup.cmd") != null);
    try std.testing.expect(std.mem.indexOf(u8, listed, "args_json") != null);

    // 2) Resolverla con aprobado concede el par (proyecto, hash) y cierra la fila.
    try std.testing.expectEqual(@as(c_int, 0), da_approval_resolve(handle, approval_id, 1));
    try std.testing.expect(worktree_prepare.isScriptApproved(st.db_conn, "proj-x", "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"));
    const chk = st.db_conn.prepare("SELECT resolved, approved FROM approvals WHERE id = ?") catch return error.ExecFailed;
    db.bindInt(chk, 1, approval_id) catch return error.ExecFailed;
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(chk));
    try std.testing.expectEqual(@as(c_int, 1), db.c.sqlite3_column_int(chk, 0));
    try std.testing.expectEqual(@as(c_int, 1), db.c.sqlite3_column_int(chk, 1));
    st.db_conn.finalize(chk);

    // 3) Una ya resuelta devuelve invalid_state, no éxito mudo.
    try std.testing.expect(da_approval_resolve(handle, approval_id, 1) != 0);

    // 4) Rechazo: se resuelve la fila pero NO se concede el hash.
    const ins2 = st.db_conn.prepare(
        "INSERT INTO approvals (task_id, description, approved, resolved, created_at, command_prefix, exe, args_json, order_id) VALUES ('worktree_setup', 'worktree setup setup.cmd (sha256 bbbbbbbbbbbb)', 0, 0, 1, 'worktree_script', NULL, ?, 999)",
    ) catch return error.ExecFailed;
    db.bindText(ins2, 1, "{\"project_id\":\"proj-x\",\"script_sha256\":\"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb\",\"script\":\"setup.cmd\"}") catch return error.ExecFailed;
    try std.testing.expectEqual(db.c.SQLITE_DONE, db.c.sqlite3_step(ins2));
    st.db_conn.finalize(ins2);
    const reject_id = db.c.sqlite3_last_insert_rowid(st.db_conn.db);
    try std.testing.expectEqual(@as(c_int, 0), da_approval_resolve(handle, reject_id, 0));
    try std.testing.expect(!worktree_prepare.isScriptApproved(st.db_conn, "proj-x", "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"));

    // 5) La lista ya no ofrece las resueltas.
    var out2: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_approval_pending_json(handle, &out2));
    const listed2 = std.mem.span(out2);
    defer da_string_free(out2);
    try std.testing.expect(std.mem.indexOf(u8, listed2, "worktree_script") == null);
}

fn loadApprovalsFromDb(st: *CoreState, aa: std.mem.Allocator) void {
    const stmt = st.db_conn.prepare("SELECT id, task_id, description, approved, resolved, command_prefix, exe, args_json, order_id FROM approvals WHERE resolved = 0 ORDER BY id") catch return;
    defer st.db_conn.finalize(stmt);
    while (db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW) {
        const id = db.c.sqlite3_column_int64(stmt, 0);
        const task_ptr = db.c.sqlite3_column_text(stmt, 1);
        const task_len = db.c.sqlite3_column_bytes(stmt, 1);
        const desc_ptr = db.c.sqlite3_column_text(stmt, 2);
        const desc_len = db.c.sqlite3_column_bytes(stmt, 2);
        const approved = db.c.sqlite3_column_int(stmt, 3) != 0;
        const resolved = db.c.sqlite3_column_int(stmt, 4) != 0;
        const cp_ptr = db.c.sqlite3_column_text(stmt, 5);
        const cp_len = db.c.sqlite3_column_bytes(stmt, 5);
        const cp: ?[]const u8 = if (cp_len > 0) aa.dupe(u8, cp_ptr[0..@intCast(cp_len)]) catch null else null;
        const exe_ptr = db.c.sqlite3_column_text(stmt, 6);
        const exe_len = db.c.sqlite3_column_bytes(stmt, 6);
        const exe: ?[]const u8 = if (exe_len > 0) aa.dupe(u8, exe_ptr[0..@intCast(exe_len)]) catch null else null;
        const aj_ptr = db.c.sqlite3_column_text(stmt, 7);
        const aj_len = db.c.sqlite3_column_bytes(stmt, 7);
        const aj: ?[]const u8 = if (aj_len > 0) aa.dupe(u8, aj_ptr[0..@intCast(aj_len)]) catch null else null;
        const order_id = db.c.sqlite3_column_int64(stmt, 8);
        const rec = ApprovalRecord{
            .id = id,
            .task_id = aa.dupe(u8, task_ptr[0..@intCast(task_len)]) catch continue,
            .description = aa.dupe(u8, desc_ptr[0..@intCast(desc_len)]) catch continue,
            .approved = approved,
            .resolved = resolved,
            .command_prefix = cp,
            .exe = exe,
            .args_json = aj,
            .order_id = order_id,
        };
        st.approvals.append(aa, rec) catch {
            var rec_mut = rec;
            rec_mut.deinit(aa);
            continue;
        };
        if (id > st.last_approval_id) st.last_approval_id = id;
    }
}

fn persistedAssignment(st: *CoreState, aa: std.mem.Allocator, plan_id: i64, task_id: []const u8) !superagent.ModelAssignment {
    const stmt = try st.db_conn.prepare(
        "SELECT t.assigned_model_id FROM tasks t JOIN contracts c ON c.id = t.contract_id WHERE t.plan_id = ? AND c.name = ? ORDER BY t.id LIMIT 1",
    );
    defer st.db_conn.finalize(stmt);
    try db.bindInt(stmt, 1, plan_id);
    try db.bindText(stmt, 2, task_id);
    const task_rc = db.c.sqlite3_step(stmt);
    if (task_rc == db.c.SQLITE_DONE or (task_rc == db.c.SQLITE_ROW and db.c.sqlite3_column_type(stmt, 0) == db.c.SQLITE_NULL)) {
        return makeUnassignedAssignment(aa, task_id, "plan rehidratado sin modelo persistido");
    }
    if (task_rc != db.c.SQLITE_ROW) return error.ExecFailed;
    const model_id = db.c.sqlite3_column_int64(stmt, 0);
    const model_stmt = try st.catalog.db.prepare(
        "SELECT p.name, m.model_name, m.is_free FROM models m JOIN providers p ON p.id = m.provider_id WHERE m.id = ? LIMIT 1",
    );
    defer st.catalog.db.finalize(model_stmt);
    try db.bindInt(model_stmt, 1, model_id);
    const model_rc = db.c.sqlite3_step(model_stmt);
    if (model_rc == db.c.SQLITE_DONE) {
        return makeUnassignedAssignment(aa, task_id, "modelo persistido ya no existe en catalogo");
    }
    if (model_rc != db.c.SQLITE_ROW) return error.ExecFailed;
    const provider_ptr = db.c.sqlite3_column_text(model_stmt, 0) orelse return error.InvalidJson;
    const provider_len = db.c.sqlite3_column_bytes(model_stmt, 0);
    const model_ptr = db.c.sqlite3_column_text(model_stmt, 1) orelse return error.InvalidJson;
    const model_len = db.c.sqlite3_column_bytes(model_stmt, 1);
    const provider = try aa.dupe(u8, provider_ptr[0..@intCast(provider_len)]);
    errdefer aa.free(provider);
    const model = try aa.dupe(u8, model_ptr[0..@intCast(model_len)]);
    errdefer aa.free(model);
    const reason = try aa.dupe(u8, "asignacion primaria restaurada del plan persistido");
    errdefer aa.free(reason);
    const fallbacks = try aa.alloc(superagent.ModelChoice, 0);
    return .{
        .task_id = task_id,
        .assigned = true,
        .provider_name = provider,
        .model_name = model,
        .is_free = db.c.sqlite3_column_int(model_stmt, 2) != 0,
        .reason = reason,
        .fallbacks = fallbacks,
    };
}

fn makeUnassignedAssignment(aa: std.mem.Allocator, task_id: []const u8, reason: []const u8) !superagent.ModelAssignment {
    const provider = try aa.dupe(u8, "none");
    errdefer aa.free(provider);
    const model = try aa.dupe(u8, "none");
    errdefer aa.free(model);
    const owned_reason = try aa.dupe(u8, reason);
    errdefer aa.free(owned_reason);
    const fallbacks = try aa.alloc(superagent.ModelChoice, 0);
    return .{
        .task_id = task_id,
        .assigned = false,
        .provider_name = provider,
        .model_name = model,
        .is_free = false,
        .reason = owned_reason,
        .fallbacks = fallbacks,
    };
}

/// Rebuilds the in-memory execution object only for a plan that never started.
/// No worker, command, approval, or artifact is replayed here.
/// CHECKPOINT-T2: `expected_approved` decide qué planes acepta — la
/// rehidratación de arranque solo quiere planes aún SIN aprobar (0); la
/// reanudación de una orden interrumpida necesita justo el contrario (1).
fn loadPersistedPlannedOutcome(st: *CoreState, aa: std.mem.Allocator, order_id: i64, expected_approved: c_int) !?superagent.OrderOutcome {
    const plan_stmt = try st.db_conn.prepare(
        "SELECT id, understanding, approved FROM plans WHERE order_id = ? ORDER BY id DESC LIMIT 1",
    );
    defer st.db_conn.finalize(plan_stmt);
    try db.bindInt(plan_stmt, 1, order_id);
    const plan_rc = db.c.sqlite3_step(plan_stmt);
    if (plan_rc == db.c.SQLITE_DONE) return null;
    if (plan_rc != db.c.SQLITE_ROW) return error.ExecFailed;
    if (db.c.sqlite3_column_int(plan_stmt, 2) != expected_approved) return null;
    const plan_id = db.c.sqlite3_column_int64(plan_stmt, 0);
    const understanding_ptr = db.c.sqlite3_column_text(plan_stmt, 1) orelse return error.InvalidJson;
    const understanding_len = db.c.sqlite3_column_bytes(plan_stmt, 1);
    const understanding = understanding_ptr[0..@intCast(understanding_len)];

    var json_out: std.Io.Writer.Allocating = .init(aa);
    defer json_out.deinit();
    var js: std.json.Stringify = .{ .writer = &json_out.writer, .options = .{} };
    try js.beginObject();
    try js.objectField("understanding");
    try js.write(understanding);
    try js.objectField("tasks");
    try js.beginArray();

    const tasks_stmt = try st.db_conn.prepare(
        "SELECT c.name, t.task_type, t.department, t.description, c.interface_spec, c.consumers_json FROM tasks t JOIN contracts c ON c.id = t.contract_id WHERE t.plan_id = ? ORDER BY t.id",
    );
    defer st.db_conn.finalize(tasks_stmt);
    try db.bindInt(tasks_stmt, 1, plan_id);
    var task_rc = db.c.sqlite3_step(tasks_stmt);
    while (task_rc == db.c.SQLITE_ROW) : (task_rc = db.c.sqlite3_step(tasks_stmt)) {
        try js.beginObject();
        const names = [_][]const u8{ "id", "task_type", "department", "description" };
        for (names, 0..) |name, col| {
            const ptr = db.c.sqlite3_column_text(tasks_stmt, @intCast(col)) orelse return error.InvalidJson;
            const len = db.c.sqlite3_column_bytes(tasks_stmt, @intCast(col));
            try js.objectField(name);
            try js.write(ptr[0..@intCast(len)]);
        }
        for ([_]struct { name: []const u8, col: c_int }{
            .{ .name = "contract_fields", .col = 4 },
            .{ .name = "depends_on", .col = 5 },
        }) |field| {
            const ptr = db.c.sqlite3_column_text(tasks_stmt, field.col) orelse return error.InvalidJson;
            const len = db.c.sqlite3_column_bytes(tasks_stmt, field.col);
            var parsed = try std.json.parseFromSlice(std.json.Value, aa, ptr[0..@intCast(len)], .{});
            defer parsed.deinit();
            try js.objectField(field.name);
            try js.write(parsed.value);
        }
        try js.endObject();
    }
    if (task_rc != db.c.SQLITE_DONE) return error.ExecFailed;
    try js.endArray();
    try js.endObject();

    var plan = try planFromJson(aa, json_out.written());
    errdefer plan.deinit();
    if (plan.tasks.len == 0) {
        plan.deinit();
        return null;
    }
    const assignments = try aa.alloc(superagent.ModelAssignment, plan.tasks.len);
    var filled: usize = 0;
    errdefer {
        for (assignments[0..filled]) |assignment| assignment.deinit(aa);
        aa.free(assignments);
    }
    for (plan.tasks, 0..) |task, i| {
        assignments[i] = try persistedAssignment(st, aa, plan_id, task.id);
        filled += 1;
    }
    const discovery_needed = try aa.alloc([]const u8, 0);
    errdefer aa.free(discovery_needed);
    const discovery_missing = try aa.alloc([]const u8, 0);
    errdefer aa.free(discovery_missing);
    const discovery_needed_resources = try aa.alloc(tool_discovery.Resource, 0);
    errdefer aa.free(discovery_needed_resources);
    return .{
        .allocator = aa,
        .order_id = order_id,
        .plan_id = plan_id,
        .status = .planned,
        .plan = plan,
        .wait_for_plan_approval = try persistedPlanApprovalMode(st.db_conn, order_id),
        .assignments = assignments,
        .discovery_needed = discovery_needed,
        .discovery_missing = discovery_missing,
        .discovery_needed_resources = discovery_needed_resources,
    };
}

/// CHECKPOINT-T2: lee el checkpoint persistido de una orden interrumpida —
/// qué tareas del plan quedaron 'completed' (se restauran sin re-ejecutar) y
/// cuáles quedaron 'running' cuando el proceso murió (se reportan como
/// interrumpidas a medias y se re-ejecutan ENTERAS). Todo lo demás corre de
/// nuevo. Las cadenas devueltas son propiedad de `aa` (arena del CoreState —
/// viven tanto como el motor, más que cualquier despacho).
fn loadResumeCheckpoint(aa: std.mem.Allocator, conn: db.Connection, plan_id: i64) !superagent.ResumeCheckpoint {
    var restored: std.ArrayList(superagent.RestoredTask) = .empty;
    var interrupted: std.ArrayList([]const u8) = .empty;
    const stmt = try conn.prepare(
        "SELECT c.name, t.status, t.artifact_path FROM tasks t JOIN contracts c ON c.id = t.contract_id WHERE t.plan_id = ? ORDER BY t.id",
    );
    defer conn.finalize(stmt);
    try db.bindInt(stmt, 1, plan_id);
    while (db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW) {
        const nptr = db.c.sqlite3_column_text(stmt, 0) orelse continue;
        const nlen = db.c.sqlite3_column_bytes(stmt, 0);
        const name = try aa.dupe(u8, nptr[0..@intCast(nlen)]);
        const sptr = db.c.sqlite3_column_text(stmt, 1);
        const slen = db.c.sqlite3_column_bytes(stmt, 1);
        const status = if (sptr != null) sptr[0..@intCast(slen)] else "";
        if (std.mem.eql(u8, status, "completed")) {
            var art: ?[]const u8 = null;
            const aptr = db.c.sqlite3_column_text(stmt, 2);
            if (aptr != null) {
                const alen = db.c.sqlite3_column_bytes(stmt, 2);
                if (alen > 0) art = try aa.dupe(u8, aptr[0..@intCast(alen)]);
            }
            try restored.append(aa, .{ .task_id = name, .artifact_path = art });
        } else if (std.mem.eql(u8, status, "running")) {
            try interrupted.append(aa, name);
        } else {
            aa.free(name);
        }
    }
    return .{
        .restored = try restored.toOwnedSlice(aa),
        .interrupted = try interrupted.toOwnedSlice(aa),
    };
}

/// SESSIONS-PERSIST-06: rehidrata órdenes persistidas en runtime.db a CoreState.orders.
fn loadOrdersFromDb(st: *CoreState, aa: std.mem.Allocator) void {
    const stmt = st.db_conn.prepare("SELECT id, project_id, user_prompt, status, created_at, COALESCE(conversation_id,''), COALESCE(clarify_rounds,0) FROM orders ORDER BY created_at DESC") catch return;
    defer st.db_conn.finalize(stmt);
    while (db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW) {
        const db_id = db.c.sqlite3_column_int64(stmt, 0);
        const wait_for_plan_approval = persistedPlanApprovalMode(st.db_conn, db_id) catch |failure| {
            std.debug.print("order plan mode restore failed: {s}\n", .{@errorName(failure)});
            continue;
        };
        const proj_ptr = db.c.sqlite3_column_text(stmt, 1);
        const proj_len = db.c.sqlite3_column_bytes(stmt, 1);
        const prompt_ptr = db.c.sqlite3_column_text(stmt, 2);
        const prompt_len = db.c.sqlite3_column_bytes(stmt, 2);
        const status_ptr = db.c.sqlite3_column_text(stmt, 3);
        const status_len = db.c.sqlite3_column_bytes(stmt, 3);
        const created = db.c.sqlite3_column_int64(stmt, 4);
        const status_text = status_ptr[0..@intCast(status_len)];
        const status = std.meta.stringToEnum(superagent.OrderStatus, status_text) orelse .pending;
        const text = aa.dupe(u8, prompt_ptr[0..@intCast(prompt_len)]) catch continue;
        const project_id = aa.dupe(u8, proj_ptr[0..@intCast(proj_len)]) catch {
            aa.free(text);
            continue;
        };
        const questions = aa.dupe(u8, "[]") catch {
            aa.free(project_id);
            aa.free(text);
            continue;
        };
        const cptr = db.c.sqlite3_column_text(stmt, 5);
        const clen = db.c.sqlite3_column_bytes(stmt, 5);
        const conversation_id: ?[]const u8 = if (cptr != null and clen > 0)
            aa.dupe(u8, cptr[0..@intCast(clen)]) catch null
        else
            null;
        var restored_outcome: ?superagent.OrderOutcome = null;
        var restored_plan_json: ?[]const u8 = null;
        if (status == .planned) {
            restored_outcome = loadPersistedPlannedOutcome(st, aa, db_id, 0) catch null;
            if (restored_outcome) |*outcome| {
                restored_plan_json = planToJson(aa, &outcome.plan) catch null;
                if (restored_plan_json == null) {
                    outcome.deinit();
                    restored_outcome = null;
                }
            }
        }
        const rec = aa.create(OrderRecord) catch {
            if (restored_plan_json) |json| aa.free(json);
            if (restored_outcome) |*outcome| outcome.deinit();
            if (conversation_id) |conversation| aa.free(conversation);
            aa.free(questions);
            aa.free(project_id);
            aa.free(text);
            continue;
        };
        rec.* = OrderRecord{
            .id = db_id,
            .db_id = db_id,
            .text = text,
            .project_id = project_id,
            .status = status,
            .plan_json = restored_plan_json,
            .outcome = restored_outcome,
            .questions = questions,
            // El hilo se perdia al rehidratar: la consulta no lo leia, asi que
            // toda orden anterior al arranque volvia a memoria SIN
            // `conversation_id` y la barra lateral no podia agruparla. Se veia
            // como si cada peticion de una conversacion fuese una sesion suelta.
            .conversation_id = conversation_id,
            .created_at = created,
            .clarify_rounds = db.c.sqlite3_column_int64(stmt, 6),
            .wait_for_plan_approval = wait_for_plan_approval,
        };
        st.orders_mutex.lock();
        st.orders.append(aa, rec) catch {
            st.orders_mutex.unlock();
            rec.deinit(aa);
            aa.destroy(rec);
            continue;
        };
        st.orders_mutex.unlock();
        if (db_id > st.last_order_id) st.last_order_id = db_id;
    }
}

/// SESSIONS-PERSIST-06: guarda un turno de conversación en runtime.db.
/// P4: usa epoch ms (health.nowMillis) para que mensajes y eventos compartan escala temporal.
/// `conn`: MULTISESSION-P0 — se usa para el timestamp (health.nowMillis).
/// `sessions`: MULTISESSION-P0 (2026-07-12) — recibido explícito en vez de leer
/// `st.sessions` internamente. Los llamadores síncronos pasan `st.sessions` tal
/// cual (sin cambio de comportamiento); dispatchApprovedOrder pasa una vista
/// temporal (session_store.sessionStoreForConn) ligada a `conn` — última fuga
/// conocida hacia st.db_conn desde el hilo de dispatch, ahora cerrada.
fn saveMessageToDb(sessions: ?session_store.SessionStore, order_id: i64, role: []const u8, content: []const u8, conn: db.Connection) void {
    if (sessions) |s| {
        const now: i64 = health.nowMillis(conn);
        s.saveMessageFn(order_id, role, content, now) catch {};
    }
}

test "MULTISESSION-P0 SESSIONS-E: saveMessageToDb's best-effort failure never blocks a real terminal commit" {
    const allocator = std.testing.allocator;
    var conn = try db.Connection.open(allocator, ":memory:");
    defer conn.close();
    var migrator = db.Migrator.init(allocator);
    try migrator.migrate(conn, &db.runtime_schema);
    try conn.exec("INSERT INTO orders (id, project_id, user_prompt, status, created_at) VALUES (1, 'p', 'hello', 'running', 1)");

    // Romper deliberadamente la capacidad de guardar mensajes (tabla ausente) —
    // simula el tipo de fallo real que saveMessageFn puede encontrar (I/O, disco
    // lleno, esquema inesperado) sin inventar un mock artificial.
    try conn.exec("DROP TABLE messages");

    var scratch: session_store.SqliteBackend = undefined;
    const broken_view = session_store.sessionStoreForConn(conn, &scratch);

    // No debe paniquear ni propagar error (catch {} en saveMessageToDb).
    saveMessageToDb(broken_view, 1, "agent", "esto falla silenciosamente", conn);

    // Lo que de verdad importa: el fallo best-effort NO deja la conexión en un
    // estado (transacción a medias, lock colgado) que impida un commit terminal
    // real inmediatamente después — el mismo mecanismo (tryCommitTerminal) que
    // usa dispatchApprovedOrder para done/failed/cancelled.
    const committed = try conn.tryCommitTerminal(1, "done", "order_done", "superagente", "{}", 1000);
    try std.testing.expect(committed);

    const stmt = try conn.prepare("SELECT status FROM orders WHERE id = 1");
    defer conn.finalize(stmt);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
    const status_ptr = db.c.sqlite3_column_text(stmt, 0);
    const status_len = db.c.sqlite3_column_bytes(stmt, 0);
    try std.testing.expectEqualStrings("done", status_ptr[0..@intCast(status_len)]);
}

/// FASE-AGENTIC-1: recarga el historial de TODA la conversación desde runtime.db
/// (mensajes de todas las órdenes con el mismo conversation_id) en vez de
/// depender únicamente del ring buffer en RAM `st.history` — que se pierde al
/// reiniciar el motor y no distingue entre conversaciones distintas (todas las
/// conversaciones abiertas en el proceso compartían el mismo buffer global).
/// La BD pasa a ser la fuente de verdad para conversaciones con id explícito;
/// `st.history` se conserva sin cambios para el caso legacy (sin conversation_id).
/// El resultado debe liberarse con `.deinit(allocator)`.
fn loadConversationHistory(st: *CoreState, allocator: std.mem.Allocator, conversation_id: []const u8) planner.ConversationHistory {
    var hist = planner.ConversationHistory.empty;
    const sessions = st.sessions orelse return hist;
    if (conversation_id.len == 0) return hist;
    const msgs = sessions.loadConversationMessagesFn(allocator, conversation_id) catch return hist;
    defer {
        for (msgs) |m| {
            allocator.free(m.role);
            allocator.free(m.content);
        }
        allocator.free(msgs);
    }
    var pending_user: ?[]const u8 = null;
    for (msgs) |m| {
        if (std.mem.eql(u8, m.role, "user")) {
            pending_user = m.content;
        } else if (std.mem.eql(u8, m.role, "agent")) {
            if (pending_user) |u| {
                // push() duplica y trunca internamente; msgs se libera al salir.
                hist.push(allocator, u, m.content, MAX_HISTORY_TURNS, MAX_TURN_TEXT_BYTES) catch {};
                pending_user = null;
            }
        }
    }
    return hist;
}

/// FASE-AGENTIC-1: vincula `order_id` a `conversation_id` en runtime.db.
/// Best-effort: si falla (sin sessions/DB), la orden simplemente queda sin
/// hilo explícito — no debe interrumpir el flujo de la orden.
fn setOrderConversationId(st: *CoreState, order_id: i64, conversation_id: ?[]const u8) void {
    const cid = conversation_id orelse return;
    if (cid.len == 0) return;
    const sessions = st.sessions orelse return;
    sessions.setConversationIdFn(order_id, cid) catch {};
}

/// `conn`: MULTISESSION-P0 — todos estos helpers de escritura a runtime.db
/// reciben la Connection explícitamente en vez de leer `st.db_conn` — así el
/// hilo de dispatch (único llamador real de la mayoría) usa su propia conexión.
fn insertApprovalToDb(conn: db.Connection, task_id: []const u8, description: []const u8, created_at: i64, command_prefix: ?[]const u8, exe: ?[]const u8, args_json: ?[]const u8, order_id: i64) !i64 {
    return insertApprovalToDbOrigin(conn, task_id, description, created_at, command_prefix, exe, args_json, order_id, "");
}

/// T12B B-2 (auditor 3): como `insertApprovalToDb`, marcando la tarjeta con el
/// origen de la sesión MCP que la pide ("" = cabina o fila sin sesión).
fn insertApprovalToDbOrigin(conn: db.Connection, task_id: []const u8, description: []const u8, created_at: i64, command_prefix: ?[]const u8, exe: ?[]const u8, args_json: ?[]const u8, order_id: i64, origin: []const u8) !i64 {
    // El ID pertenece a esta sentencia, no al último INSERT de la conexión
    // (eventos y otras tarjetas pueden insertarse concurrentemente).
    const stmt = try conn.prepare("INSERT INTO approvals (task_id, description, approved, resolved, created_at, command_prefix, exe, args_json, order_id, origin) VALUES (?, ?, 0, 0, ?, ?, ?, ?, ?, ?) RETURNING id");
    defer conn.finalize(stmt);
    try db.bindText(stmt, 1, task_id);
    try db.bindText(stmt, 2, description);
    try db.bindInt(stmt, 3, created_at);
    if (command_prefix) |p| {
        try db.bindText(stmt, 4, p);
    } else {
        try db.bindText(stmt, 4, "");
    }
    if (exe) |e| {
        try db.bindText(stmt, 5, e);
    } else {
        try db.bindText(stmt, 5, "");
    }
    if (args_json) |a| {
        try db.bindText(stmt, 6, a);
    } else {
        try db.bindText(stmt, 6, "");
    }
    try db.bindInt(stmt, 7, order_id);
    try db.bindText(stmt, 8, origin);
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) return error.ExecFailed;
    const id = db.c.sqlite3_column_int64(stmt, 0);
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE) return error.ExecFailed;
    return id;
}

/// F0/A3: emite un evento approval_needed ligado a la orden (best-effort).
const MCP_WRITES_NOTE_WINDOW_MS = command_approval.MCP_WRITES_NOTE_WINDOW_MS;
const withRecentMcpWritesNote = command_approval.withRecentMcpWritesNote;

/// T12 M5: el MCP anota cada archivo que escribió con `fs_write` (evento
/// `mcp_file_written_v1`, ruta relativa a la raíz confinada). Solo para un
/// núcleo con superficie MCP: la cabina no escribe por esta vía.
pub export fn da_mcp_file_written(handle: ?*anyopaque, path: [*:0]const u8) callconv(.c) c_int {
    var buf: [4096]u8 = undefined;
    const root = ownedCStr(workspace.projectOrEffectiveRoot(&buf)) orelse return @intFromEnum(err(.oom, "MCP project root"));
    defer da_string_free(root);
    return da_mcp_file_written_v2(handle, root, path);
}

pub export fn da_mcp_file_written_v2(handle: ?*anyopaque, project_root: [*:0]const u8, path: [*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_mcp_file_written: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    if (!st.mcp_surface) return @intFromEnum(err(.invalid_state, "da_mcp_file_written: solo para la superficie MCP"));
    const rel = std.mem.span(path);
    if (rel.len == 0 or rel.len > 4096) return @intFromEnum(err(.invalid_arg, "da_mcp_file_written: ruta vacía o demasiado larga"));
    const aa = st.arena.child_allocator;
    const key = command_approval.projectKey(aa, std.mem.span(project_root)) catch return @intFromEnum(err(.invalid_arg, "MCP project root"));
    defer aa.free(key);
    const payload = std.json.Stringify.valueAlloc(aa, .{ .path = rel, .project_root = key }, .{}) catch return @intFromEnum(err(.oom, "da_mcp_file_written: OOM"));
    defer aa.free(payload);
    const stmt = st.db_conn.prepare("INSERT INTO events (ts, source, kind, payload_json, order_id) VALUES (?, 'mcp', 'mcp_file_written_v1', ?, 0)") catch return @intFromEnum(err(.internal, "da_mcp_file_written: no se pudo preparar el evento"));
    defer st.db_conn.finalize(stmt);
    db.bindInt(stmt, 1, health.nowMillis(st.db_conn)) catch return @intFromEnum(err(.internal, "da_mcp_file_written: bind"));
    db.bindText(stmt, 2, payload) catch return @intFromEnum(err(.internal, "da_mcp_file_written: bind"));
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE) return @intFromEnum(err(.internal, "da_mcp_file_written: no se pudo guardar el evento"));
    return @intFromEnum(ok());
}

fn insertApprovalEvent(conn: db.Connection, aa: std.mem.Allocator, order_id: i64, approval_id: i64, task_id: []const u8, description: []const u8, command_prefix: ?[]const u8) void {
    command_approval.emitNeeded(conn, aa, order_id, approval_id, task_id, description, command_prefix) catch |e| std.log.err("approval_needed event: {s}", .{@errorName(e)});
}

fn updateApprovalResolved(st: *CoreState, id: i64, approved: bool) !void {
    const stmt = try st.db_conn.prepare("UPDATE approvals SET approved = ?, resolved = 1 WHERE id = ?");
    defer st.db_conn.finalize(stmt);
    try db.bindInt(stmt, 1, if (approved) 1 else 0);
    try db.bindInt(stmt, 2, id);
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE) return error.ExecFailed;
}

const ClosedApproval = struct { id: i64, order_id: i64 };

const TERMINAL_ORDER_STATUSES = [_][]const u8{ "done", "failed", "rejected", "cancelled", "interrupted", "audit_unavailable" };

fn isTerminalOrderStatus(status: []const u8) bool {
    for (TERMINAL_ORDER_STATUSES) |t| {
        if (std.mem.eql(u8, status, t)) return true;
    }
    return false;
}

const OrderLiveness = enum { missing, live, terminal };

/// (auditoría el segundo auditor): estado real de la orden de una aprobación. Ante
/// cualquier duda de lectura devuelve `.live` — nunca bloquear una aprobación
/// legítima por un fallo transitorio de la consulta.
fn orderLiveness(conn: db.Connection, order_id: i64) OrderLiveness {
    if (order_id <= 0) return .live;
    const stmt = conn.prepare("SELECT status FROM orders WHERE id = ?") catch return .live;
    defer conn.finalize(stmt);
    db.bindInt(stmt, 1, order_id) catch return .live;
    const rc = db.c.sqlite3_step(stmt);
    if (rc == db.c.SQLITE_DONE) return .missing;
    if (rc != db.c.SQLITE_ROW) return .live;
    const p = db.c.sqlite3_column_text(stmt, 0);
    if (p == null) return .live;
    return if (isTerminalOrderStatus(std.mem.span(p))) .terminal else .live;
}

/// deja el motivo del cierre en la traza. El esquema de `approvals`
/// no tiene columna de razón, así que el "por qué" vive en `events` como
/// `approval_closed` (append-only, sin tocar la fila auditada).
///
/// r3 (auditoría el segundo auditor): devuelve error si el evento no se pudo
/// escribir. El criterio pide que TODO cierre quede explicado; si el motivo no
/// llega a la traza, el llamador debe revertir la transacción en vez de dejar
/// una fila `resolved = 1` sin su evento.
fn emitApprovalClosed(conn: db.Connection, approval_id: i64, order_id: i64, now_ms: i64, reason: []const u8) !void {
    var buf: [256]u8 = undefined;
    const payload = std.fmt.bufPrint(&buf, "{{\"approval_id\":{d},\"reason\":\"{s}\"}}", .{ approval_id, reason }) catch return error.OutOfMemory;
    const stmt = try conn.prepare("INSERT INTO events (ts, source, kind, payload_json, order_id) VALUES (?, 'core', 'approval_closed', ?, ?)");
    defer conn.finalize(stmt);
    try db.bindInt(stmt, 1, now_ms);
    try db.bindText(stmt, 2, payload);
    try db.bindInt(stmt, 3, order_id);
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE) return error.ExecFailed;
}

/// (tanda 1, 12-nov): deja en la traza de la orden que el usuario
/// resolvió una aprobación. Sin este evento el hilo no sabía que la tarjeta
/// «Hace falta tu aprobación» ya estaba contestada y la seguía pintando.
/// La resolución ya ocurrió: si el evento no se escribe, se registra el fallo
/// y la cabina sigue viendo la tarjeta hasta que la orden avance.
fn emitApprovalResolved(conn: db.Connection, approval_id: i64, order_id: i64, approved: bool) void {
    if (order_id <= 0) return;
    var buf: [96]u8 = undefined;
    const payload = std.fmt.bufPrint(&buf, "{{\"approval_id\":{d},\"approved\":{s}}}", .{ approval_id, if (approved) "true" else "false" }) catch unreachable;
    const stmt = conn.prepare("INSERT INTO events (ts, source, kind, payload_json, order_id) VALUES (?, 'core', 'approval_resolved', ?, ?)") catch |e| {
        std.log.err("approval_resolved prepare: {s}", .{@errorName(e)});
        return;
    };
    defer conn.finalize(stmt);
    db.bindInt(stmt, 1, health.nowMillis(conn)) catch |e| return std.log.err("approval_resolved bind: {s}", .{@errorName(e)});
    db.bindText(stmt, 2, payload) catch |e| return std.log.err("approval_resolved bind: {s}", .{@errorName(e)});
    db.bindInt(stmt, 3, order_id) catch |e| return std.log.err("approval_resolved bind: {s}", .{@errorName(e)});
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE) std.log.err("approval_resolved insert failed", .{});
}

/// (auditoría el segundo auditor): cierra UNA aprobación pendiente. Devuelve true
/// solo si el UPDATE ganó (la fila seguía con `resolved = 0`), false si ya
/// estaba resuelta. Devuelve error si el UPDATE ganó pero el evento
/// `approval_closed` no se pudo insertar: el UPDATE y el evento comparten la
/// transacción abierta por el llamador, que debe hacer ROLLBACK para no dejar
/// una fila cerrada sin su motivo. No hace BEGIN/COMMIT.
fn closeApprovalRow(conn: db.Connection, id: i64, order_id: i64, now_ms: i64, reason: []const u8) !bool {
    const upd = try conn.prepare("UPDATE approvals SET resolved = 1, approved = 0 WHERE id = ? AND resolved = 0 RETURNING id");
    defer conn.finalize(upd);
    try db.bindInt(upd, 1, id);
    const rc = db.c.sqlite3_step(upd);
    if (rc == db.c.SQLITE_DONE) return false;
    if (rc != db.c.SQLITE_ROW) return error.ExecFailed;
    try emitApprovalClosed(conn, id, order_id, now_ms, reason);
    return true;
}

/// cierra una aprobación en su propia transacción y refleja el
/// cierre en la copia en memoria que lista el Monitor. Devuelve true si la fila
/// cambió; false si ya estaba resuelta o el UPDATE/COMMIT falló.
fn closeStaleApprovalById(st: ?*CoreState, conn: db.Connection, id: i64, order_id: i64, now_ms: i64, reason: []const u8) bool {
    conn.exec("BEGIN IMMEDIATE") catch return false;
    const changed = closeApprovalRow(conn, id, order_id, now_ms, reason) catch {
        // El motivo no se pudo registrar: revertir el cierre entero (no dejar
        // una fila resuelta sin su evento).
        conn.exec("ROLLBACK") catch {};
        return false;
    };
    conn.exec("COMMIT") catch {
        conn.exec("ROLLBACK") catch {};
        return false;
    };
    if (!changed) return false;
    if (st) |s| {
        s.output_mutex.lock();
        defer s.output_mutex.unlock();
        for (s.approvals.items) |*a| {
            if (a.id == id and !a.resolved) {
                a.approved = false;
                a.resolved = true;
            }
        }
    }
    return true;
}

/// (H-PB-6): cierra (resolved=1, approved=0) las aprobaciones sin
/// resolver cuya orden ya es terminal y, si `include_orphans`, las que apuntan
/// a una orden inexistente (order_id>0 — el 0 lo usan aprobaciones del CLI
/// driver que llevan la orden en task_id="order-N"). No borra filas (auditoría):
/// solo marca resuelta-denegada y deja un evento `approval_closed` con el
/// motivo. Con `st`, refleja el cierre en la copia en memoria que lista el
/// Monitor, pero SOLO de las filas cuyo UPDATE ganó (auditoría el segundo auditor: antes
/// marcaba candidatas cuyo UPDATE pudo fallar, divergiendo memoria y base).
/// Los UPDATE y sus eventos viven en la MISMA transacción. Idempotente.
fn closeStaleApprovals(st: ?*CoreState, conn: db.Connection, include_orphans: bool, now_ms: i64, reason: []const u8) void {
    var closed: std.ArrayListUnmanaged(ClosedApproval) = .empty;
    defer closed.deinit(conn.allocator);
    const sel = conn.prepare(
        \\SELECT a.id, a.order_id FROM approvals a
        \\WHERE a.resolved = 0 AND (
        \\    EXISTS (SELECT 1 FROM orders o WHERE o.id = a.order_id
        \\            AND o.status IN ('done','failed','rejected','cancelled','interrupted','audit_unavailable'))
        \\    OR (?1 AND a.order_id > 0
        \\        AND NOT EXISTS (SELECT 1 FROM orders o WHERE o.id = a.order_id))
        \\)
    ) catch return;
    defer conn.finalize(sel);
    db.bindInt(sel, 1, if (include_orphans) 1 else 0) catch return;
    while (db.c.sqlite3_step(sel) == db.c.SQLITE_ROW) {
        closed.append(conn.allocator, .{
            .id = db.c.sqlite3_column_int64(sel, 0),
            .order_id = db.c.sqlite3_column_int64(sel, 1),
        }) catch break;
    }
    if (closed.items.len == 0) return;

    // Auditoría el segundo auditor (punto 3): el UPDATE de cada fila y su evento van en la
    // MISMA transacción. Si algo falla, ROLLBACK deja todo como estaba.
    //
    // r4 (auditoría el segundo auditor, punto 2): reservar la capacidad de `done`
    // ANTES de abrir la transacción. Así el `append` posterior no puede fallar
    // (con `appendAssumeCapacity`) una vez hecho el COMMIT, lo que dejaría filas
    // cerradas en la base pero sin reflejar en `st.approvals` (tarjeta colgada).
    // Si la reserva falla no se cierra nada: la base queda intacta.
    var done: std.ArrayListUnmanaged(ClosedApproval) = .empty;
    defer done.deinit(conn.allocator);
    done.ensureTotalCapacity(conn.allocator, closed.items.len) catch return;

    conn.exec("BEGIN IMMEDIATE") catch return;
    for (closed.items) |c| {
        const changed = closeApprovalRow(conn, c.id, c.order_id, now_ms, reason) catch {
            // r3 (auditoría el segundo auditor): el evento `approval_closed` no se
            // pudo escribir; revertir TODO el lote y no marcar nada en memoria,
            // para que ninguna fila quede cerrada sin su motivo.
            conn.exec("ROLLBACK") catch {};
            return;
        };
        if (changed) done.appendAssumeCapacity(c);
    }
    conn.exec("COMMIT") catch {
        conn.exec("ROLLBACK") catch {};
        return;
    };
    if (done.items.len == 0) return;

    if (st) |s| {
        s.output_mutex.lock();
        defer s.output_mutex.unlock();
        for (s.approvals.items) |*a| {
            if (a.resolved) continue;
            for (done.items) |c| {
                if (a.id == c.id) {
                    a.approved = false;
                    a.resolved = true;
                    break;
                }
            }
        }
    }
}

/// Solo una UI gana la resolución persistida, incluso con varios procesos.
/// El ganador ejecuta; un doble clic/reintento no puede lanzar otro hijo.
const ClaimOutcome = enum { won, already_resolved, order_terminal, order_missing };

/// r3 (auditoría el segundo auditor) + r4 (auditoría el segundo auditor): reclama la aprobación y
/// comprueba, en la MISMA sentencia UPDATE, que su orden EXISTA y no sea
/// terminal. Antes la comprobación del estado y la reclamación eran dos
/// operaciones separadas: si la orden terminaba en medio, un comando podía
/// lanzarse tras el fin de la orden. r4: el `NOT EXISTS` solo excluía órdenes
/// terminales, de modo que una orden BORRADA (sin fila en `orders`) podía
/// reclamarse; ahora con `order_id > 0` hace falta un `EXISTS` de la orden viva.
///
/// `won`: la fila era `resolved = 0`, su orden existe y no es terminal.
/// `already_resolved`: la fila ya estaba resuelta (o no existe).
/// `order_terminal`: la fila sigue `resolved = 0` porque la orden es terminal.
/// `order_missing`: la fila sigue `resolved = 0` porque la orden ya no existe.
/// En los dos últimos el llamador debe cerrarla con su motivo y no ejecutar nada.
fn claimCommandApproval(st: *CoreState, id: i64, approved: bool) !ClaimOutcome {
    // RETURNING vincula el resultado al statement. sqlite3_changes pertenece
    // a la conexión y otra llamada concurrente podría sobrescribirlo.
    const query = try st.db_conn.prepare(
        \\UPDATE approvals SET approved=?, resolved=1
        \\WHERE id=? AND resolved=0
        \\  AND (approvals.order_id <= 0
        \\       OR EXISTS (
        \\           SELECT 1 FROM orders o
        \\           WHERE o.id = approvals.order_id
        \\             AND o.status NOT IN ('done','failed','rejected','cancelled','interrupted','audit_unavailable')))
        \\RETURNING id
    );
    defer st.db_conn.finalize(query);
    try db.bindInt(query, 1, if (approved) 1 else 0);
    try db.bindInt(query, 2, id);
    const rc = db.c.sqlite3_step(query);
    if (rc == db.c.SQLITE_DONE) {
        // El UPDATE no tocó ninguna fila. Con `id=?` y `resolved=0` ya en el
        // WHERE, la única condición que pudo fallar es el estado de la orden
        // (terminal o inexistente); si la fila no existe o ya estaba resuelta,
        // es un simple "ya resuelta". Distinguimos terminal de inexistente para
        // que el cierre lleve el motivo correcto.
        const sel = try st.db_conn.prepare("SELECT resolved, order_id FROM approvals WHERE id = ?");
        defer st.db_conn.finalize(sel);
        try db.bindInt(sel, 1, id);
        if (db.c.sqlite3_step(sel) != db.c.SQLITE_ROW) return .already_resolved;
        if (db.c.sqlite3_column_int64(sel, 0) != 0) return .already_resolved;
        const oid = db.c.sqlite3_column_int64(sel, 1);
        if (oid > 0 and orderLiveness(st.db_conn, oid) == .missing) return .order_missing;
        return .order_terminal;
    }
    if (rc != db.c.SQLITE_ROW) return error.ExecFailed;
    if (db.c.sqlite3_column_int64(query, 0) != id) return error.ExecFailed;
    if (db.c.sqlite3_step(query) != db.c.SQLITE_DONE) return error.ExecFailed;
    return .won;
}

fn insertWorkerOutputEvent(conn: db.Connection, aa: std.mem.Allocator, order_id: i64, worker_id: []const u8, stream: []const u8, text: []const u8, seq: i64, task_id: []const u8) !void {
    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginObject() catch return error.OutOfMemory;
    js.objectField("stream") catch return error.OutOfMemory;
    js.write(stream) catch return error.OutOfMemory;
    js.objectField("text") catch return error.OutOfMemory;
    js.write(text) catch return error.OutOfMemory;
    js.objectField("seq") catch return error.OutOfMemory;
    js.write(seq) catch return error.OutOfMemory;
    if (task_id.len > 0) {
        js.objectField("task_id") catch return error.OutOfMemory;
        js.write(task_id) catch return error.OutOfMemory;
    }
    js.endObject() catch return error.OutOfMemory;
    const payload = out.written();
    const stmt = try conn.prepare("INSERT INTO events (ts, source, kind, payload_json, order_id) VALUES (?, ?, 'worker_output', ?, ?)");
    defer conn.finalize(stmt);
    try db.bindInt(stmt, 1, seq);
    try db.bindText(stmt, 2, worker_id);
    try db.bindText(stmt, 3, payload);
    try db.bindInt(stmt, 4, order_id);
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE) return error.ExecFailed;
}

fn persistOrderTasksStatus(conn: db.Connection, order_id: i64, status: []const u8) void {
    const stmt = conn.prepare(
        \\UPDATE tasks
        \\SET status = ?
        \\WHERE plan_id IN (SELECT id FROM plans WHERE order_id = ?)
    ) catch return;
    defer conn.finalize(stmt);
    db.bindText(stmt, 1, status) catch return;
    db.bindInt(stmt, 2, order_id) catch return;
    _ = db.c.sqlite3_step(stmt);
}

/// TERMINAL-STATE-DESIGN-2026-07-12 (P0 cierre): copia en memoria (`rec.status`)
/// lo que `orders.status` realmente tiene en DB — la DB es la autoridad. Si la
/// lectura falla o el valor no mapea a un `OrderStatus` conocido, `rec.status`
/// queda intacto (no se asume nada sin confirmación).
fn syncRecStatusFromDb(conn: db.Connection, rec: *OrderRecord) void {
    const stmt = conn.prepare("SELECT status FROM orders WHERE id = ?") catch return;
    defer conn.finalize(stmt);
    // db_id != id cuando processOrder insertó una fila nueva (p. ej. tras
    // resolver una clarificación): el estado real vive en esa fila.
    db.bindInt(stmt, 1, rec.db_id orelse rec.id) catch return;
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) return;
    const ptr = db.c.sqlite3_column_text(stmt, 0) orelse return;
    const len = db.c.sqlite3_column_bytes(stmt, 0);
    const text = ptr[0..@intCast(len)];
    if (std.meta.stringToEnum(superagent.OrderStatus, text)) |parsed| {
        rec.status = parsed;
    }
}

/// Par proveedor/modelo candidato a sondeo (strings en arena de CoreState).
const ProbePair = struct { provider: []const u8, model: []const u8 };

const ProbeAllSummary = struct {
    candidates: usize = 0,
    probed: usize = 0,
    ok: usize = 0,
    failed: usize = 0,
    skipped: usize = 0,
    disabled_not_found: usize = 0,
    /// r3: resultado del volcado del escenario a `model_health` real.
    /// `merge_ok` filas fusionadas, `merge_failed` que no. Con `merge_failed > 0`
    /// la ronda NO se presenta como éxito (el evento lo lleva).
    merge_ok: usize = 0,
    merge_failed: usize = 0,
};

/// una ronda de sondeo sin ningún OK no es señal sobre los modelos
/// (más bien sobre la red o la cuota): no debe escribir salud.
fn autoVerifyAllProbesFailed(summary: ProbeAllSummary) bool {
    return summary.probed > 0 and summary.ok == 0;
}

fn mergeStagedHealth(
    st: *CoreState,
    conn: db.Connection,
    rows: []const health.StagedHealthRow,
    summary: ProbeAllSummary,
    order_id: i64,
    failures: u32,
) MergeStagedOutcome {
    if (autoVerifyAllProbesFailed(summary)) {
        emitAutoVerifyEvent(st, "auto_verify_skipped", order_id, failures, summary, conn, .{ .reason = "all_probes_failed" });
        return .{};
    }
    return mergeStagedRowsLogged(st, conn, rows, summary, order_id, failures);
}

/// r4: tope de filas fallidas que el resultado conserva para
/// identificarlas una a una. El escenario nunca tiene más de
/// AUTO_VERIFY_MAX_MODELS (24) filas, así que 32 cubre el caso real.
const MERGE_FAILURE_LIST_MAX: usize = 32;

/// r4: una fila que no se pudo volcar, con el error concreto que
/// devolvió health.mergeStagedRow. `model_id`/`key_label` apuntan a las
/// cadenas de las filas del escenario: solo son válidas mientras viva `rows`.
const MergeStagedFailure = struct {
    model_id: []const u8,
    key_label: []const u8,
    err: db.DbError,
};

/// r3/r4: resultado explícito del volcado del escenario. Deja saber
/// al llamador cuántas filas se fusionaron y cuáles no; cada fallida queda
/// identificada (model_id, key_label y error concreto), no solo la primera.
const MergeStagedOutcome = struct {
    merged: usize = 0,
    failed: usize = 0,
    /// Error original de la primera fila que no se pudo volcar; `null` si todas
    /// se fusionaron. Con valor no nulo el llamador NO debe declarar éxito.
    first_error: ?db.DbError = null,
    /// Una entrada por fila fallida, en orden de aparición, hasta
    /// MERGE_FAILURE_LIST_MAX. `failure_len` dice cuántas son válidas.
    failures: [MERGE_FAILURE_LIST_MAX]MergeStagedFailure = undefined,
    failure_len: usize = 0,
};

/// r2/r3/r4: vuelca las filas del escenario a model_health real. Un
/// fallo de volcado (BD bloqueada, trigger, E/S) NO puede tragarse: se sigue
/// con las demás filas, cada fallo se guarda en el resultado y se registra en
/// `events` con su fila y su error concreto (un evento por fila fallida).
fn mergeStagedRowsLogged(
    st: *CoreState,
    conn: db.Connection,
    rows: []const health.StagedHealthRow,
    summary: ProbeAllSummary,
    order_id: i64,
    failures: u32,
) MergeStagedOutcome {
    var out: MergeStagedOutcome = .{};
    for (rows) |row| {
        health.mergeStagedRow(conn, row) catch |merge_err| {
            out.failed += 1;
            if (out.first_error == null) out.first_error = merge_err;
            if (out.failure_len < MERGE_FAILURE_LIST_MAX) {
                out.failures[out.failure_len] = .{
                    .model_id = row.model_id,
                    .key_label = row.key_label,
                    .err = merge_err,
                };
                out.failure_len += 1;
            }
            continue;
        };
        out.merged += 1;
    }
    var i: usize = 0;
    while (i < out.failure_len) : (i += 1) {
        const failed_row = out.failures[i];
        emitAutoVerifyEvent(st, "auto_verify_merge_failed", order_id, failures, summary, conn, .{
            .reason = "merge_failed",
            .err = failed_row.err,
            .model_id = failed_row.model_id,
            .key_label = failed_row.key_label,
            .merge_ok = out.merged,
            .merge_failed = out.failed,
        });
    }
    if (out.failed > out.failure_len) {
        emitAutoVerifyEvent(st, "auto_verify_merge_failed", order_id, failures, summary, conn, .{
            .reason = "merge_failed_truncated",
            .err = out.first_error,
            .merge_ok = out.merged,
            .merge_failed = out.failed,
        });
    }
    return out;
}

/// r2: abre el escenario del sondeo automático. Devuelve error si el
/// test lo fuerza o si la BD en memoria no se puede crear/inicializar; el
/// llamador debe fallar cerrado (nunca sondear contra la salud real).
fn openAutoVerifyStaging(st: *CoreState, aa: std.mem.Allocator) !db.Connection {
    if (st.auto_verify_stage_unavailable) return error.StagingUnavailable;
    var sc = try db.Connection.open(aa, ":memory:");
    errdefer sc.close();
    try health.initStaging(sc);
    return sc;
}

/// ronda serial de sondeo, con escenario opcional. Con
/// `sink == .staged` los sondeos escriben en una BD en memoria y solo se
/// vuelcan a `conn` cuando la ronda tuvo algún OK; una ronda 24/24 fallida es
/// señal local (red, proxy, reloj) y deja `model_health` intacta. La usan la
/// vía serial (`:memory:` / sin pares) y el repliegue por OOM del paralelo.
fn probePairsStaged(
    st: *CoreState,
    aa: std.mem.Allocator,
    pairs: []const ProbePair,
    conn: db.Connection,
    sink: HealthProbeSink,
    auto_order_id: i64,
    failures: u32,
    summary: *ProbeAllSummary,
) void {
    var stage_conn: ?db.Connection = null;
    if (sink == .staged) {
        stage_conn = openAutoVerifyStaging(st, aa) catch {
            // FALLO CERRADO (r2): sin escenario no se sondea ni se escribe en la
            // salud real; la ronda queda entera como skipped y se registra el
            // motivo. Antes se replegaba a `conn` y contaminaba model_health.
            emitAutoVerifyEvent(st, "auto_verify_staging_failed", auto_order_id, failures, .{}, conn, .{ .reason = "staging_unavailable" });
            summary.candidates += pairs.len;
            summary.skipped += pairs.len;
            return;
        };
    }
    defer if (stage_conn) |*sc| sc.close();
    const probe_conn = if (stage_conn) |sc| sc else conn;
    for (pairs) |p| {
        summary.candidates += 1;
        const status = probeModelWith(st.auto_verify_probe_fn, aa, st.catalog_path, probe_conn, p.provider, p.model) orelse {
            summary.skipped += 1;
            continue;
        };
        summary.probed += 1;
        if (status == .ok) {
            summary.ok += 1;
        } else {
            summary.failed += 1;
        }
    }
    if (stage_conn) |sc| {
        const staged = health.readStagedRows(aa, sc) catch null;
        const outcome = if (staged) |rows| blk: {
            defer health.freeStagedRows(aa, rows);
            break :blk mergeStagedHealth(st, conn, rows, summary.*, auto_order_id, failures);
        } else mergeStagedHealth(st, conn, &.{}, summary.*, auto_order_id, failures);
        summary.merge_ok += outcome.merged;
        summary.merge_failed += outcome.failed;
    }
}

/// una llamada de sondeo, con costura de pruebas opcional.
fn probeModelWith(
    probe_fn: ?AutoVerifyProbeFn,
    allocator: std.mem.Allocator,
    catalog_path: []const u8,
    runtime: db.Connection,
    provider: []const u8,
    model: []const u8,
) ?health.Status {
    if (probe_fn) |f| return f(allocator, catalog_path, runtime, provider, model, "ping");
    return live_worker.probeModel(allocator, catalog_path, runtime, provider, model, "ping");
}

/// el sondeo manual escribe la salud directamente; el automático
/// escribe en un escenario y solo lo vuelca si la ronda no falló entera.
const HealthProbeSink = enum { direct, staged };

fn runActiveHealthProbeAll(st: *CoreState, max_models: usize, conn: db.Connection) ProbeAllSummary {
    return runHealthProbeAll(st, max_models, conn, .direct, 0, 0);
}

fn runAutoHealthProbeAll(st: *CoreState, max_models: usize, conn: db.Connection, order_id: i64, failures: u32) ProbeAllSummary {
    return runHealthProbeAll(st, max_models, conn, .staged, order_id, failures);
}

fn runHealthProbeAll(
    st: *CoreState,
    max_models: usize,
    conn: db.Connection,
    sink: HealthProbeSink,
    auto_order_id: i64,
    failures: u32,
) ProbeAllSummary {
    const aa = st.arena.child_allocator;
    var summary: ProbeAllSummary = .{};
    const limit = if (max_models == 0) std.math.maxInt(usize) else max_models;
    const stmt = st.catalog.db.prepare(
        \\SELECT p.name, m.model_name
        \\FROM models m JOIN providers p ON m.provider_id = p.id
        \\WHERE p.enabled = 1
        \\  AND m.available = 1
        \\  AND m.is_free = 1
    ++ @import("model_capabilities.zig").sql_filter ++
        \\ORDER BY m.is_favorite DESC, p.name, m.model_name
    ) catch return summary;

    // PASO 1: volcar los pares proveedor/modelo y FINALIZAR la sentencia.
    //
    // Antes se sondeaba DENTRO del bucle del `SELECT`, con la sentencia de
    // lectura abierta sobre `st.catalog.db`. Y `probeModel` no se limita a
    // escribir: reabre el MISMO catálogo por ruta
    // (`LiveLlm.initForced(allocator, catalog_path, ...)`) y escribe salud en
    // `conn`. O sea, un cursor de lectura vivo sobre un archivo que otra
    // conexión está modificando, durante toda la ronda de red.
    //
    // Es el paso 2 del plan de CRASH-SONDEO-SALUD.md y el sospechoso que ese
    // documento señala por su nombre. Volcar primero y sondear después elimina
    // el solapamiento por completo, y además libera el bloqueo de lectura del
    // catálogo mientras se espera a la red — que puede ser minutos.
    const Pair = ProbePair;
    var pairs = std.ArrayList(Pair).empty;
    defer {
        for (pairs.items) |p| {
            aa.free(p.provider);
            aa.free(p.model);
        }
        pairs.deinit(aa);
    }

    {
        defer st.catalog.db.finalize(stmt);
        while (pairs.items.len < limit and db.c.sqlite3_step(@as(?*db.c.sqlite3_stmt, stmt)) == db.c.SQLITE_ROW) {
            const provider_ptr = db.c.sqlite3_column_text(stmt, 0) orelse continue;
            const model_ptr = db.c.sqlite3_column_text(stmt, 1) orelse continue;
            // Se DUPLICAN: los punteros de sqlite3_column_text solo son válidos
            // hasta el siguiente step o el finalize. Guardar el slice prestado y
            // usarlo después del bucle sería leer memoria liberada — el mismo
            // fallo de la familia /.
            const provider = aa.dupe(u8, provider_ptr[0..std.mem.len(provider_ptr)]) catch continue;
            const model = aa.dupe(u8, model_ptr[0..std.mem.len(model_ptr)]) catch {
                aa.free(provider);
                continue;
            };
            pairs.append(aa, .{ .provider = provider, .model = model }) catch {
                aa.free(provider);
                aa.free(model);
                continue;
            };
        }
    }

    // PASO 2: sondear, ya sin ninguna sentencia abierta sobre el catálogo.
    //
    // SONDO-PARALELO (mesa redonda): un hilo POR PROVEEDOR, nunca por modelo —
    // lanzar N peticiones simultáneas contra la misma clave provoca los 429 de
    // los free-tiers que el sondeo intenta medir. Dentro del hilo los modelos
    // se prueban en serie, y tras 2 fallos consecutivos de auth/timeout/429 el
    // resto del proveedor se marca skipped sin quemar más peticiones.
    //
    // Cada hilo lleva su propio ArenaAllocator y su propia conexión al runtime:
    // ni el allocator ni db.Connection son compartibles entre hilos.
    // En ":memory:" cada open abre una BD distinta — ahí no hay reconciliación
    // posible y el sondeo queda serial (los tests la usan).
    if (std.mem.eql(u8, st.runtime_path, ":memory:") or pairs.items.len == 0) {
        probePairsStaged(st, aa, pairs.items, conn, sink, auto_order_id, failures, &summary);
    } else {
        // La consulta ya ordena por proveedor: agrupar es cortar el array.
        var groups = std.ArrayList([]const Pair).empty;
        defer groups.deinit(aa);
        var start: usize = 0;
        while (start < pairs.items.len) {
            var end = start + 1;
            while (end < pairs.items.len and
                std.mem.eql(u8, pairs.items[end].provider, pairs.items[start].provider)) : (end += 1)
            {}
            groups.append(aa, pairs.items[start..end]) catch break;
            start = end;
        }

        const ctxs = aa.alloc(ProbeWorkerCtx, groups.items.len) catch blk: {
            // OOM al repartir trabajo: antes que perder la ronda entera, cae al
            // camino serial de siempre — igual de correcta, solo más lenta — y
            // también con escenario: la regla 24/24 vale en las dos vías.
            probePairsStaged(st, aa, pairs.items, conn, sink, auto_order_id, failures, &summary);
            break :blk null;
        };
        if (ctxs) |list| {
            const threads = aa.alloc(std.Thread, list.len) catch null;
            var spawned: usize = 0;
            if (threads) |ts| {
                for (list, 0..) |*ctx, i| {
                    ctx.* = .{
                        .pairs = groups.items[i],
                        .catalog_path = st.catalog_path,
                        .runtime_path = st.runtime_path,
                        .probe_fn = st.auto_verify_probe_fn,
                        .stage_health = sink == .staged,
                        .stage_unavailable = st.auto_verify_stage_unavailable,
                    };
                    ts[i] = std.Thread.spawn(.{}, probeWorker, .{ctx}) catch break;
                    spawned += 1;
                }
                for (ts[0..spawned]) |t| t.join();
            }
            // Los ctx que no llegaron a hilo (spawn o alloc falló) se sondean
            // aquí en serie: el sondeo nunca se pierde por falta de hilos.
            for (list[spawned..]) |*ctx| probeWorker(ctx);
            for (list) |ctx| {
                summary.candidates += ctx.summary.candidates;
                summary.probed += ctx.summary.probed;
                summary.ok += ctx.summary.ok;
                summary.failed += ctx.summary.failed;
                summary.skipped += ctx.summary.skipped;
            }
            if (sink == .staged) {
                var staging_failed = false;
                for (list) |ctx| {
                    if (ctx.staging_failed) staging_failed = true;
                }
                if (staging_failed) {
                    // FALLO CERRADO (r2): ningún hilo pudo crear su escenario;
                    // no se vuelca nada a la salud real (los grupos quedaron
                    // skipped) y se registra el motivo.
                    emitAutoVerifyEvent(st, "auto_verify_staging_failed", auto_order_id, failures, summary, conn, .{ .reason = "staging_unavailable" });
                } else if (autoVerifyAllProbesFailed(summary)) {
                    emitAutoVerifyEvent(st, "auto_verify_skipped", auto_order_id, failures, summary, conn, .{ .reason = "all_probes_failed" });
                } else {
                    for (list) |ctx| {
                        if (ctx.staged_rows) |rows| {
                            const outcome = mergeStagedRowsLogged(st, conn, rows, summary, auto_order_id, failures);
                            summary.merge_ok += outcome.merged;
                            summary.merge_failed += outcome.failed;
                        }
                    }
                }
                for (list) |*ctx| {
                    if (ctx.staged_rows) |rows| health.freeStagedRows(std.heap.page_allocator, rows);
                    ctx.staged_rows = null;
                }
            }
        }
    }
    summary.disabled_not_found = st.catalog.disableConsistentNotFound(conn, ACTIVE_PROBE_NOT_FOUND_DISABLE_THRESHOLD) catch 0;
    return summary;
}

/// SONDO-PARALELO: contexto de un hilo de sondeo (un proveedor, en serie).
const ProbeWorkerCtx = struct {
    pairs: []const ProbePair,
    catalog_path: []const u8,
    runtime_path: []const u8,
    probe_fn: ?AutoVerifyProbeFn = null,
    /// el hilo escribe la salud en su propia BD de escenario y
    /// devuelve las filas al hilo principal, que decide si las vuelca.
    stage_health: bool = false,
    /// r2: solo tests — el escenario no se puede abrir. El hilo
    /// falla cerrado (skipped, sin sondear) en vez de usar la BD real.
    stage_unavailable: bool = false,
    /// r2: el hilo no pudo crear su escenario y no sondeó nada.
    staging_failed: bool = false,
    staged_rows: ?[]health.StagedHealthRow = null,
    summary: ProbeAllSummary = .{},
};

/// Número de fallos consecutivos de auth/timeout/rate-limit que tumban el
/// sondeo del proveedor entero — insistir solo empeora el rate-limit.
const PROBE_PROVIDER_ABORT_AFTER: u32 = 2;

fn probeWorker(ctx: *ProbeWorkerCtx) void {
    var arena = std.heap.ArenaAllocator.init(std.heap.page_allocator);
    defer arena.deinit();
    const aa2 = arena.child_allocator;
    const staging = ctx.stage_health;
    if (staging and ctx.stage_unavailable) {
        // FALLO CERRADO (r2): sin escenario no se sondea contra la BD real.
        ctx.staging_failed = true;
        ctx.summary.candidates += ctx.pairs.len;
        ctx.summary.skipped += ctx.pairs.len;
        return;
    }
    var conn = db.Connection.open(aa2, if (staging) ":memory:" else ctx.runtime_path) catch {
        // Sin conexión no se puede ni registrar salud: todo el grupo queda
        // contado como skipped, que es lo honesto — nunca se sondeó.
        if (staging) ctx.staging_failed = true;
        ctx.summary.candidates += ctx.pairs.len;
        ctx.summary.skipped += ctx.pairs.len;
        return;
    };
    if (staging) {
        health.initStaging(conn) catch {
            // FALLO CERRADO (r2): antes se reabría la BD real y el hilo escribía
            // en model_health sin escenario. Ahora el grupo queda skipped y el
            // hilo principal registra auto_verify_staging_failed.
            ctx.staging_failed = true;
            ctx.summary.candidates += ctx.pairs.len;
            ctx.summary.skipped += ctx.pairs.len;
            return;
        };
    }
    defer conn.close();
    var consecutive_fatal: u32 = 0;
    for (ctx.pairs, 0..) |p, i| {
        ctx.summary.candidates += 1;
        const status = probeModelWith(ctx.probe_fn, aa2, ctx.catalog_path, conn, p.provider, p.model) orelse {
            ctx.summary.skipped += 1;
            continue;
        };
        ctx.summary.probed += 1;
        if (status == .ok) {
            ctx.summary.ok += 1;
            consecutive_fatal = 0;
            continue;
        }
        ctx.summary.failed += 1;
        switch (status) {
            .auth_failed, .timeout, .rate_limited => {
                consecutive_fatal += 1;
                if (consecutive_fatal >= PROBE_PROVIDER_ABORT_AFTER) {
                    // El resto del proveedor ni se intenta: auth muerto o
                    // rate-limit activo no se arregla pidiendo más.
                    ctx.summary.skipped += ctx.pairs.len - i - 1;
                    ctx.summary.candidates += ctx.pairs.len - i - 1;
                    // `break`, no `return`: con escenario hay que pasar a
                    // recoger las filas de los modelos ya sondeados.
                    break;
                }
            },
            else => consecutive_fatal = 0,
        }
    }
    if (staging) {
        // Las filas se copian a memoria del proceso (page_allocator) porque el
        // hilo termina y su arena muere; el hilo principal las libera tras el
        // volcado. Filas vacías: no hay nada que volcar.
        ctx.staged_rows = health.readStagedRows(std.heap.page_allocator, conn) catch null;
    }
}

fn emitAutoVerifyTriggered(st: *CoreState, order_id: i64, failures: u32, summary: ProbeAllSummary, conn: db.Connection) void {
    emitAutoVerifyEvent(st, "auto_verify_triggered", order_id, failures, summary, conn, null);
}

/// r3: datos extra opcionales de un evento de sondeo. `err` lleva el
/// nombre del error concreto de un volcado fallido y `model_id`/`key_label` la
/// fila afectada; `merge_ok`/`merge_failed` el resultado parcial del volcado.
const AutoVerifyEventExtra = struct {
    reason: ?[]const u8 = null,
    err: ?db.DbError = null,
    model_id: ?[]const u8 = null,
    key_label: ?[]const u8 = null,
    merge_ok: ?usize = null,
    merge_failed: ?usize = null,
};

fn emitAutoVerifyEvent(
    st: *CoreState,
    kind: []const u8,
    order_id: i64,
    failures: u32,
    summary: ProbeAllSummary,
    conn: db.Connection,
    extra: ?AutoVerifyEventExtra,
) void {
    var out: std.Io.Writer.Allocating = .init(st.arena.child_allocator);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginObject() catch return;
    js.objectField("failures") catch return;
    js.write(failures) catch return;
    js.objectField("candidates") catch return;
    js.write(summary.candidates) catch return;
    js.objectField("probed") catch return;
    js.write(summary.probed) catch return;
    js.objectField("ok") catch return;
    js.write(summary.ok) catch return;
    js.objectField("failed") catch return;
    js.write(summary.failed) catch return;
    js.objectField("skipped") catch return;
    js.write(summary.skipped) catch return;
    js.objectField("disabled_not_found") catch return;
    js.write(summary.disabled_not_found) catch return;
    const merge_ok: usize = if (extra) |e| (e.merge_ok orelse summary.merge_ok) else summary.merge_ok;
    const merge_failed: usize = if (extra) |e| (e.merge_failed orelse summary.merge_failed) else summary.merge_failed;
    if (merge_ok > 0 or merge_failed > 0) {
        js.objectField("merge_ok") catch return;
        js.write(merge_ok) catch return;
        js.objectField("merge_failed") catch return;
        js.write(merge_failed) catch return;
    }
    if (extra) |e| {
        if (e.reason) |r| {
            js.objectField("reason") catch return;
            js.write(r) catch return;
        }
        if (e.err) |merge_err| {
            js.objectField("error") catch return;
            js.write(@errorName(merge_err)) catch return;
        }
        if (e.model_id) |m| {
            js.objectField("model_id") catch return;
            js.write(m) catch return;
        }
        if (e.key_label) |k| {
            js.objectField("key_label") catch return;
            js.write(k) catch return;
        }
    }
    js.endObject() catch return;

    const stmt = conn.prepare("INSERT INTO events (ts, source, kind, payload_json, order_id) VALUES (?, 'governance', ?, ?, ?)") catch return;
    defer conn.finalize(stmt);
    db.bindInt(stmt, 1, health.nowMillis(conn)) catch return;
    db.bindText(stmt, 2, kind) catch return;
    db.bindText(stmt, 3, out.written()) catch return;
    db.bindInt(stmt, 4, order_id) catch return;
    _ = db.c.sqlite3_step(stmt);
}

fn noteDispatchFailureAndMaybeAutoVerify(st: *CoreState, order_id: i64, conn: db.Connection) void {
    st.dispatch_failure_count += 1;
    if (st.dispatch_failure_count < AUTO_VERIFY_FAILURE_THRESHOLD) return;
    const failures = st.dispatch_failure_count;
    st.dispatch_failure_count = 0;

    // una ronda de hasta 24 sondeos no puede repetirse con cada
    // racha de 3 fallos. El reloj es el de la BD (health.nowMillis), no el del
    // proceso, para que el enfriamiento sea observable y testeable.
    const now_ms = health.nowMillis(conn);
    if (st.last_auto_verify_ms != 0 and now_ms - st.last_auto_verify_ms < AUTO_VERIFY_MIN_INTERVAL_MS) {
        emitAutoVerifyEvent(st, "auto_verify_cooled_down", order_id, failures, .{}, conn, null);
        return;
    }
    st.last_auto_verify_ms = now_ms;
    const summary = runAutoHealthProbeAll(st, AUTO_VERIFY_MAX_MODELS, conn, order_id, failures);
    emitAutoVerifyTriggered(st, order_id, failures, summary, conn);
}

/// Deriva la ruta de un archivo hermano de `db_path`.
/// - Si `db_path` es ":memory:", devuelve ":memory:" (cada open es independiente).
/// - Si `db_path` tiene directorio padre, el hermano vive en ese mismo directorio.
/// - Si `db_path` es un archivo sin directorio (p. ej. "runtime.db"), el hermano
///   queda como nombre simple (comportamiento anterior, cwd).
fn deriveSiblingPath(allocator: std.mem.Allocator, db_path: []const u8, sibling: []const u8) ![:0]const u8 {
    if (std.mem.eql(u8, db_path, ":memory:")) return ":memory:";
    if (std.mem.endsWith(u8, db_path, "runtime.db")) {
        const prefix = db_path[0 .. db_path.len - "runtime.db".len];
        const tmp = try std.fmt.allocPrint(allocator, "{s}{s}", .{ prefix, sibling });
        defer allocator.free(tmp);
        return try allocator.dupeZ(u8, tmp);
    }
    const dir = std.fs.path.dirname(db_path);
    if (dir) |d| {
        const tmp = try std.fmt.allocPrint(allocator, "{s}" ++ std.fs.path.sep_str ++ "{s}", .{ d, sibling });
        defer allocator.free(tmp);
        return try allocator.dupeZ(u8, tmp);
    } else {
        return try allocator.dupeZ(u8, sibling);
    }
}

pub export fn da_core_init(out_handle: *?*anyopaque, db_path: [*:0]const u8) callconv(.c) c_int {
    const allocator = std.heap.page_allocator;
    var arena = std.heap.ArenaAllocator.init(allocator);
    errdefer arena.deinit();
    const aa = arena.child_allocator;

    const path_input: [:0]const u8 = std.mem.span(db_path);
    const path: [:0]const u8 = blk: {
        if (std.mem.eql(u8, path_input, ":memory:")) break :blk path_input;
        if (std.fs.path.dirname(path_input) != null) break :blk path_input;
        // FIRE-04: nombre simple sin directorio → anclar canónicamente a la raíz
        // del proyecto (junto a build.zig), no al cwd.
        const canonical = paths.canonicalDbPath(aa, path_input) catch {
            arena.deinit();
            return @intFromEnum(err(.internal, "da_core_init: data path resolution or protection failed"));
        };
        break :blk canonical;
    };
    if (!std.mem.eql(u8, path, ":memory:")) {
        if (std.fs.path.dirname(path)) |dir| {
            @import("private_data.zig").ensureDirectory(aa, dir) catch {
                arena.deinit();
                return @intFromEnum(err(.internal, "da_core_init: private data directory protection failed"));
            };
        }
    }
    // 11-nov: antes de abrir, apartar un WAL de base recién creada emparejado
    // con una base grande (incidente del 10-nov; ver wal_guard.zig).
    if (!std.mem.eql(u8, path, ":memory:")) {
        const catalog_guard = deriveSiblingPath(aa, path, "catalog.db") catch null;
        const ledger_guard = deriveSiblingPath(aa, path, "ledger.db") catch null;
        var guard_paths: [3][]const u8 = undefined;
        var guard_count: usize = 0;
        guard_paths[guard_count] = path;
        guard_count += 1;
        if (catalog_guard) |cp| {
            guard_paths[guard_count] = cp;
            guard_count += 1;
        }
        if (ledger_guard) |lp| {
            guard_paths[guard_count] = lp;
            guard_count += 1;
        }
        @import("wal_guard.zig").guardAll(aa, guard_paths[0..guard_count]);
    }
    var conn = db.Connection.open(aa, path) catch {
        arena.deinit();
        return @intFromEnum(err(.internal, "da_core_init: failed to open database"));
    };
    errdefer conn.close();

    // MULTISESSION-P0: copia propia de `path` — `path` puede ser `path_input`
    // (un slice prestado de la memoria del llamador C vía std.mem.span), que no
    // sobrevive más allá de esta llamada. runtime_path debe sobrevivir mientras
    // viva CoreState (el hilo de dispatch lo lee mucho después de que da_core_init
    // retorne), así que se duplica incondicionalmente aquí.
    const runtime_path: [:0]const u8 = aa.dupeZ(u8, path) catch {
        conn.close();
        arena.deinit();
        return @intFromEnum(err(.oom, "da_core_init: out of memory copying runtime path"));
    };

    // El catálogo NO puede compartir el archivo de runtime: ambos esquemas usan
    // PRAGMA user_version y colisionarían (la migración del catálogo subiría la
    // versión y el migrador de runtime saltaría sus tablas orders/plans/tasks →
    // PrepareFailed). El catálogo vive en su propio "catalog.db" (donde residen
    // proveedores/claves/modelos reales); en ":memory:" cada open ya es una BD
    // distinta, así que se mantiene separado de forma natural.
    // CAMBIO (FIX A): catalog_path y ledger_path se derivan del DIRECTORIO de
    // db_path, no del cwd. Así apuntar da_core_init a un runtime.db limpio en
    // un directorio cualquiera usa catalog.db/ledger.db hermanos predecibles.
    const catalog_path: [:0]const u8 = deriveSiblingPath(aa, path, "catalog.db") catch {
        arena.deinit();
        return @intFromEnum(err(.oom, "da_core_init: out of memory deriving catalog path"));
    };
    const catalog = model_catalog.ModelCatalog.init(aa, catalog_path) catch |e| {
        arena.deinit();
        if (e == error.DbSchemaAhead) {
            return @intFromEnum(err(.internal, "da_core_init: catalog.db tiene un esquema mas nuevo (user_version > migraciones); usa el catalog.db correcto o regeneralo (nunca editar a mano)"));
        }
        return @intFromEnum(err(.internal, "da_core_init: failed to init model catalog"));
    };
    errdefer catalog.deinit();

    // Run runtime schema (orders, plans, tasks, contracts tables)
    var migrator2 = db.Migrator.init(aa);
    migrator2.migrate(conn, &db.runtime_schema) catch |e| {
        arena.deinit();
        if (e == error.DbSchemaAhead) {
            return @intFromEnum(err(.internal, "da_core_init: la base de datos tiene un esquema mas nuevo (user_version > migraciones). Fue creada por una version posterior o mezclada con otro esquema. Solucion: usa la BD correcta (p. ej. ide/build/runtime.db) o eliminala para regenerarla."));
        }
        return @intFromEnum(err(.internal, "da_core_init: failed to run runtime migration"));
    };

    // RESUME-INTERRUPTED: una orden en 'pending'/'approved'/'running' al abrir
    // la base implica un hilo que murió con el proceso anterior — nunca puede
    // ser legítima (los hilos no sobreviven al proceso). Queda 'interrupted':
    // visible y reanudable por el usuario, pero el motor NO la relanza solo
    // porque cada re-lanzamiento gasta cuota de proveedor. Los estados de
    // pausa honesta ('clarifying', 'planned') NO se tocan: esperan decisión
    // del usuario, no un hilo vivo.
    // 10-nov (propietario: «hacer lo mismo que las otras IDE»): 'awaiting_approval'
    // (un comando esperando permiso) SÍ pasa a 'interrupted'. Como en Claude
    // Code, Cursor o Codex, la aprobación vive con su turno: si el proceso se
    // cierra, la pregunta se descarta en vez de quedar semanas en el Monitor
    // (había tres de órdenes viejas, una con un comando de 2 219 caracteres).
    // La orden sigue visible y reanudable; si vuelve a necesitar el comando,
    // lo pregunta de nuevo. closeStaleApprovals (abajo) cierra sus tarjetas.
    // Los turnos vivos de esas órdenes se marcan igual (su CHECK ya admite
    // 'interrupted' desde el esquema).
    conn.exec(
        "UPDATE orders SET status = 'interrupted' WHERE status IN ('pending','approved','running','awaiting_approval')",
    ) catch {};
    conn.exec(
        "UPDATE turns SET status = 'interrupted' WHERE status = 'running'",
    ) catch {};

    // (H-PB-6): ninguna aprobación debe quedar colgada de una orden
    // que ya terminó o que ya no existe. La reconciliación corre ANTES de
    // loadApprovalsFromDb (que solo carga resolved=0) para que el Monitor y el
    // CLI dejen de ofrecer tarjetas de órdenes muertas; no se borra ninguna fila.
    closeStaleApprovals(null, conn, true, health.nowMillis(conn), "orden terminada o inexistente");

    // Ledger append-only (auditoría/escalaciones) en archivo propio.
    const ledger_path: [:0]const u8 = deriveSiblingPath(aa, path, "ledger.db") catch {
        arena.deinit();
        return @intFromEnum(err(.oom, "da_core_init: out of memory deriving ledger path"));
    };
    var ledger = db.Connection.open(aa, ledger_path) catch {
        arena.deinit();
        return @intFromEnum(err(.internal, "da_core_init: failed to open ledger database"));
    };
    errdefer ledger.close();
    var migrator3 = db.Migrator.init(aa);
    migrator3.migrate(ledger, &db.ledger_schema) catch |e| {
        ledger.close();
        arena.deinit();
        if (e == error.DbSchemaAhead) {
            return @intFromEnum(err(.internal, "da_core_init: ledger schema ahead"));
        }
        return @intFromEnum(err(.internal, "da_core_init: failed to run ledger migration"));
    };

    // ENGRAM-WIRE-07: instanciar backend de memoria (Engram si ENGRAM_BIN disponible,
    // fallback local persistente sobre runtime.db en caso contrario).
    const memory_bundle: engram_memory.MemoryBundle = blk: {
        var env_buf: [1024:0]u8 = undefined;
        const env_len = GetEnvironmentVariableA("ENGRAM_BIN", &env_buf, @intCast(env_buf.len));
        if (env_len > 0 and env_len < env_buf.len) {
            const engram_path_buf = env_buf[0..env_len];
            // el transporte MCP posee su runtime io — uno local moría
            // al salir del bloque y toda llamada a memoria quedaba colgada.
            if (engram_memory.EngramMemory.connect(aa, engram_path_buf, "devagents")) |em| {
                break :blk engram_memory.MemoryBundle{ .engram = em };
            } else |_| {}
        }
        break :blk engram_memory.MemoryBundle{ .local = local_memory.LocalMemory.init(aa, conn) };
    };

    const state = aa.create(CoreState) catch {
        arena.deinit();
        return @intFromEnum(err(.oom, "da_core_init: out of memory"));
    };
    state.* = .{
        .arena = arena,
        .db_conn = conn,
        .runtime_path = runtime_path,
        .catalog = catalog,
        .catalog_path = catalog_path,
        .ledger = ledger,
        .ledger_path = ledger_path,
        .orders = .empty,
        .orders_mutex = sync.Mutex.init(),
        .worker_outputs = .empty,
        .last_order_id = 0,
        .approvals = .empty,
        .last_approval_id = 0,
        .output_seq = 0,
        .history = planner.ConversationHistory.empty,
        .dispatch_registry = dispatch_registry.DispatchRegistry.init(aa),
        .dispatch_failure_count = 0,
        .output_mutex = sync.Mutex.init(),
        .plan_mutex = sync.Mutex.init(),
        .plan_thread = null,
        .plan_done = true,
        .plan_ok = false,
        .plan_order_id = -1,
        .plan_cancel_token = null,
        .plan_cancel_requested = false,
        .plan_forced_provider = null,
        .plan_forced_model = null,
        .exec_forced_provider = null,
        .exec_forced_model = null,
        .audit_forced_provider = null,
        .audit_forced_model = null,
        .plan_deterministic = false,
        .od_mcp_state = od_mcp.OdMcpState.init(aa),
        .mcp_token = null,
        .inventory = null,
        .inventory_mutex = sync.Mutex.init(),
        .discovery_kw = null,
        .discovery_llm = null,
        .registry = null,
        .sessions = null,
        .memory = memory_bundle,
        .perm_mode = .normal,
        .perm_allow = .empty,
        .perm_deny = .empty,
        .perm_session_allow = .empty,
        .perm_mutex = sync.Mutex.init(),
        .mcp_surface = false,
        .ledger_mutex = sync.Mutex.init(),
        .audit_queue = .empty,
        .audit_queue_mutex = sync.Mutex.init(),
        .escalated_usage_ids = .empty,
        .escalated_usage_mutex = sync.Mutex.init(),
        .memory_mutex = sync.Mutex.init(),
        .ship_poll_thread = null,
        .ship_poll_stop = std.atomic.Value(bool).init(false),
        .gh_capture_fn = null,
    };
    // SESSIONS-PERSIST-06: crear almacén de sesiones (backend SQLite por defecto).
    state.sessions = session_store.createSqliteStore(aa, conn) catch null;
    // PIXEL-DEVTEAM-05: cargar el registro unificado (5 nativos + dev-team de Pixel
    // Enterprise). loadUnifiedDefault degrada a SOLO-NATIVOS si el archivo falta o es
    // inválido (nunca null/all-or-nothing); solo queda null ante OOM.
    state.registry = pixel_registry.loadUnifiedDefault(aa) catch null;
    // Cargar aprobaciones pendientes persistidas para que CLI one-shot y GUI vean
    // el mismo estado tras reiniciar el proceso.
    loadApprovalsFromDb(state, aa);
    // SESSIONS-PERSIST-06: rehidratar órdenes persistidas.
    loadOrdersFromDb(state, aa);
    // E5.08: límites de agentes externos persistidos en settings del catálogo
    // (best-effort — un valor corrupto degrada a los defaults, nunca rompe init).
    if (state.catalog.db.prepare("SELECT value FROM settings WHERE key='external_agent_limits'")) |s| {
        defer state.catalog.db.finalize(s);
        if (db.c.sqlite3_step(s) == db.c.SQLITE_ROW) {
            const ptr = db.c.sqlite3_column_text(s, 0);
            if (ptr != null) {
                const text = ptr[0..std.mem.len(ptr)];
                state.external_limits = external_agents.Limits.fromJson(state.external_limits, aa, text) catch state.external_limits;
            }
        }
    } else |_| {}
    // 10-nov: permisos elegidos en la cabina (con autorización del host).
    loadPersistedPermissionConfig(state, aa);
    // Tanda 5: si la versión preparada ya está instalada (o es vieja), se
    // limpian updates\ y las claves de preparado. Un fallo no impide arrancar,
    // pero se dice: lo preparado seguirá a la vista en la cabina.
    updater.cleanupApplied(aa, state.catalog.db, updateDataDir(state)) catch |e|
        std.debug.print("updater: no se pudo limpiar la actualización ya aplicada: {s}\n", .{@errorName(e)});
    // MCP-AUTH: asegurar el token del servidor MCP — el archivo `mcp_token` junto
    // a runtime.db es la credencial que el usuario copia a clientes externos.
    state.mcp_token = ensureMcpToken(aa, runtime_path);
    // B3/B4: poller de GitHub en hilo de fondo — non-blocking para la
    // conversacion (intervalo adaptativo del propio poller). En ":memory:" no
    // se lanza: su Connection nueva veria una BD vacia independiente.
    if (!std.mem.eql(u8, runtime_path, ":memory:")) {
        state.ship_poll_stop.store(false, .release);
        state.ship_poll_thread = std.Thread.spawn(.{}, shipPollThreadFn, .{state}) catch null;
    }
    // Detection runs in background to preserve native cold startup.
    // QA-B H11: el servidor MCP no la lanza (`startup_external_detection`).
    if (!builtin.is_test and startup_external_detection and !std.mem.eql(u8, runtime_path, ":memory:")) {
        state.external_detection_thread = std.Thread.spawn(.{}, externalDetectionThread, .{state}) catch |e| blk: {
            std.debug.print("external CLI discovery thread failed: {s}; retry agents_external_refresh\n", .{@errorName(e)});
            break :blk null;
        };
    }
    out_handle.* = state;
    if (!std.mem.eql(u8, runtime_path, ":memory:")) {
        const s = conn.prepare("SELECT 1 FROM webhooks WHERE direction='out' AND active=1 LIMIT 1") catch {
            state.deinit();
            out_handle.* = null;
            return @intFromEnum(err(.internal, "da_core_init: webhook registry unavailable"));
        };
        const configured = db.c.sqlite3_step(s) == db.c.SQLITE_ROW;
        conn.finalize(s);
        if (configured) {
            state.webhook_dispatcher = webhooks.Dispatcher.start(aa, runtime_path) catch {
                state.deinit();
                out_handle.* = null;
                return @intFromEnum(err(.internal, "da_core_init: webhook dispatcher unavailable"));
            };
        }
    }
    // T7 (e): reglas del proyecto abierto (o las de DevAgents).

    return @intFromEnum(ok());
}

/// B3: lazo del GitHubPoller. Cada iteracion sondea las PRs no terminales de
/// `pull_requests` contra `gh pr view` real; el intervalo lo fija el poller
/// (5s con PRs activas, 30s en reposo) y la espera es interrumpible para que
/// deinit no se quede colgado hasta 30s detras de un sueño.
fn shipPollThreadFn(st: *CoreState) void {
    var conn = db.Connection.open(std.heap.page_allocator, st.runtime_path) catch return;
    defer conn.close();
    var poller = github_poller.GitHubPoller.init(std.heap.page_allocator, conn, null);
    defer poller.deinit();
    // T4-GITEA: las mismas costuras inyectables que usa el ship (null en
    // produccion = git/credential fill y HTTP reales).
    poller.gh.capture_fn = st.gh_capture_fn;
    poller.gh.capture_full_fn = st.gh_capture_full_fn;
    poller.gitea.http_fn = st.gitea_rest_fn;
    poller.gh.forge_auth_fn = forgeStoreAuth;
    poller.gh.forge_auth_ctx = st;
    poller.gh.rest_enabled = st.forge_rest_enabled;
    while (!st.ship_poll_stop.load(.acquire)) {
        {
            const hosts = configuredForgeHosts(st, poller.allocator) catch |e| {
                std.log.err("forges: configuracion del sondeo: {s}", .{@errorName(e)});
                return;
            };
            defer freeForgeHosts(poller.allocator, hosts);
            poller.gh.forge_hosts = hosts;
            _ = poller.pollOnce() catch |e| {
                std.log.err("forges: sondeo fallido: {s}", .{@errorName(e)});
            };
            poller.gh.forge_hosts = &.{};
        }
        const wait_ms = poller.status.interval_ms;
        var slept: u64 = 0;
        while (slept < wait_ms and !st.ship_poll_stop.load(.acquire)) : (slept += 250) {
            Sleep(250);
        }
    }
}

/// MCP-AUTH: lee o crea el token del servidor MCP. Vive en `<dir(runtime)>/mcp_token`
/// — misma carpeta y mismo nivel de confianza que la propia runtime.db. En
/// ":memory:" o ante fallo de archivo, devuelve un token efímero en RAM (las
/// tools privilegiadas siguen exigiéndolo; el operador lo ve por stderr).
fn ensureMcpToken(aa: std.mem.Allocator, runtime_path: [:0]const u8) ?[]const u8 {
    if (!std.mem.eql(u8, runtime_path, ":memory:")) {
        if (std.fs.path.dirname(runtime_path)) |dir| {
            if (std.fmt.allocPrint(aa, "{s}" ++ std.fs.path.sep_str ++ "mcp_token", .{dir})) |tok_path| {
                if (readFileAllocC(aa, tok_path)) |raw| {
                    const t = std.mem.trim(u8, raw, " \t\r\n");
                    if (t.len >= 16) {
                        @import("private_data.zig").protectFile(aa, tok_path) catch {
                            aa.free(raw);
                            return null;
                        };
                        return t;
                    }
                    aa.free(raw);
                }
                const tok = genTokenHexC(aa) orelse return null;
                if (!writeFileC(tok_path, tok)) {
                    aa.free(tok);
                    return null;
                }
                return tok;
            } else |_| {}
        }
    }
    return genTokenHexC(aa);
}

fn genTokenHexC(aa: std.mem.Allocator) ?[]const u8 {
    var bytes: [16]u8 = undefined;
    // El fork Zig 0.16 no expone std.crypto.random — BCryptGenRandom con
    // BCRYPT_USE_SYSTEM_PREFERRED_RNG (0x2) es el CSPRNG del sistema.
    if (BCryptGenRandom(null, &bytes, bytes.len, 0x00000002) != 0) return null;
    const hex_chars = "0123456789abcdef";
    const out = aa.alloc(u8, 32) catch return null;
    for (bytes, 0..) |b, i| {
        out[i * 2] = hex_chars[b >> 4];
        out[i * 2 + 1] = hex_chars[b & 0x0f];
    }
    return out;
}

/// Lee `path` vía Win32 (el fork Zig no expone std.fs.readFileAlloc).
fn readFileAllocC(aa: std.mem.Allocator, path: []const u8) ?[]u8 {
    const buf = readFileBounded(aa, path, 4096) catch return null;
    if (buf.len == 0) {
        aa.free(buf);
        return null;
    }
    return buf;
}

const ReadBoundedError = error{ NotFound, TooLarge, ReadFailed, OutOfMemory };

/// Lee entero un archivo de hasta `max` bytes con Win32. Sustituye al
/// `@cImport` de stdio.h que usaba `da_checklist_json`: con las cabeceras de
/// MinGW y fortify, el translate-c de Zig 0.16 no compila `fread` en
/// ReleaseSafe (cimport.zig: «expected type 'c_int', found 'bool'»), y eso
/// impedía compilar la CLI, el MCP y la DLL de distribución en ReleaseSafe
/// (medido el 13-nov, E:\devagents-cache\t4-rs-build.log).
fn readFileBounded(aa: std.mem.Allocator, path: []const u8, max: u32) ReadBoundedError![]u8 {
    const GENERIC_READ: u32 = 0x80000000;
    const FILE_SHARE_READ: u32 = 0x00000001;
    const OPEN_EXISTING: u32 = 3;
    const INVALID: windows.HANDLE = @ptrFromInt(~@as(usize, 0));
    const path_z = try aa.dupeZ(u8, path);
    defer aa.free(path_z);
    const h = CreateFileA(path_z.ptr, GENERIC_READ, FILE_SHARE_READ, null, OPEN_EXISTING, 0x80, null);
    if (h == INVALID) return error.NotFound;
    defer _ = CloseHandle(h);
    var high: u32 = 0;
    const size = GetFileSize(h, &high);
    if (size == 0xFFFFFFFF) return error.ReadFailed;
    if (high != 0 or size > max) return error.TooLarge;
    const buf = try aa.alloc(u8, size);
    errdefer aa.free(buf);
    var n: u32 = 0;
    if (size > 0 and (ReadFile(h, buf.ptr, size, &n, null) == 0 or n != size)) return error.ReadFailed;
    return buf;
}

fn writeFileC(path: []const u8, data: []const u8) bool {
    @import("private_data.zig").writeNew(std.heap.page_allocator, path, data) catch return false;
    return true;
}

/// Construye o refresca el inventario de herramientas escaneando los mounts activos.
/// Devuelve un DiscoveryBackend y un puntero al inventory (vive en CoreState).
/// P12-T2: Prefiere LlmDiscovery si hay LLM configurado; si no, usa KeywordDiscovery.
fn ensureInventory(st: *CoreState) struct { dbk: tool_discovery.DiscoveryBackend, inv: ?*const tool_discovery.Inventory } {
    st.inventory_mutex.lock();
    defer st.inventory_mutex.unlock();

    if (st.inventory == null) {
        const aa = st.arena.child_allocator;
        var threaded = std.Io.Threaded.init(aa, .{});
        defer threaded.deinit();
        const io = threaded.io();

        var reg = mounts.MountRegistry.init(aa, st.db_conn);
        if (reg.getActivePaths(aa)) |mount_paths| {
            defer {
                for (mount_paths) |p| aa.free(p);
                aa.free(mount_paths);
            }
            st.inventory = tool_discovery.scanRoots(aa, io, mount_paths) catch null;
        } else |_| {
            st.inventory = null;
        }
    }

    const inv_ptr: ?*const tool_discovery.Inventory = if (st.inventory) |*inv| inv else null;

    // P12-T2: Inicializar LlmDiscovery (sin LLM por defecto → fallback a keyword).
    // El LLM se configura desde superagent.zig cuando hay LiveLlm disponible.
    if (st.discovery_llm == null) {
        st.discovery_llm = tool_discovery.LlmDiscovery.init(st.arena.child_allocator);
    }
    // Si el LlmDiscovery tiene LLM configurado y no hay dispatch vivo, usarlo.
    // Con dispatch timeout el LiveLlm puede seguir corriendo; reutilizarlo durante
    // una planificación nueva bloqueaba la UI y dejaba órdenes pending.
    // C3-REGISTRY: "ningún dispatch vivo" ahora es sobre TODO el registro (puede
    // haber varias órdenes en vuelo a la vez) — hasAnyInFlight() cubre eso.
    // NOTA (riesgo pre-existente, no corregido en esta migración): st.discovery_llm
    // es un único LlmDiscovery compartido por TODO CoreState; con 2+ órdenes
    // realmente concurrentes, sus punteros llm_ctx/llm_fn (apuntados a la
    // LiveLlm local de CADA dispatch vía FIX-P11-CRASH) podrían pisarse entre sí.
    // Antes del registro esto era inalcanzable (single-flight global); ahora es
    // posible en teoría. Fuera de alcance de este incremento (ver informe final).
    const can_use_discovery_llm = st.discovery_llm.?.llm_fn != null and
        st.discovery_llm.?.llm_ctx != null and
        !st.dispatch_registry.hasAnyInFlight();
    if (can_use_discovery_llm) {
        return .{ .dbk = st.discovery_llm.?.backend(), .inv = inv_ptr };
    }

    // Fallback: keyword discovery.
    if (st.discovery_kw == null) {
        st.discovery_kw = tool_discovery.KeywordDiscovery.init(st.arena.child_allocator);
    }
    const dbk = st.discovery_kw.?.backend();
    return .{ .dbk = dbk, .inv = inv_ptr };
}

pub export fn da_core_shutdown(handle: ?*anyopaque) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_core_shutdown: null handle"));
    const state: *CoreState = @ptrCast(@alignCast(handle));
    state.deinit();
    return @intFromEnum(ok());
}

pub export fn da_order_submit(handle: ?*anyopaque, order_text: [*:0]const u8, project_id: [*:0]const u8, conversation_id: ?[*:0]const u8, out_order: *?*anyopaque) callconv(.c) c_int {
    return submitSync(handle, order_text, project_id, conversation_id, out_order, false);
}

fn submitSync(handle: ?*anyopaque, order_text: [*:0]const u8, project_id: [*:0]const u8, conversation_id: ?[*:0]const u8, out_order: *?*anyopaque, wait_for_plan_approval: bool) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_order_submit: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    if (rejectInvalidConfiguration(st)) |rc| return rc;

    const text = std.mem.span(order_text);
    const proj = std.mem.span(project_id);
    const conv_id: ?[]const u8 = if (conversation_id) |c| std.mem.span(c) else null;

    if (text.len == 0) return @intFromEnum(err(.invalid_arg, "da_order_submit: empty order text"));

    // FASE-AGENTIC-1: si la orden trae conversation_id, el historial real viene
    // de la BD (cruza TODAS las órdenes del hilo); si no, se preserva el
    // comportamiento legacy del ring buffer en RAM (st.history).
    var conv_hist: planner.ConversationHistory = if (conv_id) |cid| loadConversationHistory(st, aa, cid) else planner.ConversationHistory.empty;
    defer conv_hist.deinit(aa);
    var forced_selection = captureModelSelection(st, aa) catch return @intFromEnum(err(.oom, "da_order_submit: OOM cloning model selection"));
    defer forced_selection.deinit(aa);

    // Planificador VIVO: usa un LLM real (con clave en catalog.db); sin clave o ante
    // fallo, LlmPlanner degrada internamente a MockPlanner (determinista).
    var llm_planner = live_planner.LlmPlanner.init(aa, st.catalog_path);
    llm_planner.history = if (conv_id != null) conv_hist.turns.items else st.history.turns.items;
    llm_planner.forced_provider = forced_selection.provider;
    llm_planner.forced_model = forced_selection.model;
    llm_planner.deterministic = st.plan_deterministic;
    llm_planner.event_conn = st.db_conn;
    llm_planner.cancel_slot = .{ .mutex = &st.plan_mutex, .slot = &st.plan_cancel_token };
    // event_order_id = 0: tryLlmPlan will query SELECT MAX(id) FROM orders,
    // which returns the order just inserted by processOrder.insertOrder.
    llm_planner.event_order_id = 0;
    var sub_planning = direct_mode.SubscriptionPlanning.init(aa);
    defer sub_planning.deinit();
    wireSubscriptionPlanning(st, &sub_planning, &llm_planner, 0);
    // E5.13 (D-C3): mapa del repositorio en el prompt del planner (~2k
    // tokens), sembrado por el texto de la orden. La caché por
    // (raíz, HEAD, config) abarata el build de los workers al despachar;
    // sin repo git o fuera de presupuesto el prompt sale igual que antes.
    {
        var er_buf: [4096]u8 = undefined;
        const map_root = workspace.effectiveRoot(&er_buf);
        var map_threaded = std.Io.Threaded.init(aa, .{});
        defer map_threaded.deinit();
        if (repo_map.renderForPrompt(aa, map_threaded.io(), map_root, text, 2000, .{}, st.db_conn)) |rm| {
            llm_planner.repo_map_text = rm.text;
            repo_map.emitBuiltEvent(st.db_conn, 0, rm);
        }
    }
    const backend = llm_planner.backend();
    const memory = st.memory.backend();

    const disc = ensureInventory(st);
    var router_storage: model_router.Router = undefined;
    const router_ptr = makeRouter(st, aa, &router_storage, st.db_conn);
    // FUGA (2026-08-06): el cache de healthFactor duplica cada clave
    // "proveedor|modelo" y la guarda; `deinitHealthCache` las libera, pero NO
    // lo llamaba ninguna ruta de produccion — solo los tests, que por eso
    // salian limpios. Cada orden dejaba atras una clave por modelo evaluado.
    defer if (router_ptr) |r| r.deinitHealthCache();
    var sup = superagent.Superagent.init(aa, st.db_conn, router_ptr, memory, health.nowSeconds(st.db_conn));
    sup.rules_catalog = st.catalog.db;
    sup.browser_registry = &st.browser_registry;
    if (st.registry) |*r| sup.registry = r;
    sup.od_mcp_state = &st.od_mcp_state;
    // P12-T3: inyectar selector agéntico + inventario + texto de orden.
    if (st.discovery_llm) |*dl| sup.discovery_llm = dl;
    sup.inventory_ptr = disc.inv;
    sup.order_text = text;
    // MODELO-MANUAL-ORQUESTACION: propagar el modelo fijado por plan_set_model — antes
    // solo alimentaba la llamada de planificación; assignModel (dispatch por-tarea) lo
    // ignoraba y siempre enrutaba free-first pese a que el usuario fijó un modelo.
    // ROLES-MODELO: exec/audit ya vienen resueltos en la selección capturada
    // (rol ?? plan). setAuditForcedModel va DESPUÉS de setForcedModel porque
    // este último también siembra el pin de auditor (semántica "toda la orden"
    // para llamadas directas); aquí el auditor efectivo manda.
    sup.setForcedModel(forced_selection.exec_provider, forced_selection.exec_model);
    sup.setAuditForcedModel(forced_selection.audit_provider, forced_selection.audit_model);
    sup.setSwarmJson(forced_selection.swarm_json);
    sup.deterministic = st.plan_deterministic;
    sup.wait_for_plan_approval = wait_for_plan_approval;
    var outcome = sup.processOrder(proj, text, &.{}, backend, disc.dbk, disc.inv) catch |e| {
        setLastError(@errorName(e));
        const rec = aa.create(OrderRecord) catch return @intFromEnum(err(.oom, "da_order_submit: OOM"));
        rec.* = OrderRecord{
            .id = 0,
            .db_id = null,
            .text = aa.dupe(u8, text) catch text,
            .project_id = aa.dupe(u8, proj) catch proj,
            .status = .failed,
            .plan_json = null,
            .outcome = null,
            .questions = &.{},
            .created_at = health.nowSeconds(st.db_conn), // segundos de época, como la fila (22-09)
        };
        st.orders_mutex.lock();
        st.orders.append(aa, rec) catch {
            st.orders_mutex.unlock();
            aa.destroy(rec);
            return @intFromEnum(err(.oom, "da_order_submit: OOM"));
        };
        st.orders_mutex.unlock();
        out_order.* = orderIdToHandle(rec.id);
        return @intFromEnum(DaResult.internal);
    };

    const order_id = outcome.order_id;
    if (order_id > st.last_order_id) st.last_order_id = order_id;
    setOrderConversationId(st, order_id, conv_id);

    // GOBERNANZA-HIBRIDO-LEDGER (no-tarea): cada llamada de planificación que
    // salió por modelo is_free=0 deja su fila ESCALATION justificada por la
    // cola serializada (FIX-ENGINE-8/9: solo el hilo principal toca ledger.db).
    emitAuxEscalations(st, st.db_conn, aa, order_id);

    // MEM-01: registrar el turno (orden + entendimiento/respuesta) tras planificar.
    st.history.push(aa, text, outcome.plan.understanding, MAX_HISTORY_TURNS, MAX_TURN_TEXT_BYTES) catch {};

    const plan_json: ?[]const u8 = if (outcome.status != .clarifying) planToJson(aa, &outcome.plan) catch null else null;
    const questions: []const u8 = if (outcome.status == .clarifying) questionsToJson(aa, outcome.plan.questions) catch "[]" else "[]";

    const rec = aa.create(OrderRecord) catch return @intFromEnum(err(.oom, "da_order_submit: OOM"));
    rec.* = OrderRecord{
        .id = order_id,
        .db_id = order_id,
        .text = aa.dupe(u8, text) catch text,
        .project_id = aa.dupe(u8, proj) catch proj,
        .status = outcome.status,
        .wait_for_plan_approval = wait_for_plan_approval,
        .plan_json = plan_json,
        .outcome = outcome,
        .questions = aa.dupe(u8, questions) catch "[]",
        .conversation_id = if (conv_id) |c| aa.dupe(u8, c) catch null else null,
        .created_at = health.nowSeconds(st.db_conn), // segundos de época, como la fila (22-09)
    };
    st.orders_mutex.lock();
    st.orders.append(aa, rec) catch {
        st.orders_mutex.unlock();
        aa.destroy(rec);
        return @intFromEnum(err(.oom, "da_order_submit: OOM"));
    };
    st.orders_mutex.unlock();
    if (outcome.status == .clarifying) bumpClarifyRounds(st, rec);

    // SESSIONS-PERSIST-06: persistir turnos de conversación.
    saveMessageToDb(st.sessions, order_id, "user", text, st.db_conn);
    saveMessageToDb(st.sessions, order_id, "agent", outcome.plan.understanding, st.db_conn);

    out_order.* = orderIdToHandle(order_id);
    return @intFromEnum(ok());
}

pub export fn da_order_answer(handle: ?*anyopaque, order: ?*anyopaque, answers_json: [*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_order_answer: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order) orelse return @intFromEnum(err(.invalid_arg, "da_order_answer: null order handle"));
    const aa = st.arena.child_allocator;

    const rec = findOrder(st, order_id) orelse return @intFromEnum(err(.not_found, "da_order_answer: order not found"));
    if (rec.status != .clarifying) return @intFromEnum(err(.invalid_state, "da_order_answer: order is not in clarifying state"));

    const answers = parseClarificationAnswers(aa, std.mem.span(answers_json)) catch
        return @intFromEnum(err(.invalid_arg, "da_order_answer: invalid answers JSON"));

    var conv_hist: planner.ConversationHistory = if (rec.conversation_id) |cid| loadConversationHistory(st, aa, cid) else planner.ConversationHistory.empty;
    defer conv_hist.deinit(aa);
    var forced_selection = captureModelSelection(st, aa) catch return @intFromEnum(err(.oom, "da_order_answer: OOM cloning model selection"));
    defer forced_selection.deinit(aa);

    var llm_planner = live_planner.LlmPlanner.init(aa, st.catalog_path);
    llm_planner.history = if (rec.conversation_id != null) conv_hist.turns.items else st.history.turns.items;
    llm_planner.forced_provider = forced_selection.provider;
    llm_planner.forced_model = forced_selection.model;
    llm_planner.deterministic = st.plan_deterministic;
    llm_planner.event_conn = st.db_conn;
    llm_planner.event_order_id = rec.db_id orelse rec.id;
    llm_planner.cancel_slot = .{ .mutex = &st.plan_mutex, .slot = &st.plan_cancel_token };
    llm_planner.clarify_rounds_used = @intCast(@max(0, rec.clarify_rounds));
    var sub_planning = direct_mode.SubscriptionPlanning.init(aa);
    defer sub_planning.deinit();
    wireSubscriptionPlanning(st, &sub_planning, &llm_planner, rec.db_id orelse rec.id);
    // E5.13 (D-C3): mismo mapa que en el submit — en re-plan la orden ya
    // existe y el evento lleva su id real.
    {
        var er_buf: [4096]u8 = undefined;
        const map_root = workspace.effectiveRoot(&er_buf);
        var map_threaded = std.Io.Threaded.init(aa, .{});
        defer map_threaded.deinit();
        if (repo_map.renderForPrompt(aa, map_threaded.io(), map_root, rec.text, 2000, .{}, st.db_conn)) |rm| {
            llm_planner.repo_map_text = rm.text;
            repo_map.emitBuiltEvent(st.db_conn, rec.db_id orelse rec.id, rm);
        }
    }
    const backend = llm_planner.backend();
    const memory = st.memory.backend();

    const disc = ensureInventory(st);
    var router_storage: model_router.Router = undefined;
    const router_ptr = makeRouter(st, aa, &router_storage, st.db_conn);
    // FUGA (2026-08-06): el cache de healthFactor duplica cada clave
    // "proveedor|modelo" y la guarda; `deinitHealthCache` las libera, pero NO
    // lo llamaba ninguna ruta de produccion — solo los tests, que por eso
    // salian limpios. Cada orden dejaba atras una clave por modelo evaluado.
    defer if (router_ptr) |r| r.deinitHealthCache();
    var sup = superagent.Superagent.init(aa, st.db_conn, router_ptr, memory, health.nowSeconds(st.db_conn));
    sup.rules_catalog = st.catalog.db;
    sup.browser_registry = &st.browser_registry;
    if (st.registry) |*r| sup.registry = r;
    sup.od_mcp_state = &st.od_mcp_state;
    // P12-T3: inyectar selector agéntico + inventario + texto de orden.
    if (st.discovery_llm) |*dl| sup.discovery_llm = dl;
    sup.inventory_ptr = disc.inv;
    sup.order_text = rec.text;
    // MODELO-MANUAL-ORQUESTACION: propagar el modelo fijado por plan_set_model — antes
    // solo alimentaba la llamada de planificación; assignModel (dispatch por-tarea) lo
    // ignoraba y siempre enrutaba free-first pese a que el usuario fijó un modelo.
    // ROLES-MODELO: exec/audit ya vienen resueltos en la selección capturada
    // (rol ?? plan). setAuditForcedModel va DESPUÉS de setForcedModel porque
    // este último también siembra el pin de auditor (semántica "toda la orden"
    // para llamadas directas); aquí el auditor efectivo manda.
    sup.setForcedModel(forced_selection.exec_provider, forced_selection.exec_model);
    sup.setAuditForcedModel(forced_selection.audit_provider, forced_selection.audit_model);
    sup.setSwarmJson(forced_selection.swarm_json);
    sup.deterministic = st.plan_deterministic;
    // replanificar sobre la MISMA fila; antes nacía otra y esta quedaba
    // `clarifying` para siempre.
    sup.wait_for_plan_approval = rec.wait_for_plan_approval;
    sup.reuse_order_id = rec.db_id;
    var outcome = sup.processOrder(rec.project_id, rec.text, answers, backend, disc.dbk, disc.inv) catch |e| {
        setLastError(@errorName(e));
        if (e == error.ClarifyRoundsExhausted) {
            rec.status = .failed;
            persistOrderFailed(st, rec);
        }
        return @intFromEnum(err(.internal, "da_order_answer: planner failed"));
    };
    emitAuxEscalations(st, st.db_conn, aa, outcome.order_id);
    setOrderConversationId(st, outcome.order_id, rec.conversation_id);

    // MEM-01: registrar el turno resultante de resolver la clarificación.
    st.history.push(aa, rec.text, outcome.plan.understanding, MAX_HISTORY_TURNS, MAX_TURN_TEXT_BYTES) catch {};

    if (rec.outcome) |*old| old.deinit();
    if (rec.plan_json) |j| aa.free(j);
    aa.free(rec.questions);

    rec.status = outcome.status;
    rec.plan_json = planToJson(aa, &outcome.plan) catch null;
    rec.outcome = outcome;
    // El outcome vive bajo un order_id NUEVO (processOrder inserta su propia
    // fila). El path async ya hace `r.db_id = outcome.order_id`; sin esto el
    // registro apunta a la fila vieja (clarifying) y plan_set/terminal/status
    // leen o escriben la orden equivocada.
    rec.db_id = outcome.order_id;
    // Siempre asignamos memoria dinámica para `questions` para que `OrderRecord.deinit`
    // pueda liberarla de forma uniforme sin distinguir literales estáticos.
    rec.questions = questionsToJson(aa, outcome.plan.questions) catch "[]";
    if (outcome.status == .clarifying) bumpClarifyRounds(st, rec);

    // SESSIONS-PERSIST-06: persistir turnos de conversación.
    if (rec.db_id) |db_id| {
        saveMessageToDb(st.sessions, db_id, "user", std.mem.span(answers_json), st.db_conn);
        saveMessageToDb(st.sessions, db_id, "agent", outcome.plan.understanding, st.db_conn);
    }

    return @intFromEnum(ok());
}

// ═══════════════════════════════════════════════════════════════════════════════
// Async plan state (F7-ASYNC-PLAN): submit/answer sin bloquear la UI de Qt.
// ═══════════════════════════════════════════════════════════════════════════════

const PlanContext = struct {
    st: *CoreState,
    order_id: i64,
};

/// lee el campo por orden desde la traza versionada existente.
fn persistedPlanApprovalMode(conn: db.Connection, order_id: i64) !bool {
    const stmt = try conn.prepare("SELECT payload_json FROM events WHERE order_id=? AND kind='order_plan_mode_v1' ORDER BY id DESC LIMIT 1");
    defer conn.finalize(stmt);
    try db.bindInt(stmt, 1, order_id);
    const rc = db.c.sqlite3_step(stmt);
    if (rc == db.c.SQLITE_DONE) return false; // Órdenes anteriores al modo.
    if (rc != db.c.SQLITE_ROW) return error.ExecFailed;
    const ptr = db.c.sqlite3_column_text(stmt, 0) orelse return error.InvalidJson;
    const len = db.c.sqlite3_column_bytes(stmt, 0);
    const json = ptr[0..@intCast(len)];
    if (std.mem.eql(u8, json, "{\"wait_for_plan_approval\":true}")) return true;
    if (std.mem.eql(u8, json, "{\"wait_for_plan_approval\":false}")) return false;
    return error.InvalidJson;
}

/// Contrato aditivo: captura el modo ANTES de arrancar la planificación.
/// issue_request opcional conserva el flujo de incidencias y sus adjuntos.
pub export fn da_order_submit_options_async(handle: ?*anyopaque, order_text: [*:0]const u8, project_id: [*:0]const u8, conversation_id: ?[*:0]const u8, attachments_json: ?[*:0]const u8, options_json: [*:0]const u8, out_order: *?*anyopaque) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "submit_options: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    const options_text = std.mem.span(options_json);
    if (options_text.len > 96 * 1024) return @intFromEnum(err(.invalid_arg, "submit_options: options too large"));
    const Options = struct { wait_for_plan_approval: bool = false, issue_request: ?[]const u8 = null };
    var options = std.json.parseFromSlice(Options, aa, options_text, .{}) catch
        return @intFromEnum(err(.invalid_arg, "submit_options: invalid options"));
    defer options.deinit();
    if (options.value.issue_request) |request| {
        const request_z = aa.dupeZ(u8, request) catch return @intFromEnum(err(.oom, "submit_options: OOM"));
        defer aa.free(request_z);
        return submitFromIssue(handle, request_z.ptr, order_text, project_id, conversation_id, attachments_json, out_order, options.value.wait_for_plan_approval);
    }
    return submitAsyncWithIssue(handle, order_text, project_id, conversation_id, attachments_json, out_order, null, options.value.wait_for_plan_approval);
}

/// Operación síncrona de solo planificar, con el contrato de ver1. El plan se
/// conserva en la misma lista de órdenes; su aprobación usa la ruta existente.
pub export fn da_order_plan_json(handle: ?*anyopaque, order_text: [*:0]const u8, out_json: *[*:0]u8) callconv(.c) c_int {
    var order: ?*anyopaque = null;
    const rc = submitSync(handle, order_text, "default", null, &order, true);
    if (rc != 0) return rc;
    return da_plan_get_json(handle, order, out_json);
}

/// Revisa la MISMA orden sin aprobar ni despachar. Las revisiones antiguas
/// permanecen en plans/tasks; el nuevo plan nace con approved=0.
pub export fn da_order_replan_async(handle: ?*anyopaque, order: ?*anyopaque, changes: [*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "replan: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const id = orderHandleToId(order) orelse return @intFromEnum(err(.invalid_arg, "replan: null order"));
    const aa = st.arena.child_allocator;
    const request = std.mem.trim(u8, std.mem.span(changes), " \t\r\n");
    if (request.len == 0 or request.len > 16384) return @intFromEnum(err(.invalid_arg, "replan: changes must contain 1..16384 bytes"));
    const rec = findOrder(st, id) orelse return @intFromEnum(err(.not_found, "replan: order not found"));
    st.plan_mutex.lock();
    defer st.plan_mutex.unlock();
    if (!st.plan_done or (rec.status != .planned and rec.status != .clarifying)) return @intFromEnum(err(.invalid_state, "replan: order must await plan approval or clarification"));
    const previous_plan = rec.plan_json orelse if (rec.outcome) |outcome| outcome.plan.understanding else "";
    if (rec.text.len + request.len + previous_plan.len > 128 * 1024) return @intFromEnum(err(.invalid_arg, "replan: accumulated context too large"));
    const answers_copy = blk: {
        const query = st.db_conn.prepare("SELECT clarifications_json FROM plans WHERE order_id=? ORDER BY id DESC LIMIT 1") catch
            return @intFromEnum(err(.internal, "replan: could not load previous answers"));
        defer st.db_conn.finalize(query);
        db.bindInt(query, 1, rec.db_id orelse rec.id) catch return @intFromEnum(err(.internal, "replan: answers bind failed"));
        const rc = db.c.sqlite3_step(query);
        if (rc != db.c.SQLITE_ROW and rc != db.c.SQLITE_DONE) return @intFromEnum(err(.internal, "replan: answers read failed"));
        const ptr = if (rc == db.c.SQLITE_ROW) db.c.sqlite3_column_text(query, 0) else null;
        const value: []const u8 = if (ptr) |text_ptr| text_ptr[0..@intCast(db.c.sqlite3_column_bytes(query, 0))] else "[]";
        break :blk aa.dupe(u8, value) catch return @intFromEnum(err(.oom, "replan: OOM answers"));
    };
    var started = false;
    defer if (!started) aa.free(answers_copy);
    // El JSON anterior es contexto del planificador, no texto de la orden ni
    // descripción de tarea: incluirlo allí contaminaba los clasificadores.
    const previous_copy = aa.dupe(u8, previous_plan) catch return @intFromEnum(err(.oom, "replan: OOM previous plan"));
    defer if (!started) aa.free(previous_copy);
    const changes_copy = aa.dupe(u8, request) catch return @intFromEnum(err(.oom, "replan: OOM changes"));
    defer if (!started) aa.free(changes_copy);
    const text = std.fmt.allocPrint(aa, "{s}\n\n[Cambios del usuario al plan; vuelve a planificar sin ejecutar]\n{s}", .{ rec.text, request }) catch return @intFromEnum(err(.oom, "replan: OOM"));
    const ctx = aa.create(AnswerContext) catch {
        aa.free(text);
        return @intFromEnum(err(.oom, "replan: OOM context"));
    };
    defer if (!started) aa.destroy(ctx);
    const stmt = st.db_conn.prepare("UPDATE orders SET user_prompt=?, status='pending' WHERE id=? AND status IN ('planned','clarifying')") catch {
        aa.free(text);
        return @intFromEnum(err(.internal, "replan: persistence failed"));
    };
    defer st.db_conn.finalize(stmt);
    db.bindText(stmt, 1, text) catch {
        aa.free(text);
        return @intFromEnum(err(.internal, "replan: bind failed"));
    };
    db.bindInt(stmt, 2, rec.db_id orelse rec.id) catch {
        aa.free(text);
        return @intFromEnum(err(.internal, "replan: bind failed"));
    };
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE or db.c.sqlite3_changes(st.db_conn.db) != 1) {
        aa.free(text);
        return @intFromEnum(err(.invalid_state, "replan: stale order"));
    }
    aa.free(rec.text);
    rec.text = text;
    rec.status = .pending;
    rec.wait_for_plan_approval = true;
    st.plan_done = false;
    st.plan_ok = false;
    st.plan_order_id = id;
    st.plan_cancel_requested = false;
    st.plan_cancel_token = null;
    ctx.* = .{ .st = st, .order_id = id, .answers_json = answers_copy, .previous_plan_json = previous_copy, .replan_changes = changes_copy };
    // Un hilo terminado anterior se recoge antes de reemplazar su handle.
    if (st.plan_thread) |thread| thread.join();
    st.plan_thread = std.Thread.spawn(.{}, planAnswerThreadFn, .{ctx}) catch {
        st.plan_done = true;
        rec.status = .failed;
        persistOrderFailed(st, rec);
        return @intFromEnum(err(.internal, "replan: failed to spawn planner"));
    };
    started = true;
    return @intFromEnum(ok());
}

/// QA-B H7 (decisión del propietario, 14-nov): sin clave de API ni modelo local la
/// cabina planifica con la CLI con suscripción, como `devagents order` y como
/// Automático en Directo: mismo catálogo de agentes (carga perezosa), misma
/// cuenta elegida y rotación, mismos seams de prueba. Una orden que llega por
/// MCP no la lanza (sigue la vía de siempre).
fn wireSubscriptionPlanning(st: *CoreState, sub: *direct_mode.SubscriptionPlanning, lp: *live_planner.LlmPlanner, order_id: i64) void {
    sub.external.catalog_conn = st.catalog.db;
    sub.external.event_conn = st.db_conn;
    sub.external.run_fn = st.external_run_fn;
    sub.external.run_ctx = st.external_run_ctx;
    sub.external.load_fn = directCatalogLoad;
    sub.external.load_ctx = @ptrCast(st);
    sub.event_order_id = order_id;
    if (st.mcp_surface) sub.origin = .mcp;
    lp.subscription = sub.subscriptionPlanner();
}

fn planThreadFn(ctx: *PlanContext) void {
    const st = ctx.st;
    const order_id = ctx.order_id;
    const aa = st.arena.child_allocator;
    defer aa.destroy(ctx);

    const rec = findOrder(st, order_id);
    if (rec == null) {
        st.plan_mutex.lock();
        st.plan_done = true;
        st.plan_ok = false;
        st.plan_mutex.unlock();
        return;
    }

    // PLAN-CANCEL: si la cancelación llegó entre el submit y el arranque de
    // este hilo (antes de que existiera token), no se planifica nada.
    st.plan_mutex.lock();
    const cancelled_at_start = st.plan_cancel_requested;
    st.plan_mutex.unlock();
    if (cancelled_at_start) {
        markPlanCancelled(st, order_id);
        st.plan_mutex.lock();
        st.plan_done = true;
        st.plan_ok = false;
        st.plan_mutex.unlock();
        return;
    }

    var conv_hist: planner.ConversationHistory = if (rec.?.conversation_id) |cid| loadConversationHistory(st, aa, cid) else planner.ConversationHistory.empty;
    defer conv_hist.deinit(aa);
    var forced_selection = captureModelSelection(st, aa) catch {
        st.plan_mutex.lock();
        st.plan_done = true;
        st.plan_ok = false;
        st.plan_mutex.unlock();
        return;
    };
    defer forced_selection.deinit(aa);

    var llm_planner = live_planner.LlmPlanner.init(aa, st.catalog_path);
    llm_planner.history = if (rec.?.conversation_id != null) conv_hist.turns.items else st.history.turns.items;
    llm_planner.forced_provider = forced_selection.provider;
    llm_planner.forced_model = forced_selection.model;
    llm_planner.deterministic = st.plan_deterministic;
    llm_planner.event_conn = st.db_conn;
    llm_planner.cancel_slot = .{ .mutex = &st.plan_mutex, .slot = &st.plan_cancel_token };
    var sub_planning = direct_mode.SubscriptionPlanning.init(aa);
    defer sub_planning.deinit();
    wireSubscriptionPlanning(st, &sub_planning, &llm_planner, rec.?.db_id orelse order_id);
    // en Directo la orden no se planifica; el modelo elegido
    // responde y trabaja con las herramientas gobernadas y la política de
    // permisos viva. El resto del hilo (persistencia, historial, mensajes)
    // es el mismo que para una respuesta de charla.
    st.perm_mutex.lock();
    const order_direct = st.plan_direct;
    // T2d-D1: sin foto de permisos la orden NO corre con `.normal` en
    // silencio (las CLI se quedaban sin terminal también en Auto): falla
    // nombrando la causa.
    var direct_perms: ?permission_snapshot.OwnedPermissionSnapshot = null;
    const direct_perms_err: ?anyerror = if (order_direct) blk: {
        direct_perms = permission_snapshot.OwnedPermissionSnapshot.initClone(aa, st.perm_mode, st.perm_allow.items, st.perm_deny.items, st.perm_session_allow.items, null, null) catch |e| break :blk e;
        break :blk null;
    } else null;
    st.perm_mutex.unlock();
    if (direct_perms_err) |e| {
        setLastError(@errorName(e));
        if (findOrder(st, order_id)) |r| {
            r.status = .failed;
            persistOrderFailedWithReason(st, r, "permission_snapshot_unavailable");
        }
        st.plan_mutex.lock();
        st.plan_done = true;
        st.plan_ok = false;
        st.plan_mutex.unlock();
        return;
    }
    defer if (direct_perms) |*snap| snap.deinit(aa);
    var direct_planner = direct_mode.DirectPlanner.init(aa, st.catalog_path);
    direct_planner.rules_catalog = st.catalog.db;
    direct_planner.history = llm_planner.history;
    direct_planner.forced_provider = forced_selection.exec_provider orelse forced_selection.provider;
    direct_planner.forced_model = forced_selection.exec_model orelse forced_selection.model;
    direct_planner.event_order_id = rec.?.db_id orelse order_id;
    direct_planner.cancel_slot = .{ .mutex = &st.plan_mutex, .slot = &st.plan_cancel_token };
    if (direct_perms) |snap| direct_planner.permission_config = snap.permissionConfig();
    if (st.mcp_surface) direct_planner.origin = .mcp;
    // 10-nov: navegador integrado también en Directo (mismo registro que el
    // despacho orquestado; una orden que llega por MCP no lo recibe).
    if (!st.mcp_surface) direct_planner.browser_registry = &st.browser_registry;
    // Directo trabaja en la carpeta del proyecto: se fija aquí y se recuerda
    // para que el navegador y «Resultados» apunten al mismo sitio.
    var direct_root_buf: [4096]u8 = undefined;
    if (order_direct) {
        const direct_root = workspace.selectedProjectRoot(&direct_root_buf) orelse workspace.effectiveRoot(&direct_root_buf);
        direct_planner.workspace_root = direct_root;
        rememberDirectRoot(st, direct_planner.event_order_id, direct_root);
    }
    // USUARIO-NUEVO B (10-nov): modo «DevAgents» = Directo + `delegate_tasks`.
    // Una orden por MCP no delega (cada subtarea abriría órdenes sin cabina).
    st.perm_mutex.lock();
    const order_delegate = order_direct and st.plan_delegate and !st.mcp_surface;
    st.perm_mutex.unlock();
    const delegate_ctx: ?*DelegateCtx = if (order_delegate and direct_planner.workspace_root != null)
        DelegateCtx.create(st, direct_planner.event_order_id, rec.?.project_id, direct_planner.workspace_root.?) catch null
    else
        null;
    defer if (delegate_ctx) |d| d.release();
    if (delegate_ctx) |d| {
        direct_planner.delegate_fn = delegateTasks;
        direct_planner.delegate_ctx = @ptrCast(d);
    } else if (order_delegate) {
        // Sin memoria para el contexto: se avisa en el ledger y la vuelta sigue como Directo.
        bonEvent(st.db_conn, direct_planner.event_order_id, "delegation_blocked_v1", "{\"cause\":\"context_unavailable\"}");
    }
    // (9-nov): Directo con un agente externo elegido en «Modelo»
    // (Claude Code, Codex…): mismo catálogo y seams que el despacho orquestado.
    const direct_agent = order_direct and if (direct_planner.forced_provider) |p| external_agents.isAgentProvider(p) else false;
    var direct_external_cat: ?[]u8 = null;
    defer if (direct_external_cat) |cat| aa.free(cat);
    if (direct_agent) {
        st.external_mutex.lock();
        direct_external_cat = if (builtin.is_test and st.external_capture_fn == null) null else externalCatalog(st, aa, false) catch null;
        st.external_mutex.unlock();
        direct_planner.external = .{
            .catalog_json = direct_external_cat,
            .catalog_conn = st.catalog.db,
            .event_conn = st.db_conn,
            .run_fn = st.external_run_fn,
            .run_ctx = st.external_run_ctx,
        };
    } else if (order_direct and direct_planner.forced_provider == null) {
        // QA primerizo (10-nov): Automático sin ningún modelo recurre a un
        // agente detectado; el catálogo solo se carga si hace falta.
        direct_planner.external = .{
            .catalog_conn = st.catalog.db,
            .event_conn = st.db_conn,
            .run_fn = st.external_run_fn,
            .run_ctx = st.external_run_ctx,
            .load_fn = directCatalogLoad,
            .load_ctx = @ptrCast(st),
        };
    }
    defer direct_planner.deinit();
    const backend = if (order_direct) direct_planner.backend() else llm_planner.backend();
    const memory = st.memory.backend();

    const disc = ensureInventory(st);
    var router_storage: model_router.Router = undefined;
    const router_ptr = makeRouter(st, aa, &router_storage, st.db_conn);
    // FUGA (2026-08-06): el cache de healthFactor duplica cada clave
    // "proveedor|modelo" y la guarda; `deinitHealthCache` las libera, pero NO
    // lo llamaba ninguna ruta de produccion — solo los tests, que por eso
    // salian limpios. Cada orden dejaba atras una clave por modelo evaluado.
    defer if (router_ptr) |r| r.deinitHealthCache();
    var sup = superagent.Superagent.init(aa, st.db_conn, router_ptr, memory, health.nowSeconds(st.db_conn));
    sup.rules_catalog = st.catalog.db;
    sup.browser_registry = &st.browser_registry;
    if (st.registry) |*r| sup.registry = r;
    sup.od_mcp_state = &st.od_mcp_state;
    // P12-T3: inyectar selector agéntico + inventario + texto de orden.
    if (st.discovery_llm) |*dl| sup.discovery_llm = dl;
    sup.inventory_ptr = disc.inv;
    sup.order_text = rec.?.text;
    // MODELO-MANUAL-ORQUESTACION: propagar el modelo fijado por plan_set_model — antes
    // solo alimentaba la llamada de planificación; assignModel (dispatch por-tarea) lo
    // ignoraba y siempre enrutaba free-first pese a que el usuario fijó un modelo.
    // ROLES-MODELO: exec/audit ya vienen resueltos en la selección capturada
    // (rol ?? plan). setAuditForcedModel va DESPUÉS de setForcedModel porque
    // este último también siembra el pin de auditor (semántica "toda la orden"
    // para llamadas directas); aquí el auditor efectivo manda.
    sup.setForcedModel(forced_selection.exec_provider, forced_selection.exec_model);
    sup.setAuditForcedModel(forced_selection.audit_provider, forced_selection.audit_model);
    sup.setSwarmJson(forced_selection.swarm_json);
    sup.deterministic = st.plan_deterministic;
    // la fila ya existe (la reservó el submit); se planifica sobre ella.
    sup.wait_for_plan_approval = rec.?.wait_for_plan_approval;
    sup.reuse_order_id = rec.?.db_id;

    var outcome = sup.processOrder(rec.?.project_id, rec.?.text, &.{}, backend, disc.dbk, disc.inv) catch |e| {
        setLastError(@errorName(e));
        if (findOrder(st, order_id)) |r| {
            // PLAN-CANCEL: una cancelación en vuelo que aborta la E/S aterriza
            // aquí como error — es 'cancelled', no 'failed'.
            st.plan_mutex.lock();
            const cancelled_in_flight = st.plan_cancel_requested;
            st.plan_mutex.unlock();
            if (cancelled_in_flight) {
                markPlanCancelled(st, order_id);
            } else {
                r.status = .failed;
                persistOrderFailedWithReason(st, r, @errorName(e));
            }
        }
        st.plan_mutex.lock();
        st.plan_done = true;
        st.plan_ok = false;
        st.plan_mutex.unlock();
        return;
    };
    // GOBERNANZA-HIBRIDO-LEDGER: el gasto de la llamada del planner es real
    // aunque el plan se descarte después — la fila ESCALATION se emite igual.
    emitAuxEscalations(st, st.db_conn, aa, outcome.order_id);

    // PLAN-CANCEL: si el usuario canceló durante la planificación, el resultado
    // se descarta — incluido un plan del MockPlanner de respaldo, que sería un
    // plan fantasma para una orden ya cancelada.
    st.plan_mutex.lock();
    const cancelled_after = st.plan_cancel_requested;
    st.plan_mutex.unlock();
    if (cancelled_after) {
        outcome.plan.deinit();
        for (outcome.assignments) |a| a.deinit(aa);
        aa.free(outcome.assignments);
        markPlanCancelled(st, order_id);
        st.plan_mutex.lock();
        st.plan_done = true;
        st.plan_ok = false;
        st.plan_mutex.unlock();
        return;
    }
    setOrderConversationId(st, outcome.order_id, rec.?.conversation_id);

    st.history.push(aa, rec.?.text, outcome.plan.understanding, MAX_HISTORY_TURNS, MAX_TURN_TEXT_BYTES) catch {};

    const plan_json: ?[]const u8 = if (outcome.status != .clarifying) planToJson(aa, &outcome.plan) catch null else null;
    const questions: []const u8 = if (outcome.status == .clarifying) questionsToJson(aa, outcome.plan.questions) catch "[]" else "[]";

    const rec2 = findOrder(st, order_id);
    if (rec2) |r| {
        r.db_id = outcome.order_id;
        if (outcome.order_id > st.last_order_id) st.last_order_id = outcome.order_id;
        if (r.outcome) |*old| old.deinit();
        if (r.plan_json) |old| aa.free(old);
        aa.free(r.questions);
        r.status = outcome.status;
        r.plan_json = plan_json;
        r.outcome = outcome;
        r.questions = aa.dupe(u8, questions) catch "[]";
        if (outcome.status == .clarifying) bumpClarifyRounds(st, r);
        // SESSIONS-PERSIST-06: persistir turnos.
        saveMessageToDb(st.sessions, outcome.order_id, "user", r.text, st.db_conn);
        saveMessageToDb(st.sessions, outcome.order_id, "agent", outcome.plan.understanding, st.db_conn);
    } else {
        outcome.plan.deinit();
        for (outcome.assignments) |a| a.deinit(aa);
        aa.free(outcome.assignments);
    }

    st.plan_mutex.lock();
    st.plan_done = true;
    st.plan_ok = true;
    st.plan_mutex.unlock();
}

const AnswerContext = struct {
    st: *CoreState,
    order_id: i64,
    answers_json: []const u8,
    previous_plan_json: ?[]const u8 = null,
    /// T8: lo que el usuario pidió cambiar; solo en un replan.
    replan_changes: ?[]const u8 = null,
};

fn planAnswerThreadFn(ctx: *AnswerContext) void {
    const st = ctx.st;
    const order_id = ctx.order_id;
    const answers_json = ctx.answers_json;
    const aa = st.arena.child_allocator;
    defer {
        aa.free(answers_json);
        if (ctx.previous_plan_json) |previous| aa.free(previous);
        if (ctx.replan_changes) |changes| aa.free(changes);
        aa.destroy(ctx);
    }

    const rec = findOrder(st, order_id);
    if (rec == null) {
        st.plan_mutex.lock();
        st.plan_done = true;
        st.plan_ok = false;
        st.plan_mutex.unlock();
        return;
    }

    // PLAN-CANCEL: cancelación recibida antes de que este hilo llegara a la
    // llamada LLM — no se planifica nada.
    st.plan_mutex.lock();
    const cancelled_at_start = st.plan_cancel_requested;
    st.plan_mutex.unlock();
    if (cancelled_at_start) {
        markPlanCancelled(st, order_id);
        st.plan_mutex.lock();
        st.plan_done = true;
        st.plan_ok = false;
        st.plan_mutex.unlock();
        return;
    }

    const answers = parseClarificationAnswers(aa, answers_json) catch {
        st.plan_mutex.lock();
        st.plan_done = true;
        st.plan_ok = false;
        st.plan_mutex.unlock();
        return;
    };

    var conv_hist: planner.ConversationHistory = if (rec.?.conversation_id) |cid| loadConversationHistory(st, aa, cid) else planner.ConversationHistory.empty;
    defer conv_hist.deinit(aa);
    if (ctx.previous_plan_json) |previous| {
        conv_hist.push(aa, "Plan anterior para revisar; contexto de solo lectura", previous, MAX_HISTORY_TURNS, 128 * 1024) catch {
            setLastError("replan: OOM previous plan history");
            rec.?.status = .failed;
            persistOrderFailed(st, rec.?);
            st.plan_mutex.lock();
            st.plan_done = true;
            st.plan_ok = false;
            st.plan_mutex.unlock();
            return;
        };
    }
    var forced_selection = captureModelSelection(st, aa) catch {
        st.plan_mutex.lock();
        st.plan_done = true;
        st.plan_ok = false;
        st.plan_mutex.unlock();
        return;
    };
    defer forced_selection.deinit(aa);

    var llm_planner = live_planner.LlmPlanner.init(aa, st.catalog_path);
    llm_planner.history = if (rec.?.conversation_id != null or ctx.previous_plan_json != null) conv_hist.turns.items else st.history.turns.items;
    llm_planner.forced_provider = forced_selection.provider;
    llm_planner.forced_model = forced_selection.model;
    llm_planner.deterministic = st.plan_deterministic;
    llm_planner.event_conn = st.db_conn;
    // La orden puede ya tener db_id de una fila insertada por un replan previo
    // (clarifying→planned): los eventos deben atribuirse a la fila real, no al
    // id interno del handle.
    llm_planner.event_order_id = rec.?.db_id orelse order_id;
    llm_planner.cancel_slot = .{ .mutex = &st.plan_mutex, .slot = &st.plan_cancel_token };
    llm_planner.clarify_rounds_used = @intCast(@max(0, rec.?.clarify_rounds));
    var sub_planning = direct_mode.SubscriptionPlanning.init(aa);
    defer sub_planning.deinit();
    wireSubscriptionPlanning(st, &sub_planning, &llm_planner, rec.?.db_id orelse order_id);
    const backend = llm_planner.backend();
    const memory = st.memory.backend();

    const disc = ensureInventory(st);
    var router_storage: model_router.Router = undefined;
    const router_ptr = makeRouter(st, aa, &router_storage, st.db_conn);
    // FUGA (2026-08-06): el cache de healthFactor duplica cada clave
    // "proveedor|modelo" y la guarda; `deinitHealthCache` las libera, pero NO
    // lo llamaba ninguna ruta de produccion — solo los tests, que por eso
    // salian limpios. Cada orden dejaba atras una clave por modelo evaluado.
    defer if (router_ptr) |r| r.deinitHealthCache();
    var sup = superagent.Superagent.init(aa, st.db_conn, router_ptr, memory, health.nowSeconds(st.db_conn));
    sup.rules_catalog = st.catalog.db;
    sup.browser_registry = &st.browser_registry;
    if (st.registry) |*r| sup.registry = r;
    sup.od_mcp_state = &st.od_mcp_state;
    // P12-T3: inyectar selector agéntico + inventario + texto de orden.
    if (st.discovery_llm) |*dl| sup.discovery_llm = dl;
    sup.inventory_ptr = disc.inv;
    sup.order_text = rec.?.text;
    // MODELO-MANUAL-ORQUESTACION: propagar el modelo fijado por plan_set_model — antes
    // solo alimentaba la llamada de planificación; assignModel (dispatch por-tarea) lo
    // ignoraba y siempre enrutaba free-first pese a que el usuario fijó un modelo.
    // ROLES-MODELO: exec/audit ya vienen resueltos en la selección capturada
    // (rol ?? plan). setAuditForcedModel va DESPUÉS de setForcedModel porque
    // este último también siembra el pin de auditor (semántica "toda la orden"
    // para llamadas directas); aquí el auditor efectivo manda.
    sup.setForcedModel(forced_selection.exec_provider, forced_selection.exec_model);
    sup.setAuditForcedModel(forced_selection.audit_provider, forced_selection.audit_model);
    sup.setSwarmJson(forced_selection.swarm_json);
    sup.deterministic = st.plan_deterministic;
    // replanificar sobre la MISMA fila (ver el answer síncrono).
    sup.wait_for_plan_approval = rec.?.wait_for_plan_approval;
    sup.reuse_order_id = rec.?.db_id;
    sup.replan_changes = ctx.replan_changes;
    var outcome = sup.processOrder(rec.?.project_id, rec.?.text, answers, backend, disc.dbk, disc.inv) catch |e| {
        setLastError(@errorName(e));
        if (findOrder(st, order_id)) |r| {
            // PLAN-CANCEL: cancelación en vuelo que abortó la E/S — 'cancelled',
            // no 'failed'.
            st.plan_mutex.lock();
            const cancelled_in_flight = st.plan_cancel_requested;
            st.plan_mutex.unlock();
            if (cancelled_in_flight) {
                markPlanCancelled(st, order_id);
            } else {
                r.status = .failed;
            }
        }
        st.plan_mutex.lock();
        st.plan_done = true;
        st.plan_ok = false;
        st.plan_mutex.unlock();
        return;
    };
    // GOBERNANZA-HIBRIDO-LEDGER: el gasto de la replanificación es real aunque
    // el plan se descarte — la fila ESCALATION se emite igual.
    emitAuxEscalations(st, st.db_conn, aa, outcome.order_id);

    // PLAN-CANCEL: cancelación durante la replanificación — el outcome se
    // descarta; la orden queda 'cancelled', nunca un plan fantasma.
    st.plan_mutex.lock();
    const cancelled_after = st.plan_cancel_requested;
    st.plan_mutex.unlock();
    if (cancelled_after) {
        outcome.plan.deinit();
        for (outcome.assignments) |a| a.deinit(aa);
        aa.free(outcome.assignments);
        markPlanCancelled(st, order_id);
        st.plan_mutex.lock();
        st.plan_done = true;
        st.plan_ok = false;
        st.plan_mutex.unlock();
        return;
    }
    setOrderConversationId(st, outcome.order_id, rec.?.conversation_id);

    st.history.push(aa, rec.?.text, outcome.plan.understanding, MAX_HISTORY_TURNS, MAX_TURN_TEXT_BYTES) catch {};

    const rec2 = findOrder(st, order_id);
    if (rec2) |r| {
        if (r.outcome) |*old| old.deinit();
        if (r.plan_json) |j| aa.free(j);
        aa.free(r.questions);

        r.status = outcome.status;
        r.plan_json = planToJson(aa, &outcome.plan) catch null;
        r.outcome = outcome;
        // El outcome del replan vive bajo un order_id NUEVO (processOrder
        // inserta su propia fila). Sin esto el registro apunta a la fila
        // clarifying vieja y findOrder/plan_set/terminal leen la orden
        // equivocada — mismo ajuste que el submit async (r.db_id = order_id).
        r.db_id = outcome.order_id;
        if (outcome.order_id > st.last_order_id) st.last_order_id = outcome.order_id;
        r.questions = questionsToJson(aa, outcome.plan.questions) catch "[]";
        if (outcome.status == .clarifying) bumpClarifyRounds(st, r);
        // SESSIONS-PERSIST-06: persistir turnos.
        if (r.db_id) |db_id| {
            saveMessageToDb(st.sessions, db_id, "user", answers_json, st.db_conn);
            saveMessageToDb(st.sessions, db_id, "agent", outcome.plan.understanding, st.db_conn);
        }
    } else {
        outcome.plan.deinit();
        for (outcome.assignments) |a| a.deinit(aa);
        aa.free(outcome.assignments);
    }

    st.plan_mutex.lock();
    st.plan_done = true;
    st.plan_ok = true;
    st.plan_mutex.unlock();
}

/// Envía una orden en lenguaje natural de forma asíncrona (F7-ASYNC-PLAN).
/// Retorna inmediatamente con el handle pre-creado; el progreso se consulta
/// con da_order_plan_poll y da_order_status. No bloquea el hilo de UI.
pub export fn da_order_submit_async(handle: ?*anyopaque, order_text: [*:0]const u8, project_id: [*:0]const u8, conversation_id: ?[*:0]const u8, out_order: *?*anyopaque) callconv(.c) c_int {
    return da_order_submit_images_async(handle, order_text, project_id, conversation_id, null, out_order);
}

/// E5.23: contrato aditivo; valida y guarda las imágenes ANTES de planificar.
pub export fn da_order_submit_images_async(handle: ?*anyopaque, order_text: [*:0]const u8, project_id: [*:0]const u8, conversation_id: ?[*:0]const u8, attachments_json: ?[*:0]const u8, out_order: *?*anyopaque) callconv(.c) c_int {
    return submitAsyncWithIssue(handle, order_text, project_id, conversation_id, attachments_json, out_order, null, false);
}

fn submitAsyncWithIssue(handle: ?*anyopaque, order_text: [*:0]const u8, project_id: [*:0]const u8, conversation_id: ?[*:0]const u8, attachments_json: ?[*:0]const u8, out_order: *?*anyopaque, issue: ?*const issues.Issue, wait_for_plan_approval: bool) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_order_submit_async: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    if (rejectInvalidConfiguration(st)) |rc| return rc;

    const text = std.mem.span(order_text);
    const proj = std.mem.span(project_id);
    const conv_id: ?[]const u8 = if (conversation_id) |c| std.mem.span(c) else null;
    if (text.len == 0) return @intFromEnum(err(.invalid_arg, "da_order_submit_async: empty order text"));

    const image_json = if (attachments_json) |j| std.mem.span(j) else "[]";
    if (image_json.len > 28 * 1024 * 1024) return @intFromEnum(err(.invalid_arg, "attachments: transporte excede 28 MiB"));
    const parsed_images = std.json.parseFromSlice(std.json.Value, aa, image_json, .{}) catch
        return @intFromEnum(err(.invalid_arg, "attachments: JSON invalido"));
    defer parsed_images.deinit();
    var images = order_attachments.decodeInputs(aa, parsed_images.value) catch |e|
        return @intFromEnum(err(.invalid_arg, @errorName(e)));
    defer images.deinit();
    if (images.items.items.len > 0 and std.mem.eql(u8, st.runtime_path, ":memory:"))
        return @intFromEnum(err(.invalid_arg, "attachments: requiere directorio de datos persistente"));

    st.plan_mutex.lock();
    defer st.plan_mutex.unlock();

    if (!st.plan_done) return @intFromEnum(err(.invalid_state, "da_order_submit_async: plan already in progress"));

    // la fila se reserva AQUÍ y su rowid es el id que se devuelve. Antes
    // era `last_order_id + 1`, un contador por proceso: con host y MCP a la vez
    // el driver recibió orderId=704 cuya fila real era la 710.
    var issue_committed = issue == null;
    if (issue != null) st.db_conn.exec("BEGIN IMMEDIATE") catch
        return @intFromEnum(err(.internal, "order_from_issue: no se pudo iniciar la transaccion"));
    defer if (!issue_committed) {
        st.db_conn.exec("ROLLBACK") catch |rollback_error| {
            _ = err(.internal, @errorName(rollback_error));
        };
    };
    const order_id = superagent.Superagent.insertOrderRow(st.db_conn, proj, text, "pending", health.nowSeconds(st.db_conn)) catch
        return @intFromEnum(err(.internal, "da_order_submit_async: no se pudo reservar la fila de la orden"));
    if (issue) |linked| {
        issues.linkOrder(st.db_conn, order_id, linked.*) catch
            return @intFromEnum(err(.internal, "order_from_issue: no se pudo guardar el vinculo; planificador no iniciado"));
        st.db_conn.exec("COMMIT") catch
            return @intFromEnum(err(.internal, "order_from_issue: no se pudo confirmar el vinculo"));
        issue_committed = true;
    }
    if (order_id > st.last_order_id) st.last_order_id = order_id;

    if (images.items.items.len > 0) {
        var image_io = std.Io.Threaded.init(aa, .{});
        defer image_io.deinit();
        order_attachments.store(aa, image_io.io(), st.db_conn, std.fs.path.dirname(st.runtime_path) orelse ".", order_id, &images) catch |e| {
            const failed = st.db_conn.prepare("UPDATE orders SET status='failed' WHERE id=?") catch
                return @intFromEnum(err(.internal, "attachments: almacenamiento y registro de fallo fallaron"));
            defer st.db_conn.finalize(failed);
            db.bindInt(failed, 1, order_id) catch return @intFromEnum(err(.internal, "attachments: no se pudo registrar fallo"));
            if (db.c.sqlite3_step(failed) != db.c.SQLITE_DONE) return @intFromEnum(err(.internal, "attachments: no se pudo registrar fallo"));
            return @intFromEnum(err(.internal, @errorName(e)));
        };
    }

    const text_copy = aa.dupe(u8, text) catch return @intFromEnum(err(.oom, "da_order_submit_async: OOM duplicating text"));
    const proj_copy = aa.dupe(u8, proj) catch {
        aa.free(text_copy);
        return @intFromEnum(err(.oom, "da_order_submit_async: OOM duplicating project_id"));
    };
    const conv_id_copy: ?[]const u8 = if (conv_id) |c| (aa.dupe(u8, c) catch null) else null;

    const rec = aa.create(OrderRecord) catch {
        aa.free(text_copy);
        aa.free(proj_copy);
        return @intFromEnum(err(.oom, "da_order_submit_async: OOM creating order"));
    };
    rec.* = OrderRecord{
        .id = order_id,
        .db_id = order_id,
        .text = text_copy,
        .project_id = proj_copy,
        .status = .pending,
        .wait_for_plan_approval = wait_for_plan_approval,
        .plan_json = null,
        .outcome = null,
        .questions = &.{},
        .conversation_id = conv_id_copy,
        .created_at = health.nowSeconds(st.db_conn), // segundos de época, como la fila (22-09)
    };
    st.orders_mutex.lock();
    st.orders.append(aa, rec) catch {
        st.orders_mutex.unlock();
        aa.destroy(rec);
        aa.free(text_copy);
        aa.free(proj_copy);
        return @intFromEnum(err(.oom, "da_order_submit_async: OOM creating order"));
    };
    st.orders_mutex.unlock();
    out_order.* = orderIdToHandle(order_id);

    st.plan_done = false;
    st.plan_ok = false;
    st.plan_order_id = order_id;
    // PLAN-CANCEL: una cancelación de la planificación ANTERIOR no puede
    // contaminar esta; el slot queda a null hasta que el hilo registre token.
    st.plan_cancel_requested = false;
    st.plan_cancel_token = null;

    const ctx = aa.create(PlanContext) catch {
        st.plan_done = true;
        return @intFromEnum(err(.oom, "da_order_submit_async: OOM creating context"));
    };
    ctx.* = .{ .st = st, .order_id = order_id };

    st.plan_thread = std.Thread.spawn(.{}, planThreadFn, .{ctx}) catch {
        st.plan_done = true;
        aa.destroy(ctx);
        return @intFromEnum(err(.internal, "da_order_submit_async: failed to spawn thread"));
    };
    return @intFromEnum(ok());
}

pub export fn da_order_attachments_json(handle: ?*anyopaque, order: ?*anyopaque, out_json: *?[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "attachments: null core"));
    const order_id = orderHandleToId(order) orelse return @intFromEnum(err(.invalid_arg, "attachments: null order"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const a = st.arena.child_allocator;
    const json = order_attachments.listJson(a, st.db_conn, order_id) catch |e| return @intFromEnum(err(.internal, @errorName(e)));
    defer a.free(json);
    out_json.* = ownedCStr(json) orelse return @intFromEnum(err(.oom, "attachments: OOM"));
    return @intFromEnum(ok());
}

/// Responde preguntas de clarificación de forma asíncrona (F7-ASYNC-PLAN).
/// Retorna inmediatamente; consulta progreso con da_order_plan_poll.
pub export fn da_order_answer_async(handle: ?*anyopaque, order: ?*anyopaque, answers_json: [*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_order_answer_async: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order) orelse return @intFromEnum(err(.invalid_arg, "da_order_answer_async: null order handle"));
    const aa = st.arena.child_allocator;

    const rec = findOrder(st, order_id) orelse return @intFromEnum(err(.not_found, "da_order_answer_async: order not found"));
    if (rec.status != .clarifying) return @intFromEnum(err(.invalid_state, "da_order_answer_async: order is not in clarifying state"));

    const json_str = std.mem.span(answers_json);
    if (json_str.len == 0) return @intFromEnum(err(.invalid_arg, "da_order_answer_async: empty answers"));

    st.plan_mutex.lock();
    defer st.plan_mutex.unlock();

    if (!st.plan_done) return @intFromEnum(err(.invalid_state, "da_order_answer_async: plan already in progress"));

    const answers_copy = aa.dupe(u8, json_str) catch return @intFromEnum(err(.oom, "da_order_answer_async: OOM duplicating answers"));

    st.plan_done = false;
    st.plan_ok = false;
    st.plan_order_id = order_id;
    // PLAN-CANCEL: mismo reset que en submit — la cancelación de una
    // planificación previa no debe matar esta replanificación.
    st.plan_cancel_requested = false;
    st.plan_cancel_token = null;

    const ctx = aa.create(AnswerContext) catch {
        aa.free(answers_copy);
        return @intFromEnum(err(.oom, "da_order_answer_async: OOM creating context"));
    };
    ctx.* = .{ .st = st, .order_id = order_id, .answers_json = answers_copy };

    st.plan_thread = std.Thread.spawn(.{}, planAnswerThreadFn, .{ctx}) catch {
        st.plan_done = true;
        aa.free(answers_copy);
        aa.destroy(ctx);
        return @intFromEnum(err(.internal, "da_order_answer_async: failed to spawn thread"));
    };
    return @intFromEnum(ok());
}

/// Consulta si una planificación/respuesta async iniciada por da_order_submit_async
/// o da_order_answer_async ha terminado. out_done=1 si terminó, out_ok=1 si tuvo
/// éxito (solo válido cuando out_done=1).
pub export fn da_order_plan_poll(handle: ?*anyopaque, out_done: *c_int, out_ok: *c_int) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_order_plan_poll: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));

    st.plan_mutex.lock();
    defer st.plan_mutex.unlock();

    out_done.* = if (st.plan_done) 1 else 0;
    out_ok.* = if (st.plan_done and st.plan_ok) 1 else 0;

    if (st.plan_done and st.plan_thread != null) {
        const t = st.plan_thread.?;
        st.plan_thread = null;
        t.join();
    }
    return @intFromEnum(ok());
}

/// ROLES-MODELO: cuerpo común de los setters de pin por rol. `slot_*` son los
/// campos de CoreState a reemplazar; provider/model vacíos o NULL limpian el
/// pin (ese rol vuelve al pin general de la orden — o al router si tampoco hay).
fn setModelPin(st: *CoreState, slot_p: *?[:0]const u8, slot_m: *?[:0]const u8, provider: ?[*:0]const u8, model: ?[*:0]const u8) c_int {
    const aa = st.arena.child_allocator;

    const prov = if (provider) |p| std.mem.span(p) else null;
    const mod = if (model) |m| std.mem.span(m) else null;

    if (prov == null or prov.?.len == 0 or mod == null or mod.?.len == 0) {
        st.perm_mutex.lock();
        defer st.perm_mutex.unlock();
        if (slot_p.*) |p| aa.free(p);
        if (slot_m.*) |m| aa.free(m);
        slot_p.* = null;
        slot_m.* = null;
        return @intFromEnum(ok());
    }

    if (!builtin.is_test and external_agents.isAgentProvider(prov.?)) {
        st.external_mutex.lock();
        const catalog = externalCatalog(st, aa, false) catch {
            st.external_mutex.unlock();
            return @intFromEnum(err(.internal, "external CLI catalog unavailable"));
        };
        st.external_mutex.unlock();
        defer aa.free(catalog);
        const pin = external_registry.resolvePin(aa, st.catalog.db, catalog, prov.?, mod.?) catch
            return @intFromEnum(err(.invalid_arg, "modelo externo no disponible; la facturación API está bloqueada"));
        pin.deinit(aa);
    }
    const prov_copy = aa.dupeZ(u8, prov.?) catch return @intFromEnum(err(.oom, "OOM"));
    const mod_copy = aa.dupeZ(u8, mod.?) catch {
        aa.free(prov_copy);
        return @intFromEnum(err(.oom, "OOM"));
    };

    st.perm_mutex.lock();
    defer st.perm_mutex.unlock();
    if (slot_p.*) |p| aa.free(p);
    if (slot_m.*) |m| aa.free(m);
    slot_p.* = prov_copy;
    slot_m.* = mod_copy;
    return @intFromEnum(ok());
}

/// ROLES-MODELO: cuerpo común de los getters de pin por rol.
fn getModelPin(st: *CoreState, slot_p: ?[:0]const u8, slot_m: ?[:0]const u8, out_provider: *?[*:0]const u8, out_model: *?[*:0]const u8) c_int {
    st.perm_mutex.lock();
    defer st.perm_mutex.unlock();

    if (slot_p) |p| {
        out_provider.* = ownedCStr(p) orelse return @intFromEnum(err(.oom, "OOM"));
    } else {
        out_provider.* = null;
    }
    if (slot_m) |m| {
        out_model.* = ownedCStr(m) orelse return @intFromEnum(err(.oom, "OOM"));
    } else {
        out_model.* = null;
    }
    return @intFromEnum(ok());
}

/// Fija el modelo forzado para planificación (F7-MODEL-SELECT).
/// provider o model NULL o cadena vacía → modo automático (router).
/// Las cadenas se copian internamente; el caller puede liberarlas.
/// ROLES-MODELO: este pin es el del coordinador y a la vez el general de la
/// orden — ejecutor y auditor lo heredan si no tienen pin propio.
pub export fn da_plan_set_model(handle: ?*anyopaque, provider: ?[*:0]const u8, model: ?[*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_plan_set_model: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    return setModelPin(st, &st.plan_forced_provider, &st.plan_forced_model, provider, model);
}

/// ROLES-MODELO: fija el modelo del EJECUTOR (tareas constructoras y
/// correcciones). Vacío/NULL = sigue al pin de la orden (da_plan_set_model).
/// Export nuevo (aditivo, no rompe C-ABI).
pub export fn da_exec_set_model(handle: ?*anyopaque, provider: ?[*:0]const u8, model: ?[*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_exec_set_model: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    return setModelPin(st, &st.exec_forced_provider, &st.exec_forced_model, provider, model);
}

/// ROLES-MODELO: fija el modelo del AUDITOR (solo tareas .auditar). Vacío/NULL
/// = automático con exclusión del fabricante productor. El auditor nunca
/// hereda el pin del planificador ni del ejecutor.
pub export fn da_audit_set_model(handle: ?*anyopaque, provider: ?[*:0]const u8, model: ?[*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_audit_set_model: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    if (provider != null and model != null and std.mem.span(provider.?).len > 0 and std.mem.span(model.?).len > 0) {
        st.perm_mutex.lock();
        const producer_p = st.exec_forced_provider orelse st.plan_forced_provider;
        const producer_m = st.exec_forced_model orelse st.plan_forced_model;
        const conflict = if (producer_p != null and producer_m != null)
            external_agents.crossModelManufacturerExcluded(producer_p.?, producer_m.?, std.mem.span(provider.?), std.mem.span(model.?))
        else
            false;
        st.perm_mutex.unlock();
        if (conflict) return @intFromEnum(err(.invalid_arg, "auditor vetado: mismo fabricante que el productor o fabricante desconocido"));
    }
    return setModelPin(st, &st.audit_forced_provider, &st.audit_forced_model, provider, model);
}

/// MODO-DETERMINISTA: con un modelo fijado por `da_plan_set_model`, prohíbe los
/// respaldos en TODA la orden — planificación, cada tarea y la corrección. La
/// orden la hace ese modelo o falla nombrándolo.
///
/// Export NUEVO en vez de un parámetro más en `da_plan_set_model`: cambiar la
/// firma de un export ya publicado rompería el contrato C-ABI (R4), y esto es
/// aditivo. Un host viejo que no lo llame se comporta exactamente como antes.
///
/// También sin pin limita cada selección automática a su primer candidato.
/// activa o apaga el modo Directo para las órdenes siguientes.
pub export fn da_set_direct_mode(handle: ?*anyopaque, enabled: c_int) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_set_direct_mode: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    st.perm_mutex.lock();
    defer st.perm_mutex.unlock();
    st.plan_direct = enabled != 0;
    // USUARIO-NUEVO B (10-nov): 2 = modo «DevAgents» (Directo que puede
    // delegar subtareas en paralelo, cada una en su worktree).
    st.plan_delegate = enabled == 2;
    return @intFromEnum(ok());
}

pub export fn da_get_direct_mode(handle: ?*anyopaque, out_enabled: ?*c_int) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_get_direct_mode: null core handle"));
    const out = out_enabled orelse return @intFromEnum(err(.invalid_arg, "da_get_direct_mode: null out"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    st.perm_mutex.lock();
    defer st.perm_mutex.unlock();
    out.* = if (st.plan_delegate) 2 else if (st.plan_direct) 1 else 0;
    return @intFromEnum(ok());
}

pub export fn da_set_deterministic_mode(handle: ?*anyopaque, enabled: c_int) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_set_deterministic_mode: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    st.perm_mutex.lock();
    defer st.perm_mutex.unlock();
    st.plan_deterministic = enabled != 0;
    return @intFromEnum(ok());
}

/// Estado actual del modo determinista, para que la interfaz pueda reflejarlo
/// tras un reinicio en vez de suponerlo apagado.
pub export fn da_get_deterministic_mode(handle: ?*anyopaque, out_enabled: ?*c_int) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_get_deterministic_mode: null core handle"));
    const out = out_enabled orelse return @intFromEnum(err(.invalid_arg, "da_get_deterministic_mode: null out"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    st.perm_mutex.lock();
    defer st.perm_mutex.unlock();
    out.* = if (st.plan_deterministic) 1 else 0;
    return @intFromEnum(ok());
}

/// FASE-AGENTIC-3: fija el tope de iteraciones del loop observe→re-planifica.
/// 1 (default) = un solo paso (comportamiento estable de hoy). ≥2 activa el loop
/// autónomo. Se acota a [1, 12] para que un valor absurdo no dispare un loop
/// desbocado (tope duro de seguridad, independiente del gate del evaluador).
pub export fn da_set_agentic_max_iterations(handle: ?*anyopaque, max_iterations: u32) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_set_agentic_max_iterations: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const clamped: usize = @min(@max(@as(usize, max_iterations), 1), 12);
    st.agentic_max_iterations = clamped;
    return @intFromEnum(ok());
}

/// Estado actual del tope agéntico, para que la UI lo refleje en vez de
/// suponer 1 tras un reinicio del proceso.
pub export fn da_get_agentic_max_iterations(handle: ?*anyopaque, out_iterations: *u32) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_get_agentic_max_iterations: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    out_iterations.* = @intCast(st.agentic_max_iterations);
    return @intFromEnum(ok());
}

/// Devuelve el modelo forzado para planificación (F7-MODEL-SELECT).
/// Si no hay modelo forzado, out_provider y out_model se setean a NULL.
/// Las cadenas devueltas deben liberarse con da_string_free.
/// ROLES-MODELO: devuelve el pin del coordinador (el general de la orden).
pub export fn da_plan_get_model(handle: ?*anyopaque, out_provider: *?[*:0]const u8, out_model: *?[*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_plan_get_model: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    return getModelPin(st, st.plan_forced_provider, st.plan_forced_model, out_provider, out_model);
}

/// ROLES-MODELO: pin específico del ejecutor (NULL = sigue al de la orden).
pub export fn da_exec_get_model(handle: ?*anyopaque, out_provider: *?[*:0]const u8, out_model: *?[*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_exec_get_model: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    return getModelPin(st, st.exec_forced_provider, st.exec_forced_model, out_provider, out_model);
}

/// ROLES-MODELO: pin específico del auditor (NULL = sigue al de la orden).
pub export fn da_audit_get_model(handle: ?*anyopaque, out_provider: *?[*:0]const u8, out_model: *?[*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_audit_get_model: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    return getModelPin(st, st.audit_forced_provider, st.audit_forced_model, out_provider, out_model);
}

/// ENJAMBRE: fija el conjunto cerrado de modelos para las tareas productoras.
/// `json` = `[{provider,model}]`; NULL, "" o "[]" = Automático (el router
/// decide por tarea, como siempre). Se valida la forma y se guarda
/// NORMALIZADO (solo provider/model, máximo 8 miembros) — un miembro que no
/// sea objeto {provider,model} strings no vacíos invalida TODO el conjunto.
/// No consulta el catálogo a propósito: la gobernanza (coste, proveedor caído,
/// no-generadores) se aplica por tarea en assignModel, donde ese contexto está
/// vivo. Export aditivo (C-ABI intacto).
pub export fn da_swarm_set_models_json(handle: ?*anyopaque, json: ?[*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_swarm_set_models_json: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    const raw = if (json) |j| std.mem.span(j) else "";
    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var count: usize = 0;
    if (raw.len > 0) {
        var parsed = std.json.parseFromSlice(std.json.Value, aa, raw, .{}) catch
            return @intFromEnum(err(.invalid_arg, "da_swarm_set_models_json: JSON invalido"));
        defer parsed.deinit();
        if (parsed.value != .array)
            return @intFromEnum(err(.invalid_arg, "da_swarm_set_models_json: se esperaba [{provider,model}]"));
        var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
        js.beginArray() catch return @intFromEnum(err(.oom, "OOM"));
        for (parsed.value.array.items) |item| {
            if (item != .object)
                return @intFromEnum(err(.invalid_arg, "da_swarm_set_models_json: cada miembro debe ser {provider,model}"));
            const pv = item.object.get("provider") orelse
                return @intFromEnum(err(.invalid_arg, "da_swarm_set_models_json: miembro sin provider"));
            const mv = item.object.get("model") orelse
                return @intFromEnum(err(.invalid_arg, "da_swarm_set_models_json: miembro sin model"));
            if (pv != .string or mv != .string or pv.string.len == 0 or mv.string.len == 0)
                return @intFromEnum(err(.invalid_arg, "da_swarm_set_models_json: provider/model deben ser strings no vacios"));
            if (count >= 8)
                return @intFromEnum(err(.invalid_arg, "da_swarm_set_models_json: maximo 8 miembros"));
            js.beginObject() catch return @intFromEnum(err(.oom, "OOM"));
            js.objectField("provider") catch return @intFromEnum(err(.oom, "OOM"));
            js.write(pv.string) catch return @intFromEnum(err(.oom, "OOM"));
            js.objectField("model") catch return @intFromEnum(err(.oom, "OOM"));
            js.write(mv.string) catch return @intFromEnum(err(.oom, "OOM"));
            js.endObject() catch return @intFromEnum(err(.oom, "OOM"));
            count += 1;
        }
        js.endArray() catch return @intFromEnum(err(.oom, "OOM"));
    }
    const stored: ?[:0]const u8 = if (count == 0)
        null
    else
        aa.dupeZ(u8, out.written()) catch return @intFromEnum(err(.oom, "OOM"));

    st.perm_mutex.lock();
    defer st.perm_mutex.unlock();
    if (st.swarm_models_json) |old| aa.free(old);
    st.swarm_models_json = stored;
    return @intFromEnum(ok());
}

/// ENJAMBRE: devuelve el conjunto fijado como JSON `[{provider,model}]`
/// ("[]" = Automático). La cadena devuelta se libera con da_string_free.
pub export fn da_swarm_get_models_json(handle: ?*anyopaque, out_json: ?*?[*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_swarm_get_models_json: null core handle"));
    const out = out_json orelse return @intFromEnum(err(.invalid_arg, "da_swarm_get_models_json: null out"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    st.perm_mutex.lock();
    defer st.perm_mutex.unlock();
    const body = st.swarm_models_json orelse "[]";
    out.* = ownedCStr(body) orelse return @intFromEnum(err(.oom, "OOM"));
    return @intFromEnum(ok());
}

/// additive read-only ABI. No discovery, process or network.
pub export fn da_cli_quota_v1_json(handle: ?*anyopaque, out_json: ?*?[*:0]const u8) callconv(.c) c_int {
    const out = out_json orelse return @intFromEnum(err(.invalid_arg, "quota: null out"));
    out.* = null;
    const st: *CoreState = @ptrCast(@alignCast(handle orelse return @intFromEnum(err(.invalid_arg, "quota: null handle"))));
    st.external_mutex.lock();
    defer st.external_mutex.unlock();
    const a = st.arena.child_allocator;
    const body = @import("cli_quota.zig").allJson(a, st.catalog.db) catch return @intFromEnum(err(.internal, "quota: read failed"));
    defer a.free(body);
    out.* = ownedCStr(body) orelse return @intFromEnum(err(.oom, "quota: OOM"));
    return @intFromEnum(ok());
}

/// E5.08 — registro de agentes externos (GOBIERNO ENCIMA): detecta los CLIs
/// instalados (`<cli> --version` por `detectAll`) y devuelve el catálogo JSON
/// [{provider, cli, display, exe, version, acp, manufacturer, label}].
/// Solo figuran los CLIs realmente presentes (versión legible) — nunca se
/// finge disponibilidad. El caller libera con da_string_free.
pub export fn da_external_agents_json(handle: ?*anyopaque, out_json: ?*?[*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_external_agents_json: null core handle"));
    const out = out_json orelse return @intFromEnum(err(.invalid_arg, "da_external_agents_json: null out"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    st.external_mutex.lock();
    defer st.external_mutex.unlock();
    const body = externalCatalog(st, aa, false) catch
        return @intFromEnum(err(.internal, "da_external_agents_json: detección o caché falló"));
    defer aa.free(body);
    out.* = ownedCStr(body) orelse return @intFromEnum(err(.oom, "OOM"));
    return @intFromEnum(ok());
