/// Tanda 4 (F0.5): `doctor` para la cabina. Usa el catálogo de agentes ya
/// detectado (o la caché), la carpeta de datos de esta sesión, la raíz del
/// proyecto elegido y las claves activas del catálogo. No lanza órdenes ni
/// sale a la red (Ollama solo en loopback).
pub export fn da_doctor_json(handle: ?*anyopaque, out_json: ?*?[*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_doctor_json: null core handle"));
    const out = out_json orelse return @intFromEnum(err(.invalid_arg, "da_doctor_json: null out"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    const agents_json: ?[]u8 = blk: {
        if (builtin.is_test and st.external_capture_fn == null) break :blk null;
        st.external_mutex.lock();
        defer st.external_mutex.unlock();
        break :blk externalCatalog(st, aa, false) catch null;
    };
    defer if (agents_json) |j| aa.free(j);
    var saved_keys: usize = 0;
    if (st.catalog.db.prepare("SELECT COUNT(*) FROM api_keys WHERE status='active'")) |stmt| {
        defer st.catalog.db.finalize(stmt);
        if (db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW) saved_keys = @intCast(@max(0, db.c.sqlite3_column_int64(stmt, 0)));
    } else |_| {}
    const in_memory = std.mem.eql(u8, st.runtime_path, ":memory:");
    const data_dir: ?[]const u8 = if (in_memory) null else std.fs.path.dirname(st.runtime_path);
    var ws_buf: [4096]u8 = undefined;
    const ws = workspace.effectiveRoot(&ws_buf);
    var report = doctor.run(aa, .{
        .data_dir = data_dir,
        .data_dir_error = if (in_memory) "base en memoria (sesión de prueba)" else null,
        .workspace = if (ws.len > 0) ws else null,
        .agents_json = agents_json,
        .saved_keys = saved_keys,
        .probes = if (builtin.is_test) doctor_test_probes orelse doctor.realProbes() else doctor.realProbes(),
    }) catch return @intFromEnum(err(.oom, "da_doctor_json: OOM"));
    defer report.deinit();
    const body = doctor.toJson(aa, report) catch return @intFromEnum(err(.oom, "OOM"));
    defer aa.free(body);
    out.* = ownedCStr(body) orelse return @intFromEnum(err(.oom, "OOM"));
    return @intFromEnum(ok());
}

var doctor_test_probes: ?doctor.Probes = null;

test "T4 doctor: da_doctor_json devuelve el informe con las comprobaciones" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    var out: ?[*:0]const u8 = null;
    try std.testing.expectEqual(@as(c_int, 0), da_doctor_json(handle, &out));
    defer da_string_free(@constCast(out.?));
    const body = std.mem.span(out.?);
    var parsed = try std.json.parseFromSlice(std.json.Value, std.testing.allocator, body, .{});
    defer parsed.deinit();
    try std.testing.expectEqual(@as(i64, 1), parsed.value.object.get("version").?.integer);
    // En memoria no hay carpeta de datos: no puede estar listo.
    try std.testing.expect(!parsed.value.object.get("ready").?.bool);
    var ids: usize = 0;
    for (parsed.value.object.get("checks").?.array.items) |c| {
        if (std.mem.eql(u8, c.object.get("id").?.string, "data_dir") or std.mem.eql(u8, c.object.get("id").?.string, "webview2") or std.mem.eql(u8, c.object.get("id").?.string, "routes")) ids += 1;
    }
    try std.testing.expectEqual(@as(usize, 3), ids);
    try std.testing.expect(da_doctor_json(null, &out) != 0);
}

// ------------------------------------------------------------------
// Tanda 5 (F0.4,): actualizador «avisar y aplicar al cerrar».
// La lógica vive en updater.zig; aquí, la frontera C y el estado real de
// órdenes del motor. Todas devuelven el estado completo (da_update_state_json)
// salvo set_enabled / set_apply_on_exit (código) y pending_apply (su JSON).

var update_test_deps: ?updater.Deps = null;

fn updateNoNetwork(_: ?*anyopaque, _: std.mem.Allocator, _: []const u8, _: updater.FetchKind, _: usize) anyerror!updater.Response {
    return error.NetworkDisabledInTests;
}

fn updateNoVerify(_: ?*anyopaque, _: std.mem.Allocator, _: []const u8) anyerror!updater.SignatureResult {
    return error.NetworkDisabledInTests;
}

/// En la suite nunca hay red: sin dobles explícitos, la red falla en voz alta.
fn updateDeps() updater.Deps {
    if (builtin.is_test) return update_test_deps orelse .{ .fetch = updateNoNetwork, .verify = updateNoVerify };
    return .{};
}

/// Carpeta de datos del runtime (la de runtime.db), como `da_doctor_json`.
fn updateDataDir(st: *CoreState) ?[]const u8 {
    if (std.mem.eql(u8, st.runtime_path, ":memory:")) return null;
    return std.fs.path.dirname(st.runtime_path);
}

/// ¿Hay alguna orden en curso? Un despacho vivo en este proceso, o una orden
/// en un estado activo en runtime.db (las mismas que RESUME-INTERRUPTED marca
/// como interrumpidas al abrir: un hilo que la está llevando, aquí o en otro
/// proceso con la misma base).
fn ordersInFlight(st: *CoreState) !bool {
    if (st.dispatch_registry.hasAnyInFlight()) return true;
    const stmt = try st.db_conn.prepare("SELECT EXISTS(SELECT 1 FROM orders WHERE status IN ('pending','approved','running','awaiting_approval'))");
    defer st.db_conn.finalize(stmt);
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) return error.OrdersUnavailable;
    return db.c.sqlite3_column_int64(stmt, 0) != 0;
}

fn updateStateOut(st: *CoreState, out: *?[*:0]const u8, comptime name: []const u8) c_int {
    const aa = st.arena.child_allocator;
    const body = updater.stateJson(aa, st.catalog.db) catch
        return @intFromEnum(err(.internal, name ++ ": no se pudo leer el estado del actualizador"));
    defer aa.free(body);
    out.* = ownedCStr(body) orelse return @intFromEnum(err(.oom, "OOM"));
    return @intFromEnum(ok());
}

/// Estado del actualizador para la cabina, sin red.
pub export fn da_update_state_json(handle: ?*anyopaque, out_json: ?*?[*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_update_state_json: null core handle"));
    const out = out_json orelse return @intFromEnum(err(.invalid_arg, "da_update_state_json: null out"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    return updateStateOut(st, out, "da_update_state_json");
}

/// Comprobación: `force` != 0 ignora las 24 h (botón «Buscar ahora»).
/// Desactivada, no sale a la red. Devuelve el estado.
pub export fn da_update_check_json(handle: ?*anyopaque, force: c_int, out_json: ?*?[*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_update_check_json: null core handle"));
    const out = out_json orelse return @intFromEnum(err(.invalid_arg, "da_update_check_json: null out"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    {
        st.update_mutex.lock();
        defer st.update_mutex.unlock();
        updater.check(st.arena.child_allocator, st.catalog.db, updateDeps(), health.nowMillis(st.catalog.db), force != 0) catch
            return @intFromEnum(err(.internal, "da_update_check_json: no se pudo guardar el resultado de la comprobación"));
    }
    return updateStateOut(st, out, "da_update_check_json");
}

/// Descarga y verificación (huella SHA-256 y firma) de la última versión.
/// Los fallos de la descarga quedan en `download_error` del estado.
pub export fn da_update_download_json(handle: ?*anyopaque, out_json: ?*?[*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_update_download_json: null core handle"));
    const out = out_json orelse return @intFromEnum(err(.invalid_arg, "da_update_download_json: null out"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    {
        st.update_mutex.lock();
        defer st.update_mutex.unlock();
        updater.download(st.arena.child_allocator, st.catalog.db, updateDeps(), updateDataDir(st)) catch
            return @intFromEnum(err(.internal, "da_update_download_json: no se pudo guardar el resultado de la descarga"));
    }
    return updateStateOut(st, out, "da_update_download_json");
}

/// Interruptor de Ajustes: 0 apaga la comprobación diaria.
pub export fn da_update_set_enabled(handle: ?*anyopaque, enabled: c_int) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_update_set_enabled: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    updater.setEnabled(st.catalog.db, enabled != 0) catch
        return @intFromEnum(err(.internal, "da_update_set_enabled: no se pudo guardar el ajuste"));
    return @intFromEnum(ok());
}

/// El clic del usuario: instalar lo preparado al cerrar (1) o no (0).
/// `apply`: 0 = no instalar; 1 = instalar (solo si la firma es verificable
/// del editor esperado); 2 = instalar aceptando «sin firma verificable»
/// (T12 M3: la cabina solo lo manda tras decírselo al usuario).
pub export fn da_update_set_apply_on_exit(handle: ?*anyopaque, apply: c_int) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_update_set_apply_on_exit: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const choice: updater.ApplyChoice = switch (apply) {
        0 => .no,
        1 => .si,
        2 => .si_sin_firma_verificable,
        else => return @intFromEnum(err(.invalid_arg, "da_update_set_apply_on_exit: apply debe ser 0, 1 o 2")),
    };
    st.update_mutex.lock();
    defer st.update_mutex.unlock();
    updater.setApplyOnExit(st.arena.child_allocator, st.catalog.db, choice) catch |e| return switch (e) {
        error.NothingStaged => @intFromEnum(err(.invalid_arg, "da_update_set_apply_on_exit: no hay ninguna actualización descargada")),
        error.UnverifiedConsentRequired => @intFromEnum(err(.invalid_state, "da_update_set_apply_on_exit: la actualización no tiene firma verificable del editor; instalarla exige aceptarlo expresamente («sin firma verificable»)")),
        else => @intFromEnum(err(.internal, "da_update_set_apply_on_exit: no se pudo guardar el ajuste")),
    };
    return @intFromEnum(ok());
}

/// Lo pide el host al cerrar: `{"apply":bool,"path":str|null,"reason":str}`.
/// Solo da ruta si hay algo preparado, aceptado, más nuevo, con la misma
/// huella que al descargarlo y sin ninguna orden en curso.
pub export fn da_update_pending_apply_json(handle: ?*anyopaque, out_json: ?*?[*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_update_pending_apply_json: null core handle"));
    const out = out_json orelse return @intFromEnum(err(.invalid_arg, "da_update_pending_apply_json: null out"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    const busy = ordersInFlight(st) catch
        return @intFromEnum(err(.internal, "da_update_pending_apply_json: no se pudo comprobar si hay órdenes en curso"));
    st.update_mutex.lock();
    defer st.update_mutex.unlock();
    const body = updater.pendingApply(aa, st.catalog.db, busy) catch
        return @intFromEnum(err(.internal, "da_update_pending_apply_json: no se pudo leer la actualización preparada"));
    defer aa.free(body);
    out.* = ownedCStr(body) orelse return @intFromEnum(err(.oom, "OOM"));
    return @intFromEnum(ok());
}

const UpdateTestNet = struct {
    api_calls: usize = 0,
    fn fetch(ctx: ?*anyopaque, a: std.mem.Allocator, _: []const u8, kind: updater.FetchKind, _: usize) anyerror!updater.Response {
        const self: *UpdateTestNet = @ptrCast(@alignCast(ctx.?));
        if (kind == .api) self.api_calls += 1;
        return .{ .status = 404, .body = try a.dupe(u8, "{\"message\":\"Not Found\"}") };
    }
};

fn updateTestJson(handle: ?*anyopaque, comptime f: anytype, args: anytype) !std.json.Parsed(std.json.Value) {
    var out: ?[*:0]const u8 = null;
    try std.testing.expectEqual(@as(c_int, 0), @call(.auto, f, .{handle} ++ args ++ .{&out}));
    defer da_string_free(@constCast(out.?));
    return std.json.parseFromSlice(std.json.Value, std.testing.allocator, std.mem.span(out.?), .{});
}

test "T5 update: C-ABI de estado, comprobación, interruptor y descarga sin carpeta" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    var net = UpdateTestNet{};
    update_test_deps = .{ .ctx = &net, .fetch = UpdateTestNet.fetch, .verify = updateNoVerify };
    defer update_test_deps = null;
    {
        var st = try updateTestJson(handle, da_update_state_json, .{});
        defer st.deinit();
        try std.testing.expectEqualStrings("nunca", st.value.object.get("status").?.string);
        try std.testing.expectEqualStrings(@import("root.zig").VERSION, st.value.object.get("current").?.string);
        try std.testing.expect(st.value.object.get("enabled").?.bool);
    }
    {
        var st = try updateTestJson(handle, da_update_check_json, .{@as(c_int, 1)});
        defer st.deinit();
        try std.testing.expectEqualStrings("sin_publicaciones", st.value.object.get("status").?.string);
        try std.testing.expectEqual(@as(usize, 1), net.api_calls);
    }
    try std.testing.expectEqual(@as(c_int, 0), da_update_set_enabled(handle, 0));
    {
        var st = try updateTestJson(handle, da_update_check_json, .{@as(c_int, 1)});
        defer st.deinit();
        try std.testing.expectEqualStrings("desactivado", st.value.object.get("status").?.string);
        try std.testing.expectEqual(@as(usize, 1), net.api_calls);
    }
    try std.testing.expectEqual(@as(c_int, 0), da_update_set_enabled(handle, 1));
    {
        // En memoria no hay carpeta de datos: la descarga lo dice, no falla en silencio.
        var st = try updateTestJson(handle, da_update_download_json, .{});
        defer st.deinit();
        try std.testing.expect(std.mem.indexOf(u8, st.value.object.get("download_error").?.string, "carpeta de datos") != null);
    }
    try std.testing.expect(da_update_set_apply_on_exit(handle, 1) != 0);
    try std.testing.expectEqual(@as(c_int, 0), da_update_set_apply_on_exit(handle, 0));
    var out: ?[*:0]const u8 = null;
    try std.testing.expect(da_update_state_json(null, &out) != 0);
    try std.testing.expect(da_update_check_json(null, 0, &out) != 0);
    try std.testing.expect(da_update_download_json(null, &out) != 0);
    try std.testing.expect(da_update_set_enabled(null, 1) != 0);
    try std.testing.expect(da_update_set_apply_on_exit(null, 1) != 0);
    try std.testing.expect(da_update_set_apply_on_exit(handle, 3) != 0);
    try std.testing.expect(da_update_pending_apply_json(null, &out) != 0);
}

test "T5 update: pending_apply no da ruta con una orden en curso del motor" {
    const a = std.testing.allocator;
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle));
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var threaded = std.Io.Threaded.init(a, .{});
    defer threaded.deinit();
    const dir = try tmp.dir.realPathFileAlloc(threaded.io(), ".", a);
    defer a.free(dir);
    const path = try std.fs.path.join(a, &.{ dir, "DevAgents-Setup-v99.0.0.exe" });
    defer a.free(path);
    const bytes = "instalador preparado";
    try std.Io.Dir.cwd().writeFile(threaded.io(), .{ .sub_path = path, .data = bytes });
    const hex = updater.sha256Hex(bytes);
    var staged_buf: std.Io.Writer.Allocating = .init(a);
    defer staged_buf.deinit();
    var js: std.json.Stringify = .{ .writer = &staged_buf.writer, .options = .{} };
    try js.write(.{ .version = "99.0.0", .path = path, .sha256 = hex[0..], .signature = "sin_firma" });
    // T12 M3: preparada sin firma verificable y aceptada expresamente como tal.
    const q = try st.catalog.db.prepare("INSERT INTO settings(key,value) VALUES('update_staged_json',?),('update_apply_on_exit','1'),('update_apply_unverified','1')");
    defer st.catalog.db.finalize(q);
    try db.bindText(q, 1, staged_buf.written());
    try std.testing.expectEqual(db.c.SQLITE_DONE, db.c.sqlite3_step(q));

    try st.db_conn.exec("INSERT INTO orders (id, project_id, user_prompt, status, created_at) VALUES (51, 'p', 'x', 'running', 1)");
    {
        var p = try updateTestJson(handle, da_update_pending_apply_json, .{});
        defer p.deinit();
        try std.testing.expect(!p.value.object.get("apply").?.bool);
        try std.testing.expect(p.value.object.get("path").? == .null);
        try std.testing.expect(std.mem.indexOf(u8, p.value.object.get("reason").?.string, "órdenes en curso") != null);
    }
    try st.db_conn.exec("UPDATE orders SET status = 'awaiting_approval' WHERE id = 51");
    {
        var p = try updateTestJson(handle, da_update_pending_apply_json, .{});
        defer p.deinit();
        try std.testing.expect(!p.value.object.get("apply").?.bool);
    }
    try st.db_conn.exec("UPDATE orders SET status = 'done' WHERE id = 51");
    var p = try updateTestJson(handle, da_update_pending_apply_json, .{});
    defer p.deinit();
    try std.testing.expect(p.value.object.get("apply").?.bool);
    try std.testing.expectEqualStrings(path, p.value.object.get("path").?.string);
}

/// QA-B H11 (14-nov): ¿`da_core_init` lanza la detección de agentes externos
/// en segundo plano? La cabina sí (arranque en frío sin esperar). El servidor
/// MCP la apaga antes de iniciar el núcleo: la detección ejecuta las CLIs
/// instaladas (unos 13 s medidos) y `da_core_shutdown` tiene que esperarla,
/// así que cerrar la entrada del MCP tardaba 13-16 s en vez de < 1 s. Lo que
/// el MCP necesite del catálogo lo carga perezoso (`externalCatalog`, caché).
pub var startup_external_detection: bool = true;

fn externalDetectionThread(st: *CoreState) void {
    st.external_mutex.lock();
    defer st.external_mutex.unlock();
    const body = externalCatalog(st, st.arena.child_allocator, true) catch |e| {
        std.debug.print("external CLI discovery failed: {s}; retry agents_external_refresh\n", .{@errorName(e)});
        return;
    };
    st.arena.child_allocator.free(body);
}

/// Carga perezosa del catálogo de agentes para Directo en Automático.
fn directCatalogLoad(ctx: ?*anyopaque, a: std.mem.Allocator) ?[]u8 {
    const st: *CoreState = @ptrCast(@alignCast(ctx orelse return null));
    if (builtin.is_test and st.external_capture_fn == null) return null;
    st.external_mutex.lock();
    defer st.external_mutex.unlock();
    return externalCatalog(st, a, false) catch null;
}

fn externalCatalog(st: *CoreState, a: std.mem.Allocator, force: bool) ![]u8 {
    if (!force) {
        if (try external_registry.cached(a, st.catalog.db, health.nowSeconds(st.catalog.db))) |text| {
            defer a.free(text);
            return external_registry.withOptions(a, st.catalog.db, text);
        }
    }
    const raw = try external_registry.refresh(a, st.catalog.db, st.external_capture_fn, st.external_resolve_fn);
    defer a.free(raw);
    return external_registry.withOptions(a, st.catalog.db, raw);
}

/// E5.55: explicit quota-free refresh; additive C ABI.
fn configurationJson(st: *CoreState, a: std.mem.Allocator) ![]u8 {
    var selection = try captureModelSelection(st, a);
    defer selection.deinit(a);
    // Avisos previos al envío: última detección conocida (ver `lastKnown`).
    const external = (try external_registry.lastKnown(a, st.catalog.db, health.nowSeconds(st.catalog.db))) orelse try a.dupe(u8, "[]");
    defer a.free(external);
    const mode_text = try external_registry.readSetting(a, st.catalog.db, "governance_mode");
    defer a.free(mode_text);
    st.perm_mutex.lock();
    const explicit_audit = st.audit_forced_provider != null;
    const deterministic = st.plan_deterministic;
    st.perm_mutex.unlock();
    const roles = [_]@import("order_preflight.zig").Role{
        .{ .role = "planificador", .provider = selection.provider, .model = selection.model },
        .{ .role = "ejecutor", .provider = selection.exec_provider, .model = selection.exec_model },
        .{ .role = "auditor", .provider = if (explicit_audit) selection.audit_provider else null, .model = if (explicit_audit) selection.audit_model else null },
    };
    const conflicts = try @import("order_preflight.zig").check(a, st.catalog.db, model_router.GovernanceMode.parse(mode_text), &roles, external, st.db_conn);
    defer a.free(conflicts);
    const budget = spend_budget.estado(st.catalog.db);
    var paid_roles = [_]bool{ false, false, false };
    for (roles, 0..) |role, i| {
        if (role.provider != null and role.model != null and !external_agents.isAgentProvider(role.provider.?))
            paid_roles[i] = !model_router.catalogModelIsFree(st.catalog.db, role.provider.?, role.model.?);
    }
    return std.json.Stringify.valueAlloc(a, .{ .budget = .{ .authorized = budget.autorizadas, .spent = budget.consumidas, .remaining = budget.restantes() }, .paid_roles = paid_roles, .allowed = @import("order_preflight.zig").allowed(conflicts), .issues = conflicts, .deterministic = deterministic, .message = if (deterministic) "Determinista: si el modelo falla, la orden falla" else "Respaldo: se prueba el siguiente candidato elegible distinto", .subscription_notice = "La suscripcion consume cuota; no cobra por llamada" }, .{});
}

pub export fn da_order_preflight_json(handle: ?*anyopaque, out_json: ?*?[*:0]const u8) callconv(.c) c_int {
    const st: *CoreState = @ptrCast(@alignCast(handle orelse return @intFromEnum(err(.invalid_arg, "null core"))));
    const out = out_json orelse return @intFromEnum(err(.invalid_arg, "null out"));
    const a = st.arena.child_allocator;
    const body = configurationJson(st, a) catch |e| return @intFromEnum(err(.internal, @errorName(e)));
    defer a.free(body);
    out.* = ownedCStr(body) orelse return @intFromEnum(err(.oom, "OOM"));
    return @intFromEnum(ok());
}

fn rejectInvalidConfiguration(st: *CoreState) ?c_int {
    const a = st.arena.child_allocator;
    const text = configurationJson(st, a) catch |e| return @intFromEnum(err(.internal, @errorName(e)));
    defer a.free(text);
    var p = std.json.parseFromSlice(std.json.Value, a, text, .{}) catch return @intFromEnum(err(.internal, "configuration JSON invalid"));
    defer p.deinit();
    const conflicts = p.value.object.get("issues").?.array.items;
    const o = for (conflicts) |conflict| {
        const object = conflict.object;
        if (object.get("severity")) |severity| {
            if (severity == .string and std.mem.eql(u8, severity.string, "warn")) continue;
        }
        break object;
    } else return null;
    if (std.mem.eql(u8, o.get("cause").?.string, "paid_budget_exhausted")) {
        const reason = spend_budget.motivoDenegacion(a, o.get("provider").?.string, o.get("model").?.string, spend_budget.estado(st.catalog.db)) catch return @intFromEnum(err(.oom, "OOM"));
        defer a.free(reason);
        return @intFromEnum(err(.invalid_state, reason));
    }
    const msg = std.fmt.allocPrint(a, "{s}: {s} {s}/{s}: {s}. {s}", .{ o.get("cause").?.string, o.get("role").?.string, o.get("provider").?.string, o.get("model").?.string, o.get("reason").?.string, o.get("action").?.string }) catch return @intFromEnum(err(.oom, "OOM"));
    defer a.free(msg);
    return @intFromEnum(err(.invalid_state, msg));
}

pub export fn da_external_agents_refresh(handle: ?*anyopaque, out_json: ?*?[*:0]const u8) callconv(.c) c_int {
    const st: *CoreState = @ptrCast(@alignCast(handle orelse return @intFromEnum(err(.invalid_arg, "null core"))));
    const out = out_json orelse return @intFromEnum(err(.invalid_arg, "null out"));
    const aa = st.arena.child_allocator;
    // QA primerizo (11-nov): la detección (lanzar cada CLI) corre SIN el
    // candado; solo leer las rutas y guardar el resultado lo toman.
    const agent_paths = blk: {
        st.external_mutex.lock();
        defer st.external_mutex.unlock();
        break :blk external_registry.readSetting(aa, st.catalog.db, "external_agent_paths") catch |e| return @intFromEnum(err(.internal, @import("external_cli_policy.zig").rejectionReason(e)));
    };
    defer aa.free(agent_paths);
    const raw = external_registry.detectBody(aa, agent_paths, st.external_capture_fn, st.external_resolve_fn) catch |e| return @intFromEnum(err(.internal, @import("external_cli_policy.zig").rejectionReason(e)));
    defer aa.free(raw);
    st.external_mutex.lock();
    defer st.external_mutex.unlock();
    external_registry.store(st.catalog.db, raw, health.nowSeconds(st.catalog.db)) catch |e| return @intFromEnum(err(.internal, @import("external_cli_policy.zig").rejectionReason(e)));
    const body = external_registry.withOptions(aa, st.catalog.db, raw) catch |e| return @intFromEnum(err(.internal, @import("external_cli_policy.zig").rejectionReason(e)));
    defer aa.free(body);
    out.* = ownedCStr(body) orelse return @intFromEnum(err(.oom, "OOM"));
    return @intFromEnum(ok());
}

pub export fn da_external_paths_json(handle: ?*anyopaque, out_json: ?*?[*:0]const u8) callconv(.c) c_int {
    const st: *CoreState = @ptrCast(@alignCast(handle orelse return @intFromEnum(err(.invalid_arg, "null core"))));
    const out = out_json orelse return @intFromEnum(err(.invalid_arg, "null out"));
    st.external_mutex.lock();
    defer st.external_mutex.unlock();
    const body = external_registry.readSetting(st.arena.child_allocator, st.catalog.db, "external_agent_paths") catch return @intFromEnum(err(.internal, "external paths read failed"));
    defer st.arena.child_allocator.free(body);
    out.* = ownedCStr(body) orelse return @intFromEnum(err(.oom, "OOM"));
    return @intFromEnum(ok());
}

/// H7: la proposición de rutas de agentes externos por MCP solo es
/// válida si es un subconjunto exacto de las ya registradas por la cabina
/// (quitar entradas o mantenerlas con su valor idéntico). Registrar una ruta
/// nueva o cambiar una existente lo suelta.
fn mcpExternalPathsSubset(allocator: std.mem.Allocator, current_text: ?[]const u8, proposed_text: []const u8) bool {
    const cur_parsed = std.json.parseFromSlice(
        std.json.Value,
        allocator,
        current_text orelse "null",
        .{},
    ) catch return false;
    defer cur_parsed.deinit();
    const pro_parsed = std.json.parseFromSlice(std.json.Value, allocator, proposed_text, .{}) catch return false;
    defer pro_parsed.deinit();
    const pro = pro_parsed.value;
    if (pro != .object) return false;
    if (cur_parsed.value != .object) return pro.object.count() == 0;
    var it = pro.object.iterator();
    while (it.next()) |kv| {
        const existing = cur_parsed.value.object.get(kv.key_ptr.*);
        if (existing == null) return false;
        const same = switch (kv.value_ptr.*) {
            .string => |s| existing.? == .string and std.mem.eql(u8, s, existing.?.string),
            else => false,
        };
        if (!same) return false;
    }
    return true;
}

pub export fn da_external_paths_set(handle: ?*anyopaque, json: ?[*:0]const u8) callconv(.c) c_int {
    const st: *CoreState = @ptrCast(@alignCast(handle orelse return @intFromEnum(err(.invalid_arg, "null core"))));
    const text = json orelse return @intFromEnum(err(.invalid_arg, "null json"));
    st.external_mutex.lock();
    defer st.external_mutex.unlock();
    // H7: por MCP solo se aceptan reformas que quitan o conservan
    // (sin re-verificación de ejecutables, que ya la hizo la cabina); el
    // registro o cambio de rutas requiere la cabina.
    if (st.mcp_surface) {
        var current_copy: ?[]u8 = null;
        var current_text: ?[]const u8 = null;
        if (st.catalog.db.prepare("SELECT value FROM settings WHERE key='external_agent_paths'")) |s| {
            defer st.catalog.db.finalize(s);
            if (db.c.sqlite3_step(s) == db.c.SQLITE_ROW) {
                const ptr = db.c.sqlite3_column_text(s, 0);
                if (ptr != null) {
                    const nb: usize = @intCast(db.c.sqlite3_column_bytes(s, 0));
                    const copy = st.arena.child_allocator.alloc(u8, nb) catch
                        return @intFromEnum(err(.oom, "da_external_paths_set: OOM"));
                    @memcpy(copy, ptr[0..nb]);
                    current_copy = copy;
                    current_text = copy;
                }
            }
        } else |_| {}
        const proposed = std.mem.span(text);
        if (proposed.len > 32768 or !mcpExternalPathsSubset(st.arena.child_allocator, current_text, proposed)) {
            if (current_copy) |c| st.arena.child_allocator.free(c);
            return @intFromEnum(err(.invalid_state, "da_external_paths_set: un cliente MCP solo puede quitar rutas de agentes externos o conservar las ya registradas; registrar o cambiar una ruta requiere la cabina"));
        }
        if (current_copy) |c| st.arena.child_allocator.free(c);
        // Persistencia literal de la reforma (subset del vigente): NO se pasa
        // por external_registry.setPaths porque re-verificaría cada binario
        // vía CLI, y esas rutas ya fueron verificadas por la cabina.
        // H7 r4: el UPDATE y la invalidación de la cache van en la
        // MISMA transacción; si el DELETE fallara, un rollback deja la caché
        // coherente con las rutas antiguas en vez de servir rutas ya no
        // registradas como vigentes.
        st.catalog.db.exec("BEGIN IMMEDIATE") catch
            return @intFromEnum(err(.internal, "da_external_paths_set: BEGIN falló"));
        var committed = false;
        defer if (!committed) st.catalog.db.exec("ROLLBACK") catch |e| std.log.err("external paths rollback: {s}", .{@errorName(e)});
        {
            const q = st.catalog.db.prepare("UPDATE settings SET value=? WHERE key='external_agent_paths'") catch
                return @intFromEnum(err(.internal, "da_external_paths_set: prepare falló"));
            defer st.catalog.db.finalize(q);
            db.bindText(q, 1, proposed) catch
                return @intFromEnum(err(.internal, "da_external_paths_set: bind falló"));
            if (db.c.sqlite3_step(q) != db.c.SQLITE_DONE)
                return @intFromEnum(err(.internal, "da_external_paths_set: no se pudo guardar"));
        }
        st.catalog.db.exec("DELETE FROM external_agent_cache") catch
            return @intFromEnum(err(.internal, "da_external_paths_set: no se pudo invalidar la cache"));
        st.catalog.db.exec("COMMIT") catch
            return @intFromEnum(err(.internal, "da_external_paths_set: no se pudo confirmar"));
        committed = true;
        return @intFromEnum(ok());
    }
    external_registry.setPaths(st.arena.child_allocator, st.catalog.db, std.mem.span(text)) catch |e| return @intFromEnum(err(.invalid_arg, @import("external_cli_policy.zig").rejectionReason(e)));
    return @intFromEnum(ok());
}

pub export fn da_external_model_options_set(handle: ?*anyopaque, json: ?[*:0]const u8) callconv(.c) c_int {
    const st: *CoreState = @ptrCast(@alignCast(handle orelse return @intFromEnum(err(.invalid_arg, "null core"))));
    const text = json orelse return @intFromEnum(err(.invalid_arg, "null json"));
    const aa = st.arena.child_allocator;
    st.external_mutex.lock();
    defer st.external_mutex.unlock();
    const cat = externalCatalog(st, aa, false) catch return @intFromEnum(err(.internal, "catalog unavailable"));
    defer aa.free(cat);
    external_registry.setOptions(aa, st.catalog.db, std.mem.span(text), cat) catch return @intFromEnum(err(.invalid_arg, "reasoning effort unsupported by selected model"));
    return @intFromEnum(ok());
}

/// (b): estado del primer arranque, guardado en el motor y no en el
/// almacenamiento del navegador interno (que cambia con cada compilación de
/// depuración o carpeta de datos nueva, y el tutorial reaparecía aunque ya
/// hubiera claves y conversaciones). `{"done":bool,"has_usage":bool}`:
/// `has_usage` = hay una clave activa, alguna orden o una CLI externa con sesión
/// de suscripción en la última detección guardada. Como en las IDE de
/// referencia, la cabina solo enseña el tutorial si nada de eso es cierto.
pub export fn da_onboarding_json(handle: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_onboarding_json: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const done = blk: {
        const stmt = st.catalog.db.prepare("SELECT value FROM settings WHERE key='ui_onboarded'") catch
            return @intFromEnum(err(.internal, "da_onboarding_json: no se pudo leer el ajuste"));
        defer st.catalog.db.finalize(stmt);
        const rc = db.c.sqlite3_step(stmt);
        if (rc == db.c.SQLITE_DONE) break :blk false;
        if (rc != db.c.SQLITE_ROW) return @intFromEnum(err(.internal, "da_onboarding_json: no se pudo leer el ajuste"));
        break :blk std.mem.eql(u8, approvalColText(stmt, 0), "true");
    };
    const keys = blk: {
        const stmt = st.catalog.db.prepare("SELECT EXISTS(SELECT 1 FROM api_keys WHERE status = 'active')") catch
            return @intFromEnum(err(.internal, "da_onboarding_json: no se pudieron contar las claves"));
        defer st.catalog.db.finalize(stmt);
        if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) return @intFromEnum(err(.internal, "da_onboarding_json: no se pudieron contar las claves"));
        break :blk db.c.sqlite3_column_int64(stmt, 0) != 0;
    };
    const orders = blk: {
        const stmt = st.db_conn.prepare("SELECT EXISTS(SELECT 1 FROM orders)") catch
            return @intFromEnum(err(.internal, "da_onboarding_json: no se pudieron contar las órdenes"));
        defer st.db_conn.finalize(stmt);
        if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) return @intFromEnum(err(.internal, "da_onboarding_json: no se pudieron contar las órdenes"));
        break :blk db.c.sqlite3_column_int64(stmt, 0) != 0;
    };
    // (b): «CLIs con sesión». Esta llamada va por el carril rápido
    // al arrancar, así que no lanza ninguna CLI ni toca el PATH: lee la última
    // detección guardada (`external_agent_cache`, la que escribe
    // external_registry.store, sin TTL como `lastKnown`). Cuenta solo
    // `session == "suscripcion"`, lo mismo que la cabina llama «listo»
    // (onboarding_help.ts describeAgents); `api_key` cobraría por API y
    // `sin_sesion`/`desconocida` no son sesión. Un JSON dañado cuenta como nada.
    const cli_session = blk: {
        const stmt = st.catalog.db.prepare(
            \\SELECT EXISTS(SELECT 1 FROM external_agent_cache c, json_each(
            \\  CASE WHEN json_valid(c.payload_json) THEN
            \\    CASE WHEN json_type(c.payload_json) = 'array' THEN c.payload_json ELSE '[]' END
            \\  ELSE '[]' END) a
            \\  WHERE c.id = 1 AND a.type = 'object' AND json_extract(a.value, '$.session') = 'suscripcion')
        ) catch
            return @intFromEnum(err(.internal, "da_onboarding_json: no se pudo leer la detección de CLIs"));
        defer st.catalog.db.finalize(stmt);
        if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) return @intFromEnum(err(.internal, "da_onboarding_json: no se pudo leer la detección de CLIs"));
        break :blk db.c.sqlite3_column_int64(stmt, 0) != 0;
    };
    const text: [:0]const u8 = switch ((@as(u2, @intFromBool(done)) << 1) | @intFromBool(keys or orders or cli_session)) {
        0 => "{\"done\":false,\"has_usage\":false}",
        1 => "{\"done\":false,\"has_usage\":true}",
        2 => "{\"done\":true,\"has_usage\":false}",
        3 => "{\"done\":true,\"has_usage\":true}",
    };
    out_json.* = ownedCStr(text) orelse return @intFromEnum(err(.oom, "da_onboarding_json: OOM"));
    return @intFromEnum(ok());
}

/// (b): el tutorial se terminó, se saltó o ya no hace falta.
pub export fn da_onboarding_done(handle: ?*anyopaque) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_onboarding_done: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const stmt = st.catalog.db.prepare(
        \\INSERT INTO settings (key, value) VALUES ('ui_onboarded', 'true')
        \\ON CONFLICT(key) DO UPDATE SET value=excluded.value
    ) catch return @intFromEnum(err(.internal, "da_onboarding_done: prepare falló"));
    defer st.catalog.db.finalize(stmt);
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE)
        return @intFromEnum(err(.internal, "da_onboarding_done: no se pudo guardar"));
    return @intFromEnum(ok());
}

test "CK-PUB-018: el primer arranque se guarda en el motor y cuenta el uso previo" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    var json: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_onboarding_json(handle, &json));
    try std.testing.expectEqualStrings("{\"done\":false,\"has_usage\":false}", std.mem.span(json));
    da_string_free(json);
    // CLIs detectadas sin sesión de suscripción (o con un JSON dañado) no son uso.
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    for ([_][:0]const u8{
        "INSERT INTO external_agent_cache(id,payload_json,detected_at) VALUES(1,'[{\"cli\":\"codex\",\"session\":\"sin_sesion\"},{\"cli\":\"gemini\",\"session\":\"desconocida\"},{\"cli\":\"claude-code\",\"session\":\"api_key\"},\"suscripcion\"]',1000)",
        "UPDATE external_agent_cache SET payload_json='no es json' WHERE id=1",
        "UPDATE external_agent_cache SET payload_json='{\"session\":\"suscripcion\"}' WHERE id=1",
    }) |sql| {
        try st.catalog.db.exec(sql);
        try std.testing.expectEqual(@as(c_int, 0), da_onboarding_json(handle, &json));
        try std.testing.expectEqualStrings("{\"done\":false,\"has_usage\":false}", std.mem.span(json));
        da_string_free(json);
    }
    // Una CLI con sesión iniciada en la última detección guardada sí lo es.
    try st.catalog.db.exec("UPDATE external_agent_cache SET payload_json='[{\"cli\":\"codex\",\"session\":\"sin_sesion\"},{\"cli\":\"claude-code\",\"session\":\"suscripcion\"}]' WHERE id=1");
    try std.testing.expectEqual(@as(c_int, 0), da_onboarding_json(handle, &json));
    try std.testing.expectEqualStrings("{\"done\":false,\"has_usage\":true}", std.mem.span(json));
    da_string_free(json);
    try st.catalog.db.exec("DELETE FROM external_agent_cache");
    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "hola", "test", null, &order));
    try std.testing.expectEqual(@as(c_int, 0), da_onboarding_json(handle, &json));
    try std.testing.expectEqualStrings("{\"done\":false,\"has_usage\":true}", std.mem.span(json));
    da_string_free(json);
    try std.testing.expectEqual(@as(c_int, 0), da_onboarding_done(handle));
    try std.testing.expectEqual(@as(c_int, 0), da_onboarding_json(handle, &json));
    try std.testing.expectEqualStrings("{\"done\":true,\"has_usage\":true}", std.mem.span(json));
    da_string_free(json);
}

/// E5.08: límites vigentes de los agentes externos como JSON
/// {task_timeout_ms, task_max_turns, order_timeout_ms, order_max_turns}.
/// El caller libera con da_string_free.
pub export fn da_external_limits_json(handle: ?*anyopaque, out_json: ?*?[*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_external_limits_json: null core handle"));
    const out = out_json orelse return @intFromEnum(err(.invalid_arg, "da_external_limits_json: null out"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    st.perm_mutex.lock();
    const lim = st.external_limits;
    st.perm_mutex.unlock();
    const limits_json = lim.toJson(aa) catch return @intFromEnum(err(.oom, "OOM"));
    defer aa.free(limits_json);
    // 10-nov (USUARIO-NUEVO A3): la herencia de instrucciones personales viaja
    // con los ajustes de agentes externos (Configuración › Agentes externos).
    // Un valor ilegible se dice como tal: null, nunca un «false» inventado.
    const inherit: ?bool = @import("external_context.zig").load(st.catalog.db) catch null;
    const body = std.fmt.allocPrint(aa, "{s},\"inherit_personal_context\":{s}}}", .{ limits_json[0 .. limits_json.len - 1], if (inherit) |v| (if (v) "true" else "false") else "null" }) catch return @intFromEnum(err(.oom, "OOM"));
    defer aa.free(body);
    out.* = ownedCStr(body) orelse return @intFromEnum(err(.oom, "OOM"));
    return @intFromEnum(ok());
}

/// 10-nov (A3): guarda `external_agent_inherit_personal_context`. Activarla
/// pasa las instrucciones personales del usuario al agente: por MCP solo se
/// puede apagar; encenderla exige la cabina.
fn setInheritPersonalContext(st: *CoreState, value: bool) ?c_int {
    if (value and st.mcp_surface)
        return @intFromEnum(err(.invalid_state, "da_external_limits_set: un cliente MCP no puede activar la herencia de instrucciones personales; requiere la cabina"));
    const stmt = st.catalog.db.prepare(
        \\INSERT INTO settings (key, value) VALUES ('external_agent_inherit_personal_context', ?)
        \\ON CONFLICT(key) DO UPDATE SET value=excluded.value
    ) catch return @intFromEnum(err(.internal, "da_external_limits_set: prepare falló"));
    defer st.catalog.db.finalize(stmt);
    db.bindText(stmt, 1, if (value) "true" else "false") catch
        return @intFromEnum(err(.internal, "da_external_limits_set: bind falló"));
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE)
        return @intFromEnum(err(.internal, "da_external_limits_set: no se pudo guardar la herencia"));
    return null;
}

/// E5.08: fija los límites de los agentes externos desde un JSON parcial
/// (claves ausentes conservan el valor vigente; 0 = sin tope en ese eje).
/// Persiste en settings.external_agent_limits del catálogo.
/// H7: endurecer un tope numérico es bajarlo o añadirlo donde no
/// había (0 = sin tope). Subir o quitar un tope vigente lo suelta.
/// R5 (el segundo auditor lote AH, P2): un eje ya ilimitado (0) que no cambia también
/// endurece, porque la decisión combina todos los ejes y ese eje no relaja nada.
fn mcpLimitHardens(comptime T: type, current: T, next: T) bool {
    return (current == 0 and next == 0) or (current == 0 and next > 0) or (current > 0 and next > 0 and next <= current);
}

pub export fn da_external_limits_set(handle: ?*anyopaque, json: ?[*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_external_limits_set: null core handle"));
    const text = json orelse return @intFromEnum(err(.invalid_arg, "da_external_limits_set: null json"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    {
        var parsed = std.json.parseFromSlice(std.json.Value, aa, std.mem.span(text), .{}) catch
            return @intFromEnum(err(.invalid_arg, "da_external_limits_set: JSON inválido"));
        defer parsed.deinit();
        if (parsed.value == .object) if (parsed.value.object.get("inherit_personal_context")) |v| {
            if (v != .bool) return @intFromEnum(err(.invalid_arg, "da_external_limits_set: inherit_personal_context debe ser true o false"));
            if (setInheritPersonalContext(st, v.bool)) |code| return code;
        };
    }
    st.perm_mutex.lock();
    const merged = external_agents.Limits.fromJson(st.external_limits, aa, std.mem.span(text)) catch {
        st.perm_mutex.unlock();
        return @intFromEnum(err(.invalid_arg, "da_external_limits_set: JSON inválido"));
    };
    // H7: por MCP cada eje de límite solo puede endurecerse (bajar
    // o añadir tope donde no hay); subirlo o poner 0 = sin tope exige la cabina.
    if (st.mcp_surface) {
        const cur = st.external_limits;
        const hardens = mcpLimitHardens(u64, cur.task_timeout_ms, merged.task_timeout_ms) and
            mcpLimitHardens(u32, cur.task_max_turns, merged.task_max_turns) and
            mcpLimitHardens(u64, cur.order_timeout_ms, merged.order_timeout_ms) and
            mcpLimitHardens(u32, cur.order_max_turns, merged.order_max_turns);
        if (!hardens) {
            st.perm_mutex.unlock();
            return @intFromEnum(err(.invalid_state, "da_external_limits_set: un cliente MCP solo puede fijar límites más bajos o añadir topes; subir un tope o poner 0 (sin tope) requiere la cabina"));
        }
    }
    st.external_limits = merged;
    st.perm_mutex.unlock();
    const body = merged.toJson(aa) catch return @intFromEnum(err(.oom, "OOM"));
    defer aa.free(body);
    const stmt = st.catalog.db.prepare(
        \\INSERT INTO settings (key, value) VALUES ('external_agent_limits', ?)
        \\ON CONFLICT(key) DO UPDATE SET value=excluded.value
    ) catch return @intFromEnum(err(.internal, "da_external_limits_set: prepare falló"));
    defer st.catalog.db.finalize(stmt);
    db.bindText(stmt, 1, body) catch
        return @intFromEnum(err(.internal, "da_external_limits_set: bind falló"));
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE)
        return @intFromEnum(err(.internal, "da_external_limits_set: no se pudo guardar"));
    return @intFromEnum(ok());
}

/// E5.15 — config de la capa semantica. {enabled, provider, model} en
/// settings.embeddings_config del catalogo. Habilitarla AUTORIZA a mandar
/// chunks del repo (troceados, tope 1200 chars, solo el pool top-BM25) al
/// endpoint de embeddings del proveedor elegido — por eso es opt-in
/// explicito y nunca default.
pub export fn da_embeddings_config_json(handle: ?*anyopaque, out_json: ?*?[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_embeddings_config_json: null core handle"));
    const out = out_json orelse return @intFromEnum(err(.invalid_arg, "da_embeddings_config_json: null out"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    var body: []const u8 = "{\"enabled\":false,\"provider\":\"\",\"model\":\"\"}";
    var owned: ?[]u8 = null;
    defer if (owned) |b| aa.free(b);
    if (st.catalog.db.prepare("SELECT value FROM settings WHERE key='embeddings_config'")) |s| {
        defer st.catalog.db.finalize(s);
        if (db.c.sqlite3_step(s) == db.c.SQLITE_ROW) {
            const ptr = db.c.sqlite3_column_text(s, 0);
            if (ptr != null) {
                owned = aa.dupe(u8, ptr[0..std.mem.len(ptr)]) catch null;
                if (owned != null) body = owned.?;
            }
        }
    } else |_| {}
    out.* = ownedCStr(body) orelse return @intFromEnum(err(.oom, "OOM"));
    return @intFromEnum(ok());
}

/// E5.15: fija la config semantica desde JSON parcial {enabled?, provider?,
/// model?} — las claves ausentes conservan el valor vigente. Persiste en
/// settings.embeddings_config. Respondera con la config fusionada.
pub export fn da_embeddings_config_set(handle: ?*anyopaque, json: ?[*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_embeddings_config_set: null core handle"));
    const text = json orelse return @intFromEnum(err(.invalid_arg, "da_embeddings_config_set: null json"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    var enabled = false;
    var prov: []const u8 = "";
    var model: []const u8 = "";
    // merge sobre la config vigente
    if (st.catalog.db.prepare("SELECT value FROM settings WHERE key='embeddings_config'")) |s| {
        defer st.catalog.db.finalize(s);
        if (db.c.sqlite3_step(s) == db.c.SQLITE_ROW) {
            const ptr = db.c.sqlite3_column_text(s, 0);
            if (ptr != null) {
                var pj = std.json.parseFromSlice(std.json.Value, aa, ptr[0..std.mem.len(ptr)], .{}) catch null;
                defer if (pj) |*p| p.deinit();
                if (pj != null and pj.?.value == .object) {
                    const o = pj.?.value.object;
                    if (o.get("enabled")) |ev| {
                        if (ev == .bool) enabled = ev.bool;
                    }
                    if (o.get("provider")) |pv| {
                        if (pv == .string) prov = aa.dupe(u8, pv.string) catch prov;
                    }
                    if (o.get("model")) |mv| {
                        if (mv == .string) model = aa.dupe(u8, mv.string) catch model;
                    }
                }
            }
        }
    } else |_| {}

    var pj = std.json.parseFromSlice(std.json.Value, aa, std.mem.span(text), .{}) catch
        return @intFromEnum(err(.invalid_arg, "da_embeddings_config_set: JSON invalido"));
    defer pj.deinit();
    if (pj.value != .object)
        return @intFromEnum(err(.invalid_arg, "da_embeddings_config_set: args debe ser objeto"));
    const o = pj.value.object;
    if (o.get("enabled")) |ev| {
        if (ev != .bool) return @intFromEnum(err(.invalid_arg, "enabled debe ser bool"));
        enabled = ev.bool;
    }
    if (o.get("provider")) |pv| {
        if (pv != .string or pv.string.len > 128) return @intFromEnum(err(.invalid_arg, "provider invalido"));
        prov = pv.string;
    }
    if (o.get("model")) |mv| {
        if (mv != .string or mv.string.len > 128) return @intFromEnum(err(.invalid_arg, "model invalido"));
        model = mv.string;
    }

    var buf: std.Io.Writer.Allocating = .init(aa);
    defer buf.deinit();
    var js: std.json.Stringify = .{ .writer = &buf.writer, .options = .{} };
    js.beginObject() catch return @intFromEnum(err(.oom, "OOM"));
    js.objectField("enabled") catch {};
    js.write(enabled) catch {};
    js.objectField("provider") catch {};
    js.write(prov) catch {};
    js.objectField("model") catch {};
    js.write(model) catch {};
    js.endObject() catch {};

    const stmt = st.catalog.db.prepare(
        \\INSERT INTO settings (key, value) VALUES ('embeddings_config', ?)
        \\ON CONFLICT(key) DO UPDATE SET value=excluded.value
    ) catch return @intFromEnum(err(.internal, "da_embeddings_config_set: prepare fallo"));
    defer st.catalog.db.finalize(stmt);
    db.bindText(stmt, 1, buf.written()) catch
        return @intFromEnum(err(.internal, "da_embeddings_config_set: bind fallo"));
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE)
        return @intFromEnum(err(.internal, "da_embeddings_config_set: no se pudo guardar"));
    return @intFromEnum(ok());
}

/// E5.15: alias del contexto compartido — la implementación (HTTP por lotes,
/// presupuesto por intento, reintento 429) vive en embedder_ctx.zig para que
/// herramientas sin CoreState (p.ej. bench_retrieval) usen la misma pieza.
const EmbedderCtx = embedder_ctx.EmbedderCtx;
const cloudEmbed = embedder_ctx.cloudEmbed;

/// Envoltura sobre embedder_ctx.resolve con la conexión y la ruta del
/// catálogo del CoreState. Mismas notas honestas estables.
fn resolveEmbedder(st: *CoreState, aa: std.mem.Allocator, out_ctx: **EmbedderCtx) ?[]const u8 {
    return embedder_ctx.resolve(st.catalog.db, st.catalog_path, aa, out_ctx);
}

/// E5.14 — `repo_search`: ranking BM25 (lexico) sobre los archivos rastreados
/// por git del repositorio. Entrada: {"query":string, "root?":string,
/// "max_results?":int}. Salida: {query_mode:"bm25", truncated, elapsed_ms,
/// files_seen, files_scanned, chunks_total, matches:[{path,line,snippet,
/// score}]}. `root` omitida = effectiveRoot. NO es busqueda semantica — la
/// capa opcional de embeddings (E5.15) se anuncia con su propia proveniencia.
pub export fn da_repo_search(
    handle: ?*anyopaque,
    query_json: [*:0]const u8,
    out_json: ?*?[*:0]u8,
) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_repo_search: null core handle"));
    const out = out_json orelse return @intFromEnum(err(.invalid_arg, "da_repo_search: null out"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    // Arena LOCAL por llamada: el corpus y el índice vectorial (~4KB por chunk
    // indexado) se cargan enteros aquí — en st.arena (persistente) cada
    // búsqueda hincharía el proceso hasta el shutdown.
    var arena = std.heap.ArenaAllocator.init(st.arena.child_allocator);
    defer arena.deinit();
    const aa = arena.allocator();

    var parsed = std.json.parseFromSlice(std.json.Value, aa, std.mem.span(query_json), .{}) catch
        return @intFromEnum(err(.invalid_arg, "da_repo_search: JSON invalido"));
    defer parsed.deinit();
    if (parsed.value != .object)
        return @intFromEnum(err(.invalid_arg, "da_repo_search: args debe ser objeto"));
    const obj = parsed.value.object;
    const q_v = obj.get("query") orelse return @intFromEnum(err(.invalid_arg, "da_repo_search: falta query"));
    if (q_v != .string or q_v.string.len == 0 or q_v.string.len > 512)
        return @intFromEnum(err(.invalid_arg, "da_repo_search: query debe ser string 1..512"));
    var max_results: usize = 20;
    if (obj.get("max_results")) |v| {
        if (v == .integer and v.integer > 0) max_results = @min(@as(usize, @intCast(v.integer)), 100);
    }
    var root_buf: [4096]u8 = undefined;
    var root: []const u8 = workspace.effectiveRoot(&root_buf);
    if (obj.get("root")) |v| {
        if (v == .string and v.string.len > 0) root = v.string;
    }

    var opts: repo_search.Options = .{ .max_results = max_results };
    var vi_opt: ?repo_search.VectorIndex = null;
    if (obj.get("mode")) |v| {
        if (v == .string and (std.mem.eql(u8, v.string, "semantic") or std.mem.eql(u8, v.string, "hybrid"))) {
            opts.semantic_rerank = true;
            // `semantic` = ranking puramente vectorial (el coseno decide solo);
            // `hybrid` = fusion RRF de BM25 + coseno.
            opts.semantic_only = std.mem.eql(u8, v.string, "semantic");
            var embed_ctx: *EmbedderCtx = undefined;
            if (resolveEmbedder(st, aa, &embed_ctx)) |note| {
                opts.semantic_note = note;
            } else {
                opts.embed_fn = cloudEmbed;
                opts.embed_ctx = embed_ctx;
                // Índice persistente del MISMO modelo: si hay trozos
                // embebidos el lado vectorial cubre el corpus entero con una
                // sola llamada (la de la consulta). Sin índice, el pool BM25
                // se reordena en vivo — no descubre matches nuevos y el
                // estado viaja declarado en la respuesta.
                vi_opt = repo_embed.loadIndex(aa, st.db_conn, root, embed_ctx.model) catch null;
                if (vi_opt) |*vi| opts.vector_index = vi;
            }
        }
    }

    var threaded = std.Io.Threaded.init(aa, .{});
    defer threaded.deinit();
    const res = repo_search.search(aa, threaded.io(), root, q_v.string, opts) catch |e| switch (e) {
        error.NotARepo => return @intFromEnum(err(.invalid_arg, "da_repo_search: root no es un repo git")),
        error.IoFailed => return @intFromEnum(err(.internal, "da_repo_search: fallo de E/S indexando")),
        error.OutOfMemory => return @intFromEnum(err(.oom, "OOM")),
    };
    defer res.deinit();
    var buf: std.Io.Writer.Allocating = .init(aa);
    defer buf.deinit();
    repo_search.writeJson(&buf.writer, res) catch
        return @intFromEnum(err(.internal, "da_repo_search: serializacion fallo"));
    out.* = ownedCStr(buf.written()) orelse return @intFromEnum(err(.oom, "OOM"));
    return @intFromEnum(ok());
}

/// Resuelve `root` de los args JSON {"root?"}; sin root = effectiveRoot.
fn argRoot(obj: std.json.ObjectMap, buf: *[4096]u8) []const u8 {
    const root: []const u8 = workspace.effectiveRoot(buf);
    if (obj.get("root")) |v| {
        if (v == .string and v.string.len > 0) return v.string;
    }
    return root;
}

/// E5.15 — `da_repo_embed_index`: construye/actualiza el índice vectorial
/// persistente del repo (repo_embeddings). Entrada {"root?":string}. Solo
/// re-embebe los trozos cuyo hash no está almacenado para el modelo
/// configurado; emite evento `repo_embed_indexed` con las cuentas reales.
/// Requiere embeddings_config habilitado + clave; si no, el JSON devuelve
/// {indexed:false, reason} honesto (nunca un índice fingido).
pub export fn da_repo_embed_index(
    handle: ?*anyopaque,
    query_json: [*:0]const u8,
    out_json: ?*?[*:0]u8,
) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_repo_embed_index: null core handle"));
    const out = out_json orelse return @intFromEnum(err(.invalid_arg, "da_repo_embed_index: null out"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    var arena = std.heap.ArenaAllocator.init(st.arena.child_allocator);
    defer arena.deinit();
    const aa = arena.allocator();

    var parsed = std.json.parseFromSlice(std.json.Value, aa, std.mem.span(query_json), .{}) catch
        return @intFromEnum(err(.invalid_arg, "da_repo_embed_index: JSON invalido"));
    defer parsed.deinit();
    if (parsed.value != .object)
        return @intFromEnum(err(.invalid_arg, "da_repo_embed_index: args debe ser objeto"));
    var root_buf: [4096]u8 = undefined;
    const root = argRoot(parsed.value.object, &root_buf);

    var embed_ctx: *EmbedderCtx = undefined;
    const note = resolveEmbedder(st, aa, &embed_ctx);

    var buf: std.Io.Writer.Allocating = .init(aa);
    defer buf.deinit();
    var js: std.json.Stringify = .{ .writer = &buf.writer, .options = .{} };
    js.beginObject() catch return @intFromEnum(err(.oom, "OOM"));
    if (note) |why| {
        js.objectField("indexed") catch {};
        js.write(false) catch {};
        js.objectField("reason") catch {};
        js.write(why) catch {};
    } else {
        var threaded = std.Io.Threaded.init(aa, .{});
        defer threaded.deinit();
        const stats = repo_embed.indexRepo(
            aa,
            threaded.io(),
            st.db_conn,
            root,
            embed_ctx.model,
            cloudEmbed,
            embed_ctx,
            .{},
        ) catch |e| switch (e) {
            error.NotARepo => return @intFromEnum(err(.invalid_arg, "da_repo_embed_index: root no es un repo git")),
            error.IoFailed, error.DbFailed => return @intFromEnum(err(.internal, "da_repo_embed_index: fallo de E/S o DB")),
            error.OutOfMemory => return @intFromEnum(err(.oom, "OOM")),
        };
        repo_embed.emitIndexedEvent(st.db_conn, 0, root, &stats);
        js.objectField("indexed") catch {};
        js.write(stats.error_note == null) catch {};
        js.objectField("model") catch {};
        js.write(stats.model) catch {};
        js.objectField("files_scanned") catch {};
        js.write(stats.files_scanned) catch {};
        js.objectField("chunks_total") catch {};
        js.write(stats.chunks_total) catch {};
        js.objectField("embedded") catch {};
        js.write(stats.embedded) catch {};
        js.objectField("reused") catch {};
        js.write(stats.reused) catch {};
        js.objectField("removed") catch {};
        js.write(stats.removed) catch {};
        js.objectField("skipped") catch {};
        js.write(stats.skipped) catch {};
        js.objectField("batches") catch {};
        js.write(stats.batches) catch {};
        js.objectField("dim") catch {};
        js.write(stats.dim) catch {};
        js.objectField("elapsed_ms") catch {};
        js.write(stats.elapsed_ms) catch {};
        js.objectField("retries_429") catch {};
        js.write(embed_ctx.retries) catch {};
        if (stats.error_note) |en| {
            js.objectField("error") catch {};
            js.write(en) catch {};
        }
        if (stats.truncated) {
            js.objectField("truncated") catch {};
            js.write(true) catch {};
        }
    }
    js.endObject() catch {};
    out.* = ownedCStr(buf.written()) orelse return @intFromEnum(err(.oom, "OOM"));
    return @intFromEnum(ok());
}

/// E5.15 — `da_repo_embed_status`: estado del índice vectorial del repo.
/// Entrada {"root?":string, "model?":string} — sin modelo informa el índice
/// más reciente de cualquier modelo. Salida {state:"empty"|"ready",
/// chunks_indexed, files_indexed, model, updated_at}.
pub export fn da_repo_embed_status(
    handle: ?*anyopaque,
    query_json: [*:0]const u8,
    out_json: ?*?[*:0]u8,
) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_repo_embed_status: null core handle"));
    const out = out_json orelse return @intFromEnum(err(.invalid_arg, "da_repo_embed_status: null out"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    var arena = std.heap.ArenaAllocator.init(st.arena.child_allocator);
    defer arena.deinit();
    const aa = arena.allocator();

    var parsed = std.json.parseFromSlice(std.json.Value, aa, std.mem.span(query_json), .{}) catch
        return @intFromEnum(err(.invalid_arg, "da_repo_embed_status: JSON invalido"));
    defer parsed.deinit();
    if (parsed.value != .object)
        return @intFromEnum(err(.invalid_arg, "da_repo_embed_status: args debe ser objeto"));
    var root_buf: [4096]u8 = undefined;
    const root = argRoot(parsed.value.object, &root_buf);
    var model: []const u8 = "";
    if (parsed.value.object.get("model")) |v| {
        if (v == .string) model = v.string;
    }

    const info = repo_embed.indexStatus(aa, st.db_conn, root, model);
    var buf: std.Io.Writer.Allocating = .init(aa);
    defer buf.deinit();
    var js: std.json.Stringify = .{ .writer = &buf.writer, .options = .{} };
    js.beginObject() catch return @intFromEnum(err(.oom, "OOM"));
    js.objectField("state") catch {};
    js.write(info.state) catch {};
    js.objectField("chunks_indexed") catch {};
    js.write(info.chunks_indexed) catch {};
    js.objectField("files_indexed") catch {};
    js.write(info.files_indexed) catch {};
    js.objectField("model") catch {};
    js.write(info.model) catch {};
    js.objectField("updated_at") catch {};
    js.write(info.updated_at) catch {};
    js.endObject() catch {};
    out.* = ownedCStr(buf.written()) orelse return @intFromEnum(err(.oom, "OOM"));
    return @intFromEnum(ok());
}

/// E5.15 — `da_embeddings_probe_json`: sondeo EN VIVO de la capacidad de
/// embeddings de (provider, model). Entrada {"provider?","model?"} — sin
/// args usa los de settings.embeddings_config. Hace UNA llamada real de
/// embedding con la puerta de presupuesto y el reintento 429 de rigor, y
/// persiste cap_embeddings_*='live_probe' SOLO cuando el endpoint respondió
/// algo medible (yes si devolvió vectores, no si 404). Un fallo de
/// auth/cuota/red NO se persiste: es fallo de la clave o del entorno, no del
/// modelo. Salida {ok, status:"yes"|"no"|"unmeasured", dim?, elapsed_ms,
/// reason?}.
pub export fn da_embeddings_probe_json(
    handle: ?*anyopaque,
    query_json: [*:0]const u8,
    out_json: ?*?[*:0]u8,
) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_embeddings_probe_json: null core handle"));
    const out = out_json orelse return @intFromEnum(err(.invalid_arg, "da_embeddings_probe_json: null out"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    var arena = std.heap.ArenaAllocator.init(st.arena.child_allocator);
    defer arena.deinit();
    const aa = arena.allocator();

    var parsed = std.json.parseFromSlice(std.json.Value, aa, std.mem.span(query_json), .{}) catch
        return @intFromEnum(err(.invalid_arg, "da_embeddings_probe_json: JSON invalido"));
    defer parsed.deinit();
    if (parsed.value != .object)
        return @intFromEnum(err(.invalid_arg, "da_embeddings_probe_json: args debe ser objeto"));
    const obj = parsed.value.object;
    var arg_provider: ?[]const u8 = null;
    var arg_model: ?[]const u8 = null;
    if (obj.get("provider")) |v| {
        if (v == .string and v.string.len > 0) arg_provider = aa.dupe(u8, v.string) catch null;
    }
    if (obj.get("model")) |v| {
        if (v == .string and v.string.len > 0) arg_model = aa.dupe(u8, v.string) catch null;
    }

    // Resolución del par (provider, model): args o embeddings_config.
    var provider: ?[]const u8 = arg_provider;
    var model: ?[]const u8 = arg_model;
    if (provider == null or model == null) {
        var embed_ctx: *EmbedderCtx = undefined;
        if (resolveEmbedder(st, aa, &embed_ctx)) |note| {
            var buf: std.Io.Writer.Allocating = .init(aa);
            defer buf.deinit();
            var js: std.json.Stringify = .{ .writer = &buf.writer, .options = .{} };
            js.beginObject() catch return @intFromEnum(err(.oom, "OOM"));
            js.objectField("ok") catch {};
            js.write(false) catch {};
            js.objectField("status") catch {};
            js.write("unmeasured") catch {};
            js.objectField("reason") catch {};
            js.write(note) catch {};
            js.endObject() catch {};
            out.* = ownedCStr(buf.written()) orelse return @intFromEnum(err(.oom, "OOM"));
            return @intFromEnum(ok());
        }
        provider = embed_ctx.provider;
        model = embed_ctx.model;
    }

    var base_url: ?[]const u8 = null;
    var api_style: ?[]const u8 = null;
    const ps = st.catalog.db.prepare("SELECT base_url, api_style FROM providers WHERE name = ?") catch return @intFromEnum(err(.internal, "probe: prepare fallo"));
    db.bindText(ps, 1, provider.?) catch {};
    if (db.c.sqlite3_step(ps) == db.c.SQLITE_ROW) {
        const bptr = db.c.sqlite3_column_text(ps, 0);
        const sptr = db.c.sqlite3_column_text(ps, 1);
        if (bptr != null) base_url = aa.dupe(u8, bptr[0..std.mem.len(bptr)]) catch null;
        if (sptr != null) api_style = aa.dupe(u8, sptr[0..std.mem.len(sptr)]) catch null;
    }
    st.catalog.db.finalize(ps);

    var probe_status: []const u8 = "unmeasured";
    var reason: []const u8 = "ok";
    var dim: usize = 0;
    var retries: u32 = 0;
    const t0 = health.nowMillis(st.db_conn);
    const style = providers.embeddings.styleForApi(api_style orelse "");
    if (base_url == null) {
        reason = "provider_missing";
    } else if (style == null) {
        reason = "unsupported_style";
    } else {
        var cm = credentials.CredentialManager.init(aa, st.catalog_path) catch null;
        var key: ?[]const u8 = null;
        if (cm) |*c| {
            key = c.getKey(provider.?) catch null;
            c.deinit();
        }
        if (key == null) {
            reason = "no_key";
        } else {
            var ctx = EmbedderCtx{
                .base_url = base_url.?,
                .api_key = key,
                .model = model.?,
                .provider = provider.?,
                .style = style.?,
                .is_free = model_router.catalogModelIsFree(st.catalog.db, provider.?, model.?),
                .catalog_db = st.catalog.db,
            };
            const probe_text = [_][]const u8{"devagents embedding capability probe"};
            if (cloudEmbed(&ctx, aa, &probe_text)) |vecs| {
                if (vecs.len == 1 and vecs[0].len > 0) {
                    probe_status = "yes";
                    dim = vecs[0].len;
                } else {
                    reason = "bad_vectors";
                }
            } else |e| {
                reason = @errorName(e);
                if (e == error.NotFound) probe_status = "no";
            }
            retries = ctx.retries;
        }
    }
    const elapsed = health.nowMillis(st.db_conn) - t0;

    // Solo un veredicto del endpoint se persiste con 'live_probe'.
    if (probe_status[0] == 'y' or std.mem.eql(u8, probe_status, "no")) {
        discovery_persistence.persistEmbeddingEvidence(
            st.catalog.db,
            provider.?,
            model.?,
            api_style orelse "unknown",
            base_url orelse "",
            if (probe_status[0] == 'y') .yes else .no,
            health.nowSeconds(st.catalog.db),
        ) catch {};
    }

    var buf: std.Io.Writer.Allocating = .init(aa);
    defer buf.deinit();
    var js: std.json.Stringify = .{ .writer = &buf.writer, .options = .{} };
    js.beginObject() catch return @intFromEnum(err(.oom, "OOM"));
    js.objectField("ok") catch {};
    js.write(std.mem.eql(u8, probe_status, "yes")) catch {};
    js.objectField("status") catch {};
    js.write(probe_status) catch {};
    js.objectField("provider") catch {};
    js.write(provider orelse "") catch {};
    js.objectField("model") catch {};
    js.write(model orelse "") catch {};
    if (dim > 0) {
        js.objectField("dim") catch {};
        js.write(dim) catch {};
    }
    js.objectField("elapsed_ms") catch {};
    js.write(elapsed) catch {};
    js.objectField("retries_429") catch {};
    js.write(retries) catch {};
    if (!std.mem.eql(u8, reason, "ok")) {
        js.objectField("reason") catch {};
        js.write(reason) catch {};
    }
    js.endObject() catch {};
    out.* = ownedCStr(buf.written()) orelse return @intFromEnum(err(.oom, "OOM"));
    return @intFromEnum(ok());
}

/// FIX-ENGINE-9: NO toca ledger.db desde el hilo de dispatch. Copia las
/// AuditEntry a una cola en memoria (mutex corto, sin I/O) y retorna.
/// El flush real a ledger.db lo hace el hilo principal via flushAuditQueue.
fn persistAuditEntries(st: *CoreState, aa: std.mem.Allocator, entries: []const superagent.AuditEntry) void {
    st.audit_queue_mutex.lock();
    defer st.audit_queue_mutex.unlock();
    for (entries) |entry| {
        const dup = superagent.AuditEntry{
            .ts = entry.ts,
            .subject_kind = aa.dupe(u8, entry.subject_kind) catch continue,
            .subject_id = entry.subject_id,
            .order_id = entry.order_id,
            .action = aa.dupe(u8, entry.action) catch continue,
            .verdict = aa.dupe(u8, entry.verdict) catch continue,
            .model_id = aa.dupe(u8, entry.model_id) catch continue,
            .provider = aa.dupe(u8, entry.provider) catch continue,
            .evidence_ref = aa.dupe(u8, entry.evidence_ref) catch continue,
            .notes = aa.dupe(u8, entry.notes) catch continue,
        };
        st.audit_queue.append(aa, dup) catch {
            dup.deinit(aa);
            continue;
        };
    }
}

/// GOBERNANZA-HIBRIDO-LEDGER: barrida del consumo NO-tarea de una orden — cada
/// fila de usage_records con worker_id 'planner' o '' (llamadas auxiliares como
/// el selector de herramientas, que se registran recién durante el despacho) que
/// salió por un modelo is_free=0 deja su fila ESCALATION justificada por la cola
/// serializada (FIX-ENGINE-8/9: el Router de producción tiene ledger=null a
/// propósito y solo el hilo principal toca ledger.db). Las tareas quedan fuera
/// a propósito: su consumo se audita por intento en emitLlmAttempts. Corre tras
/// processOrder (aunque el plan se descarte o cancele, el gasto es real) y tras
/// dispatchApprovedOrder; `escalated_usage_ids` deduplica entre ambas barridas.
fn emitAuxEscalations(st: *CoreState, conn: db.Connection, aa: std.mem.Allocator, order_id: i64) void {
    const stmt = conn.prepare("SELECT id, worker_id, provider, model, key_label FROM usage_records WHERE order_id = ? AND worker_id IN ('planner', '')") catch return;
    defer conn.finalize(stmt);
    db.bindInt(stmt, 1, order_id) catch return;
    while (db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW) {
        const usage_id = db.c.sqlite3_column_int64(stmt, 0);
        const wid_ptr = db.c.sqlite3_column_text(stmt, 1);
        const prov_ptr = db.c.sqlite3_column_text(stmt, 2);
        const mdl_ptr = db.c.sqlite3_column_text(stmt, 3);
        const key_ptr = db.c.sqlite3_column_text(stmt, 4);
        const wid = if (wid_ptr != null) wid_ptr[0..std.mem.len(wid_ptr)] else "";
        const prov = if (prov_ptr != null) prov_ptr[0..std.mem.len(prov_ptr)] else "";
        const mdl = if (mdl_ptr != null) mdl_ptr[0..std.mem.len(mdl_ptr)] else "";
        const key = if (key_ptr != null) key_ptr[0..std.mem.len(key_ptr)] else "";
        if (prov.len == 0 or mdl.len == 0) continue;
        if (model_router.catalogModelIsFree(st.catalog.db, prov, mdl)) continue;
        st.escalated_usage_mutex.lock();
        const already = st.escalated_usage_ids.contains(usage_id);
        if (!already) st.escalated_usage_ids.put(aa, usage_id, {}) catch {};
        st.escalated_usage_mutex.unlock();
        if (already) continue;
        const etapa: []const u8 = if (std.mem.eql(u8, wid, "planner")) "planificar" else "orquestacion auxiliar";
        const nota = std.fmt.allocPrint(
            aa,
            "politica de gobernanza: etapa '{s}' asignada a pago (key={s})",
            .{ etapa, if (key.len > 0) key else "?" },
        ) catch continue;
        defer aa.free(nota);
        const evid = std.fmt.allocPrint(aa, "usage:{d}", .{usage_id}) catch continue;
        defer aa.free(evid);
        persistAuditEntries(st, aa, &.{
            .{
                .ts = 0,
                .subject_kind = "model_router",
                .subject_id = 0,
                .order_id = order_id,
                .action = "ESCALATION",
                .verdict = "PASS",
                .model_id = mdl,
                .provider = prov,
                .evidence_ref = evid,
                .notes = nota,
            },
        });
    }
}

/// FIX-ENGINE-9: drena la cola de audit desde el hilo principal y escribe
/// a ledger.db. Seguro: solo el hilo principal toca ledger.db ahora.
fn flushAuditQueue(st: *CoreState) void {
    st.audit_queue_mutex.lock();
    if (st.audit_queue.items.len == 0) {
        st.audit_queue_mutex.unlock();
        return;
    }
    const aa = st.arena.child_allocator;
    const owned = aa.alloc(superagent.AuditEntry, st.audit_queue.items.len) catch {
        st.audit_queue_mutex.unlock();
        return;
    };
    for (st.audit_queue.items, 0..) |e, i| owned[i] = e;
    st.audit_queue.clearRetainingCapacity();
    st.audit_queue_mutex.unlock();

    st.ledger_mutex.lock();
    defer st.ledger_mutex.unlock();
    persistAuditEntriesOnConn(aa, st.ledger, owned, st.db_conn) catch |e| {
        if (!builtin.is_test) {
            std.debug.print("[FIX-ENGINE-9] audit flush best-effort skip: {s}\n", .{@errorName(e)});
        }
    };

    for (owned) |e| e.deinit(aa);
    aa.free(owned);
}

fn persistAuditEntriesOnConn(aa: std.mem.Allocator, conn: db.Connection, entries: []const superagent.AuditEntry, runtime: db.Connection) !void {
    var prev_hash: ?[]const u8 = null;
    var prev_hash_owned: ?[]u8 = null;
    defer if (prev_hash_owned) |old| aa.free(old);

    const sql = "INSERT INTO audit_ledger (ts, subject_kind, subject_id, order_id, action, verdict, model_id, provider, evidence_ref, notes, prev_hash, row_hash) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)";
    for (entries) |entry| {
        const ts = health.nowMillis(runtime);
        var content_buf: std.Io.Writer.Allocating = .init(aa);
        defer content_buf.deinit();
        // FIX-ENGINE-11: usar PUNTERO al writer (&content_buf.writer), NO una copia
        // por valor. Una copia rompe @fieldParentPtr en el drain del Allocating →
        // al crecer el buffer escribe en un puntero basura → 0xC0000005 (crash que
        // mataba la 2ª orden de cada sesión durante el flush de auditoría).
        const cw = &content_buf.writer;
        cw.print("{d}|{s}|{d}|{d}|{s}|{s}|{s}|{s}|{s}", .{
            ts, entry.subject_kind, entry.subject_id, entry.order_id, entry.action, entry.verdict, entry.model_id, entry.provider, entry.evidence_ref,
        }) catch break;
        const row_hash = db.computeRowHash(prev_hash, content_buf.written());
        const hash_slice = aa.dupe(u8, &row_hash) catch break;

        const stmt = conn.prepare(sql) catch |e| {
            aa.free(hash_slice);
            const errmsg = db.c.sqlite3_errmsg(conn.db);
            const msg_len = std.mem.len(errmsg);
            if (!builtin.is_test) {
                std.debug.print("[FIX-ENGINE-6] prepare failed: {s} errmsg={s}\n", .{ @errorName(e), errmsg[0..msg_len] });
            }
            break;
        };
        defer conn.finalize(stmt);

        db.bindInt(stmt, 1, ts) catch break;
        db.bindText(stmt, 2, entry.subject_kind) catch break;
        db.bindInt(stmt, 3, entry.subject_id) catch break;
        db.bindInt(stmt, 4, entry.order_id) catch break;
        db.bindText(stmt, 5, entry.action) catch break;
        db.bindText(stmt, 6, entry.verdict) catch break;
        db.bindText(stmt, 7, entry.model_id) catch break;
        db.bindText(stmt, 8, entry.provider) catch break;
        db.bindText(stmt, 9, entry.evidence_ref) catch break;
        db.bindText(stmt, 10, entry.notes) catch break;
        if (prev_hash) |ph| {
            db.bindText(stmt, 11, ph) catch break;
        } else {
            db.bindText(stmt, 11, "") catch break;
        }
        db.bindText(stmt, 12, hash_slice) catch break;

        const rc = db.c.sqlite3_step(stmt);
        if (rc != db.c.SQLITE_DONE) {
            aa.free(hash_slice);
            const errmsg = db.c.sqlite3_errmsg(conn.db);
            const msg_len = std.mem.len(errmsg);
            if (!builtin.is_test) {
                std.debug.print("[FIX-ENGINE-6] step failed rc={d} errmsg={s}\n", .{ rc, errmsg[0..msg_len] });
            }
            break;
        }

        if (prev_hash_owned) |old| aa.free(old);
        prev_hash_owned = hash_slice;
        prev_hash = hash_slice;
    }
}

/// Despacha una orden ya planeada (rec.status == .planned). Extraído para que
/// `da_order_approve` y `da_order_confirm_json` compartan el mismo camino de
/// router + LiveLlm + volcado de salidas/aprobaciones sin duplicar lógica.
/// `conn`: MULTISESSION-P0 (2026-07-12) — la Connection de runtime.db que este
/// hilo debe usar EXCLUSIVAMENTE (nunca `st.db_conn` dentro de esta función ni
/// de lo que llama). Los llamadores síncronos (da_order_approve/da_order_confirm_json,
/// que corren en el hilo llamador sin hilo de dispatch separado) pasan
/// `st.db_conn` directamente — no hay concurrencia real que evitar ahí. El
/// llamador asíncrono (dispatchThreadFn) pasa su propia Connection, abierta y
/// migrada dentro del hilo.
/// CHECKPOINT-T2: `is_resume` distingue un despacho de reanudación — lee el
/// checkpoint persistido de la orden y lo inyecta al Superagent para que las
/// tareas ya completadas no vuelvan a correr.
/// persiste la selección de modelo con la que la orden se lanzó en el
/// ledger de la orden (evento 'model_selection'). Sin ella, un resume tras
/// reinicio relee los pins GLOBALES — ya vacíos — y el router libre podía
/// enrutar a un modelo de pago una orden que el usuario fijó local (medido:
/// #660 Ollama|qwen2.5:3b → resume → Cohere|command-a-03-2025).
/// Best-effort: un evento perdido degrada al comportamiento anterior, no
/// tumba el dispatch.
fn persistLaunchModelSelection(conn: db.Connection, aa: std.mem.Allocator, order_id: i64, snap: *const permission_snapshot.OwnedPermissionSnapshot) void {
    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginObject() catch return;
    js.objectField("v") catch return;
    js.write(1) catch return;
    // write() desenvuelve el opcional: pin nulo se persiste como null — la
    // ausencia de pin también es un dato honesto de lanzamiento.
    js.objectField("plan_p") catch return;
    js.write(snap.forced_provider) catch return;
    js.objectField("plan_m") catch return;
    js.write(snap.forced_model) catch return;
    js.objectField("exec_p") catch return;
    js.write(snap.exec_forced_provider) catch return;
    js.objectField("exec_m") catch return;
    js.write(snap.exec_forced_model) catch return;
    js.objectField("audit_p") catch return;
    js.write(snap.audit_forced_provider) catch return;
    js.objectField("audit_m") catch return;
    js.write(snap.audit_forced_model) catch return;
    js.objectField("swarm") catch return;
    js.write(snap.swarm_json) catch return;
    js.endObject() catch return;
    const payload = out.written();
    const stmt = conn.prepare("INSERT INTO events (ts, source, kind, payload_json, order_id) VALUES (?, 'core', 'model_selection', ?, ?)") catch return;
    defer conn.finalize(stmt);
    db.bindInt(stmt, 1, health.nowMillis(conn)) catch return;
    db.bindText(stmt, 2, payload) catch return;
    db.bindInt(stmt, 3, order_id) catch return;
    _ = db.c.sqlite3_step(stmt);
}

/// lee la selección de modelo persistida de la orden (último evento
/// 'model_selection'). Null si la orden es anterior al fix o nunca despachó —
/// el llamador cae entonces a los globales, como antes.
fn loadLaunchModelSelection(aa: std.mem.Allocator, conn: db.Connection, order_id: i64) ?permission_snapshot.OwnedModelSelection {
    const stmt = conn.prepare("SELECT payload_json FROM events WHERE order_id = ? AND kind = 'model_selection' ORDER BY id DESC LIMIT 1") catch return null;
    defer conn.finalize(stmt);
    db.bindInt(stmt, 1, order_id) catch return null;
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) return null;
    const ptr = db.c.sqlite3_column_text(stmt, 0) orelse return null;
    const len: usize = @intCast(db.c.sqlite3_column_bytes(stmt, 0));
    const txt = @as([*]const u8, @ptrCast(ptr))[0..len];
    const parsed = std.json.parseFromSlice(std.json.Value, aa, txt, .{}) catch return null;
    defer parsed.deinit();
    if (parsed.value != .object) return null;
    const obj = parsed.value.object;
    const str = struct {
        fn f(o: std.json.ObjectMap, k: []const u8) ?[]const u8 {
            const v = o.get(k) orelse return null;
            return if (v == .string) v.string else null;
        }
    }.f;
    return permission_snapshot.OwnedModelSelection.initCloneRoles(
        aa,
        str(obj, "plan_p"),
        str(obj, "plan_m"),
        str(obj, "exec_p"),
        str(obj, "exec_m"),
        str(obj, "audit_p"),
        str(obj, "audit_m"),
        str(obj, "swarm"),
    ) catch null;
}

test "E-83: resume restaura la selección persistida, no los globales vacíos" {
    const allocator = std.testing.allocator;
    var conn = try db.Connection.open(allocator, ":memory:");
    defer conn.close();
    var migrator = db.Migrator.init(allocator);
    try migrator.migrate(conn, &db.runtime_schema);
    try conn.exec("INSERT INTO orders (id, project_id, user_prompt, status, created_at) VALUES (7, 'p', 'x', 'running', 1)");

    // Lanzamiento con plan+exec y auditor independiente fijados por el usuario.
    var snap = try permission_snapshot.OwnedPermissionSnapshot.initCloneRoles(
        allocator,
        .normal, // perm_mode irrelevante para este test
        &.{},
        &.{},
        &.{},
        "Ollama",
        "qwen2.5:3b",
        null,
        null,
        "Google",
        "gemini-fixture",
        "[{\"provider\":\"Ollama\",\"model\":\"qwen2.5:3b\"}]",
    );
    defer snap.deinit(allocator);
    persistLaunchModelSelection(conn, allocator, 7, &snap);

    // Resume post-reinicio: los globales están vacíos — snapshot "de ahora" sin pins.
    var resumed = try permission_snapshot.OwnedPermissionSnapshot.initCloneRoles(
        allocator,
        .normal,
        &.{},
        &.{},
        &.{},
        null,
        null,
        null,
        null,
        null,
        null,
        null,
    );
    defer resumed.deinit(allocator);
    var sel = loadLaunchModelSelection(allocator, conn, 7) orelse return error.TestUnexpectedNull;
    defer sel.deinit(allocator);
    try resumed.applyModelSelection(allocator, &sel);

    // La orden reanudada corre con lo que el usuario fijó — no con router libre.
    try std.testing.expectEqualStrings("Ollama", resumed.forced_provider.?);
    try std.testing.expectEqualStrings("qwen2.5:3b", resumed.forced_model.?);
    try std.testing.expectEqualStrings("Ollama", resumed.exec_forced_provider.?);
    try std.testing.expectEqualStrings("qwen2.5:3b", resumed.exec_forced_model.?);
    try std.testing.expectEqualStrings("Google", resumed.audit_forced_provider.?);
    try std.testing.expectEqualStrings("gemini-fixture", resumed.audit_forced_model.?);
    try std.testing.expect(resumed.swarm_json != null);
}

test "E-83: orden sin evento persistido degrada a globales (legacy)" {
    const allocator = std.testing.allocator;
    var conn = try db.Connection.open(allocator, ":memory:");
    defer conn.close();
    var migrator = db.Migrator.init(allocator);
    try migrator.migrate(conn, &db.runtime_schema);
    try conn.exec("INSERT INTO orders (id, project_id, user_prompt, status, created_at) VALUES (9, 'p', 'x', 'running', 1)");
    try std.testing.expect(loadLaunchModelSelection(allocator, conn, 9) == null);
}

// ── E5.18 (D-C5): Best-of-N ───────────────────────────────────────────────
//
// La orden padre declara `orders.best_of_n` (2..4) y opcionalmente
// `best_of_n_members` (JSON [{provider,model}]). Al despachar NO corre su
// propio plan: runBestOfN crea una orden hija por miembro — cada una con su
// plan clonado, su space `orden-<padre>-m<k>` (worktree git o directorio
// degradado) y su pin de ejecutor persistido como `model_selection` ANTES de
// llamar a dispatchApprovedOrder(is_resume=true), que lo restaura como una
// reanudación normal. Auditor sin pin: la selección automática ya excluye al
// fabricante del productor (E5.08). Misma maquinaria — sin tubería paralela.
//
// Al terminar todas se asigna rank determinista (gates → pruebas → veredicto
// → coste → tiempo; empate total = mismo rank) y la padre queda
// `awaiting_best_of_n` — estado de espera honesto, no terminal. El usuario
// elige con da_best_of_n_choose: el ganador se aplica sobre el worktree de la
// padre y las perdedoras se archivan.

/// Evento best_of_n_* ligado a la orden PADRE — el usuario ve el desenlace
/// en la orden que lanzó; el payload nombra a la hija.
fn bonEvent(conn: db.Connection, parent_id: i64, kind: []const u8, payload: []const u8) void {
    const stmt = conn.prepare("INSERT INTO events (ts, source, kind, payload_json, order_id) VALUES (?, 'core', ?, ?, ?)") catch return;
    defer conn.finalize(stmt);
    db.bindInt(stmt, 1, health.nowMillis(conn)) catch return;
    db.bindText(stmt, 2, kind) catch return;
    db.bindText(stmt, 3, payload) catch return;
    db.bindInt(stmt, 4, parent_id) catch return;
    _ = db.c.sqlite3_step(stmt);
}

// ── USUARIO-NUEVO B (10-nov): modo «DevAgents» — delegación ───────────────
//
// La conversación (Directo) llama a `delegate_tasks`. Cada subtarea es una
// ORDEN HIJA (parent_order_id = la conversación) con su plan (la tarea y su
// auditoría, validado por el planificador), su asignación por el router con la
// gobernanza vigente, su worktree propio (spaces.createSpace, como las
// candidatas de best-of-N) y su despacho por `dispatchApprovedOrder`: mismos
// eventos, misma auditoría, mismos topes de gasto. Corren en paralelo, un hilo
// y una conexión por hija. Al terminar, lo hecho y auditado se integra en la
// carpeta del proyecto con `best_of_n.applyWinner` (la fusión que ya usa la
// Colmena); dos subtareas que tocan el mismo archivo no se pisan.

const DelegateCtx = struct {
    st: *CoreState,
    parent_order_id: i64,
    project_id: []u8,
    root: []u8,
    refs: std.atomic.Value(u32) = std.atomic.Value(u32).init(1),
    busy: std.atomic.Value(bool) = std.atomic.Value(bool).init(false),
    /// Seam de prueba: sustituye el despacho real de cada hija.
    dispatch_fn: ?*const fn (st: *CoreState, rec: *OrderRecord, conn: db.Connection) DaResult = null,

    fn create(st: *CoreState, parent_order_id: i64, project_id: []const u8, root: []const u8) !*DelegateCtx {
        const a = std.heap.page_allocator;
        const self = try a.create(DelegateCtx);
        errdefer a.destroy(self);
        const pid = try a.dupe(u8, project_id);
        errdefer a.free(pid);
        self.* = .{ .st = st, .parent_order_id = parent_order_id, .project_id = pid, .root = try a.dupe(u8, root) };
        return self;
    }

    fn retain(self: *DelegateCtx) void {
        _ = self.refs.fetchAdd(1, .acq_rel);
    }

    /// Un hilo HTTP que la conversación abandonó al cancelar puede seguir
    /// dentro de la herramienta: el contexto vive hasta la última referencia.
    fn release(self: *DelegateCtx) void {
        if (self.refs.fetchSub(1, .acq_rel) != 1) return;
        const a = std.heap.page_allocator;
        a.free(self.project_id);
        a.free(self.root);
        a.destroy(self);
    }
};

fn delegationCancelRequested(st: *CoreState) bool {
    st.plan_mutex.lock();
    defer st.plan_mutex.unlock();
    return st.plan_cancel_requested;
}

fn delegationErrorJson(a: std.mem.Allocator, code: []const u8, detail: []const u8) ![]u8 {
    return std.json.Stringify.valueAlloc(a, .{ .@"error" = code, .detail = detail }, .{});
}

const DelegateChild = struct {
    index: usize,
    sub: *const delegation.Subtask,
    order_id: i64 = 0,
    rec: OrderRecord = undefined,
    token: ?*live_worker.CancellationToken = null,
    thread: ?std.Thread = null,
    started_ms: u64 = 0,
    elapsed_ms: u64 = 0,
    result: DaResult = .ok,
    setup_error: ?[]const u8 = null,
    /// `setup_error` lo reservó `allocator` (frase con el diagnóstico real).
    owned_error: bool = false,
    /// `rec.outcome` (plan y asignaciones) es propio y se libera al final.
    has_rec: bool = false,
    /// No llegó a lanzarse porque el usuario pulsó «Detener» antes.
    skipped: bool = false,
    /// Seguía trabajando cuando el usuario pulsó «Detener» y se le cortó.
    cut: bool = false,
    done: std.atomic.Value(bool) = std.atomic.Value(bool).init(false),
};

const DelegateThreadCtx = struct {
    ctx: *DelegateCtx,
    child: *DelegateChild,
    runtime_path: [:0]const u8,
};

fn delegateChildThread(t: *DelegateThreadCtx) void {
    const st = t.ctx.st;
    defer t.child.done.store(true, .release);
    var conn = db.Connection.open(st.arena.child_allocator, t.runtime_path) catch {
        t.child.result = err(.internal, "delegación: no se pudo abrir la base de la subtarea");
        return;
    };
    defer conn.close();
    const t0 = GetTickCount64();
    t.child.result = if (t.ctx.dispatch_fn) |f| f(st, &t.child.rec, conn) else dispatchApprovedOrder(st, &t.child.rec, conn, true);
    t.child.elapsed_ms = GetTickCount64() - t0;
}

/// Selección de modelos de la hija (esquema v1 de model_selection): el modelo
/// pedido para ejecutar, o ninguno (decide el router con la gobernanza); el
/// auditor nunca se fija (exclusión de autoauditoría del router).
fn persistDelegateSelection(conn: db.Connection, aa: std.mem.Allocator, child_order_id: i64, provider: ?[]const u8, model: ?[]const u8, swarm_json: ?[:0]const u8) void {
    const payload = std.json.Stringify.valueAlloc(aa, .{
        .v = @as(u32, 1),
        .plan_p = provider,
        .plan_m = model,
        .exec_p = provider,
        .exec_m = model,
        .audit_p = @as(?[]const u8, null),
        .audit_m = @as(?[]const u8, null),
        .swarm = if (swarm_json) |s| @as(?[]const u8, s) else null,
    }, .{}) catch return;
    defer aa.free(payload);
    const stmt = conn.prepare("INSERT INTO events (ts, source, kind, payload_json, order_id) VALUES (?, 'core', 'model_selection', ?, ?)") catch return;
    defer conn.finalize(stmt);
    db.bindInt(stmt, 1, health.nowMillis(conn)) catch return;
    db.bindText(stmt, 2, payload) catch return;
    db.bindInt(stmt, 3, child_order_id) catch return;
    _ = db.c.sqlite3_step(stmt);
}

/// Último payload de un evento de la orden (o null).
fn lastEventPayload(aa: std.mem.Allocator, conn: db.Connection, order_id: i64, kind: []const u8) ?std.json.Parsed(std.json.Value) {
    const stmt = conn.prepare("SELECT payload_json FROM events WHERE order_id = ? AND kind = ? ORDER BY id DESC LIMIT 1") catch return null;
    defer conn.finalize(stmt);
    db.bindInt(stmt, 1, order_id) catch return null;
    db.bindText(stmt, 2, kind) catch return null;
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) return null;
    const p = db.c.sqlite3_column_text(stmt, 0) orelse return null;
    const parsed = std.json.parseFromSlice(std.json.Value, aa, std.mem.span(@as([*:0]const u8, @ptrCast(p))), .{}) catch return null;
    if (parsed.value != .object) {
        parsed.deinit();
        return null;
    }
    return parsed;
}

/// `UPDATE … SET x = ? WHERE id = ?` con su resultado: un enlace de la hija
/// que no se guardó es un fallo de preparación, no un silencio.
fn delegateUpdate(conn: db.Connection, sql: []const u8, value: i64, id: i64) bool {
    const stmt = conn.prepare(sql) catch return false;
    defer conn.finalize(stmt);
    db.bindInt(stmt, 1, value) catch return false;
    db.bindInt(stmt, 2, id) catch return false;
    return db.c.sqlite3_step(stmt) == db.c.SQLITE_DONE;
}

/// `task_done` de la tarea productora (t1) de una orden hija delegada.
fn producerDonePayload(aa: std.mem.Allocator, conn: db.Connection, order_id: i64) ?std.json.Parsed(std.json.Value) {
    const stmt = conn.prepare("SELECT payload_json FROM events WHERE order_id = ? AND kind = 'task_done' AND json_extract(payload_json, '$.task_id') = 't1' ORDER BY id DESC LIMIT 1") catch return null;
    defer conn.finalize(stmt);
    db.bindInt(stmt, 1, order_id) catch return null;
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) return null;
    const p = db.c.sqlite3_column_text(stmt, 0) orelse return null;
    const parsed = std.json.parseFromSlice(std.json.Value, aa, std.mem.span(@as([*:0]const u8, @ptrCast(p))), .{}) catch return null;
    if (parsed.value != .object) {
        parsed.deinit();
        return null;
    }
    return parsed;
}

fn jsonStr(v: std.json.Value, key: []const u8) []const u8 {
    if (v != .object) return "";
    const x = v.object.get(key) orelse return "";
    return if (x == .string) x.string else "";
}

/// Remate D2: último `task_provider_failed` del auditor de una orden hija.
fn auditProviderFailure(aa: std.mem.Allocator, conn: db.Connection, order_id: i64, audit_task_id: []const u8) ?std.json.Parsed(std.json.Value) {
    const stmt = conn.prepare("SELECT payload_json FROM events WHERE order_id = ? AND kind = 'task_provider_failed' AND json_extract(payload_json, '$.task_id') = ? ORDER BY id DESC LIMIT 1") catch return null;
    defer conn.finalize(stmt);
    db.bindInt(stmt, 1, order_id) catch return null;
    db.bindText(stmt, 2, audit_task_id) catch return null;
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) return null;
    const p = db.c.sqlite3_column_text(stmt, 0) orelse return null;
    const parsed = std.json.parseFromSlice(std.json.Value, aa, std.mem.span(@as([*:0]const u8, @ptrCast(p))), .{}) catch return null;
    if (parsed.value != .object) {
        parsed.deinit();
        return null;
    }
    return parsed;
}

/// Motivo llano de «sin auditar» de una hija (propiedad de `a`).
fn unauditedReason(a: std.mem.Allocator, aa: std.mem.Allocator, conn: db.Connection, order_id: i64, audit_task_id: []const u8) ![]u8 {
    var parsed = auditProviderFailure(aa, conn, order_id, audit_task_id);
    defer if (parsed) |*p| p.deinit();
    const failure: ?delegation.AuditFailure = if (parsed) |p| .{
        .provider = jsonStr(p.value, "provider"),
        .model = jsonStr(p.value, "model"),
        .http_status = if (p.value.object.get("http_status")) |h| (if (h == .integer) h.integer else null) else null,
        .daily = if (p.value.object.get("rate_daily")) |d| (d == .bool and d.bool) else false,
        .said = jsonStr(p.value, "excerpt"),
    } else null;
    // Sin fallo de proveedor: el motivo con el que el motor descartó el
    // veredicto (`task_audit_unavailable_v1.error_msg`).
    var motor = if (failure == null) lastEventPayload(aa, conn, order_id, "task_audit_unavailable_v1") else null;
    defer if (motor) |*m| m.deinit();
    const detail: []const u8 = if (motor) |m| jsonStr(m.value, "error_msg") else "";
    return delegation.unauditedTextWith(a, failure, detail);
}

/// `bonEvent` que dice si se guardó: lo que se borra después depende de ello.
fn bonEventChecked(conn: db.Connection, order_id: i64, kind: []const u8, payload: []const u8) bool {
    const stmt = conn.prepare("INSERT INTO events (ts, source, kind, payload_json, order_id) VALUES (?, 'core', ?, ?, ?)") catch return false;
    defer conn.finalize(stmt);
    db.bindInt(stmt, 1, health.nowMillis(conn)) catch return false;
    db.bindText(stmt, 2, kind) catch return false;
    db.bindText(stmt, 3, payload) catch return false;
    db.bindInt(stmt, 4, order_id) catch return false;
    return db.c.sqlite3_step(stmt) == db.c.SQLITE_DONE;
}

/// Remate D6 (10-nov): retira el worktree de una subtarea YA integrada, igual
/// que la Colmena (best-of-N) retira los suyos al elegir: `spaces.archiveSpace`
/// (git worktree remove + `archived_at`; la rama y las filas se conservan).
/// Antes guarda en el ledger de la hija el informe de su auditor, que solo
/// vivía en el worktree. Devuelve null si se retiró, o la frase de por qué
/// sigue ahí (no se borra nada que no se haya podido guardar).
fn retireDelegateWorktree(aa: std.mem.Allocator, conn: db.Connection, child_order_id: i64, wt: []const u8, reports: []const []const u8, root: []const u8, buf: *[256]u8) ?[]const u8 {
    const space_id: i64 = blk: {
        const stmt = conn.prepare("SELECT space_id FROM orders WHERE id = ?") catch return "su worktree sigue en su sitio: no se pudo leer a qué espacio pertenece";
        defer conn.finalize(stmt);
        db.bindInt(stmt, 1, child_order_id) catch return "su worktree sigue en su sitio: no se pudo leer a qué espacio pertenece";
        if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW or db.c.sqlite3_column_type(stmt, 0) == db.c.SQLITE_NULL)
            return "su worktree sigue en su sitio: la subtarea no tiene un espacio registrado";
        break :blk db.c.sqlite3_column_int64(stmt, 0);
    };
    if (reports.len > 0) {
        var source = confined_fs.Root.init(aa, wt) catch return "su worktree sigue en su sitio: no se pudo abrir para guardar el informe de su auditor";
        defer source.deinit();
        for (reports) |rel| {
            const nested = std.fmt.allocPrint(aa, "orden-{d}\\{s}", .{ child_order_id, rel }) catch return "su worktree sigue en su sitio: sin memoria para guardar el informe de su auditor";
            defer aa.free(nested);
            std.mem.replaceScalar(u8, nested, '/', '\\');
            const content = source.readFileAlloc(aa, nested, 256 * 1024) catch |e| switch (e) {
                error.FileNotFound => source.readFileAlloc(aa, rel, 256 * 1024) catch return "su worktree sigue en su sitio: no se pudo leer el informe de su auditor para guardarlo",
                else => return "su worktree sigue en su sitio: no se pudo leer el informe de su auditor para guardarlo",
            };
            defer aa.free(content);
            const payload = std.json.Stringify.valueAlloc(aa, .{ .file = rel, .content = content }, .{}) catch return "su worktree sigue en su sitio: sin memoria para guardar el informe de su auditor";
            defer aa.free(payload);
            if (!bonEventChecked(conn, child_order_id, "delegation_audit_report_v1", payload))
                return "su worktree sigue en su sitio: no se pudo guardar el informe de su auditor en el registro";
        }
    }
    spaces.archiveSpace(aa, conn, space_id, root) catch |e|
        return std.fmt.bufPrint(buf, "su worktree sigue en su sitio: no se pudo retirar (detalle técnico: {s})", .{@errorName(e)}) catch "su worktree sigue en su sitio: no se pudo retirar";
    // el worktree ya salió; su rama también (decisión del propietario
    // del 12-nov). Si git no la borra, el worktree NO sigue ahí: se deja
    // dicho en la orden hija que la rama quedó en el repositorio.
    spaces.deleteSpaceBranch(aa, conn, space_id, root) catch |e| {
        std.log.warn("rama de la subtarea {d} sin borrar: {s}", .{ child_order_id, @errorName(e) });
        var pbuf: [128]u8 = undefined;
        const payload = std.fmt.bufPrint(&pbuf, "{{\"error\":\"{s}\"}}", .{@errorName(e)}) catch "{}";
        if (!bonEventChecked(conn, child_order_id, "delegation_branch_kept_v1", payload))
            std.log.err("delegation_branch_kept_v1 de la orden {d} sin registrar", .{child_order_id});
    };
    return null;
}

/// P1-3: ¿existe el par en el catálogo? Nube: fila en providers+models.
/// Agente externo: listado en la última detección (resolvePin sin
/// AgentUnavailable/ModelUnavailable). Otros motivos (sesión, binario,
/// facturación) no son «no existe»: los decide la comprobación previa.
fn delegatePairInCatalog(a: std.mem.Allocator, catalog: db.Connection, external: []const u8, provider: []const u8, model: []const u8) !bool {
    if (external_agents.isAgentProvider(provider)) {
        const pin = external_registry.resolvePin(a, catalog, external, provider, model) catch |e| switch (e) {
            error.OutOfMemory => return e,
            error.AgentUnavailable, error.ModelUnavailable => return false,
            else => return true,
        };
        pin.deinit(a);
        return true;
    }
    const q = try catalog.prepare("SELECT 1 FROM providers p JOIN models m ON m.provider_id = p.id WHERE p.name = ? AND m.model_name = ? LIMIT 1");
    defer catalog.finalize(q);
    try db.bindText(q, 1, provider);
    try db.bindText(q, 2, model);
    return switch (db.c.sqlite3_step(q)) {
        db.c.SQLITE_ROW => true,
        db.c.SQLITE_DONE => false,
        else => error.StepFailed,
    };
}

/// `delegate_tasks`: ver el bloque de arriba. Devuelve el JSON del resultado
/// (o `{error, detail}` con frase llana) propiedad de `allocator`.
fn delegateTasks(raw: ?*anyopaque, allocator: std.mem.Allocator, args_json: []const u8) anyerror![]u8 {
    const ctx: *DelegateCtx = @ptrCast(@alignCast(raw orelse return error.InvalidContext));
    ctx.retain();
    defer ctx.release();
    const st = ctx.st;
    const aa = st.arena.child_allocator;
    if (ctx.busy.swap(true, .acq_rel)) return delegationErrorJson(allocator, "busy", delegation.BUSY_TEXT);
    defer ctx.busy.store(false, .release);

    var req = delegation.parse(allocator, args_json) catch |e| switch (e) {
        error.OutOfMemory => return e,
        else => return delegationErrorJson(allocator, delegation.parseErrorCode(e), delegation.parseErrorText(e)),
    };
    defer req.deinit();
    if (delegationCancelRequested(st)) return delegationErrorJson(allocator, "cancelled", delegation.CANCELLED_TEXT);

    const is_memory = std.mem.eql(u8, st.runtime_path, ":memory:");
    // Conexión propia del hilo que delega (la conversación corre en otro).
    var owned_conn: ?db.Connection = null;
    defer if (owned_conn) |*c| c.close();
    const conn: db.Connection = if (is_memory) st.db_conn else blk: {
        const c = db.Connection.open(aa, st.runtime_path) catch
            return delegationErrorJson(allocator, "storage", "No se pudo abrir la base de datos de órdenes para delegar.");
        owned_conn = c;
        break :blk c;
    };

    // Sin git no hay worktrees: se dice y no se trabaja en el mismo espacio.
    if (!spaces.isGitRepo(aa, ctx.root)) {
        bonEvent(conn, ctx.parent_order_id, "delegation_blocked_v1", "{\"cause\":\"no_git\"}");
        return delegationErrorJson(allocator, "no_git", delegation.NO_GIT_TEXT);
    }

    // Un modelo pedido explícitamente pasa la MISMA comprobación previa que un
    // modelo fijado a mano en el compositor (order_preflight): gobernanza
    // vigente («Solo gratis», «Solo local»), clave, disponibilidad y cupo de
    // pago. Sin modelo, lo elige el router con esa misma gobernanza.
    {
        const mode_text = try external_registry.readSetting(aa, st.catalog.db, "governance_mode");
        defer aa.free(mode_text);
        const external = (try external_registry.lastKnown(aa, st.catalog.db, health.nowSeconds(st.catalog.db))) orelse try aa.dupe(u8, "[]");
        defer aa.free(external);
        // P1-3 (hueco de B1e): un par bien formado que no está en el catálogo
        // no tumba la delegación: esa subtarea va en selección automática y
        // su resultado lo dice (`model_note`), como el formato inválido.
        for (req.items) |*s| {
            const p = s.provider orelse continue;
            if (!try delegatePairInCatalog(aa, st.catalog.db, external, p, s.model.?)) try delegation.ignoreModel(s, req.allocator);
        }
        for (req.items, 0..) |s, i| {
            const p = s.provider orelse continue;
            const role = [_]@import("order_preflight.zig").Role{.{ .role = "ejecutor", .provider = p, .model = s.model.? }};
            const blocked = try @import("order_preflight.zig").check(aa, st.catalog.db, model_router.GovernanceMode.parse(mode_text), &role, external, conn);
            defer aa.free(blocked);
            if (@import("order_preflight.zig").allowed(blocked)) continue;
            const why = for (blocked) |found| {
                if (found.severity == .block) break found.reason;
            } else "bloqueado por la gobernanza";
            const d = try std.fmt.allocPrint(allocator, "No se delegó: la subtarea {d} pide {s}|{s} y no se puede usar ({s}). Quita «model» para que DevAgents elija uno con la gobernanza vigente, o cambia el ajuste en Configuración › Gobernanza.", .{ i + 1, p, s.model.?, why });
            defer allocator.free(d);
            return delegationErrorJson(allocator, "model_blocked", d);
        }
    }
    // Presupuesto ANTES de lanzar (como best-of-N): cada subtarea con un modelo
    // de pago pedido explícitamente necesita al menos una llamada autorizada.
    {
        var paid: u64 = 0;
        for (req.items) |s| {
            const p = s.provider orelse continue;
            if (external_agents.isAgentProvider(p)) continue;
            if (!model_router.catalogModelIsFree(st.catalog.db, p, s.model.?)) paid += 1;
        }
        if (paid > 0) {
            const est = spend_budget.estado(st.catalog.db);
            if (est.restantes() < paid) {
                const d = try std.fmt.allocPrint(allocator, "No se delegó: {d} subtarea(s) piden un modelo de pago y el presupuesto autorizado restante es {d}. Autoriza más en Configuración › Gobernanza o deja que DevAgents elija (respeta «Solo gratis»).", .{ paid, est.restantes() });
                defer allocator.free(d);
                return delegationErrorJson(allocator, "budget_insufficient", d);
            }
        }
    }

    const now = health.nowSeconds(conn);
    var router_storage: model_router.Router = undefined;
    const router_ptr = makeRouter(st, aa, &router_storage, conn);
    defer if (router_ptr) |r| r.deinitHealthCache();
    var memory_scratch: local_memory.LocalMemory = undefined;
    const memory_backend = st.memory.backendForConn(conn, &memory_scratch);
    var sup = superagent.Superagent.init(aa, conn, router_ptr, memory_backend, now);
    sup.rules_catalog = st.catalog.db;
    sup.setSwarmJson(st.swarm_models_json);

    const children = try allocator.alloc(DelegateChild, req.items.len);
    defer allocator.free(children);
    defer for (children) |*c| {
        if (c.owned_error) allocator.free(c.setup_error.?);
        if (c.has_rec) c.rec.outcome.?.deinit();
    };
    const child_project = try std.fmt.allocPrint(aa, "{s}delegada:{s}", .{ session_store.INTERNAL_PROJECT_PREFIX, ctx.project_id });
    defer aa.free(child_project);
    for (req.items, 0..) |*s, i| children[i] = .{ .index = i, .sub = s };

    // ── Preparar cada hija (fila, plan, asignación, worktree) ──────────────
    for (children) |*c| {
        const s = c.sub;
        const child_id = superagent.Superagent.insertOrderRow(conn, child_project, s.instruction, "running", now) catch {
            c.setup_error = "no se pudo crear la orden de la subtarea";
            continue;
        };
        c.order_id = child_id;
        if (!delegateUpdate(conn, "UPDATE orders SET parent_order_id = ? WHERE id = ?", ctx.parent_order_id, child_id)) {
            c.setup_error = "no se pudo enlazar la subtarea con la conversación";
            continue;
        }
        const plan_text = try delegation.planJson(aa, s.*);
        defer aa.free(plan_text);
        var plan = live_planner.planFromJson(aa, plan_text) catch {
            c.setup_error = "el plan de la subtarea no pasó la validación del planificador";
            continue;
        };
        const pid = sup.insertPlan(child_id, plan.understanding, &.{}) catch {
            plan.deinit();
            c.setup_error = "no se pudo guardar el plan de la subtarea";
            continue;
        };
        if (!delegateUpdate(conn, "UPDATE plans SET approved = ? WHERE id = ?", 1, pid)) {
            plan.deinit();
            c.setup_error = "no se pudo aprobar el plan de la subtarea";
            continue;
        }
        sup.setExecForcedModel(s.provider, s.model);
        sup.setAuditForcedModel(null, null);
        const assignments = sup.assignAndPersist(pid, plan.tasks) catch {
            plan.deinit();
            c.setup_error = "no se pudo asignar modelo a la subtarea con la gobernanza vigente";
            continue;
        };
        persistDelegateSelection(conn, aa, child_id, s.provider, s.model, st.swarm_models_json);
        // Worktree propio `orden-<conversación>-d<k>`.
        const name = try std.fmt.allocPrint(aa, "orden-{d}-d{d}", .{ ctx.parent_order_id, c.index + 1 });
        var cdiag: worktree_prepare.Diag = .{};
        var audit_ctx: WorktreeAuditCtx = .{ .st = st, .order_id = child_id };
        var sp = spaces.createSpace(aa, conn, child_project, name, .order, ctx.root, .{
            .order_id = child_id,
            .diag = &cdiag,
            .audit_fn = worktreeAuditSink,
            .audit_ctx = &audit_ctx,
        }) catch |e| {
            plan.deinit();
            for (assignments) |asg| asg.deinit(aa);
            aa.free(assignments);
            c.setup_error = if (cdiag.len > 0) (std.fmt.allocPrint(allocator, "no se pudo preparar el worktree de la subtarea: {s}", .{cdiag.msg()}) catch "no se pudo preparar el worktree de la subtarea") else (std.fmt.allocPrint(allocator, "no se pudo preparar el worktree de la subtarea ({s})", .{@errorName(e)}) catch "no se pudo preparar el worktree de la subtarea");
            // Las dos ramas reservan con `allocator` salvo el texto fijo de respaldo (OOM).
            c.owned_error = !std.mem.eql(u8, c.setup_error.?, "no se pudo preparar el worktree de la subtarea");
            _ = conn.tryCommitTerminal(child_id, "failed", "order_failed", "superagente", "{\"cause\":\"worktree_prepare_failed\"}", health.nowMillis(conn)) catch false;
            continue;
        };
        defer sp.deinit(aa);
        if (!delegateUpdate(conn, "UPDATE orders SET space_id = ? WHERE id = ?", sp.id, child_id)) {
            plan.deinit();
            for (assignments) |asg| asg.deinit(aa);
            aa.free(assignments);
            c.setup_error = "no se pudo enlazar la subtarea con su worktree";
            continue;
        }
        c.rec = .{
            .id = child_id,
            .db_id = child_id,
            .text = s.instruction,
            .project_id = child_project,
            .status = .running,
            .plan_json = null,
            .outcome = superagent.OrderOutcome{
                .allocator = aa,
                .order_id = child_id,
                .plan_id = pid,
                .status = .running,
                .plan = plan,
                .assignments = assignments,
                .discovery_needed = &.{},
                .discovery_missing = &.{},
                .discovery_needed_resources = &.{},
            },
            .questions = &.{},
            .created_at = now,
        };
        c.has_rec = true;
    }

    // Evento de arranque en la conversación: la cabina pinta una línea por subtarea.
    {
        var out: std.Io.Writer.Allocating = .init(aa);
        defer out.deinit();
        var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
        try js.beginObject();
        try js.objectField("count");
        try js.write(children.len);
        try js.objectField("subtasks");
        try js.beginArray();
        for (children) |*c| {
            try js.beginObject();
            try js.objectField("index");
            try js.write(c.index + 1);
            try js.objectField("role");
            try js.write(c.sub.role.label);
            try js.objectField("instruction");
            try js.write(c.sub.instruction[0..@min(c.sub.instruction.len, 160)]);
            try js.objectField("child_order_id");
            try js.write(c.order_id);
            try js.objectField("model");
            try js.write(if (c.sub.model) |m| @as(?[]const u8, m) else null);
            try js.objectField("setup_error");
            try js.write(c.setup_error);
            try js.endObject();
        }
        try js.endArray();
        try js.endObject();
        bonEvent(conn, ctx.parent_order_id, "delegation_started_v1", out.written());
    }

    // ── Lanzar en paralelo (en serie solo con la base en memoria de las pruebas) ──
    const runtime_path = try aa.dupeZ(u8, st.runtime_path);
    defer aa.free(runtime_path);
    const thread_ctxs = try allocator.alloc(DelegateThreadCtx, children.len);
    defer allocator.free(thread_ctxs);
    for (children, 0..) |*c, i| {
        if (c.setup_error != null) {
            c.done.store(true, .release);
            continue;
        }
        // «Detener» mientras se lanzaban: las que faltan no arrancan.
        if (delegationCancelRequested(st)) {
            c.skipped = true;
            c.done.store(true, .release);
            _ = conn.tryCommitTerminal(c.order_id, "cancelled", "order_cancelled", "superagente", "{\"cause\":\"delegation_cancelled\"}", health.nowMillis(conn)) catch false;
            continue;
        }
        st.dispatch_registry.begin(c.order_id, false, GetTickCount64()) catch {
            c.setup_error = "el despacho de la subtarea no pudo registrarse";
            c.done.store(true, .release);
            continue;
        };
        c.token = live_worker.CancellationToken.create(std.heap.page_allocator) catch null;
        if (c.token) |tok| _ = st.dispatch_registry.attachCancellationToken(c.order_id, tok);
        c.started_ms = GetTickCount64();
        thread_ctxs[i] = .{ .ctx = ctx, .child = c, .runtime_path = runtime_path };
        if (is_memory) {
            const t0 = GetTickCount64();
            c.result = if (ctx.dispatch_fn) |f| f(st, &c.rec, conn) else dispatchApprovedOrder(st, &c.rec, conn, true);
            c.elapsed_ms = GetTickCount64() - t0;
            c.done.store(true, .release);
        } else {
            c.thread = std.Thread.spawn(.{}, delegateChildThread, .{&thread_ctxs[i]}) catch blk: {
                c.setup_error = "no se pudo lanzar el hilo de la subtarea";
                c.done.store(true, .release);
                break :blk null;
            };
        }
    }

    // Espera con «Detener»: la cancelación de la conversación corta TODAS las hijas.
    var cancelled = false;
    while (true) {
        var all_done = true;
        for (children) |*c| if (!c.done.load(.acquire)) {
            all_done = false;
        };
        if (all_done) break;
        if (!cancelled and delegationCancelRequested(st)) {
            cancelled = true;
            for (children) |*c| if (!c.done.load(.acquire)) {
                c.cut = true;
                _ = st.dispatch_registry.requestCancel(c.order_id);
            };
        }
        Sleep(100);
    }
    for (children) |*c| {
        if (c.thread) |t| t.join();
        if (c.order_id != 0 and c.started_ms != 0) {
            st.dispatch_registry.finish(c.order_id, c.result == .ok);
            st.dispatch_registry.joinIfFinished(c.order_id);
        }
        if (c.token) |tok| tok.release();
        if (c.elapsed_ms == 0 and c.started_ms != 0) c.elapsed_ms = GetTickCount64() - c.started_ms;
    }
    if (!cancelled) cancelled = delegationCancelRequested(st);
    // Una hija que no llegó a despacharse no se queda «running» para siempre.
    for (children) |*c| if (c.setup_error) |why| if (c.order_id != 0) {
        const body = std.json.Stringify.valueAlloc(aa, .{ .cause = "delegation_setup_failed", .reason = why }, .{}) catch continue;
        defer aa.free(body);
        _ = conn.tryCommitTerminal(c.order_id, "failed", "order_failed", "superagente", body, health.nowMillis(conn)) catch false;
    };

    // ── Resultados, conflictos e integración ────────────────────────────────
    const changed = try allocator.alloc(?[]const []const u8, children.len);
    defer allocator.free(changed);
    const sets = try allocator.alloc(?best_of_n.ChangedSets, children.len);
    defer {
        for (sets) |s| if (s) |cs| best_of_n.freeChangedSets(aa, cs);
        allocator.free(sets);
    }
    const statuses = try allocator.alloc([]const u8, children.len);
    defer allocator.free(statuses);
    const verdicts = try allocator.alloc(best_of_n.Verdict, children.len);
    defer allocator.free(verdicts);
    const wt_paths = try allocator.alloc(?[]u8, children.len);
    defer {
        for (wt_paths) |p| if (p) |x| aa.free(x);
        allocator.free(wt_paths);
    }
    // Rutas DESTINO (relativas a la carpeta del proyecto) de lo que cada
    // subtarea cambió: sin la carpeta `orden-<hija>` del motor de órdenes y
    // sin el informe de su auditor. Con ellas se detectan los choques.
    const dests = try allocator.alloc([][]const u8, children.len);
    const reports = try allocator.alloc([][]const u8, children.len);
    defer {
        for (dests) |d| {
            for (d) |p| aa.free(p);
            aa.free(d);
        }
        allocator.free(dests);
        for (reports) |d| {
            for (d) |p| aa.free(p);
            aa.free(d);
        }
        allocator.free(reports);
    }
    for (dests) |*d| d.* = &.{};
    for (reports) |*d| d.* = &.{};
    for (children, 0..) |*c, i| {
        changed[i] = null;
        sets[i] = null;
        wt_paths[i] = null;
        var sbuf: [64]u8 = undefined;
        const s = if (c.order_id != 0) best_of_n.childStatus(conn, c.order_id, &sbuf) else "";
        statuses[i] = try allocator.dupe(u8, if (c.setup_error != null) "failed" else if (s.len > 0) s else "failed");
        verdicts[i] = if (c.order_id != 0) best_of_n.collectMetrics(conn, c.order_id, @intCast(c.elapsed_ms)).verdict else .none;
        var wbuf: [4096]u8 = undefined;
        if (c.order_id != 0) if (orderSpacePath(conn, c.order_id, &wbuf)) |wt| {
            wt_paths[i] = try aa.dupe(u8, wt);
            var abuf: [64]u8 = undefined;
            const prefix = std.fmt.bufPrint(&abuf, "orden-{d}", .{c.order_id}) catch null;
            sets[i] = best_of_n.changedFiles(aa, wt, prefix);
        };
        if (sets[i]) |cs| {
            dests[i] = try delegation.destinationFiles(aa, cs.copy, c.order_id, delegation.auditTaskId(c.sub.*), .work);
            reports[i] = try delegation.destinationFiles(aa, cs.copy, c.order_id, delegation.auditTaskId(c.sub.*), .audit_report);
        }
        // Solo se integra lo terminado y aprobado por su auditor; «sin
        // auditar» bloquea la entrega (decisión P0.1), igual que en la Colmena.
        const integrable = !cancelled and std.mem.eql(u8, statuses[i], "done") and verdicts[i] != .fail and verdicts[i] != .unavailable;
        if (integrable and sets[i] != null) changed[i] = dests[i];
    }
    defer for (statuses) |s| allocator.free(s);
    const conflict = try delegation.conflictMask(allocator, changed);
    defer allocator.free(conflict);

    var integrated_count: usize = 0;
    var out: std.Io.Writer.Allocating = .init(allocator);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    try js.beginObject();
    try js.objectField("ok");
    try js.write(!cancelled);
    try js.objectField("cancelled");
    try js.write(cancelled);
    try js.objectField("subtasks");
    try js.beginArray();
    for (children, 0..) |*c, i| {
        var integrated = false;
        var integrate_error: ?[]const u8 = null;
        var integrate_buf: [256]u8 = undefined;
        if (changed[i] != null and !conflict[i]) {
            // La salida de la hija vive en `orden-<hija>` de su worktree; la
            // conversación de DevAgents trabaja en la RAÍZ del proyecto (como
            // Directo), así que se reancla a la raíz. El informe del auditor
            // queda como evidencia en el worktree.
            var from_buf: [64]u8 = undefined;
            const remap: ?best_of_n.PathRemap = if (std.fmt.bufPrint(&from_buf, "orden-{d}", .{c.order_id})) |from| .{ .from = from, .to = "" } else |_| null;
            const owns: []const []const u8 = @ptrCast(c.sub.files);
            if (best_of_n.applyWinnerSkipping(aa, wt_paths[i].?, ctx.root, owns, remap, reports[i])) |_| {
                integrated = true;
                integrated_count += 1;
            } else |e| {
                // Frase llana para el modelo y la cabina; el nombre del error
                // queda solo como detalle técnico al final.
                integrate_error = std.fmt.bufPrint(&integrate_buf, "su trabajo no se pudo copiar a la carpeta del proyecto; queda en su worktree (detalle técnico: {s})", .{@errorName(e)}) catch "su trabajo no se pudo copiar a la carpeta del proyecto; queda en su worktree";
            }
        }
        // Motivo llano del fallo (order_failed de la hija) si lo hay.
        var failed_reason: []const u8 = "";
        var failed_parsed = if (c.order_id != 0) lastEventPayload(aa, conn, c.order_id, "order_failed") else null;
        defer if (failed_parsed) |*p| p.deinit();
        if (failed_parsed) |p| {
            // Solo frases: `cause` es un código del motor (`tasks_failed`) y
            // la nota de la subtarea ya dice en llano por qué no se integró.
            failed_reason = jsonStr(p.value, "reason");
            if (failed_reason.len == 0) failed_reason = jsonStr(p.value, "detail");
        }
        var model_used: []const u8 = if (c.sub.model) |m| m else "";
        // El modelo que HIZO la subtarea es el de t1 (t2 es su auditor).
        var done_parsed = if (c.order_id != 0) producerDonePayload(aa, conn, c.order_id) else null;
        defer if (done_parsed) |*p| p.deinit();
        if (done_parsed) |p| {
            const mu = jsonStr(p.value, "model_used");
            if (mu.len > 0) model_used = mu;
        }
        // Una orden hija cerrada «sin auditar» (su auditor no dejó un
        // veredicto que se sostenga) no se presenta como PASS aunque la
        // puerta determinista haya pasado: el veredicto que cuenta es ese.
        // Una subtarea cortada por «Detener» (o que no llegó a arrancar) no
        // tiene un veredicto suyo que contar.
        const stopped = c.cut or c.skipped;
        const verdict_text: []const u8 = if (stopped or std.mem.eql(u8, statuses[i], "audit_unavailable")) "sin auditar" else switch (verdicts[i]) {
            .pass => "PASS",
            .fail => "FAIL",
            .unavailable => "sin auditar",
            .none => if (c.sub.role.task_type == .auditar) "—" else "sin auditar",
        };
        const files: []const []const u8 = dests[i];
        // Remate D6: lo integrado retira su worktree (como la Colmena); lo
        // que no se integró se conserva y se dice dónde está.
        // Una subtarea terminada y aprobada que no cambió nada tampoco deja
        // trabajo que conservar.
        const nothing_to_integrate = !integrated and !conflict[i] and !cancelled and !stopped and wt_paths[i] != null and dests[i].len == 0 and
            std.mem.eql(u8, statuses[i], "done") and verdicts[i] != .fail and verdicts[i] != .unavailable;
        const retire = integrated or nothing_to_integrate;
        var retire_buf: [256]u8 = undefined;
        const retire_error: ?[]const u8 = if (retire) retireDelegateWorktree(aa, conn, c.order_id, wt_paths[i].?, reports[i], ctx.root, &retire_buf) else null;
        const worktree_kept = wt_paths[i] != null and (!retire or retire_error != null);
        // Dónde revisar a mano lo que no se integró (dentro de la carpeta del
        // proyecto, así que el modelo puede leerlo con sus herramientas).
        const worktree_rel: ?[]const u8 = if (!worktree_kept) null else if (wt_paths[i]) |wt| (if (wt.len > ctx.root.len + 1 and std.ascii.startsWithIgnoreCase(wt, ctx.root)) wt[ctx.root.len + 1 ..] else wt) else null;
        // Lo que terminó ANTES de «Detener» conserva su estado real; solo lo
        // que se cortó (o no arrancó) se cuenta como cancelado.
        const status_text: []const u8 = if (stopped) "cancelled" else statuses[i];
        // Remate D2: «sin auditar» lleva su motivo real (cuota diaria del
        // auditor, límite, clave…) y qué puede hacer el usuario.
        // Solo lo que terminó y se quedó sin veredicto: una productora que
        // falló antes de la auditoría tiene su propio motivo (`order_failed`).
        const unaudited = !stopped and !cancelled and !integrated and !conflict[i] and c.setup_error == null and c.order_id != 0 and
            (std.mem.eql(u8, statuses[i], "audit_unavailable") or verdicts[i] == .unavailable);
        const audit_reason: ?[]u8 = if (unaudited) try unauditedReason(allocator, aa, conn, c.order_id, delegation.auditTaskId(c.sub.*)) else null;
        defer if (audit_reason) |r| allocator.free(r);
        const error_text: ?[]const u8 = if (stopped) null else if (c.setup_error) |e2| e2 else if (integrate_error) |ie| ie else if (audit_reason) |ar| ar else if (failed_reason.len > 0) failed_reason else if (retire_error) |re| re else null;
        const note_base: []const u8 = if (integrated)
            "integrada en la carpeta del proyecto"
        else if (conflict[i])
            "no se integró: toca un archivo que otra subtarea ya cambió"
        else if (stopped)
            "cancelada con «Detener»: no se integró"
        else if (cancelled)
            "terminó antes de «Detener», pero al detener no se integra nada"
        else if (verdicts[i] == .fail)
            "su auditor la rechazó: no se integró"
        else if (unaudited)
            "sin auditar: no se integró (la entrega se bloquea hasta que la audite otro modelo)"
        else if (!std.mem.eql(u8, statuses[i], "done"))
            "falló: no se integró"
        else
            "sin cambios que integrar";
        const note_owned: ?[]u8 = if (retire and retire_error == null)
            try std.fmt.allocPrint(allocator, "{s}; su worktree se retiró", .{note_base})
        else if (worktree_rel) |rel|
            try std.fmt.allocPrint(allocator, "{s}; su trabajo queda en su worktree {s}", .{ note_base, rel })
        else
            null;
        defer if (note_owned) |n| allocator.free(n);
        const note: []const u8 = note_owned orelse note_base;

        try js.beginObject();
        try js.objectField("index");
        try js.write(i + 1);
        try js.objectField("role");
        try js.write(c.sub.role.label);
        try js.objectField("child_order_id");
        try js.write(c.order_id);
        try js.objectField("status");
        try js.write(status_text);
        try js.objectField("verdict");
        try js.write(verdict_text);
        try js.objectField("model");
        try js.write(model_used);
        try js.objectField("duration_ms");
        try js.write(c.elapsed_ms);
        try js.objectField("files");
        try js.write(files);
        try js.objectField("worktree");
        try js.write(worktree_rel);
        try js.objectField("integrated");
        try js.write(integrated);
        try js.objectField("conflict");
        try js.write(conflict[i]);
        try js.objectField("unaudited");
        try js.write(unaudited);
        try js.objectField("retryable");
        try js.write(unaudited and worktree_kept);
        try js.objectField("note");
        try js.write(note);
        try js.objectField("error");
        try js.write(error_text);
        // P1-3: el `model` pedido que se ignoró (formato inválido o fuera del
        // catálogo) lo dice la propia subtarea.
        if (try delegation.modelNote(allocator, c.sub.*)) |model_note| {
            defer allocator.free(model_note);
            try js.objectField("model_note");
            try js.write(model_note);
        }
        try js.endObject();

        // Una línea por subtarea en el ledger de la conversación.
        const ev = std.json.Stringify.valueAlloc(aa, .{
            .index = i + 1,
            .role = c.sub.role.label,
            .child_order_id = c.order_id,
            .status = status_text,
            .verdict = verdict_text,
            .model = model_used,
            .duration_ms = c.elapsed_ms,
            .files = files,
            .integrated = integrated,
            .conflict = conflict[i],
            .unaudited = unaudited,
            .retryable = unaudited and worktree_kept,
            .worktree = worktree_rel,
            .note = note,
            .@"error" = error_text,
        }, .{}) catch null;
        if (ev) |payload| {
            defer aa.free(payload);
            bonEvent(conn, ctx.parent_order_id, "delegation_subtask_finished_v1", payload);
        }
        // Lo integrado se anuncia como cualquier escritura (Resultados, Cambios).
        if (integrated) for (files) |rel| {
            const abs = std.fs.path.join(aa, &.{ ctx.root, rel }) catch continue;
            defer aa.free(abs);
            const fw = std.json.Stringify.valueAlloc(aa, .{ .file_path = abs, .task_id = "delegada", .artifact_name = std.fs.path.basename(rel) }, .{}) catch continue;
            defer aa.free(fw);
            bonEvent(conn, ctx.parent_order_id, "file_written", fw);
        };
    }
    try js.endArray();
    try js.objectField("integrated");
    try js.write(integrated_count);
    try js.objectField("detail");
    if (cancelled) {
        try js.write(delegation.CANCELLED_TEXT);
    } else if (integrated_count < children.len) {
        // Remate D1/D2: lo no integrado no se da por hecho, y su motivo llega
        // al usuario tal cual (el campo `error` ya es una frase llana).
        const d = try std.fmt.allocPrint(allocator, "Se integraron {d} de {d} subtareas. Dile al usuario ese recuento y, por cada subtarea no integrada, copia su motivo (campo error) con lo que puede hacer y dónde quedó su trabajo (campo worktree). No las des por hechas.", .{ integrated_count, children.len });
        defer allocator.free(d);
        try js.write(d);
    } else {
        try js.write("Revisa cada subtarea (estado, veredicto, archivos y si se integró) antes de responder al usuario.");
    }
    try js.endObject();

    const fin = std.json.Stringify.valueAlloc(aa, .{ .cancelled = cancelled, .integrated = integrated_count, .count = children.len }, .{}) catch null;
    if (fin) |payload| {
        defer aa.free(payload);
        bonEvent(conn, ctx.parent_order_id, "delegation_finished_v1", payload);
    }
    return out.toOwnedSlice();
}

// ── FASE0-B2 (10-nov): «Reintentar auditoría» de una vuelta que delegó ─────
//
// La orden madre de una delegación no tiene tareas propias: su «sin auditar»
// es el de sus hijas. Reintentar no relanza la vuelta ni repite trabajo:
// reanuda SOLO las hijas que siguen `audit_unavailable` por el camino de
// siempre (dispatchApprovedOrder en reanudación: la tarea productora se
// restaura del checkpoint y solo corre la auditoría), integra las que ahora
// pasan con la misma fusión que `delegate_tasks`, deja una línea
// `delegation_audit_retry_v1` por hija en el ledger de la madre y vuelve a
// cerrar la madre con el recuento actualizado (`delegationTally`).

fn isDelegationMother(conn: db.Connection, order_id: i64) bool {
    const stmt = conn.prepare("SELECT 1 FROM events WHERE order_id = ? AND kind = 'delegation_finished_v1' LIMIT 1") catch return false;
    defer conn.finalize(stmt);
    db.bindInt(stmt, 1, order_id) catch return false;
    return db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW;
}

const DelegateRetryChild = struct {
    order_id: i64,
    /// Posición y rol con los que la subtarea se enseñó en la conversación.
    index: i64 = 0,
    role: []u8,
    text: []u8,
    project_id: []u8,
    rec: OrderRecord = undefined,
    has_rec: bool = false,
    setup_error: ?[]const u8 = null,
    token: ?*live_worker.CancellationToken = null,
    thread: ?std.Thread = null,
    started_ms: u64 = 0,
    elapsed_ms: u64 = 0,
    result: DaResult = .ok,
    /// Seguía auditándose cuando el usuario pulsó «Detener».
    cut: bool = false,
    done: std.atomic.Value(bool) = std.atomic.Value(bool).init(false),

    fn auditTaskId(self: *const DelegateRetryChild) []const u8 {
        if (!self.has_rec) return "t2";
        const tasks = self.rec.outcome.?.plan.tasks;
        return if (tasks.len > 0 and tasks[0].task_type == .auditar) "t1" else "t2";
    }
};

const DelegateRetry = struct {
    children: []DelegateRetryChild,

    fn freeChild(c: *DelegateRetryChild, aa: std.mem.Allocator) void {
        if (c.has_rec) c.rec.outcome.?.deinit();
        aa.free(c.role);
        aa.free(c.text);
        aa.free(c.project_id);
    }

    fn destroy(self: *DelegateRetry, aa: std.mem.Allocator) void {
        for (self.children) |*c| freeChild(c, aa);
        aa.free(self.children);
        aa.destroy(self);
    }
};

fn columnDupe(aa: std.mem.Allocator, stmt: ?*db.c.sqlite3_stmt, col: c_int) ![]u8 {
    const ptr = db.c.sqlite3_column_text(stmt, col) orelse return aa.dupe(u8, "");
    return aa.dupe(u8, ptr[0..@intCast(db.c.sqlite3_column_bytes(stmt, col))]);
}

/// Hijas de `parent_id` que siguen «sin auditar», con su plan aprobado
/// rehidratado. Corre en el hilo que llama a `da_order_resume_async` (usa
/// `st.db_conn`, como la rehidratación de una reanudación normal).
fn prepareDelegateRetry(st: *CoreState, parent_id: i64) !*DelegateRetry {
    const aa = st.arena.child_allocator;
    var list = std.ArrayList(DelegateRetryChild).empty;
    errdefer {
        for (list.items) |*c| DelegateRetry.freeChild(c, aa);
        list.deinit(aa);
    }
    {
        const last_line = "FROM events e WHERE e.order_id = o.parent_order_id AND e.kind = 'delegation_subtask_finished_v1' AND json_extract(e.payload_json, '$.child_order_id') = o.id ORDER BY e.id DESC LIMIT 1";
        const stmt = try st.db_conn.prepare(
            "SELECT o.id, o.user_prompt, o.project_id, " ++
                "COALESCE((SELECT json_extract(e.payload_json, '$.index') " ++ last_line ++ "), 0), " ++
                "COALESCE((SELECT json_extract(e.payload_json, '$.role') " ++ last_line ++ "), '') " ++
                "FROM orders o WHERE o.parent_order_id = ? AND o.status = 'audit_unavailable' ORDER BY o.id",
        );
        defer st.db_conn.finalize(stmt);
        try db.bindInt(stmt, 1, parent_id);
        var rc = db.c.sqlite3_step(stmt);
        while (rc == db.c.SQLITE_ROW) : (rc = db.c.sqlite3_step(stmt)) {
            const text = try columnDupe(aa, stmt, 1);
            errdefer aa.free(text);
            const project_id = try columnDupe(aa, stmt, 2);
            errdefer aa.free(project_id);
            const role = try columnDupe(aa, stmt, 4);
            errdefer aa.free(role);
            try list.append(aa, .{
                .order_id = db.c.sqlite3_column_int64(stmt, 0),
                .index = db.c.sqlite3_column_int64(stmt, 3),
                .role = role,
                .text = text,
                .project_id = project_id,
            });
        }
        if (rc != db.c.SQLITE_DONE) return error.StepFailed;
    }
    for (list.items) |*c| {
        // Un plan que no se puede rehidratar no impide reintentar las demás:
        // esa hija se cuenta como «sigue sin auditar» con su motivo.
        const outcome = loadPersistedPlannedOutcome(st, aa, c.order_id, 1) catch null;
        if (outcome == null) {
            c.setup_error = "no se pudo recuperar el plan aprobado de la subtarea; su trabajo sigue en su worktree";
            continue;
        }
        c.rec = .{
            .id = c.order_id,
            .db_id = c.order_id,
            .text = c.text,
            .project_id = c.project_id,
            .status = .audit_unavailable,
            .plan_json = null,
            .outcome = outcome,
            .questions = &.{},
            .created_at = health.nowSeconds(st.db_conn),
        };
        c.has_rec = true;
    }
    const self = try aa.create(DelegateRetry);
    errdefer aa.destroy(self);
    self.* = .{ .children = try list.toOwnedSlice(aa) };
    return self;
}

const DelegateRetryThreadCtx = struct {
    st: *CoreState,
    child: *DelegateRetryChild,
    runtime_path: [:0]const u8,
};

fn delegateRetryDispatch(st: *CoreState, c: *DelegateRetryChild, conn: db.Connection) void {
    const t0 = GetTickCount64();
    c.result = if (st.delegate_retry_dispatch_fn) |f| f(st, &c.rec, conn) else dispatchApprovedOrder(st, &c.rec, conn, true);
    c.elapsed_ms = GetTickCount64() - t0;
}

fn delegateRetryThread(t: *DelegateRetryThreadCtx) void {
    defer t.child.done.store(true, .release);
    var conn = db.Connection.open(t.st.arena.child_allocator, t.runtime_path) catch {
        t.child.result = err(.internal, "reintento de auditoría: no se pudo abrir la base de la subtarea");
        return;
    };
    defer conn.close();
    delegateRetryDispatch(t.st, t.child, conn);
}

/// Cierra la madre con el recuento vigente, con la misma regla que el cierre
/// de la vuelta (Remate D1): «sin auditar» si alguna hija sigue sin auditar,
/// `failed` si no se integró ninguna y `done` con el recuento en otro caso.
fn commitDelegationMother(st: *CoreState, conn: db.Connection, rec: *OrderRecord, parent_id: i64) DaResult {
    const aa = st.arena.child_allocator;
    var sup = superagent.Superagent.init(aa, conn, null, superagent.NoopMemory.backend(), health.nowSeconds(conn));
    sup.rules_catalog = st.catalog.db;
    const tally = sup.delegationTally(parent_id) catch return commitRetryFailure(st, conn, rec, parent_id, "no se pudo leer el recuento de la delegación");
    const resumen = std.fmt.allocPrint(aa, "{d} de {d} subtareas integradas", .{ tally.integrated, tally.count }) catch return commitRetryFailure(st, conn, rec, parent_id, "sin memoria");
    defer aa.free(resumen);
    const body = std.json.Stringify.valueAlloc(aa, .{
        .cause = if (tally.integrated < tally.count) "delegation_not_integrated" else "delegation_integrated",
        .reason = resumen,
        .integrated = tally.integrated,
        .count = tally.count,
        .unaudited = tally.unaudited,
        .tasks = 0,
        .audit_retry = true,
    }, .{}) catch return commitRetryFailure(st, conn, rec, parent_id, "sin memoria");
    defer aa.free(body);
    const now_ms = health.nowMillis(conn);
    const committed = (if (tally.unaudited > 0)
        conn.tryCommitTerminal(parent_id, "audit_unavailable", "order_audit_unavailable_v1", "superagente", body, now_ms)
    else if (tally.integrated == 0)
        conn.tryCommitTerminal(parent_id, "failed", "order_failed", "superagente", body, now_ms)
    else
        conn.tryCommitTerminal(parent_id, "done", "order_done", "superagente", body, now_ms)) catch
        return commitRetryFailure(st, conn, rec, parent_id, "no se pudo guardar el estado final de la conversación");
    syncRecStatusFromDb(conn, rec);
    if (!committed) return err(.invalid_state, "reintento de auditoría: la conversación ya tenía un estado final");
    return .ok;
}

/// El reintento no pudo completarse por un fallo interno: la madre vuelve a
/// «sin auditar» (nunca se queda «en curso») y el motivo queda en el ledger.
fn commitRetryFailure(st: *CoreState, conn: db.Connection, rec: *OrderRecord, parent_id: i64, why: []const u8) DaResult {
    const aa = st.arena.child_allocator;
    const fallback = "{\"cause\":\"delegation_audit_retry_failed\",\"tasks\":0,\"audit_retry\":true}";
    const body = std.json.Stringify.valueAlloc(aa, .{ .cause = "delegation_audit_retry_failed", .reason = why, .tasks = 0, .audit_retry = true }, .{}) catch null;
    defer if (body) |b| aa.free(b);
    const committed = conn.tryCommitTerminal(parent_id, "audit_unavailable", "order_audit_unavailable_v1", "superagente", body orelse fallback, health.nowMillis(conn)) catch false;
    syncRecStatusFromDb(conn, rec);
    if (!committed) return err(.internal, "reintento de auditoría: falló y no se pudo devolver la conversación a «sin auditar»");
    return err(.internal, "reintento de auditoría: no se pudo completar; la conversación sigue «sin auditar»");
}

fn freePathLists(aa: std.mem.Allocator, lists: [][][]const u8) void {
    for (lists) |d| {
        for (d) |p| aa.free(p);
        aa.free(d);
    }
    aa.free(lists);
}

fn retryDelegatedAudits(st: *CoreState, rec: *OrderRecord, conn: db.Connection, retry: *DelegateRetry) DaResult {
    const aa = st.arena.child_allocator;
    const parent_id = rec.db_id orelse rec.id;
    const children = retry.children;
    const is_memory = std.mem.eql(u8, st.runtime_path, ":memory:");

    // La madre pasa a «en curso» mientras se reaudita; si otro camino ya la
    // movió de «sin auditar», no se toca nada.
    {
        const upd = conn.prepare("UPDATE orders SET status = 'running' WHERE id = ? AND status = 'audit_unavailable'") catch
            return err(.internal, "reintento de auditoría: no se pudo marcar la conversación en curso");
        defer conn.finalize(upd);
        db.bindInt(upd, 1, parent_id) catch return err(.internal, "reintento de auditoría: no se pudo marcar la conversación en curso");
        if (db.c.sqlite3_step(upd) != db.c.SQLITE_DONE or conn.changes() == 0)
            return err(.invalid_state, "reintento de auditoría: la conversación ya no está «sin auditar»");
    }
    rec.status = .running;

    {
        var ids = std.ArrayList(i64).empty;
        defer ids.deinit(aa);
        for (children) |*c| ids.append(aa, c.order_id) catch return commitRetryFailure(st, conn, rec, parent_id, "sin memoria");
        const payload = std.json.Stringify.valueAlloc(aa, .{ .count = children.len, .children = ids.items }, .{}) catch return commitRetryFailure(st, conn, rec, parent_id, "sin memoria");
        defer aa.free(payload);
        bonEvent(conn, parent_id, "delegation_audit_retry_started_v1", payload);
    }

    // Carpeta del proyecto donde se integra: la que recordó la vuelta o, tras
    // un reinicio, la base del worktree de la primera hija que lo conserva.
    var root_buf: [4096]u8 = undefined;
    var root: ?[]const u8 = directOrderRoot(st, parent_id, &root_buf);
    const wt_bufs = aa.alloc([4096]u8, children.len) catch return commitRetryFailure(st, conn, rec, parent_id, "sin memoria");
    defer aa.free(wt_bufs);
    const wts = aa.alloc(?[]const u8, children.len) catch return commitRetryFailure(st, conn, rec, parent_id, "sin memoria");
    defer aa.free(wts);
    for (children, 0..) |*c, i| {
        // P1-4: registrada Y en disco; sin ella la hija no es reintentable.
        wts[i] = liveChildWorktree(conn, c.order_id, &wt_bufs[i]);
        if (wts[i] == null and c.setup_error == null) c.setup_error = DELEGATE_NO_WORKTREE_TEXT;
        if (root == null) if (wts[i]) |wt| if (spaces.baseOfWorktree(wt)) |base| {
            @memcpy(root_buf[0..base.len], base);
            root = root_buf[0..base.len];
        };
    }

    // ── Reauditar: un hilo y una conexión por hija (en serie con :memory:) ──
    const mother_token = st.dispatch_registry.retainCancellationToken(parent_id);
    defer if (mother_token) |t| @constCast(t).release();
    const runtime_path = aa.dupeZ(u8, st.runtime_path) catch return commitRetryFailure(st, conn, rec, parent_id, "sin memoria");
    defer aa.free(runtime_path);
    const thread_ctxs = aa.alloc(DelegateRetryThreadCtx, children.len) catch return commitRetryFailure(st, conn, rec, parent_id, "sin memoria");
    defer aa.free(thread_ctxs);
    for (children, 0..) |*c, i| {
        if (c.setup_error == null and root == null) c.setup_error = "no se pudo localizar la carpeta del proyecto de esta conversación";
        if (c.setup_error != null or (mother_token != null and mother_token.?.isCancelled())) {
            c.done.store(true, .release);
            continue;
        }
        st.dispatch_registry.begin(c.order_id, false, GetTickCount64()) catch {
            c.setup_error = "el reintento de la auditoría no pudo registrarse (puede haber otro en marcha)";
            c.done.store(true, .release);
            continue;
        };
        c.token = live_worker.CancellationToken.create(std.heap.page_allocator) catch null;
        if (c.token) |tok| _ = st.dispatch_registry.attachCancellationToken(c.order_id, tok);
        c.started_ms = GetTickCount64();
        if (is_memory) {
            delegateRetryDispatch(st, c, conn);
            c.done.store(true, .release);
        } else {
            thread_ctxs[i] = .{ .st = st, .child = c, .runtime_path = runtime_path };
            c.thread = std.Thread.spawn(.{}, delegateRetryThread, .{&thread_ctxs[i]}) catch blk: {
                c.setup_error = "no se pudo lanzar el hilo del reintento de la auditoría";
                c.done.store(true, .release);
                break :blk null;
            };
        }
    }
    var cancelled = false;
    while (true) {
        var all_done = true;
        for (children) |*c| if (!c.done.load(.acquire)) {
            all_done = false;
        };
        if (all_done) break;
        if (!cancelled and mother_token != null and mother_token.?.isCancelled()) {
            cancelled = true;
            for (children) |*c| if (!c.done.load(.acquire)) {
                c.cut = true;
                _ = st.dispatch_registry.requestCancel(c.order_id);
            };
        }
        Sleep(100);
    }
    for (children) |*c| {
        if (c.thread) |t| t.join();
        if (c.started_ms != 0) {
            st.dispatch_registry.finish(c.order_id, c.result == .ok);
            st.dispatch_registry.joinIfFinished(c.order_id);
        }
        if (c.token) |tok| tok.release();
    }
    if (!cancelled) cancelled = mother_token != null and mother_token.?.isCancelled();

    // ── Resultado de cada hija e integración de las que ahora pasan ────────
    const dests = aa.alloc([][]const u8, children.len) catch return commitRetryFailure(st, conn, rec, parent_id, "sin memoria");
    for (dests) |*d| d.* = &.{};
    defer freePathLists(aa, dests);
    const reports = aa.alloc([][]const u8, children.len) catch return commitRetryFailure(st, conn, rec, parent_id, "sin memoria");
    for (reports) |*d| d.* = &.{};
    defer freePathLists(aa, reports);
    const changed = aa.alloc(?[]const []const u8, children.len) catch return commitRetryFailure(st, conn, rec, parent_id, "sin memoria");
    defer aa.free(changed);
    const status_bufs = aa.alloc([64]u8, children.len) catch return commitRetryFailure(st, conn, rec, parent_id, "sin memoria");
    defer aa.free(status_bufs);
    const statuses = aa.alloc([]const u8, children.len) catch return commitRetryFailure(st, conn, rec, parent_id, "sin memoria");
    defer aa.free(statuses);
    const verdicts = aa.alloc(best_of_n.Verdict, children.len) catch return commitRetryFailure(st, conn, rec, parent_id, "sin memoria");
    defer aa.free(verdicts);
    for (children, 0..) |*c, i| {
        changed[i] = null;
        statuses[i] = best_of_n.childStatus(conn, c.order_id, &status_bufs[i]);
        verdicts[i] = best_of_n.collectMetrics(conn, c.order_id, @intCast(c.elapsed_ms)).verdict;
        const wt = wts[i] orelse continue;
        var abuf: [64]u8 = undefined;
        const prefix = std.fmt.bufPrint(&abuf, "orden-{d}", .{c.order_id}) catch null;
        const cs = best_of_n.changedFiles(aa, wt, prefix) orelse continue;
        defer best_of_n.freeChangedSets(aa, cs);
        dests[i] = delegation.destinationFiles(aa, cs.copy, c.order_id, c.auditTaskId(), .work) catch return commitRetryFailure(st, conn, rec, parent_id, "sin memoria");
        reports[i] = delegation.destinationFiles(aa, cs.copy, c.order_id, c.auditTaskId(), .audit_report) catch return commitRetryFailure(st, conn, rec, parent_id, "sin memoria");
        // Solo se integra lo terminado y aprobado por su auditor (P0.1).
        const integrable = !cancelled and c.setup_error == null and c.started_ms != 0 and std.mem.eql(u8, statuses[i], "done") and verdicts[i] != .fail and verdicts[i] != .unavailable;
        if (integrable) changed[i] = dests[i];
    }
    const conflict = delegation.conflictMask(aa, changed) catch return commitRetryFailure(st, conn, rec, parent_id, "sin memoria");
    defer aa.free(conflict);

    for (children, 0..) |*c, i| {
        var integrated = false;
        var integrate_buf: [256]u8 = undefined;
        var integrate_error: ?[]const u8 = null;
        if (changed[i] != null and !conflict[i]) {
            var from_buf: [64]u8 = undefined;
            const remap: ?best_of_n.PathRemap = if (std.fmt.bufPrint(&from_buf, "orden-{d}", .{c.order_id})) |from| .{ .from = from, .to = "" } else |_| null;
            if (best_of_n.applyWinnerSkipping(aa, wts[i].?, root.?, &.{}, remap, reports[i])) |_| {
                integrated = true;
            } else |e| {
                integrate_error = std.fmt.bufPrint(&integrate_buf, "su trabajo no se pudo copiar a la carpeta del proyecto; queda en su worktree (detalle técnico: {s})", .{@errorName(e)}) catch "su trabajo no se pudo copiar a la carpeta del proyecto; queda en su worktree";
            }
        }
        const attempted = c.started_ms != 0 and !c.cut;
        const still_unaudited = !integrated and (!attempted or cancelled or std.mem.eql(u8, statuses[i], "audit_unavailable") or
            (std.mem.eql(u8, statuses[i], "done") and verdicts[i] == .unavailable));
        const approved = attempted and !cancelled and std.mem.eql(u8, statuses[i], "done") and verdicts[i] != .fail and verdicts[i] != .unavailable;
        const nothing_to_integrate = approved and !integrated and !conflict[i] and wts[i] != null and dests[i].len == 0;
        const retire = integrated or nothing_to_integrate;
        var retire_buf: [256]u8 = undefined;
        const retire_error: ?[]const u8 = if (retire) retireDelegateWorktree(aa, conn, c.order_id, wts[i].?, reports[i], root.?, &retire_buf) else null;
        const worktree_kept = wts[i] != null and (!retire or retire_error != null);
        const worktree_rel: ?[]const u8 = if (!worktree_kept) null else if (wts[i]) |wt| (if (root != null and wt.len > root.?.len + 1 and std.ascii.startsWithIgnoreCase(wt, root.?)) wt[root.?.len + 1 ..] else wt) else null;
        const audit_reason: ?[]u8 = if (still_unaudited and attempted and !cancelled) (unauditedReason(aa, aa, conn, c.order_id, c.auditTaskId()) catch return commitRetryFailure(st, conn, rec, parent_id, "sin memoria")) else null;
        defer if (audit_reason) |r| aa.free(r);
        var failed_parsed = if (std.mem.eql(u8, statuses[i], "failed")) lastEventPayload(aa, conn, c.order_id, "order_failed") else null;
        defer if (failed_parsed) |*p| p.deinit();
        const failed_reason: []const u8 = if (failed_parsed) |p| jsonStr(p.value, "reason") else "";
        const error_text: ?[]const u8 = if (c.setup_error) |e2| e2 else if (integrate_error) |ie| ie else if (audit_reason) |ar| ar else if (failed_reason.len > 0) failed_reason else if (retire_error) |re| re else null;
        const verdict_text: []const u8 = if (still_unaudited) "sin auditar" else switch (verdicts[i]) {
            .pass => "PASS",
            .fail => "FAIL",
            .unavailable => "sin auditar",
            .none => "—",
        };
        const note_base: []const u8 = if (integrated)
            "auditoría reintentada: aprobada e integrada en la carpeta del proyecto"
        else if (c.setup_error != null)
            "no se pudo reintentar su auditoría: sigue sin auditar"
        else if (!attempted or cancelled)
            "reintento detenido con «Detener»: sigue sin auditar"
        else if (conflict[i])
            "auditoría reintentada: aprobada, pero no se integró porque toca un archivo que otra subtarea ya cambió"
        else if (verdicts[i] == .fail)
            "auditoría reintentada: su auditor la rechazó, no se integró"
        else if (still_unaudited)
            "auditoría reintentada: sigue sin auditar, no se integró"
        else if (!std.mem.eql(u8, statuses[i], "done"))
            "auditoría reintentada: la subtarea falló, no se integró"
        else if (integrate_error != null)
            "auditoría reintentada: aprobada, pero no se pudo integrar"
        else
            "auditoría reintentada: aprobada, sin cambios que integrar";
        const note_owned: ?[]u8 = if (retire and retire_error == null)
            (std.fmt.allocPrint(aa, "{s}; su worktree se retiró", .{note_base}) catch return commitRetryFailure(st, conn, rec, parent_id, "sin memoria"))
        else if (worktree_rel) |rel|
            (std.fmt.allocPrint(aa, "{s}; su trabajo queda en su worktree {s}", .{ note_base, rel }) catch return commitRetryFailure(st, conn, rec, parent_id, "sin memoria"))
        else
            null;
        defer if (note_owned) |n| aa.free(n);
        const files: []const []const u8 = dests[i];
        const role: []const u8 = c.role;
        const ev = std.json.Stringify.valueAlloc(aa, .{
            .index = c.index,
            .role = role,
            .child_order_id = c.order_id,
            .status = if (!attempted) "audit_unavailable" else statuses[i],
            .verdict = verdict_text,
            .duration_ms = c.elapsed_ms,
            .files = files,
            .integrated = integrated,
            .conflict = conflict[i],
            .unaudited = still_unaudited,
            .resolved = !still_unaudited,
            // P1-4: solo se puede volver a reintentar lo que conserva su copia
            // de trabajo; la cabina no ofrece «Reintentar» si ninguna la tiene.
            .retryable = still_unaudited and worktree_kept,
            .worktree = worktree_rel,
            .note = @as([]const u8, note_owned orelse note_base),
            .@"error" = error_text,
        }, .{}) catch return commitRetryFailure(st, conn, rec, parent_id, "sin memoria");
        defer aa.free(ev);
        // El recuento de la madre sale de estas líneas: si una no se guarda,
        // el cierre no puede darse por bueno.
        if (!bonEventChecked(conn, parent_id, "delegation_audit_retry_v1", ev))
            return commitRetryFailure(st, conn, rec, parent_id, "no se pudo guardar el resultado del reintento");
        // Lo integrado se anuncia como cualquier escritura (Resultados, Cambios).
        if (integrated) for (files) |rel| {
            const abs = std.fs.path.join(aa, &.{ root.?, rel }) catch continue;
            defer aa.free(abs);
            const fw = std.json.Stringify.valueAlloc(aa, .{ .file_path = abs, .task_id = "delegada", .artifact_name = std.fs.path.basename(rel) }, .{}) catch continue;
            defer aa.free(fw);
            bonEvent(conn, parent_id, "file_written", fw);
        };
    }
    return commitDelegationMother(st, conn, rec, parent_id);
}

const GetTempPathA = if (@import("builtin").os.tag == .windows) struct {
    extern "kernel32" fn GetTempPathA(size: u32, buffer: [*]u8) callconv(.winapi) u32;
}.GetTempPathA else @import("platform.zig").tempPath;

/// Despacho simulado de una hija (el del motor real necesita proveedores): en
/// su worktree escribe el primer archivo declarado con la instrucción como
/// contenido, deja el veredicto del auditor y cierra la orden `done`. Una
/// instrucción que empieza por «FALLA» cierra `failed`; por «RECHAZA», el
/// auditor da FAIL.
fn testDelegateDispatch(st: *CoreState, rec: *OrderRecord, conn: db.Connection) DaResult {
    const id = rec.db_id.?;
    // «DETENER»: el usuario pulsa «Detener» mientras esta subtarea trabaja.
    if (std.mem.startsWith(u8, rec.text, "DETENER")) {
        st.plan_mutex.lock();
        st.plan_cancel_requested = true;
        st.plan_mutex.unlock();
    }
    if (std.mem.startsWith(u8, rec.text, "FALLA")) {
        _ = conn.tryCommitTerminal(id, "failed", "order_failed", "superagente", "{\"cause\":\"all_tasks_failed\",\"reason\":\"el modelo no produjo el archivo\"}", health.nowMillis(conn)) catch false;
        return .ok;
    }
    var buf: [4096]u8 = undefined;
    const wt = orderSpacePath(conn, id, &buf) orelse return err(.internal, "sin worktree");
    const owns = rec.outcome.?.plan.tasks[0].owns;
    var threaded = std.Io.Threaded.init(std.testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var dir = std.Io.Dir.cwd().openDir(io, wt, .{}) catch return err(.internal, "worktree ilegible");
    defer dir.close(io);
    // Como el motor de órdenes: la salida va a `orden-<id>/` y el auditor deja
    // su informe `t2.txt` al lado.
    var sub_buf: [64]u8 = undefined;
    const sub = std.fmt.bufPrint(&sub_buf, "orden-{d}", .{id}) catch return err(.internal, "ruta");
    dir.createDirPath(io, sub) catch return err(.internal, "no se pudo crear la carpeta de la orden");
    var out_dir = dir.openDir(io, sub, .{}) catch return err(.internal, "carpeta de la orden ilegible");
    defer out_dir.close(io);
    out_dir.writeFile(io, .{ .sub_path = if (owns.len > 0) owns[0] else "salida.txt", .data = rec.text }) catch return err(.internal, "no se pudo escribir");
    // «SINAUDITAR»: el auditor (OpenRouter gratuito) devuelve 429 por la cuota
    // diaria y la hija cierra «sin auditar», como en el recorrido en vivo.
    if (std.mem.startsWith(u8, rec.text, "SINAUDITAR")) {
        bonEvent(conn, id, "task_done", "{\"task_id\":\"t1\",\"success\":true,\"model_used\":\"modelo-simulado\"}");
        bonEvent(conn, id, "task_provider_failed", "{\"task_id\":\"t2\",\"provider\":\"OpenRouter\",\"model\":\"google/gemma:free\",\"status\":\"rate_limited\",\"http_status\":429,\"reason\":\"cuota o limite del proveedor\",\"excerpt\":\"[texto externo] Rate limit exceeded: free-models-per-day.\",\"rate_daily\":true}");
        bonEvent(conn, id, "task_audit_unavailable_v1", "{\"task_id\":\"t2\",\"success\":false,\"cause\":\"audit_unavailable\"}");
        _ = conn.tryCommitTerminal(id, "audit_unavailable", "order_audit_unavailable_v1", "superagente", "{\"completed\":1,\"failed\":0}", health.nowMillis(conn)) catch false;
        return .ok;
    }
    out_dir.writeFile(io, .{ .sub_path = "t2.txt", .data = "PASS: informe del auditor" }) catch return err(.internal, "no se pudo escribir el informe");
    bonEvent(conn, id, "task_done", "{\"task_id\":\"t1\",\"success\":true,\"model_used\":\"modelo-simulado\"}");
    bonEvent(conn, id, "task_audit", if (std.mem.startsWith(u8, rec.text, "RECHAZA")) "{\"task_id\":\"t2\",\"verdict\":\"FAIL\"}" else "{\"task_id\":\"t2\",\"verdict\":\"PASS\"}");
    _ = conn.tryCommitTerminal(id, "done", "order_done", "superagente", "{\"completed\":2,\"failed\":0}", health.nowMillis(conn)) catch false;
    return .ok;
}

fn testDelegateRoot(a: std.mem.Allocator, io: std.Io, with_git: bool) ![]u8 {
    var buffer: [4096]u8 = undefined;
    const n = GetTempPathA(buffer.len, &buffer);
    if (n == 0 or n >= buffer.len) return error.TestUnexpectedResult;
    const root = try std.fmt.allocPrint(a, "{s}devagents-delegate-{d}", .{ buffer[0..n], GetTickCount64() });
    errdefer a.free(root);
    try std.Io.Dir.cwd().createDirPath(io, root);
    if (with_git) {
        var init = try headless_adapter.defaultCapture(a, &.{ "git", "init", root }, null);
        defer init.deinit(a);
        try std.testing.expectEqual(@as(u32, 0), init.exit_code);
        var commit = try headless_adapter.defaultCapture(a, &.{ "git", "-c", "user.name=B", "-c", "user.email=b@test", "-c", "commit.gpgsign=false", "commit", "--allow-empty", "-m", "base" }, root);
        defer commit.deinit(a);
        try std.testing.expectEqual(@as(u32, 0), commit.exit_code);
    }
    return root;
}

fn testDelegateResult(a: std.mem.Allocator, json: []const u8) !std.json.Parsed(std.json.Value) {
    return std.json.parseFromSlice(std.json.Value, a, json, .{});
}

test "USUARIO-NUEVO B: delegate_tasks sin git no delega ni trabaja en el mismo espacio" {
    const a = std.testing.allocator;
    var threaded = std.Io.Threaded.init(a, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    const root = try testDelegateRoot(a, io, false);
    defer a.free(root);
    defer std.Io.Dir.cwd().deleteTree(io, root) catch |e| std.debug.print("delegate cleanup: {s}\n", .{@errorName(e)});
    const parent = try superagent.Superagent.insertOrderRow(st.db_conn, "p", "conversación", "running", 1);
    const ctx = try DelegateCtx.create(st, parent, "p", root);
    defer ctx.release();
    ctx.dispatch_fn = testDelegateDispatch;
    const out = try delegateTasks(ctx, a, "{\"tasks\":[{\"role\":\"programar\",\"instruction\":\"crea a.txt\",\"files\":[\"a.txt\"]}]}");
    defer a.free(out);
    var r = try testDelegateResult(a, out);
    defer r.deinit();
    try std.testing.expectEqualStrings("no_git", r.value.object.get("error").?.string);
    try std.testing.expect(std.mem.indexOf(u8, r.value.object.get("detail").?.string, "Iniciar git aquí") != null);
    // Ninguna orden hija creada; el bloqueo queda en el ledger de la conversación.
    const q = try st.db_conn.prepare("SELECT (SELECT COUNT(*) FROM orders WHERE parent_order_id = ?), (SELECT COUNT(*) FROM events WHERE order_id = ? AND kind = 'delegation_blocked_v1')");
    defer st.db_conn.finalize(q);
    try db.bindInt(q, 1, parent);
    try db.bindInt(q, 2, parent);
    try std.testing.expect(db.c.sqlite3_step(q) == db.c.SQLITE_ROW);
    try std.testing.expectEqual(@as(i64, 0), db.c.sqlite3_column_int64(q, 0));
    try std.testing.expectEqual(@as(i64, 1), db.c.sqlite3_column_int64(q, 1));
}

test "USUARIO-NUEVO B: delegate_tasks valida, limita, respeta «Detener» y no se solapa" {
    const a = std.testing.allocator;
    var threaded = std.Io.Threaded.init(a, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    const root = try testDelegateRoot(a, io, true);
    defer a.free(root);
    defer std.Io.Dir.cwd().deleteTree(io, root) catch |e| std.debug.print("delegate cleanup: {s}\n", .{@errorName(e)});
    const ctx = try DelegateCtx.create(st, 1, "p", root);
    defer ctx.release();
    ctx.dispatch_fn = testDelegateDispatch;
    const cases = [_]struct { args: []const u8, code: []const u8 }{
        .{ .args = "{\"tasks\":[{\"role\":\"programar\",\"instruction\":\"1\"},{\"role\":\"programar\",\"instruction\":\"2\"},{\"role\":\"programar\",\"instruction\":\"3\"},{\"role\":\"programar\",\"instruction\":\"4\"},{\"role\":\"programar\",\"instruction\":\"5\"}]}", .code = "too_many_subtasks" },
        .{ .args = "{\"tasks\":[{\"role\":\"ejecutar\",\"instruction\":\"dir\"}]}", .code = "unknown_role" },
        .{ .args = "{\"tasks\":[{\"role\":\"programar\",\"instruction\":\"x\",\"files\":[\"..\\\\fuera\"]}]}", .code = "invalid_files" },
    };
    for (cases) |c| {
        const out = try delegateTasks(ctx, a, c.args);
        defer a.free(out);
        var r = try testDelegateResult(a, out);
        defer r.deinit();
        try std.testing.expectEqualStrings(c.code, r.value.object.get("error").?.string);
    }
    // Otra delegación en curso en la misma conversación: se dice, no se apila.
    ctx.busy.store(true, .release);
    {
        const out = try delegateTasks(ctx, a, "{\"tasks\":[{\"role\":\"programar\",\"instruction\":\"x\"}]}");
        defer a.free(out);
        try std.testing.expect(std.mem.indexOf(u8, out, "\"busy\"") != null);
    }
    ctx.busy.store(false, .release);
    // «Detener» antes de lanzar: nada se crea ni se integra.
    st.plan_mutex.lock();
    st.plan_cancel_requested = true;
    st.plan_mutex.unlock();
    {
        const out = try delegateTasks(ctx, a, "{\"tasks\":[{\"role\":\"programar\",\"instruction\":\"x\",\"files\":[\"x.txt\"]}]}");
        defer a.free(out);
        try std.testing.expect(std.mem.indexOf(u8, out, "\"cancelled\"") != null);
        var xbuf: [4096]u8 = undefined;
        try std.testing.expectError(error.FileNotFound, std.Io.Dir.cwd().access(io, try std.fmt.bufPrint(&xbuf, "{s}" ++ std.fs.path.sep_str ++ "x.txt", .{root}), .{}));
    }
    st.plan_mutex.lock();
    st.plan_cancel_requested = false;
    st.plan_mutex.unlock();
}

test "USUARIO-NUEVO B: un modelo pedido para una subtarea respeta «Solo gratis» y no crea nada" {
    const a = std.testing.allocator;
    var threaded = std.Io.Threaded.init(a, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    try st.catalog.db.exec("INSERT INTO providers(name,base_url,api_style,enabled,is_local) VALUES('PagoB','http://127.0.0.1','openai',1,0)");
    try st.catalog.db.exec("INSERT INTO models(provider_id,model_name,is_free,available) SELECT id,'caro',0,1 FROM providers WHERE name='PagoB'");
    try st.catalog.db.exec("INSERT INTO api_keys(provider_id,label,key_ciphertext,status) SELECT id,'synthetic',X'00','active' FROM providers WHERE name='PagoB'");
    try st.catalog.db.exec("INSERT INTO settings(key,value) VALUES('governance_mode','free_tier_first') ON CONFLICT(key) DO UPDATE SET value='free_tier_first'");
    const root = try testDelegateRoot(a, io, true);
    defer a.free(root);
    defer std.Io.Dir.cwd().deleteTree(io, root) catch |e| std.debug.print("delegate cleanup: {s}\n", .{@errorName(e)});
    const parent = try superagent.Superagent.insertOrderRow(st.db_conn, "p", "conversación", "running", 1);
    const ctx = try DelegateCtx.create(st, parent, "p", root);
    defer ctx.release();
    ctx.dispatch_fn = testDelegateDispatch;
    const out = try delegateTasks(ctx, a, "{\"tasks\":[{\"role\":\"programar\",\"instruction\":\"x\",\"files\":[\"x.txt\"],\"model\":\"PagoB|caro\"}]}");
    defer a.free(out);
    var r = try testDelegateResult(a, out);
    defer r.deinit();
    try std.testing.expectEqualStrings("model_blocked", r.value.object.get("error").?.string);
    try std.testing.expect(std.mem.indexOf(u8, r.value.object.get("detail").?.string, "Solo gratis") != null);
    const q = try st.db_conn.prepare("SELECT COUNT(*) FROM orders WHERE parent_order_id = ?");
    defer st.db_conn.finalize(q);
    try db.bindInt(q, 1, parent);
    try std.testing.expect(db.c.sqlite3_step(q) == db.c.SQLITE_ROW);
    try std.testing.expectEqual(@as(i64, 0), db.c.sqlite3_column_int64(q, 0));
}

test "P1-3 hueco B1e: un model bien formado fuera del catalogo no tumba su subtarea; va en automatico y lo dice" {
    const a = std.testing.allocator;
    var threaded = std.Io.Threaded.init(a, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    const root = try testDelegateRoot(a, io, true);
    defer a.free(root);
    defer std.Io.Dir.cwd().deleteTree(io, root) catch |e| std.debug.print("delegate cleanup: {s}\n", .{@errorName(e)});
    const parent = try superagent.Superagent.insertOrderRow(st.db_conn, "p", "conversación", "running", 1);
    const ctx = try DelegateCtx.create(st, parent, "p", root);
    defer ctx.release();
    ctx.dispatch_fn = testDelegateDispatch;
    const out = try delegateTasks(ctx, a,
        \\{"tasks":[
        \\ {"role":"programar","instruction":"fantasma","files":["f.txt"],"model":"Fantasma|no-existe"},
        \\ {"role":"programar","instruction":"agente","files":["g.txt"],"model":"agent:codex|sin-detectar"},
        \\ {"role":"programar","instruction":"normal","files":["h.txt"]}
        \\]}
    );
    defer a.free(out);
    var r = try testDelegateResult(a, out);
    defer r.deinit();
    try std.testing.expect(r.value.object.get("error") == null);
    const subs = r.value.object.get("subtasks").?.array.items;
    try std.testing.expectEqual(@as(usize, 3), subs.len);
    for (subs) |s| {
        try std.testing.expectEqualStrings("done", s.object.get("status").?.string);
        try std.testing.expect(s.object.get("integrated").?.bool);
    }
    try std.testing.expectEqualStrings("el modelo pedido «Fantasma|no-existe» no es válido; lo eligió DevAgents", subs[0].object.get("model_note").?.string);
    try std.testing.expectEqualStrings("el modelo pedido «agent:codex|sin-detectar» no es válido; lo eligió DevAgents", subs[1].object.get("model_note").?.string);
    try std.testing.expect(subs[2].object.get("model_note") == null);
    // Arrancó en automático: el evento de arranque no lleva el modelo pedido.
    var started = lastEventPayload(a, st.db_conn, parent, "delegation_started_v1").?;
    defer started.deinit();
    for (started.value.object.get("subtasks").?.array.items) |s| try std.testing.expect(s.object.get("model").? == .null);
    // El ejecutor gobernado deja la nota tal cual (no la duplica ni la pierde).
    const annotated = try delegation.annotateIgnoredModels(a, "{\"tasks\":[{\"role\":\"programar\",\"instruction\":\"fantasma\",\"model\":\"Fantasma|no-existe\"}]}", out);
    defer a.free(annotated);
    try std.testing.expect(std.mem.indexOf(u8, annotated, "Fantasma|no-existe") != null);
}

test "USUARIO-NUEVO B: «Detener» a mitad corta las subtareas que faltan y no integra nada" {
    const a = std.testing.allocator;
    var threaded = std.Io.Threaded.init(a, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    const root = try testDelegateRoot(a, io, true);
    defer a.free(root);
    defer std.Io.Dir.cwd().deleteTree(io, root) catch |e| std.debug.print("delegate cleanup: {s}\n", .{@errorName(e)});
    const parent = try superagent.Superagent.insertOrderRow(st.db_conn, "p", "conversación", "running", 1);
    const ctx = try DelegateCtx.create(st, parent, "p", root);
    defer ctx.release();
    ctx.dispatch_fn = testDelegateDispatch;
    const out = try delegateTasks(ctx, a,
        \\{"tasks":[
        \\ {"role":"programar","instruction":"DETENER aqui","files":["uno.txt"]},
        \\ {"role":"programar","instruction":"no llega","files":["dos.txt"]}
        \\]}
    );
    defer a.free(out);
    var r = try testDelegateResult(a, out);
    defer r.deinit();
    try std.testing.expect(r.value.object.get("cancelled").?.bool);
    try std.testing.expectEqual(@as(i64, 0), r.value.object.get("integrated").?.integer);
    const subs = r.value.object.get("subtasks").?.array.items;
    try std.testing.expectEqualStrings("cancelled", subs[1].object.get("status").?.string);
    for (subs) |s| try std.testing.expect(!s.object.get("integrated").?.bool);
    // Nada llegó a la carpeta del proyecto.
    var buf: [4096]u8 = undefined;
    try std.testing.expectError(error.FileNotFound, std.Io.Dir.cwd().access(io, try std.fmt.bufPrint(&buf, "{s}" ++ std.fs.path.sep_str ++ "uno.txt", .{root}), .{}));
    try std.testing.expectError(error.FileNotFound, std.Io.Dir.cwd().access(io, try std.fmt.bufPrint(&buf, "{s}" ++ std.fs.path.sep_str ++ "dos.txt", .{root}), .{}));
    // La segunda quedó cerrada como cancelada, no «running» para siempre.
    const q = try st.db_conn.prepare("SELECT status FROM orders WHERE id = ?");
    defer st.db_conn.finalize(q);
    try db.bindInt(q, 1, subs[1].object.get("child_order_id").?.integer);
    try std.testing.expect(db.c.sqlite3_step(q) == db.c.SQLITE_ROW);
    try std.testing.expectEqualStrings("cancelled", std.mem.span(db.c.sqlite3_column_text(q, 0)));
}

test "USUARIO-NUEVO B: dos subtareas en worktrees propios se integran; las que chocan, fallan o se rechazan, no" {
    const a = std.testing.allocator;
    var threaded = std.Io.Threaded.init(a, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    const root = try testDelegateRoot(a, io, true);
    defer a.free(root);
    defer std.Io.Dir.cwd().deleteTree(io, root) catch |e| std.debug.print("delegate cleanup: {s}\n", .{@errorName(e)});
    const parent = try superagent.Superagent.insertOrderRow(st.db_conn, "p", "conversación", "running", 1);
    const ctx = try DelegateCtx.create(st, parent, "p", root);
    defer ctx.release();
    ctx.dispatch_fn = testDelegateDispatch;
    const out = try delegateTasks(ctx, a,
        \\{"tasks":[
        \\ {"role":"programar","instruction":"api lista","files":["api.js"]},
        \\ {"role":"documentar","instruction":"guia lista","files":["GUIA.md"]},
        \\ {"role":"programar","instruction":"choca con api","files":["api.js"]},
        \\ {"role":"programar","instruction":"FALLA siempre","files":["f.txt"]}
        \\]}
    );
    defer a.free(out);
    var r = try testDelegateResult(a, out);
    defer r.deinit();
    const subs = r.value.object.get("subtasks").?.array.items;
    try std.testing.expectEqual(@as(usize, 4), subs.len);
    // 1 y 2: hechas, auditadas PASS, integradas, cada una en su worktree.
    for (subs[0..2]) |s| {
        try std.testing.expectEqualStrings("done", s.object.get("status").?.string);
        try std.testing.expectEqualStrings("PASS", s.object.get("verdict").?.string);
        try std.testing.expect(s.object.get("integrated").?.bool);
        try std.testing.expectEqualStrings("modelo-simulado", s.object.get("model").?.string);
    }
    // 3: hecha, pero toca api.js como la 1 → no se integra (conflicto).
    try std.testing.expect(subs[2].object.get("conflict").?.bool);
    try std.testing.expect(!subs[2].object.get("integrated").?.bool);
    // 4: falla con su motivo llano, sin integrar.
    try std.testing.expectEqualStrings("failed", subs[3].object.get("status").?.string);
    try std.testing.expectEqualStrings("el modelo no produjo el archivo", subs[3].object.get("error").?.string);
    try std.testing.expect(!subs[3].object.get("integrated").?.bool);
    try std.testing.expectEqual(@as(i64, 2), r.value.object.get("integrated").?.integer);
    // Lo integrado está en la carpeta del proyecto, con el contenido de la PRIMERA.
    var path_buf: [4096]u8 = undefined;
    const api = try std.fmt.bufPrint(&path_buf, "{s}" ++ std.fs.path.sep_str ++ "api.js", .{root});
    const content = try std.Io.Dir.cwd().readFileAlloc(io, api, a, .limited(1024));
    defer a.free(content);
    try std.testing.expectEqualStrings("api lista", content);
    // En la raíz (como Directo), sin la carpeta `orden-<hija>` ni el informe
    // del auditor, que se queda en el worktree como evidencia.
    try std.testing.expectEqualStrings("api.js", subs[0].object.get("files").?.array.items[0].string);
    try std.testing.expectEqual(@as(usize, 1), subs[0].object.get("files").?.array.items.len);
    try std.testing.expectError(error.FileNotFound, std.Io.Dir.cwd().access(io, try std.fmt.bufPrint(&path_buf, "{s}" ++ std.fs.path.sep_str ++ "t2.txt", .{root}), .{}));
    try std.testing.expect(std.mem.startsWith(u8, subs[2].object.get("worktree").?.string, ".devagents"));
    // Remate D6: las integradas retiran su worktree (como la Colmena) tras
    // guardar el informe de su auditor en el registro; las demás lo conservan
    // y la nota dice dónde está.
    for (subs[0..2]) |s| {
        try std.testing.expect(s.object.get("worktree").? == .null);
        try std.testing.expect(std.mem.indexOf(u8, s.object.get("note").?.string, "su worktree se retiró") != null);
        const child = s.object.get("child_order_id").?.integer;
        const sq = try st.db_conn.prepare("SELECT s.archived_at, s.worktree_path FROM spaces s JOIN orders o ON o.space_id = s.id WHERE o.id = ?");
        defer st.db_conn.finalize(sq);
        try db.bindInt(sq, 1, child);
        try std.testing.expect(db.c.sqlite3_step(sq) == db.c.SQLITE_ROW);
        try std.testing.expect(db.c.sqlite3_column_type(sq, 0) != db.c.SQLITE_NULL);
        const wt = std.mem.span(db.c.sqlite3_column_text(sq, 1));
        try std.testing.expectError(error.FileNotFound, std.Io.Dir.cwd().access(io, wt, .{}));
        const rq = try st.db_conn.prepare("SELECT payload_json FROM events WHERE order_id = ? AND kind = 'delegation_audit_report_v1'");
        defer st.db_conn.finalize(rq);
        try db.bindInt(rq, 1, child);
        try std.testing.expect(db.c.sqlite3_step(rq) == db.c.SQLITE_ROW);
        try std.testing.expect(std.mem.indexOf(u8, std.mem.span(db.c.sqlite3_column_text(rq, 0)), "PASS: informe del auditor") != null);
    }
    for (subs[2..4]) |s| {
        const rel = s.object.get("worktree").?.string;
        try std.testing.expect(std.mem.indexOf(u8, s.object.get("note").?.string, rel) != null);
        var kept_buf: [4096]u8 = undefined;
        try std.Io.Dir.cwd().access(io, try std.fmt.bufPrint(&kept_buf, "{s}" ++ std.fs.path.sep_str ++ "{s}", .{ root, rel }), .{});
    }
    // Hijas enlazadas a la conversación y ocultas de la barra lateral.
    const q = try st.db_conn.prepare("SELECT COUNT(*), SUM(substr(project_id,1,2)='__'), COUNT(DISTINCT space_id) FROM orders WHERE parent_order_id = ?");
    defer st.db_conn.finalize(q);
    try db.bindInt(q, 1, parent);
    try std.testing.expect(db.c.sqlite3_step(q) == db.c.SQLITE_ROW);
    try std.testing.expectEqual(@as(i64, 4), db.c.sqlite3_column_int64(q, 0));
    try std.testing.expectEqual(@as(i64, 4), db.c.sqlite3_column_int64(q, 1));
    try std.testing.expectEqual(@as(i64, 4), db.c.sqlite3_column_int64(q, 2));
    // La cabina recibe un evento por subtarea más el de arranque y el de cierre.
    const ev = try st.db_conn.prepare("SELECT kind, COUNT(*) FROM events WHERE order_id = ? AND kind LIKE 'delegation_%' GROUP BY kind ORDER BY kind");
    defer st.db_conn.finalize(ev);
    try db.bindInt(ev, 1, parent);
    var kinds: [3]i64 = .{ 0, 0, 0 };
    while (db.c.sqlite3_step(ev) == db.c.SQLITE_ROW) {
        const k = std.mem.span(db.c.sqlite3_column_text(ev, 0));
        const n = db.c.sqlite3_column_int64(ev, 1);
        if (std.mem.eql(u8, k, "delegation_started_v1")) kinds[0] = n;
        if (std.mem.eql(u8, k, "delegation_subtask_finished_v1")) kinds[1] = n;
        if (std.mem.eql(u8, k, "delegation_finished_v1")) kinds[2] = n;
    }
    try std.testing.expectEqualSlices(i64, &.{ 1, 4, 1 }, &kinds);
    // Una subtarea rechazada por su auditor tampoco se integra.
    const out2 = try delegateTasks(ctx, a, "{\"tasks\":[{\"role\":\"programar\",\"instruction\":\"RECHAZA esto\",\"files\":[\"r.txt\"]}]}");
    defer a.free(out2);
    var r2 = try testDelegateResult(a, out2);
    defer r2.deinit();
    const s2 = r2.value.object.get("subtasks").?.array.items[0];
    try std.testing.expectEqualStrings("FAIL", s2.object.get("verdict").?.string);
    try std.testing.expect(!s2.object.get("integrated").?.bool);
}

// D2 (11-nov, defecto en vivo: madre 46, hija 48): lo que comprueba la
// subtarea mientras su worktree existe, para afirmarlo después.
var test_d2_citas_verificadas: usize = 0;
var test_d2_citas_fallidas: usize = 99;
var test_d2_listed: bool = false;
var test_d2_read_back: bool = false;
var test_d2_report_is_evidence: bool = false;

/// Hija con el motor REAL de persistencia (workspace.persistTaskFiles): su
/// productor entrega `docs/uno.txt` y su auditor un informe `t2`, como la
/// orden 48 del recorrido en vivo.
fn testDelegateDispatchD2(st: *CoreState, rec: *OrderRecord, conn: db.Connection) DaResult {
    _ = st;
    const a = std.testing.allocator;
    const id = rec.db_id.?;
    var buf: [4096]u8 = undefined;
    const wt = orderSpacePath(conn, id, &buf) orelse return err(.internal, "sin worktree");
    workspace.setOrderRootOverride(wt);
    defer workspace.setOrderRootOverride(null);
    const producer = planner.PlannedTask{ .id = "t1", .task_type = .programar, .department = "programacion", .description = rec.text, .contract_fields = &.{}, .depends_on = &.{} };
    const arts = [_]worker_backend.Artifact{.{ .path = "docs/uno.txt", .content = "UNO\n" }};
    const produced = (workspace.persistTaskFiles(a, id, producer, &arts) catch return err(.internal, "persistencia del productor")) orelse return err(.internal, "el productor no escribió nada");
    for (produced) |p| a.free(p);
    a.free(produced);
    const report_text = "PASS: docs/uno.txt:1 `UNO` contiene exactamente la linea pedida por la instruccion de la subtarea.\n";
    const auditor = planner.PlannedTask{ .id = "t2", .task_type = .auditar, .department = "auditoria", .description = "Audita lo que produjo t1 frente a su instruccion.", .contract_fields = &.{}, .depends_on = &.{} };
    const report = [_]worker_backend.Artifact{.{ .path = "t2.txt", .content = report_text }};
    const report_paths = (workspace.persistTaskFiles(a, id, auditor, &report) catch return err(.internal, "persistencia del informe")) orelse return err(.internal, "el auditor no escribió nada");
    defer {
        for (report_paths) |p| a.free(p);
        a.free(report_paths);
    }
    var order_buf: [4096]u8 = undefined;
    const order_dir = std.fmt.bufPrint(&order_buf, "{s}" ++ std.fs.path.sep_str ++ "orden-{d}" ++ std.fs.path.sep_str ++ "", .{ wt, id }) catch return err(.internal, "ruta");
    test_d2_report_is_evidence = std.ascii.startsWithIgnoreCase(report_paths[0], order_dir);
    // La cita del auditor, tal como la escribe, se resuelve.
    var citas = audit_citas.verificaDeOrden(a, wt, id, report_text) catch return err(.internal, "citas");
    defer citas.deinit(a);
    test_d2_citas_verificadas = citas.verificadas;
    test_d2_citas_fallidas = citas.fallidas;
    // listOrderFiles y readOrderFile ven la salida con su ruta pedida.
    const files = workspace.listOrderFiles(a, id) catch return err(.internal, "listOrderFiles");
    defer {
        for (files) |f| f.deinit(a);
        a.free(files);
    }
    for (files) |f| {
        if (std.mem.eql(u8, f.name, "docs/uno.txt") and f.size == 4) test_d2_listed = true;
    }
    if (workspace.readOrderFile(a, id, "docs/uno.txt") catch null) |body| {
        defer a.free(body);
        test_d2_read_back = std.mem.eql(u8, body, "UNO\n");
    }
    bonEvent(conn, id, "task_done", "{\"task_id\":\"t1\",\"success\":true,\"model_used\":\"modelo-simulado\"}");
    bonEvent(conn, id, "task_audit", "{\"task_id\":\"t2\",\"verdict\":\"PASS\"}");
    _ = conn.tryCommitTerminal(id, "done", "order_done", "superagente", "{\"completed\":2,\"failed\":0}", health.nowMillis(conn)) catch false;
    return .ok;
}

test "D2: la hija escribe docs/uno.txt en su ruta pedida, su cita se resuelve, se integra en docs\\uno.txt y el informe del auditor no se copia" {
    const a = std.testing.allocator;
    var threaded = std.Io.Threaded.init(a, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    const root = try testDelegateRoot(a, io, true);
    defer a.free(root);
    defer std.Io.Dir.cwd().deleteTree(io, root) catch |e| std.debug.print("delegate cleanup: {s}\n", .{@errorName(e)});
    const parent = try superagent.Superagent.insertOrderRow(st.db_conn, "p", "conversación", "running", 1);
    const ctx = try DelegateCtx.create(st, parent, "p", root);
    defer ctx.release();
    ctx.dispatch_fn = testDelegateDispatchD2;
    test_d2_citas_verificadas = 0;
    test_d2_citas_fallidas = 99;
    test_d2_listed = false;
    test_d2_read_back = false;
    test_d2_report_is_evidence = false;
    const out = try delegateTasks(ctx, a, "{\"tasks\":[{\"role\":\"programar\",\"instruction\":\"crea docs/uno.txt con UNO\",\"files\":[\"docs/uno.txt\"]}]}");
    defer a.free(out);
    var r = try testDelegateResult(a, out);
    defer r.deinit();
    const s = r.value.object.get("subtasks").?.array.items[0];
    try std.testing.expectEqualStrings("done", s.object.get("status").?.string);
    try std.testing.expect(s.object.get("integrated").?.bool);
    // Lo que se cuenta al modelo y a la cabina es la ruta pedida.
    const files = s.object.get("files").?.array.items;
    try std.testing.expectEqual(@as(usize, 1), files.len);
    try std.testing.expectEqualStrings("docs/uno.txt", files[0].string);
    // Dentro del worktree de la hija: cita resuelta, listado y lectura.
    try std.testing.expectEqual(@as(usize, 1), test_d2_citas_verificadas);
    try std.testing.expectEqual(@as(usize, 0), test_d2_citas_fallidas);
    try std.testing.expect(test_d2_listed);
    try std.testing.expect(test_d2_read_back);
    try std.testing.expect(test_d2_report_is_evidence);
    // En el proyecto de la madre: docs\uno.txt, sin `orden-<hija>` ni informe.
    var path_buf: [4096]u8 = undefined;
    const doc = try std.Io.Dir.cwd().readFileAlloc(io, try std.fmt.bufPrint(&path_buf, "{s}" ++ std.fs.path.sep_str ++ "docs" ++ std.fs.path.sep_str ++ "uno.txt", .{root}), a, .limited(64));
    defer a.free(doc);
    try std.testing.expectEqualStrings("UNO\n", doc);
    try std.testing.expectError(error.FileNotFound, std.Io.Dir.cwd().access(io, try std.fmt.bufPrint(&path_buf, "{s}" ++ std.fs.path.sep_str ++ "uno.txt", .{root}), .{}));
    for ([_][]const u8{ "t2.txt", "t2.md" }) |name| {
        try std.testing.expectError(error.FileNotFound, std.Io.Dir.cwd().access(io, try std.fmt.bufPrint(&path_buf, "{s}" ++ std.fs.path.sep_str ++ "{s}", .{ root, name }), .{}));
    }
    const child = s.object.get("child_order_id").?.integer;
    try std.testing.expectError(error.FileNotFound, std.Io.Dir.cwd().access(io, try std.fmt.bufPrint(&path_buf, "{s}" ++ std.fs.path.sep_str ++ "orden-{d}", .{ root, child }), .{}));
}

test "D2: Best-of-N sigue integrando la salida de la candidata escrita en la raiz de su espacio" {
    const a = std.testing.allocator;
    var threaded = std.Io.Threaded.init(a, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const root = try testDelegateRoot(a, io, true);
    defer a.free(root);
    defer std.Io.Dir.cwd().deleteTree(io, root) catch |e| std.debug.print("bon cleanup: {s}\n", .{@errorName(e)});
    // Candidata (orden 790) y padre (orden 789) en espacios git del proyecto.
    var path_buf: [4096]u8 = undefined;
    var bon_spaces: [2][]u8 = undefined;
    for ([_][]const u8{ "orden-789", "orden-790" }, 0..) |name, i| {
        bon_spaces[i] = try std.fmt.allocPrint(a, "{s}" ++ std.fs.path.sep_str ++ ".devagents" ++ std.fs.path.sep_str ++ "spaces" ++ std.fs.path.sep_str ++ "{s}", .{ root, name });
        const branch = try std.fmt.bufPrint(&path_buf, "devagents/{s}", .{name});
        var add = try headless_adapter.defaultCapture(a, &.{ "git", "worktree", "add", "-b", branch, bon_spaces[i] }, root);
        defer add.deinit(a);
        try std.testing.expectEqual(@as(u32, 0), add.exit_code);
    }
    defer for (bon_spaces) |sp| a.free(sp);
    {
        workspace.setOrderRootOverride(bon_spaces[1]);
        defer workspace.setOrderRootOverride(null);
        const task = planner.PlannedTask{ .id = "t1", .task_type = .programar, .department = "programacion", .description = "crea src/x.py", .contract_fields = &.{}, .depends_on = &.{} };
        const arts = [_]worker_backend.Artifact{.{ .path = "src/x.py", .content = "print(1)\n" }};
        const written = (try workspace.persistTaskFiles(a, 790, task, &arts)).?;
        defer {
            for (written) |p| a.free(p);
            a.free(written);
        }
        // En la raíz de su espacio, con su subcarpeta.
        try std.testing.expect(std.mem.endsWith(u8, written[0], "orden-790" ++ std.fs.path.sep_str ++ "src" ++ std.fs.path.sep_str ++ "x.py"));
    }
    const sets = best_of_n.changedFiles(a, bon_spaces[1], "orden-790").?;
    defer best_of_n.freeChangedSets(a, sets);
    var seen = false;
    for (sets.copy) |p| {
        if (std.mem.eql(u8, p, "src/x.py")) seen = true;
    }
    try std.testing.expect(seen);
    const applied = try best_of_n.applyWinner(a, bon_spaces[1], bon_spaces[0], &.{"src/x.py"}, .{ .from = "orden-790", .to = "orden-789" });
    try std.testing.expect(applied.copied >= 1);
    const got = try std.Io.Dir.cwd().readFileAlloc(io, try std.fmt.bufPrint(&path_buf, "{s}" ++ std.fs.path.sep_str ++ "src" ++ std.fs.path.sep_str ++ "x.py", .{bon_spaces[0]}), a, .limited(64));
    defer a.free(got);
    try std.testing.expectEqualStrings("print(1)\n", got);
}

test "Remate D1/D2/D6: dos subtareas sin auditar (cuota diaria del auditor) dicen por qué, no se integran y conservan su worktree" {
    const a = std.testing.allocator;
    var threaded = std.Io.Threaded.init(a, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    const root = try testDelegateRoot(a, io, true);
    defer a.free(root);
    defer std.Io.Dir.cwd().deleteTree(io, root) catch |e| std.debug.print("delegate cleanup: {s}\n", .{@errorName(e)});
    const parent = try superagent.Superagent.insertOrderRow(st.db_conn, "p", "conversación", "running", 1);
    const ctx = try DelegateCtx.create(st, parent, "p", root);
    defer ctx.release();
    ctx.dispatch_fn = testDelegateDispatch;
    const out = try delegateTasks(ctx, a,
        \\{"tasks":[
        \\ {"role":"documentar","instruction":"SINAUDITAR uno","files":["uno.txt"]},
        \\ {"role":"documentar","instruction":"SINAUDITAR dos","files":["dos.txt"]}
        \\]}
    );
    defer a.free(out);
    var r = try testDelegateResult(a, out);
    defer r.deinit();
    try std.testing.expectEqual(@as(i64, 0), r.value.object.get("integrated").?.integer);
    // El modelo recibe el recuento y la orden de trasladar cada motivo.
    try std.testing.expect(std.mem.indexOf(u8, r.value.object.get("detail").?.string, "Se integraron 0 de 2") != null);
    for (r.value.object.get("subtasks").?.array.items) |s| {
        try std.testing.expectEqualStrings("sin auditar", s.object.get("verdict").?.string);
        try std.testing.expect(s.object.get("unaudited").?.bool);
        try std.testing.expect(!s.object.get("integrated").?.bool);
        const why = s.object.get("error").?.string;
        try std.testing.expect(std.mem.indexOf(u8, why, "se agotó la cuota gratuita de hoy de OpenRouter") != null);
        try std.testing.expect(std.mem.indexOf(u8, why, "google/gemma:free") != null);
        try std.testing.expect(std.mem.indexOf(u8, why, "Configuración › Proveedores") != null);
        // Sin integrar: el worktree se conserva y la nota dice dónde.
        const rel = s.object.get("worktree").?.string;
        try std.testing.expect(std.mem.indexOf(u8, s.object.get("note").?.string, rel) != null);
        var kept_buf: [4096]u8 = undefined;
        try std.Io.Dir.cwd().access(io, try std.fmt.bufPrint(&kept_buf, "{s}" ++ std.fs.path.sep_str ++ "{s}", .{ root, rel }), .{});
    }
    var buf: [4096]u8 = undefined;
    try std.testing.expectError(error.FileNotFound, std.Io.Dir.cwd().access(io, try std.fmt.bufPrint(&buf, "{s}" ++ std.fs.path.sep_str ++ "uno.txt", .{root}), .{}));
    // D1: el ledger de la conversación cuenta 0 de 2 y 2 sin auditar; con eso
    // la orden madre cierra «sin auditar», no «hecha».
    var sup = superagent.Superagent.init(a, st.db_conn, null, superagent.NoopMemory.backend(), 1);
    sup.rules_catalog = st.catalog.db;
    const tally = try sup.delegationTally(parent);
    try std.testing.expectEqual(@as(i64, 2), tally.count);
    try std.testing.expectEqual(@as(i64, 0), tally.integrated);
    try std.testing.expectEqual(@as(i64, 2), tally.unaudited);
}

var test_retry_calls: u32 = 0;
var test_retry_pass_all: bool = false;

/// Reanudación simulada de una hija «sin auditar»: como el motor real, NO
/// vuelve a producir (t1 se restaura del checkpoint); solo corre su auditor.
/// La hija cuyo texto contiene «dos» sigue sin auditor hasta que
/// `test_retry_pass_all` lo permite.
fn testDelegateRetryDispatch(st: *CoreState, rec: *OrderRecord, conn: db.Connection) DaResult {
    _ = st;
    test_retry_calls += 1;
    const id = rec.db_id.?;
    if (!test_retry_pass_all and std.mem.indexOf(u8, rec.text, "dos") != null) {
        bonEvent(conn, id, "task_audit_unavailable_v1", "{\"task_id\":\"t2\",\"success\":false,\"cause\":\"audit_unavailable\"}");
        _ = conn.tryCommitTerminal(id, "audit_unavailable", "order_audit_unavailable_v1", "superagente", "{\"completed\":1,\"failed\":0}", health.nowMillis(conn)) catch false;
        return .ok;
    }
    var buf: [4096]u8 = undefined;
    const wt = orderSpacePath(conn, id, &buf) orelse return err(.internal, "sin worktree");
    var threaded = std.Io.Threaded.init(std.testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var report_buf: [4096]u8 = undefined;
    const report = std.fmt.bufPrint(&report_buf, "{s}" ++ std.fs.path.sep_str ++ "orden-{d}" ++ std.fs.path.sep_str ++ "t2.txt", .{ wt, id }) catch return err(.internal, "ruta");
    std.Io.Dir.cwd().writeFile(io, .{ .sub_path = report, .data = "PASS: informe del auditor (reintento)" }) catch return err(.internal, "no se pudo escribir el informe");
    bonEvent(conn, id, "task_audit", "{\"task_id\":\"t2\",\"verdict\":\"PASS\"}");
    _ = conn.tryCommitTerminal(id, "done", "order_done", "superagente", "{\"completed\":2,\"failed\":0}", health.nowMillis(conn)) catch false;
    return .ok;
}

fn testCountRows(conn: db.Connection, sql: []const u8, id: i64) !i64 {
    const stmt = try conn.prepare(sql);
    defer conn.finalize(stmt);
    try db.bindInt(stmt, 1, id);
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) return error.TestUnexpectedResult;
    return db.c.sqlite3_column_int64(stmt, 0);
}

fn testResumeAndWait(handle: ?*anyopaque, order: ?*anyopaque) !c_int {
    try std.testing.expectEqual(@as(c_int, 0), da_order_resume_async(handle, order));
    var done: c_int = 0;
    var ok_flag: c_int = 0;
    var attempts: u32 = 0;
    while (done == 0 and attempts < 3000) : (attempts += 1) {
        Sleep(10);
        _ = da_order_dispatch_poll(handle, order, &done, &ok_flag);
    }
    try std.testing.expect(done == 1);
    return ok_flag;
}

test "FASE0-B2 Reintentar de la madre: reaudita solo las hijas sin auditar, integra las que pasan y no relanza ni duplica" {
    const a = std.testing.allocator;
    var threaded = std.Io.Threaded.init(a, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    const root = try testDelegateRoot(a, io, true);
    defer a.free(root);
    defer std.Io.Dir.cwd().deleteTree(io, root) catch |e| std.debug.print("delegate cleanup: {s}\n", .{@errorName(e)});
    const parent = try superagent.Superagent.insertOrderRow(st.db_conn, "p", "conversación", "running", 1);
    {
        const ctx = try DelegateCtx.create(st, parent, "p", root);
        defer ctx.release();
        ctx.dispatch_fn = testDelegateDispatch;
        const out = try delegateTasks(ctx, a,
            \\{"tasks":[
            \\ {"role":"documentar","instruction":"SINAUDITAR uno","files":["uno.txt"]},
            \\ {"role":"documentar","instruction":"SINAUDITAR dos","files":["dos.txt"]},
            \\ {"role":"documentar","instruction":"tres ya auditada","files":["tres.txt"]}
            \\]}
        );
        defer a.free(out);
    }
    // La vuelta cierra como la deja processOrder (Remate D1): «sin auditar».
    try std.testing.expect(try st.db_conn.tryCommitTerminal(parent, "audit_unavailable", "order_audit_unavailable_v1", "superagente", "{\"cause\":\"delegation_not_integrated\",\"tasks\":0}", 1));
    // Como tras cerrar y abrir la aplicación: la madre está en memoria sin
    // outcome y sin la carpeta recordada de la vuelta.
    const aa = st.arena.child_allocator;
    const mrec = try aa.create(OrderRecord);
    mrec.* = .{
        .id = parent,
        .db_id = parent,
        .text = try aa.dupe(u8, "conversación"),
        .project_id = try aa.dupe(u8, "p"),
        .status = .audit_unavailable,
        .plan_json = null,
        .outcome = null,
        .questions = try aa.alloc(u8, 0),
        .created_at = 1,
    };
    st.orders_mutex.lock();
    st.orders.append(aa, mrec) catch |e| {
        st.orders_mutex.unlock();
        return e;
    };
    st.orders_mutex.unlock();
    const order = orderIdToHandle(parent);

    var path_buf: [4096]u8 = undefined;
    const cwd = std.Io.Dir.cwd();
    try std.testing.expectError(error.FileNotFound, cwd.access(io, try std.fmt.bufPrint(&path_buf, "{s}" ++ std.fs.path.sep_str ++ "uno.txt", .{root}), .{}));
    try cwd.access(io, try std.fmt.bufPrint(&path_buf, "{s}" ++ std.fs.path.sep_str ++ "tres.txt", .{root}), .{});
    const orders_before = try testCountRows(st.db_conn, "SELECT COUNT(*) FROM orders WHERE id > ?", 0);
    const spaces_before = try testCountRows(st.db_conn, "SELECT COUNT(*) FROM spaces WHERE id > ?", 0);

    st.delegate_retry_dispatch_fn = testDelegateRetryDispatch;
    test_retry_calls = 0;
    test_retry_pass_all = false;

    // ── Primer reintento: «uno» pasa, «dos» sigue sin auditor ──────────────
    _ = try testResumeAndWait(handle, order);
    // Solo se tocaron las dos hijas sin auditar; la ya integrada no.
    try std.testing.expectEqual(@as(u32, 2), test_retry_calls);
    // Nada se relanzó ni se duplicó: ni órdenes, ni worktrees, ni otra delegación.
    try std.testing.expectEqual(orders_before, try testCountRows(st.db_conn, "SELECT COUNT(*) FROM orders WHERE id > ?", 0));
    try std.testing.expectEqual(spaces_before, try testCountRows(st.db_conn, "SELECT COUNT(*) FROM spaces WHERE id > ?", 0));
    try std.testing.expectEqual(@as(i64, 1), try testCountRows(st.db_conn, "SELECT COUNT(*) FROM events WHERE order_id = ? AND kind = 'delegation_started_v1'", parent));
    try std.testing.expectEqual(@as(i64, 2), try testCountRows(st.db_conn, "SELECT COUNT(*) FROM events WHERE order_id = ? AND kind = 'delegation_audit_retry_v1'", parent));
    // La hija ya auditada («tres», índice 3) no se toca: no deja línea de reintento.
    try std.testing.expectEqual(@as(i64, 0), try testCountRows(st.db_conn, "SELECT COUNT(*) FROM events WHERE order_id = ? AND kind = 'delegation_audit_retry_v1' AND json_extract(payload_json, '$.index') = 3", parent));
    // «uno» se integró con el contenido que produjo la hija la primera vez; su
    // informe de auditoría no se copia al proyecto. «dos» sigue en su worktree.
    const uno = try cwd.readFileAlloc(io, try std.fmt.bufPrint(&path_buf, "{s}" ++ std.fs.path.sep_str ++ "uno.txt", .{root}), a, .limited(4096));
    defer a.free(uno);
    try std.testing.expectEqualStrings("SINAUDITAR uno", uno);
    try std.testing.expectError(error.FileNotFound, cwd.access(io, try std.fmt.bufPrint(&path_buf, "{s}" ++ std.fs.path.sep_str ++ "t2.txt", .{root}), .{}));
    try std.testing.expectError(error.FileNotFound, cwd.access(io, try std.fmt.bufPrint(&path_buf, "{s}" ++ std.fs.path.sep_str ++ "dos.txt", .{root}), .{}));
    var sup = superagent.Superagent.init(a, st.db_conn, null, superagent.NoopMemory.backend(), 1);
    sup.rules_catalog = st.catalog.db;
    var tally = try sup.delegationTally(parent);
    try std.testing.expectEqual(@as(i64, 3), tally.count);
    try std.testing.expectEqual(@as(i64, 2), tally.integrated);
    try std.testing.expectEqual(@as(i64, 1), tally.unaudited);
    // La madre sigue «sin auditar» (queda una), con el recuento nuevo.
    try std.testing.expectEqual(superagent.OrderStatus.audit_unavailable, mrec.status);
    {
        var last = lastEventPayload(a, st.db_conn, parent, "order_audit_unavailable_v1").?;
        defer last.deinit();
        try std.testing.expectEqualStrings("2 de 3 subtareas integradas", jsonStr(last.value, "reason"));
    }
    {
        var line = lastEventPayload(a, st.db_conn, parent, "delegation_audit_retry_v1").?;
        defer line.deinit();
        try std.testing.expectEqual(@as(i64, 2), line.value.object.get("index").?.integer);
        try std.testing.expect(line.value.object.get("unaudited").?.bool);
        try std.testing.expect(!line.value.object.get("integrated").?.bool);
        try std.testing.expect(std.mem.indexOf(u8, jsonStr(line.value, "note"), "sigue sin auditar") != null);
        try std.testing.expect(std.mem.indexOf(u8, jsonStr(line.value, "worktree"), "orden-") != null);
    }

    // ── Segundo reintento: solo queda «dos», y ahora su auditor responde ───
    test_retry_pass_all = true;
    _ = try testResumeAndWait(handle, order);
    try std.testing.expectEqual(@as(u32, 3), test_retry_calls);
    try std.testing.expectEqual(orders_before, try testCountRows(st.db_conn, "SELECT COUNT(*) FROM orders WHERE id > ?", 0));
    // Un segundo «Reintentar» seguido no duplica filas: una más por «dos», ni una
    // repetida para «uno» ni para la ya auditada.
    try std.testing.expectEqual(@as(i64, 3), try testCountRows(st.db_conn, "SELECT COUNT(*) FROM events WHERE order_id = ? AND kind = 'delegation_audit_retry_v1'", parent));
    const dos = try cwd.readFileAlloc(io, try std.fmt.bufPrint(&path_buf, "{s}" ++ std.fs.path.sep_str ++ "dos.txt", .{root}), a, .limited(4096));
    defer a.free(dos);
    try std.testing.expectEqualStrings("SINAUDITAR dos", dos);
    tally = try sup.delegationTally(parent);
    try std.testing.expectEqual(@as(i64, 3), tally.integrated);
    try std.testing.expectEqual(@as(i64, 0), tally.unaudited);
    try std.testing.expectEqual(superagent.OrderStatus.done, mrec.status);
    // Los worktrees de lo integrado se retiraron (como en la delegación).
    try std.testing.expectEqual(@as(i64, 0), try testCountRows(st.db_conn, "SELECT COUNT(*) FROM spaces WHERE archived_at IS NULL AND id > ?", 0));

    // ── Ya no hay nada sin auditar: «Reintentar» no relanza nada ───────────
    try std.testing.expect(da_order_resume_async(handle, order) != 0);
    try std.testing.expectEqual(@as(u32, 3), test_retry_calls);
}

test "P1-4 B2f: una hija sin auditar cuyo worktree ya no existe no es reintentable y lo dice en llano" {
    const a = std.testing.allocator;
    var threaded = std.Io.Threaded.init(a, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    const root = try testDelegateRoot(a, io, true);
    defer a.free(root);
    defer std.Io.Dir.cwd().deleteTree(io, root) catch |e| std.debug.print("delegate cleanup: {s}\n", .{@errorName(e)});
    const parent = try superagent.Superagent.insertOrderRow(st.db_conn, "p", "conversación", "running", 1);
    var child_id: i64 = 0;
    {
        const ctx = try DelegateCtx.create(st, parent, "p", root);
        defer ctx.release();
        ctx.dispatch_fn = testDelegateDispatch;
        const out = try delegateTasks(ctx, a, "{\"tasks\":[{\"role\":\"documentar\",\"instruction\":\"SINAUDITAR uno\",\"files\":[\"uno.txt\"]}]}");
        defer a.free(out);
        var r = try testDelegateResult(a, out);
        defer r.deinit();
        const s = r.value.object.get("subtasks").?.array.items[0];
        // Recién delegada conserva su worktree: se puede reintentar.
        try std.testing.expect(s.object.get("unaudited").?.bool);
        try std.testing.expect(s.object.get("retryable").?.bool);
        child_id = s.object.get("child_order_id").?.integer;
    }
    {
        var line = lastEventPayload(a, st.db_conn, parent, "delegation_subtask_finished_v1").?;
        defer line.deinit();
        try std.testing.expect(line.value.object.get("retryable").?.bool);
    }
    try std.testing.expect(try st.db_conn.tryCommitTerminal(parent, "audit_unavailable", "order_audit_unavailable_v1", "superagente", "{\"cause\":\"delegation_not_integrated\",\"tasks\":0}", 1));
    // El usuario (o una limpieza) borra la copia de trabajo de la hija.
    var wbuf: [4096]u8 = undefined;
    const wt = orderSpacePath(st.db_conn, child_id, &wbuf).?;
    try std.Io.Dir.cwd().deleteTree(io, wt);
    try std.testing.expect(liveChildWorktree(st.db_conn, child_id, &wbuf) == null);

    const aa = st.arena.child_allocator;
    const mrec = try aa.create(OrderRecord);
    mrec.* = .{
        .id = parent,
        .db_id = parent,
        .text = try aa.dupe(u8, "conversación"),
        .project_id = try aa.dupe(u8, "p"),
        .status = .audit_unavailable,
        .plan_json = null,
        .outcome = null,
        .questions = try aa.alloc(u8, 0),
        .created_at = 1,
    };
    st.orders_mutex.lock();
    st.orders.append(aa, mrec) catch |e| {
        st.orders_mutex.unlock();
        return e;
    };
    st.orders_mutex.unlock();
    st.delegate_retry_dispatch_fn = testDelegateRetryDispatch;
    test_retry_calls = 0;
    test_retry_pass_all = true;
    _ = try testResumeAndWait(handle, orderIdToHandle(parent));
    // No se relanzó nada: no hay trabajo que auditar.
    try std.testing.expectEqual(@as(u32, 0), test_retry_calls);
    var line = lastEventPayload(a, st.db_conn, parent, "delegation_audit_retry_v1").?;
    defer line.deinit();
    try std.testing.expect(line.value.object.get("unaudited").?.bool);
    try std.testing.expect(!line.value.object.get("retryable").?.bool);
    try std.testing.expectEqualStrings(DELEGATE_NO_WORKTREE_TEXT, jsonStr(line.value, "error"));
    try std.testing.expect(line.value.object.get("worktree").? == .null);
    // La madre vuelve a «sin auditar» (no se queda «en curso»).
    try std.testing.expectEqual(superagent.OrderStatus.audit_unavailable, mrec.status);
}

test "USUARIO-NUEVO B: profundidad 1 — solo la conversación recibe delegate_tasks" {
    const a = std.testing.allocator;
    // Sin delegate_fn (como en toda tarea despachada por el superagente) la
    // herramienta responde que aquí no se delega, en llano.
    var plain = governed_tool_executor.GovernedToolExecutor{ .plan_approved = true, .agentic = true, .allocator = a };
    defer plain.deinitState(a);
    const res = try governed_tool_executor.GovernedToolExecutor.execute(@ptrCast(&plain), governed_tool_executor.DELEGATE_TOOL_NAME, "{\"tasks\":[]}");
    try std.testing.expect(std.mem.indexOf(u8, res, "delegation_unavailable") != null);
    try std.testing.expect(std.mem.indexOf(u8, res, "no vuelve a delegar") != null);
}

/// Persiste la selección de lanzamiento de una hija best-of-N con el MISMO
/// esquema v1 que persistLaunchModelSelection: ejecutor y planificador fijados
/// al miembro, auditor a null (ruteo con exclusión del fabricante — E5.08).
/// dispatchApprovedOrder(child, is_resume=true) la restaura via
/// loadLaunchModelSelection antes de asignar modelos.
fn persistBestOfNChildSelection(conn: db.Connection, aa: std.mem.Allocator, child_order_id: i64, m: best_of_n.Member, swarm_json: ?[:0]const u8) void {
    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginObject() catch return;
    js.objectField("v") catch return;
    js.write(1) catch return;
    js.objectField("plan_p") catch return;
    js.write(m.provider) catch return;
    js.objectField("plan_m") catch return;
    js.write(m.model) catch return;
    js.objectField("exec_p") catch return;
    js.write(m.provider) catch return;
    js.objectField("exec_m") catch return;
    js.write(m.model) catch return;
    js.objectField("audit_p") catch return;
    js.write(@as(?[]const u8, null)) catch return;
    js.objectField("audit_m") catch return;
    js.write(@as(?[]const u8, null)) catch return;
    js.objectField("swarm") catch return;
    js.write(if (swarm_json) |s| @as(?[]const u8, s) else null) catch return;
    js.endObject() catch return;
    const stmt = conn.prepare("INSERT INTO events (ts, source, kind, payload_json, order_id) VALUES (?, 'core', 'model_selection', ?, ?)") catch return;
    defer conn.finalize(stmt);
    db.bindInt(stmt, 1, health.nowMillis(conn)) catch return;
    db.bindText(stmt, 2, out.written()) catch return;
    db.bindInt(stmt, 3, child_order_id) catch return;
    _ = db.c.sqlite3_step(stmt);
}

/// UPDATE honesto de estado no-terminal (awaiting_best_of_n / running) —
/// mismo guard anti-pisado de terminales que updateOrderStatus.
fn bonSetStatus(conn: db.Connection, order_id: i64, status: []const u8) void {
    const stmt = conn.prepare("UPDATE orders SET status = ? WHERE id = ? AND status NOT IN ('done','failed','rejected','cancelled')") catch return;
    defer conn.finalize(stmt);
    db.bindText(stmt, 1, status) catch return;
    db.bindInt(stmt, 2, order_id) catch return;
    _ = db.c.sqlite3_step(stmt);
}

/// Falla la padre con causa honesta y evento — el motivo viaja legible.
fn bonAbort(st: *CoreState, rec: *OrderRecord, conn: db.Connection, parent_id: i64, cause: []const u8, detail: []const u8) DaResult {
    const aa = st.arena.child_allocator;
    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginObject() catch {};
    js.objectField("cause") catch {};
    js.write(cause) catch {};
    js.objectField("detail") catch {};
    js.write(detail) catch {};
    js.endObject() catch {};
    bonEvent(conn, parent_id, "best_of_n_aborted", out.written());
    _ = conn.tryCommitTerminal(parent_id, "failed", "order_failed", "superagente", out.written(), health.nowMillis(conn)) catch false;
    syncRecStatusFromDb(conn, rec);
    return err(.invalid_state, detail);
}

fn runBestOfN(st: *CoreState, rec: *OrderRecord, conn: db.Connection, outcome: *superagent.OrderOutcome, n_req: u32, members_json: ?[]const u8) DaResult {
    const aa = st.arena.child_allocator;
    const parent_id = rec.db_id orelse rec.id;
    const now = health.nowSeconds(conn);

    rec.status = .running;
    bonSetStatus(conn, parent_id, "running");

    // sup compartido para pick + persistencia de planes hijos. El pin de
    // ejecutor se re-fija por candidata antes de su assignAndPersist.
    var router_storage: model_router.Router = undefined;
    const router_ptr = makeRouter(st, aa, &router_storage, conn);
    defer if (router_ptr) |r| r.deinitHealthCache();
    var memory_scratch: local_memory.LocalMemory = undefined;
    const memory_backend = st.memory.backendForConn(conn, &memory_scratch);
    var sup = superagent.Superagent.init(aa, conn, router_ptr, memory_backend, now);
    sup.rules_catalog = st.catalog.db;
    sup.browser_registry = &st.browser_registry;
    st.external_mutex.lock();
    const external_cat = if (builtin.is_test and st.external_capture_fn == null) null else externalCatalog(st, aa, false) catch |e| blk: {
        std.debug.print("external CLI catalog unavailable for dispatch: {s}; agent tasks fail explicitly, retry agents_external_refresh\n", .{@errorName(e)});
        break :blk null;
    };
    st.external_mutex.unlock();
    defer if (external_cat) |cat| aa.free(cat);
    sup.external_catalog_json = external_cat;
    sup.external_limits = st.external_limits;
    sup.external_run_fn = st.external_run_fn;
    sup.external_run_ctx = st.external_run_ctx;
    sup.external_capture_fn = st.external_capture_fn;
    sup.external_getenv_fn = st.external_getenv_fn;

    if (st.registry) |*r| sup.registry = r;
    sup.od_mcp_state = &st.od_mcp_state;
    sup.order_text = rec.text;
    sup.setSwarmJson(st.swarm_models_json);

    // Candidatas: en reanudación se reusan las filas persistidas (nunca se
    // repican miembros — la composición ya quedó fijada); en fresco se eligen
    // N miembros de proveedores distintos y se crean las filas.
    var cands = best_of_n.listByParent(conn, aa, parent_id) catch
        return bonAbort(st, rec, conn, parent_id, "candidates_list_failed", "best_of_n: no se pudo listar candidatas");
    var cands_owned = true;
    defer if (cands_owned) best_of_n.freeCandidateList(aa, cands);
    if (cands.len == 0) {
        const members = sup.pickBestOfNMembers(aa, n_req, members_json) catch
            return bonAbort(st, rec, conn, parent_id, "members_pick_failed", "best_of_n: OOM eligiendo miembros");
        if (members.len < n_req) {
            var dbuf: [256]u8 = undefined;
            const d = std.fmt.bufPrint(&dbuf, "best_of_n pidió {d} candidatas pero solo hay {d} miembros usables con proveedor distinto (enjambre o lista explícita)", .{ n_req, members.len }) catch "best_of_n: proveedores distintos insuficientes";
            return bonAbort(st, rec, conn, parent_id, "insufficient_distinct_providers", d);
        }
        // Presupuesto ×N ANTES de lanzar: cada miembro no-gratuito necesita al
        // menos una llamada autorizada; sin margen se aborta sin gastar nada.
        var paid_needed: u64 = 0;
        for (members) |m| {
            if (external_agents.isAgentProvider(m.provider)) continue; // suscripción, sin coste marginal
            if (!model_router.catalogModelIsFree(st.catalog.db, m.provider, m.model)) paid_needed += 1;
        }
        if (paid_needed > 0) {
            const est = spend_budget.estado(st.catalog.db);
            if (est.restantes() < paid_needed) {
                var dbuf: [256]u8 = undefined;
                const d = std.fmt.bufPrint(&dbuf, "best_of_n requiere {d} llamadas de pago ({d} candidatas no gratuitas) y el presupuesto autorizado restante es {d} — autoriza más en Ajustes o usa miembros gratuitos", .{ paid_needed, paid_needed, est.restantes() }) catch "best_of_n: presupuesto insuficiente";
                return bonAbort(st, rec, conn, parent_id, "budget_insufficient", d);
            }
        }
        var idx: u32 = 1;
        var new_cands = std.ArrayList(best_of_n.CandidateRow).empty;
        for (members) |m| {
            const cid = best_of_n.insertCandidate(conn, parent_id, idx, .{ .provider = m.provider, .model = m.model }) catch
                return bonAbort(st, rec, conn, parent_id, "candidate_insert_failed", "best_of_n: no se pudo persistir la candidata");
            new_cands.append(aa, .{
                .id = cid,
                .parent_order_id = parent_id,
                .member_idx = idx,
                .provider = aa.dupe(u8, m.provider) catch "",
                .model = aa.dupe(u8, m.model) catch "",
            }) catch
                return bonAbort(st, rec, conn, parent_id, "oom", "best_of_n: OOM registrando candidatas");
            idx += 1;
        }
        cands = new_cands.toOwnedSlice(aa) catch
            return bonAbort(st, rec, conn, parent_id, "oom", "best_of_n: OOM registrando candidatas");
        cands_owned = false; // las strings viven en la arena
        // Evento de composición: la lista fijada queda en el ledger de la padre.
        var out: std.Io.Writer.Allocating = .init(aa);
        defer out.deinit();
        var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
        js.beginObject() catch {};
        js.objectField("n") catch {};
        js.write(cands.len) catch {};
        js.objectField("members") catch {};
        js.beginArray() catch {};
        for (cands) |c| {
            js.beginObject() catch {};
            js.objectField("member_idx") catch {};
            js.write(c.member_idx) catch {};
            js.objectField("provider") catch {};
            js.write(c.provider) catch {};
            js.objectField("model") catch {};
            js.write(c.model) catch {};
            js.endObject() catch {};
        }
        js.endArray() catch {};
        js.endObject() catch {};
        bonEvent(conn, parent_id, "best_of_n_started", out.written());
    }

    // Token de cancelación de la PADRE — se adjunta a cada hija para que
    // cancelar la orden cancele la candidata en vuelo.
    const parent_token: ?*const live_worker.CancellationToken = st.dispatch_registry.retainCancellationToken(parent_id) orelse
        live_worker.CancellationToken.create(std.heap.page_allocator) catch null;
    defer if (parent_token) |t| @constCast(t).release();

    // Worktree de la padre (si la raíz es git): donde cae la fusión aprobada.
    var base_buf: [4096]u8 = undefined;
    const base = workspace.effectiveRoot(&base_buf);
    if (spaces.isGitRepo(aa, base)) {
        var pwt_buf: [4096]u8 = undefined;
        var pdiag: worktree_prepare.Diag = .{};
        _ = ensureOrderSpace(st, conn, rec, base, &pwt_buf, &pdiag) catch |e| {
            var dbuf: [256]u8 = undefined;
            const d = std.fmt.bufPrint(&dbuf, "best_of_n: el worktree de la orden no se pudo preparar: {s}", .{if (pdiag.len > 0) pdiag.msg() else @errorName(e)}) catch "best_of_n: worktree padre fallido";
            return bonAbort(st, rec, conn, parent_id, "worktree_prepare_failed", d);
        };
    }

    var cancelled = false;
    for (cands) |*c| {
        if (parent_token) |t| {
            if (t.isCancelled()) {
                cancelled = true;
                break;
            }
        }
        // Reanudación: candidata ya terminada → conserva métricas, no recorre.
        if (std.mem.eql(u8, c.status, "done") or std.mem.eql(u8, c.status, "failed") or std.mem.eql(u8, c.status, "audit_unavailable")) continue;

        var st_buf: [64]u8 = undefined;
        const child_st = best_of_n.childStatus(conn, c.child_order_id orelse 0, &st_buf);
        if (c.child_order_id != null and std.mem.eql(u8, child_st, "running")) {
            // La hija quedó 'running' de un crash — re-dispatch con checkpoint.
        } else if (c.child_order_id != null and !std.mem.eql(u8, child_st, "running")) {
            // Hija existe pero la candidata no tiene métricas (crash entre
            // dispatch y updateResult): recoger lo que haya.
            const m2 = best_of_n.collectMetrics(conn, c.child_order_id.?, c.metrics.elapsed_ms);
            best_of_n.updateResult(conn, c.id, c.child_order_id, c.space_id, c.plan_id, if (child_st.len > 0) child_st else "failed", m2) catch {};
            c.status = aa.dupe(u8, if (child_st.len > 0) child_st else "failed") catch "failed";
            c.metrics = m2;
            continue;
        }

        // ── Crear la hija (si no existe) ────────────────────────────────
        var child_id: i64 = c.child_order_id orelse 0;
        var space_id: ?i64 = c.space_id;
        var child_plan_id: ?i64 = c.plan_id;
        // El outcome hijo comparte el plan de la padre (solo lectura en el
        // dispatch) con asignaciones propias persistidas bajo su plan_id. Vive
        // en la arena — nunca se deinit por separado (el plan es prestado).
        var child_outcome_storage: superagent.OrderOutcome = undefined;
        if (child_id == 0) {
            child_id = superagent.Superagent.insertOrderRow(conn, rec.project_id, rec.text, "running", now) catch
                return bonAbort(st, rec, conn, parent_id, "child_order_failed", "best_of_n: no se pudo crear la orden hija");
            const pu = conn.prepare("UPDATE orders SET parent_order_id = ? WHERE id = ?") catch return bonAbort(st, rec, conn, parent_id, "child_order_failed", "best_of_n: UPDATE parent_order_id");
            db.bindInt(pu, 1, parent_id) catch {};
            db.bindInt(pu, 2, child_id) catch {};
            _ = db.c.sqlite3_step(pu);
            conn.finalize(pu);
            c.child_order_id = child_id;
        }
        if (child_plan_id == null) {
            const pid = sup.insertPlan(child_id, outcome.plan.understanding, &.{}) catch
                return bonAbort(st, rec, conn, parent_id, "child_plan_failed", "best_of_n: no se pudo clonar el plan");
            child_plan_id = pid;
            c.plan_id = pid;
            const ap = conn.prepare("UPDATE plans SET approved = 1 WHERE id = ?") catch null;
            if (ap) |s| {
                db.bindInt(s, 1, pid) catch {};
                _ = db.c.sqlite3_step(s);
                conn.finalize(s);
            }
            // Pin del ejecutor = miembro; auditor SIN pin (exclusión E5.08).
            sup.setExecForcedModel(c.provider, c.model);
            sup.setAuditForcedModel(null, null);
            const child_assignments = sup.assignAndPersist(pid, outcome.plan.tasks) catch
                return bonAbort(st, rec, conn, parent_id, "child_assign_failed", "best_of_n: no se pudo persistir la asignación hija");
            c.metrics.status = "assigned";
            c.child_order_id = child_id;
            child_outcome_storage = superagent.OrderOutcome{
                .allocator = aa,
                .order_id = child_id,
                .plan_id = pid,
                .status = .running,
                .plan = outcome.plan,
                .assignments = child_assignments,
                .discovery_needed = &.{},
                .discovery_missing = &.{},
                .discovery_needed_resources = &.{},
            };
        } else {
            // Reanudación: plan y tareas ya persistidas. Las asignaciones en
            // memoria quedan vacías — refreshAssignmentsForDispatch las
            // reconstruye al despachar con el pin del miembro (restaurado de
            // model_selection), sin duplicar filas en la BD.
            child_outcome_storage = superagent.OrderOutcome{
                .allocator = aa,
                .order_id = child_id,
                .plan_id = child_plan_id,
                .status = .running,
                .plan = outcome.plan,
                .assignments = aa.alloc(superagent.ModelAssignment, 0) catch
                    return bonAbort(st, rec, conn, parent_id, "oom", "best_of_n: OOM"),
                .discovery_needed = &.{},
                .discovery_missing = &.{},
                .discovery_needed_resources = &.{},
            };
        }

        // Space propio `orden-<padre>-m<k>` si aún no lo tiene.
        if (space_id == null) {
            const name = std.fmt.allocPrint(aa, "orden-{d}-m{d}", .{ parent_id, c.member_idx }) catch
                return bonAbort(st, rec, conn, parent_id, "oom", "best_of_n: OOM nombrando space");
            var cdiag: worktree_prepare.Diag = .{};
            var audit_ctx: WorktreeAuditCtx = .{ .st = st, .order_id = child_id };
            var sp = spaces.createSpace(aa, conn, rec.project_id, name, .order, base, .{
                .order_id = child_id,
                .diag = &cdiag,
                .audit_fn = worktreeAuditSink,
                .audit_ctx = &audit_ctx,
            }) catch |e| {
                if (worktree_prepare.isPrepError(e)) {
                    var dbuf: [256]u8 = undefined;
                    const d = std.fmt.bufPrint(&dbuf, "best_of_n: space de la candidata m{d} falló: {s}", .{ c.member_idx, if (cdiag.len > 0) cdiag.msg() else @errorName(e) }) catch "best_of_n: space fallido";
                    return bonAbort(st, rec, conn, parent_id, "worktree_prepare_failed", d);
                }
                return bonAbort(st, rec, conn, parent_id, "space_failed", "best_of_n: no se pudo crear el space de la candidata");
            };
            space_id = sp.id;
            c.space_id = sp.id;
            const su = conn.prepare("UPDATE orders SET space_id = ? WHERE id = ?") catch null;
            if (su) |s| {
                db.bindInt(s, 1, sp.id) catch {};
                db.bindInt(s, 2, child_id) catch {};
                _ = db.c.sqlite3_step(s);
                conn.finalize(s);
            }
            // sp se libera al final del scope — la arena lo absorbe.
            _ = &sp;
        }

        persistBestOfNChildSelection(conn, aa, child_id, .{ .provider = c.provider, .model = c.model }, st.swarm_models_json);

        // ── Despachar la hija por la maquinaria normal ──────────────────
        {
            var ev: std.Io.Writer.Allocating = .init(aa);
            defer ev.deinit();
            var js: std.json.Stringify = .{ .writer = &ev.writer, .options = .{} };
            js.beginObject() catch {};
            js.objectField("candidate_id") catch {};
            js.write(c.id) catch {};
            js.objectField("member_idx") catch {};
            js.write(c.member_idx) catch {};
            js.objectField("provider") catch {};
            js.write(c.provider) catch {};
            js.objectField("model") catch {};
            js.write(c.model) catch {};
            js.objectField("child_order_id") catch {};
            js.write(child_id) catch {};
            js.endObject() catch {};
            bonEvent(conn, parent_id, "best_of_n_candidate_started", ev.written());
        }

        var child_rec = OrderRecord{
            .id = child_id,
            .db_id = child_id,
            .text = rec.text,
            .project_id = rec.project_id,
            .status = .running,
            .plan_json = null,
            .outcome = child_outcome_storage,
            .questions = &.{},
            .created_at = now,
        };
        const t0 = GetTickCount64();
        const rc = dispatchApprovedOrder(st, &child_rec, conn, true);
        const elapsed: i64 = @intCast(GetTickCount64() - t0);
        // La DB es la autoridad del estado de la hija.
        var st_buf2: [64]u8 = undefined;
        const final_st = best_of_n.childStatus(conn, child_id, &st_buf2);
        const metrics = best_of_n.collectMetrics(conn, child_id, elapsed);
        const st_txt = if (final_st.len > 0) final_st else if (rc == .ok) "done" else "failed";
        best_of_n.updateResult(conn, c.id, child_id, space_id, c.plan_id, st_txt, metrics) catch {};
        c.status = aa.dupe(u8, st_txt) catch st_txt;
        c.metrics = metrics;
        c.metrics.status = c.status;

        var ev2: std.Io.Writer.Allocating = .init(aa);
        defer ev2.deinit();
        var js2: std.json.Stringify = .{ .writer = &ev2.writer, .options = .{} };
        js2.beginObject() catch {};
        js2.objectField("candidate_id") catch {};
        js2.write(c.id) catch {};
        js2.objectField("child_order_id") catch {};
        js2.write(child_id) catch {};
        js2.objectField("status") catch {};
        js2.write(st_txt) catch {};
        js2.objectField("gates") catch {};
        js2.beginObject() catch {};
        js2.objectField("pass") catch {};
        js2.write(metrics.gates_pass) catch {};
        js2.objectField("fail") catch {};
        js2.write(metrics.gates_fail) catch {};
        js2.endObject() catch {};
        js2.objectField("tests") catch {};
        js2.beginObject() catch {};
        js2.objectField("pass") catch {};
        js2.write(metrics.tests_pass) catch {};
        js2.objectField("fail") catch {};
        js2.write(metrics.tests_fail) catch {};
        js2.endObject() catch {};
        js2.objectField("verdict") catch {};
        js2.write(metrics.verdict.toText()) catch {};
        js2.objectField("cost_tokens") catch {};
        js2.write(metrics.cost_tokens) catch {};
        js2.objectField("elapsed_ms") catch {};
        js2.write(metrics.elapsed_ms) catch {};
        js2.endObject() catch {};
        bonEvent(conn, parent_id, "best_of_n_candidate_finished", ev2.written());
    }

    if (cancelled) {
        for (cands) |*c| {
            if (!std.mem.eql(u8, c.status, "done") and !std.mem.eql(u8, c.status, "failed") and !std.mem.eql(u8, c.status, "audit_unavailable")) {
                best_of_n.updateResult(conn, c.id, c.child_order_id, c.space_id, c.plan_id, "cancelled", c.metrics) catch {};
            }
        }
        bonEvent(conn, parent_id, "best_of_n_aborted", "{\"cause\":\"cancelled\"}");
        _ = conn.tryCommitTerminal(parent_id, "cancelled", "order_cancelled", "superagente", "{\"cause\":\"best_of_n_cancelled\"}", health.nowMillis(conn)) catch false;
        syncRecStatusFromDb(conn, rec);
        return ok();
    }

    // ── Ranking determinista: ordenar por ranksAbove (estable por member_idx)
    // y asignar rank de competición (empate total = mismo rank → el usuario
    // decide; no hay desempate silencioso).
    std.mem.sort(best_of_n.CandidateRow, cands, {}, struct {
        fn lt(_: void, a: best_of_n.CandidateRow, b: best_of_n.CandidateRow) bool {
            if (best_of_n.ranksAbove(a.metrics, b.metrics)) return true;
            if (best_of_n.ranksAbove(b.metrics, a.metrics)) return false;
            return a.member_idx < b.member_idx;
        }
    }.lt);
    best_of_n.assignRanks(cands);
    for (cands) |*c| {
        if (c.rank) |r| best_of_n.setRank(conn, c.id, r);
    }

    var out3: std.Io.Writer.Allocating = .init(aa);
    defer out3.deinit();
    var js3: std.json.Stringify = .{ .writer = &out3.writer, .options = .{} };
    js3.beginObject() catch {};
    js3.objectField("candidates") catch {};
    js3.beginArray() catch {};
    for (cands) |*c| {
        js3.beginObject() catch {};
        js3.objectField("candidate_id") catch {};
        js3.write(c.id) catch {};
        js3.objectField("member_idx") catch {};
        js3.write(c.member_idx) catch {};
        js3.objectField("provider") catch {};
        js3.write(c.provider) catch {};
        js3.objectField("model") catch {};
        js3.write(c.model) catch {};
        js3.objectField("rank") catch {};
        js3.write(c.rank) catch {};
        js3.objectField("status") catch {};
        js3.write(c.status) catch {};
        js3.endObject() catch {};
    }
    js3.endArray() catch {};
    js3.endObject() catch {};
    bonEvent(conn, parent_id, "best_of_n_ranked", out3.written());

    // La padre queda esperando la elección del usuario — NO es terminal.
    bonSetStatus(conn, parent_id, "awaiting_best_of_n");
    rec.status = .awaiting_best_of_n;
    return ok();
}

fn dispatchApprovedOrder(st: *CoreState, rec: *OrderRecord, conn: db.Connection, is_resume: bool) DaResult {
    const aa = st.arena.child_allocator;

    if (rec.outcome == null) {
        return err(.invalid_state, "dispatchApprovedOrder: planned order has no executable persisted outcome");
    }

    var all_failed: bool = false;
    if (rec.outcome) |*outcome| {
        // La orden puede tener `id` interno de la fila clarifying y `db_id` de
        // la fila real del plan: los eventos, el estado y la cancelación deben
        // atribuirse a la fila que el usuario y runtime.db ven — `db_id`.
        const dispatch_db_id = rec.db_id orelse rec.id;
        // E5.18 (D-C5): una orden con `best_of_n` no despacha su plan directo —
        // corre la orquestación de candidatas (una hija por miembro, proveedor
        // distinto, worktree propio). En reanudación entra igual: runBestOfN
        // salta las candidatas ya terminadas.
        {
            const bon_cfg = best_of_n.orderConfig(conn, aa, dispatch_db_id);
            defer if (bon_cfg.members_json) |mj| aa.free(mj);
            if (bon_cfg.n >= best_of_n.MIN_N and bon_cfg.n <= best_of_n.MAX_N) {
                return runBestOfN(st, rec, conn, outcome, bon_cfg.n, bon_cfg.members_json);
            }
        }
        st.perm_mutex.lock();
        const order_deterministic = st.plan_deterministic;
        var order_snapshot = permission_snapshot.OwnedPermissionSnapshot.initCloneRoles(
            aa,
            st.perm_mode,
            st.perm_allow.items,
            st.perm_deny.items,
            st.perm_session_allow.items,
            st.plan_forced_provider,
            st.plan_forced_model,
            st.exec_forced_provider,
            st.exec_forced_model,
            st.audit_forced_provider,
            st.audit_forced_model,
            st.swarm_models_json,
        ) catch {
            st.perm_mutex.unlock();
            return err(.oom, "dispatchApprovedOrder: OOM cloning permission snapshot");
        };
        st.perm_mutex.unlock();
        defer order_snapshot.deinit(aa);

        // la selección de modelo es un dato DE LA ORDEN, no del proceso.
        // En el despacho inicial se persiste en el ledger; en reanudación
        // (post-reinicio, globales vacíos) se restaura — un resume local nunca
        // puede reenrutar a un modelo de pago. Los permisos NO se restauran:
        // son política viva del proceso, no dato congelado de la orden.
        if (is_resume) {
            if (loadLaunchModelSelection(aa, conn, dispatch_db_id)) |*sel| {
                order_snapshot.applyModelSelection(aa, sel) catch {};
            }
        } else {
            persistLaunchModelSelection(conn, aa, dispatch_db_id, &order_snapshot);
        }

        const now = health.nowSeconds(conn);
        var router_storage: model_router.Router = undefined;
        const router_ptr = makeRouter(st, aa, &router_storage, conn);
        defer if (router_ptr) |r| r.deinitHealthCache();
        // MULTISESSION-P0 (2026-07-12): si st.memory usa el fallback LocalMemory,
        // memory_backend queda atado a `conn` (la Connection propia de este hilo)
        // en vez de la conexión original de st.memory — última fuga conocida
        // hacia st.db_conn desde el hilo de dispatch. `memory_scratch` vive en
        // este scope hasta el final del bloque (mismo scope que `sup`/`conn`),
        // así que nunca sobrevive a la conexión del hilo. st.memory en sí NUNCA
        // se muta (backendForConn es de solo lectura sobre una vista distinta).
        var memory_scratch: local_memory.LocalMemory = undefined;
        const memory_backend = st.memory.backendForConn(conn, &memory_scratch);
        // MULTISESSION-P0 (2026-07-12): último uso conocido de st.db_conn desde el
        // hilo de dispatch — st.sessions (SessionStore) capturaba su PROPIA
        // Connection en createSqliteStore (== st.db_conn de entonces); saveMessageToDb
        // seguía escribiendo ahí pese a recibir `conn` solo para el timestamp. La vista
        // temporal vive en `session_scratch` (mismo scope que `sup`/`conn`, nunca
        // sobrevive al hilo); st.sessions NUNCA se muta (sessionStoreForConn es una
        // vista de solo-construcción sobre otra Connection, con deinit no-op).
        var session_scratch: session_store.SqliteBackend = undefined;
        const session_view: ?session_store.SessionStore = if (st.sessions != null)
            session_store.sessionStoreForConn(conn, &session_scratch)
        else
            null;
        var sup = superagent.Superagent.init(aa, conn, router_ptr, memory_backend, now);
        sup.rules_catalog = st.catalog.db;
        sup.browser_registry = &st.browser_registry;
        // C2: token de cancelación para ESTE despacho.
        // (dispatch_db_id se calcula arriba, junto al snapshot — es la fila
        // real del plan en runtime.db.)
        const cancel_token: ?*const live_worker.CancellationToken = if (st.dispatch_registry.retainCancellationToken(dispatch_db_id)) |token|
            token
        else blk: {
            const token = live_worker.CancellationToken.create(std.heap.page_allocator) catch null;
            break :blk token;
        };
        defer if (cancel_token) |token| @constCast(token).release();
        sup.cancel_token = cancel_token;
        if (st.registry) |*r| sup.registry = r;
        sup.od_mcp_state = &st.od_mcp_state;
        // P12-T3: inyectar selector agéntico + inventario + texto de orden.
        if (st.discovery_llm) |*dl| sup.discovery_llm = dl;
        if (st.inventory) |*inv| sup.inventory_ptr = inv;
        sup.order_text = rec.text;
        // MODELO-MANUAL-ORQUESTACION: propagar el modelo fijado por plan_set_model — antes
        // solo alimentaba la llamada de planificación; assignModel (dispatch por-tarea) lo
        // ignoraba y siempre enrutaba free-first pese a que el usuario fijó un modelo.
        // ROLES-MODELO: el pin del ejecutor es exec ?? plan; el del auditor es
        // audit ?? plan (resueltos al capturar el snapshot). El auditor jamás
        // hereda del ejecutor — auditoría con el modelo constructor no cuenta.
        sup.setForcedModel(order_snapshot.exec_forced_provider, order_snapshot.exec_forced_model);
        sup.setAuditForcedModel(order_snapshot.audit_forced_provider, order_snapshot.audit_forced_model);
        // ENJAMBRE: el conjunto capturado al aprobar la orden — un cambio del
        // usuario posterior no muta este despacho.
        sup.setSwarmJson(order_snapshot.swarm_json);
        sup.deterministic = order_deterministic;
        // F0: inyectar conexión para emitir eventos de ciclo de vida ligados a la orden.
        sup.setEventConn(conn, dispatch_db_id);
        // CHECKPOINT-T2: un despacho de REANUDACIÓN lee el checkpoint
        // persistido — sin él la orden correría entera otra vez, rehaciendo
        // trabajo ya hecho. Si la carga falla, reanudar degrada a re-ejecución
        // completa (nunca a fingir que algo se hizo).
        if (is_resume) {
            if (outcome.plan_id) |pid| {
                sup.resume_checkpoint = loadResumeCheckpoint(aa, conn, pid) catch null;
            }
        }
        // P2: inyectar configuración de permisos.
        sup.permission_config = order_snapshot.permissionConfig();
        // E5.08 — GOBIERNO ENCIMA: límites de agentes externos y seams de
        // ejecución/detección (los seams de test se propagan; null = real).
        st.external_mutex.lock();
        const external_cat = if (builtin.is_test and st.external_capture_fn == null) null else externalCatalog(st, aa, false) catch |e| blk: {
            std.debug.print("external CLI catalog unavailable for dispatch: {s}; agent tasks fail explicitly, retry agents_external_refresh\n", .{@errorName(e)});
            break :blk null;
        };
        st.external_mutex.unlock();
        defer if (external_cat) |cat| aa.free(cat);
        sup.external_catalog_json = external_cat;
        sup.external_limits = st.external_limits;
        sup.external_run_fn = st.external_run_fn;
        sup.external_run_ctx = st.external_run_ctx;
        sup.external_capture_fn = st.external_capture_fn;
        sup.external_getenv_fn = st.external_getenv_fn;
        // El plan autoriza las tareas; denylist y código inline conservan
        // aprobación humana explícita de cada comando.
        sup.plan_approved = true;
        // Un plan confirmado por MCP autoriza las tareas, no la ejecución sin
        // humano: cada comando no-consulta pasa por tarjeta de la cabina.
        if (st.mcp_surface) sup.order_origin = .mcp;
        // FIX-DISPATCH-P0: marcar running ANTES de llamar approveAndDispatch para que
        // da_order_status refleje el estado correcto aunque el dispatch tarde o cuelgue.
        rec.status = .running;
        // B3-SPACE-PER-ORDER (F5): la orden trabaja aislada en su worktree del
        // space cuando la raiz efectiva es un repo git real. El override es
        // thread-local: solo ESTE hilo de dispatch lo ve — UI, poller y otras
        // ordenes concurrentes siguen en la raiz global. Sin repo no hay space
        // (la orden escribe en la raiz como antes) y ship devolvera
        // NotAGitRepo honesto. Va DESPUES de status=.running: git worktree add
        // puede tardar y la orden ya esta corriendo mientras prepara su sitio.
        {
            var space_base_buf: [4096]u8 = undefined;
            const space_base = workspace.effectiveRoot(&space_base_buf);
            var space_wt_buf: [4096]u8 = undefined;
            // E5.18: una hija best-of-N puede traer space degradado (directorio
            // sin git) — orderSpacePath lo encuentra aunque la base no sea repo
            // y el aislamiento por directorio sigue siendo real. Sin space
            // previo, la creación exige repo git como siempre.
            if (orderSpacePath(conn, dispatch_db_id, &space_wt_buf)) |p| {
                workspace.setOrderRootOverride(p);
            } else if (spaces.isGitRepo(aa, space_base)) {
                var prep_diag: worktree_prepare.Diag = .{};
                if (ensureOrderSpace(st, conn, rec, space_base, &space_wt_buf, &prep_diag)) |opt| {
                    if (opt) |p| workspace.setOrderRootOverride(p);
                } else |e| {
                    // E5.04/la preparación del worktree falló → la orden
                    // cae con la causa real; NO se sigue en la raíz (sería
                    // escribir donde el usuario pidió aislamiento).
                    persistOrderTasksStatus(conn, dispatch_db_id, "failed");
                    var out: std.Io.Writer.Allocating = .init(aa);
                    defer out.deinit();
                    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
                    js.beginObject() catch return err(.internal, "dispatchApprovedOrder: OOM");
                    js.objectField("cause") catch return err(.internal, "dispatchApprovedOrder: OOM");
                    js.write("worktree_prepare_failed") catch return err(.internal, "dispatchApprovedOrder: OOM");
                    js.objectField("detail") catch return err(.internal, "dispatchApprovedOrder: OOM");
                    js.write(if (prep_diag.len > 0) prep_diag.msg() else @errorName(e)) catch return err(.internal, "dispatchApprovedOrder: OOM");
                    js.endObject() catch return err(.internal, "dispatchApprovedOrder: OOM");
                    _ = conn.tryCommitTerminal(dispatch_db_id, "failed", "order_failed", "superagente", out.written(), health.nowMillis(conn)) catch false;
                    syncRecStatusFromDb(conn, rec);
                    var ebuf: [768]u8 = undefined;
                    const emsg = std.fmt.bufPrint(&ebuf, "dispatchApprovedOrder: worktree prepare failed: {s}", .{
                        if (prep_diag.len > 0) prep_diag.msg() else @errorName(e),
                    }) catch "dispatchApprovedOrder: worktree prepare failed";
                    return err(.invalid_state, emsg);
                }
            }
        }
        defer workspace.setOrderRootOverride(null);
        // Ejecución VIVA: si hay clave configurada en catalog.db, despacha a un LLM real
        // (NativeWorker + credentials + conector). Una asignación viva sin clave falla.
        // MODO-DETERMINISTA: esta es la cadena que en la orden 113 quemó 10 modelos
        // antes de rendirse. Con un modelo fijado y el modo activo, se reduce a ese
        // modelo y solo ese; si falla, falla nombrándolo.
        const pinned = order_snapshot.forced_provider != null and order_snapshot.forced_model != null and !external_agents.isAgentProvider(order_snapshot.forced_provider.?);
        var live_opt = if (pinned)
            (if (order_deterministic)
                live_worker.LiveLlm.initExact(aa, st.catalog_path, order_snapshot.forced_provider.?, order_snapshot.forced_model.?)
            else
                live_worker.LiveLlm.initForced(aa, st.catalog_path, order_snapshot.forced_provider.?, order_snapshot.forced_model.?))
        else
            live_worker.LiveLlm.init(aa, st.catalog_path);
        const exec_uses_plan = order_snapshot.exec_forced_provider == null or
            (pinned and std.mem.eql(u8, order_snapshot.exec_forced_provider.?, order_snapshot.forced_provider.?) and
                order_snapshot.exec_forced_model != null and std.mem.eql(u8, order_snapshot.exec_forced_model.?, order_snapshot.forced_model.?));
        if (pinned and live_opt == null and exec_uses_plan) {
            persistOrderTasksStatus(conn, dispatch_db_id, "failed");
            const reason = std.fmt.allocPrint(aa, "{s}/{s}: modelo no disponible con la gobernanza, claves o catalogo actuales; cambia a un modelo elegible o a la suscripcion", .{ order_snapshot.forced_provider.?, order_snapshot.forced_model.? }) catch return err(.oom, "dispatch diagnostic OOM");
            defer aa.free(reason);
            const body = std.json.Stringify.valueAlloc(aa, .{ .cause = "selected_model_unavailable", .provider = order_snapshot.forced_provider, .model = order_snapshot.forced_model, .reason = reason }, .{}) catch return err(.oom, "dispatch diagnostic OOM");
            defer aa.free(body);
            _ = conn.tryCommitTerminal(dispatch_db_id, "failed", "order_failed", "superagente", body, health.nowMillis(conn)) catch false;
            syncRecStatusFromDb(conn, rec);
            return err(.invalid_state, "dispatchApprovedOrder: selected model is unavailable under current governance");
        }
        // Registro PASIVO de salud: cada intento del fallback vivo marca model_health
        // (mismo runtime.db que lee da_health_summary_json y el panel de la GUI).
        // UX-08: también registramos eventos de fallback/proveedor ligados a esta orden.
        if (live_opt) |*l| {
            l.deterministic = order_deterministic;
            l.setHealthConn(conn);
            l.setEventConn(conn, dispatch_db_id);
            l.reorderByHealth();
            if (cancel_token) |tok| l.setCancelToken(tok);
        }
        defer if (live_opt) |*l| l.deinit();
        // FIX-P11-CRASH: Clear LLM pointers on discovery_llm before LiveLlm is
        // deinitialized. approveAndDispatch calls setLlm(ctx, fn) which stores
        // a pointer to the local LiveLlm in st.discovery_llm.llm_ctx. After
        // this function returns, the defer above frees LiveLlm, leaving a
        // dangling pointer. The next order's ensureInventory checks llm_fn != null
        // and uses the dangling llm_ctx → use-after-free → crash.
        // This defer runs BEFORE l.deinit() (LIFO order), clearing the pointers.
        defer if (st.discovery_llm) |*dl| {
            dl.llm_ctx = null;
            dl.llm_fn = null;
        };
        // FASE-AGENTIC-3: propagar el tope de iteraciones del loop observe→re-planifica.
        // Default 1 (agentic_max_iterations) → agenticExecute hace un solo dispatch,
        // idéntico a approveAndDispatch (el evaluador/re-plan NO corren).
        sup.max_agent_iterations = st.agentic_max_iterations;
        // Planner para re-planificar objetivos de seguimiento (solo se usa si el
        // loop está activado y el evaluador pide otro paso). Construido como en
        // planThreadFn; con el gate en 1 queda sin usar (coste despreciable).
        var loop_planner = live_planner.LlmPlanner.init(aa, st.catalog_path);
        loop_planner.history = st.history.turns.items;
        loop_planner.forced_provider = order_snapshot.forced_provider;
        loop_planner.forced_model = order_snapshot.forced_model;
        loop_planner.event_conn = conn;
        const loop_backend = loop_planner.backend();
        // LOCAL-JSON (E5.03): el paso evaluador pide su esquema de decisión a
        // los candidatos locales vía el envoltorio — el mismo LiveLlm sirve
        // también a las tareas, así que el esquema se fija en cada entrada.
        var eval_ctx: live_worker.LiveLlm.EvaluatorCallCtx = undefined;
        if (live_opt) |*l| eval_ctx = .{ .live = l };
        var dr = (if (st.test_llm_fn) |tf|
            sup.agenticExecute(outcome, loop_backend, tf, st.test_llm_ctx, st.catalog_path, rec.text, null, null)
        else if (live_opt) |*l|
            sup.agenticExecute(outcome, loop_backend, live_worker.LiveLlm.llmFn, l, st.catalog_path, rec.text, live_worker.LiveLlm.evaluatorCompleteObjectFn, &eval_ctx)
        else
            sup.agenticExecute(outcome, loop_backend, null, null, st.catalog_path, rec.text, null, null)) catch |e| {
            setLastError(@errorName(e));
            // TERMINAL-STATE-DESIGN-2026-07-12 (P0 cierre): dispatch_failed queda
            // puramente informativo — ya NO fuerza orders.status a failed (ni en DB
            // ni en memoria). Si agenticExecute ya comprometió un terminal real antes
            // de lanzar esta excepción, ese terminal debe sobrevivir intacto; si no
            // comprometió ninguno, la orden queda como estaba (p. ej. running) hasta
            // que un commit real la resuelva. Las tareas huérfanas sí se marcan.
            persistOrderTasksStatus(conn, dispatch_db_id, "failed");
            noteDispatchFailureAndMaybeAutoVerify(st, dispatch_db_id, conn);
            // FIX-DISPATCH-P0: emit event so failure is visible in order_events.
            {
                var out: std.Io.Writer.Allocating = .init(aa);
                defer out.deinit();
                var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
                js.beginObject() catch {};
                js.objectField("error") catch {};
                js.write(@errorName(e)) catch {};
                js.endObject() catch {};
                sup.recordEvent("dispatch_failed", out.written());
            }
            return err(.internal, "dispatch failed");
        };
        defer dr.deinit(aa);

        // FASE-AGENTIC-2: persistir el entregable real como turno "agent" — se
        // suma al turno de "understanding" ya guardado al planificar (da_order_submit),
        // así el historial de conversación (FASE 1) tiene tanto el reconocimiento
        // inicial como el resultado real, y la UI puede mostrar el entregable.
        if (dr.final_answer.len > 0) {
            saveMessageToDb(session_view, dispatch_db_id, "agent", dr.final_answer, conn);
        }

        // ENGRAM-WIRE-07: persistir hallazgos y resumen de sesión en memoria.
        // MULTISESSION-P0: reusa memory_backend (atado a `conn`) — NUNCA
        // st.memory.backend() de nuevo, que volvería a apuntar a st.db_conn.
        // C3-REGISTRY: memory_mutex serializa esto entre órdenes concurrentes —
        // necesario para el backend `.engram` (McpClient compartido, no
        // thread-safe; ver comentario en CoreState.memory_mutex).
        st.memory_mutex.lock();
        memory_backend.saveFinding(dr.report);
        st.memory_mutex.unlock();
        const summary_opt: ?[]u8 = std.fmt.allocPrint(aa, "Orden {d}: {d} completadas, {d} fallidas, {d} aprobadas pendientes", .{
            dispatch_db_id,
            dr.completed_count,
            dr.failed_count,
            dr.pending_approvals.len,
        }) catch null;
        defer if (summary_opt) |s| aa.free(s);
        st.memory_mutex.lock();
        memory_backend.saveSessionSummary(summary_opt orelse "orden completada", rec.project_id);
        st.memory_mutex.unlock();

        // TERMINAL-STATE-DESIGN-2026-07-12 (P0 cierre): usa el MISMO criterio que
        // superagent.zig ya calculó (dr.order_failed = order_really_failed) en vez
        // de recomputar uno propio a partir de dr.completed_count==0. Los dos podían
        // divergir exactamente cuando había aprobaciones de ejecución pendientes con
        // 0 tareas completadas todavía: order_failed ya es false ahí (awaiting_
        // approval no es un fallo), pero el criterio independiente marcaba
        // all_failed=true y forzaba la rama de fallo sobre una orden que solo estaba
        // pausada. dr.order_failed ya incluye completed==0 como uno de sus criterios
        // (P1-FALSE-GREEN), así que esto no pierde cobertura, solo elimina la
        // duplicación y la posible discrepancia.
        if (dr.order_failed) {
            all_failed = true;
        }

        // Volcar todas las salidas (reporte + posible salida del executor gobernado)
        // al panel de consolas de la GUI vía da_worker_output_poll y, de forma aditiva,
        // a la tabla events para que el driver CLI-JSON pueda leerlas entre procesos.
        // Phase 4: proteger mutaciones de worker_outputs y approvals con output_mutex.
        st.output_mutex.lock();
        for (dr.outputs) |so| {
            st.output_seq += 1;
            const wo = WorkerOutput{
                .worker_id = aa.dupe(u8, so.worker_id) catch continue,
                .stream = aa.dupe(u8, so.stream) catch continue,
                .text = aa.dupe(u8, so.text) catch continue,
                .ts_ms = st.output_seq,
                .task_id = "",
            };
            st.worker_outputs.append(aa, wo) catch {
                aa.free(wo.worker_id);
                aa.free(wo.stream);
                aa.free(wo.text);
                continue;
            };
            insertWorkerOutputEvent(conn, aa, dispatch_db_id, wo.worker_id, wo.stream, wo.text, wo.ts_ms, so.task_id) catch {};
        }

        // El reporte consolidado siempre se expone como salida del superagente.
        st.output_seq += 1;
        const wo_rep = WorkerOutput{
            .worker_id = aa.dupe(u8, "superagente") catch "superagente",
            .stream = aa.dupe(u8, "reporte") catch "reporte",
            .text = aa.dupe(u8, dr.report) catch dr.report,
            .ts_ms = st.output_seq,
            .task_id = "",
        };
        st.worker_outputs.append(aa, wo_rep) catch {
            aa.free(wo_rep.text);
            st.output_mutex.unlock();
            return ok();
        };
        insertWorkerOutputEvent(conn, aa, dispatch_db_id, wo_rep.worker_id, wo_rep.stream, wo_rep.text, wo_rep.ts_ms, wo_rep.task_id) catch {};

        // Las acciones que escapan de la política generan aprobaciones reales.
        for (dr.pending_approvals) |req| {
            // el registro en memoria es propietario de todas sus cadenas.
            // Antes copiaba task_id y description pero guardaba command_prefix,
            // exe y args_json como punteros a `req`, que `dr.deinit` libera al
            // salir de este bloque: el siguiente approvals_list leía memoria
            // liberada y el proceso moría (el driver MCP lo vio como un
            // tools/call colgado 120 s; la #748 de la campaña r4).
            // T12 M5: orden pedida por MCP: la tarjeta dice si un cliente MCP
            // escribió archivos del proyecto en los últimos minutos.
            var mcp_root_buf: [4096]u8 = undefined;
            var noted_req = req;
            const noted = if (st.mcp_surface) withRecentMcpWritesNote(aa, conn, req.description, workspace.projectOrEffectiveRoot(&mcp_root_buf)) catch |e| blk: {
                std.log.warn("aviso de escrituras MCP no añadido a la tarjeta: {s}", .{@errorName(e)});
                break :blk null;
            } else null;
            defer if (noted) |text| aa.free(text);
            if (noted) |text| noted_req.description = text;
            // T12B B-2 (auditor 3): la tarjeta del despacho también es de la
            // sesión MCP que originó la orden; se marca en la base (sobrevive
            // al reinicio) y se registra en memoria para esta sesión.
            const id = insertApprovalToDbOrigin(conn, noted_req.task_id, noted_req.description, 0, noted_req.command_prefix, noted_req.exe, noted_req.args_json, dispatch_db_id, if (st.mcp_surface) st.mcp_origin else "") catch blk: {
                st.last_approval_id += 1;
                break :blk st.last_approval_id;
            };
            const app = aprobacionDesdePeticion(aa, id, noted_req, dispatch_db_id) catch continue;
            st.approvals.append(aa, app) catch {
                var a_mut = app;
                a_mut.deinit(aa);
                continue;
            };
            if (st.mcp_surface) st.mcp_owned_approvals.append(st.arena.child_allocator, id) catch |e| std.log.err("MCP approval ownership: {s}", .{@errorName(e)});
            if (id > st.last_approval_id) st.last_approval_id = id;
            insertApprovalEvent(conn, aa, dispatch_db_id, id, app.task_id, app.description, app.command_prefix);
        }
        st.output_mutex.unlock();

        // FIX-ENGINE-4: marcar status ANTES de escribir audit_ledger.
        // C2 requisito D: cancelled tiene precedencia sobre all_failed — mismo
        // patrón defensivo de "segundo intento, la DB es la autoridad" que la
        // rama failed de abajo, pero SIN persistOrderTasksStatus/noteDispatch-
        // FailureAndMaybeAutoVerify (side-effects de fallo real que no aplican
        // a una cancelación explícita).
        if (dr.order_cancelled) {
            var out: std.Io.Writer.Allocating = .init(aa);
            defer out.deinit();
            var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
            js.beginObject() catch {};
            js.objectField("completed") catch {};
            js.write(dr.completed_count) catch {};
            js.objectField("failed") catch {};
            js.write(dr.failed_count) catch {};
            js.endObject() catch {};
            _ = conn.tryCommitTerminal(dispatch_db_id, "cancelled", "order_cancelled", "superagente", out.written(), health.nowMillis(conn)) catch false;
            // superagent ya debió comprometer este mismo terminal dentro de
            // approveAndDispatch/finalizeDeferredOrder; esto es solo un segundo
            // intento defensivo (p. ej. si la orden estaba en has_exec_approvals).
            // La DB es la autoridad — sync refleja lo que realmente ganó.
            syncRecStatusFromDb(conn, rec);
        } else if (all_failed) {
            // TERMINAL-STATE-DESIGN-2026-07-12: status+evento ya no se escriben por
            // separado (persistOrderAndTasksFailed hacía un UPDATE incondicional).
            // La transición de orders.status ahora vive dentro de tryCommitTerminal,
            // atada a la MISMA transacción que el evento order_failed; el reflejo en
            // memoria (rec.status) solo se aplica si ese commit realmente ganó —
            // evita pisar un terminal que agenticExecute ya haya committeado antes
            // de llegar aquí (la doble emisión que documentaba TERMINAL-EVENTS-
            // INVENTORY-2026-07-11 Sitio 3).
            persistOrderTasksStatus(conn, dispatch_db_id, "failed");
            noteDispatchFailureAndMaybeAutoVerify(st, dispatch_db_id, conn);
            // P1-FALSE-GREEN: emit order_failed event with accionable cause.
            {
                var out: std.Io.Writer.Allocating = .init(aa);
                defer out.deinit();
                var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
                js.beginObject() catch {};
                js.objectField("completed") catch {};
                js.write(dr.completed_count) catch {};
                js.objectField("failed") catch {};
                js.write(dr.failed_count) catch {};
                js.objectField("cause") catch {};
                if (dr.failed_count > 0) {
                    js.write("all_tasks_failed") catch {};
                } else {
                    js.write("no_tasks_completed") catch {};
                }
                js.endObject() catch {};
                _ = conn.tryCommitTerminal(dispatch_db_id, "failed", "order_failed", "superagente", out.written(), health.nowMillis(conn)) catch false;
                // El superagent puede haber comprometido el mismo terminal antes
                // de llegar aquí; en ese caso este segundo intento devuelve false,
                // pero memoria igualmente debe reflejar el ganador almacenado.
                syncRecStatusFromDb(conn, rec);
            }
        } else {
            // TERMINAL-STATE-DESIGN-2026-07-12 (P0 cierre): la DB es la autoridad.
            // agenticExecute (dentro de approveAndDispatch/finalizeDeferredOrder) ya
            // decidió y comprometió — vía tryCommitTerminal, o vía updateOrderStatus
            // para awaiting_approval — el estado real de esta orden. Recalcular aquí
            // con un criterio propio (has_exec sobre st.approvals) podía divergir del
            // que usó superagent.zig (ctx.pending) y pisar en MEMORIA un "done" que
            // la DB nunca comprometió (o esconder un "failed"/otro terminal que sí
            // ganó la carrera).
            syncRecStatusFromDb(conn, rec);
        }

        // (H-PB-6): si el despacho dejó la orden en un estado
        // terminal (done/failed/cancelled/audit_unavailable), sus aprobaciones
        // de ejecución pendientes ya no son accionables — se cierran al instante
        // (resolved=1, approved=0) para que el Monitor no muestre tarjetas
        // colgadas de órdenes terminadas. No-op si la orden sigue en pausa.
        closeStaleApprovals(st, conn, false, health.nowMillis(conn), "orden terminada");

        // FIX-ENGINE-9: queue audit_entries in memory (no ledger.db I/O from bg thread).
        // The main thread flushes via flushAuditQueue in da_order_dispatch_poll /
        // da_audit_ledger_json. Best-effort: if flush fails, the order already completed.
        if (dr.audit_entries.len > 0) {
            persistAuditEntries(st, aa, dr.audit_entries);
        }
    }

    // P4: la auto-auditoría real ya corre por separado (audit_pipeline). No crear
    // aprobación de auditoría pendiente — era un stub que se acumulaba sin resolver.
    return ok();
}

pub export fn da_order_approve(handle: ?*anyopaque, order: ?*anyopaque) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_order_approve: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order) orelse return @intFromEnum(err(.invalid_arg, "da_order_approve: null order handle"));

    const rec = findOrder(st, order_id) orelse return @intFromEnum(err(.not_found, "da_order_approve: order not found"));
    if (rec.status != .planned) return @intFromEnum(err(.invalid_state, "da_order_approve: order must be in planned state"));

    // Síncrono: sin hilo de dispatch separado, st.db_conn es seguro aquí.
    return @intFromEnum(dispatchApprovedOrder(st, rec, st.db_conn, false));
}

fn planStringsJson(aa: std.mem.Allocator, values: []const []const u8) ![]const u8 {
    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    try js.beginArray();
    for (values) |value| try js.write(value);
    try js.endArray();
    return aa.dupe(u8, out.written());
}

fn planContractFieldsJson(aa: std.mem.Allocator, fields: []const planner.ContractField) ![]const u8 {
    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    try js.beginArray();
    for (fields) |field| {
        try js.beginObject();
        try js.objectField("name");
        try js.write(field.name);
        try js.objectField("type");
        try js.write(@tagName(field.field_type));
        try js.objectField("required");
        try js.write(field.required);
        if (field.value) |value| {
            try js.objectField("value");
            try js.write(value);
        }
        try js.endObject();
    }
    try js.endArray();
    return aa.dupe(u8, out.written());
}

/// Appends a complete plan revision atomically while preserving prior revisions.
/// The latest-id check rejects an editor based on an obsolete in-memory plan.
fn persistEditedPlan(conn: db.Connection, aa: std.mem.Allocator, order_id: i64, expected_plan_id: i64, plan: *const planner.Plan) !i64 {
    try conn.exec("BEGIN IMMEDIATE");
    var tx_open = true;
    errdefer if (tx_open) conn.exec("ROLLBACK") catch {};

    const latest = try conn.prepare("SELECT id, approved FROM plans WHERE order_id = ? ORDER BY id DESC LIMIT 1");
    defer conn.finalize(latest);
    try db.bindInt(latest, 1, order_id);
    const latest_rc = db.c.sqlite3_step(latest);
    if (latest_rc != db.c.SQLITE_ROW) {
        if (latest_rc == db.c.SQLITE_DONE) return error.StalePlan;
        return error.ExecFailed;
    }
    if (db.c.sqlite3_column_int64(latest, 0) != expected_plan_id or db.c.sqlite3_column_int(latest, 1) != 0) return error.StalePlan;

    const insert_plan = try conn.prepare("INSERT INTO plans (order_id, understanding, clarifications_json, approved, created_at) VALUES (?, ?, '[]', 0, ?)");
    defer conn.finalize(insert_plan);
    try db.bindInt(insert_plan, 1, order_id);
    try db.bindText(insert_plan, 2, plan.understanding);
    try db.bindInt(insert_plan, 3, health.nowMillis(conn));
    if (db.c.sqlite3_step(insert_plan) != db.c.SQLITE_DONE) return error.ExecFailed;
    const plan_id = db.c.sqlite3_last_insert_rowid(conn.db);

    for (plan.tasks) |task| {
        const fields_json = try planContractFieldsJson(aa, task.contract_fields);
        defer aa.free(fields_json);
        const depends_json = try planStringsJson(aa, task.depends_on);
        defer aa.free(depends_json);

        const contract = try conn.prepare("INSERT INTO contracts (plan_id, name, interface_spec, consumers_json, producers_json) VALUES (?, ?, ?, ?, '[]')");
        defer conn.finalize(contract);
        try db.bindInt(contract, 1, plan_id);
        try db.bindText(contract, 2, task.id);
        try db.bindText(contract, 3, fields_json);
        try db.bindText(contract, 4, depends_json);
        if (db.c.sqlite3_step(contract) != db.c.SQLITE_DONE) return error.ExecFailed;
        const contract_id = db.c.sqlite3_last_insert_rowid(conn.db);

        const task_stmt = try conn.prepare("INSERT INTO tasks (plan_id, department, task_type, description, contract_id, assigned_model_id, status, created_at) VALUES (?, ?, ?, ?, ?, NULL, 'planned', ?)");
        defer conn.finalize(task_stmt);
        try db.bindInt(task_stmt, 1, plan_id);
        try db.bindText(task_stmt, 2, task.department);
        try db.bindText(task_stmt, 3, task.task_type.toText());
        try db.bindText(task_stmt, 4, task.description);
        try db.bindInt(task_stmt, 5, contract_id);
        try db.bindInt(task_stmt, 6, health.nowMillis(conn));
        if (db.c.sqlite3_step(task_stmt) != db.c.SQLITE_DONE) return error.ExecFailed;
    }

    // La procedencia de esta revisión se guarda en la misma transacción.
    const edit_event = try conn.prepare("INSERT INTO events (order_id, kind, payload_json, ts, source) VALUES (?, 'plan_edited', ?, ?, 'core')");
    defer conn.finalize(edit_event);
    const edit_payload = try std.fmt.allocPrint(aa, "{{\"previous_plan_id\":{d},\"plan_id\":{d},\"task_count\":{d}}}", .{ expected_plan_id, plan_id, plan.tasks.len });
    defer aa.free(edit_payload);
    try db.bindInt(edit_event, 1, order_id);
    try db.bindText(edit_event, 2, edit_payload);
    try db.bindInt(edit_event, 3, health.nowMillis(conn));
    if (db.c.sqlite3_step(edit_event) != db.c.SQLITE_DONE) return error.ExecFailed;
    try conn.exec("COMMIT");
    tx_open = false;
    return plan_id;
}

fn replaceEditablePlan(st: *CoreState, rec: *OrderRecord, aa: std.mem.Allocator, json_str: []const u8, new_plan: *planner.Plan) DaResult {
    const outcome = if (rec.outcome) |*value| value else return err(.invalid_state, "editable plan has no executable outcome");
    const plan_id = outcome.plan_id orelse return err(.invalid_state, "editable plan has no persisted plan id");
    if (new_plan.tasks.len == 0) return err(.invalid_arg, "edited plan must contain at least one task");
    const new_assignments = allocUnassignedAssignments(aa, new_plan.tasks) catch |e| return err(.oom, @errorName(e));
    const new_json = aa.dupe(u8, json_str) catch {
        for (new_assignments) |assignment| assignment.deinit(aa);
        aa.free(new_assignments);
        return err(.oom, "edited plan JSON OOM");
    };

    const new_plan_id = persistEditedPlan(st.db_conn, aa, rec.db_id orelse rec.id, plan_id, new_plan) catch |e| {
        for (new_assignments) |assignment| assignment.deinit(aa);
        aa.free(new_assignments);
        aa.free(new_json);
        setLastError(@errorName(e));
        return if (e == error.StalePlan)
            err(.invalid_state, "edited plan is stale; reload the latest revision")
        else
            err(.internal, "edited plan persistence failed");
    };

    outcome.plan.deinit();
    for (outcome.assignments) |assignment| assignment.deinit(aa);
    aa.free(outcome.assignments);
    if (rec.plan_json) |old| aa.free(old);
    outcome.plan = new_plan.*;
    outcome.plan_id = new_plan_id;
    outcome.assignments = new_assignments;
    rec.plan_json = new_json;
    return ok();
}

/// Confirma un plan (posiblemente editado por la GUI) y lo despacha.
/// `plan_json` sigue el esquema de `da_plan_get_json`: objeto con
/// `understanding` y `tasks[]`. Las clarificaciones pendientes deben resolverse
/// antes vía `da_order_answer`.
pub export fn da_order_confirm_json(handle: ?*anyopaque, order: ?*anyopaque, plan_json: [*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_order_confirm_json: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order) orelse return @intFromEnum(err(.invalid_arg, "da_order_confirm_json: null order handle"));
    const aa = st.arena.child_allocator;

    const rec = findOrder(st, order_id) orelse return @intFromEnum(err(.not_found, "da_order_confirm_json: order not found"));
    if (rec.status == .clarifying) return @intFromEnum(err(.invalid_state, "da_order_confirm_json: order has pending clarifications"));
    if (rec.status != .planned) return @intFromEnum(err(.invalid_state, "da_order_confirm_json: order must be in planned state"));

    const json_str = std.mem.span(plan_json);
    if (json_str.len == 0) return @intFromEnum(err(.invalid_arg, "da_order_confirm_json: empty plan json"));

    var new_plan = planFromJson(aa, json_str) catch |e| {
        setLastError(@errorName(e));
        return @intFromEnum(err(.invalid_arg, "da_order_confirm_json: invalid plan json"));
    };

    if (rec.outcome == null) {
        new_plan.deinit();
        return @intFromEnum(err(.invalid_state, "da_order_confirm_json: no outcome to dispatch"));
    }
    const replace_result = replaceEditablePlan(st, rec, aa, json_str, &new_plan);
    if (replace_result != .ok) {
        new_plan.deinit();
        return @intFromEnum(replace_result);
    }

    // Síncrono: sin hilo de dispatch separado, st.db_conn es seguro aquí.
    return @intFromEnum(dispatchApprovedOrder(st, rec, st.db_conn, false));
}

/// Guarda el plan JSON editado sin despachar. La GUI usa esto antes de
/// da_order_dispatch_async para evitar el bloqueo síncrono de da_order_confirm_json.
pub export fn da_order_plan_set_json(handle: ?*anyopaque, order: ?*anyopaque, plan_json: [*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_order_plan_set_json: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order) orelse return @intFromEnum(err(.invalid_arg, "da_order_plan_set_json: null order handle"));
    const aa = st.arena.child_allocator;

    const rec = findOrder(st, order_id) orelse return @intFromEnum(err(.not_found, "da_order_plan_set_json: order not found"));
    if (rec.status == .clarifying) return @intFromEnum(err(.invalid_state, "da_order_plan_set_json: order has pending clarifications"));
    if (rec.status != .planned) return @intFromEnum(err(.invalid_state, "da_order_plan_set_json: order must be in planned state"));

    const json_str = std.mem.span(plan_json);
    if (json_str.len == 0) return @intFromEnum(err(.invalid_arg, "da_order_plan_set_json: empty plan json"));

    var new_plan = planFromJson(aa, json_str) catch |e| {
        setLastError(@errorName(e));
        return @intFromEnum(err(.invalid_arg, "da_order_plan_set_json: invalid plan json"));
    };

    if (rec.outcome == null) {
        new_plan.deinit();
        return @intFromEnum(err(.invalid_state, "da_order_plan_set_json: no outcome to set"));
    }
    const replace_result = replaceEditablePlan(st, rec, aa, json_str, &new_plan);
    if (replace_result != .ok) new_plan.deinit();
    return @intFromEnum(replace_result);
}

/// Despacha una orden ya planeada en un hilo en segundo plano (F7-ASYNC).
/// Retorna inmediatamente; el progreso se consulta con da_order_dispatch_poll
/// y da_order_status. No bloquea el hilo de UI.
pub export fn da_order_dispatch_async(handle: ?*anyopaque, order: ?*anyopaque) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_order_dispatch_async: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order) orelse return @intFromEnum(err(.invalid_arg, "da_order_dispatch_async: null order handle"));

    const rec = findOrder(st, order_id) orelse return @intFromEnum(err(.not_found, "da_order_dispatch_async: order not found"));
    if (rec.status != .planned) return @intFromEnum(err(.invalid_state, "da_order_dispatch_async: order must be in planned state"));

    // C3-REGISTRY: `:memory:` sigue serializado (memory_dispatch_active dentro
    // del registro rechaza una 2ª orden CUALQUIERA mientras una esté en vuelo);
    // archivos distintos permiten órdenes distintas concurrentes — begin() solo
    // rechaza un redespacho de la MISMA order_id todavía en vuelo.
    const is_memory = std.mem.eql(u8, st.runtime_path, ":memory:");
    const task_count = if (rec.outcome) |outcome| outcome.plan.tasks.len else 1;
    const timeout_ms = dispatchTimeoutForOrder(st.db_conn, st.arena.child_allocator, rec.db_id orelse rec.id, task_count);
    st.dispatch_registry.beginWithTimeout(order_id, is_memory, GetTickCount64(), timeout_ms) catch |e| switch (e) {
        error.DuplicateOrder => return @intFromEnum(err(.invalid_state, "da_order_dispatch_async: dispatch already in progress for this order")),
        error.MemoryBusy => return @intFromEnum(err(.invalid_state, "da_order_dispatch_async: :memory: runtime allows only one dispatch in flight")),
        error.Closing => return @intFromEnum(err(.invalid_state, "da_order_dispatch_async: core is shutting down")),
        error.OutOfMemory => return @intFromEnum(err(.oom, "da_order_dispatch_async: OOM")),
    };

    // Page allocator: un TimedCallCtx HTTP puede sobrevivir al CoreState tras
    // timeout; un token dentro del Arena quedaría colgante al destruir el Core.
    const token = live_worker.CancellationToken.create(std.heap.page_allocator) catch {
        st.dispatch_registry.abortNeverStarted(order_id);
        return @intFromEnum(err(.oom, "da_order_dispatch_async: OOM token"));
    };
    defer token.release();

    if (!st.dispatch_registry.attachCancellationToken(order_id, token)) {
        st.dispatch_registry.abortNeverStarted(order_id);
        return @intFromEnum(err(.internal, "da_order_dispatch_async: failed to attach cancellation token"));
    }

    // El hilo recibe el order_id (no el puntero a rec, que puede moverse al realloc de orders).
    const ctx = st.arena.child_allocator.create(DispatchContext) catch {
        st.dispatch_registry.abortNeverStarted(order_id);
        return @intFromEnum(err(.oom, "da_order_dispatch_async: OOM"));
    };
    // MULTISESSION-P0 (2026-07-12): copia profunda PROPIA de runtime_path — no un
    // slice prestado de CoreState. st.runtime_path ya sobrevive mientras dure
    // CoreState (deinit hace join() del hilo antes de liberar nada), pero el
    // contexto no debe depender de esa garantía transitivamente: se duplica de
    // nuevo aquí para que el hilo sea autónomo incluso si esa invariante cambiara.
    const runtime_path_owned = st.arena.child_allocator.dupeZ(u8, st.runtime_path) catch {
        st.arena.child_allocator.destroy(ctx);
        st.dispatch_registry.abortNeverStarted(order_id);
        return @intFromEnum(err(.oom, "da_order_dispatch_async: OOM copying runtime path"));
    };
    ctx.* = .{ .st = st, .order_id = order_id, .runtime_path_owned = runtime_path_owned, .is_resume = false };
    const thread = std.Thread.spawn(.{}, dispatchThreadFn, .{ctx}) catch {
        st.arena.child_allocator.free(runtime_path_owned);
        st.arena.child_allocator.destroy(ctx);
        st.dispatch_registry.abortNeverStarted(order_id);
        return @intFromEnum(err(.internal, "da_order_dispatch_async: failed to spawn thread"));
    };
    st.dispatch_registry.setThread(order_id, thread);
    return @intFromEnum(ok());
}

/// CHECKPOINT-T2: reanuda una orden marcada 'interrupted' por la
/// reconciliación de arranque. Continúa desde la primera tarea no completada
/// según el checkpoint persistido (tabla tasks): las 'completed' no vuelven a
/// correr; una tarea que quedó 'running' se reporta como interrumpida y se
/// re-ejecuta ENTERA — nunca se finge continuidad interna.
///
/// Mismo contrato async que da_order_dispatch_async: retorna al instante y el
/// progreso se consulta con da_order_dispatch_poll / da_order_status /
/// da_order_events_json. Solo el usuario puede pedirla — el motor jamás
/// re-lanza una orden interrumpida por su cuenta (RESUME-INTERRUPTED).
pub export fn da_order_resume_async(handle: ?*anyopaque, order: ?*anyopaque) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_order_resume_async: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order) orelse return @intFromEnum(err(.invalid_arg, "da_order_resume_async: null order handle"));

    const rec = findOrder(st, order_id) orelse return @intFromEnum(err(.not_found, "da_order_resume_async: order not found"));
    // AUDIT-UNAVAILABLE-P0: el reintento manual de auditoría usa este mismo
    // camino. Una orden 'audit_unavailable' re-ejecuta SOLO las tareas de
    // auditoría que quedaron sin veredicto (las 'completed' se restauran desde
    // el checkpoint, las 'audit_unavailable' no entran ni en restored ni en
    // interrupted → corren de nuevo con un proveedor vivo).
    if (rec.status != .interrupted and rec.status != .audit_unavailable)
        return @intFromEnum(err(.invalid_state, "da_order_resume_async: order must be in interrupted or audit_unavailable state"));

    // Tras un reinicio la orden interrumpida no tiene outcome en memoria (solo
    // las .planned se rehidratan en loadOrdersFromDb): se reconstruye desde el
    // plan APROBADO persistido. Sin plan rehidratable no hay nada que reanudar
    // — el usuario tendría que re-enviar la orden.
    const aa = st.arena.child_allocator;
    // FASE0-B2: una vuelta que delegó no tiene tareas propias que reanudar.
    // Su «Reintentar auditoría» reaudita las hijas que siguen sin auditar; no
    // relanza la vuelta ni repite el trabajo de ninguna (retryDelegatedAudits).
    var delegation_retry: ?*DelegateRetry = null;
    if (rec.status == .audit_unavailable and isDelegationMother(st.db_conn, rec.db_id orelse rec.id)) {
        const retry = prepareDelegateRetry(st, rec.db_id orelse rec.id) catch
            return @intFromEnum(err(.internal, "da_order_resume_async: no se pudieron leer las subtareas sin auditar de esta conversación"));
        if (retry.children.len == 0) {
            retry.destroy(aa);
            return @intFromEnum(err(.invalid_state, "da_order_resume_async: esta conversación no tiene subtareas sin auditar que reintentar"));
        }
        delegation_retry = retry;
    } else if (rec.outcome == null) {
        rec.outcome = loadPersistedPlannedOutcome(st, aa, order_id, 1) catch null;
        if (rec.outcome == null) {
            return @intFromEnum(err(.invalid_state, "da_order_resume_async: interrupted order has no resumable persisted plan"));
        }
    }
    // El hilo de despacho se queda con `delegation_retry`; hasta entonces,
    // cualquier salida por error lo libera aquí.
    var retry_handed_off = false;
    defer if (!retry_handed_off) if (delegation_retry) |r| r.destroy(aa);

    const is_memory = std.mem.eql(u8, st.runtime_path, ":memory:");
    const task_count = if (delegation_retry) |r| r.children.len * 2 else if (rec.outcome) |outcome| outcome.plan.tasks.len else 1;
    const timeout_ms = dispatchTimeoutForOrder(st.db_conn, st.arena.child_allocator, rec.db_id orelse rec.id, task_count);
    st.dispatch_registry.beginWithTimeout(order_id, is_memory, GetTickCount64(), timeout_ms) catch |e| switch (e) {
        error.DuplicateOrder => return @intFromEnum(err(.invalid_state, "da_order_resume_async: dispatch already in progress for this order")),
        error.MemoryBusy => return @intFromEnum(err(.invalid_state, "da_order_resume_async: :memory: runtime allows only one dispatch in flight")),
        error.Closing => return @intFromEnum(err(.invalid_state, "da_order_resume_async: core is shutting down")),
        error.OutOfMemory => return @intFromEnum(err(.oom, "da_order_resume_async: OOM")),
    };

    const token = live_worker.CancellationToken.create(std.heap.page_allocator) catch {
        st.dispatch_registry.abortNeverStarted(order_id);
        return @intFromEnum(err(.oom, "da_order_resume_async: OOM token"));
    };
    defer token.release();

    if (!st.dispatch_registry.attachCancellationToken(order_id, token)) {
        st.dispatch_registry.abortNeverStarted(order_id);
        return @intFromEnum(err(.internal, "da_order_resume_async: failed to attach cancellation token"));
    }

    const ctx = st.arena.child_allocator.create(DispatchContext) catch {
        st.dispatch_registry.abortNeverStarted(order_id);
        return @intFromEnum(err(.oom, "da_order_resume_async: OOM"));
    };
    const runtime_path_owned = st.arena.child_allocator.dupeZ(u8, st.runtime_path) catch {
        st.arena.child_allocator.destroy(ctx);
        st.dispatch_registry.abortNeverStarted(order_id);
        return @intFromEnum(err(.oom, "da_order_resume_async: OOM copying runtime path"));
    };
    ctx.* = .{ .st = st, .order_id = order_id, .runtime_path_owned = runtime_path_owned, .is_resume = true, .delegation_retry = delegation_retry };
    const thread = std.Thread.spawn(.{}, dispatchThreadFn, .{ctx}) catch {
        st.arena.child_allocator.free(runtime_path_owned);
        st.arena.child_allocator.destroy(ctx);
        st.dispatch_registry.abortNeverStarted(order_id);
        return @intFromEnum(err(.internal, "da_order_resume_async: failed to spawn thread"));
    };
    retry_handed_off = true;
    st.dispatch_registry.setThread(order_id, thread);
    return @intFromEnum(ok());
}

/// SEMANTIC-GATE-T3: fija el observable declarado de la orden — un array JSON
/// de aserciones (ver semantic_gate.zig) que el gate semántico comprobará tras
/// el gate de ejecución. El 'done' exige que lo declarado se cumpla; si no, la
/// orden termina 'failed' con cause=semantic_gate_failed y la diferencia
/// concreta. Modificable mientras la orden no haya terminado ni esté en vuelo;
/// un JSON vacío ("[]") equivale a borrar la declaración (persiste NULL).
pub export fn da_order_set_expected(
    handle: ?*anyopaque,
    order: ?*anyopaque,
    expected_json: [*:0]const u8,
) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_order_set_expected: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order) orelse return @intFromEnum(err(.invalid_arg, "da_order_set_expected: null order handle"));
    const rec = findOrder(st, order_id) orelse return @intFromEnum(err(.not_found, "da_order_set_expected: order not found"));
    switch (rec.status) {
        .done, .failed, .cancelled => return @intFromEnum(err(.invalid_state, "da_order_set_expected: order already terminated")),
        .running => return @intFromEnum(err(.invalid_state, "da_order_set_expected: order is executing; declare before dispatch")),
        else => {},
    }

    const aa = st.arena.child_allocator;
    const json_str = std.mem.span(expected_json);
    // Validación REAL: el JSON debe parsear a un array de aserciones conocidas.
    // Una declaración inválida no se guarda — el gate no puede comprobar lo que
    // no entiende y un campo inválido silencioso sería un falso sentido de
    // seguridad.
    const assertions = semantic_gate.parseAssertions(aa, json_str) catch {
        return @intFromEnum(err(.invalid_arg, "da_order_set_expected: expected_json must be an array of assertions ({kind,path,needle,task_id})"));
    };
    defer {
        for (assertions) |as| as.deinit(aa);
        aa.free(assertions);
    }

    const stmt = st.db_conn.prepare("UPDATE orders SET expected_result = ? WHERE id = ?") catch {
        return @intFromEnum(err(.internal, "da_order_set_expected: prepare failed"));
    };
    defer st.db_conn.finalize(stmt);
    // [] = declaración vacía honesta -> NULL (no un array vacío que simularía
    // "algo declarado" sin comprobar nada).
    if (assertions.len == 0) {
        _ = db.c.sqlite3_bind_null(stmt, 1);
    } else {
        db.bindText(stmt, 1, json_str) catch return @intFromEnum(err(.internal, "da_order_set_expected: bind failed"));
    }
    // La fila real de la orden es db_id (outcome.order_id tras clarificación);
    // escribir bajo order_id (handle) dejaría la declaración en una fila que el
    // gate nunca lee.
    db.bindInt(stmt, 2, rec.db_id orelse order_id) catch return @intFromEnum(err(.internal, "da_order_set_expected: bind failed"));
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE) {
        return @intFromEnum(err(.internal, "da_order_set_expected: update failed"));
    }
    return @intFromEnum(ok());
}

/// SEMANTIC-GATE-T3: devuelve el observable declarado de la orden (JSON) o una
/// cadena vacía si no hay ninguno. El llamador libera con da_string_free.
pub export fn da_order_expected_json(
    handle: ?*anyopaque,
    order: ?*anyopaque,
    out_json: *?[*:0]u8,
) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_order_expected_json: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order) orelse return @intFromEnum(err(.invalid_arg, "da_order_expected_json: null order handle"));
    const rec = findOrder(st, order_id) orelse return @intFromEnum(err(.not_found, "da_order_expected_json: order not found"));

    var text: []const u8 = "";
    defer if (text.len > 0) st.arena.child_allocator.free(text);
    if (st.db_conn.prepare("SELECT expected_result FROM orders WHERE id = ?")) |stmt| {
        defer st.db_conn.finalize(stmt);
        db.bindInt(stmt, 1, rec.db_id orelse order_id) catch {};
        if (db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW) {
            const ptr = db.c.sqlite3_column_text(stmt, 0);
            const len = db.c.sqlite3_column_bytes(stmt, 0);
            if (ptr != null and len > 0) text = st.arena.child_allocator.dupe(u8, ptr[0..@intCast(len)]) catch "";
        }
    } else |_| {}

    // ownedCStr: el borde exige c_allocator — es el allocator con el que
    // da_string_free libera (otro allocator = corrupción de heap).
    const duped = ownedCStr(text) orelse {
        return @intFromEnum(err(.oom, "da_order_expected_json: OOM"));
    };
    out_json.* = duped;
    return @intFromEnum(ok());
}

pub export fn da_order_cancel(
    handle: ?*anyopaque,
    order: ?*anyopaque,
) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_order_cancel: null core handle"));
    if (order == null) return @intFromEnum(err(.invalid_arg, "da_order_cancel: null order handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order) orelse return @intFromEnum(err(.invalid_arg, "da_order_cancel: invalid order handle"));

    const rec = findOrder(st, order_id) orelse return @intFromEnum(err(.not_found, "da_order_cancel: order not found"));

    if (rec.status == .planned or rec.status == .clarifying) {
        // cancela el plan cuando aún no hay despacho; si ya hay un
        // despacho en vuelo, manda la cancelación del token (comportamiento de
        // main) para no dejarlo corriendo tras responder ok.
        const active = st.dispatch_registry.snapshot(order_id);
        // Si la orden ya tuvo un despacho terminado, su status .planned puede
        // ser el resto de una salida temprana sin estado terminal persistido.
        // La marca sobrevive a joinIfFinished: nunca se re-cancela como plan
        // (la segunda llamada sigue siendo invalid_state, como en main).
        const ever_dispatched = active.found or st.dispatch_registry.hasFinished(order_id);
        if (!ever_dispatched) {
            st.plan_mutex.lock();
            const planning = !st.plan_done and st.plan_order_id == order_id;
            st.plan_mutex.unlock();
            if (planning) return da_plan_cancel(handle, order);
            const committed = st.db_conn.tryCommitTerminal(rec.db_id orelse rec.id, "cancelled", "order_cancelled", "usuario", "{\"cause\":\"plan_cancelled\"}", health.nowMillis(st.db_conn)) catch
                return @intFromEnum(err(.internal, "da_order_cancel: plan cancellation persistence failed"));
            if (!committed) return @intFromEnum(err(.invalid_state, "da_order_cancel: order already terminal"));
            rec.status = .cancelled;
            return @intFromEnum(ok());
        }
    }

    const snap = st.dispatch_registry.snapshot(order_id);
    if (!snap.found or snap.done) {
        // una orden en awaiting_approval no tiene dispatch activo, pero
        // sí es cancelable — si no, una aprobación denegada u olvidada la
        // dejaba wedged para siempre sin salida por la API pública.
        if (rec.status == .awaiting_approval) {
            rec.status = .cancelled;
            _ = st.db_conn.tryCommitTerminal(rec.db_id orelse rec.id, "cancelled", "order_cancelled", "usuario", "\"orden cancelada en awaiting_approval\"", health.nowMillis(st.db_conn)) catch false;
            // Sus aprobaciones pendientes dejan de ser accionables: quedan
            // resueltas-denegadas para no seguir vivas en la UI.
            st.output_mutex.lock();
            for (st.approvals.items) |*a| {
                if (!a.resolved and a.order_id == order_id) {
                    a.approved = false;
                    a.resolved = true;
                    updateApprovalResolved(st, a.id, false) catch {};
                }
            }
            st.output_mutex.unlock();
            return @intFromEnum(ok());
        }
        return @intFromEnum(err(.invalid_state, "da_order_cancel: no active dispatch found for this order"));
    }

    if (!st.dispatch_registry.requestCancel(order_id)) {
        return @intFromEnum(err(.invalid_state, "da_order_cancel: failed to request cancel"));
    }

    return @intFromEnum(ok());
}

/// PLAN-CANCEL: cancela la planificación EN CURSO (da_order_submit_async /
/// da_order_answer_async). da_order_cancel solo cubre el despacho; sin esto,
/// una orden en fase planning era incancelable hasta que el LLM respondiera.
///
/// `order` puede ser NULL → cancela la planificación actual sea cual sea.
/// Si se pasa una orden, debe ser la que está planificándose (plan_order_id).
/// La transición honesta a `cancelled` la hace el hilo de planificación al
/// despertar (o este mismo export si el hilo aún no arrancó): el resultado
/// tardío —incluido un plan del MockPlanner de respaldo— se descarta siempre.
pub export fn da_plan_cancel(
    handle: ?*anyopaque,
    order: ?*anyopaque,
) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_plan_cancel: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));

    const wanted: ?i64 = orderHandleToId(order);

    st.plan_mutex.lock();
    if (st.plan_done) {
        st.plan_mutex.unlock();
        return @intFromEnum(err(.invalid_state, "da_plan_cancel: no plan in progress"));
    }
    if (wanted) |oid| {
        if (oid != st.plan_order_id) {
            st.plan_mutex.unlock();
            return @intFromEnum(err(.not_found, "da_plan_cancel: that order is not the one being planned"));
        }
    }
    st.plan_cancel_requested = true;
    const token = st.plan_cancel_token;
    const victim = st.plan_order_id;
    st.plan_mutex.unlock();

    // El token aborta la E/S HTTP del planner (transporte la mira cada 100 ms).
    // Puede ser null en la ventana entre spawn del hilo y la 1ª llamada LLM —
    // el flag basta: el hilo lo comprueba al entrar y tras processOrder.
    if (token) |t| t.cancel();

    // Si el hilo ya marcó la orden por su cuenta el UPDATE es no-op
    // (tryCommitTerminal es condicional); si aún no llegó, esto la deja
    // cancelled por adelantado y el hilo respetará el flag sin reescribirla.
    markPlanCancelled(st, victim);
    return @intFromEnum(ok());
}

test "PLAN-CANCEL: da_plan_cancel valida contrato, flag y estado terminal" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);

    try std.testing.expectEqual(
        @as(c_int, @intFromEnum(DaResult.invalid_arg)),
        da_plan_cancel(null, null),
    );
    // Sin planificación en vuelo: invalid_state.
    try std.testing.expectEqual(
        @as(c_int, @intFromEnum(DaResult.invalid_state)),
        da_plan_cancel(handle, null),
    );

    const st: *CoreState = @ptrCast(@alignCast(handle));
    var order: ?*anyopaque = null;
    try std.testing.expectEqual(
        @as(c_int, 0),
        da_order_submit(handle, "crea un modulo de logging en C", "cancel-test", null, &order),
    );
    const order_id = orderHandleToId(order).?;

    // Simular una planificación en vuelo sobre ESA orden.
    st.plan_mutex.lock();
    st.plan_done = false;
    st.plan_order_id = order_id;
    st.plan_mutex.unlock();

    // Orden distinta a la que planifica → not_found.
    try std.testing.expectEqual(
        @as(c_int, @intFromEnum(DaResult.not_found)),
        da_plan_cancel(handle, orderIdToHandle(order_id + 100_000)),
    );

    try std.testing.expectEqual(@as(c_int, 0), da_plan_cancel(handle, order));
    st.plan_mutex.lock();
    const flagged = st.plan_cancel_requested;
    st.plan_mutex.unlock();
    try std.testing.expect(flagged);

    const rec = findOrder(st, order_id).?;
    try std.testing.expectEqual(superagent.OrderStatus.cancelled, rec.status);
}

test "C2-CANCEL: da_order_cancel valida contrato publico e idempotencia en vuelo" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);

    try std.testing.expectEqual(
        @as(c_int, @intFromEnum(DaResult.invalid_arg)),
        da_order_cancel(null, null),
    );

    var order: ?*anyopaque = null;
    try std.testing.expectEqual(
        @as(c_int, 0),
        da_order_submit(handle, "crea un modulo de logging en C", "cancel-test", null, &order),
    );
    const order_id = orderHandleToId(order).?;
    const st: *CoreState = @ptrCast(@alignCast(handle));

    try st.dispatch_registry.begin(order_id, true, 1);
    const token = try live_worker.CancellationToken.create(std.testing.allocator);
    defer token.release();
    try std.testing.expect(st.dispatch_registry.attachCancellationToken(order_id, token));

    try std.testing.expectEqual(@as(c_int, 0), da_order_cancel(handle, order));
    try std.testing.expect(token.isCancelled());
    // Repetir mientras sigue en vuelo es un no-op exitoso, no una segunda transición.
    try std.testing.expectEqual(@as(c_int, 0), da_order_cancel(handle, order));

    st.dispatch_registry.finish(order_id, false);
    try std.testing.expectEqual(
        @as(c_int, @intFromEnum(DaResult.invalid_state)),
        da_order_cancel(handle, order),
    );
    try std.testing.expectEqual(
        @as(c_int, @intFromEnum(DaResult.not_found)),
        da_order_cancel(handle, orderIdToHandle(order_id + 100_000)),
    );
}

test "C2-CANCEL P1: cancelar tras salida temprana del despacho no reescribe la orden y el plan pendiente sigue cancelandose" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);

    var order: ?*anyopaque = null;
    try std.testing.expectEqual(
        @as(c_int, 0),
        da_order_submit(handle, "crea un modulo de logging en C", "cancel-early-exit", null, &order),
    );
    const order_id = orderHandleToId(order).?;
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const rec = findOrder(st, order_id).?;

    // Despacho en vuelo: la primera cancelacion marca el token.
    try st.dispatch_registry.begin(order_id, true, 1);
    const token = try live_worker.CancellationToken.create(std.testing.allocator);
    defer token.release();
    try std.testing.expect(st.dispatch_registry.attachCancellationToken(order_id, token));
    try std.testing.expectEqual(@as(c_int, 0), da_order_cancel(handle, order));
    try std.testing.expect(token.isCancelled());

    // Salida temprana sin estado terminal persistido (p.ej. fallo al abrir la
    // conexion) y poll que retira la entrada terminada.
    st.dispatch_registry.finish(order_id, false);
    var done: c_int = 0;
    var succeeded: c_int = 1;
    try std.testing.expectEqual(@as(c_int, 0), da_order_dispatch_poll(handle, order, &done, &succeeded));
    try std.testing.expectEqual(@as(c_int, 1), done);
    try std.testing.expectEqual(@as(c_int, 0), succeeded);
    try std.testing.expect(!st.dispatch_registry.snapshot(order_id).found);

    // La segunda cancelacion no puede caer en la rama de plan ni confirmar
    // exito: la orden ya tuvo un despacho y su estado no se reescribe.
    try std.testing.expectEqual(
        @as(c_int, @intFromEnum(DaResult.invalid_state)),
        da_order_cancel(handle, order),
    );
    try std.testing.expectEqual(superagent.OrderStatus.planned, rec.status);

    // El modo plan de sigue vivo: una orden planificada que nunca
    // se despacho se cancela y persiste cancelled.
    var pending: ?*anyopaque = null;
    try std.testing.expectEqual(
        @as(c_int, 0),
        da_order_submit(handle, "crea otro modulo en C", "cancel-early-exit-plan", null, &pending),
    );
    try std.testing.expectEqual(@as(c_int, 0), da_order_cancel(handle, pending));
    var status: c_int = -1;
    try std.testing.expectEqual(@as(c_int, 0), da_order_status(handle, pending, &status));
    try std.testing.expectEqual(@as(c_int, @intFromEnum(DaOrderStatus.cancelled)), status);
}

test "E3.24: tormenta pública de cancelaciones — ráfagas repetidas sin estado corrupto" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);

    // Ráfaga sobre la NADA: 200 da_plan_cancel sin planificación en vuelo —
    // cada una debe ser invalid_state limpio, nunca un estado fantasma.
    for (0..200) |_| {
        try std.testing.expectEqual(
            @as(c_int, @intFromEnum(DaResult.invalid_state)),
            da_plan_cancel(handle, null),
        );
    }

    var order: ?*anyopaque = null;
    try std.testing.expectEqual(
        @as(c_int, 0),
        da_order_submit(handle, "crea un modulo de logging en C", "cancel-storm", null, &order),
    );
    const order_id = orderHandleToId(order).?;
    const st: *CoreState = @ptrCast(@alignCast(handle));

    try st.dispatch_registry.begin(order_id, true, 1);
    const token = try live_worker.CancellationToken.create(std.testing.allocator);
    defer token.release();
    try std.testing.expect(st.dispatch_registry.attachCancellationToken(order_id, token));

    // Ráfaga de 64 cancels sobre la MISMA orden en vuelo: la primera señaliza,
    // las 63 restantes son no-op exitoso — jamás una segunda transición.
    for (0..64) |_| {
        try std.testing.expectEqual(@as(c_int, 0), da_order_cancel(handle, order));
    }
    try std.testing.expect(token.isCancelled());

    // Ráfaga mixta: plan_cancel sin plan + order_cancel sobre la orden viva.
    for (0..32) |_| {
        try std.testing.expectEqual(
            @as(c_int, @intFromEnum(DaResult.invalid_state)),
            da_plan_cancel(handle, null),
        );
        try std.testing.expectEqual(@as(c_int, 0), da_order_cancel(handle, order));
    }

    // Cierre limpio: la orden termina y todo cancel posterior es invalid_state.
    st.dispatch_registry.finish(order_id, false);
    for (0..16) |_| {
        try std.testing.expectEqual(
            @as(c_int, @intFromEnum(DaResult.invalid_state)),
            da_order_cancel(handle, order),
        );
    }
}

const DispatchContext = struct {
    st: *CoreState,
    order_id: i64,
    /// MULTISESSION-P0: copia profunda propia (no prestada) de la ruta de
    /// runtime.db, liberada por dispatchThreadFn junto con el resto del contexto.
    runtime_path_owned: [:0]const u8,
    /// CHECKPOINT-T2: true solo cuando el hilo nació de da_order_resume_async —
    /// dispatchApprovedOrder lee entonces el checkpoint persistido.
    is_resume: bool,
    /// FASE0-B2: reintento de auditoría de una vuelta que delegó. El hilo de
    /// despacho es su propietario y lo libera al terminar.
    delegation_retry: ?*DelegateRetry = null,
};

/// C3-DESIGN-2026-07-12 (auditoría single-flight, incremento 2): tipo PURO que
/// modela lo que hoy son 6 campos escalares sueltos en CoreState
/// (dispatch_order_id/dispatch_thread/dispatch_done/dispatch_ok/
/// dispatch_timed_out/dispatch_start_ms) — el estado de UN despacho en curso.
///
/// DELIBERADAMENTE NO está cableado a CoreState/da_order_dispatch_async/
/// da_order_dispatch_poll/deinit todavía. La migración completa a un mapa
/// order_id→DispatchState (para reemplazar el single-flight GLOBAL por uno
/// POR-ORDEN) toca ~96 referencias a estos 6 campos en 9 sitios (da_core_init,
/// da_order_dispatch_async, dispatchThreadFn, da_order_dispatch_poll,
/// CoreState.deinit, y 2 bloques de test que MANIPULAN los campos directamente
/// para simular timeouts sin esperar 240s reales) — y cambia el CONTRATO
/// observable de da_order_dispatch_async: hoy rechaza CUALQUIER segundo
/// despacho mientras uno esté en vuelo (sin importar order_id); con un mapa,
/// dos ÓRDENES DISTINTAS podrían despacharse a la vez. Eso es exactamente lo
/// que C3 pide preparar, pero es un cambio de comportamiento consecuente, no
/// un refactor de almacenamiento — no es seguro hacerlo parcialmente en este
/// turno (ver informe final para el diseño exacto de la migración completa).
///
/// Este tipo + sus tests puros (sin CoreState/hilos/SQLite) son el primer paso
/// seguro: capturan la lógica hoy dispersa entre da_order_dispatch_async y
/// da_order_dispatch_poll (cuándo se considera "reportable como terminado",
/// cuándo expira el timeout) en un solo lugar verificable en aislamiento.
pub const DispatchState = struct {
    order_id: i64,
    thread: ?std.Thread = null,
    done: bool = true,
    ok: bool = false,
    timed_out: bool = false,
    start_ms: u64 = 0,

    /// Estado inicial al arrancar un despacho — espeja el bloque de asignación
    /// en da_order_dispatch_async (líneas dispatch_done=false/dispatch_ok=false/
    /// dispatch_order_id=order_id/dispatch_start_ms=now/dispatch_timed_out=false).
    pub fn begin(order_id: i64, start_ms: u64) DispatchState {
        return .{
            .order_id = order_id,
            .thread = null,
            .done = false,
            .ok = false,
            .timed_out = false,
            .start_ms = start_ms,
        };
    }

    /// Espeja la condición de da_order_dispatch_poll para out_done: terminó de
    /// verdad O se declaró timeout (aunque el hilo real siga corriendo).
    pub fn isReportableDone(self: DispatchState) bool {
        return self.done or self.timed_out;
    }

    /// Espeja out_ok de da_order_dispatch_poll: solo válido cuando reportable
    /// como terminado, y solo true si terminó de verdad con éxito (un timeout
    /// nunca es "ok", incluso si el hilo real termina exitosamente después).
    pub fn isReportableOk(self: DispatchState) bool {
        return self.done and self.ok;
    }

    /// Función PURA (no llama GetTickCount64, no muta estado) — espeja el
    /// cálculo `elapsed >= DISPATCH_TIMEOUT_MS` de da_order_dispatch_poll.
    /// `now_ms` se recibe como parámetro para que sea testeable sin reloj real.
    pub fn hasTimedOutAt(self: DispatchState, now_ms: u64, timeout_ms: u64) bool {
        if (self.done or self.timed_out) return false;
        return (now_ms -% self.start_ms) >= timeout_ms;
    }
};

test "MULTISESSION-P0 C3-DESIGN DispatchState.begin: estado inicial coincide con da_order_dispatch_async" {
    const s = DispatchState.begin(42, 1000);
    try std.testing.expectEqual(@as(i64, 42), s.order_id);
    try std.testing.expect(s.thread == null);
    try std.testing.expect(!s.done);
    try std.testing.expect(!s.ok);
    try std.testing.expect(!s.timed_out);
    try std.testing.expectEqual(@as(u64, 1000), s.start_ms);
}

test "MULTISESSION-P0 C3-DESIGN DispatchState.isReportableDone: ni terminado ni timeout -> no reportable" {
    const s = DispatchState.begin(1, 0);
    try std.testing.expect(!s.isReportableDone());
}

test "MULTISESSION-P0 C3-DESIGN DispatchState.isReportableDone: terminado real -> reportable" {
    var s = DispatchState.begin(1, 0);
    s.done = true;
    try std.testing.expect(s.isReportableDone());
}

test "MULTISESSION-P0 C3-DESIGN DispatchState.isReportableDone: timeout declarado sin terminar de verdad -> reportable" {
    var s = DispatchState.begin(1, 0);
    s.timed_out = true;
    try std.testing.expect(s.isReportableDone());
}

test "MULTISESSION-P0 C3-DESIGN DispatchState.isReportableOk: timeout nunca es ok, aunque ok quedara true por error" {
    var s = DispatchState.begin(1, 0);
    s.timed_out = true;
    s.ok = true; // no debería poder pasar en la práctica, pero la función no debe confiar en eso
    try std.testing.expect(!s.isReportableOk());
}

test "MULTISESSION-P0 C3-DESIGN DispatchState.isReportableOk: terminado real + ok=true -> ok" {
    var s = DispatchState.begin(1, 0);
    s.done = true;
    s.ok = true;
    try std.testing.expect(s.isReportableOk());
}

test "MULTISESSION-P0 C3-DESIGN DispatchState.isReportableOk: terminado real + ok=false -> no ok" {
    var s = DispatchState.begin(1, 0);
    s.done = true;
    try std.testing.expect(!s.isReportableOk());
}

test "MULTISESSION-P0 C3-DESIGN DispatchState.hasTimedOutAt: no expira antes del umbral" {
    const s = DispatchState.begin(1, 1000);
    try std.testing.expect(!s.hasTimedOutAt(1000 + 239_000, 240_000));
}

test "MULTISESSION-P0 C3-DESIGN DispatchState.hasTimedOutAt: expira justo en el umbral" {
    const s = DispatchState.begin(1, 1000);
    try std.testing.expect(s.hasTimedOutAt(1000 + 240_000, 240_000));
}

test "MULTISESSION-P0 C3-DESIGN DispatchState.hasTimedOutAt: nunca reporta timeout si ya terminó de verdad" {
    var s = DispatchState.begin(1, 1000);
    s.done = true;
    try std.testing.expect(!s.hasTimedOutAt(1000 + 999_000, 240_000));
}

test "MULTISESSION-P0 C3-DESIGN DispatchState.hasTimedOutAt: no re-declara timeout si ya estaba declarado" {
    var s = DispatchState.begin(1, 1000);
    s.timed_out = true;
    // da_order_dispatch_poll depende de esto para no repetir el evento
    // dispatch_failed / persistOrderTasksStatus en cada poll subsiguiente.
    try std.testing.expect(!s.hasTimedOutAt(1000 + 999_000, 240_000));
}

fn dispatchThreadFn(ctx: *DispatchContext) void {
    const st = ctx.st;
    const order_id = ctx.order_id;
    const aa = st.arena.child_allocator;
    // MULTISESSION-P0: orden de defer importa — LIFO significa que el ÚLTIMO
    // `defer` escrito corre PRIMERO. destroy(ctx) debe ejecutarse AL FINAL (así
    // que se escribe PRIMERO aquí); si corriera antes, el free() de abajo leería
    // ctx.runtime_path_owned desde memoria ya liberada (use-after-free/segfault
    // real, detectado por los tests MULTISESSION-P0 D/F/G/I).
    defer aa.destroy(ctx);
    defer aa.free(ctx.runtime_path_owned);
    defer if (ctx.delegation_retry) |r| r.destroy(aa);

    // Recuperar el registro de orden (puede haberse movido tras realloc, así que buscamos de nuevo)
    const rec = findOrder(st, order_id);
    if (rec == null) {
        st.dispatch_registry.finish(order_id, false);
        return;
    }

    // MULTISESSION-P0 (2026-07-12): este hilo NUNCA comparte el sqlite3* del hilo
    // principal (st.db_conn). Abre su PROPIA Connection al mismo archivo DENTRO
    // del hilo (la Connection no cruza el spawn — solo la ruta, ya copiada) y la
    // cierra ANTES de liberar el contexto (los `defer` de abajo, registrados
    // después de los de arriba, corren primero por ser LIFO).
    //
    // ":memory:" es la única excepción explícita: cada open(":memory:") crea una
    // base de datos vacía y AISLADA — abrir "otra" aquí produciría una réplica
    // desconectada que nunca ve lo que escribe/lee el hilo principal (silenciosamente
    // incorrecto, peor que compartir). Para ese caso (solo tests/hermetic — runtime.db
    // en producción siempre es un archivo) se mantiene la ejecución SERIALIZADA:
    // se sigue usando st.db_conn a propósito, documentado aquí explícitamente.
    //
    // C3-REGISTRY (2026-07-12): la exclusividad de `:memory:` ya NO depende de un
    // assert dentro de este hilo — da_order_dispatch_async la garantiza ANTES de
    // spawnear, vía DispatchRegistry.begin() (memory_dispatch_active, rechazo real
    // en TODOS los modos de build, no solo Debug/ReleaseSafe). Para cuando este
    // hilo arranca, la exclusividad ya está garantizada; no hace falta re-verificar.
    const is_memory = std.mem.eql(u8, ctx.runtime_path_owned, ":memory:");
    var owned_conn: ?db.Connection = null;
    defer if (owned_conn) |*c| c.close();

    const thread_conn: db.Connection = if (is_memory) st.db_conn else blk: {
        var conn = db.Connection.open(aa, ctx.runtime_path_owned) catch {
            // I: error al abrir no deja el dispatch colgado — se reporta fallido
            // sin tocar ningún handle compartido (nunca se llegó a abrir uno).
            // Solo afecta la entrada de ESTA orden en el registro; otras órdenes
            // en vuelo (con su propia Connection) no se ven afectadas.
            st.dispatch_registry.finish(order_id, false);
            return;
        };
        // Defensivo/idempotente: el archivo YA está migrado (da_core_init lo hizo);
        // esta llamada no debería aplicar nada nuevo, solo confirma el esquema.
        var migrator = db.Migrator.init(aa);
        migrator.migrate(conn, &db.runtime_schema) catch {
            conn.close();
            st.dispatch_registry.finish(order_id, false);
            return;
        };
        owned_conn = conn;
        break :blk conn;
    };

    // FIX-DISPATCH-P0-SAFE: ejecutar dispatchApprovedOrder directamente en este hilo.
    // No se usa un sub-hilo watchdog con detach — eso causaba use-after-free porque
    // el sub-hilo conservaba punteros a WatchdogCtx (stack-local), CoreState y
    // OrderRecord después de que dispatchThreadFn retornara.
    //
    // Si dispatchApprovedOrder cuelga (HTTP/SSE bloqueante sin timeout a nivel socket),
    // el registro sigue marcando esta orden como no terminada y dispatch_poll detecta
    // el timeout transcurrido (DISPATCH_TIMEOUT_MS) — solo para ESTA orden, sin
    // afectar el poll de otras órdenes en vuelo. El hilo sigue corriendo pero NO es
    // detached: deinit (o un redespacho de la misma orden) hace join(), esperando a
    // que termine. Esto es seguro porque el hilo solo accede a CoreState, que sigue
    // vivo mientras deinit no haya retornado.
    //
    // Limitación conocida: si el hilo truly cuelga para siempre, deinit bloquea
    // (join de esa entrada específica). Esto es preferible a un use-after-free
    // silencioso o a un detach que dejaría punteros colgando (ver C3-DECISIONS).
    const result = if (ctx.delegation_retry) |retry|
        retryDelegatedAudits(st, rec.?, thread_conn, retry)
    else
        dispatchApprovedOrder(st, rec.?, thread_conn, ctx.is_resume);

    // GOBERNANZA-HIBRIDO-LEDGER: las llamadas auxiliares no-tarea del despacho
    // (p.ej. el selector de herramientas, worker_id='') también consumen pago —
    // barrida final deduplicada contra lo ya emitido tras la planificación.
    emitAuxEscalations(st, thread_conn, aa, order_id);

    st.dispatch_registry.finish(order_id, result == .ok);
}

/// Consulta si un despacho async iniciado por da_order_dispatch_async ha terminado.
/// out_done: 1 si terminó, 0 si sigue en curso.
/// out_ok: 1 si terminó con éxito, 0 si falló (solo válido cuando out_done=1).
pub export fn da_order_dispatch_poll(handle: ?*anyopaque, order: ?*anyopaque, out_done: *c_int, out_ok: *c_int) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_order_dispatch_poll: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order) orelse return @intFromEnum(err(.invalid_arg, "da_order_dispatch_poll: null order handle"));

    // C3-REGISTRY (2026-07-12): FIX-ENGINE-9 — drenar cola de audit pendiente.
    // El comentario original (FIX-SEGFAULT-P0) gateaba esto tras los flags
    // GLOBALES de dispatch porque, ANTES de la migración a Connection propia
    // por hilo (MULTISESSION-P0), los hilos fanout escribían vía st.db_conn —
    // ese riesgo ya no existe: st.db_conn (conexión principal) NUNCA es la
    // conexión de ningún hilo de despacho (cada orden abre/usa la suya propia,
    // ver DispatchRegistry/dispatchThreadFn). flushAuditQueue solo toca
    // st.db_conn/st.ledger bajo sus propios mutex — seguro sin condicionarlo a
    // ningún flag de dispatch, y sin importar cuántas órdenes estén en vuelo.
    flushAuditQueue(st);

    const snap = st.dispatch_registry.snapshot(order_id);
    if (!snap.found) {
        out_done.* = 1;
        out_ok.* = 0;
        return @intFromEnum(ok());
    }

    // FIX-DISPATCH-P0-SAFE: detección de timeout desde el lado del poll, POR
    // ORDEN — el timeout de la orden A nunca marca ni consulta el estado de B.
    // Esto reemplaza el watchdog inseguro basado en sub-hilo + detach.
    // El hilo sigue corriendo (no se puede cancelar HTTP/SSE) pero no es
    // detached: deinit (o un redespacho de la misma orden) hace join().
    if (!snap.done and !snap.timed_out) {
        const elapsed = GetTickCount64() - snap.start_ms;
        if (elapsed >= snap.timeout_ms and st.dispatch_registry.markTimedOut(order_id)) {
            // El timeout del watchdog deja de ser solo visual: solicita cancelación
            // cooperativa para que LiveLlm abandone inmediatamente la espera del
            // socket y Superagent pueda comprometer order_cancelled. No escribe el
            // estado terminal aquí; la máquina transaccional conserva esa autoridad.
            _ = st.dispatch_registry.requestCancel(order_id);
            // TERMINAL-STATE-DESIGN-2026-07-12 (P0 cierre): el watchdog de timeout
            // resuelve su PROPIO contrato (out_done/out_ok más abajo) sin necesidad
            // de tocar orders.status — dejarlo intacto evita pisar un terminal real
            // que el hilo de despacho pueda haber comprometido justo antes de
            // expirar el timeout (el hilo sigue corriendo, no se cancela). Las
            // tareas huérfanas de ESTA orden sí se marcan.
            persistOrderTasksStatus(st.db_conn, order_id, "failed");
            noteDispatchFailureAndMaybeAutoVerify(st, order_id, st.db_conn);
            // Emitir evento de timeout visible en order_events (vía st.db_conn,
            // la conexión del hilo que está haciendo el poll — no la del hilo de
            // despacho de esta orden, que sigue corriendo con la suya propia).
            const aa = st.arena.child_allocator;
            var sup = superagent.Superagent.init(aa, st.db_conn, null, superagent.NoopMemory.backend(), 0);
            sup.rules_catalog = st.catalog.db;
            sup.setEventConn(st.db_conn, order_id);
            var out: std.Io.Writer.Allocating = .init(aa);
            defer out.deinit();
            var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
            js.beginObject() catch {};
            js.objectField("error") catch {};
            js.write("dispatch_timeout") catch {};
            js.objectField("timeout_ms") catch {};
            js.write(snap.timeout_ms) catch {};
            js.endObject() catch {};
            sup.recordEvent("dispatch_failed", out.written());
            // SUPPRESS-IN-TESTS: el test A6 simula un timeout deliberadamente;
            // este print va a stderr y el test runner de Zig 0.16 lo captura como
            // result_stderr del step, mostrando un "failed command" espurio aunque
            // el step pase (538/538). Útil en producción, ruido puro en tests.
            if (!builtin.is_test) {
                std.debug.print("[dispatch_poll] Timeout ({d}ms) — order {d} marked failed\n", .{ snap.timeout_ms, order_id });
            }
        }
    }

    // Releer tras el posible markTimedOut de arriba.
    const final_snap = st.dispatch_registry.snapshot(order_id);
    out_done.* = if (final_snap.found and (final_snap.done or final_snap.timed_out)) 1 else 0;
    out_ok.* = if (final_snap.found and final_snap.done and final_snap.ok) 1 else 0;

    // Phase 3: join del hilo terminado para evitar leak de handle — solo el de
    // ESTA orden, sin tocar el thread handle de ninguna otra.
    st.dispatch_registry.joinIfFinished(order_id);
    return @intFromEnum(ok());
}

fn allocUnassignedAssignments(a: std.mem.Allocator, tasks: []const planner.PlannedTask) ![]superagent.ModelAssignment {
    var list = std.ArrayList(superagent.ModelAssignment).empty;
    errdefer {
        for (list.items) |asg| asg.deinit(a);
        list.deinit(a);
    }
    for (tasks) |pt| {
        const reason = try a.dupe(u8, "plan editado sin re-router");
        errdefer a.free(reason);
        const provider = try a.dupe(u8, "none");
        errdefer a.free(provider);
        const model = try a.dupe(u8, "none");
        errdefer a.free(model);
        try list.append(a, .{
            .task_id = pt.id,
            .assigned = false,
            .provider_name = provider,
            .model_name = model,
            .is_free = false,
            .reason = reason,
        });
    }
    return list.toOwnedSlice(a);
}

pub export fn da_order_status(handle: ?*anyopaque, order: ?*anyopaque, out_status: *c_int) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_order_status: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order) orelse return @intFromEnum(err(.invalid_arg, "da_order_status: null order handle"));

    const rec = findOrder(st, order_id) orelse return @intFromEnum(err(.not_found, "da_order_status: order not found"));
    const da_st: DaOrderStatus = orderStatusToDa(rec.status);
    out_status.* = @intCast(@intFromEnum(da_st));
    return @intFromEnum(ok());
}

/// UX-13: lista todas las órdenes/sesiones como JSON.
/// Mezcla sesiones en memoria (estado real-time) con sesiones persistidas en BD
/// (histórico), deduplicando por id. Orden: created_at DESC.
/// Devuelve array [{id,title,status,status_text,created_at,message_count,event_count,conversation_id,archived_at}].
/// El caller libera con da_string_free.
pub export fn da_sessions_json(handle: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    return sessionsJson(handle, .active, out_json);
}

/// como `da_sessions_json` pero con el filtro de archivo.
/// `mode`: 0 = activas (idéntico a `da_sessions_json`), 1 = solo archivadas
/// (el interruptor «Ver archivadas»), 2 = todas. El caller libera con
/// da_string_free.
pub export fn da_sessions_json_filtered(handle: ?*anyopaque, mode: c_int, out_json: *[*:0]u8) callconv(.c) c_int {
    const filter: session_store.SessionFilter = switch (mode) {
        0 => .active,
        1 => .archived,
        2 => .all,
        else => return @intFromEnum(err(.invalid_arg, "da_sessions_json_filtered: mode invalido (0=activas,1=archivadas,2=todas)")),
    };
    return sessionsJson(handle, filter, out_json);
}

fn sessionsJson(handle: ?*anyopaque, filter: session_store.SessionFilter, out_json: *[*:0]u8) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_sessions_json: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    var archived_ids = std.AutoHashMap(i64, i64).init(aa);
    defer archived_ids.deinit();
    {
        const stmt = st.db_conn.prepare("SELECT id, archived_at FROM orders WHERE archived_at IS NOT NULL") catch
            return @intFromEnum(err(.internal, "No se pudo leer el archivo de sesiones"));
        defer st.db_conn.finalize(stmt);
        while (true) {
            const step = db.c.sqlite3_step(stmt);
            if (step == db.c.SQLITE_DONE) break;
            if (step != db.c.SQLITE_ROW) return @intFromEnum(err(.internal, "No se pudo leer el archivo de sesiones"));
            archived_ids.put(db.c.sqlite3_column_int64(stmt, 0), db.c.sqlite3_column_int64(stmt, 1)) catch
                return @intFromEnum(err(.oom, "Sin memoria para listar sesiones"));
        }
    }

    // 1) Recolectar ids en memoria para dedup.
    var seen = std.AutoHashMap(i64, void).init(aa);
    defer seen.deinit();

    // los contadores por sesión eran dos `COUNT(*)` por fila — con ~700
    // sesiones y la tabla `events` engordada eso eran ~1400 consultas y ~42 s
    // dentro del handler, con TODO el carril rápido del bridge esperando
    // detrás (la cabina arrancaba muda >1 min). Dos agregados GROUP BY lo
    // dejan en una pasada por tabla.
    var msg_counts = std.AutoHashMap(i64, i64).init(aa);
    defer msg_counts.deinit();
    var ev_counts = std.AutoHashMap(i64, i64).init(aa);
    defer ev_counts.deinit();
    {
        const stmt = st.db_conn.prepare("SELECT order_id, COUNT(*) FROM messages GROUP BY order_id") catch null;
        if (stmt) |s| {
            defer st.db_conn.finalize(s);
            while (db.c.sqlite3_step(s) == db.c.SQLITE_ROW)
                msg_counts.put(db.c.sqlite3_column_int64(s, 0), db.c.sqlite3_column_int64(s, 1)) catch {};
        }
    }
    // Remate D1 (10-nov): recuento de la delegación de cada vuelta («0 de 2
    // integradas»), en la MISMA pasada por `events` que el contador.
    var deleg_counts = std.AutoHashMap(i64, [2]i64).init(aa);
    defer deleg_counts.deinit();
    {
        const stmt = st.db_conn.prepare(
            "SELECT order_id, COUNT(*), " ++
                "COALESCE(SUM(CASE WHEN kind = 'delegation_finished_v1' THEN json_extract(payload_json, '$.count') END), 0), " ++
                "COALESCE(SUM(CASE WHEN kind = 'delegation_finished_v1' THEN json_extract(payload_json, '$.integrated') END), 0) + " ++
                "COALESCE(SUM(CASE WHEN kind = 'delegation_audit_retry_v1' AND json_extract(payload_json, '$.integrated') = 1 THEN 1 END), 0) " ++
                "FROM events GROUP BY order_id",
        ) catch null;
        if (stmt) |s| {
            defer st.db_conn.finalize(s);
            while (db.c.sqlite3_step(s) == db.c.SQLITE_ROW) {
                const oid = db.c.sqlite3_column_int64(s, 0);
                ev_counts.put(oid, db.c.sqlite3_column_int64(s, 1)) catch
                    return @intFromEnum(err(.oom, "Sin memoria para listar sesiones"));
                const delegated = db.c.sqlite3_column_int64(s, 2);
                if (delegated > 0) deleg_counts.put(oid, .{ delegated, db.c.sqlite3_column_int64(s, 3) }) catch
                    return @intFromEnum(err(.oom, "Sin memoria para listar sesiones"));
            }
        }
    }

    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_sessions_json: OOM"));
        return @intFromEnum(ok());
    };

    // 2) Sesiones en memoria (estado real-time).
    for (st.orders.items) |o| {
        // M8: las ordenes que lanza la propia maquinaria (el gate de
        // aceptacion mete cuatro por pasada) no son conversaciones del usuario
        // y no deben llenarle la barra lateral. El filtro va aqui ADEMAS de en
        // `session_store.listSessions` porque esta lista mezcla las dos
        // fuentes: las vivas en memoria y las persistidas.
        if (std.mem.startsWith(u8, o.project_id, session_store.INTERNAL_PROJECT_PREFIX)) continue;
        // Una sesión borrada por el usuario no vuelve a la lista aunque su
        // registro siga vivo por los handles obsoletos.
        if (o.deleted) continue;
        // el filtro de archivo decide si esta orden viva sale.
        const archived_at = archived_ids.get(o.db_id orelse o.id) orelse 0;
        switch (filter) {
            .active => {
                if (archived_at != 0) continue;
            },
            .archived => {
                if (archived_at == 0) continue;
            },
            .all => {},
        }
        const db_id = o.db_id orelse o.id;
        seen.put(db_id, {}) catch continue;
        const title = getOrderTitle(st, db_id, o.text, aa);
        defer aa.free(title);
        const msg_count = msg_counts.get(db_id) orelse 0;
        const ev_count = ev_counts.get(db_id) orelse 0;
        js.beginObject() catch continue;
        js.objectField("id") catch continue;
        js.write(o.id) catch continue;
        js.objectField("title") catch continue;
        js.write(title) catch continue;
        js.objectField("status") catch continue;
        js.write(@intFromEnum(orderStatusToDa(o.status))) catch continue;
        js.objectField("status_text") catch continue;
        js.write(o.status.toText()) catch continue;
        js.objectField("created_at") catch continue;
        js.write(o.created_at) catch continue;
        js.objectField("message_count") catch continue;
        js.write(msg_count) catch continue;
        js.objectField("event_count") catch continue;
        js.write(ev_count) catch continue;
        // Mismo campo que en la rama persistida: sin el, las ordenes VIVAS
        // (las que acabas de lanzar) no se agrupaban con las de su hilo y la
        // barra lateral volvia a enseñarlas sueltas justo cuando mas se nota.
        js.objectField("conversation_id") catch continue;
        js.write(o.conversation_id orelse "") catch continue;
        // La base es la fuente de verdad también para órdenes en memoria.
        js.objectField("archived_at") catch continue;
        js.write(archived_at) catch continue;
        if (deleg_counts.get(db_id)) |d| {
            js.objectField("delegated") catch continue;
            js.write(d[0]) catch continue;
            js.objectField("integrated") catch continue;
            js.write(d[1]) catch continue;
        }
        js.endObject() catch continue;
    }

    // 3) Sesiones persistidas en BD que no están en memoria (histórico).
    if (st.sessions) |s| {
        const db_sessions = s.listSessionsFilteredFn(aa, filter) catch &[_]session_store.SessionInfo{};
        defer {
            // `status` y `conversation_id` tambien se duplican en listSessions y
            // aqui solo se liberaba `title`: fuga por sesion en cada listado.
            for (db_sessions) |si| {
                aa.free(si.title);
                aa.free(si.status);
                aa.free(si.conversation_id);
            }
            aa.free(db_sessions);
        }
        for (db_sessions) |si| {
            if (seen.contains(si.id)) continue;
            const msg_count = msg_counts.get(si.id) orelse 0;
            const ev_count = ev_counts.get(si.id) orelse 0;
            js.beginObject() catch continue;
            js.objectField("id") catch continue;
            js.write(si.id) catch continue;
            js.objectField("title") catch continue;
            js.write(si.title) catch continue;
            js.objectField("status") catch continue;
            js.write(@as(i64, 0)) catch continue;
            js.objectField("status_text") catch continue;
            js.write(si.status) catch continue;
            js.objectField("created_at") catch continue;
            js.write(si.created_at) catch continue;
            js.objectField("message_count") catch continue;
            js.write(msg_count) catch continue;
            js.objectField("event_count") catch continue;
            js.write(ev_count) catch continue;
            // Lo que permite a la barra lateral agrupar las ordenes de un mismo
            // hilo en UNA fila en vez de enseñar cinco casi identicas.
            js.objectField("conversation_id") catch continue;
            js.write(si.conversation_id) catch continue;
            // epoch segundos en que se archivó, o 0 si activa.
            js.objectField("archived_at") catch continue;
            js.write(si.archived_at) catch continue;
            if (deleg_counts.get(si.id)) |d| {
                js.objectField("delegated") catch continue;
                js.write(d[0]) catch continue;
                js.objectField("integrated") catch continue;
                js.write(d[1]) catch continue;
            }
            js.endObject() catch continue;
        }
    }

    js.endArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_sessions_json: OOM"));
        return @intFromEnum(ok());
    };
    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_sessions_json: OOM"));
    return @intFromEnum(ok());
}

/// Devuelve el título persistido de una orden, o el título derivado del prompt
/// si no hay renombramiento previo.
fn getOrderTitle(st: *CoreState, db_id: i64, fallback: []const u8, aa: std.mem.Allocator) []const u8 {
    // P1 (16-oct-2026, corrección de la auditoría): el titulo sale del TEXTO
    // DEL USUARIO, no del ENTENDIMIENTO del planificador.
    //
    // La regla es EXACTAMENTE la de `session_store.zig:176` (title > prompt
    // del usuario no vacío > entendimiento): las sesiones vivas y las
    // persistidas deben rotularse igual, o la barra lateral cambia de título
    // en cuanto la orden pasa de la memoria a la base. Antes esta rama aún
    // priorizaba el entendimiento («El usuario solicita crear un ar…») y las
    // vivas salían robóticas mientras las persistidas ya no.
    //
    // Un renombrado explicito del usuario gana siempre: `title` va primero.
    //
    // P4: si el texto recortado supera 80 caracteres se le añade «…» para que
    // el recorte sea visible y no parezca que el título acaba ahí.
    const stmt = st.db_conn.prepare(
        \\SELECT TRIM(REPLACE(REPLACE(
        \\  CASE WHEN LENGTH(raw) > 80 THEN SUBSTR(raw, 1, 80) || CHAR(8230) ELSE raw END,
        \\  CHAR(10), ' '), CHAR(13), ' '))
        \\FROM (
        \\  SELECT COALESCE(
        \\    o.title,
        \\    NULLIF(TRIM(o.user_prompt), ''),
        \\    (SELECT p.understanding FROM plans p
        \\      WHERE p.order_id = o.id AND TRIM(COALESCE(p.understanding,'')) <> ''
        \\        AND p.understanding NOT LIKE 'No pude planificar%'
        \\      ORDER BY p.id DESC LIMIT 1)) AS raw
        \\  FROM orders o WHERE o.id = ?
        \\)
    ) catch return deriveTitle(aa, fallback) catch fallback;
    defer st.db_conn.finalize(stmt);
    db.bindInt(stmt, 1, db_id) catch return deriveTitle(aa, fallback) catch fallback;
    if (db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW) {
        const ptr = db.c.sqlite3_column_text(stmt, 0);
        const len = db.c.sqlite3_column_bytes(stmt, 0);
        return aa.dupe(u8, ptr[0..@intCast(len)]) catch deriveTitle(aa, fallback) catch fallback;
    }
    return deriveTitle(aa, fallback) catch fallback;
}

/// SESSIONS-PERSIST-06: devuelve los mensajes de una sesión como JSON array
/// [{id,role,content,created_at}]. El caller libera con da_string_free.
pub export fn da_session_messages_json(handle: ?*anyopaque, order: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_session_messages_json: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order) orelse return @intFromEnum(err(.invalid_arg, "da_session_messages_json: null order handle"));
    const aa = st.arena.child_allocator;

    // Si la orden está en memoria, usar su db_id; si no, asumir que order_id
    // es el db_id persistido (sesión histórica tras reinicio).
    const db_id: i64 = if (findOrder(st, order_id)) |rec| (rec.db_id orelse rec.id) else order_id;

    if (st.sessions) |s| {
        const msgs = s.loadMessagesFn(aa, db_id) catch {
            out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_session_messages_json: OOM"));
            return @intFromEnum(ok());
        };
        defer {
            for (msgs) |m| {
                aa.free(m.role);
                aa.free(m.content);
            }
            aa.free(msgs);
        }
        var out: std.Io.Writer.Allocating = .init(aa);
        defer out.deinit();
        var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
        js.beginArray() catch {
            out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_session_messages_json: OOM"));
            return @intFromEnum(ok());
        };
        for (msgs) |m| {
            js.beginObject() catch continue;
            js.objectField("id") catch continue;
            js.write(m.id) catch continue;
            js.objectField("role") catch continue;
            js.write(m.role) catch continue;
            js.objectField("content") catch continue;
            js.write(m.content) catch continue;
            js.objectField("created_at") catch continue;
            js.write(m.created_at) catch continue;
            js.endObject() catch continue;
        }
        js.endArray() catch {
            out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_session_messages_json: OOM"));
            return @intFromEnum(ok());
        };
        out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_session_messages_json: OOM"));
        return @intFromEnum(ok());
    }

    out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_session_messages_json: OOM"));
    return @intFromEnum(ok());
}

/// P4: devuelve el timeline completo de una sesión para replay tipo Devin:
/// mensajes de chat + eventos de motor (razonamiento, comandos, archivos, reporte)
/// intercalables cronológicamente, más metadatos de la orden. El caller libera con
/// da_string_free.
/// out_json: {
///   "order": {id, title, status, status_text, created_at},
///   "messages": [{id, role, content, created_at}],
///   "events": [{id, ts, source, kind, title, severity, payload}],
///   "has_more": bool,
///   "offset": i64,
///   "limit": i64,
///   "message_count": i64,
///   "event_count": i64
/// }
pub export fn da_session_timeline_json(
    handle: ?*anyopaque,
    order: ?*anyopaque,
    offset: i64,
    limit: i64,
    out_json: *[*:0]u8,
) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_session_timeline_json: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order) orelse return @intFromEnum(err(.invalid_arg, "da_session_timeline_json: null order handle"));
    const aa = st.arena.child_allocator;

    const db_id: i64 = if (findOrder(st, order_id)) |rec| (rec.db_id orelse rec.id) else order_id;
    const eff_limit: i64 = if (limit <= 0 or limit > 200) 50 else limit;

    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginObject() catch {
        out_json.* = ownedCStr("{}") orelse return @intFromEnum(err(.oom, "da_session_timeline_json: OOM"));
        return @intFromEnum(ok());
    };

    // ── order metadata ──
    js.objectField("order") catch {};
    js.beginObject() catch {};
    js.objectField("id") catch {};
    js.write(order_id) catch {};
    {
        const title = getOrderTitle(st, db_id, "", aa);
        defer aa.free(title);
        js.objectField("title") catch {};
        js.write(title) catch {};
    }
    {
        const status_text: []const u8 = if (findOrder(st, order_id)) |rec| rec.status.toText() else blk: {
            const stmt = st.db_conn.prepare("SELECT status FROM orders WHERE id = ?") catch break :blk "unknown";
            defer st.db_conn.finalize(stmt);
            db.bindInt(stmt, 1, db_id) catch break :blk "unknown";
            if (db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW) {
                const ptr = db.c.sqlite3_column_text(stmt, 0);
                const len = db.c.sqlite3_column_bytes(stmt, 0);
                break :blk ptr[0..@intCast(len)];
            }
            break :blk "unknown";
        };
        const status_int: i64 = if (findOrder(st, order_id)) |rec| @intFromEnum(orderStatusToDa(rec.status)) else 0;
        js.objectField("status") catch {};
        js.write(status_int) catch {};
        js.objectField("status_text") catch {};
        js.write(status_text) catch {};
    }
    {
        const created_at: i64 = if (findOrder(st, order_id)) |rec| rec.created_at else blk: {
            const stmt = st.db_conn.prepare("SELECT created_at FROM orders WHERE id = ?") catch break :blk 0;
            defer st.db_conn.finalize(stmt);
            db.bindInt(stmt, 1, db_id) catch break :blk 0;
            if (db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW) {
                break :blk db.c.sqlite3_column_int64(stmt, 0);
            }
            break :blk 0;
        };
        js.objectField("created_at") catch {};
        js.write(created_at) catch {};
    }
    js.endObject() catch {};

    // ── messages (paginados) ──
    var message_count: i64 = 0;
    var has_more: bool = false;
    js.objectField("messages") catch {};
    if (st.sessions) |s| {
        const all_msgs = s.loadMessagesFn(aa, db_id) catch &[_]session_store.Message{};
        defer {
            if (all_msgs.len > 0) {
                for (all_msgs) |m| {
                    aa.free(m.role);
                    aa.free(m.content);
                }
                aa.free(all_msgs);
            }
        }
        message_count = @intCast(all_msgs.len);
        const start: usize = @intCast(@max(0, offset));
        const end: usize = @intCast(@min(all_msgs.len, start + @as(usize, @intCast(eff_limit))));
        if (end < all_msgs.len) has_more = true;
        js.beginArray() catch {};
        for (start..end) |i| {
            const m = all_msgs[i];
            js.beginObject() catch continue;
            js.objectField("id") catch continue;
            js.write(m.id) catch continue;
            js.objectField("role") catch continue;
            js.write(m.role) catch continue;
            js.objectField("content") catch continue;
            js.write(m.content) catch continue;
            js.objectField("created_at") catch continue;
            js.write(m.created_at) catch continue;
            js.endObject() catch continue;
        }
        js.endArray() catch {};
    } else {
        js.beginArray() catch {};
        js.endArray() catch {};
    }

    // ── events (paginados, ordenados por ts) ──
    var event_count: i64 = 0;
    js.objectField("events") catch {};
    const count_stmt = st.db_conn.prepare("SELECT COUNT(*) FROM events WHERE order_id = ?") catch null;
    if (count_stmt) |stmt| {
        defer st.db_conn.finalize(stmt);
        db.bindInt(stmt, 1, db_id) catch {};
        if (db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW) {
            event_count = db.c.sqlite3_column_int64(stmt, 0);
        }
    }
    const stmt_opt = st.db_conn.prepare("SELECT id, ts, source, kind, payload_json FROM events WHERE order_id = ? ORDER BY ts ASC, id ASC LIMIT ? OFFSET ?") catch null;
    if (stmt_opt) |stmt| {
        defer st.db_conn.finalize(stmt);
        db.bindInt(stmt, 1, db_id) catch {};
        db.bindInt(stmt, 2, eff_limit) catch {};
        db.bindInt(stmt, 3, offset) catch {};

        var arena = std.heap.ArenaAllocator.init(aa);
        defer arena.deinit();
        const tmp = arena.child_allocator;

        js.beginArray() catch {};
        while (db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW) {
            const id = db.c.sqlite3_column_int64(stmt, 0);
            const ts = db.c.sqlite3_column_int64(stmt, 1);
            const source_ptr = db.c.sqlite3_column_text(stmt, 2);
            const source_len = db.c.sqlite3_column_bytes(stmt, 2);
            const kind_ptr = db.c.sqlite3_column_text(stmt, 3);
            const kind_len = db.c.sqlite3_column_bytes(stmt, 3);
            const payload_ptr = db.c.sqlite3_column_text(stmt, 4);
            const payload_len = db.c.sqlite3_column_bytes(stmt, 4);
            const source = source_ptr[0..@intCast(source_len)];
            const kind = kind_ptr[0..@intCast(kind_len)];
            const payload_json = payload_ptr[0..@intCast(payload_len)];

            var parsed = std.json.parseFromSlice(std.json.Value, tmp, payload_json, .{}) catch null;
            const payload = if (parsed) |*p| &p.value else null;
            const title = eventTitle(tmp, kind, source, payload) catch kind;
            const severity = eventSeverity(kind, payload);

            js.beginObject() catch continue;
            js.objectField("id") catch continue;
            js.write(id) catch continue;
            js.objectField("ts") catch continue;
            js.write(ts) catch continue;
            js.objectField("source") catch continue;
            js.write(source) catch continue;
            js.objectField("kind") catch continue;
            js.write(kind) catch continue;
            js.objectField("title") catch continue;
            js.write(title) catch continue;
            js.objectField("severity") catch continue;
            js.write(severity) catch continue;
            js.objectField("payload") catch continue;
            if (payload) |p| js.write(p.*) catch continue else js.write(std.json.Value{ .null = {} }) catch continue;
            js.endObject() catch continue;

            if (parsed) |*p| p.deinit();
        }
        js.endArray() catch {};
        if (event_count > offset + eff_limit) has_more = true;
    } else {
        js.beginArray() catch {};
        js.endArray() catch {};
    }

    js.objectField("has_more") catch {};
    js.write(has_more) catch {};
    js.objectField("offset") catch {};
    js.write(offset) catch {};
    js.objectField("limit") catch {};
    js.write(eff_limit) catch {};
    js.objectField("message_count") catch {};
    js.write(message_count) catch {};
    js.objectField("event_count") catch {};
    js.write(event_count) catch {};
    js.endObject() catch {};

    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_session_timeline_json: OOM"));
    return @intFromEnum(ok());
}

/// P2: Establece la raíz del workspace donde se guardan los archivos generados.
/// Si path es NULL o vacío, restaura el default ("devagents-workspace").
pub export fn da_set_workspace_root(handle: ?*anyopaque, path: ?[*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_set_workspace_root: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    if (st.mcp_surface) {
        // Un cliente MCP solo puede estrechar la raíz ya elegida; moverla a otra
        // carpeta (donde pueda dejar un script que luego se ejecute) es de la cabina.
        const requested = if (path) |p| std.mem.span(p) else "";
        // SEC2 R6/H6: se compara la raiz EFECTIVA pedida con la efectiva vigente
        // (la seleccion no incluye el segmento S2 y dejaba mover a una hermana).
        if (!workspace.narrowsEffectiveRoot(requested)) {
            return @intFromEnum(err(.invalid_state, "da_set_workspace_root: un cliente MCP solo puede estrechar la raiz actual; cambiarla requiere la cabina o DEVAGENTS_WORKSPACE_ROOT al lanzar devagents-mcp"));
        }
    }
    if (path) |p| {
        const s = std.mem.span(p);
        if (s.len > 0) {
            workspace.setWorkspaceRootChecked(s) catch |e| {
                var buf: [256]u8 = undefined;
                const msg = std.fmt.bufPrint(&buf, "workspace: {s}; raíz conservada, elija una ruta absoluta sin reparse points", .{@errorName(e)}) catch "workspace: raíz inválida; raíz conservada";
                return @intFromEnum(err(.invalid_arg, msg));
            };

            return @intFromEnum(ok());
        }
    }
    workspace.setWorkspaceRootChecked(workspace.WORKSPACE_ROOT) catch return @intFromEnum(err(.internal, "workspace: no se pudo restaurar la raíz por defecto"));

    return @intFromEnum(ok());
}

// ── T7 (e): «Reglas del proyecto» ──────────────────────────────
//
// Por proyecto (la carpeta que eligió el usuario; sin elegir, la raíz de
// trabajo), guardadas en catalog.db y aplicadas en todos los modos por
// core/src/project_rules.zig. Solo la cabina las cambia: un cliente MCP no
// toca las reglas que lo gobiernan («paridad sin gobierno», 13-nov).

fn projectRulesRoot(buf: *[4096]u8) []const u8 {
    return workspace.selectedProjectRoot(buf) orelse workspace.effectiveRoot(buf);
}

/// {projectRoot, custom, rules, defaultRules, projectDocs, precedence, maxBytes}.
pub export fn da_project_rules_get_json(handle: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_project_rules_get_json: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    var buf: [4096]u8 = undefined;
    const body = project_rules.describeJson(aa, st.catalog.db, projectRulesRoot(&buf)) catch |e| return switch (e) {
        error.OutOfMemory => @intFromEnum(err(.oom, "da_project_rules_get_json: OOM")),
        else => @intFromEnum(err(.internal, "da_project_rules_get_json: no se pudieron leer las reglas del proyecto")),
    };
    defer aa.free(body);
    out_json.* = ownedCStr(body) orelse return @intFromEnum(err(.oom, "da_project_rules_get_json: OOM"));
    return @intFromEnum(ok());
}

// ── T7 (f): varias cuentas por CLI ─────────────────────────────
//
// Carpeta por cuenta bajo `<datos>\cli-accounts`; la cabina las da de alta, el
// usuario inicia sesión en la terminal integrada y elige con cuál empiezan
// las órdenes. Solo la cabina: un cliente MCP no toca cuentas ni credenciales.

fn cliAccountsGuard(handle: ?*anyopaque, comptime name: []const u8) ?*CoreState {
    const st: *CoreState = @ptrCast(@alignCast(handle orelse {
        _ = err(.invalid_arg, name ++ ": null core handle");
        return null;
    }));
    if (st.mcp_surface) {
        _ = err(.invalid_state, name ++ ": las cuentas de las CLIs solo se gestionan en la cabina");
        return null;
    }
    return st;
}

fn cliAccountsFail(e: anyerror) c_int {
    return switch (e) {
        error.UnsupportedCli => @intFromEnum(err(.invalid_arg, "Esa CLI no admite varias cuentas aisladas (solo Codex y Claude Code)")),
        error.InvalidLabel => @intFromEnum(err(.invalid_arg, "Nombre de cuenta no válido (1 a 40 caracteres, sin comillas ni & | < > ^ %)")),
        error.TooManyAccounts => @intFromEnum(err(.invalid_arg, "Máximo 8 cuentas por CLI")),
        error.UnknownAccount => @intFromEnum(err(.not_found, "Esa cuenta no existe")),
        error.InvalidDataDir => @intFromEnum(err(.internal, "La carpeta de datos no admite cuentas (ruta no válida o sin permiso)")),
        error.AccountFolderBusy => @intFromEnum(err(.invalid_state, "La carpeta de la cuenta está en uso (cierra la CLI que la usa) y no se quitó nada; vuelve a intentarlo")),
        error.OutOfMemory => @intFromEnum(err(.oom, "cuentas de CLI: OOM")),
        else => @intFromEnum(err(.internal, "No se pudieron guardar las cuentas de la CLI")),
    };
}

fn cliAccountsDataDir(st: *CoreState) ?[]const u8 {
    if (std.mem.eql(u8, st.runtime_path, ":memory:")) return null;
    return std.fs.path.dirname(st.runtime_path);
}

/// {clis:[{cli,display,envVar,selected,accounts:[{id,label,dir,loginCommand}]}], unsupported:[...]}
pub export fn da_cli_accounts_json(handle: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    const st = cliAccountsGuard(handle, "da_cli_accounts_json") orelse return @intFromEnum(DaResult.invalid_state);
    const aa = st.arena.child_allocator;
    const body = cli_accounts.describeJson(aa, st.catalog.db) catch |e| return cliAccountsFail(e);
    defer aa.free(body);
    out_json.* = ownedCStr(body) orelse return @intFromEnum(err(.oom, "da_cli_accounts_json: OOM"));
    return @intFromEnum(ok());
}

/// `{"cli":"codex","label":"Trabajo"}` → crea la carpeta y la registra.
pub export fn da_cli_account_add(handle: ?*anyopaque, json: ?[*:0]const u8) callconv(.c) c_int {
    const st = cliAccountsGuard(handle, "da_cli_account_add") orelse return @intFromEnum(DaResult.invalid_state);
    const aa = st.arena.child_allocator;
    const data_dir = cliAccountsDataDir(st) orelse return @intFromEnum(err(.invalid_state, "da_cli_account_add: sin carpeta de datos"));
    var parsed = std.json.parseFromSlice(struct { cli: []const u8, label: []const u8 }, aa, std.mem.span(json orelse return @intFromEnum(err(.invalid_arg, "da_cli_account_add: falta el JSON"))), .{}) catch
        return @intFromEnum(err(.invalid_arg, "da_cli_account_add: se esperaba {cli,label}"));
    defer parsed.deinit();
    var threaded = std.Io.Threaded.init(aa, .{});
    defer threaded.deinit();
    const account = cli_accounts.add(aa, threaded.io(), st.catalog.db, data_dir, parsed.value.cli, parsed.value.label) catch |e| return cliAccountsFail(e);
    cli_accounts.freeAccount(aa, account);
    return @intFromEnum(ok());
}

/// Quita la cuenta y su carpeta (solo bajo `<datos>\cli-accounts`).
pub export fn da_cli_account_remove(handle: ?*anyopaque, id: ?[*:0]const u8) callconv(.c) c_int {
    const st = cliAccountsGuard(handle, "da_cli_account_remove") orelse return @intFromEnum(DaResult.invalid_state);
    const aa = st.arena.child_allocator;
    const data_dir = cliAccountsDataDir(st) orelse return @intFromEnum(err(.invalid_state, "da_cli_account_remove: sin carpeta de datos"));
    var threaded = std.Io.Threaded.init(aa, .{});
    defer threaded.deinit();
    // QA-B 6: si la carpeta no se pudo borrar, la cuenta igualmente se quitó
    // entera y el aviso viaja en el estado (`notice`) que la cabina pinta.
    const outcome = cli_accounts.remove(aa, threaded.io(), st.catalog.db, data_dir, std.mem.span(id orelse return @intFromEnum(err(.invalid_arg, "da_cli_account_remove: falta id")))) catch |e| return cliAccountsFail(e);
    if (outcome == .left_behind or outcome == .kept_outside) std.log.warn("cuenta de CLI quitada; su carpeta queda en disco ({s})", .{@tagName(outcome)});
    return @intFromEnum(ok());
}

/// `{"cli":"codex","id":"codex-2"}` o `{"cli":"codex","id":null}` (login del sistema).
pub export fn da_cli_account_select(handle: ?*anyopaque, json: ?[*:0]const u8) callconv(.c) c_int {
    const st = cliAccountsGuard(handle, "da_cli_account_select") orelse return @intFromEnum(DaResult.invalid_state);
    const aa = st.arena.child_allocator;
    var parsed = std.json.parseFromSlice(struct { cli: []const u8, id: ?[]const u8 = null }, aa, std.mem.span(json orelse return @intFromEnum(err(.invalid_arg, "da_cli_account_select: falta el JSON"))), .{}) catch
        return @intFromEnum(err(.invalid_arg, "da_cli_account_select: se esperaba {cli,id}"));
    defer parsed.deinit();
    const id: ?[]const u8 = if (parsed.value.id) |v| (if (v.len == 0) null else v) else null;
    cli_accounts.select(aa, st.catalog.db, parsed.value.cli, id) catch |e| return cliAccountsFail(e);
    return @intFromEnum(ok());
}

/// `{"rules":"<texto>"}` guarda reglas propias para el proyecto abierto;
/// `{"rules":""}` o `{"reset":true}` vuelve a las de DevAgents.
pub export fn da_project_rules_set(handle: ?*anyopaque, json: ?[*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_project_rules_set: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    if (st.mcp_surface) return @intFromEnum(err(.invalid_state, "da_project_rules_set: las reglas del proyecto solo se cambian en la cabina"));
    const aa = st.arena.child_allocator;
    const text = std.mem.span(json orelse return @intFromEnum(err(.invalid_arg, "da_project_rules_set: falta el JSON")));
    var parsed = std.json.parseFromSlice(std.json.Value, aa, text, .{}) catch return @intFromEnum(err(.invalid_arg, "da_project_rules_set: JSON inválido"));
    defer parsed.deinit();
    if (parsed.value != .object) return @intFromEnum(err(.invalid_arg, "da_project_rules_set: se esperaba un objeto"));
    const reset = if (parsed.value.object.get("reset")) |v| v == .bool and v.bool else false;
    const rules: ?[]const u8 = if (reset) null else if (parsed.value.object.get("rules")) |v| switch (v) {
        .string => |s| s,
        .null => null,
        else => return @intFromEnum(err(.invalid_arg, "da_project_rules_set: rules debe ser texto")),
    } else return @intFromEnum(err(.invalid_arg, "da_project_rules_set: falta rules o reset"));
    var buf: [4096]u8 = undefined;
    const root = projectRulesRoot(&buf);
    project_rules.save(st.catalog.db, aa, root, rules) catch |e| return switch (e) {
        error.RulesTooLarge => @intFromEnum(err(.invalid_arg, "Las reglas superan 16 KiB")),
        error.InvalidRules => @intFromEnum(err(.invalid_arg, "Las reglas deben ser texto UTF-8 sin caracteres nulos")),
        error.OutOfMemory => @intFromEnum(err(.oom, "da_project_rules_set: OOM")),
        else => @intFromEnum(err(.internal, "No se pudieron guardar las reglas del proyecto")),
    };

    return @intFromEnum(ok());
}

test "E5.20 E-129: C-ABI muestra el rechazo de reanclaje por last_error" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    defer workspace.setWorkspaceRoot(workspace.WORKSPACE_ROOT);
    try std.testing.expect(da_set_workspace_root(handle, "..") != 0);
    var message: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_last_error(&message));
    defer da_string_free(message);
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(message), "WorkspaceReanchorDenied") != null);
    try std.testing.expect(da_set_workspace_root(null, "C:\\tmp") != 0);
    try std.testing.expectEqual(@as(c_int, 0), da_set_workspace_root(handle, null));
}

/// P2: Lista los artefactos generados, opcionalmente filtrados por order_id.
/// Devuelve un JSON array de objetos {order_id, file_path, size}.
/// Si order_id es 0, lista todas las órdenes.
const FIND_DATA_W = extern struct {
    dwFileAttributes: u32,
    ftCreationTime_dwLowDateTime: u32,
    ftCreationTime_dwHighDateTime: u32,
    ftLastAccessTime_dwLowDateTime: u32,
    ftLastAccessTime_dwHighDateTime: u32,
    ftLastWriteTime_dwLowDateTime: u32,
    ftLastWriteTime_dwHighDateTime: u32,
    nFileSizeHigh: u32,
    nFileSizeLow: u32,
    dwReserved0: u32,
    dwReserved1: u32,
    cFileName: [260]u16,
    cAlternateFileName: [14]u16,
};

const FILE_ATTRIBUTE_DIRECTORY_FLAG: u32 = 0x10;

/// la enumeración de artefactos va por la API W — la vía ANSI
/// (FindFirstFileA) mutilaba nombres UTF-8 reales (0/40 intactos medido en
/// E3.18) y hacía rutas unicode completamente inaccesibles.
fn findFirstUtf8(pattern_utf8: []const u8, fd: *FIND_DATA_W) windows.HANDLE {
    const pattern_w = std.unicode.utf8ToUtf16LeAllocZ(std.heap.page_allocator, pattern_utf8) catch return windows.INVALID_HANDLE_VALUE;
    defer std.heap.page_allocator.free(pattern_w);
    return FindFirstFileW(pattern_w, @ptrCast(fd));
}

fn fdNameUtf8(a: std.mem.Allocator, fd: *const FIND_DATA_W) ![]u8 {
    const len = std.mem.indexOfScalar(u16, &fd.cFileName, 0) orelse fd.cFileName.len;
    return std.unicode.utf16LeToUtf8Alloc(a, fd.cFileName[0..len]);
}

/// Escribe en `js` los objetos {order_id, file_path, file_name, size} de los
/// archivos directamente dentro de `dir_utf8`. Best-effort como el llamador:
/// una entrada que no se puede serializar corta la enumeración de ese dir.
fn listArtifactsDirUtf8(js: *std.json.Stringify, dir_utf8: []const u8, order_id: i64) void {
    const pattern = std.fmt.allocPrint(std.heap.page_allocator, "{s}" ++ std.fs.path.sep_str ++ "*", .{dir_utf8}) catch return;
    defer std.heap.page_allocator.free(pattern);
    var fd: FIND_DATA_W = undefined;
    const h = findFirstUtf8(pattern, &fd);
    if (h == windows.INVALID_HANDLE_VALUE) return;
    defer _ = FindClose(h);
    while (true) {
        if (fd.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY_FLAG == 0) {
            const name = fdNameUtf8(std.heap.page_allocator, &fd) catch break;
            defer std.heap.page_allocator.free(name);
            if (!std.mem.eql(u8, name, ".") and !std.mem.eql(u8, name, "..")) {
                const size: u64 = (@as(u64, fd.nFileSizeHigh) << 32) | @as(u64, fd.nFileSizeLow);
                const full_path = std.fmt.allocPrint(std.heap.page_allocator, "{s}" ++ std.fs.path.sep_str ++ "{s}", .{ dir_utf8, name }) catch break;
                defer std.heap.page_allocator.free(full_path);
                js.beginObject() catch break;
                js.objectField("order_id") catch break;
                js.write(order_id) catch break;
                js.objectField("file_path") catch break;
                js.write(full_path) catch break;
                js.objectField("file_name") catch break;
                js.write(name) catch break;
                js.objectField("size") catch break;
                js.write(size) catch break;
                js.endObject() catch break;
            }
        }
        if (FindNextFileW(h, @ptrCast(&fd)) == 0) break;
    }
}

pub export fn da_list_artifacts_json(handle: ?*anyopaque, order_id: i64, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_list_artifacts_json: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    // B3: los artefactos de una orden con space viven en su worktree, no en la
    // raiz global — sin esta resolucion la UI no veria nada de esa orden.
    var wt_buf: [4096]u8 = undefined;
    const art_db_id: i64 = if (findOrder(st, order_id)) |rec| (rec.db_id orelse rec.id) else order_id;
    const root = if (order_id > 0)
        orderWorktree(st, art_db_id, &wt_buf)
    else
        workspace.effectiveRoot(&wt_buf);

    var out: std.Io.Writer.Allocating = .init(std.heap.page_allocator);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_list_artifacts_json: OOM"));
        return @intFromEnum(ok());
    };

    if (order_id > 0) {
        // List files for a specific order
        const dir = std.fmt.allocPrint(std.heap.page_allocator, "{s}" ++ std.fs.path.sep_str ++ "orden-{d}", .{ root, order_id }) catch {
            out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_list_artifacts_json: OOM"));
            return @intFromEnum(ok());
        };
        defer std.heap.page_allocator.free(dir);
        listArtifactsDirUtf8(&js, dir, order_id);
    } else {
        // List all order directories
        const pattern = std.fmt.allocPrint(std.heap.page_allocator, "{s}" ++ std.fs.path.sep_str ++ "*", .{root}) catch {
            out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_list_artifacts_json: OOM"));
            return @intFromEnum(ok());
        };
        defer std.heap.page_allocator.free(pattern);

        var fd: FIND_DATA_W = undefined;
        const h = findFirstUtf8(pattern, &fd);
        if (h != windows.INVALID_HANDLE_VALUE) {
            defer _ = FindClose(h);
            while (true) {
                if (fd.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY_FLAG != 0) {
                    const name = fdNameUtf8(std.heap.page_allocator, &fd) catch break;
                    defer std.heap.page_allocator.free(name);
                    if (std.mem.eql(u8, name, ".") or std.mem.eql(u8, name, "..") or
                        !std.mem.startsWith(u8, name, "orden-"))
                    {
                        if (FindNextFileW(h, @ptrCast(&fd)) == 0) break;
                        continue;
                    }
                    const oid = std.fmt.parseInt(i64, name[6..], 10) catch {
                        if (FindNextFileW(h, @ptrCast(&fd)) == 0) break;
                        continue;
                    };
                    const dir = std.fmt.allocPrint(std.heap.page_allocator, "{s}" ++ std.fs.path.sep_str ++ "{s}", .{ root, name }) catch break;
                    defer std.heap.page_allocator.free(dir);
                    listArtifactsDirUtf8(&js, dir, oid);
                }
                if (FindNextFileW(h, @ptrCast(&fd)) == 0) break;
            }
        }
    }

    js.endArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_list_artifacts_json: OOM"));
        return @intFromEnum(ok());
    };
    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_list_artifacts_json: OOM"));
    return @intFromEnum(ok());
}

/// SESSIONS-PERSIST-06: renombra una sesión (persiste title en runtime.db).
pub export fn da_session_rename(handle: ?*anyopaque, order: ?*anyopaque, title: [*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_session_rename: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order) orelse return @intFromEnum(err(.invalid_arg, "da_session_rename: null order handle"));
    const t = std.mem.span(title);
    if (t.len == 0) return @intFromEnum(err(.invalid_arg, "da_session_rename: empty title"));

    const rec = findOrder(st, order_id) orelse return @intFromEnum(err(.not_found, "da_session_rename: order not found"));
    const db_id = rec.db_id orelse rec.id;

    if (st.sessions) |s| {
        s.renameSessionFn(db_id, t) catch return @intFromEnum(err(.internal, "da_session_rename: DB error"));
    } else {
        return @intFromEnum(err(.internal, "da_session_rename: no session store"));
    }
    return @intFromEnum(ok());
}

/// S8: borra una sesión del historial, con todo lo que cuelga de ella.
///
/// Acepta el id de orden AUNQUE ya no esté en memoria: el historial que ve el
/// usuario mezcla las órdenes vivas con las persistidas (ver `da_sessions_json`),
/// y exigir `findOrder` haría imposible borrar justo las viejas, que son las que
/// llenan la lista.
pub export fn da_session_delete(handle: ?*anyopaque, order: ?*anyopaque) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_session_delete: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order) orelse return @intFromEnum(err(.invalid_arg, "da_session_delete: null order handle"));
    const db_id = if (findOrder(st, order_id)) |rec| (rec.db_id orelse rec.id) else order_id;

    const dispatch = st.dispatch_registry.snapshot(order_id);
    if (dispatch.found and !dispatch.done) return @intFromEnum(err(.invalid_state, "da_session_delete: execution is active; stop it before deleting"));
    const s = st.sessions orelse return @intFromEnum(err(.internal, "da_session_delete: no session store"));
    s.deleteSessionFn(db_id) catch |e| return @intFromEnum(if (e == error.SessionActive)
        err(.invalid_state, "da_session_delete: order is active; stop it before deleting")
    else
        err(.internal, "da_session_delete: transaction failed; session preserved"));
    // The record stays allocated until shutdown; invalidate approvals through a
    // stale handle instead of freeing memory another reader might still hold.
    // `deleted` la saca de `da_sessions_json`: sin ella la sesión borrada
    // reaparecía en la barra lateral como «rejected» hasta el reinicio.
    if (findOrder(st, order_id)) |rec| {
        rec.status = .rejected;
        rec.deleted = true;
    }
    return @intFromEnum(ok());
}

/// archiva (`archived != 0`) o desarchiva una sesión. Es
/// REVERSIBLE y nunca borra: marca `orders.archived_at` de todas las órdenes
/// del hilo (o solo la orden si no tiene conversación). Archivar solo afecta a
/// órdenes terminales; una en curso permanece visible. Acepta el id de una
/// orden que ya no está en memoria porque el historial mezcla órdenes vivas y
/// persistidas.
pub export fn da_session_archive(handle: ?*anyopaque, order: ?*anyopaque, archived: c_int) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_session_archive: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order) orelse return @intFromEnum(err(.invalid_arg, "da_session_archive: null order handle"));
    const db_id = if (findOrder(st, order_id)) |rec| (rec.db_id orelse rec.id) else order_id;
    const want_archived = archived != 0;
    const s = st.sessions orelse return @intFromEnum(err(.internal, "da_session_archive: no session store"));

    s.archiveSessionFn(db_id, want_archived) catch return @intFromEnum(err(.internal, "No se pudo archivar o restaurar la sesión"));
    return @intFromEnum(ok());
}

/// recuento sin modificar datos para la confirmación de la cabina.
pub export fn da_session_archive_before_preview(handle: ?*anyopaque, before_secs: i64, out_count: *c_int) callconv(.c) c_int {
    if (handle == null or before_secs <= 0) return @intFromEnum(err(.invalid_arg, "Falta el motor o la fecha de corte"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const s = st.sessions orelse return @intFromEnum(err(.internal, "No hay almacén de sesiones"));
    const count = s.previewArchiveBeforeFn(before_secs) catch return @intFromEnum(err(.internal, "No se pudo contar el historial anterior"));
    out_count.* = @intCast(@min(count, std.math.maxInt(c_int)));
    return @intFromEnum(ok());
}

/// API nueva de esta tanda. Exige el recuento confirmado; la
/// comparación ocurre en la misma transacción que archiva los hilos completos.
pub export fn da_session_archive_before(handle: ?*anyopaque, before_secs: i64, expected_count: c_int, out_archived: *c_int) callconv(.c) c_int {
    if (handle == null or before_secs <= 0 or expected_count < 0) return @intFromEnum(err(.invalid_arg, "Falta el motor, la fecha o el recuento confirmado"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const s = st.sessions orelse return @intFromEnum(err(.internal, "No hay almacén de sesiones"));
    const moved = s.archiveBeforeCheckedFn(before_secs, expected_count) catch |e| return @intFromEnum(if (e == error.ArchiveChanged)
        err(.invalid_state, "El historial cambió. Revisa el recuento y confirma de nuevo.")
    else
        err(.internal, "No se pudo archivar el historial anterior"));
    out_archived.* = @intCast(@min(moved, std.math.maxInt(c_int)));
    return @intFromEnum(ok());
}

fn deriveTitle(allocator: std.mem.Allocator, text: []const u8) ![]const u8 {
    const trimmed = std.mem.trim(u8, text, " \t\r\n");
    const limit: usize = 60;
    if (trimmed.len <= limit) return allocator.dupe(u8, trimmed);
    // No cortar UTF-8 a la mitad
    var end: usize = limit;
    while (end > 0) : (end -= 1) {
        if ((trimmed[end] & 0xc0) != 0x80) break;
    }
    if (end == 0) end = limit;
    const base = trimmed[0..end];
    const suffix = "…";
    const result = try allocator.alloc(u8, base.len + suffix.len);
    @memcpy(result[0..base.len], base);
    @memcpy(result[base.len..], suffix);
    return result;
}

pub export fn da_plan_get_json(handle: ?*anyopaque, order: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_plan_get_json: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order) orelse return @intFromEnum(err(.invalid_arg, "da_plan_get_json: null order handle"));

    const rec = findOrder(st, order_id) orelse return @intFromEnum(err(.not_found, "da_plan_get_json: order not found"));
    if (rec.outcome) |*outcome| {
        const aa = st.arena.child_allocator;
        const plan_json = planToJson(aa, &outcome.plan) catch return @intFromEnum(err(.oom, "da_plan_get_json: OOM serializing plan"));
        defer aa.free(plan_json);
        const with_mode = std.fmt.allocPrint(aa, "{s},\"wait_for_plan_approval\":{s}}}", .{ plan_json[0 .. plan_json.len - 1], if (rec.wait_for_plan_approval) "true" else "false" }) catch return @intFromEnum(err(.oom, "da_plan_get_json: OOM serializing mode"));
        defer aa.free(with_mode);
        out_json.* = ownedCStr(with_mode) orelse return @intFromEnum(err(.oom, "da_plan_get_json: OOM"));
        return @intFromEnum(ok());
    }

    // El borde C entrega [*:0]u8: la cadena DEBE terminar en NUL o el consumidor
    // (QString::fromUtf8/strlen) lee fuera del buffer → basura o crash intermitente.
    // ownedCStr garantiza terminador + propiedad del caller (c_allocator).
    if (rec.status == .clarifying) {
        // D8: el contrato es el objeto plan ({understanding, needs_clarification,
        // questions:[{id,text,options}]}), no el array de preguntas pelado — con
        // el array la UI nunca entraba en fase clarifying y el formulario de
        // respuestas era inalcanzable desde la cabina.
        const payload: []const u8 = if (rec.outcome) |*o|
            (planToJson(st.arena.child_allocator, &o.plan) catch null) orelse "{\"needs_clarification\":true,\"questions\":[]}"
        else
            "{\"needs_clarification\":true,\"questions\":[]}";
        out_json.* = ownedCStr(payload) orelse return @intFromEnum(err(.oom, "da_plan_get_json: OOM"));
        return @intFromEnum(ok());
    }

    if (rec.plan_json) |json| {
        out_json.* = ownedCStr(json) orelse return @intFromEnum(err(.oom, "da_plan_get_json: OOM"));
        return @intFromEnum(ok());
    }

    return @intFromEnum(err(.invalid_state, "da_plan_get_json: no plan available"));
}

