pub export fn da_health_probe_all_json(handle: ?*anyopaque, max_models: c_int, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_health_probe_all_json: null handle"));
    if (max_models < 0) return @intFromEnum(err(.invalid_arg, "da_health_probe_all_json: max_models must be non-negative"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    const limit: usize = if (max_models > 0) @intCast(max_models) else 0;
    const summary = runActiveHealthProbeAll(st, limit, st.db_conn);

    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginObject() catch return @intFromEnum(err(.oom, "da_health_probe_all_json: OOM"));
    js.objectField("candidates") catch return @intFromEnum(err(.oom, "da_health_probe_all_json: OOM"));
    js.write(summary.candidates) catch return @intFromEnum(err(.oom, "da_health_probe_all_json: OOM"));
    js.objectField("probed") catch return @intFromEnum(err(.oom, "da_health_probe_all_json: OOM"));
    js.write(summary.probed) catch return @intFromEnum(err(.oom, "da_health_probe_all_json: OOM"));
    js.objectField("ok") catch return @intFromEnum(err(.oom, "da_health_probe_all_json: OOM"));
    js.write(summary.ok) catch return @intFromEnum(err(.oom, "da_health_probe_all_json: OOM"));
    js.objectField("failed") catch return @intFromEnum(err(.oom, "da_health_probe_all_json: OOM"));
    js.write(summary.failed) catch return @intFromEnum(err(.oom, "da_health_probe_all_json: OOM"));
    js.objectField("skipped") catch return @intFromEnum(err(.oom, "da_health_probe_all_json: OOM"));
    js.write(summary.skipped) catch return @intFromEnum(err(.oom, "da_health_probe_all_json: OOM"));
    js.objectField("disabled_not_found") catch return @intFromEnum(err(.oom, "da_health_probe_all_json: OOM"));
    js.write(summary.disabled_not_found) catch return @intFromEnum(err(.oom, "da_health_probe_all_json: OOM"));
    js.endObject() catch return @intFromEnum(err(.oom, "da_health_probe_all_json: OOM"));
    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_health_probe_all_json: OOM"));
    return @intFromEnum(ok());
}

/// MATRIZ-SONDEO (E1.32): mide EN VIVO tool_calls / structured_output /
/// reasoning de un (provider, model) y persiste lo medido en
/// discovery_snapshots_v2 con provenance 'live_probe'. Devuelve
/// {provider,model,status,tool_calls,structured_output,reasoning}; los
/// valores de celda son "yes"|"no"|"not_probed" — un fallo de auth/red
/// nunca mide capacidad del modelo. El caller libera con da_string_free.
pub export fn da_capability_probe_json(handle: ?*anyopaque, provider: [*:0]const u8, model: [*:0]const u8, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_capability_probe_json: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    const provider_s = std.mem.span(provider);
    const model_s = std.mem.span(model);
    const result = live_worker.probeModelCapabilities(aa, st.catalog_path, st.db_conn, provider_s, model_s) orelse {
        // initForced no encontró el par: no se midió nada — respuesta honesta.
        const empty = std.fmt.allocPrint(
            aa,
            "{{\"provider\":\"{s}\",\"model\":\"{s}\",\"status\":\"skipped\",\"tool_calls\":\"not_probed\",\"structured_output\":\"not_probed\",\"reasoning\":\"not_probed\"}}",
            .{ provider_s, model_s },
        ) catch return @intFromEnum(err(.oom, "da_capability_probe_json: OOM"));
        out_json.* = ownedCStr(empty) orelse return @intFromEnum(err(.oom, "da_capability_probe_json: OOM"));
        return @intFromEnum(ok());
    };
    const j = std.fmt.allocPrint(
        aa,
        "{{\"provider\":\"{s}\",\"model\":\"{s}\",\"status\":\"{s}\",\"tool_calls\":\"{s}\",\"structured_output\":\"{s}\",\"reasoning\":\"{s}\"}}",
        .{ provider_s, model_s, result.status.toString(), result.tool_calls, result.structured_output, result.reasoning },
    ) catch return @intFromEnum(err(.oom, "da_capability_probe_json: OOM"));
    out_json.* = ownedCStr(j) orelse return @intFromEnum(err(.oom, "da_capability_probe_json: OOM"));
    return @intFromEnum(ok());
}

/// Proveedores, claves (sin el texto cifrado) y modelos del catálogo como JSON.
pub export fn da_vision_probe_json(handle: ?*anyopaque, provider: [*:0]const u8, model: [*:0]const u8, out_json: *?[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "vision_probe: null core"));
    const p = std.mem.span(provider);
    const m = std.mem.span(model);
    if (p.len == 0 or p.len > 256 or m.len == 0 or m.len > 512 or !std.unicode.utf8ValidateSlice(p) or !std.unicode.utf8ValidateSlice(m))
        return @intFromEnum(err(.invalid_arg, "vision_probe: proveedor/modelo invalido"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const a = st.arena.child_allocator;
    const probe = live_worker.probeModelVision(a, st.catalog_path, st.db_conn, p, m);
    const result = .{
        .provider = p,
        .model = m,
        .status = if (probe) |r| r.status.toString() else "skipped",
        .cap_vision_status = if (probe) |r| r.vision else "not_probed",
        .reason = if (probe) |r| r.reason else "modelo ausente, sin clave o no elegible: solo nube gratuita",
    };
    const json = std.json.Stringify.valueAlloc(a, result, .{}) catch return @intFromEnum(err(.oom, "vision_probe: OOM"));
    defer a.free(json);
    out_json.* = ownedCStr(json) orelse return @intFromEnum(err(.oom, "vision_probe: OOM"));
    return @intFromEnum(ok());
}

/// Proveedores, claves (sin el texto cifrado) y modelos del catálogo como JSON.
/// El caller libera con da_string_free.
fn writeModelVisionFields(js: *std.json.Stringify, catalog: db.Connection, provider: []const u8, model: []const u8) !void {
    const stmt = try catalog.prepare(
        \\SELECT cap_vision_status,cap_vision_provenance,metadata_updated_at
        \\FROM discovery_snapshots_v2 WHERE provider=? AND (model_id=? OR model_id=? || '/' || ?)
        \\ORDER BY (model_id=?) DESC LIMIT 1
    );
    defer catalog.finalize(stmt);
    try db.bindText(stmt, 1, provider);
    try db.bindText(stmt, 2, model);
    try db.bindText(stmt, 3, provider);
    try db.bindText(stmt, 4, model);
    try db.bindText(stmt, 5, model);
    const rc = db.c.sqlite3_step(stmt);
    if (rc != db.c.SQLITE_ROW and rc != db.c.SQLITE_DONE) return error.StepFailed;
    inline for (.{ "cap_vision_status", "cap_vision_provenance", "cap_vision_updated_at" }, 0..) |field, index| {
        try js.objectField(field);
        try js.write(if (rc == db.c.SQLITE_ROW) std.mem.span(db.c.sqlite3_column_text(stmt, index)) else "not_probed");
    }
}

pub export fn da_providers_list_json(handle: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_providers_list_json: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_providers_list_json: OOM"));
        return @intFromEnum(ok());
    };

    // GOBERNANZA-CATALOGO: se lista TODO proveedor conocido (para poder reactivarlo con
    // una clave nueva), pero ahora se expone `enabled` para que la UI distinga un
    // proveedor "sin clave/deshabilitado" de uno activo — antes ambos se veían idénticos.
    const prov_stmt = st.catalog.db.prepare("SELECT id, name, base_url, api_style, is_free_tier, enabled, is_local FROM providers ORDER BY name") catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_providers_list_json: OOM"));
        return @intFromEnum(ok());
    };
    defer st.catalog.db.finalize(prov_stmt);

    while (db.c.sqlite3_step(prov_stmt) == db.c.SQLITE_ROW) {
        const prov_id = db.c.sqlite3_column_int64(prov_stmt, 0);
        const prov_name = std.mem.span(db.c.sqlite3_column_text(prov_stmt, 1));
        const base_url = std.mem.span(db.c.sqlite3_column_text(prov_stmt, 2));
        const api_style = std.mem.span(db.c.sqlite3_column_text(prov_stmt, 3));
        const is_free_tier = db.c.sqlite3_column_int(prov_stmt, 4) != 0;
        const enabled = db.c.sqlite3_column_int(prov_stmt, 5) != 0;
        // MODELO-LOCAL: la UI necesita saber qué proveedores corren en la
        // máquina para mostrar la política conservadora (sin enjambre
        // automático, inferencias en secuencia).
        const is_local = db.c.sqlite3_column_int(prov_stmt, 6) != 0;

        js.beginObject() catch continue;
        js.objectField("name") catch continue;
        js.write(prov_name) catch continue;
        js.objectField("base_url") catch continue;
        js.write(base_url) catch continue;
        js.objectField("api_style") catch continue;
        js.write(api_style) catch continue;
        js.objectField("is_free_tier") catch continue;
        js.write(is_free_tier) catch continue;
        js.objectField("enabled") catch continue;
        js.write(enabled) catch continue;
        js.objectField("local") catch continue;
        js.write(is_local) catch continue;

        js.objectField("keys") catch continue;
        js.beginArray() catch continue;
        const key_stmt = st.catalog.db.prepare("SELECT label, status, quota_limit, quota_used FROM api_keys WHERE provider_id = ? ORDER BY id") catch continue;
        defer st.catalog.db.finalize(key_stmt);
        db.bindInt(key_stmt, 1, prov_id) catch continue;
        while (db.c.sqlite3_step(key_stmt) == db.c.SQLITE_ROW) {
            js.beginObject() catch continue;
            js.objectField("label") catch continue;
            js.write(std.mem.span(db.c.sqlite3_column_text(key_stmt, 0))) catch continue;
            js.objectField("status") catch continue;
            js.write(std.mem.span(db.c.sqlite3_column_text(key_stmt, 1))) catch continue;
            js.objectField("quota_limit") catch continue;
            js.write(db.c.sqlite3_column_int64(key_stmt, 2)) catch continue;
            js.objectField("quota_used") catch continue;
            js.write(db.c.sqlite3_column_int64(key_stmt, 3)) catch continue;
            js.endObject() catch continue;
        }
        js.endArray() catch continue;

        js.objectField("models") catch continue;
        js.beginArray() catch continue;
        // is_favorite lo decide la curaduria automatica del router; se expone
        // para que la tabla del catalogo pueda mostrarlo. Es de SOLO LECTURA:
        // no hay ninguna funcion en esta API para que el usuario lo cambie.
        const model_stmt = st.catalog.db.prepare("SELECT model_name, context_window, is_free, available, is_favorite FROM models WHERE provider_id = ? ORDER BY is_favorite DESC, model_name") catch continue;
        defer st.catalog.db.finalize(model_stmt);
        db.bindInt(model_stmt, 1, prov_id) catch continue;
        while (db.c.sqlite3_step(model_stmt) == db.c.SQLITE_ROW) {
            js.beginObject() catch continue;
            js.objectField("name") catch continue;
            js.write(std.mem.span(db.c.sqlite3_column_text(model_stmt, 0))) catch continue;
            js.objectField("context_window") catch continue;
            js.write(db.c.sqlite3_column_int64(model_stmt, 1)) catch continue;
            const raw_is_free = db.c.sqlite3_column_int(model_stmt, 2) != 0;
            const effective_is_free = raw_is_free and
                (!std.ascii.eqlIgnoreCase(prov_name, "OpenCode") or
                    model_roster.isOpenCodeKnownFree(std.mem.span(db.c.sqlite3_column_text(model_stmt, 0))));
            js.objectField("is_free") catch continue;
            js.write(effective_is_free) catch continue;
            js.objectField("available") catch continue;
            js.write(db.c.sqlite3_column_int(model_stmt, 3) != 0) catch continue;
            js.objectField("is_favorite") catch continue;
            js.write(db.c.sqlite3_column_int(model_stmt, 4) != 0) catch continue;
            // S4: ¿sirve este modelo para generar TEXTO? El desplegable de modelo de la
            // cabina ofrecía `imagen-4.0`, `veo-3.1`, `lyria-3`, los `rerank-*` y los de
            // embeddings como si el agente pudiera trabajar con ellos. El router ya los
            // excluye (`isNonTextGenModel`), pero el usuario podía fijarlos a mano y
            // condenar la orden. Se publica el flag en vez de duplicar la lista de
            // patrones en TypeScript: una sola fuente de verdad, la del motor.
            writeModelVisionFields(&js, st.catalog.db, prov_name, std.mem.span(db.c.sqlite3_column_text(model_stmt, 0))) catch |e|
                return @intFromEnum(err(.internal, @errorName(e)));
            js.objectField("text_gen") catch continue;
            js.write(!model_router.isNonTextGenModel(std.mem.span(db.c.sqlite3_column_text(model_stmt, 0)))) catch continue;
            js.endObject() catch continue;
        }
        js.endArray() catch continue;
        js.endObject() catch continue;
    }
    js.endArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_providers_list_json: OOM"));
        return @intFromEnum(ok());
    };
    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_providers_list_json: OOM"));
    return @intFromEnum(ok());
}

/// Info del catálogo cargado: ruta absoluta y conteos. NUNCA incluye claves en claro.
/// Devuelve objeto JSON {catalog_path_abs, model_count, provider_count, key_count}.
/// El caller libera con da_string_free.
pub export fn da_catalog_info_json(handle: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_catalog_info_json: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    // Resolver ruta absoluta del catalog_path (Windows).
    var absBuf: [4096]u8 = undefined;
    absBuf[0] = 0;
    const absLen = GetFullPathNameA(st.catalog_path.ptr, 4096, @as([*:0]u8, @ptrCast(&absBuf[0])), null);
    const absPath: [:0]const u8 = if (absLen > 0 and absLen < 4096) blk: {
        absBuf[absLen] = 0;
        break :blk absBuf[0..absLen :0];
    } else st.catalog_path;

    var model_count: i64 = 0;
    var provider_count: i64 = 0;
    var key_count: i64 = 0;

    // GOBERNANZA-CATALOGO: conteos de lo REALMENTE usable, no un COUNT(*) bruto histórico.
    // Antes esto contaba TODAS las filas de siempre (proveedores/modelos deshabilitados o
    // sin clave incluidos) — el número mostrado en la UI nunca bajaba tras quitar claves o
    // proveedores comprometidos, dando la falsa impresión de que "Refrescar catálogo" no
    // hacía nada. model_count exige provider habilitado Y modelo disponible; provider_count
    // solo cuenta habilitados; key_count solo claves activas (no rotated/exhausted).
    const count_stmt = st.catalog.db.prepare(
        \\SELECT
        \\  (SELECT COUNT(*) FROM models m JOIN providers p ON m.provider_id = p.id WHERE p.enabled = 1 AND m.available = 1),
        \\  (SELECT COUNT(*) FROM providers WHERE enabled = 1),
        \\  (SELECT COUNT(*) FROM api_keys WHERE status = 'active')
    ) catch null;
    if (count_stmt) |stmt| {
        defer st.catalog.db.finalize(stmt);
        if (db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW) {
            model_count = db.c.sqlite3_column_int64(stmt, 0);
            provider_count = db.c.sqlite3_column_int64(stmt, 1);
            key_count = db.c.sqlite3_column_int64(stmt, 2);
        }
    }

    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginObject() catch {
        out_json.* = ownedCStr("{\"catalog_path_abs\":\"\",\"model_count\":0,\"provider_count\":0,\"key_count\":0}") orelse return @intFromEnum(err(.oom, "da_catalog_info_json: OOM"));
        return @intFromEnum(ok());
    };
    js.objectField("catalog_path_abs") catch {};
    js.write(absPath) catch {};
    js.objectField("model_count") catch {};
    js.write(model_count) catch {};
    js.objectField("provider_count") catch {};
    js.write(provider_count) catch {};
    js.objectField("key_count") catch {};
    js.write(key_count) catch {};
    js.endObject() catch {};

    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_catalog_info_json: OOM"));
    return @intFromEnum(ok());
}

/// PIXEL-DEVTEAM-05: registro unificado de especialistas (5 nativos + dev-team de
/// Pixel Enterprise) y sus divisiones. Permite a la GUI y a un auditor OBSERVAR el
/// equipo importado. Objeto JSON:
///   {"specialists":[{name,department,source,task_types:[...],model_hint,description}],
///    "divisions":[{id,name,emoji,room_id,agent_ids:[...]}]}
/// `source` es "native" o "pixel". `model_hint` es string o null. El caller libera
/// con da_string_free. NUNCA incluye claves ni secretos.
pub export fn da_specialists_json(handle: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_specialists_json: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };

    js.beginObject() catch {
        out_json.* = ownedCStr("{\"specialists\":[],\"divisions\":[]}") orelse return @intFromEnum(err(.oom, "da_specialists_json: OOM"));
        return @intFromEnum(ok());
    };
    js.objectField("specialists") catch {};
    js.beginArray() catch {};
    if (st.registry) |*reg| {
        for (reg.specialists) |s| {
            js.beginObject() catch {};
            js.objectField("name") catch {};
            js.write(s.name) catch {};
            js.objectField("department") catch {};
            js.write(s.department) catch {};
            js.objectField("source") catch {};
            js.write(switch (s.source) {
                .native => "native",
                .pixel => "pixel",
            }) catch {};
            js.objectField("task_types") catch {};
            js.beginArray() catch {};
            for (s.task_types) |tt| js.write(tt.toText()) catch {};
            js.endArray() catch {};
            js.objectField("model_hint") catch {};
            if (s.model_hint) |m| {
                js.write(m) catch {};
            } else {
                js.write(null) catch {};
            }
            js.objectField("description") catch {};
            js.write(s.description) catch {};
            js.endObject() catch {};
        }
    }
    js.endArray() catch {};

    js.objectField("divisions") catch {};
    js.beginArray() catch {};
    if (st.registry) |*reg| {
        for (reg.divisions) |d| {
            js.beginObject() catch {};
            js.objectField("id") catch {};
            js.write(d.id) catch {};
            js.objectField("name") catch {};
            js.write(d.name) catch {};
            js.objectField("emoji") catch {};
            js.write(d.emoji) catch {};
            js.objectField("room_id") catch {};
            js.write(d.room_id) catch {};
            js.objectField("agent_ids") catch {};
            js.beginArray() catch {};
            for (d.agent_ids) |a| js.write(a) catch {};
            js.endArray() catch {};
            js.endObject() catch {};
        }
    }
    js.endArray() catch {};
    js.endObject() catch {};

    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_specialists_json: OOM"));
    return @intFromEnum(ok());
}

/// Candidatos del router para una tarea: score, why=, free/paid, health factor.
/// `task_type`: texto de la taxonomía (planificar, programar, auditar...).
/// Devuelve array JSON [{provider,model,score,is_free,reason}].
pub export fn da_router_candidates_json(handle: ?*anyopaque, task_type: [*:0]const u8, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_router_candidates_json: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    const tt_str = std.mem.span(task_type);
    const tt = parseTaskType(tt_str) orelse .programar;

    const now = health.nowSeconds(st.db_conn);
    // FIX-ENGINE-8: null ledger — los writes de audit se serializan via ledger_mutex.
    var router = model_router.Router.init(aa, st.catalog.db, null, now);
    router.setHealthConn(st.db_conn);

    var candidates = router.rankCandidates(.{ .task_type = tt, .required_context = 8000 }) catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_router_candidates_json: OOM"));
        return @intFromEnum(ok());
    };
    defer {
        for (candidates.items) |c| c.deinit(aa);
        candidates.deinit(aa);
    }

    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_router_candidates_json: OOM"));
        return @intFromEnum(ok());
    };
    for (candidates.items) |c| {
        js.beginObject() catch continue;
        js.objectField("provider") catch continue;
        js.write(c.provider_name) catch continue;
        js.objectField("model") catch continue;
        js.write(c.model_name) catch continue;
        js.objectField("score") catch continue;
        js.write(c.score) catch continue;
        js.objectField("is_free") catch continue;
        js.write(c.is_free) catch continue;
        js.objectField("reason") catch continue;
        js.write(c.reason) catch continue;
        js.endObject() catch continue;
    }
    js.endArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_router_candidates_json: OOM"));
        return @intFromEnum(ok());
    };
    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_router_candidates_json: OOM"));
    return @intFromEnum(ok());
}

/// P10-T3: Scores reales de calidad por modelo+task_type desde catalog.db.
/// Devuelve array JSON [{model,provider,task_type,score,samples,updated_at}].
pub export fn da_model_scores_json(handle: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_model_scores_json: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_model_scores_json: OOM"));
        return @intFromEnum(ok());
    };

    const stmt = st.catalog.db.prepare("SELECT m.model_name, p.name, ms.task_type, ms.score, ms.sample_count, ms.updated_at FROM model_scores ms JOIN models m ON ms.model_id = m.id JOIN providers p ON m.provider_id = p.id ORDER BY ms.score DESC") catch null;
    if (stmt) |s| {
        defer st.catalog.db.finalize(s);
        while (db.c.sqlite3_step(s) == db.c.SQLITE_ROW) {
            js.beginObject() catch continue;
            js.objectField("model") catch continue;
            const mptr = db.c.sqlite3_column_text(s, 0);
            const mlen = db.c.sqlite3_column_bytes(s, 0);
            js.write(if (mptr != null) mptr[0..@intCast(mlen)] else "") catch continue;
            js.objectField("provider") catch continue;
            const pptr = db.c.sqlite3_column_text(s, 1);
            const plen = db.c.sqlite3_column_bytes(s, 1);
            js.write(if (pptr != null) pptr[0..@intCast(plen)] else "") catch continue;
            js.objectField("task_type") catch continue;
            const tptr = db.c.sqlite3_column_text(s, 2);
            const tlen = db.c.sqlite3_column_bytes(s, 2);
            js.write(if (tptr != null) tptr[0..@intCast(tlen)] else "") catch continue;
            js.objectField("score") catch continue;
            js.write(db.c.sqlite3_column_double(s, 3)) catch continue;
            js.objectField("samples") catch continue;
            js.write(db.c.sqlite3_column_int64(s, 4)) catch continue;
            js.objectField("updated_at") catch continue;
            js.write(db.c.sqlite3_column_int64(s, 5)) catch continue;
            js.endObject() catch continue;
        }
    }

    js.endArray() catch {};
    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_model_scores_json: OOM"));
    return @intFromEnum(ok());
}

/// Filas ESCALATION del ledger append-only (auditoría de escaladas a pago).
/// Devuelve array JSON [{ts,model_id,provider,justification}].
pub export fn da_ledger_escalations_json(handle: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_ledger_escalations_json: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    // FIX-ENGINE-9: drenar cola de audit pendiente antes de leer.
    flushAuditQueue(st);

    // FIX-ENGINE-8: serializar lectura de ledger.db con ledger_mutex.
    st.ledger_mutex.lock();
    defer st.ledger_mutex.unlock();
    const stmt = st.ledger.prepare("SELECT ts, model_id, provider, notes FROM audit_ledger WHERE action='ESCALATION' ORDER BY ts DESC") catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_ledger_escalations_json: OOM"));
        return @intFromEnum(ok());
    };
    defer st.ledger.finalize(stmt);

    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_ledger_escalations_json: OOM"));
        return @intFromEnum(ok());
    };
    while (db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW) {
        js.beginObject() catch continue;
        js.objectField("ts") catch continue;
        js.write(db.c.sqlite3_column_int64(stmt, 0)) catch continue;
        js.objectField("model_id") catch continue;
        js.write(db.c.sqlite3_column_int64(stmt, 1)) catch continue;
        js.objectField("provider") catch continue;
        js.write(std.mem.span(db.c.sqlite3_column_text(stmt, 2))) catch continue;
        js.objectField("justification") catch continue;
        js.write(std.mem.span(db.c.sqlite3_column_text(stmt, 3))) catch continue;
        js.endObject() catch continue;
    }
    js.endArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_ledger_escalations_json: OOM"));
        return @intFromEnum(ok());
    };
    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_ledger_escalations_json: OOM"));
    return @intFromEnum(ok());
}

/// Lista TODAS las acciones del audit_ledger (no solo ESCALATION).
/// Devuelve array JSON [{ts,subject_kind,subject_id,action,verdict,model_id,provider,evidence_ref,notes}].
/// Ordenado por ts DESC, límite 200 filas.
pub export fn da_audit_ledger_json(handle: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_audit_ledger_json: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    // FIX-ENGINE-9: drenar cola de audit pendiente antes de leer.
    flushAuditQueue(st);

    // FIX-ENGINE-8: serializar lectura de ledger.db con ledger_mutex.
    st.ledger_mutex.lock();
    defer st.ledger_mutex.unlock();
    const stmt = st.ledger.prepare("SELECT ts, subject_kind, subject_id, action, verdict, model_id, provider, evidence_ref, notes, COALESCE(order_id,0) FROM audit_ledger ORDER BY id DESC LIMIT 200") catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_audit_ledger_json: OOM"));
        return @intFromEnum(ok());
    };
    defer st.ledger.finalize(stmt);

    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_audit_ledger_json: OOM"));
        return @intFromEnum(ok());
    };
    while (db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW) {
        js.beginObject() catch continue;
        js.objectField("ts") catch continue;
        js.write(db.c.sqlite3_column_int64(stmt, 0)) catch continue;
        js.objectField("subject_kind") catch continue;
        js.write(std.mem.span(db.c.sqlite3_column_text(stmt, 1))) catch continue;
        js.objectField("subject_id") catch continue;
        js.write(db.c.sqlite3_column_int64(stmt, 2)) catch continue;
        js.objectField("action") catch continue;
        js.write(std.mem.span(db.c.sqlite3_column_text(stmt, 3))) catch continue;
        js.objectField("verdict") catch continue;
        js.write(std.mem.span(db.c.sqlite3_column_text(stmt, 4))) catch continue;
        js.objectField("model_id") catch continue;
        // model_id es TEXT (nombre del modelo, p.ej. "deepseek-v4"); leerlo como
        // int64 exportaba siempre 0 y escondía quién firmó cada asiento.
        {
            const model_ptr = db.c.sqlite3_column_text(stmt, 5);
            js.write(if (model_ptr != null) std.mem.span(model_ptr) else "") catch continue;
        }
        js.objectField("provider") catch continue;
        js.write(std.mem.span(db.c.sqlite3_column_text(stmt, 6))) catch continue;
        js.objectField("evidence_ref") catch continue;
        js.write(std.mem.span(db.c.sqlite3_column_text(stmt, 7))) catch continue;
        js.objectField("notes") catch continue;
        const notes_ptr = db.c.sqlite3_column_text(stmt, 8);
        if (notes_ptr != null) {
            js.write(std.mem.span(notes_ptr)) catch continue;
        } else {
            js.write("") catch continue;
        }
        js.objectField("order_id") catch continue;
        js.write(db.c.sqlite3_column_int64(stmt, 9)) catch continue;
        js.endObject() catch continue;
    }
    js.endArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_audit_ledger_json: OOM"));
        return @intFromEnum(ok());
    };
    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_audit_ledger_json: OOM"));
    return @intFromEnum(ok());
}

/// AUDIT-INDEP: estado de checklist DERIVADO del audit_ledger por subject.
/// Antes `audit_pipeline.deriveStatus` era código muerto (solo tests). Aquí la
/// máquina de estados (pending→built→audited→verified|reopened) se calcula
/// sobre las filas reales del ledger con verificación de la cadena de hashes.
/// Devuelve [{subject_kind,subject_id,status,builder,auditors[]}] — status
/// "chain_broken" cuando la cadena no verifica (ledger manipulado: nada
/// certifica). Solo-lectura; el caller libera con da_string_free.
pub export fn da_audit_checklist_json(handle: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_audit_checklist_json: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    // Drenar la cola antes de derivar: las marcas del dispatch en curso deben
    // estar asentadas para que el estado refleje la realidad.
    flushAuditQueue(st);

    st.ledger_mutex.lock();
    defer st.ledger_mutex.unlock();

    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };

    const subjects = audit_pipeline.deriveAllSubjects(st.ledger, aa) catch |e| {
        if (e == error.HashChainBroken) {
            // Ledger manipulado o corrupto: el reporte honesto es la ruptura,
            // no un estado fingido.
            js.beginArray() catch {};
            js.beginObject() catch {};
            js.objectField("status") catch {};
            js.write("chain_broken") catch {};
            js.endObject() catch {};
            js.endArray() catch {};
            out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_audit_checklist_json: OOM"));
            return @intFromEnum(ok());
        }
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_audit_checklist_json: OOM"));
        return @intFromEnum(ok());
    };
    defer {
        for (subjects) |*s| s.deinit(aa);
        aa.free(subjects);
    }

    js.beginArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_audit_checklist_json: OOM"));
        return @intFromEnum(ok());
    };
    for (subjects) |s| {
        js.beginObject() catch continue;
        js.objectField("subject_kind") catch continue;
        js.write(s.subject_kind) catch continue;
        js.objectField("subject_id") catch continue;
        js.write(s.subject_id) catch continue;
        js.objectField("order_id") catch continue;
        js.write(s.order_id) catch continue;
        js.objectField("status") catch continue;
        js.write(s.status.toText()) catch continue;
        js.objectField("builder") catch continue;
        js.write(s.builder orelse "") catch continue;
        js.objectField("auditors") catch continue;
        js.beginArray() catch continue;
        for (s.auditors) |m| js.write(m) catch continue;
        js.endArray() catch continue;
        js.endObject() catch continue;
    }
    js.endArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_audit_checklist_json: OOM"));
        return @intFromEnum(ok());
    };
    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_audit_checklist_json: OOM"));
    return @intFromEnum(ok());
}

/// CHECKLIST.md parseado a JSON: array de objetos {status, text, marks[]}.
/// Lee el archivo del filesystem (repo root). Solo-lectura.
pub export fn da_checklist_json(handle: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    _ = handle;
    const allocator = std.heap.page_allocator;
    const candidates = [_][]const u8{
        "docs/historia/CHECKLIST.md", "../docs/historia/CHECKLIST.md", "../../docs/historia/CHECKLIST.md",
        "CHECKLIST.md",               "../CHECKLIST.md",               "../../CHECKLIST.md",
        "../../../CHECKLIST.md",
    };
    var found: ?[]u8 = null;
    for (candidates) |candidate| {
        found = readFileBounded(allocator, candidate, 2 * 1024 * 1024) catch |e| switch (e) {
            error.NotFound => continue,
            error.TooLarge => {
                out_json.* = ownedCStr("{\"error\":\"CHECKLIST.md demasiado grande\"}") orelse return @intFromEnum(err(.oom, "da_checklist_json: OOM"));
                return @intFromEnum(ok());
            },
            error.ReadFailed => {
                out_json.* = ownedCStr("{\"error\":\"CHECKLIST.md lectura incompleta\"}") orelse return @intFromEnum(err(.oom, "da_checklist_json: OOM"));
                return @intFromEnum(ok());
            },
            error.OutOfMemory => {
                out_json.* = ownedCStr("{\"error\":\"CHECKLIST.md no se puede leer\"}") orelse return @intFromEnum(err(.oom, "da_checklist_json: OOM"));
                return @intFromEnum(ok());
            },
        };
        break;
    }
    const content = found orelse {
        out_json.* = ownedCStr("{\"error\":\"CHECKLIST.md no encontrado\"}") orelse return @intFromEnum(err(.oom, "da_checklist_json: OOM"));
        return @intFromEnum(ok());
    };
    defer allocator.free(content);

    var out: std.Io.Writer.Allocating = .init(allocator);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_checklist_json: OOM"));
        return @intFromEnum(ok());
    };

    var it = std.mem.splitScalar(u8, content, '\n');
    while (it.next()) |line| {
        const trimmed = std.mem.trim(u8, line, " \t\r\n");
        if (trimmed.len < 5) continue;
        if (!std.mem.startsWith(u8, trimmed, "- [")) continue;
        const close = std.mem.indexOf(u8, trimmed, "]");
        if (close == null or close.? < 3) continue;
        const status = trimmed[3..close.?];
        const rest = std.mem.trim(u8, trimmed[close.? + 1 ..], " \t");

        js.beginObject() catch continue;
        js.objectField("status") catch continue;
        js.write(status) catch continue;
        js.objectField("text") catch continue;
        js.write(rest) catch continue;
        js.objectField("raw") catch continue;
        js.write(trimmed) catch continue;
        js.endObject() catch continue;
    }

    js.endArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_checklist_json: OOM"));
        return @intFromEnum(ok());
    };
    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_checklist_json: OOM"));
    return @intFromEnum(ok());
}

/// H7 r4: true si la ruta es UNC. Vive en mounts.zig, junto al
/// validador de raíces nuevas de la CLI (QA-A H8), para no duplicarla.
const mountPathIsUnc = mounts.pathIsUnc;

/// Componentes normalizados de una ruta Windows (patrón de `Sandbox.normalize`):
/// cualquier separador, segmentos vacíos y `.` fuera, `..` sube un nivel y nunca
/// por encima de la raíz. La comparación posterior es insensible a mayúsculas,
/// que es como resuelve Windows.
fn mountPathComponents(allocator: std.mem.Allocator, path: []const u8) ![][]const u8 {
    var stack: std.ArrayList([]const u8) = .empty;
    errdefer mountPathComponentsFree(allocator, stack.toOwnedSlice(allocator) catch &.{});
    var it = std.mem.tokenizeAny(u8, path, "/\\");
    while (it.next()) |seg| {
        if (seg.len == 0 or std.mem.eql(u8, seg, ".")) continue;
        if (std.mem.eql(u8, seg, "..")) {
            if (stack.items.len > 0) {
                const popped = stack.pop();
                if (popped) |p| allocator.free(p);
            }
            continue;
        }
        const owned = try allocator.dupe(u8, seg);
        errdefer allocator.free(owned);
        try stack.append(allocator, owned);
    }
    return stack.toOwnedSlice(allocator);
}

fn mountPathComponentsFree(allocator: std.mem.Allocator, comps: [][]const u8) void {
    for (comps) |c| allocator.free(c);
    allocator.free(comps);
}

/// `wanted` es descendiente de `root` por componentes, ignorando caja.
fn mountWithin(wanted: []const []const u8, root: []const []const u8) bool {
    if (wanted.len < root.len) return false;
    for (root, 0..) |comp, i| {
        if (!std.ascii.eqlIgnoreCase(comp, wanted[i])) return false;
    }
    return true;
}

/// H7 r4: destino efectivo de `path` —el que resuelven los
/// reparse points (junction/symlink) si la ruta existe, o el ancestro existente
/// más cercano si no. Devuelve null si no existe nada de la ruta (el llamador
/// posee el slice).
fn mountEffectivePath(allocator: std.mem.Allocator, path: []const u8) ?[]const u8 {
    var current: []const u8 = path;
    while (true) {
        if (sandbox.canonicalizeExisting(allocator, current)) |canon| return canon;
        const parent = std.fs.path.dirname(current) orelse return null;
        if (parent.len >= current.len) return null;
        current = parent;
    }
}

/// H7 r4: una raíz registrada por la cabina confina a `wanted_path`
/// solo si la ruta normalizada queda dentro de la raíz normalizada Y la ruta
/// efectiva (reparse points resueltos) sigue dentro de la raíz efectiva. Una
/// UNC no la confina ninguna raíz de unidad, ni a la inversa.
/// R5 (el segundo auditor lote AH, P1-a): si la raíz todavía no existe, no basta la relación
/// léxica —se resolvía `true` sin comprobar nada físico—. Se resuelve el
/// ancestro existente más profundo de la raíz y de la ruta pedida (el mismo
/// helper canónico de los reparse points) y se comparan canónicos; y ese
/// ancestro debe además seguir siendo un punto de la propia raíz: si la
/// resolución lo reescribe (junction/symlink hacia fuera), la raíz registrada
/// no quedó confirmada y el montaje se rechaza (fail closed).
fn mountConfined(allocator: std.mem.Allocator, wanted_comps: []const []const u8, wanted_path: []const u8, root_path: []const u8) bool {
    if (mountPathIsUnc(wanted_path) != mountPathIsUnc(root_path)) return false;
    const root_comps = mountPathComponents(allocator, root_path) catch return false;
    defer mountPathComponentsFree(allocator, root_comps);
    if (!mountWithin(wanted_comps, root_comps)) return false;
    const root_anc = mountEffectivePath(allocator, root_path) orelse return false;
    defer allocator.free(root_anc);
    const wanted_anc = mountEffectivePath(allocator, wanted_path) orelse return false;
    defer allocator.free(wanted_anc);
    const root_anc_comps = mountPathComponents(allocator, root_anc) catch return false;
    defer mountPathComponentsFree(allocator, root_anc_comps);
    if (sandbox.canonicalizeExisting(allocator, root_path)) |root_canon| {
        // La raíz existe: su canónica es la referencia; el ancestro resuelto
        // de la raíz coincide con ella y compara contra la ruta efectiva.
        allocator.free(root_canon);
    } else if (!mountWithin(root_comps, root_anc_comps)) {
        // Raíz inexistente bajo un ancestro que reescribe la ruta (p. ej. una
        // junction hacia fuera): lo léxico no confirma la raíz → fail closed.
        return false;
    }
    const wanted_anc_comps = mountPathComponents(allocator, wanted_anc) catch return false;
    defer mountPathComponentsFree(allocator, wanted_anc_comps);
    return mountWithin(wanted_anc_comps, root_anc_comps);
}

/// Agrega una ruta al registro de mounts activos (SKILLS-RUNTIME-01).
/// `path`: directorio raíz que contiene carpetas de skills (<name>/SKILL.md).
pub export fn da_mount_add(handle: ?*anyopaque, path: [*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_mount_add: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    // H7: por MCP solo se aceptan montajes dentro de una raíz ya
    // registrada; registrar una raíz nueva requiere la cabina. El confinamiento
    // no es de prefijo textual: la ruta se normaliza (`.`/`..`, caja,
    // separadores) y su destino efectivo (junctions y demás reparse points) se
    // resuelve antes de comparar con la raíz, que también se resuelve.
    if (st.mcp_surface) {
        var check = mounts.MountRegistry.init(aa, st.db_conn);
        const active = check.listActive(aa) catch {
            setLastError("da_mount_add: failed to list cabin-registered mounts");
            return @intFromEnum(err(.internal, "da_mount_add: failed to check mounts"));
        };
        defer {
            for (active) |m| aa.free(m.path);
            aa.free(active);
        }
        const wanted = std.mem.span(path);
        if (wanted.len == 0 or wanted.len > 4096)
            return @intFromEnum(err(.invalid_state, "da_mount_add: ruta vacía o demasiado larga; registrar montajes por MCP requiere la cabina"));
        const wanted_comps = mountPathComponents(aa, wanted) catch
            return @intFromEnum(err(.oom, "da_mount_add: OOM"));
        defer mountPathComponentsFree(aa, wanted_comps);
        var confined = false;
        for (active) |m| {
            if (mountConfined(aa, wanted_comps, wanted, m.path)) {
                confined = true;
                break;
            }
        }
        if (!confined)
            return @intFromEnum(err(.invalid_state, "da_mount_add: un cliente MCP solo puede registrar montajes dentro de raíces ya registradas, sin salirse de ellas (ruta normalizada y destino resuelto); registrar una raíz nueva requiere la cabina"));
    }
    var reg = mounts.MountRegistry.init(aa, st.db_conn);
    const now: i64 = @intCast(@divFloor(GetTickCount64(), 1000));
    reg.add(std.mem.span(path), now) catch |e| {
        // QA-A H12: en palabras (antes «failed to add mount» para todo).
        var msg_buf: [512]u8 = undefined;
        const msg = std.fmt.bufPrint(&msg_buf, "da_mount_add: «{s}» {s}", .{ std.mem.span(path), mounts.newRootErrorMessage(e) }) catch "da_mount_add: no se pudo montar";
        return @intFromEnum(err(if (e == error.AlreadyMounted) .invalid_state else .internal, msg));
    };
    return @intFromEnum(ok());
}

/// Elimina una ruta del registro de mounts activos.
/// `path`: ruta exacta previamente registrada (coincidencia de texto).
pub export fn da_mount_remove(handle: ?*anyopaque, path: [*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_mount_remove: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    var reg = mounts.MountRegistry.init(aa, st.db_conn);
    reg.remove(std.mem.span(path)) catch |e| {
        // QA-A H12: PathNotFound es «no hay ese montaje», con la ruta.
        var msg_buf: [512]u8 = undefined;
        if (e == error.PathNotFound) {
            const msg = std.fmt.bufPrint(&msg_buf, "da_mount_remove: no hay ningún montaje con la ruta «{s}» (míralos con mounts_list)", .{std.mem.span(path)}) catch "da_mount_remove: no hay ningún montaje con esa ruta";
            return @intFromEnum(err(.not_found, msg));
        }
        const msg = std.fmt.bufPrint(&msg_buf, "da_mount_remove: no se pudo quitar «{s}»: {s}", .{ std.mem.span(path), @errorName(e) }) catch "da_mount_remove: no se pudo quitar el montaje";
        return @intFromEnum(err(.internal, msg));
    };
    return @intFromEnum(ok());
}

/// Lista todos los mounts registrados como JSON array [{id,path,added_at,active}].
/// El caller libera con da_string_free.
pub export fn da_mounts_list_json(handle: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_mounts_list_json: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    var reg = mounts.MountRegistry.init(aa, st.db_conn);
    const list = reg.list(aa) catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_mounts_list_json: OOM"));
        return @intFromEnum(ok());
    };
    defer {
        for (list) |m| aa.free(m.path);
        aa.free(list);
    }
    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_mounts_list_json: OOM"));
        return @intFromEnum(ok());
    };
    for (list) |m| {
        js.beginObject() catch continue;
        js.objectField("id") catch continue;
        js.write(m.id) catch continue;
        js.objectField("path") catch continue;
        js.write(m.path) catch continue;
        js.objectField("added_at") catch continue;
        js.write(m.added_at) catch continue;
        js.objectField("active") catch continue;
        js.write(m.active) catch continue;
        js.endObject() catch continue;
    }
    js.endArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_mounts_list_json: OOM"));
        return @intFromEnum(ok());
    };
    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_mounts_list_json: OOM"));
    return @intFromEnum(ok());
}

// ── Spaces ────────────────────────────────────────────────────────────────
//
// `core/src/spaces.zig` lleva desde F5 creando un git worktree por orden, con
// su rama y su fila en runtime.db, y NUNCA tuvo una funcion `da_space*`: era
// motor sin cable. Estos cuatro exports son el puente que faltaba.
//
// El directorio base de todos ellos es la raiz efectiva S2 del workspace
// (`workspace.effectiveRoot`), que es sobre la que el agente tiene
// permiso: crear un worktree fuera de ahi burlaria el sandbox.

/// Serializa un SpaceInfo dentro de un objeto JSON ya abierto.
fn writeSpaceJson(js: *std.json.Stringify, s: spaces.SpaceInfo) void {
    js.beginObject() catch return;
    js.objectField("id") catch return;
    js.write(s.id) catch return;
    js.objectField("projectId") catch return;
    js.write(s.project_id) catch return;
    js.objectField("kind") catch return;
    js.write(s.kind.toString()) catch return;
    js.objectField("name") catch return;
    js.write(s.name) catch return;
    js.objectField("worktreePath") catch return;
    js.write(s.worktree_path) catch return;
    js.objectField("branch") catch return;
    js.write(s.branch) catch return;
    js.objectField("createdAt") catch return;
    js.write(s.created_at) catch return;
    js.objectField("archivedAt") catch return;
    if (s.archived_at) |a| js.write(a) catch return else js.write(null) catch return;
    js.objectField("isNonGitDegraded") catch return;
    js.write(s.is_non_git_degraded) catch return;
    js.endObject() catch return;
}

/// Lista los spaces activos de un proyecto. Devuelve un array JSON.
/// El llamador libera con da_string_free.
pub export fn da_spaces_list_json(handle: ?*anyopaque, project_id: ?[*:0]const u8, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_spaces_list_json: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    const pid = if (project_id) |p| std.mem.span(p) else "default";

    const list = spaces.listSpaces(aa, st.db_conn, pid) catch {
        // Una lista vacia es un resultado legitimo (proyecto sin spaces); un
        // fallo de consulta tambien acaba aqui, pero devolver "[]" es lo unico
        // que el panel puede pintar sin inventarse nada.
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_spaces_list_json: OOM"));
        return @intFromEnum(ok());
    };
    defer {
        for (list) |*item| item.deinit(aa);
        aa.free(list);
    }

    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_spaces_list_json: OOM"));
        return @intFromEnum(ok());
    };
    for (list) |s| writeSpaceJson(&js, s);
    js.endArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_spaces_list_json: OOM"));
        return @intFromEnum(ok());
    };
    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_spaces_list_json: OOM"));
    return @intFromEnum(ok());
}

/// E5.05: estado de `.devagents/worktree.json` del proyecto para la cabina.
/// Devuelve {exists, valid, detail, copy[], setup_windows, setup_posix,
/// timeout_s, suggestions:[{lockfile,command}]} — la inspección no ejecuta
/// nada; sin archivo vienen las sugerencias por lockfiles del motor.
pub export fn da_worktree_config_json(handle: ?*anyopaque, project_id: ?[*:0]const u8, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_worktree_config_json: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    // El proyecto de la cabina es el del workspace (un proyecto por host);
    // el id se acepta por simetría con da_spaces_list_json.
    _ = project_id;

    // E5.05: la tarjeta debe leer el MISMO directorio que prepara la orden —
    // effectiveRoot aplica el anclaje S2 (segmento devagents-workspace), que
    // es donde vive .devagents/worktree.json. Con getWorkspaceRoot (raíz
    // cruda) la tarjeta decía "sin preparación" aunque la orden sí la veía.
    var root_buf: [4096]u8 = undefined;
    var status = worktree_prepare.inspectConfig(aa, workspace.effectiveRoot(&root_buf));
    defer status.deinit();

    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginObject() catch return @intFromEnum(err(.oom, "da_worktree_config_json: OOM"));
    js.objectField("exists") catch return @intFromEnum(err(.oom, "da_worktree_config_json: OOM"));
    js.write(status.exists) catch return @intFromEnum(err(.oom, "da_worktree_config_json: OOM"));
    js.objectField("valid") catch return @intFromEnum(err(.oom, "da_worktree_config_json: OOM"));
    js.write(status.valid) catch return @intFromEnum(err(.oom, "da_worktree_config_json: OOM"));
    js.objectField("detail") catch return @intFromEnum(err(.oom, "da_worktree_config_json: OOM"));
    js.write(status.detail) catch return @intFromEnum(err(.oom, "da_worktree_config_json: OOM"));
    js.objectField("copy") catch return @intFromEnum(err(.oom, "da_worktree_config_json: OOM"));
    js.beginArray() catch return @intFromEnum(err(.oom, "da_worktree_config_json: OOM"));
    for (status.copy) |rel| js.write(rel) catch return @intFromEnum(err(.oom, "da_worktree_config_json: OOM"));
    js.endArray() catch return @intFromEnum(err(.oom, "da_worktree_config_json: OOM"));
    js.objectField("setup_windows") catch return @intFromEnum(err(.oom, "da_worktree_config_json: OOM"));
    js.write(status.setup_windows) catch return @intFromEnum(err(.oom, "da_worktree_config_json: OOM"));
    js.objectField("setup_posix") catch return @intFromEnum(err(.oom, "da_worktree_config_json: OOM"));
    js.write(status.setup_posix) catch return @intFromEnum(err(.oom, "da_worktree_config_json: OOM"));
    js.objectField("timeout_s") catch return @intFromEnum(err(.oom, "da_worktree_config_json: OOM"));
    js.write(status.timeout_s) catch return @intFromEnum(err(.oom, "da_worktree_config_json: OOM"));
    js.objectField("suggestions") catch return @intFromEnum(err(.oom, "da_worktree_config_json: OOM"));
    js.beginArray() catch return @intFromEnum(err(.oom, "da_worktree_config_json: OOM"));
    const n = @min(status.lockfiles.len, status.commands.len);
    for (status.lockfiles[0..n], status.commands[0..n]) |lf, cmd| {
        js.beginObject() catch return @intFromEnum(err(.oom, "da_worktree_config_json: OOM"));
        js.objectField("lockfile") catch return @intFromEnum(err(.oom, "da_worktree_config_json: OOM"));
        js.write(lf) catch return @intFromEnum(err(.oom, "da_worktree_config_json: OOM"));
        js.objectField("command") catch return @intFromEnum(err(.oom, "da_worktree_config_json: OOM"));
        js.write(cmd) catch return @intFromEnum(err(.oom, "da_worktree_config_json: OOM"));
        js.endObject() catch return @intFromEnum(err(.oom, "da_worktree_config_json: OOM"));
    }
    js.endArray() catch return @intFromEnum(err(.oom, "da_worktree_config_json: OOM"));
    js.endObject() catch return @intFromEnum(err(.oom, "da_worktree_config_json: OOM"));
    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_worktree_config_json: OOM"));
    return @intFromEnum(ok());
}

/// Crea un space y devuelve su ficha como objeto JSON.
///
/// `kind` acepta "order" o "main-checkout"; cualquier otra cosa se rechaza en
/// vez de caer a un valor por defecto, porque la columna de la tabla lleva un
/// CHECK y un valor silenciosamente cambiado seria peor que un error.
pub export fn da_space_create(
    handle: ?*anyopaque,
    project_id: ?[*:0]const u8,
    name: ?[*:0]const u8,
    kind: ?[*:0]const u8,
    out_json: *[*:0]u8,
) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_space_create: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    const pid = if (project_id) |p| std.mem.span(p) else "default";
    const nm = if (name) |n| std.mem.span(n) else "";
    if (nm.len == 0) return @intFromEnum(err(.invalid_arg, "da_space_create: falta el nombre"));

    const kind_str = if (kind) |k| std.mem.span(k) else "order";
    const parsed_kind = spaces.SpaceKind.parse(kind_str) catch
        return @intFromEnum(err(.invalid_arg, "da_space_create: kind debe ser 'order' o 'main-checkout'"));

    var prep_diag: worktree_prepare.Diag = .{};
    var root_buf: [4096]u8 = undefined;
    var info = spaces.createSpace(aa, st.db_conn, pid, nm, parsed_kind, workspace.effectiveRoot(&root_buf), .{ .diag = &prep_diag }) catch |e| {
        var ebuf: [768]u8 = undefined;
        const emsg = std.fmt.bufPrint(&ebuf, "da_space_create: {s}", .{
            if (prep_diag.len > 0) prep_diag.msg() else @errorName(e),
        }) catch "da_space_create: no se pudo crear el space";
        return @intFromEnum(err(.internal, emsg));
    };
    defer info.deinit(aa);

    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    writeSpaceJson(&js, info);
    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_space_create: OOM"));
    return @intFromEnum(ok());
}

/// Archiva un space: retira su worktree y le pone `archived_at`. La fila sigue
/// existiendo hasta que se pode (da_spaces_prune).
pub export fn da_space_archive(handle: ?*anyopaque, space_id: i64) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_space_archive: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    var root_buf: [4096]u8 = undefined;
    spaces.archiveSpace(aa, st.db_conn, space_id, workspace.effectiveRoot(&root_buf)) catch |e| {
        var ebuf: [256]u8 = undefined;
        const message = std.fmt.bufPrint(&ebuf, "da_space_archive: {s}", .{@errorName(e)}) catch "da_space_archive: no se pudo archivar";
        return @intFromEnum(err(.internal, message));
    };
    return @intFromEnum(ok());
}

/// Borra las filas de los spaces ya archivados y poda los worktrees colgantes.
/// Escribe en `out_count` cuantos se podaron.
pub export fn da_spaces_prune(handle: ?*anyopaque, project_id: ?[*:0]const u8, out_count: *u32) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_spaces_prune: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    const pid = if (project_id) |p| std.mem.span(p) else "default";
    var root_buf: [4096]u8 = undefined;
    out_count.* = spaces.pruneSpaces(aa, st.db_conn, pid, workspace.effectiveRoot(&root_buf)) catch |e| {
        var ebuf: [256]u8 = undefined;
        const message = std.fmt.bufPrint(&ebuf, "da_spaces_prune: {s}", .{@errorName(e)}) catch "da_spaces_prune: no se pudo podar";
        return @intFromEnum(err(.internal, message));
    };
    return @intFromEnum(ok());
}

/// r6: poda ACOTADA a los ids aprobados por un humano. Para cada id
/// se comprueba que sigue archivado y pertenece al proyecto antes de retirar
/// su worktree/rama y borrar su fila; el resto de espacios del proyecto no se
/// toca aunque esten archivados. `ids_json` es un array JSON de enteros.
pub export fn da_spaces_prune_ids(
    handle: ?*anyopaque,
    project_id: ?[*:0]const u8,
    ids_json: ?[*:0]const u8,
    out_count: *u32,
) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_spaces_prune_ids: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    const raw = ids_json orelse
        return @intFromEnum(err(.invalid_arg, "da_spaces_prune_ids: falta ids_json"));
    var parsed = std.json.parseFromSlice([]i64, aa, std.mem.span(raw), .{}) catch
        return @intFromEnum(err(.invalid_arg, "da_spaces_prune_ids: ids_json debe ser un array JSON de enteros"));
    defer parsed.deinit();
    for (parsed.value) |id| {
        if (id <= 0)
            return @intFromEnum(err(.invalid_arg, "da_spaces_prune_ids: los ids deben ser enteros > 0"));
    }
    const pid = if (project_id) |p| std.mem.span(p) else "default";
    var root_buf: [4096]u8 = undefined;
    out_count.* = spaces.pruneSpacesByIds(aa, st.db_conn, pid, parsed.value, workspace.effectiveRoot(&root_buf)) catch |e| {
        var ebuf: [256]u8 = undefined;
        const message = std.fmt.bufPrint(&ebuf, "da_spaces_prune_ids: {s}", .{@errorName(e)}) catch "da_spaces_prune_ids: no se pudo podar";
        return @intFromEnum(err(.internal, message));
    };
    return @intFromEnum(ok());
}

