// ── Ship Flow (matriz B / C-05-B): orden done → PR real → merge ────────────
//
// El conector gh es honesto de fabrica (numero/URL/estado siempre de
// `gh pr view`, jamas inventados); aqui solo se decide QUE orden se empaqueta
// y DONDE: el worktree de su space si lo tiene, o el workspace efectivo.
// Los eventos `ship_*` dejan el intento y su resultado en el timeline de la
// orden — incluido el fallo con su mensaje real (B3).

fn insertShipEvent(conn: db.Connection, order_id: i64, kind: []const u8, payload: []const u8) void {
    const stmt = conn.prepare("INSERT INTO events (ts, source, kind, payload_json, order_id) VALUES (?, 'ship_flow', ?, ?, ?)") catch return;
    defer conn.finalize(stmt);
    db.bindInt(stmt, 1, health.nowMillis(conn)) catch return;
    db.bindText(stmt, 2, kind) catch return;
    db.bindText(stmt, 3, payload) catch return;
    db.bindInt(stmt, 4, order_id) catch return;
    _ = db.c.sqlite3_step(stmt);
}

/// Ruta del worktree del space ligado a la orden (orders.space_id -> spaces
/// .worktree_path, solo si sigue activo). Null si la orden no tiene space.
fn orderSpacePath(conn: db.Connection, order_db_id: i64, buf: *[4096]u8) ?[]const u8 {
    const sel = conn.prepare("SELECT space_id FROM orders WHERE id = ?") catch return null;
    defer conn.finalize(sel);
    db.bindInt(sel, 1, order_db_id) catch return null;
    if (db.c.sqlite3_step(sel) != db.c.SQLITE_ROW) return null;
    if (db.c.sqlite3_column_type(sel, 0) == db.c.SQLITE_NULL) return null;
    const space_id = db.c.sqlite3_column_int64(sel, 0);
    const s2 = conn.prepare("SELECT worktree_path FROM spaces WHERE id = ? AND archived_at IS NULL") catch return null;
    defer conn.finalize(s2);
    db.bindInt(s2, 1, space_id) catch return null;
    if (db.c.sqlite3_step(s2) != db.c.SQLITE_ROW) return null;
    const p = std.mem.span(db.c.sqlite3_column_text(s2, 0));
    if (p.len >= buf.len) return null;
    @memcpy(buf[0..p.len], p);
    return buf[0..p.len];
}

const GetFileAttributesW = if (@import("builtin").os.tag == .windows) struct {
    extern "kernel32" fn GetFileAttributesW(lpFileName: [*:0]const u16) callconv(.winapi) u32;
}.GetFileAttributesW else @import("providers").posix_files.GetFileAttributesW;

/// P1-4: motivo llano de una hija «sin auditar» que ya no se puede reintentar.
const DELEGATE_NO_WORKTREE_TEXT = "su copia de trabajo ya no existe; vuelve a pedir la subtarea";

/// P1-4 (observación de B2f): worktree de una hija delegada solo si sigue
/// registrado (orderSpacePath) Y existe en disco como carpeta. Una ruta que no
/// se puede convertir a UTF-16 no se puede comprobar: se devuelve tal cual
/// (el reintento fallará después con su propio motivo, no se oculta).
fn liveChildWorktree(conn: db.Connection, order_db_id: i64, buf: *[4096]u8) ?[]const u8 {
    const wt = orderSpacePath(conn, order_db_id, buf) orelse return null;
    var wide: [4097]u16 = undefined;
    const n = std.unicode.utf8ToUtf16Le(wide[0..4096], wt) catch return wt;
    wide[n] = 0;
    const attrs = GetFileAttributesW(wide[0..n :0].ptr);
    if (attrs == INVALID_FILE_ATTRIBUTES or (attrs & 0x10) == 0) return null;
    return wt;
}

/// Resuelve el worktree de la orden: el space ligado (orders.space_id) si
/// existe y sigue activo; si no, el workspace efectivo del motor.
fn orderWorktree(st: *CoreState, order_db_id: i64, buf: *[4096]u8) []const u8 {
    if (directOrderRoot(st, order_db_id, buf)) |root| return root;
    return orderSpacePath(st.db_conn, order_db_id, buf) orelse workspace.effectiveRoot(buf);
}

/// 10-nov: recuerda la carpeta en la que trabaja una orden de Directo.
fn rememberDirectRoot(st: *CoreState, order_db_id: i64, root: []const u8) void {
    if (order_db_id <= 0 or root.len == 0 or root.len > 4096) return;
    const a = st.arena.child_allocator;
    const copy = a.dupe(u8, root) catch return;
    st.direct_roots_mutex.lock();
    defer st.direct_roots_mutex.unlock();
    const gop = st.direct_roots.getOrPut(a, order_db_id) catch {
        a.free(copy);
        return;
    };
    if (gop.found_existing) a.free(gop.value_ptr.*);
    gop.value_ptr.* = copy;
}

fn directOrderRoot(st: *CoreState, order_db_id: i64, buf: *[4096]u8) ?[]const u8 {
    st.direct_roots_mutex.lock();
    defer st.direct_roots_mutex.unlock();
    const root = st.direct_roots.get(order_db_id) orelse return null;
    @memcpy(buf[0..root.len], root);
    return buf[0..root.len];
}

/// B3 (F5): garantiza que la orden tiene un space propio — lo crea como
/// worktree git real sobre `base` si hace falta. Solo se llama cuando `base`
/// ES un repo git (isGitRepo lo decidio arriba): en un directorio plano no hay
/// worktree que aislar y la orden escribe en la raiz como siempre. Null si no
/// aplica; los fallos de creación abortan el despacho con diagnóstico.
/// E5.04: la evidencia de copia (nombre + sha256, nunca contenido) entra al
/// audit_queue — el flush a ledger.db lo hace el hilo principal, como manda
/// FIX-ENGINE-8/9 (los hilos de despacho no escriben el ledger).
const WorktreeAuditCtx = struct {
    st: *CoreState,
    order_id: i64,
};

fn worktreeAuditSink(ctx: ?*anyopaque, rec: worktree_prepare.CopyRecord) void {
    const c: *const WorktreeAuditCtx = @ptrCast(@alignCast(ctx orelse return));
    const aa = c.st.arena.child_allocator;
    const notes = std.fmt.allocPrint(aa, "sha256={s}", .{rec.sha256_hex[0..]}) catch return;
    defer aa.free(notes);
    persistAuditEntries(c.st, aa, &.{.{
        .ts = health.nowSeconds(c.st.db_conn),
        .subject_kind = "worktree_copy",
        .subject_id = 0,
        .order_id = c.order_id,
        .action = "copy",
        .verdict = "ok",
        .model_id = "",
        .provider = "",
        .evidence_ref = rec.filename,
        .notes = notes,
    }});
}

/// ES un repo git (isGitRepo lo decidio arriba): en un directorio plano no hay
/// worktree que aislar y la orden escribe en la raiz como siempre. Null si no
/// aplica o algo falla fuera de la preparación — pero un fallo de PREPARACIÓN
/// (E5.04) se propaga como error: la orden debe caer con la causa real, no
/// continuar escribiendo en la raíz donde pidió aislamiento.
fn ensureOrderSpace(st: *CoreState, conn: db.Connection, rec: *OrderRecord, base: []const u8, buf: *[4096]u8, diag: *worktree_prepare.Diag) error{PrepareFailed}!?[]const u8 {
    // Native browser registration may prepare the same order before dispatch.
    // This per-handle lock is independent of the browser queue and the STA.
    st.browser_workspace_mutex.lock();
    defer st.browser_workspace_mutex.unlock();
    const order_db_id = rec.db_id orelse rec.id;
    if (orderSpacePath(conn, order_db_id, buf)) |p| return p;
    const aa = st.arena.child_allocator;
    const name = std.fmt.allocPrint(aa, "orden-{d}", .{order_db_id}) catch return null;
    var audit_ctx: WorktreeAuditCtx = .{ .st = st, .order_id = order_db_id };
    var sp = spaces.createSpace(aa, conn, rec.project_id, name, .order, base, .{
        .order_id = order_db_id,
        .diag = diag,
        .audit_fn = worktreeAuditSink,
        .audit_ctx = &audit_ctx,
    }) catch |e| {
        // cualquier fallo de creación aborta con la causa visible,
        // jamás continúa escribiendo en la raíz global de la orden.
        if (diag.len == 0) {
            const msg = std.fmt.bufPrint(&diag.buf, "space creation: {s}", .{@errorName(e)}) catch return error.PrepareFailed;
            diag.len = msg.len;
        }
        return error.PrepareFailed;
    };
    defer sp.deinit(aa);
    const u = conn.prepare("UPDATE orders SET space_id = ? WHERE id = ?") catch return null;
    defer conn.finalize(u);
    db.bindInt(u, 1, sp.id) catch return null;
    db.bindInt(u, 2, order_db_id) catch return null;
    if (db.c.sqlite3_step(u) != db.c.SQLITE_DONE) return null;
    if (sp.worktree_path.len >= buf.len) return null;
    @memcpy(buf[0..sp.worktree_path.len], sp.worktree_path);
    return buf[0..sp.worktree_path.len];
}

