/// E5.18: fija la opción best-of-N de una orden aún no despachada.
/// `n` ∈ {0=apagado, 2,3,4}; `members_json` es la lista explícita opcional
/// `[{provider,model}]` (null/vacío = se toman del enjambre fijado al aprobar).
/// Los duplicados de proveedor no se validan aquí: la validación real corre
/// en el despacho (runBestOfN la aplica contra la gobernanza viva).
pub export fn da_order_set_best_of_n(handle: ?*anyopaque, order: ?*anyopaque, n: c_int, members_json: ?[*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_order_set_best_of_n: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order) orelse return @intFromEnum(err(.invalid_arg, "da_order_set_best_of_n: null order handle"));
    if (n != 0 and (n < best_of_n.MIN_N or n > best_of_n.MAX_N))
        return @intFromEnum(err(.invalid_arg, "da_order_set_best_of_n: n debe ser 0 (apagado) o estar entre 2 y 4"));
    const mj: ?[]const u8 = if (members_json) |p| std.mem.span(p) else null;
    if (mj) |raw| {
        if (raw.len > 0) {
            var parsed = std.json.parseFromSlice(std.json.Value, st.arena.child_allocator, raw, .{}) catch
                return @intFromEnum(err(.invalid_arg, "da_order_set_best_of_n: members_json no es JSON válido"));
            defer parsed.deinit();
            if (parsed.value != .array)
                return @intFromEnum(err(.invalid_arg, "da_order_set_best_of_n: members_json debe ser un array [{provider,model}]"));
        }
    }
    const db_id = blk: {
        // La orden puede no estar en memoria (rehidratada) — resolver por fila.
        if (findOrder(st, order_id)) |rec| break :blk rec.db_id orelse rec.id;
        const sel = st.db_conn.prepare("SELECT id FROM orders WHERE id = ?") catch
            return @intFromEnum(err(.internal, "da_order_set_best_of_n: prepare"));
        defer st.db_conn.finalize(sel);
        db.bindInt(sel, 1, order_id) catch return @intFromEnum(err(.internal, "da_order_set_best_of_n: bind"));
        if (db.c.sqlite3_step(sel) != db.c.SQLITE_ROW)
            return @intFromEnum(err(.not_found, "da_order_set_best_of_n: orden no encontrada"));
        break :blk order_id;
    };
    const stmt = st.db_conn.prepare("UPDATE orders SET best_of_n = ?, best_of_n_members = ? WHERE id = ?") catch
        return @intFromEnum(err(.internal, "da_order_set_best_of_n: prepare"));
    defer st.db_conn.finalize(stmt);
    db.bindInt(stmt, 1, n) catch return @intFromEnum(err(.internal, "da_order_set_best_of_n: bind"));
    if (mj) |raw| {
        if (raw.len > 0) {
            db.bindText(stmt, 2, raw) catch return @intFromEnum(err(.internal, "da_order_set_best_of_n: bind"));
        } else {
            _ = db.c.sqlite3_bind_null(stmt, 2);
        }
    } else {
        _ = db.c.sqlite3_bind_null(stmt, 2);
    }
    db.bindInt(stmt, 3, db_id) catch return @intFromEnum(err(.internal, "da_order_set_best_of_n: bind"));
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE)
        return @intFromEnum(err(.internal, "da_order_set_best_of_n: update falló"));
    return @intFromEnum(ok());
}

/// E5.18: lista las candidatas de una orden best-of-N con métricas y rank.
/// Sirve la tarjeta comparativa de la WebUI y la tool MCP homónima.
pub export fn da_best_of_n_candidates_json(handle: ?*anyopaque, order: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_best_of_n_candidates_json: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order) orelse return @intFromEnum(err(.invalid_arg, "da_best_of_n_candidates_json: null order handle"));
    const aa = st.arena.child_allocator;
    const cands = best_of_n.listByParent(st.db_conn, aa, order_id) catch
        return @intFromEnum(err(.internal, "da_best_of_n_candidates_json: list failed"));
    defer best_of_n.freeCandidateList(aa, cands);

    // Ruta del worktree por candidata (space_id → spaces.worktree_path) y la
    // de la padre (donde cae la fusión): la tarjeta compara candidata vs esa
    // base con el mismo LCS del diff_viewer.
    var pwt: ?[]const u8 = null;
    var pwt_buf: [4096]u8 = undefined;
    pwt = orderSpacePath(st.db_conn, order_id, &pwt_buf);
    var base_buf: [4096]u8 = undefined;
    if (pwt == null) pwt = workspace.effectiveRoot(&base_buf);

    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginObject() catch return @intFromEnum(err(.oom, "OOM"));
    js.objectField("order_id") catch return @intFromEnum(err(.oom, "OOM"));
    js.write(@as(i64, order_id)) catch return @intFromEnum(err(.oom, "OOM"));
    js.objectField("parent_worktree") catch return @intFromEnum(err(.oom, "OOM"));
    js.write(pwt) catch return @intFromEnum(err(.oom, "OOM"));
    js.objectField("candidates") catch return @intFromEnum(err(.oom, "OOM"));
    js.beginArray() catch return @intFromEnum(err(.oom, "OOM"));
    for (cands) |*c| {
        var wt: ?[]const u8 = null;
        var wt_buf: [4096]u8 = undefined;
        if (c.child_order_id) |cid| wt = orderSpacePath(st.db_conn, cid, &wt_buf);
        // Archivos cambiados en el worktree candidato (tope 200 por lista —
        // payload de tarjeta, no de auditoría; el applyWinner real lee todo).
        // `orden-<hija>` es la carpeta de artefactos: el paseo FS la cubre
        // aunque el repo envolvente la tenga en .gitignore.
        var files = std.ArrayList([]const u8).empty;
        var deleted = std.ArrayList([]const u8).empty;
        var art_buf: [64]u8 = undefined;
        const artifact_prefix: ?[]const u8 = if (c.child_order_id) |cid|
            std.fmt.bufPrint(&art_buf, "orden-{d}", .{cid}) catch null
        else
            null;
        if (wt) |w| {
            if (best_of_n.changedFiles(aa, w, artifact_prefix)) |sets| {
                for (sets.copy) |p| {
                    if (files.items.len >= 200) break;
                    files.append(aa, p) catch break;
                }
                for (sets.del) |p| {
                    if (deleted.items.len >= 200) break;
                    deleted.append(aa, p) catch break;
                }
            }
        }
        js.beginObject() catch return @intFromEnum(err(.oom, "OOM"));
        js.objectField("id") catch return @intFromEnum(err(.oom, "OOM"));
        js.write(c.id) catch return @intFromEnum(err(.oom, "OOM"));
        js.objectField("member_idx") catch return @intFromEnum(err(.oom, "OOM"));
        js.write(c.member_idx) catch return @intFromEnum(err(.oom, "OOM"));
        js.objectField("provider") catch return @intFromEnum(err(.oom, "OOM"));
        js.write(c.provider) catch return @intFromEnum(err(.oom, "OOM"));
        js.objectField("model") catch return @intFromEnum(err(.oom, "OOM"));
        js.write(c.model) catch return @intFromEnum(err(.oom, "OOM"));
        js.objectField("child_order_id") catch return @intFromEnum(err(.oom, "OOM"));
        js.write(c.child_order_id) catch return @intFromEnum(err(.oom, "OOM"));
        js.objectField("space_id") catch return @intFromEnum(err(.oom, "OOM"));
        js.write(c.space_id) catch return @intFromEnum(err(.oom, "OOM"));
        js.objectField("worktree") catch return @intFromEnum(err(.oom, "OOM"));
        js.write(wt) catch return @intFromEnum(err(.oom, "OOM"));
        js.objectField("files") catch return @intFromEnum(err(.oom, "OOM"));
        js.beginArray() catch return @intFromEnum(err(.oom, "OOM"));
        for (files.items) |p| js.write(p) catch return @intFromEnum(err(.oom, "OOM"));
        js.endArray() catch return @intFromEnum(err(.oom, "OOM"));
        js.objectField("deleted_files") catch return @intFromEnum(err(.oom, "OOM"));
        js.beginArray() catch return @intFromEnum(err(.oom, "OOM"));
        for (deleted.items) |p| js.write(p) catch return @intFromEnum(err(.oom, "OOM"));
        js.endArray() catch return @intFromEnum(err(.oom, "OOM"));
        js.objectField("status") catch return @intFromEnum(err(.oom, "OOM"));
        js.write(c.status) catch return @intFromEnum(err(.oom, "OOM"));
        js.objectField("gates_pass") catch return @intFromEnum(err(.oom, "OOM"));
        js.write(c.metrics.gates_pass) catch return @intFromEnum(err(.oom, "OOM"));
        js.objectField("gates_fail") catch return @intFromEnum(err(.oom, "OOM"));
        js.write(c.metrics.gates_fail) catch return @intFromEnum(err(.oom, "OOM"));
        js.objectField("tests_pass") catch return @intFromEnum(err(.oom, "OOM"));
        js.write(c.metrics.tests_pass) catch return @intFromEnum(err(.oom, "OOM"));
        js.objectField("tests_fail") catch return @intFromEnum(err(.oom, "OOM"));
        js.write(c.metrics.tests_fail) catch return @intFromEnum(err(.oom, "OOM"));
        js.objectField("audit_verdict") catch return @intFromEnum(err(.oom, "OOM"));
        js.write(c.metrics.verdict.toText()) catch return @intFromEnum(err(.oom, "OOM"));
        js.objectField("cost_tokens") catch return @intFromEnum(err(.oom, "OOM"));
        js.write(c.metrics.cost_tokens) catch return @intFromEnum(err(.oom, "OOM"));
        js.objectField("elapsed_ms") catch return @intFromEnum(err(.oom, "OOM"));
        js.write(c.metrics.elapsed_ms) catch return @intFromEnum(err(.oom, "OOM"));
        js.objectField("rank") catch return @intFromEnum(err(.oom, "OOM"));
        js.write(c.rank) catch return @intFromEnum(err(.oom, "OOM"));
        js.objectField("chosen") catch return @intFromEnum(err(.oom, "OOM"));
        js.write(c.chosen) catch return @intFromEnum(err(.oom, "OOM"));
        js.endObject() catch return @intFromEnum(err(.oom, "OOM"));
    }
    js.endArray() catch return @intFromEnum(err(.oom, "OOM"));
    js.endObject() catch return @intFromEnum(err(.oom, "OOM"));
    const json = out.written();
    out_json.* = ownedCStr(json) orelse return @intFromEnum(err(.oom, "da_best_of_n_candidates_json: OOM"));
    return @intFromEnum(ok());
}

/// E5.18: el usuario elige la candidata ganadora. Aplica sus cambios al
/// worktree de la orden padre (git diff sobre la base común, o los `owns`
/// declarados en modo degradado), archiva las perdedoras y cierra la orden
/// en `done`. Solo desde `awaiting_best_of_n` — la fusión es decisión humana.
pub export fn da_best_of_n_choose(handle: ?*anyopaque, order: ?*anyopaque, candidate_id: i64) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_best_of_n_choose: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order) orelse return @intFromEnum(err(.invalid_arg, "da_best_of_n_choose: null order handle"));
    const aa = st.arena.child_allocator;
    const parent_id: i64 = order_id;

    // Estado real de la padre — la fusión solo existe si está esperando.
    var st_buf: [64]u8 = undefined;
    const parent_st = best_of_n.childStatus(st.db_conn, parent_id, &st_buf);
    if (!std.mem.eql(u8, parent_st, "awaiting_best_of_n"))
        return @intFromEnum(err(.invalid_state, "da_best_of_n_choose: la orden no está esperando elección best-of-N"));

    const cands = best_of_n.listByParent(st.db_conn, aa, parent_id) catch
        return @intFromEnum(err(.internal, "da_best_of_n_choose: list failed"));
    defer best_of_n.freeCandidateList(aa, cands);
    if (cands.len == 0)
        return @intFromEnum(err(.invalid_state, "da_best_of_n_choose: la orden no tiene candidatas"));

    var winner: ?*const best_of_n.CandidateRow = null;
    for (cands) |*c| {
        if (c.id == candidate_id) {
            winner = c;
            break;
        }
    }
    const w = winner orelse
        return @intFromEnum(err(.invalid_arg, "da_best_of_n_choose: candidate_id no pertenece a esta orden"));
    // Solo una candidata que corrió puede ganar — pending/cancelled no.
    if (w.child_order_id == null)
        return @intFromEnum(err(.invalid_state, "da_best_of_n_choose: la candidata nunca llegó a despacharse"));

    var base_buf: [4096]u8 = undefined;
    const base = workspace.effectiveRoot(&base_buf);
    var src_buf: [4096]u8 = undefined;
    const cand_wt = orderSpacePath(st.db_conn, w.child_order_id.?, &src_buf) orelse blk: {
        // Space archivado o inexistente: modo degradado sobre su ruta si la
        // fila conserva worktree_path (espacio sin registrar también se lee).
        if (w.space_id) |sid| {
            const sel = st.db_conn.prepare("SELECT worktree_path FROM spaces WHERE id = ?") catch null;
            if (sel) |s| {
                defer st.db_conn.finalize(s);
                db.bindInt(s, 1, sid) catch {};
                if (db.c.sqlite3_step(s) == db.c.SQLITE_ROW) {
                    const p = std.mem.span(db.c.sqlite3_column_text(s, 0));
                    if (p.len < src_buf.len) {
                        @memcpy(src_buf[0..p.len], p);
                        break :blk src_buf[0..p.len];
                    }
                }
            }
        }
        break :blk base;
    };
    var dst_buf: [4096]u8 = undefined;
    const parent_wt = orderSpacePath(st.db_conn, parent_id, &dst_buf) orelse base;

    // `owns` del plan padre para el modo degradado (sin git): las rutas
    // declaradas son lo único que se puede mover con certeza.
    var owns_list = std.ArrayList([]const u8).empty;
    defer owns_list.deinit(aa);
    const parent_db_id = blk: {
        if (findOrder(st, parent_id)) |rec| {
            if (rec.outcome) |*oc| {
                for (oc.plan.tasks) |t| for (t.owns) |o| owns_list.append(aa, o) catch {};
            }
            break :blk rec.db_id orelse rec.id;
        }
        break :blk parent_id;
    };

    // La candidata escribió bajo `orden-<hija>` (convención por orden
    // ejecutora); la padre lee `orden-<padre>` — la fusión reancla.
    var from_buf: [64]u8 = undefined;
    var to_buf: [64]u8 = undefined;
    const remap: ?best_of_n.PathRemap = blk: {
        const from = std.fmt.bufPrint(&from_buf, "orden-{d}", .{w.child_order_id.?}) catch break :blk null;
        const to = std.fmt.bufPrint(&to_buf, "orden-{d}", .{parent_db_id}) catch break :blk null;
        break :blk .{ .from = from, .to = to };
    };

    const applied = best_of_n.applyWinner(aa, cand_wt, parent_wt, owns_list.items, remap) catch |e| {
        setLastError(@errorName(e));
        return @intFromEnum(err(.internal, "da_best_of_n_choose: no se pudo aplicar el ganador"));
    };

    best_of_n.setChosen(st.db_conn, w.id);
    // Perdedoras archivadas — la evidencia (filas, eventos) queda intacta.
    for (cands) |*c| {
        if (c.id == w.id) continue;
        if (c.space_id) |sid| spaces.archiveSpace(aa, st.db_conn, sid, base) catch {};
        const us = st.db_conn.prepare("UPDATE best_of_n_candidates SET status = 'archived' WHERE id = ?") catch continue;
        db.bindInt(us, 1, c.id) catch {
            st.db_conn.finalize(us);
            continue;
        };
        _ = db.c.sqlite3_step(us);
        st.db_conn.finalize(us);
    }

    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginObject() catch {};
    js.objectField("candidate_id") catch {};
    js.write(w.id) catch {};
    js.objectField("member_idx") catch {};
    js.write(w.member_idx) catch {};
    js.objectField("provider") catch {};
    js.write(w.provider) catch {};
    js.objectField("model") catch {};
    js.write(w.model) catch {};
    js.objectField("files_copied") catch {};
    js.write(applied.copied) catch {};
    js.objectField("files_deleted") catch {};
    js.write(applied.deleted) catch {};
    js.endObject() catch {};
    bonEvent(st.db_conn, parent_id, "best_of_n_chosen", out.written());

    // Cierre terminal honesto: la padre gana el resultado de la candidata
    // elegida — done con el evento order_done de la pareja válida. Las tareas
    // del plan padre quedan satisfechas por la fusión (el timeout del torneo
    // pudo haberlas marcado 'failed' en el camino — ahora ya no lo están).
    persistOrderTasksStatus(st.db_conn, parent_id, "completed");
    _ = st.db_conn.tryCommitTerminal(parent_id, "done", "order_done", "superagente", out.written(), health.nowMillis(st.db_conn)) catch false;
    if (findOrder(st, parent_id)) |rec| syncRecStatusFromDb(st.db_conn, rec);
    return @intFromEnum(ok());
}

/// da_order_ship_json(handle, order, out_json) — empaqueta la orden en un PR.
/// La orden debe estar `done`: la revision ya ocurrio en el gate de aprobacion
/// y ship publica el RESULTADO, no trabajo a medio hacer. Errores: mensaje
/// real de gh/git en last_error + evento ship_failed en la orden.
pub export fn da_order_ship_json(handle: ?*anyopaque, order: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_order_ship_json: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order) orelse return @intFromEnum(err(.invalid_arg, "da_order_ship_json: null order handle"));
    const rec = findOrder(st, order_id) orelse return @intFromEnum(err(.not_found, "da_order_ship_json: order not found"));
    if (rec.status != .done) return @intFromEnum(err(.invalid_state, "da_order_ship_json: solo se puede enviar una orden terminada (done)"));
    const aa = st.arena.child_allocator;
    const order_db_id = rec.db_id orelse rec.id;

    var wt_buf: [4096]u8 = undefined;
    const worktree = orderWorktree(st, order_db_id, &wt_buf);

    insertShipEvent(st.db_conn, order_db_id, "ship_started", "{}");

    var gh = providers.github.GitHubConnector.init(aa, null);
    defer gh.deinit();
    gh.capture_fn = st.gh_capture_fn;
    gh.capture_full_fn = st.gh_capture_full_fn;
    // T4-GITEA: el conector REST se arma siempre — barato mientras no haya red;
    // solo dispara si el remote de la orden resulta no ser GitHub.
    var gitea = providers.gitea.GiteaConnector.init(aa);
    defer gitea.deinit();
    gitea.http_fn = st.gitea_rest_fn;
    gh.forge_auth_fn = forgeStoreAuth;
    gh.forge_auth_ctx = st;
    gh.rest_enabled = st.forge_rest_enabled;
    const forge_hosts = configuredForgeHosts(st, aa) catch return @intFromEnum(err(.internal, "forges: configuracion de hosts invalida"));
    defer freeForgeHosts(aa, forge_hosts);
    gh.forge_hosts = forge_hosts;

    var res = ship_flow.shipOrder(aa, st.db_conn, &gh, &gitea, order_db_id, rec.text, worktree) catch |e| {
        var out: std.Io.Writer.Allocating = .init(aa);
        defer out.deinit();
        var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
        js.beginObject() catch return @intFromEnum(err(.internal, "da_order_ship_json: OOM"));
        js.objectField("error") catch return @intFromEnum(err(.internal, "da_order_ship_json: OOM"));
        js.write(@errorName(e)) catch return @intFromEnum(err(.internal, "da_order_ship_json: OOM"));
        js.objectField("detail") catch return @intFromEnum(err(.internal, "da_order_ship_json: OOM"));
        const err_detail = if (gitea.last_error.items.len > 0) gitea.last_error.items else gh.last_error.items;
        js.write(err_detail) catch return @intFromEnum(err(.internal, "da_order_ship_json: OOM"));
        js.endObject() catch return @intFromEnum(err(.internal, "da_order_ship_json: OOM"));
        insertShipEvent(st.db_conn, order_db_id, "ship_failed", out.written());
        const detail = if (err_detail.len > 0) err_detail else @errorName(e);
        const msg = std.fmt.allocPrint(aa, "ship: {s}", .{detail}) catch "ship fallo";
        return @intFromEnum(err(.internal, msg));
    };
    defer res.deinit(aa);

    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginObject() catch return @intFromEnum(err(.internal, "da_order_ship_json: OOM"));
    js.objectField("ok") catch return @intFromEnum(err(.internal, "da_order_ship_json: OOM"));
    js.write(true) catch return @intFromEnum(err(.internal, "da_order_ship_json: OOM"));
    js.objectField("pr") catch return @intFromEnum(err(.internal, "da_order_ship_json: OOM"));
    js.beginObject() catch return @intFromEnum(err(.internal, "da_order_ship_json: OOM"));
    js.objectField("id") catch return @intFromEnum(err(.internal, "da_order_ship_json: OOM"));
    js.write(res.pr_id) catch return @intFromEnum(err(.internal, "da_order_ship_json: OOM"));
    js.objectField("number") catch return @intFromEnum(err(.internal, "da_order_ship_json: OOM"));
    js.write(res.number) catch return @intFromEnum(err(.internal, "da_order_ship_json: OOM"));
    js.objectField("url") catch return @intFromEnum(err(.internal, "da_order_ship_json: OOM"));
    js.write(res.url) catch return @intFromEnum(err(.internal, "da_order_ship_json: OOM"));
    js.objectField("state") catch return @intFromEnum(err(.internal, "da_order_ship_json: OOM"));
    js.write(res.state.toString()) catch return @intFromEnum(err(.internal, "da_order_ship_json: OOM"));
    js.objectField("adopted") catch return @intFromEnum(err(.internal, "da_order_ship_json: OOM"));
    js.write(res.adopted) catch return @intFromEnum(err(.internal, "da_order_ship_json: OOM"));
    js.objectField("manual") catch return @intFromEnum(err(.internal, "da_order_ship_json: OOM"));
    js.write(res.manual) catch return @intFromEnum(err(.internal, "da_order_ship_json: OOM"));
    js.objectField("branch") catch return @intFromEnum(err(.internal, "da_order_ship_json: OOM"));
    js.write(res.branch) catch return @intFromEnum(err(.internal, "da_order_ship_json: OOM"));
    js.endObject() catch return @intFromEnum(err(.internal, "da_order_ship_json: OOM"));
    js.endObject() catch return @intFromEnum(err(.internal, "da_order_ship_json: OOM"));
    const json = out.written();
    out_json.* = ownedCStr(json) orelse return @intFromEnum(err(.oom, "da_order_ship_json: OOM"));
    insertShipEvent(st.db_conn, order_db_id, "ship_done", json);
    return @intFromEnum(ok());
}

/// Construye el stdin de `git credential approve/fill`. El protocolo es por
/// lineas: un salto en cualquier campo inyectaria pares extra — rechazo duro.
/// El host tampoco admite espacios ni '/' (seria otra cosa, no un host).
fn buildCredentialInput(allocator: std.mem.Allocator, host: []const u8, user: []const u8, pass: []const u8) ![]u8 {
    for ([_][]const u8{ host, user, pass }) |f| {
        if (f.len == 0 or std.mem.indexOfAny(u8, f, "\r\n") != null) return error.InvalidField;
    }
    if (std.mem.indexOfAny(u8, host, " \t") != null or std.mem.indexOfScalar(u8, host, '/') != null) return error.InvalidHost;
    return std.fmt.allocPrint(allocator, "protocol=https\nhost={s}\nusername={s}\npassword={s}\n\n", .{ host, user, pass });
}

/// da_git_store_credential(handle, cred_json, out_json) — guarda una
/// credencial HTTPS en el administrador de credenciales de git via
/// `git credential approve` y la relee con `credential fill` para confirmar
/// que el almacen la tomo. cred_json: {"host","username","password"}.
/// El secreto viaja por stdin, jamas por argv ni por logs. Es la MISMA
/// credencial que usa el push: tras guardarla, ship la recoge por
/// `git credential fill` sin mas pasos (el "actualiza credenciales" que el
/// aviso de la tarjeta manual ofrece al usuario).
pub export fn da_git_store_credential(handle: ?*anyopaque, cred_json: [*:0]const u8, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_git_store_credential: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    const json_str = std.mem.span(cred_json);
    if (json_str.len == 0) return @intFromEnum(err(.invalid_arg, "da_git_store_credential: empty json"));

    var parsed = std.json.parseFromSlice(std.json.Value, aa, json_str, .{}) catch {
        return @intFromEnum(err(.invalid_arg, "da_git_store_credential: invalid JSON"));
    };
    defer parsed.deinit();
    const obj = switch (parsed.value) {
        .object => |o| o,
        else => return @intFromEnum(err(.invalid_arg, "da_git_store_credential: expected object")),
    };
    const host = if (obj.get("host")) |v| if (v == .string) v.string else "" else "";
    const user = if (obj.get("username")) |v| if (v == .string) v.string else "" else "";
    const pass = if (obj.get("password")) |v| if (v == .string) v.string else "" else "";
    const input = buildCredentialInput(aa, host, user, pass) catch |e| switch (e) {
        error.OutOfMemory => return @intFromEnum(err(.oom, "da_git_store_credential: OOM")),
        error.InvalidField => return @intFromEnum(err(.invalid_arg, "da_git_store_credential: campo vacio, con salto de linea o host invalido")),
        error.InvalidHost => return @intFromEnum(err(.invalid_arg, "da_git_store_credential: host invalido")),
    };

    var gh = providers.github.GitHubConnector.init(aa, null);
    defer gh.deinit();
    gh.capture_fn = st.gh_capture_fn;

    {
        var cap = gh.captureInput(&[_][]const u8{ "git", "credential", "approve" }, null, input, providers.github.GIT_GUARD_ENV) catch |e| {
            const msg = std.fmt.allocPrint(aa, "git credential approve: {s}", .{@errorName(e)}) catch "credential approve fallo";
            return @intFromEnum(err(.internal, msg));
        };
        defer cap.deinit(gh.allocator);
        if (cap.exit_code != 0) {
            const msg = std.fmt.allocPrint(aa, "git credential approve salio {d}; no se pudo guardar la credencial", .{cap.exit_code}) catch "credential approve fallo";
            return @intFromEnum(err(.internal, msg));
        }
    }

    // Relectura real: el store solo confirma si `fill` la devuelve. Si el
    // helper rechazo el almacen, la contraseña leida no sera la enviada.
    const fill_in = std.fmt.allocPrint(aa, "protocol=https\nhost={s}\n\n", .{host}) catch
        return @intFromEnum(err(.oom, "da_git_store_credential: OOM"));
    var cap = gh.captureInput(&[_][]const u8{ "git", "credential", "fill" }, null, fill_in, providers.github.GIT_GUARD_ENV) catch |e| {
        const msg = std.fmt.allocPrint(aa, "git credential fill: {s}", .{@errorName(e)}) catch "credential fill fallo";
        return @intFromEnum(err(.internal, msg));
    };
    defer cap.deinit(gh.allocator);
    var verified = false;
    if (cap.exit_code == 0) {
        var it = std.mem.splitScalar(u8, cap.stdout, '\n');
        while (it.next()) |line| {
            const l = std.mem.trim(u8, line, " \t\r");
            if (std.mem.startsWith(u8, l, "password=") and std.mem.eql(u8, l["password=".len..], pass)) verified = true;
        }
    }

    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginObject() catch return @intFromEnum(err(.internal, "da_git_store_credential: OOM"));
    js.objectField("stored") catch return @intFromEnum(err(.internal, "da_git_store_credential: OOM"));
    js.write(verified) catch return @intFromEnum(err(.internal, "da_git_store_credential: OOM"));
    js.objectField("host") catch return @intFromEnum(err(.internal, "da_git_store_credential: OOM"));
    js.write(host) catch return @intFromEnum(err(.internal, "da_git_store_credential: OOM"));
    js.endObject() catch return @intFromEnum(err(.internal, "da_git_store_credential: OOM"));
    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_git_store_credential: OOM"));
    return @intFromEnum(ok());
}

/// da_pr_merge(handle, pr_id) — merge real via gh + refresco autoritativo.
/// Devuelve out_json {"merged":bool,"state":"..."} con el estado POST-view.
pub export fn da_pr_merge(handle: ?*anyopaque, pr_id: i64, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_pr_merge: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    var gh = providers.github.GitHubConnector.init(aa, null);
    defer gh.deinit();
    gh.capture_fn = st.gh_capture_fn;
    var gitea = providers.gitea.GiteaConnector.init(aa);
    defer gitea.deinit();
    gitea.http_fn = st.gitea_rest_fn;
    gh.forge_auth_fn = forgeStoreAuth;
    gh.forge_auth_ctx = st;
    gh.rest_enabled = st.forge_rest_enabled;
    const forge_hosts = configuredForgeHosts(st, aa) catch return @intFromEnum(err(.internal, "forges: configuracion de hosts invalida"));
    defer freeForgeHosts(aa, forge_hosts);
    gh.forge_hosts = forge_hosts;

    const state = ship_flow.mergePr(st.db_conn, &gh, &gitea, pr_id) catch |e| {
        const detail = if (gitea.last_error.items.len > 0) gitea.last_error.items else if (gh.last_error.items.len > 0) gh.last_error.items else @errorName(e);
        const msg = std.fmt.allocPrint(aa, "pr_merge: {s}", .{detail}) catch "pr_merge fallo";
        return @intFromEnum(if (e == error.NotFound) err(.not_found, msg) else err(.internal, msg));
    };
    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginObject() catch return @intFromEnum(err(.internal, "da_pr_merge: OOM"));
    js.objectField("merged") catch return @intFromEnum(err(.internal, "da_pr_merge: OOM"));
    js.write(state == .merged) catch return @intFromEnum(err(.internal, "da_pr_merge: OOM"));
    js.objectField("state") catch return @intFromEnum(err(.internal, "da_pr_merge: OOM"));
    js.write(state.toString()) catch return @intFromEnum(err(.internal, "da_pr_merge: OOM"));
    js.endObject() catch return @intFromEnum(err(.internal, "da_pr_merge: OOM"));
    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_pr_merge: OOM"));
    return @intFromEnum(ok());
}

/// da_prs_json(handle, order_id, out_json) — PRs de una orden (0 = todas).
pub export fn da_prs_json(handle: ?*anyopaque, order_id: i64, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_prs_json: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    const rows = ship_flow.listPrs(aa, st.db_conn, order_id) catch
        return @intFromEnum(err(.internal, "da_prs_json: no se pudo listar"));
    defer {
        for (rows) |*r| r.deinit(aa);
        aa.free(rows);
    }
    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginArray() catch return @intFromEnum(err(.internal, "da_prs_json: OOM"));
    for (rows) |r| {
        js.beginObject() catch return @intFromEnum(err(.internal, "da_prs_json: OOM"));
        js.objectField("id") catch return @intFromEnum(err(.internal, "da_prs_json: OOM"));
        js.write(r.id) catch return @intFromEnum(err(.internal, "da_prs_json: OOM"));
        js.objectField("order_id") catch return @intFromEnum(err(.internal, "da_prs_json: OOM"));
        js.write(r.order_id) catch return @intFromEnum(err(.internal, "da_prs_json: OOM"));
        js.objectField("repo") catch return @intFromEnum(err(.internal, "da_prs_json: OOM"));
        js.write(r.repo) catch return @intFromEnum(err(.internal, "da_prs_json: OOM"));
        js.objectField("number") catch return @intFromEnum(err(.internal, "da_prs_json: OOM"));
        js.write(r.number) catch return @intFromEnum(err(.internal, "da_prs_json: OOM"));
        js.objectField("state") catch return @intFromEnum(err(.internal, "da_prs_json: OOM"));
        js.write(r.state) catch return @intFromEnum(err(.internal, "da_prs_json: OOM"));
        js.objectField("url") catch return @intFromEnum(err(.internal, "da_prs_json: OOM"));
        js.write(r.url) catch return @intFromEnum(err(.internal, "da_prs_json: OOM"));
        js.objectField("last_polled_at") catch return @intFromEnum(err(.internal, "da_prs_json: OOM"));
        js.write(r.last_polled_at) catch return @intFromEnum(err(.internal, "da_prs_json: OOM"));
        js.endObject() catch return @intFromEnum(err(.internal, "da_prs_json: OOM"));
    }
    js.endArray() catch return @intFromEnum(err(.internal, "da_prs_json: OOM"));
    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_prs_json: OOM"));
    return @intFromEnum(ok());
}

/// da_repo_clone(handle, url, target_dir) — clonado GitHub sin checkout previo
/// (B6): `git clone <url> <target>` real; falla honesto con stderr de git.
pub export fn da_repo_clone(handle: ?*anyopaque, url: ?[*:0]const u8, target_dir: ?[*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_repo_clone: null core handle"));
    if (url == null or target_dir == null) return @intFromEnum(err(.invalid_arg, "da_repo_clone: faltan url/target_dir"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    const clone_url = std.mem.span(url.?);
    const clone_target = std.mem.span(target_dir.?);
    // `git clone -- <url>`: una URL que empiece por `-` (--upload-pack=...) o un
    // transporte ext::/file:// ejecutaria comandos locales. Solo https o ssh de forja.
    if (!providers.github.isCloneUrlAllowed(clone_url)) {
        return @intFromEnum(err(.invalid_arg, "da_repo_clone: solo se admiten URL https:// o git@host:ruta"));
    }
    if (clone_target.len == 0 or clone_target[0] == '-') return @intFromEnum(err(.invalid_arg, "da_repo_clone: target_dir invalido"));
    // H14: destino usado por git tras el filtro. En MCP es la ruta RESUELTA
    // contra la raíz (absoluta); en cabina queda como llegó, sin re-resolver.
    var resolved_target: []const u8 = clone_target;
    var resolved_alloc: ?[]u8 = null;
    if (st.mcp_surface) {
        // Sin humano, el clon solo puede escribir dentro de la raíz efectiva.
        // El destino relativo se resuelve contra la MISMA base que las
        // comprobaciones (la raíz), nunca contra el cwd del proceso, y el
        // reparse check corre sobre esa ruta resuelta: la real que git
        // recibirá, porque se le pasa absoluta y ya no la re-resuelve.
        var root_buf: [4096]u8 = undefined;
        const root = workspace.effectiveRoot(&root_buf);
        const abs = std.fs.path.resolve(aa, &.{ root, clone_target }) catch
            return @intFromEnum(err(.invalid_state, "da_repo_clone: un cliente MCP solo puede clonar dentro de la raiz del workspace"));
        const inside = workspace.resolvesInside(abs, root) and blk: {
            const checked = confined_fs.strictNewPath(aa, abs) catch break :blk false;
            aa.free(checked);
            break :blk true;
        };
        if (!inside) {
            aa.free(abs);
            return @intFromEnum(err(.invalid_state, "da_repo_clone: un cliente MCP solo puede clonar dentro de la raiz del workspace"));
        }
        resolved_target = abs;
        resolved_alloc = abs;
    }
    var gh = providers.github.GitHubConnector.init(aa, null);
    defer gh.deinit();
    gh.capture_fn = st.gh_capture_fn;
    gh.capture_full_fn = st.gh_capture_full_fn;
    gh.cloneRepo(clone_url, resolved_target) catch |e| {
        if (resolved_alloc) |p| aa.free(p);
        const detail = if (gh.last_error.items.len > 0) gh.last_error.items else @errorName(e);
        const msg = std.fmt.allocPrint(aa, "git clone fallo: {s}", .{detail}) catch "git clone fallo";
        return @intFromEnum(err(.internal, msg));
    };
    if (resolved_alloc) |p| aa.free(p);
    return @intFromEnum(ok());
}

/// da_order_worktree_json(handle, order, out_json) — la carpeta REAL donde la
/// orden escribe: su worktree de space si lo tiene, o la raiz efectiva. La UI
/// la necesita para apuntar el punto de control al sitio correcto (B3).
pub export fn da_order_worktree_json(handle: ?*anyopaque, order: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_order_worktree_json: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order) orelse return @intFromEnum(err(.invalid_arg, "da_order_worktree_json: null order handle"));
    const rec = findOrder(st, order_id) orelse return @intFromEnum(err(.not_found, "da_order_worktree_json: order not found"));
    const aa = st.arena.child_allocator;
    const order_db_id = rec.db_id orelse rec.id;
    var wt_buf: [4096]u8 = undefined;
    const path = orderWorktree(st, order_db_id, &wt_buf);
    // space_id sale de la fila spaces, si la orden tiene una activa.
    // (is_non_git_degraded no se persiste en la tabla — la degradacion se
    // detecta sola: un worktree que no es repo hace fallar git abajo.)
    var space_id: i64 = 0;
    if (st.db_conn.prepare("SELECT s.id FROM orders o JOIN spaces s ON s.id = o.space_id WHERE o.id = ? AND s.archived_at IS NULL")) |sel| {
        defer st.db_conn.finalize(sel);
        db.bindInt(sel, 1, order_db_id) catch {};
        if (db.c.sqlite3_step(sel) == db.c.SQLITE_ROW) {
            space_id = db.c.sqlite3_column_int64(sel, 0);
        }
    } else |_| {}
    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginObject() catch return @intFromEnum(err(.internal, "da_order_worktree_json: OOM"));
    js.objectField("path") catch return @intFromEnum(err(.internal, "da_order_worktree_json: OOM"));
    js.write(path) catch return @intFromEnum(err(.internal, "da_order_worktree_json: OOM"));
    js.objectField("space_id") catch return @intFromEnum(err(.internal, "da_order_worktree_json: OOM"));
    if (space_id > 0) js.write(space_id) catch return @intFromEnum(err(.internal, "OOM")) else js.write(null) catch return @intFromEnum(err(.internal, "OOM"));
    js.endObject() catch return @intFromEnum(err(.internal, "OOM"));
    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_order_worktree_json: OOM"));
    return @intFromEnum(ok());
}

// ── Plugins ───────────────────────────────────────────────────────────────
//
// `core/src/plugin_loader.zig` son 801 lineas con verificacion de ABI, anclaje
// de confianza por SHA-256 en catalog.db y carga real de DLL — y NUNCA tuvo una
// funcion `da_plugin_*`. Sin este puente, el cargador es codigo muerto.
//
// Convencion de instalacion, deliberadamente simple: cada plugin vive en su
// propia subcarpeta de `%LOCALAPPDATA%\DevAgents\plugins\` con un `plugin.json`
// y su DLL al lado. Nada de rutas arbitrarias: un plugin es codigo nativo que
// se carga en el proceso, asi que el sitio donde puede estar es UNO y conocido.

/// Lee un archivo de texto pequeno (manifiestos). Devuelve null si no existe.
fn readSmallFile(allocator: std.mem.Allocator, path: []const u8) ?[]u8 {
    const path_z = allocator.dupeZ(u8, path) catch return null;
    defer allocator.free(path_z);
    const h = CreateFileA(path_z.ptr, 0x80000000, 0x00000001, null, 3, 0x80, null);
    const INVALID: windows.HANDLE = @ptrFromInt(~@as(usize, 0));
    if (h == INVALID) return null;
    defer _ = CloseHandle(h);

    // 256 KiB de tope: un manifiesto es un JSON de unas pocas lineas. Sin tope,
    // apuntar esto a un DLL de 200 MB se lo comeria entero en memoria.
    var buf = allocator.alloc(u8, 256 * 1024) catch return null;
    var read: u32 = 0;
    if (ReadFile(h, buf.ptr, @intCast(buf.len), &read, null) == 0 or read == 0) {
        allocator.free(buf);
        return null;
    }
    if (allocator.resize(buf, read)) {
        buf.len = read;
        return buf;
    }
    const exact = allocator.dupe(u8, buf[0..read]) catch {
        allocator.free(buf);
        return null;
    };
    allocator.free(buf);
    return exact;
}

/// Inventario de plugins instalados. Devuelve un array JSON.
///
/// Cada entrada dice si el plugin es de CONFIANZA, es decir si el SHA-256 del
/// DLL en disco coincide con el anclado en `plugin_trust`. Un plugin sin anclar
/// o con el hash cambiado se lista igualmente, marcado y con el motivo: ocultar
/// lo que no carga dejaria al usuario sin saber por que su plugin no aparece.
pub export fn da_plugins_list_json(handle: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_plugins_list_json: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    const dir = paths.pluginsDir(aa) catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "OOM"));
        return @intFromEnum(ok());
    };
    defer aa.free(dir);

    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "OOM"));
        return @intFromEnum(ok());
    };

    const pattern = std.fmt.allocPrint(aa, "{s}" ++ std.fs.path.sep_str ++ "*", .{dir}) catch {
        js.endArray() catch {};
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "OOM"));
        return @intFromEnum(ok());
    };
    defer aa.free(pattern);

    var fd: FIND_DATA_W = undefined;
    const h = findFirstUtf8(pattern, &fd);
    if (h != windows.INVALID_HANDLE_VALUE) {
        defer _ = FindClose(h);
        const loader = plugin_loader.PluginLoader.init(aa);
        while (true) {
            const is_dir = (fd.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY_FLAG) != 0;
            const name_len = std.mem.indexOfScalar(u16, &fd.cFileName, 0) orelse fd.cFileName.len;
            const name16 = fd.cFileName[0..name_len];
            const is_dot = std.mem.eql(u16, name16, &[_]u16{'.'}) or std.mem.eql(u16, name16, &[_]u16{ '.', '.' });
            if (is_dir and !is_dot) {
                const entry = std.unicode.utf16LeToUtf8Alloc(aa, name16) catch break;
                defer aa.free(entry);
                writePluginEntry(aa, &js, &loader, st, dir, entry);
            }
            if (FindNextFileW(h, @ptrCast(&fd)) == 0) break;
        }
    }

    js.endArray() catch {};
    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_plugins_list_json: OOM"));
    return @intFromEnum(ok());
}

/// Serializa una carpeta de plugin. Nunca falla hacia fuera: una carpeta
/// ilegible se publica como entrada con `error`, no se omite.
fn writePluginEntry(
    aa: std.mem.Allocator,
    js: *std.json.Stringify,
    loader: *const plugin_loader.PluginLoader,
    st: *CoreState,
    dir: []const u8,
    entry: []const u8,
) void {
    const manifest_path = std.fmt.allocPrint(aa, "{s}" ++ std.fs.path.sep_str ++ "{s}" ++ std.fs.path.sep_str ++ "plugin.json", .{ dir, entry }) catch return;
    defer aa.free(manifest_path);

    js.beginObject() catch return;
    js.objectField("folder") catch return;
    js.write(entry) catch return;

    const text = readSmallFile(aa, manifest_path);
    if (text == null) {
        js.objectField("name") catch return;
        js.write(entry) catch return;
        js.objectField("trusted") catch return;
        js.write(false) catch return;
        js.objectField("error") catch return;
        js.write("Falta plugin.json en la carpeta del plugin") catch return;
        js.endObject() catch return;
        return;
    }
    defer aa.free(text.?);

    const manifest = loader.parseManifest(text.?) catch |e| {
        js.objectField("name") catch return;
        js.write(entry) catch return;
        js.objectField("trusted") catch return;
        js.write(false) catch return;
        js.objectField("error") catch return;
        js.write(@errorName(e)) catch return;
        js.endObject() catch return;
        return;
    };
    defer manifest.deinit(aa);

    js.objectField("name") catch return;
    js.write(manifest.name) catch return;
    js.objectField("version") catch return;
    js.write(manifest.version) catch return;
    js.objectField("abiVersion") catch return;
    js.write(manifest.abi_version) catch return;
    js.objectField("dllName") catch return;
    js.write(manifest.dll_name) catch return;

    js.objectField("capabilities") catch return;
    js.beginArray() catch return;
    for (manifest.capabilities) |c| {
        js.beginObject() catch continue;
        js.objectField("kind") catch continue;
        js.write(@tagName(c.kind)) catch continue;
        js.objectField("name") catch continue;
        js.write(c.name) catch continue;
        js.objectField("description") catch continue;
        js.write(c.description) catch continue;
        js.endObject() catch continue;
    }
    js.endArray() catch return;

    // Confianza: se COMPARA el hash del DLL en disco contra el anclado. No
    // basta con que exista una fila en plugin_trust; si el archivo cambio
    // despues de anclarlo, el plugin ya no es el que se aprobo.
    const dll_path = std.fmt.allocPrint(aa, "{s}" ++ std.fs.path.sep_str ++ "{s}" ++ std.fs.path.sep_str ++ "{s}", .{ dir, entry, manifest.dll_name }) catch {
        js.endObject() catch return;
        return;
    };
    defer aa.free(dll_path);

    var trusted = false;
    var reason: []const u8 = "";
    if (manifest.abi_version != plugin_loader.EXPECTED_ABI_VERSION) {
        reason = "La version de ABI del plugin no es la que soporta este motor";
    } else if (loader.loadTrustedFromCatalog(dll_path, text.?, st.catalog.db)) |loaded| {
        var l = loaded;
        l.deinit();
        trusted = true;
    } else |e| {
        reason = @errorName(e);
    }

    js.objectField("trusted") catch return;
    js.write(trusted) catch return;
    if (!trusted) {
        js.objectField("error") catch return;
        js.write(reason) catch return;
    }
    js.endObject() catch return;
}

/// Ancla el hash del DLL de un plugin ya copiado en la carpeta de plugins y
/// comprueba que carga. `folder` es el nombre de la subcarpeta, no una ruta:
/// aceptar rutas arbitrarias convertiria esto en "carga el DLL que yo te diga".
pub export fn da_plugin_trust(handle: ?*anyopaque, folder: ?[*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_plugin_trust: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    const name = if (folder) |f| std.mem.span(f) else "";
    if (name.len == 0) return @intFromEnum(err(.invalid_arg, "da_plugin_trust: falta la carpeta"));
    // Un separador o `..` en el nombre lo saca de la carpeta de plugins.
    if (std.mem.indexOfAny(u8, name, "\\/:") != null or std.mem.indexOf(u8, name, "..") != null) {
        return @intFromEnum(err(.invalid_arg, "da_plugin_trust: la carpeta debe ser un nombre simple"));
    }

    const dir = paths.pluginsDir(aa) catch return @intFromEnum(err(.internal, "da_plugin_trust: sin carpeta de plugins"));
    defer aa.free(dir);

    const manifest_path = std.fmt.allocPrint(aa, "{s}" ++ std.fs.path.sep_str ++ "{s}" ++ std.fs.path.sep_str ++ "plugin.json", .{ dir, name }) catch
        return @intFromEnum(err(.oom, "OOM"));
    defer aa.free(manifest_path);

    const text = readSmallFile(aa, manifest_path) orelse
        return @intFromEnum(err(.invalid_arg, "da_plugin_trust: no se encontro plugin.json"));
    defer aa.free(text);

    const loader = plugin_loader.PluginLoader.init(aa);
    const manifest = loader.parseManifest(text) catch
        return @intFromEnum(err(.invalid_arg, "da_plugin_trust: plugin.json invalido"));
    defer manifest.deinit(aa);

    if (manifest.abi_version != plugin_loader.EXPECTED_ABI_VERSION) {
        return @intFromEnum(err(.invalid_arg, "da_plugin_trust: version de ABI no soportada"));
    }

    const dll_path = std.fmt.allocPrint(aa, "{s}" ++ std.fs.path.sep_str ++ "{s}" ++ std.fs.path.sep_str ++ "{s}", .{ dir, name, manifest.dll_name }) catch
        return @intFromEnum(err(.oom, "OOM"));
    defer aa.free(dll_path);

    loader.pinPluginHash(st.catalog.db, manifest.name, dll_path) catch
        return @intFromEnum(err(.internal, "da_plugin_trust: no se pudo anclar el hash del DLL"));

    // Se carga de verdad antes de dar el anclaje por bueno. Anclar un DLL que
    // luego no carga deja al usuario con un plugin "de confianza" inservible.
    var loaded = loader.loadTrustedFromCatalog(dll_path, text, st.catalog.db) catch
        return @intFromEnum(err(.internal, "da_plugin_trust: el hash quedo anclado pero el DLL no carga"));
    loaded.deinit();

    return @intFromEnum(ok());
}

/// Retira la confianza de un plugin: borra su ancla. El DLL sigue en disco, y
/// dejara de cargarse hasta que se vuelva a anclar.
pub export fn da_plugin_untrust(handle: ?*anyopaque, plugin_name: ?[*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_plugin_untrust: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const name = if (plugin_name) |p| std.mem.span(p) else "";
    if (name.len == 0) return @intFromEnum(err(.invalid_arg, "da_plugin_untrust: falta el nombre"));

    const stmt = st.catalog.db.prepare("DELETE FROM plugin_trust WHERE name = ?") catch
        return @intFromEnum(err(.internal, "da_plugin_untrust: no se pudo preparar la consulta"));
    defer st.catalog.db.finalize(stmt);
    db.bindText(stmt, 1, name) catch return @intFromEnum(err(.internal, "da_plugin_untrust: bind"));
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE) {
        return @intFromEnum(err(.internal, "da_plugin_untrust: no se pudo borrar el ancla"));
    }
    return @intFromEnum(ok());
}

/// Devuelve la ruta de la carpeta de plugins, para que la cabina pueda abrirla.
pub export fn da_plugins_dir(handle: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_plugins_dir: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    const dir = paths.pluginsDir(aa) catch return @intFromEnum(err(.internal, "da_plugins_dir: sin carpeta"));
    defer aa.free(dir);

    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginObject() catch {};
    js.objectField("path") catch {};
    js.write(dir) catch {};
    js.endObject() catch {};
    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_plugins_dir: OOM"));
    return @intFromEnum(ok());
}

/// Una llamada al modelo, sin planificador y sin orden. Devuelve
/// `{ok, text, provider, model}` o `{ok:false, error}`.
///
/// Existe por la decisión D4. El autocompletado por comentario del editor
/// (Ctrl+Enter) mandaba su petición por `da_order_submit`, es decir por el
/// PLANIFICADOR — y el planificador no genera código: clasifica la intención y
/// devuelve un plan, con una descripción en prosa en `understanding`. Por eso
/// Ctrl+Enter proponía prosa: no era un fallo del prompt, era que iba por el
/// camino equivocado. Pedirle a un planificador el contenido de un archivo no
/// podía funcionar por mucho que se afinara el texto.
///
/// Esto NO es un atajo alrededor de la gobernanza: no escribe archivos, no
/// ejecuta nada y no crea una orden. Es una transformación de texto de un solo
/// disparo, que es exactamente lo que Ctrl+Enter necesita. Lo que devuelve pasa
/// después por el visor de cambios, donde el usuario acepta o rechaza bloque a
/// bloque.
pub export fn da_complete_text(
    handle: ?*anyopaque,
    system_prompt: ?[*:0]const u8,
    user_prompt: ?[*:0]const u8,
    out_json: *[*:0]u8,
) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_complete_text: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    const sys = if (system_prompt) |s| std.mem.span(s) else "";
    const usr = if (user_prompt) |u| std.mem.span(u) else "";
    if (usr.len == 0) return @intFromEnum(err(.invalid_arg, "da_complete_text: falta el prompt"));

    // La seleccion va POR EL ROUTER, no por LiveLlm.init.
    //
    // Encontrado probando D4 con la aplicacion delante: el chat respondia con
    // `claude-fable-5` y Ctrl+Enter devolvia AuthFailed EN EL MISMO MOMENTO. No
    // era cuota: eran dos caminos de seleccion distintos. `LiveLlm.init` ordena
    // por `is_free DESC`, o sea prueba primero los gratuitos, e IGNORA
    // `settings.governance_mode`. El chat va por el router, que si lo lee, y con
    // "Prioriza pago" elige los modelos donde queda cuota.
    //
    // Es la misma clase de fallo que (la gobernanza no llegaba al router):
    // el usuario elige una politica, un camino la respeta y el otro no, asi que
    // la misma configuracion da resultados distintos segun por donde entres.
    // El router es el UNICO sitio donde la gobernanza esta implementada;
    // duplicar ese criterio aqui seria acabar con dos politicas que divergen.
    const now = health.nowSeconds(st.db_conn);
    var router = model_router.Router.init(aa, st.catalog.db, null, now);
    router.setHealthConn(st.db_conn);
    defer router.deinitHealthCache();

    var candidates = router.rankCandidates(.{ .task_type = .programar, .required_context = 8000 }) catch {
        out_json.* = ownedCStr("{\"ok\":false,\"error\":\"El router no pudo ordenar candidatos\"}") orelse
            return @intFromEnum(err(.oom, "OOM"));
        return @intFromEnum(ok());
    };
    defer {
        for (candidates.items) |c| c.deinit(aa);
        candidates.deinit(aa);
    }
    if (candidates.items.len == 0) {
        out_json.* = ownedCStr("{\"ok\":false,\"error\":\"No hay ningun modelo elegible con clave activa\"}") orelse
            return @intFromEnum(err(.oom, "OOM"));
        return @intFromEnum(ok());
    }

    // Se recorren en el orden del router: si uno falla por cuota o por clave, se
    // degrada al siguiente. Sin esto, un rate_limited del primero dejaria
    // Ctrl+Enter inservible aunque hubiera cuatro proveedores mas.
    //
    // ACOTADO (2026-08-06). Este bucle no tenia tope: recorria TODOS los
    // candidatos del router —143 en el equipo del usuario— y cada llamada podia
    // esperar el plazo completo de una tarea de construccion. Y no bloquea solo
    // a Ctrl+Enter: el host atiende todos los mensajes `core.*` con UN SOLO hilo
    // trabajador, asi que mientras esto corre se quedan en cola el arbol de
    // archivos, el cambio de pestana y la busqueda — la IDE entera parece
    // colgada. Medido: `core.complete` 96.375 ms y el `core.status()` siguiente
    // 96.382 ms esperando detras.
    //
    // Un autocompletado es interactivo: o contesta pronto o no sirve. Tres
    // candidatos y un presupuesto total acotan el peor caso a algo que el
    // usuario puede tolerar; el respaldo largo sigue existiendo en las ordenes,
    // que es donde tiene sentido.
    const COMPLETE_MAX_CANDIDATES: usize = 3;
    const COMPLETE_PER_CALL_MS: u64 = 20_000;
    const COMPLETE_TOTAL_BUDGET_MS: u64 = 45_000;
    const started_ms = GetTickCount64();

    var last_err: []const u8 = "El proveedor no devolvio texto";
    var tried: usize = 0;
    for (candidates.items) |cand| {
        if (tried >= COMPLETE_MAX_CANDIDATES) break;
        if (GetTickCount64() - started_ms >= COMPLETE_TOTAL_BUDGET_MS) {
            last_err = "se agoto el tiempo de autocompletado";
            break;
        }
        const opt = live_worker.LiveLlm.initForced(aa, st.catalog_path, cand.provider_name, cand.model_name);
        if (opt == null) {
            last_err = "sin clave activa";
            continue;
        }
        var llm = opt.?;
        defer llm.deinit();
        // Ruta V1, la MISMA que usan las tareas del despacho y que sí produce
        // texto. `setUseConnectorV2(true)` mandaba Ctrl+Enter por `callTimedDirectV2`,
        // que nació como camino de SONDEO (probeModel es su consumidor declarado).
        // Que el autocompletado —una funcionalidad de usuario— viajara por el
        // camino de los pings es lo que hay que descartar primero: `core.complete`
        // lleva devolviendo `{"ok":false,"error":"empty"}` en el arnés del puente
        // desde antes de esta sesión, con las claves funcionando.
        llm.setUseConnectorV2(false);
        if (llm.lives.len == 0) {
            last_err = "sin clave activa";
            continue;
        }
        // Solo cuenta como intento lo que de verdad llega a llamar al proveedor:
        // descartar candidatos sin clave es instantaneo y no gasta presupuesto.
        tried += 1;
        const live = llm.lives[0];
        llm.buffer.clearRetainingCapacity();
        llm.callWithDeadline(live, if (sys.len > 0) sys else "Eres un asistente de programacion.", usr, COMPLETE_PER_CALL_MS) catch |e| {
            last_err = @errorName(e);
            continue;
        };
        const text = llm.buffer.items;
        if (text.len == 0) {
            last_err = "empty";
            continue;
        }

        var out: std.Io.Writer.Allocating = .init(aa);
        defer out.deinit();
        var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
        js.beginObject() catch {};
        js.objectField("ok") catch {};
        js.write(true) catch {};
        js.objectField("text") catch {};
        js.write(text) catch {};
        js.objectField("provider") catch {};
        js.write(live.cfg.name) catch {};
        js.objectField("model") catch {};
        js.write(live.model) catch {};
        js.endObject() catch {};
        out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_complete_text: OOM"));
        return @intFromEnum(ok());
    }

    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginObject() catch {};
    js.objectField("ok") catch {};
    js.write(false) catch {};
    js.objectField("error") catch {};
    js.write(last_err) catch {};
    js.endObject() catch {};
    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_complete_text: OOM"));
    return @intFromEnum(ok());
}

/// Descubre skills desde los mounts activos y devuelve el inventario como JSON.
/// El caller libera con da_string_free.
/// Mete una cadena dentro de unas comillas de JSON dejandola analizable.
///
/// Hace falta de verdad: una ruta de Windows como `C:\tmp\da_skill_test` emite
/// `\t` y `\d` en crudo. El primero se decodifica como tabulador y el segundo
/// ni siquiera es un escape valido, asi que el documento entero deja de poder
/// analizarse. Y como el host entrega las respuestas con PostWebMessageAsJson,
/// un JSON invalido no genera un error: NO SE ENTREGA NADA, y la llamada de la
/// cabina se queda colgada para siempre.
fn appendJsonEscaped(list: *std.ArrayList(u8), allocator: std.mem.Allocator, s: []const u8) !void {
    for (s) |c| switch (c) {
        '"' => try list.appendSlice(allocator, "\\\""),
        '\\' => try list.appendSlice(allocator, "\\\\"),
        '\n' => try list.appendSlice(allocator, "\\n"),
        '\r' => try list.appendSlice(allocator, "\\r"),
        '\t' => try list.appendSlice(allocator, "\\t"),
        else => {
            if (c < 0x20) {
                var buf: [8]u8 = undefined;
                const hex = try std.fmt.bufPrint(&buf, "\\u{x:0>4}", .{c});
                try list.appendSlice(allocator, hex);
            } else {
                try list.append(allocator, c);
            }
        },
    };
}

pub export fn da_skills_discover_json(handle: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_skills_discover_json: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    var reg = mounts.MountRegistry.init(aa, st.db_conn);
    const mount_paths = reg.getActivePaths(aa) catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_skills_discover_json: OOM"));
        return @intFromEnum(ok());
    };
    defer aa.free(mount_paths);
    if (mount_paths.len == 0) {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_skills_discover_json: OOM"));
        return @intFromEnum(ok());
    }
    // Escaneo manual vía kernel32 (evita std.Io.Threaded → stack overflow en
    // DLL/Qt). API W — un mount root o carpeta de skill con unicode era
    // inaccesible por la vía ANSI.
    const GENERIC_READ: u32 = 0x80000000;
    const FILE_SHARE_READ: u32 = 0x00000001;
    const OPEN_EXISTING: u32 = 3;

    var out: std.ArrayList(u8) = .empty;
    defer out.deinit(aa);
    out.appendSlice(aa, "{\"resources\":[") catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_skills_discover_json: OOM"));
        return @intFromEnum(ok());
    };
    var first = true;

    for (mount_paths) |root_path| {
        const pattern = std.mem.concat(aa, u8, &.{ root_path, "\\*" }) catch continue;
        defer aa.free(pattern);
        var findData: FIND_DATA_W = undefined;
        const hFind = findFirstUtf8(pattern, &findData);
        if (hFind == windows.INVALID_HANDLE_VALUE) continue;
        defer _ = FindClose(hFind);
        while (true) {
            if (findData.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY_FLAG != 0) {
                const name_len = std.mem.indexOfScalar(u16, &findData.cFileName, 0) orelse findData.cFileName.len;
                const name16 = findData.cFileName[0..name_len];
                const is_dot = std.mem.eql(u16, name16, &[_]u16{'.'}) or std.mem.eql(u16, name16, &[_]u16{ '.', '.' });
                if (!is_dot) {
                    const name = std.unicode.utf16LeToUtf8Alloc(aa, name16) catch break;
                    defer aa.free(name);
                    const skillPath = std.mem.concat(aa, u8, &.{ root_path, "\\", name, "\\SKILL.md" }) catch break;
                    defer aa.free(skillPath);
                    const skillPathW = std.unicode.utf8ToUtf16LeAllocZ(std.heap.page_allocator, skillPath) catch break;
                    defer std.heap.page_allocator.free(skillPathW);
                    const hFile = CreateFileW(
                        skillPathW,
                        GENERIC_READ,
                        FILE_SHARE_READ,
                        null,
                        OPEN_EXISTING,
                        0,
                        null,
                    );
                    if (hFile != windows.INVALID_HANDLE_VALUE) {
                        defer _ = CloseHandle(hFile);
                        const size = GetFileSize(hFile, null);
                        if (size != std.math.maxInt(u32)) {
                            const buf = aa.alloc(u8, size) catch break;
                            defer aa.free(buf);
                            var read: u32 = 0;
                            if (ReadFile(hFile, buf.ptr, @intCast(size), &read, null) != 0 and read == size) {
                                if (tool_discovery.parseFrontmatter(aa, buf[0..read]) catch null) |fm_const| {
                                    var fm = fm_const;
                                    defer fm.deinit();
                                    const skillName = fm.get("name") orelse name;
                                    const desc = fm.get("description") orelse "";
                                    if (!first) {
                                        out.appendSlice(aa, ",") catch {};
                                    }
                                    first = false;
                                    out.appendSlice(aa, "{\"kind\":\"skill\",\"name\":\"") catch {};
                                    appendJsonEscaped(&out, aa, skillName) catch {};
                                    out.appendSlice(aa, "\",\"path\":\"") catch {};
                                    appendJsonEscaped(&out, aa, skillPath) catch {};
                                    out.appendSlice(aa, "\",\"description\":\"") catch {};
                                    appendJsonEscaped(&out, aa, desc) catch {};
                                    out.appendSlice(aa, "\",\"source_root\":\"") catch {};
                                    appendJsonEscaped(&out, aa, root_path) catch {};
                                    out.appendSlice(aa, "\"}") catch {};
                                }
                            }
                        }
                    }
                }
            }
            if (FindNextFileW(hFind, @ptrCast(&findData)) == 0) break;
        }
    }

    out.appendSlice(aa, "],\"warnings\":[]}") catch {};
    out_json.* = ownedCStr(out.items) orelse return @intFromEnum(err(.oom, "da_skills_discover_json: OOM"));
    return @intFromEnum(ok());
}

