pub export fn da_webhook_add(handle: ?*anyopaque, config_json: [*:0]const u8, out_id: *i64) callconv(.c) c_int {
    return addWebhookWithStarter(handle, config_json, out_id, webhooks.Dispatcher.start);
}

fn addWebhookWithStarter(handle: ?*anyopaque, config_json: [*:0]const u8, out_id: *i64, start: *const fn (std.mem.Allocator, []const u8) anyerror!*webhooks.Dispatcher) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "webhooks: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const a = st.arena.child_allocator;
    // H7: el opt-in de destinos privados (allow_private=true) es una
    // decisión de confianza de la cabina; un cliente MCP siempre lo rechaza.
    if (st.mcp_surface) {
        const parsed = std.json.parseFromSlice(std.json.Value, a, std.mem.span(config_json), .{}) catch null;
        defer if (parsed) |*p| p.deinit();
        if (parsed != null and parsed.?.value == .object) {
            if (parsed.?.value.object.get("allow_private")) |v| {
                if (v == .bool and v.bool)
                    return @intFromEnum(err(.invalid_arg, "webhook_add: un cliente MCP no puede habilitar destinos privados; el opt-in allow_private requiere la cabina"));
            }
        }
    }
    // e5-harden punto 10: el despachador arranca ANTES de guardar; si no
    // arranca, no queda un receptor guardado que nunca recibiría nada.
    if (st.webhook_dispatcher == null and !std.mem.eql(u8, st.runtime_path, ":memory:")) {
        st.webhook_dispatcher = start(a, st.runtime_path) catch return @intFromEnum(err(.internal, "webhooks: no arrancó el despachador de avisos; el receptor no se guardó"));
    }
    out_id.* = webhooks.addConfig(a, st.db_conn, std.mem.span(config_json)) catch |e| {
        if (e == error.PrivateDestination) return @intFromEnum(err(.invalid_arg, "webhooks: PrivateDestination: destino privado; requiere allow_private=true y un receptor de confianza"));
        // QA-A H12: frase que dice qué pasó y qué hacer, no «invalid
        // configuration or storage failure» para todo.
        var msg_buf: [512]u8 = undefined;
        const msg = std.fmt.bufPrint(&msg_buf, "webhooks: {s} ({s})", .{ webhooks.errorMessage(e), @errorName(e) }) catch "webhooks: no se pudo registrar el receptor";
        return @intFromEnum(err(if (e == error.InvalidConfig) .invalid_arg else .internal, msg));
    };
    return @intFromEnum(ok());
}

test "HARD10. dispatcher failure never saves a partial webhook" {
    const Fail = struct {
        fn start(_: std.mem.Allocator, _: []const u8) anyerror!*webhooks.Dispatcher {
            return error.InjectedDispatcherFailure;
        }
    };
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    const original = st.runtime_path;
    st.runtime_path = "synthetic-runtime";
    defer st.runtime_path = original;
    var id: i64 = 99;
    try std.testing.expect(addWebhookWithStarter(handle, "{\"url\":\"https://example.test/hook\"}", &id, Fail.start) != 0);
    const count = try st.db_conn.prepare("SELECT COUNT(*) FROM webhooks");
    defer st.db_conn.finalize(count);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(count));
    try std.testing.expectEqual(@as(i64, 0), db.c.sqlite3_column_int64(count, 0));
}

