/// P12-T1: Devuelve el inventario UNIFICADO como JSON (skills + MCPs + plugins + webhooks).
/// Incluye cost y source por recurso. Si hay un servidor MCP conectado (od_mcp_state),
/// sus tools se fusionan en el inventario. El caller libera con da_string_free.
pub export fn da_inventory_json(handle: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_inventory_json: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    st.inventory_mutex.lock();
    defer st.inventory_mutex.unlock();

    // Asegurar que el inventario base existe.
    if (st.inventory == null) {
        var threaded = std.Io.Threaded.init(aa, .{});
        defer threaded.deinit();
        const io = threaded.io();
        var reg = mounts.MountRegistry.init(aa, st.db_conn);
        if (reg.getActivePaths(aa)) |mount_paths| {
            defer {
                for (mount_paths) |p| aa.free(p);
                aa.free(mount_paths);
            }
            st.inventory = tool_discovery.scanRoots(aa, io, mount_paths) catch null;
        } else |_| {
            st.inventory = null;
        }
    }

    if (st.inventory == null) {
        out_json.* = ownedCStr("{\"resources\":[],\"warnings\":[\"no inventory available\"]}") orelse
            return @intFromEnum(err(.oom, "da_inventory_json: OOM"));
        return @intFromEnum(ok());
    }

    // Si hay MCP conectado, fusionar sus tools.
    var final_inventory = st.inventory.?;
    var merged: ?tool_discovery.Inventory = null;
    defer if (merged) |*m| m.deinit(aa);

    if (st.od_mcp_state.connected) {
        if (st.od_mcp_state.listToolsJson(aa)) |tools_json| {
            defer aa.free(tools_json);
            merged = tool_discovery.mergeMcpTools(aa, &st.inventory.?, "open-design", tools_json) catch null;
            if (merged) |*m| {
                final_inventory = m.*;
            }
        } else |_| {}
    }

    const json = final_inventory.toJson(aa) catch {
        out_json.* = ownedCStr("{\"resources\":[],\"warnings\":[\"toJson failed\"]}") orelse
            return @intFromEnum(err(.oom, "da_inventory_json: OOM"));
        return @intFromEnum(ok());
    };
    defer aa.free(json);
    out_json.* = ownedCStr(json) orelse return @intFromEnum(err(.oom, "da_inventory_json: OOM"));
    return @intFromEnum(ok());
}

/// P12-T1: Invalida el cache del inventario para forzar re-escaneo en la próxima consulta.
pub export fn da_inventory_refresh(handle: ?*anyopaque) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_inventory_refresh: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    st.inventory_mutex.lock();
    defer st.inventory_mutex.unlock();
    if (st.inventory) |*inv| {
        inv.deinit(st.arena.child_allocator);
        st.inventory = null;
    }
    return @intFromEnum(ok());
}

pub export fn da_worker_output_poll(handle: ?*anyopaque, since_ms: i64, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_worker_output_poll: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_worker_output_poll: OOM"));
        return @intFromEnum(ok());
    };
    st.output_mutex.lock();
    defer st.output_mutex.unlock();
    for (st.worker_outputs.items) |wo| {
        if (wo.ts_ms <= since_ms) continue;
        js.beginObject() catch continue;
        js.objectField("worker_id") catch continue;
        js.write(wo.worker_id) catch continue;
        js.objectField("stream") catch continue;
        js.write(wo.stream) catch continue;
        js.objectField("text") catch continue;
        js.write(wo.text) catch continue;
        js.objectField("ts") catch continue;
        js.write(wo.ts_ms) catch continue;
        js.endObject() catch continue;
    }
    js.endArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_worker_output_poll: OOM"));
        return @intFromEnum(ok());
    };
    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_worker_output_poll: OOM"));
    return @intFromEnum(ok());
}

/// UX-08: devuelve el timeline de eventos de una orden. `since_event_id` permite
/// polling incremental (solo eventos con id > since_event_id). `out_json` es un
/// array de objetos {id,ts,source,kind,title,severity,payload}. El caller libera
/// con da_string_free.
pub export fn da_order_events_json(handle: ?*anyopaque, order: ?*anyopaque, since_event_id: i64, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_order_events_json: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order) orelse return @intFromEnum(err(.invalid_arg, "da_order_events_json: null order handle"));
    const aa = st.arena.child_allocator;

    // P4: usar db_id para ordenes en memoria, igual que session_messages.
    const db_id: i64 = if (findOrder(st, order_id)) |rec| (rec.db_id orelse rec.id) else order_id;

    const stmt = st.db_conn.prepare("SELECT id, ts, source, kind, payload_json FROM events WHERE order_id = ? AND id > ? ORDER BY ts ASC, id ASC") catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_order_events_json: OOM"));
        return @intFromEnum(ok());
    };
    defer st.db_conn.finalize(stmt);
    db.bindInt(stmt, 1, db_id) catch {};
    db.bindInt(stmt, 2, since_event_id) catch {};

    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_order_events_json: OOM"));
        return @intFromEnum(ok());
    };

    var arena = std.heap.ArenaAllocator.init(aa);
    defer arena.deinit();
    const tmp = arena.child_allocator;

    while (db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW) {
        const id = db.c.sqlite3_column_int64(stmt, 0);
        const ts = db.c.sqlite3_column_int64(stmt, 1);
        const source_ptr = db.c.sqlite3_column_text(stmt, 2);
        const source_len = db.c.sqlite3_column_bytes(stmt, 2);
        const kind_ptr = db.c.sqlite3_column_text(stmt, 3);
        const kind_len = db.c.sqlite3_column_bytes(stmt, 3);
        const payload_ptr = db.c.sqlite3_column_text(stmt, 4);
        const payload_len = db.c.sqlite3_column_bytes(stmt, 4);

        const source = source_ptr[0..@intCast(source_len)];
        const kind = kind_ptr[0..@intCast(kind_len)];
        const payload_json = payload_ptr[0..@intCast(payload_len)];

        // Parsear payload una vez para extraer campos derivados (stream, etc.).
        var parsed = std.json.parseFromSlice(std.json.Value, tmp, payload_json, .{}) catch null;
        const payload = if (parsed) |*p| &p.value else null;

        const title = eventTitle(tmp, kind, source, payload) catch kind;
        const severity = eventSeverity(kind, payload);

        js.beginObject() catch continue;
        js.objectField("id") catch continue;
        js.write(id) catch continue;
        js.objectField("ts") catch continue;
        js.write(ts) catch continue;
        js.objectField("source") catch continue;
        js.write(source) catch continue;
        js.objectField("kind") catch continue;
        js.write(kind) catch continue;
        js.objectField("title") catch continue;
        js.write(title) catch continue;
        js.objectField("severity") catch continue;
        js.write(severity) catch continue;
        js.objectField("payload") catch continue;
        if (payload) |p| js.write(p.*) catch continue else js.write(std.json.Value{ .null = {} }) catch continue;
        js.endObject() catch continue;

        if (parsed) |*p| p.deinit();
    }
    js.endArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_order_events_json: OOM"));
        return @intFromEnum(ok());
    };
    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_order_events_json: OOM"));
    return @intFromEnum(ok());
}

/// UI-ACTION: registra una acción cosmética pedida por un agente/cliente externo.
/// `action_json` = `{"action":"set_theme","args":{...}}` — `action` debe pasar el
/// allowlist de `executor.zig` (única fuente, la misma que usan la tarea `ui` y la
/// tool `ui_action`). `order_id=0` = acción global (sin orden). Inserta un evento
/// kind='ui_action' y devuelve su id en `out_event_id` — el ack vuelve por
/// `da_ui_action_ack` y se lee con `da_ui_actions_poll`.
pub export fn da_ui_action_request(handle: ?*anyopaque, action_json: ?[*:0]const u8, order_id: i64, out_event_id: *i64) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_ui_action_request: null handle"));
    if (action_json == null) return @intFromEnum(err(.invalid_arg, "da_ui_action_request: null action_json"));
    const st: *CoreState = @ptrCast(@alignCast(handle));

    const raw = std.mem.span(action_json.?);
    if (raw.len > 8192) return @intFromEnum(err(.invalid_arg, "da_ui_action_request: payload too large"));

    var parsed = std.json.parseFromSlice(std.json.Value, std.heap.c_allocator, raw, .{}) catch
        return @intFromEnum(err(.invalid_arg, "da_ui_action_request: invalid JSON"));
    defer parsed.deinit();
    if (parsed.value != .object) return @intFromEnum(err(.invalid_arg, "da_ui_action_request: payload must be an object"));
    const action_v = parsed.value.object.get("action") orelse
        return @intFromEnum(err(.invalid_arg, "da_ui_action_request: missing action"));
    if (action_v != .string or action_v.string.len == 0) return @intFromEnum(err(.invalid_arg, "da_ui_action_request: action must be a string"));
    if (!executor.uiActionAllowed(action_v.string))
        return @intFromEnum(err(.invalid_arg, "da_ui_action_request: action not in allowlist"));
    if (parsed.value.object.get("args")) |args_v| {
        if (args_v != .object) return @intFromEnum(err(.invalid_arg, "da_ui_action_request: args must be an object"));
        var ait = args_v.object.iterator();
        while (ait.next()) |entry| {
            const known = std.mem.eql(u8, entry.key_ptr.*, "theme") or std.mem.eql(u8, entry.key_ptr.*, "view") or std.mem.eql(u8, entry.key_ptr.*, "session_id") or std.mem.eql(u8, entry.key_ptr.*, "text");
            if (!known) return @intFromEnum(err(.invalid_arg, "da_ui_action_request: unknown args key"));
            if (entry.value_ptr.* != .string or entry.value_ptr.string.len > 256) return @intFromEnum(err(.invalid_arg, "da_ui_action_request: args values must be short strings"));
        }
    }

    const stmt = st.db_conn.prepare("INSERT INTO events (ts, source, kind, payload_json, order_id) VALUES (?, ?, 'ui_action', ?, ?)") catch
        return @intFromEnum(err(.internal, "da_ui_action_request: prepare failed"));
    defer st.db_conn.finalize(stmt);
    db.bindInt(stmt, 1, health.nowMillis(st.db_conn)) catch {};
    db.bindText(stmt, 2, "ui") catch {};
    db.bindText(stmt, 3, raw) catch {};
    db.bindInt(stmt, 4, order_id) catch {};
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE)
        return @intFromEnum(err(.internal, "da_ui_action_request: insert failed"));
    out_event_id.* = db.c.sqlite3_last_insert_rowid(st.db_conn.db);
    return @intFromEnum(ok());
}

/// UI-ACTION: polling incremental de acciones y sus acks. Devuelve
/// [{id,ts,kind,payload,order_id}] con kind ∈ {ui_action, ui_action_result} e
/// id > since_id. La cabina lo sondea (~1 s) y también ve las acciones que
/// lleguen por el stream de la orden (mission_control las despacha igual).
pub export fn da_ui_actions_poll(handle: ?*anyopaque, since_id: i64, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_ui_actions_poll: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    // Solo acciones PENDIENTES: una ui_action que ya tiene su ui_action_result
    // no vuelve a salir. Antes el sondeo devolvía el historial completo, así
    // que cada carga de la cabina (lastId=0) re-aplicaba y re-ackeaba todas las
    // acciones jamás pedidas — una ráfaga de ~100 llamadas que dejaba el
    // bridge mudo ~1 min tras cada reload.
    const stmt = st.db_conn.prepare(
        "SELECT id, ts, kind, payload_json, order_id FROM events WHERE id > ? AND (" ++
            "kind = 'ui_action_result' OR (" ++
            "kind = 'ui_action' AND NOT EXISTS (" ++
            "SELECT 1 FROM events r WHERE r.kind = 'ui_action_result' " ++
            "AND json_extract(r.payload_json, '$.action_id') = events.id))) ORDER BY id ASC",
    ) catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_ui_actions_poll: OOM"));
        return @intFromEnum(ok());
    };
    defer st.db_conn.finalize(stmt);
    db.bindInt(stmt, 1, since_id) catch {};

    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_ui_actions_poll: OOM"));
        return @intFromEnum(ok());
    };
    var arena = std.heap.ArenaAllocator.init(aa);
    defer arena.deinit();
    const tmp = arena.child_allocator;

    while (db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW) {
        const payload_ptr = db.c.sqlite3_column_text(stmt, 3);
        const payload_len = db.c.sqlite3_column_bytes(stmt, 3);
        const kind_ptr = db.c.sqlite3_column_text(stmt, 2);
        const kind_len = db.c.sqlite3_column_bytes(stmt, 2);
        js.beginObject() catch continue;
        js.objectField("id") catch continue;
        js.write(db.c.sqlite3_column_int64(stmt, 0)) catch continue;
        js.objectField("ts") catch continue;
        js.write(db.c.sqlite3_column_int64(stmt, 1)) catch continue;
        js.objectField("kind") catch continue;
        js.write(kind_ptr[0..@intCast(kind_len)]) catch continue;
        js.objectField("payload") catch continue;
        const payload_json = payload_ptr[0..@intCast(payload_len)];
        var parsed = std.json.parseFromSlice(std.json.Value, tmp, payload_json, .{}) catch null;
        if (parsed) |*p| {
            js.write(p.value) catch continue;
            p.deinit();
        } else {
            js.write(std.json.Value{ .null = {} }) catch continue;
        }
        js.objectField("order_id") catch continue;
        js.write(db.c.sqlite3_column_int64(stmt, 4)) catch continue;
        js.endObject() catch continue;
    }
    js.endArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_ui_actions_poll: OOM"));
        return @intFromEnum(ok());
    };
    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_ui_actions_poll: OOM"));
    return @intFromEnum(ok());
}

/// UI-ACTION: la cabina reporta el resultado de aplicar una acción — cierra el
/// loop para el agente/cliente que la pidió. `detail` es opcional (p. ej. el
/// tema aplicado o la razón del fallo).
pub export fn da_ui_action_ack(handle: ?*anyopaque, action_id: i64, ok_flag: c_int, detail: ?[*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_ui_action_ack: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));

    const detail_slice: []const u8 = if (detail) |d| std.mem.span(d) else "";
    if (detail_slice.len > 1024) return @intFromEnum(err(.invalid_arg, "da_ui_action_ack: detail too large"));

    var out: std.Io.Writer.Allocating = .init(st.arena.child_allocator);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginObject() catch return @intFromEnum(err(.internal, "da_ui_action_ack: encode failed"));
    js.objectField("action_id") catch return @intFromEnum(err(.internal, "da_ui_action_ack: encode failed"));
    js.write(action_id) catch return @intFromEnum(err(.internal, "da_ui_action_ack: encode failed"));
    js.objectField("ok") catch return @intFromEnum(err(.internal, "da_ui_action_ack: encode failed"));
    js.write(ok_flag != 0) catch return @intFromEnum(err(.internal, "da_ui_action_ack: encode failed"));
    if (detail_slice.len > 0) {
        js.objectField("detail") catch return @intFromEnum(err(.internal, "da_ui_action_ack: encode failed"));
        js.write(detail_slice) catch return @intFromEnum(err(.internal, "da_ui_action_ack: encode failed"));
    }
    js.endObject() catch return @intFromEnum(err(.internal, "da_ui_action_ack: encode failed"));

    const stmt = st.db_conn.prepare("INSERT INTO events (ts, source, kind, payload_json, order_id) VALUES (?, 'ui', 'ui_action_result', ?, 0)") catch
        return @intFromEnum(err(.internal, "da_ui_action_ack: prepare failed"));
    defer st.db_conn.finalize(stmt);
    db.bindInt(stmt, 1, health.nowMillis(st.db_conn)) catch {};
    db.bindText(stmt, 2, out.written()) catch {};
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE)
        return @intFromEnum(err(.internal, "da_ui_action_ack: insert failed"));
    return @intFromEnum(ok());
}

/// UX-08: título legible derivado de kind/source/payload para el timeline.
fn payloadString(payload: ?*const std.json.Value, key: []const u8) []const u8 {
    const p = payload orelse return "";
    if (p.* != .object) return "";
    const v = p.object.get(key) orelse return "";
    return if (v == .string) v.string else "";
}

/// UX-08: título legible derivado de kind/source/payload para el timeline.
fn eventTitle(allocator: std.mem.Allocator, kind: []const u8, source: []const u8, payload: ?*const std.json.Value) std.mem.Allocator.Error![]const u8 {
    if (std.mem.eql(u8, kind, "worker_output")) {
        const stream = payloadString(payload, "stream");
        if (std.mem.eql(u8, source, "superagente")) return try allocator.dupe(u8, "Reporte consolidado");
        if (std.mem.eql(u8, stream, "stderr")) return try std.fmt.allocPrint(allocator, "Error de {s}", .{source});
        if (std.mem.eql(u8, stream, "reporte")) return try std.fmt.allocPrint(allocator, "Reporte de {s}", .{source});
        return try std.fmt.allocPrint(allocator, "Salida de {s}", .{source});
    }
    if (std.mem.eql(u8, kind, "timeout")) return try allocator.dupe(u8, "Timeout de tarea");
    if (std.mem.eql(u8, kind, "retry")) return try allocator.dupe(u8, "Reintentando tarea");
    if (std.mem.eql(u8, kind, "escalated")) return try allocator.dupe(u8, "Tarea escalada");
    if (std.mem.eql(u8, kind, "unhealthy")) return try allocator.dupe(u8, "Worker no responde");
    if (std.mem.eql(u8, kind, "restart")) return try allocator.dupe(u8, "Worker reiniciado");
    if (std.mem.eql(u8, kind, "provider_failed")) return try allocator.dupe(u8, "Fallo de proveedor");
    if (std.mem.eql(u8, kind, "provider_fallback")) return try allocator.dupe(u8, "Fallback a proveedor");
    if (std.mem.eql(u8, kind, "provider_exhausted")) return try allocator.dupe(u8, "Proveedores agotados");
    if (std.mem.eql(u8, kind, "provider_contract_abort")) return try allocator.dupe(u8, "Cadena detenida: respuesta sin formato usable");
    if (std.mem.eql(u8, kind, "order_running")) return try allocator.dupe(u8, "Orden en ejecución");
    if (std.mem.eql(u8, kind, "order_done")) return try allocator.dupe(u8, "Orden completada");
    if (std.mem.eql(u8, kind, "order_failed")) return try allocator.dupe(u8, "Orden fallida");
    if (std.mem.eql(u8, kind, "task_started")) return try allocator.dupe(u8, "Tarea iniciada");
    if (std.mem.eql(u8, kind, "task_done")) return try allocator.dupe(u8, "Tarea completada");
    if (std.mem.eql(u8, kind, "task_failed")) return try allocator.dupe(u8, "Tarea fallida");
    if (std.mem.eql(u8, kind, "approval_needed")) return try allocator.dupe(u8, "Aprobación pendiente");
    if (std.mem.eql(u8, kind, "reasoning_delta")) return try allocator.dupe(u8, "Razonamiento");
    if (std.mem.eql(u8, kind, "content_delta")) return try allocator.dupe(u8, "Generando respuesta");
    if (std.mem.eql(u8, kind, "file_written")) return try allocator.dupe(u8, "Archivo escrito");
    if (std.mem.eql(u8, kind, "shell_command")) return try allocator.dupe(u8, "Comando shell");
    return try std.fmt.allocPrint(allocator, "{s}", .{kind});
}

/// UX-08: severidad visual (info/warning/error) derivada de kind/payload.
fn eventSeverity(kind: []const u8, payload: ?*const std.json.Value) []const u8 {
    if (std.mem.eql(u8, kind, "worker_output")) {
        const stream = payloadString(payload, "stream");
        if (std.mem.eql(u8, stream, "stderr")) return "error";
        return "info";
    }
    if (std.mem.eql(u8, kind, "timeout") or
        std.mem.eql(u8, kind, "escalated") or
        std.mem.eql(u8, kind, "unhealthy") or
        std.mem.eql(u8, kind, "provider_exhausted") or
        std.mem.eql(u8, kind, "provider_contract_abort") or
        std.mem.eql(u8, kind, "provider_failed")) return "error";
    if (std.mem.eql(u8, kind, "retry") or
        std.mem.eql(u8, kind, "restart") or
        std.mem.eql(u8, kind, "provider_fallback") or
        std.mem.eql(u8, kind, "approval_needed")) return "warning";
    if (std.mem.eql(u8, kind, "task_failed") or
        std.mem.eql(u8, kind, "order_failed")) return "error";
    if (std.mem.eql(u8, kind, "shell_command")) {
        const status = payloadString(payload, "status");
        if (std.mem.eql(u8, status, "done")) {
            const exit_str = payloadString(payload, "exit_code");
            if (exit_str.len > 0 and !std.mem.eql(u8, exit_str, "0")) return "error";
        }
        return "info";
    }
    if (std.mem.eql(u8, kind, "file_written")) return "info";
    if (std.mem.eql(u8, kind, "order_running") or
        std.mem.eql(u8, kind, "order_done") or
        std.mem.eql(u8, kind, "task_started") or
        std.mem.eql(u8, kind, "task_done") or
        std.mem.eql(u8, kind, "reasoning_delta") or
        std.mem.eql(u8, kind, "content_delta")) return "info";
    return "info";
}

pub export fn da_memory_context_json(handle: ?*anyopaque, project: [*:0]const u8, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_memory_context_json: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    const proj = std.mem.span(project);

    if (st.memory.backend().loadContext(aa, proj)) |ctx| {
        defer aa.free(ctx);
        out_json.* = ownedCStr(ctx) orelse return @intFromEnum(err(.oom, "da_memory_context_json: OOM"));
    } else {
        const fallback = "{\"sessions\":[],\"findings\":[],\"note\":\"Sin datos de memoria para este proyecto.\"}";
        out_json.* = ownedCStr(fallback) orelse return @intFromEnum(err(.oom, "da_memory_context_json: OOM"));
    }
    return @intFromEnum(ok());
}

pub export fn da_approval_pending_json(handle: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_approval_pending_json: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_approval_pending_json: OOM"));
        return @intFromEnum(ok());
    };
    // (H-PB-6): el Monitor es la vista de esta función. Antes de
    // listar, reconciliar lo que un terminal no cerró en su momento (p. ej. el
    // commit del superagente, que no pasa por c_api): ninguna tarjeta de una
    // orden ya terminada debe salir. Cierra en DB y en memoria, idempotente.
    closeStaleApprovals(st, st.db_conn, false, health.nowMillis(st.db_conn), "orden terminada");
    st.output_mutex.lock();
    defer st.output_mutex.unlock();
    for (st.approvals.items) |a| {
        if (a.resolved) continue;
        // T12B M-1 (auditor 3): una sesión MCP solo ve sus propias tarjetas;
        // la cabina (sin mcp_surface) sigue viendo la bandeja entera porque es
        // quien aprueba. `mcp_owned_approvals` está protegida por output_mutex,
        // que ya se toma arriba.
        if (st.mcp_surface and std.mem.indexOfScalar(i64, st.mcp_owned_approvals.items, a.id) == null) continue;
        // MCP y UI son procesos distintos: para shell_command la tabla es
        // autoritativa y evita mostrar una copia de memoria ya resuelta por UI.
        if (a.command_prefix) |prefix| if (std.mem.eql(u8, prefix, "shell_command")) continue;
        js.beginObject() catch continue;
        js.objectField("id") catch continue;
        js.write(a.id) catch continue;
        js.objectField("task_id") catch continue;
        js.write(a.task_id) catch continue;
        js.objectField("description") catch continue;
        js.write(a.description) catch continue;
        js.objectField("command_prefix") catch continue;
        js.write(a.command_prefix orelse "") catch continue;
        js.objectField("exe") catch continue;
        js.write(a.exe orelse "") catch continue;
        // E5.05: args_json para que la tarjeta de aprobación muestre el
        // script y su sha256 (command_prefix 'worktree_script').
        js.objectField("args_json") catch continue;
        js.write(a.args_json orelse "") catch continue;
        js.objectField("order_id") catch continue;
        js.write(a.order_id) catch continue;
        js.endObject() catch continue;
    }
    // E5.05: las aprobaciones 'worktree_script' viven SOLO en la tabla — la
    // preparación del worktree las inserta fuera de la lista en memoria, así
    // que sin esta unión ni la cabina ni approvals_list del MCP las verían
    // (medido en vivo: la orden caía pending_approval y la lista salía []).
    {
        var seen = std.AutoHashMap(i64, void).init(aa);
        defer seen.deinit();
        for (st.approvals.items) |a| {
            // Solo deduplicar las tarjetas emitidas arriba. Tras reiniciar,
            // las cargadas de DB aún no están en mcp_owned_approvals: su
            // origen persistido se comprueba en la unión que sigue.
            if (a.resolved) continue;
            if (st.mcp_surface and std.mem.indexOfScalar(i64, st.mcp_owned_approvals.items, a.id) == null) continue;
            if (a.command_prefix) |prefix| if (std.mem.eql(u8, prefix, "shell_command")) continue;
            seen.put(a.id, {}) catch {};
        }
        // r4 (auditoría el segundo auditor): las solicitudes de archivar/podar
        // spaces las inserta el servidor MCP fuera de la lista en memoria con
        // el prefijo "spaces_mcp"; sin esta unión la cabina nunca las mostraba
        // y el humano no podía concederlas. La resolución sigue siendo la
        // misma: da_approval_resolve (core.approvals.resolve del puente).
        const sel = st.db_conn.prepare(
            "SELECT id, task_id, description, command_prefix, args_json, order_id, exe, origin FROM approvals WHERE resolved = 0 AND (command_prefix IN (?, ?, ?, ?, ?, ?) OR origin <> '')",
        ) catch null;
        if (sel) |s| {
            defer st.db_conn.finalize(s);
            db.bindText(s, 1, worktree_prepare.APPROVAL_PREFIX) catch {};
            // E5.09: las tarjetas 'agent_acp' (permiso de comando del agente
            // externo vía puente ACP) también se persisten fuera de la lista
            // en memoria — medido en vivo: la orden quedaba esperando una
            // tarjeta que la cabina nunca mostraba.
            db.bindText(s, 2, external_agents.ACP_APPROVAL_PREFIX) catch {};
            db.bindText(s, 3, command_approval.PREFIX) catch |e| std.log.err("approval list inline bind: {s}", .{@errorName(e)});
            db.bindText(s, 4, "shell_command") catch |e| std.log.err("approval list shell bind: {s}", .{@errorName(e)});
            db.bindText(s, 5, "spaces_mcp") catch |e| std.log.err("approval list spaces bind: {s}", .{@errorName(e)});
            db.bindText(s, 6, SCREEN_CAPTURE_PREFIX) catch |e| std.log.err("approval list capture bind: {s}", .{@errorName(e)});
            while (db.c.sqlite3_step(s) == db.c.SQLITE_ROW) {
                const id = db.c.sqlite3_column_int64(s, 0);
                if (seen.contains(id)) continue;
                // T12B M-1: la unión de la tabla tampoco puede saltarse el
                // filtro de sesión (worktree_script, agent_acp, spaces_mcp…).
                // T12B B-2: además de la lista en memoria, cuenta el origen
                // persistido, que sobrevive a reiniciar el proceso MCP.
                if (st.mcp_surface and std.mem.indexOfScalar(i64, st.mcp_owned_approvals.items, id) == null) {
                    const row_origin = approvalColText(s, 7);
                    if (st.mcp_origin.len == 0 or !std.mem.eql(u8, row_origin, st.mcp_origin)) continue;
                }
                js.beginObject() catch continue;
                js.objectField("id") catch continue;
                js.write(id) catch continue;
                js.objectField("task_id") catch continue;
                js.write(approvalColText(s, 1)) catch continue;
                js.objectField("description") catch continue;
                js.write(approvalColText(s, 2)) catch continue;
                js.objectField("command_prefix") catch continue;
                js.write(approvalColText(s, 3)) catch continue;
                js.objectField("exe") catch continue;
                js.write(approvalColText(s, 6)) catch continue;
                js.objectField("args_json") catch continue;
                js.write(approvalColText(s, 4)) catch continue;
                js.objectField("order_id") catch continue;
                js.write(db.c.sqlite3_column_int64(s, 5)) catch continue;
                js.endObject() catch continue;
            }
        }
    }
    js.endArray() catch {
        out_json.* = ownedCStr("[]") orelse return @intFromEnum(err(.oom, "da_approval_pending_json: OOM"));
        return @intFromEnum(ok());
    };
    // F2: el borde entrega [*:0]u8 → ownedCStr garantiza NUL (antes dupe sin sentinel
    // → over-read en QString::fromUtf8) y propiedad del caller (c_allocator).
    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_approval_pending_json: OOM"));
    return @intFromEnum(ok());
}

/// Texto de una columna de `approvals`, tolerante a NULL (exe/args_json lo son).
fn approvalColText(stmt: anytype, col: c_int) []const u8 {
    if (db.c.sqlite3_column_type(stmt, col) == db.c.SQLITE_NULL) return "";
    const t = db.c.sqlite3_column_text(stmt, col);
    if (t == null) return "";
    return std.mem.span(t);
}

/// r5/r6: cierre común cuando una ejecución aprobada NO llega a
/// lanzar (o su resultado fue cancelado): la orden cierra `cancelled` por la
/// MISMA autoridad transaccional (tryCommitTerminal), la memoria refleja lo
/// que confirme la DB y se cierran las aprobaciones pendientes — nada de
/// `running`/awaiting_approval colgado ni tarjeta sin cerrar.
fn closeCancelledResume(st: *CoreState, order_id: i64) void {
    const cancel_now = health.nowMillis(st.db_conn);
    const won = st.db_conn.tryCommitTerminal(order_id, "cancelled", "order_cancelled", "usuario", "\"orden cancelada durante la ejecucion aprobada\"", cancel_now) catch false;
    if (findOrder(st, order_id)) |rec_cancel| {
        if (won) rec_cancel.status = .cancelled else syncRecStatusFromDb(st.db_conn, rec_cancel);
    }
    closeStaleApprovals(st, st.db_conn, false, cancel_now, "orden cancelada");
}

/// P-EXEC-4: re-ejecuta el comando almacenado en la aprobación tras ser aprobada.
/// Usa executor.runGoverned con la misma política que governedExecuteRaw.
/// Captura stdout/exit, emite evento shell_command status:done, y añade output.
fn resumeExecutionApproval(st: *CoreState, aa: std.mem.Allocator, approval_id: i64, spawn_fn: ?executor.SpawnFn) !void {
    // Leer exe + args_json de la aprobación (bajo mutex).
    var exe_dup: ?[]const u8 = null;
    var args_json_dup: ?[]const u8 = null;
    var task_id_dup: ?[]const u8 = null;
    var order_id: i64 = 0;
    defer if (exe_dup) |e| aa.free(e);
    defer if (args_json_dup) |a| aa.free(a);
    defer if (task_id_dup) |t| aa.free(t);

    // La aprobación shell conserva el cwd/timeout revisados por el humano.
    // Las aprobaciones antiguas siguen almacenando solamente el array de argv.
    var approved_cwd: ?[]u8 = null;
    defer if (approved_cwd) |c| aa.free(c);
    var approved_timeout: u32 = 10_000;
    var approved_detached = false;

    st.output_mutex.lock();
    {
        defer st.output_mutex.unlock();
        for (st.approvals.items) |*a| {
            if (a.id == approval_id) {
                if (a.exe) |e| exe_dup = try aa.dupe(u8, e);
                if (a.args_json) |aj| args_json_dup = try aa.dupe(u8, aj);
                task_id_dup = try aa.dupe(u8, a.task_id);
                order_id = a.order_id;
                break;
            }
        }
    }

    if (exe_dup == null) {
        // La UI puede resolver una tarjeta creada por otro proceso MCP.
        const query = try st.db_conn.prepare("SELECT exe, args_json, task_id, order_id FROM approvals WHERE id=? AND command_prefix='shell_command' AND resolved=1 AND approved=1");
        defer st.db_conn.finalize(query);
        try db.bindInt(query, 1, approval_id);
        if (db.c.sqlite3_step(query) != db.c.SQLITE_ROW) return error.InvalidArguments;
        exe_dup = try aa.dupe(u8, approvalColText(query, 0));
        if (args_json_dup) |a| aa.free(a);
        args_json_dup = null;
        args_json_dup = try aa.dupe(u8, approvalColText(query, 1));
        if (task_id_dup) |t| aa.free(t);
        task_id_dup = null;
        task_id_dup = try aa.dupe(u8, approvalColText(query, 2));
        order_id = db.c.sqlite3_column_int64(query, 3);
    }
    const exe = exe_dup.?;
    const task_id = task_id_dup orelse "executor";

    // r4 (auditoría el segundo auditor, punto 3): la última comprobación del estado
    // de la orden se movió JUSTO antes de emitir `running`/lanzar el ejecutor y
    // va en la MISMA transacción BEGIN IMMEDIATE que ese INSERT (más abajo). La
    // reclamación (claimCommandApproval) ya comprobó el estado, pero otra vía
    // pudo terminar (o borrar) la orden después; mantener la comprobación aquí
    // dejaba una ventana hasta el arranque del proceso.

    // Parse args_json → []const []const u8
    var args = std.ArrayList([]const u8).empty;
    defer {
        for (args.items) |a_item| aa.free(a_item);
        args.deinit(aa);
    }
    if (args_json_dup) |aj| {
        var parsed = try std.json.parseFromSlice(std.json.Value, aa, aj, .{});
        defer parsed.deinit();
        const argv = if (parsed.value == .object) blk: {
            const obj = parsed.value.object;
            if (obj.get("cwd")) |v| {
                if (v != .string) return error.InvalidArguments;
                approved_cwd = try aa.dupe(u8, v.string);
            }
            if (obj.get("detached")) |v| {
                if (v != .bool) return error.InvalidArguments;
                approved_detached = v.bool;
            }
            if (obj.get("timeout_ms")) |v| {
                if (v == .integer and v.integer > 0 and v.integer <= 300_000) approved_timeout = @intCast(v.integer);
            }
            break :blk obj.get("args") orelse return error.InvalidArguments;
        } else parsed.value;
        if (argv == .array) {
            for (argv.array.items) |item| {
                if (item != .string) return error.InvalidArguments;
                const dup = try aa.dupe(u8, item.string);
                args.append(aa, dup) catch |e| {
                    aa.free(dup);
                    return e;
                };
            }
        } else return error.InvalidArguments;
    }

    // D3-FIX: Usar effectiveRoot (lógica centralizada) para resolver la raíz efectiva.
    // Esto garantiza que resumeExecutionApproval use la MISMA raíz que persistTask,
    // evitando PathOutsideSandbox al aprobar una ejecución previamente bloqueada.
    var er_buf: [4096]u8 = undefined;
    var project_buf: [4096]u8 = undefined;
    const effective_root = workspace.effectiveRoot(&er_buf);
    // QA-B 2b: un comando pedido con `"root":"project"` (git_commit del MCP)
    // se aprobó con un cwd de la carpeta del proyecto: su sandbox es ella.
    const approval_root = if (approved_cwd) |c| blk: {
        if (workspace.resolvesInside(c, effective_root)) break :blk effective_root;
        const project = workspace.projectOrEffectiveRoot(&project_buf);
        break :blk if (workspace.resolvesInside(c, project)) project else effective_root;
    } else effective_root;
    const cwd = approved_cwd orelse approval_root;
    const timeout_ms = approved_timeout;

    // r5 (cierre del hallazgo bloqueante de la auditoría r4): la
    // ejecución reanudada queda cubierta por el MISMO mecanismo de cancelación
    // del despacho (DispatchRegistry + live_worker.CancellationToken, igual
    // secuencia que da_order_dispatch_async). La entrada se registra ANTES de
    // la transacción del evento `running` para que da_order_cancel encuentre un
    // despacho activo y marque el token en vez de comprometer el terminal por
    // la vía (reservada a órdenes sin dispatch). Si la cancelación llegara
    // antes del registro, la comprobación intra-transacción de orderLiveness ya
    // impide el lanzamiento. Las ejecuciones detached no registran nada: no hay
    // hijo supervisado que cubrir (runDetached no consulta el token).
    var cancel_token: ?*const live_worker.CancellationToken = null;
    var resume_cancel_registered = false;
    var resume_token_owned: ?*live_worker.CancellationToken = null;
    var resume_cancel_finished_ok = true;
    defer {
        // Cierra la entrada del registro y suelta las referencias — en el
        // mismo orden que el despacho: finish (marca), joinIfFinished (saca y
        // libera la referencia del registro), release (la referencia propia).
        if (resume_cancel_registered) {
            st.dispatch_registry.finish(order_id, resume_cancel_finished_ok);
            st.dispatch_registry.joinIfFinished(order_id);
        }
        if (resume_token_owned) |tok| tok.release();
    }
    if (order_id > 0 and !approved_detached) {
        const is_memory = std.mem.eql(u8, st.runtime_path, ":memory:");
        if (st.dispatch_registry.beginWithTimeout(order_id, is_memory, GetTickCount64(), timeout_ms)) |_| {
            resume_cancel_registered = true;
            // Page allocator (como el despacho async): el token puede sobrevivir
            // a este scope vía referencias del registro.
            if (live_worker.CancellationToken.create(std.heap.page_allocator)) |tok| {
                if (st.dispatch_registry.attachCancellationToken(order_id, tok)) {
                    resume_token_owned = tok;
                    cancel_token = tok;
                } else {
                    // La entrada desapareció (cierre en curso): sin registro no
                    // hay cobertura por token; el sondeo de terminalidad del
                    // callback sigue cubriendo la cancelación vía DB.
                    st.dispatch_registry.abortNeverStarted(order_id);
                    resume_cancel_registered = false;
                    tok.release();
                }
            } else |_| {
                // OOM del token: se retira la entrada para no dejar un despacho
                // «activo» sin token (da_order_cancel caería en invalid_state);
                // sin entrada, su vía compromete el terminal y el sondeo
                // de terminalidad del callback mata al hijo igualmente.
                st.dispatch_registry.abortNeverStarted(order_id);
                resume_cancel_registered = false;
            }
        } else |err_begin| switch (err_begin) {
            // Ya hay un despacho en vuelo para esta orden (p. ej. el hilo que la
            // aparcó aún no llamó a finish): se usa SU token, que es el mismo
            // que da_order_cancel marcará a través de esa entrada.
            error.DuplicateOrder => {
                if (st.dispatch_registry.retainCancellationToken(order_id)) |tok| {
                    resume_token_owned = @constCast(tok);
                    cancel_token = tok;
                }
            },
            // :memory: ocupado por otra orden / cierre / OOM: se sigue sin token
            // propio; el sondeo de terminalidad del callback (abajo) mantiene la
            // coherencia igualmente.
            else => {},
        }
    }

    const ResumeCancelCtx = struct {
        token: ?*const live_worker.CancellationToken = null,
        st: *CoreState,
        order_id: i64,
        ticks: u32 = 0,

        /// Comprobación COMPLETA (token + terminalidad real en la DB) para los
        /// puntos de decisión — justo antes de lanzar —, no para cada vuelta.
        fn cancelled(self: *@This()) bool {
            if (self.token) |tok| {
                if (tok.isCancelled()) return true;
            }
            if (self.order_id <= 0) return false;
            return orderLiveness(self.st.db_conn, self.order_id) != .live;
        }

        /// Callback del bucle de espera del executor: el token se mira en cada
        /// vuelta (≈1 ms); la terminalidad en la DB cada ~100 ms para no
        /// castigar la conexión. Cubre también fines/cancelaciones comprometidos
        /// por vías que no pasan por el token.
        fn check(raw: ?*anyopaque) bool {
            const self: *@This() = @ptrCast(@alignCast(raw.?));
            if (self.token) |tok| {
                if (tok.isCancelled()) return true;
            }
            if (self.order_id <= 0) return false;
            self.ticks +%= 1;
            if (self.ticks % 100 != 0) return false;
            return orderLiveness(self.st.db_conn, self.order_id) != .live;
        }
    };
    var resume_cancel = ResumeCancelCtx{ .token = cancel_token, .st = st, .order_id = order_id };

    // Línea efectiva completa: viaja en cada evento para que la UI correlacione
    // running→delta→done y muestre el comando real, no solo el exe.
    const display = try executor.renderCommandLine(aa, exe, args.items);
    defer aa.free(display);

    // El `running` se emite al aprobar — la card del comando aparece en ese
    // instante (estado "ejecutando") y no espera al primer chunk de salida,
    // igual que en governedExecuteRawAtCwd.
    //
    // r4 (auditoría el segundo auditor, punto 3): la última comprobación del estado
    // de la orden y el INSERT del evento `running` van en la MISMA transacción
    // BEGIN IMMEDIATE. La transición a terminal de una orden (tryCommitTerminal)
    // también usa BEGIN IMMEDIATE, así que la comprobación queda serializada con
    // ella: no puede colarse un fin/borrado de orden entre comprobar y reservar.
    // Si la orden ya es terminal o no existe, ROLLBACK y no se lanza nada. Tras
    // el COMMIT queda la ventana hasta el arranque del proceso (ver informe §7
    // sobre si la transición terminal mata o espera al ejecutor: no lo hace).
    {
        st.db_conn.exec("BEGIN IMMEDIATE") catch return error.ExecFailed;
        var committed = false;
        // Cualquier `return`/error antes del COMMIT revierte la transacción
        // (incluido un OOM al serializar el payload), para no dejar el enlace
        // SQLite abierto con un BEGIN pendiente.
        defer if (!committed) st.db_conn.exec("ROLLBACK") catch {};
        if (order_id > 0) {
            switch (orderLiveness(st.db_conn, order_id)) {
                .live => {},
                .terminal => return error.OrderTerminal,
                .missing => return error.OrderMissing,
            }
        }
        // Un fallo de memoria no puede producir JSON parcial ni un spawn sin
        // el evento que muestra qué comando aprobó el humano.
        const payload = try std.json.Stringify.valueAlloc(aa, .{
            .command = display,
            .exe = exe,
            .task_id = task_id,
            .status = "running",
            .approval_id = approval_id,
        }, .{});
        defer aa.free(payload);
        const stmt = try st.db_conn.prepare("INSERT INTO events (ts, source, kind, payload_json, order_id) VALUES (?, ?, 'shell_command', ?, ?)");
        defer st.db_conn.finalize(stmt);
        try db.bindInt(stmt, 1, health.nowMillis(st.db_conn));
        try db.bindText(stmt, 2, "executor");
        try db.bindText(stmt, 3, payload);
        try db.bindInt(stmt, 4, order_id);
        if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE) return error.ExecFailed;
        st.db_conn.exec("COMMIT") catch return error.ExecFailed;
        committed = true;
    }

    if (approved_detached) {
        // r6 (auditoría el segundo auditor r5, P1-a): la comprobación previa al
        // lanzamiento también cubre la rama detached — si la orden se canceló
        // o llegó a terminal tras el COMMIT del evento `running` y antes de
        // aquí, NO se invoca runDetached (token si lo hubiera + orderLiveness
        // en DB; en esta ruta no hay entrada de registro propia, así que la
        // comprobación efectiva es la terminalidad real). La cancelación
        // DURANTE una ejecución detached queda FUERA del alcance: no hay hijo
        // supervisado (runDetached devuelve el PID y desengancha).
        if (resume_cancel.cancelled()) {
            closeCancelledResume(st, order_id);
            // El `running` emitido arriba no queda colgado: mismo contrato que
            // la ruta supervisada (done + cancelled + exit 130).
            const cancel_payload = try std.json.Stringify.valueAlloc(aa, .{
                .command = display,
                .exe = exe,
                .task_id = task_id,
                .status = "done",
                .approval_id = approval_id,
                .pid = @as(u32, 0),
                .cancelled = true,
                .exit_code = @as(i32, 130),
                .detached = true,
            }, .{});
            defer aa.free(cancel_payload);
            const cancel_stmt = try st.db_conn.prepare("INSERT INTO events (ts, source, kind, payload_json, order_id) VALUES (?, ?, 'shell_command', ?, ?)");
            defer st.db_conn.finalize(cancel_stmt);
            try db.bindInt(cancel_stmt, 1, health.nowMillis(st.db_conn));
            try db.bindText(cancel_stmt, 2, "executor");
            try db.bindText(cancel_stmt, 3, cancel_payload);
            try db.bindInt(cancel_stmt, 4, order_id);
            if (db.c.sqlite3_step(cancel_stmt) != db.c.SQLITE_DONE) return error.ExecFailed;
            return;
        }
        const result = executor.runDetached(aa, .{ .workspace_root = approval_root }, exe, args.items, cwd);
        const pid = if (result) |r| r.pid else |_| @as(u32, 0);
        const failure = if (result) |_| "" else |e| @errorName(e);
        const payload = try std.json.Stringify.valueAlloc(aa, .{
            .command = display,
            .exe = exe,
            .task_id = task_id,
            .status = if (pid != 0) "done" else "failed",
            .approval_id = approval_id,
            .pid = pid,
            .stderr = failure,
            .detached = true,
        }, .{});
        defer aa.free(payload);
        const stmt = try st.db_conn.prepare("INSERT INTO events (ts, source, kind, payload_json, order_id) VALUES (?, ?, 'shell_command', ?, ?)");
        defer st.db_conn.finalize(stmt);
        try db.bindInt(stmt, 1, health.nowMillis(st.db_conn));
        try db.bindText(stmt, 2, "executor");
        try db.bindText(stmt, 3, payload);
        try db.bindInt(stmt, 4, order_id);
        if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE) return error.ExecFailed;
        return;
    }

    // r5: comprobación final justo antes de lanzar. Tras el COMMIT,
    // una cancelación que pase por da_order_cancel solo puede marcar NUESTRO
    // token (el registro ve la entrada activa), pero el token pudo marcarse
    // mientras corría la transacción; y otra vía pudo comprometer el terminal.
    // El executor repite la comprobación justo antes de CreateProcess para
    // cubrir la carrera hasta el arranque real.
    const cancelled_before_launch = resume_cancel.cancelled();

    // P4: streaming sink — emite delta events a runtime.db para streaming en vivo.
    const ResumeSinkCtx = struct {
        st: *CoreState,
        aa: std.mem.Allocator,
        order_id: i64,
        task_id: []const u8,
        display: []const u8,
    };
    var resume_sink_ctx = ResumeSinkCtx{ .st = st, .aa = aa, .order_id = order_id, .task_id = task_id, .display = display };
    const resume_sink_fn = struct {
        fn sink(ctx: ?*anyopaque, chunk: []const u8, stream: executor.StreamKind) void {
            const sc: *ResumeSinkCtx = @ptrCast(@alignCast(ctx.?));
            const stream_name = if (stream == .stderr) "stderr" else "stdout";
            var out: std.Io.Writer.Allocating = .init(sc.aa);
            defer out.deinit();
            var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
            js.beginObject() catch return;
            js.objectField("task_id") catch return;
            js.write(sc.task_id) catch return;
            js.objectField("command") catch return;
            js.write(sc.display) catch return;
            js.objectField("status") catch return;
            js.write("delta") catch return;
            js.objectField("stream") catch return;
            js.write(stream_name) catch return;
            js.objectField("chunk") catch return;
            js.write(chunk) catch return;
            js.endObject() catch return;
            const stmt = sc.st.db_conn.prepare("INSERT INTO events (ts, source, kind, payload_json, order_id) VALUES (?, ?, 'shell_command', ?, ?)") catch return;
            defer sc.st.db_conn.finalize(stmt);
            db.bindInt(stmt, 1, health.nowMillis(sc.st.db_conn)) catch return;
            db.bindText(stmt, 2, "executor") catch return;
            db.bindText(stmt, 3, out.written()) catch return;
            db.bindInt(stmt, 4, sc.order_id) catch return;
            _ = db.c.sqlite3_step(stmt);
        }
    }.sink;

    // Ejecutar sin pedir aprobación (ya fue aprobada).
    // FIX: antes era `catch return` — silenciaba ExeNotResolved/SpawnFailed sin output,
    // causando que el usuario viera una aprobación resuelta sin respuesta visible.
    // r5: la política lleva el callback de cancelación de la ORDEN
    // (token del registro + terminalidad real) — el bucle del executor lo
    // consulta y mata al hijo en plazo corto, sin esperar al timeout aprobado.
    // Si la cancelación ya está marcada antes de lanzar, ni se llama: resultado
    // cancelado directo (no arranca).
    var er: executor.RunResult = if (cancelled_before_launch)
        .{ .exit_code = 130, .stdout = try aa.dupe(u8, ""), .stderr = try aa.dupe(u8, ""), .cancelled = true }
    else
        executor.runGoverned(aa, executor.Policy{
            .origin = .local,
            .timeout_ms = timeout_ms,
            .workspace_root = approval_root,
            .is_cancelled_fn = if (order_id > 0) ResumeCancelCtx.check else null,
            .cancelled_ctx = if (order_id > 0) @as(?*anyopaque, @ptrCast(&resume_cancel)) else null,
        }, exe, args.items, cwd, spawn_fn, resume_sink_fn, &resume_sink_ctx) catch |e| {
            const err_text = std.fmt.allocPrint(aa, "Error ejecutando {s}: {s}", .{ exe, @errorName(e) }) catch return;
            defer aa.free(err_text);
            st.output_mutex.lock();
            st.output_seq += 1;
            const wo_err = WorkerOutput{
                .worker_id = aa.dupe(u8, "executor") catch {
                    st.output_mutex.unlock();
                    return;
                },
                .stream = aa.dupe(u8, "stderr") catch {
                    st.output_mutex.unlock();
                    return;
                },
                .text = aa.dupe(u8, err_text) catch {
                    st.output_mutex.unlock();
                    return;
                },
                .ts_ms = st.output_seq,
                .task_id = "",
            };
            st.worker_outputs.append(aa, wo_err) catch {};
            st.output_mutex.unlock();
            insertWorkerOutputEvent(st.db_conn, aa, order_id, wo_err.worker_id, wo_err.stream, wo_err.text, wo_err.ts_ms, wo_err.task_id) catch {};
            resume_cancel_finished_ok = false; // el lanzamiento falló: no fue un cierre limpio
            // QA-B 2a: la tarjeta y `approval_result` del MCP ven el fallo,
            // no un `running` que nunca termina.
            const failed_payload = std.json.Stringify.valueAlloc(aa, .{ .command = display, .exe = exe, .task_id = task_id, .status = "failed", .approval_id = approval_id, .stderr = err_text }, .{}) catch return;
            defer aa.free(failed_payload);
            const failed_stmt = st.db_conn.prepare("INSERT INTO events (ts, source, kind, payload_json, order_id) VALUES (?, 'executor', 'shell_command', ?, ?)") catch return;
            defer st.db_conn.finalize(failed_stmt);
            db.bindInt(failed_stmt, 1, health.nowMillis(st.db_conn)) catch return;
            db.bindText(failed_stmt, 2, failed_payload) catch return;
            db.bindInt(failed_stmt, 3, order_id) catch return;
            _ = db.c.sqlite3_step(failed_stmt);
            return;
        };
    defer er.deinit(aa);

    // r5 (criterio c): si la cancelación llegó mientras el comando
    // corría (o justo antes de lanzar), la orden cierra `cancelled` por la
    // MISMA autoridad transaccional (tryCommitTerminal) y sus aprobaciones
    // pendientes se cierran; la memoria refleja lo que la DB confirme — nada de
    // `running`/awaiting_approval colgado ni tarjeta sin cerrar.
    if (er.cancelled) {
        resume_cancel_finished_ok = false;
        closeCancelledResume(st, order_id);
    }

    // Construir texto de salida.
    const header = if (er.timed_out)
        "exit=timeout (el programa seguia corriendo; salida capturada en pantalla)\n"
    else if (er.cancelled)
        "exit=cancelled (orden cancelada; proceso terminado sin esperar al timeout)\n"
    else
        "";
    // E3.16: si el cap dejó fuera bytes del pipe, el texto lo dice en lugar de
    // reportar exit con la salida muda.
    const trunc_note = if (er.stdoutTruncated() or er.stderrTruncated())
        std.fmt.allocPrint(aa, "\n[salida truncada al cap: stdout {d} B mostrados de {d} B, stderr {d} B de {d} B]", .{ er.stdout.len, er.stdout_total_bytes, er.stderr.len, er.stderr_total_bytes }) catch ""
    else
        "";
    defer if (trunc_note.len > 0) aa.free(trunc_note);
    const text = if (er.timed_out or er.cancelled)
        std.fmt.allocPrint(aa, "{s}{s}{s}{s}", .{ header, er.stdout, if (er.stderr.len > 0) er.stderr else "", trunc_note }) catch return
    else
        std.fmt.allocPrint(aa, "exit={d}\n{s}{s}{s}", .{ er.exit_code, er.stdout, if (er.stderr.len > 0) er.stderr else "", trunc_note }) catch return;
    defer aa.free(text);

    // Añadir output a worker_outputs + evento.
    st.output_mutex.lock();
    st.output_seq += 1;
    const wo = WorkerOutput{
        .worker_id = aa.dupe(u8, "executor") catch {
            st.output_mutex.unlock();
            return;
        },
        .stream = aa.dupe(u8, "stdout") catch {
            st.output_mutex.unlock();
            return;
        },
        .text = aa.dupe(u8, text) catch {
            st.output_mutex.unlock();
            return;
        },
        .ts_ms = st.output_seq,
        .task_id = "",
    };
    st.worker_outputs.append(aa, wo) catch {};
    st.output_mutex.unlock();

    insertWorkerOutputEvent(st.db_conn, aa, order_id, wo.worker_id, wo.stream, wo.text, wo.ts_ms, wo.task_id) catch {};

    // Emitir evento shell_command status:done.
    {
        var out: std.Io.Writer.Allocating = .init(aa);
        defer out.deinit();
        var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
        js.beginObject() catch return;
        js.objectField("command") catch return;
        js.write(display) catch return;
        js.objectField("exe") catch return;
        js.write(exe) catch return;
        js.objectField("task_id") catch return;
        js.write(task_id) catch return;
        js.objectField("status") catch return;
        js.write("done") catch return;
        js.objectField("approval_id") catch return;
        js.write(approval_id) catch return;
        js.objectField("exit_code") catch return;
        js.write(er.exit_code) catch return;
        if (er.cancelled) {
            js.objectField("cancelled") catch return;
            js.write(true) catch return;
        }
        js.objectField("stdout") catch return;
        js.write(er.stdout) catch return;
        js.objectField("stderr") catch return;
        js.write(if (er.stderr.len > 0) er.stderr else "") catch return;
        js.objectField("stdout_truncated") catch return;
        js.write(er.stdoutTruncated()) catch return;
        js.objectField("stdout_total_bytes") catch return;
        js.write(er.stdout_total_bytes) catch return;
        js.objectField("stderr_truncated") catch return;
        js.write(er.stderrTruncated()) catch return;
        js.objectField("stderr_total_bytes") catch return;
        js.write(er.stderr_total_bytes) catch return;
        js.endObject() catch return;
        const payload = out.written();
        const stmt = st.db_conn.prepare("INSERT INTO events (ts, source, kind, payload_json, order_id) VALUES (?, ?, 'shell_command', ?, ?)") catch return;
        defer st.db_conn.finalize(stmt);
        db.bindInt(stmt, 1, health.nowMillis(st.db_conn)) catch return;
        db.bindText(stmt, 2, "executor") catch return;
        db.bindText(stmt, 3, payload) catch return;
        db.bindInt(stmt, 4, order_id) catch return;
        _ = db.c.sqlite3_step(stmt);
    }
}

/// P-EXEC-4: tras resolver una aprobación de ejecución, comprueba si la orden
//  tiene más aprobaciones de ejecución pendientes. Si no, avanza la orden a done.
fn commitApprovedOrderTerminal(conn: db.Connection, order_id: i64, now_ms: i64) !bool {
    return conn.tryCommitTerminal(
        order_id,
        "done",
        "order_done",
        "superagente",
        "{\"cause\":\"approvals_resolved\"}",
        now_ms,
    );
}

fn checkAndAdvanceOrder(st: *CoreState, order_id: i64) void {
    // ¿Hay más aprobaciones de ejecución sin resolver para esta orden?
    st.output_mutex.lock();
    var has_pending_exec = false;
    for (st.approvals.items) |*a| {
        if (!a.resolved and a.exe != null and a.order_id == order_id) {
            has_pending_exec = true;
            break;
        }
    }
    st.output_mutex.unlock();

    if (has_pending_exec) return;

    // Avanzar la orden a done.
    const rec = findOrder(st, order_id) orelse return;
    if (rec.status != .awaiting_approval) return;

    const won = commitApprovedOrderTerminal(st.db_conn, order_id, health.nowMillis(st.db_conn)) catch return;
    if (won) rec.status = .done;

    // P4: la auto-auditoría real ya corre por separado (audit_pipeline). No crear
    // aprobación de auditoría pendiente — era un stub que se acumulaba sin resolver.
}

test "TERMINAL-P0 approval completion commits status and event together" {
    const allocator = std.testing.allocator;
    var conn = try db.Connection.open(allocator, ":memory:");
    defer conn.close();
    var migrator = db.Migrator.init(allocator);
