    try conn.exec("INSERT INTO orders (id, project_id, user_prompt, status, created_at) VALUES (1, 'p', 'hi', 'awaiting_approval', 1)");

    try std.testing.expect(try commitApprovedOrderTerminal(conn, 1, 2));
    const stmt = try conn.prepare("SELECT o.status, e.kind FROM orders o JOIN events e ON e.order_id=o.id WHERE o.id=1");
    defer conn.finalize(stmt);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
    const status_ptr = db.c.sqlite3_column_text(stmt, 0) orelse return error.TestUnexpectedNull;
    const status_len: usize = @intCast(db.c.sqlite3_column_bytes(stmt, 0));
    const kind_ptr = db.c.sqlite3_column_text(stmt, 1) orelse return error.TestUnexpectedNull;
    const kind_len: usize = @intCast(db.c.sqlite3_column_bytes(stmt, 1));
    try std.testing.expectEqualStrings("done", status_ptr[0..status_len]);
    try std.testing.expectEqualStrings("order_done", kind_ptr[0..kind_len]);
}

test "TERMINAL-P0 c_api: two concurrent approval-completion resolutions produce exactly one terminal" {
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try isolatedTestPath(&tmp, "race-approval.db");
    defer allocator.free(path);

    {
        var setup = try db.Connection.open(allocator, path);
        defer setup.close();
        var migrator = db.Migrator.init(allocator);
        try migrator.migrate(setup, &db.runtime_schema);
        try setup.exec("INSERT INTO orders (id, project_id, user_prompt, status, created_at) VALUES (1, 'p', 'hi', 'awaiting_approval', 1)");
    }

    const RaceCtx = struct {
        path: [:0]const u8,
        result: bool = false,

        fn run(self: *@This()) void {
            var conn = db.Connection.open(std.testing.allocator, self.path) catch return;
            defer conn.close();
            self.result = commitApprovedOrderTerminal(conn, 1, 1) catch false;
        }
    };

    var ctx1 = RaceCtx{ .path = path };
    var ctx2 = RaceCtx{ .path = path };
    const t1 = try std.Thread.spawn(.{}, RaceCtx.run, .{&ctx1});
    const t2 = try std.Thread.spawn(.{}, RaceCtx.run, .{&ctx2});
    t1.join();
    t2.join();

    // Exactamente una de las dos resoluciones "concurrentes" (dos hilos llamando a
    // checkAndAdvanceOrder vía la misma ruta atómica) gana.
    try std.testing.expect(ctx1.result != ctx2.result);

    var verify = try db.Connection.open(allocator, path);
    defer verify.close();
    const cnt_stmt = try verify.prepare("SELECT COUNT(*) FROM events WHERE order_id = 1 AND kind = 'order_done'");
    defer verify.finalize(cnt_stmt);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(cnt_stmt));
    try std.testing.expectEqual(@as(c_int, 1), db.c.sqlite3_column_int(cnt_stmt, 0));
}

test "TERMINAL-P0 c_api: memory reflects what the DB confirms, not a blind assumption" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);

    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "crea un modulo de logging en C", "test", null, &order));

    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order).?;
    const rec = findOrder(st, order_id) orelse return error.TestExpectedEqual;

    // La DB ya tiene un terminal "failed" comprometido por otro camino (p. ej. otro
    // hilo ganó la carrera dentro de agenticExecute), pero la memoria todavía cree
    // "running" — el valor optimista que dispatchApprovedOrder asigna antes de
    // despachar (rec.status = .running).
    rec.status = .running;
    {
        const stmt = try st.db_conn.prepare("UPDATE orders SET status = 'failed' WHERE id = ?");
        defer st.db_conn.finalize(stmt);
        try db.bindInt(stmt, 1, order_id);
        _ = db.c.sqlite3_step(stmt);
    }

    syncRecStatusFromDb(st.db_conn, rec);

    // La memoria copió lo que la DB confirma — no se asumió "done" a ciegas.
    try std.testing.expectEqual(superagent.OrderStatus.failed, rec.status);
}

test "TERMINAL-P0 c_api: awaiting_approval yields no terminal until the LAST exec approval resolves" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);

    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "crea un modulo de logging en C", "test", null, &order));

    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order).?;
    const rec = findOrder(st, order_id) orelse return error.TestExpectedEqual;
    const aa = st.arena.child_allocator;

    // Orden pausada esperando 2 aprobaciones de ejecución (P-EXEC-4).
    rec.status = .awaiting_approval;
    {
        const stmt = try st.db_conn.prepare("UPDATE orders SET status = 'awaiting_approval' WHERE id = ?");
        defer st.db_conn.finalize(stmt);
        try db.bindInt(stmt, 1, order_id);
        _ = db.c.sqlite3_step(stmt);
    }
    st.output_mutex.lock();
    try st.approvals.append(aa, ApprovalRecord{
        .id = 101,
        .task_id = try aa.dupe(u8, "t1"),
        .description = try aa.dupe(u8, "run t1"),
        .approved = false,
        .resolved = false,
        .exe = try aa.dupe(u8, "echo"),
        .order_id = order_id,
    });
    try st.approvals.append(aa, ApprovalRecord{
        .id = 102,
        .task_id = try aa.dupe(u8, "t2"),
        .description = try aa.dupe(u8, "run t2"),
        .approved = false,
        .resolved = false,
        .exe = try aa.dupe(u8, "echo"),
        .order_id = order_id,
    });
    st.output_mutex.unlock();

    // Con 2 pendientes: checkAndAdvanceOrder sale temprano (has_pending_exec), sin
    // tocar status ni emitir terminal.
    checkAndAdvanceOrder(st, order_id);
    try std.testing.expectEqual(superagent.OrderStatus.awaiting_approval, rec.status);
    {
        const stmt = try st.db_conn.prepare("SELECT COUNT(*) FROM events WHERE order_id = ? AND kind = 'order_done'");
        defer st.db_conn.finalize(stmt);
        try db.bindInt(stmt, 1, order_id);
        try std.testing.expect(db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW);
        try std.testing.expectEqual(@as(c_int, 0), db.c.sqlite3_column_int(stmt, 0));
    }

    // Resuelve la PRIMERA (queda 1 pendiente): todavía sin terminal.
    st.output_mutex.lock();
    st.approvals.items[0].resolved = true;
    st.output_mutex.unlock();
    checkAndAdvanceOrder(st, order_id);
    try std.testing.expectEqual(superagent.OrderStatus.awaiting_approval, rec.status);

    // Resuelve la ÚLTIMA: ahora sí avanza a done, atómicamente, con su evento.
    st.output_mutex.lock();
    st.approvals.items[1].resolved = true;
    st.output_mutex.unlock();
    checkAndAdvanceOrder(st, order_id);
    try std.testing.expectEqual(superagent.OrderStatus.done, rec.status);
    {
        const stmt = try st.db_conn.prepare("SELECT status FROM orders WHERE id = ?");
        defer st.db_conn.finalize(stmt);
        try db.bindInt(stmt, 1, order_id);
        try std.testing.expect(db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW);
        try std.testing.expectEqualStrings("done", std.mem.span(db.c.sqlite3_column_text(stmt, 0)));
    }
}

test "E-95 c_api: denied exec approval still advances the order out of awaiting_approval" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);

    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "crea un modulo de logging en C", "test", null, &order));

    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order).?;
    const rec = findOrder(st, order_id) orelse return error.TestExpectedEqual;
    const aa = st.arena.child_allocator;

    // Orden pausada con UNA aprobación de ejecución pendiente.
    rec.status = .awaiting_approval;
    {
        const stmt = try st.db_conn.prepare("UPDATE orders SET status = 'awaiting_approval' WHERE id = ?");
        defer st.db_conn.finalize(stmt);
        try db.bindInt(stmt, 1, order_id);
        _ = db.c.sqlite3_step(stmt);
    }
    st.output_mutex.lock();
    try st.approvals.append(aa, ApprovalRecord{
        .id = 201,
        .task_id = try aa.dupe(u8, "t1"),
        .description = try aa.dupe(u8, "run t1"),
        .approved = false,
        .resolved = false,
        .exe = try aa.dupe(u8, "echo"),
        .order_id = order_id,
    });
    st.output_mutex.unlock();

    // El usuario DENIEGA (approved=0): antes la orden quedaba wedged en
    // awaiting_approval para siempre. Ahora debe avanzar a done.
    try std.testing.expectEqual(@as(c_int, 0), da_approval_resolve(handle, 201, 0));
    try std.testing.expectEqual(superagent.OrderStatus.done, rec.status);
    {
        const stmt = try st.db_conn.prepare("SELECT status FROM orders WHERE id = ?");
        defer st.db_conn.finalize(stmt);
        try db.bindInt(stmt, 1, order_id);
        try std.testing.expect(db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW);
        try std.testing.expectEqualStrings("done", std.mem.span(db.c.sqlite3_column_text(stmt, 0)));
    }
    // Y la denegación quedó persistida (approved=0, resolved=1).
    const ap = st.approvals.items[0];
    try std.testing.expect(ap.resolved and !ap.approved);
}

test "E-95 c_api: da_order_cancel unwedges an order parked in awaiting_approval" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);

    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "crea un modulo de logging en C", "test", null, &order));

    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order).?;
    const rec = findOrder(st, order_id) orelse return error.TestExpectedEqual;
    const aa = st.arena.child_allocator;

    rec.status = .awaiting_approval;
    {
        const stmt = try st.db_conn.prepare("UPDATE orders SET status = 'awaiting_approval' WHERE id = ?");
        defer st.db_conn.finalize(stmt);
        try db.bindInt(stmt, 1, order_id);
        _ = db.c.sqlite3_step(stmt);
    }
    st.output_mutex.lock();
    try st.approvals.append(aa, ApprovalRecord{
        .id = 301,
        .task_id = try aa.dupe(u8, "t1"),
        .description = try aa.dupe(u8, "run t1"),
        .approved = false,
        .resolved = false,
        .exe = try aa.dupe(u8, "echo"),
        .order_id = order_id,
    });
    st.output_mutex.unlock();

    // Sin dispatch activo: antes devolvía "no active dispatch found" y la
    // orden quedaba sin salida. Ahora cancela honesto (memoria + DB + evento)
    // y resuelve-deniega las aprobaciones huérfanas.
    try std.testing.expectEqual(@as(c_int, 0), da_order_cancel(handle, order));
    try std.testing.expectEqual(superagent.OrderStatus.cancelled, rec.status);
    {
        const stmt = try st.db_conn.prepare("SELECT status FROM orders WHERE id = ?");
        defer st.db_conn.finalize(stmt);
        try db.bindInt(stmt, 1, order_id);
        try std.testing.expect(db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW);
        try std.testing.expectEqualStrings("cancelled", std.mem.span(db.c.sqlite3_column_text(stmt, 0)));
    }
    try std.testing.expect(st.approvals.items[0].resolved and !st.approvals.items[0].approved);
}

test "CK-CAB-019 c_api: una orden que llega a terminal deja de ofrecer sus aprobaciones en el Monitor" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle));

    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "crea un modulo de logging en C", "test", null, &order));
    const order_id = orderHandleToId(order).?;
    const db_id = findOrder(st, order_id).?.db_id orelse order_id;

    // La tarjeta real de la #748: un ExeNotResolved que quedó pendiente.
    const aid = try insertApprovalToDb(
        st.db_conn,
        "t1",
        "Ejecutar zig requiere aprobación: ExeNotResolved",
        1,
        command_approval.PREFIX,
        "zig",
        "[\"build-exe\",\"build.zig\"]",
        db_id,
    );

    // Antes de terminar: el Monitor SÍ la muestra (rojo sin arreglo).
    {
        var before: [*:0]u8 = undefined;
        try std.testing.expectEqual(@as(c_int, 0), da_approval_pending_json(handle, &before));
        defer da_string_free(before);
        try std.testing.expect(std.mem.indexOf(u8, std.mem.span(before), "ExeNotResolved") != null);
    }

    // La orden pasa a un estado terminal (fallo del despacho).
    {
        const upd = try st.db_conn.prepare("UPDATE orders SET status = 'failed' WHERE id = ?");
        defer st.db_conn.finalize(upd);
        try db.bindInt(upd, 1, db_id);
        _ = db.c.sqlite3_step(upd);
    }
    if (findOrder(st, order_id)) |r| r.status = .failed;

    // El Monitor ya NO la ofrece...
    var after: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_approval_pending_json(handle, &after));
    defer da_string_free(after);
    try std.testing.expectEqualStrings("[]", std.mem.span(after));

    // ...y quedó cerrada en DB (resolved=1, approved=0), sin borrar la fila.
    const chk = try st.db_conn.prepare("SELECT resolved, approved FROM approvals WHERE id = ?");
    defer st.db_conn.finalize(chk);
    try db.bindInt(chk, 1, aid);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(chk));
    try std.testing.expectEqual(@as(c_int, 1), db.c.sqlite3_column_int(chk, 0));
    try std.testing.expectEqual(@as(c_int, 0), db.c.sqlite3_column_int(chk, 1));
}

