test "10-nov c_api: al arrancar, una orden esperando aprobación de un comando queda interrumpida y su tarjeta se cierra" {
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try isolatedTestPath(&tmp, "stale-awaiting.db");
    defer allocator.free(path);

    var approval_id: i64 = 0;
    {
        var conn = try db.Connection.open(allocator, path);
        defer conn.close();
        var migrator = db.Migrator.init(allocator);
        try migrator.migrate(conn, &db.runtime_schema);
        try conn.exec("INSERT INTO orders (id, project_id, user_prompt, status, created_at) VALUES (915, 'p', 'web', 'awaiting_approval', 1)");
        try conn.exec("INSERT INTO orders (id, project_id, user_prompt, status, created_at) VALUES (916, 'p', 'plan', 'planned', 1)");
        approval_id = try insertApprovalToDb(conn, "t1", "Ejecutar powershell requiere aprobación", 1, command_approval.PREFIX, "powershell", "[]", 915);
    }

    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, path.ptr));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle));

    var json: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_approval_pending_json(handle, &json));
    defer da_string_free(json);
    try std.testing.expectEqualStrings("[]", std.mem.span(json));

    const chk = try st.db_conn.prepare("SELECT (SELECT status FROM orders WHERE id = 915), (SELECT status FROM orders WHERE id = 916), (SELECT resolved FROM approvals WHERE id = ?)");
    defer st.db_conn.finalize(chk);
    try db.bindInt(chk, 1, approval_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(chk));
    const s1: [*]const u8 = db.c.sqlite3_column_text(chk, 0) orelse return error.TestUnexpectedNull;
    const s2: [*]const u8 = db.c.sqlite3_column_text(chk, 1) orelse return error.TestUnexpectedNull;
    try std.testing.expectEqualStrings("interrupted", s1[0..@intCast(db.c.sqlite3_column_bytes(chk, 0))]);
    // Un plan esperando aprobación es una pausa honesta: no se toca.
    try std.testing.expectEqualStrings("planned", s2[0..@intCast(db.c.sqlite3_column_bytes(chk, 1))]);
    try std.testing.expectEqual(@as(c_int, 1), db.c.sqlite3_column_int(chk, 2));
}

test "CK-CAB-019 c_api: aprobar una tarjeta de una orden terminal se rechaza y no ejecuta" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle));

    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "crea un modulo de logging en C", "test", null, &order));
    const order_id = orderHandleToId(order).?;
    const db_id = findOrder(st, order_id).?.db_id orelse order_id;

    // Tarjeta de ejecución (shell_command, la que resume el comando). Exe que no
    // resuelve: reproducimos el ExeNotResolved de la #748 sin lanzar nada real.
    const aid = try insertApprovalToDb(
        st.db_conn,
        "t1",
        "Ejecutar zig requiere aprobación: ExeNotResolved",
        1,
        "shell_command",
        "definitely-not-a-real-exe-xyz-748",
        "[\"build-exe\"]",
        db_id,
    );

    // La orden termina por una vía que no cierra aprobaciones.
    {
        const upd = try st.db_conn.prepare("UPDATE orders SET status = 'failed' WHERE id = ?");
        defer st.db_conn.finalize(upd);
        try db.bindInt(upd, 1, db_id);
        _ = db.c.sqlite3_step(upd);
    }
    if (findOrder(st, order_id)) |r| r.status = .failed;

    // Aprobar: la API debe cerrarla y devolver error, sin intentar ejecutar.
    try std.testing.expect(da_approval_resolve(handle, aid, 1) != 0);

    const chk = try st.db_conn.prepare("SELECT resolved, approved FROM approvals WHERE id = ?");
    defer st.db_conn.finalize(chk);
    try db.bindInt(chk, 1, aid);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(chk));
    try std.testing.expectEqual(@as(c_int, 1), db.c.sqlite3_column_int(chk, 0));
    try std.testing.expectEqual(@as(c_int, 0), db.c.sqlite3_column_int(chk, 1));

    // Se dejó el motivo del cierre y NINGÚN evento de ejecución del comando.
    const ev = try st.db_conn.prepare("SELECT payload_json FROM events WHERE kind = 'approval_closed' AND order_id = ?");
    defer st.db_conn.finalize(ev);
    try db.bindInt(ev, 1, db_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(ev));
    try std.testing.expect(std.mem.indexOf(u8, approvalColText(ev, 0), "\"reason\":\"orden terminada") != null);
    const exe_ev = try st.db_conn.prepare("SELECT COUNT(*) FROM events WHERE kind = 'shell_command'");
    defer st.db_conn.finalize(exe_ev);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(exe_ev));
    try std.testing.expectEqual(@as(c_int, 0), db.c.sqlite3_column_int(exe_ev, 0));
}

