test "CK-CAB-019 c_api: el cierre deja un evento approval_closed con su motivo y marca solo lo cerrado" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle));

    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "crea un modulo de logging en C", "test", null, &order));
    const order_id = orderHandleToId(order).?;
    const db_id = findOrder(st, order_id).?.db_id orelse order_id;

    const aid = try insertApprovalToDb(st.db_conn, "t1", "tarjeta con orden terminal", 1, command_approval.PREFIX, "zig", "[]", db_id);
    try st.approvals.append(st.arena.child_allocator, .{
        .id = aid,
        .task_id = try st.arena.child_allocator.dupe(u8, "t1"),
        .description = try st.arena.child_allocator.dupe(u8, "tarjeta con orden terminal"),
        .approved = false,
        .resolved = false,
        .order_id = db_id,
    });

    {
        const upd = try st.db_conn.prepare("UPDATE orders SET status = 'done' WHERE id = ?");
        defer st.db_conn.finalize(upd);
        try db.bindInt(upd, 1, db_id);
        _ = db.c.sqlite3_step(upd);
    }
    if (findOrder(st, order_id)) |r| r.status = .done;

    // Listar dispara la reconciliación (closeStaleApprovals).
    var json: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_approval_pending_json(handle, &json));
    defer da_string_free(json);
    try std.testing.expectEqualStrings("[]", std.mem.span(json));

    // La fila quedó cerrada y el evento lleva approval_id y motivo.
    const ev = try st.db_conn.prepare("SELECT payload_json FROM events WHERE kind = 'approval_closed' AND order_id = ?");
    defer st.db_conn.finalize(ev);
    try db.bindInt(ev, 1, db_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(ev));
    const payload = approvalColText(ev, 0);
    var idbuf: [32]u8 = undefined;
    const idstr = try std.fmt.bufPrint(&idbuf, "\"approval_id\":{d}", .{aid});
    try std.testing.expect(std.mem.indexOf(u8, payload, idstr) != null);
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"reason\":\"orden terminada\"") != null);

    // La copia en memoria solo marca la fila cuyo UPDATE ganó.
    var mem_resolved = false;
    for (st.approvals.items) |a| {
        if (a.id == aid) {
            mem_resolved = a.resolved and !a.approved;
        }
    }
    try std.testing.expect(mem_resolved);
}

test "CK-CAB-019 r3 c_api: si el evento de cierre no se puede escribir, la aprobación no se cierra" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle));

    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "crea un modulo de logging en C", "test", null, &order));
    const order_id = orderHandleToId(order).?;
    const db_id = findOrder(st, order_id).?.db_id orelse order_id;

    const aid = try insertApprovalToDb(st.db_conn, "t1", "tarjeta con orden terminal", 1, command_approval.PREFIX, "zig", "[]", db_id);
    try st.approvals.append(st.arena.child_allocator, .{
        .id = aid,
        .task_id = try st.arena.child_allocator.dupe(u8, "t1"),
        .description = try st.arena.child_allocator.dupe(u8, "tarjeta con orden terminal"),
        .approved = false,
        .resolved = false,
        .order_id = db_id,
    });
    {
        const upd = try st.db_conn.prepare("UPDATE orders SET status = 'done' WHERE id = ?");
        defer st.db_conn.finalize(upd);
        try db.bindInt(upd, 1, db_id);
        _ = db.c.sqlite3_step(upd);
    }
    if (findOrder(st, order_id)) |r| r.status = .done;

    // El INSERT del evento `approval_closed` no puede ocurrir (no hay tabla
    // `events`). El cierre debe revertirse por completo: ni la fila ni la
    // memoria pueden quedar resueltas sin su motivo.
    try st.db_conn.exec("ALTER TABLE events RENAME TO events_bak");
    defer st.db_conn.exec("ALTER TABLE events_bak RENAME TO events") catch {};

    var json: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_approval_pending_json(handle, &json));
    da_string_free(json);

    const chk = try st.db_conn.prepare("SELECT resolved, approved FROM approvals WHERE id = ?");
    defer st.db_conn.finalize(chk);
    try db.bindInt(chk, 1, aid);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(chk));
    try std.testing.expectEqual(@as(c_int, 0), db.c.sqlite3_column_int(chk, 0));

    for (st.approvals.items) |a| {
        if (a.id == aid) try std.testing.expect(!a.resolved);
    }
}

