test "CK-CAB-019 r4 c_api: closeStaleApprovals cierra el lote completo y marca toda la memoria" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle));

    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "crea un modulo de logging en C", "test", null, &order));
    const order_id = orderHandleToId(order).?;
    const db_id = findOrder(st, order_id).?.db_id orelse order_id;

    var ids: [4]i64 = undefined;
    for (&ids) |*slot| {
        slot.* = try insertApprovalToDb(st.db_conn, "t1", "tarjeta pendiente", 1, command_approval.PREFIX, "zig", "[]", db_id);
        try st.approvals.append(st.arena.child_allocator, .{
            .id = slot.*,
            .task_id = try st.arena.child_allocator.dupe(u8, "t1"),
            .description = try st.arena.child_allocator.dupe(u8, "tarjeta pendiente"),
            .approved = false,
            .resolved = false,
            .order_id = db_id,
        });
    }
    {
        const upd = try st.db_conn.prepare("UPDATE orders SET status = 'done' WHERE id = ?");
        defer st.db_conn.finalize(upd);
        try db.bindInt(upd, 1, db_id);
        _ = db.c.sqlite3_step(upd);
    }
    if (findOrder(st, order_id)) |r| r.status = .done;

    // La reserva de capacidad previa al BEGIN (punto 2 r4) garantiza que el lote
    // completo se cierra y se refleja en memoria sin que un append pueda fallar
    // tras el COMMIT. Aquí se comprueba que TODO el lote queda cerrado y marcado.
    closeStaleApprovals(st, st.db_conn, false, health.nowMillis(st.db_conn), "orden terminada");

    for (ids) |id| {
        const chk = try st.db_conn.prepare("SELECT resolved, approved FROM approvals WHERE id = ?");
        defer st.db_conn.finalize(chk);
        try db.bindInt(chk, 1, id);
        try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(chk));
        try std.testing.expectEqual(@as(c_int, 1), db.c.sqlite3_column_int(chk, 0));
        try std.testing.expectEqual(@as(c_int, 0), db.c.sqlite3_column_int(chk, 1));
        var mem = false;
        for (st.approvals.items) |a| {
            if (a.id == id and a.resolved and !a.approved) mem = true;
        }
        try std.testing.expect(mem);
    }
}

test "CK-CAB-019 r5 c_api: cancelar la orden mata el comando reanudado en plazo corto" {
    if (@import("builtin").os.tag != .windows) return @import("platform.zig").skip("T9: perfil y ExecutionPolicy de PowerShell (Windows)");
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try isolatedTestPath(&tmp, "cab019-b.db");
    defer allocator.free(path);
    const root = try tmp.dir.realPathFileAlloc(std.testing.io, ".", allocator);
    defer allocator.free(root);
    workspace.setOrderRootOverride(root);
    defer workspace.setOrderRootOverride(null);

    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, path.ptr));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "crea un modulo de logging en C", "test", null, &order));
    const order_id = orderHandleToId(order).?;
    const db_id = findOrder(st, order_id).?.db_id orelse order_id;

    // Comando REAL: escribe un marcador (prueba de que el hijo llegó a correr)
    // y se queda durmiendo 30 s. Con timeout aprobado de 120 s, volver en <8 s
    // solo puede venir de la cancelación, no del vencimiento.
    const marker = try std.fmt.allocPrint(allocator, "{s}" ++ std.fs.path.sep_str ++ "cab019-b-marker.txt", .{root});
    defer allocator.free(marker);
    const marker_z = try allocator.dupeZ(u8, marker);
    defer allocator.free(marker_z);
    const script = try std.fmt.allocPrint(allocator, "[System.IO.File]::WriteAllText('{s}','vivo'); Start-Sleep -Seconds 30", .{marker});
    defer allocator.free(script);
    const args_list = [_][]const u8{ "-NoProfile", "-NonInteractive", "-Command", script };
    const ApprovedArgs = struct {
        args: []const []const u8,
        cwd: []const u8,
        timeout_ms: u32,
    };
    var args_buf: std.Io.Writer.Allocating = .init(allocator);
    defer args_buf.deinit();
    var args_js: std.json.Stringify = .{ .writer = &args_buf.writer, .options = .{} };
    try args_js.write(ApprovedArgs{ .args = &args_list, .cwd = root, .timeout_ms = 120_000 });
    const aid = try insertApprovalToDb(st.db_conn, "t1", "tarjeta de ejecución", 1, "shell_command", "powershell", args_buf.written(), db_id);
    {
        const upd = try st.db_conn.prepare("UPDATE approvals SET resolved = 1, approved = 1 WHERE id = ?");
        defer st.db_conn.finalize(upd);
        try db.bindInt(upd, 1, aid);
        _ = db.c.sqlite3_step(upd);
    }

    // Hilo observador: espera al despacho activo Y al marcador (el hijo corrió
    // de verdad) y entonces cancela la orden por el registro — el mismo camino
    // que da_order_cancel cuando la entrada está viva.
    const Watch = struct {
        registry: *dispatch_registry.DispatchRegistry,
        order_id: i64,
        marker: [*:0]const u8,
        fired: *std.atomic.Value(bool),
        fn run(self: @This()) void {
            var waited: u32 = 0;
            while (waited < 4000) : (waited += 1) {
                const snap = self.registry.snapshot(self.order_id);
                if (snap.found and !snap.done and GetFileAttributesA(self.marker) != INVALID_FILE_ATTRIBUTES) {
                    self.fired.store(true, .release);
                    _ = self.registry.requestCancel(self.order_id);
                    return;
                }
                Sleep(5);
            }
        }
    };
    var fired = std.atomic.Value(bool).init(false);
    const watcher = try std.Thread.spawn(.{}, Watch.run, .{Watch{
        .registry = &st.dispatch_registry,
        .order_id = order_id,
        .marker = marker_z.ptr,
        .fired = &fired,
    }});
    defer watcher.join();

    const started = GetTickCount64();
    try resumeExecutionApproval(st, aa, aid, null);
    const elapsed = GetTickCount64() - started;

    try std.testing.expect(fired.load(.acquire)); // el hijo llegó a correr
    try std.testing.expect(elapsed < 8000); // ni los 30 s del hijo ni el timeout de 120 s

    const stmt = try st.db_conn.prepare("SELECT status FROM orders WHERE id = ?");
    defer st.db_conn.finalize(stmt);
    try db.bindInt(stmt, 1, db_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
    try std.testing.expectEqualStrings("cancelled", std.mem.span(db.c.sqlite3_column_text(stmt, 0)));
    try std.testing.expectEqual(superagent.OrderStatus.cancelled, findOrder(st, order_id).?.status);

    // El evento de cierre dice lo que pasó: done, cancelado y exit 130.
    const ev = try st.db_conn.prepare("SELECT payload_json FROM events WHERE kind = 'shell_command' AND order_id = ? ORDER BY id DESC LIMIT 1");
    defer st.db_conn.finalize(ev);
    try db.bindInt(ev, 1, order_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(ev));
    const payload = std.mem.span(db.c.sqlite3_column_text(ev, 0));
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"status\":\"done\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"cancelled\":true") != null);
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"exit_code\":130") != null);

    try std.testing.expect(GetFileAttributesA(marker_z.ptr) != INVALID_FILE_ATTRIBUTES);
}

test "CK-CAB-019 r5 c_api: una orden cancelada antes de lanzar no ejecuta el comando reanudado" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
