        _ = db.c.sqlite3_step(upd);
    }

    // Despacho pre-registrado con el token YA marcado: reproduce la carrera en
    // la que la cancelación llega tras el registro pero antes de que el hijo
    // arranque. Sin la comprobación previa al lanzamiento, el mock de spawn se
    // invocaría (rojo).
    try st.dispatch_registry.beginWithTimeout(order_id, true, GetTickCount64(), 120_000);
    const token = try live_worker.CancellationToken.create(std.testing.allocator);
    defer token.release();
    try std.testing.expect(st.dispatch_registry.attachCancellationToken(order_id, token));
    defer {
        st.dispatch_registry.finish(order_id, false);
        st.dispatch_registry.joinIfFinished(order_id);
    }
    token.cancel();

    approval_resume_spawn_count = 0;
    approval_resume_argv_complete = false;
    try resumeExecutionApproval(st, aa, aid, approvalResumeMock);
    try std.testing.expectEqual(@as(usize, 0), approval_resume_spawn_count);

    const stmt = try st.db_conn.prepare("SELECT status FROM orders WHERE id = ?");
