    try std.testing.expectEqual(superagent.OrderStatus.cancelled, findOrder(st, order_id).?.status);

    const ev = try st.db_conn.prepare("SELECT payload_json FROM events WHERE kind = 'shell_command' AND order_id = ? ORDER BY id DESC LIMIT 1");
    defer st.db_conn.finalize(ev);
    try db.bindInt(ev, 1, order_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(ev));
    const payload = std.mem.span(db.c.sqlite3_column_text(ev, 0));
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"status\":\"done\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"cancelled\":true") != null);
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"exit_code\":130") != null);
}

test "CK-CAB-019 r6 c_api: da_order_cancel marca el token activo aunque exista una entrada terminada antigua" {
    if (@import("builtin").os.tag != .windows) return @import("platform.zig").skip("T9: perfil y ExecutionPolicy de PowerShell (Windows)");
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try isolatedTestPath(&tmp, "cab019-r6-entry.db");
    defer allocator.free(path);
    const root = try tmp.dir.realPathFileAlloc(std.testing.io, ".", allocator);
    defer allocator.free(root);
    workspace.setOrderRootOverride(root);
    defer workspace.setOrderRootOverride(null);

    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, path.ptr));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "crea un modulo de logging en C", "test", null, &order));
    const order_id = orderHandleToId(order).?;
    const db_id = findOrder(st, order_id).?.db_id orelse order_id;

    // La orden está EJECUTANDO (running, valor real del motor): la vía de
    // da_order_cancel (awaiting_approval) no aplica y la selección de la
    // entrada en el registro es lo único que decide entre marcar el token
    // activo o fallar (rojo con la primera entrada terminada).
    {
        const upd = try st.db_conn.prepare("UPDATE orders SET status = 'running' WHERE id = ?");
        defer st.db_conn.finalize(upd);
        try db.bindInt(upd, 1, db_id);
        _ = db.c.sqlite3_step(upd);
    }
    findOrder(st, order_id).?.status = .running;

    // Entrada TERMINADA antigua de la misma orden, aún en la lista (el
    // despacho anterior la terminó pero no la retiró): la entrada ACTIVA que
    // resumeExecutionApproval registra (r5) queda DESPUÉS. Sin P1-b, snapshot
    // devuelve la terminada y da_order_cancel no marca el token vivo.
    try st.dispatch_registry.beginWithTimeout(order_id, false, GetTickCount64() - 60_000, 120_000);
    st.dispatch_registry.finish(order_id, true);
    try std.testing.expect(st.dispatch_registry.snapshot(order_id).done);

    // Comando REAL de 30 s con timeout aprobado de 120 s: volver en <8 s solo
    // puede venir de que da_order_cancel marcó el token de la entrada activa,
    // no del vencimiento ni del sondeo de terminalidad (la orden no es
    // terminal hasta que la propia cancelación la cierra).
    const marker = try std.fmt.allocPrint(allocator, "{s}" ++ std.fs.path.sep_str ++ "cab019-r6-marker.txt", .{root});
    defer allocator.free(marker);
    const marker_z = try allocator.dupeZ(u8, marker);
    defer allocator.free(marker_z);
    const script = try std.fmt.allocPrint(allocator, "[System.IO.File]::WriteAllText('{s}','vivo'); Start-Sleep -Seconds 30", .{marker});
    defer allocator.free(script);
    const args_list = [_][]const u8{ "-NoProfile", "-NonInteractive", "-Command", script };
    const ApprovedArgs = struct {
        args: []const []const u8,
        cwd: []const u8,
        timeout_ms: u32,
    };
    var args_buf: std.Io.Writer.Allocating = .init(allocator);
    defer args_buf.deinit();
    var args_js: std.json.Stringify = .{ .writer = &args_buf.writer, .options = .{} };
    try args_js.write(ApprovedArgs{ .args = &args_list, .cwd = root, .timeout_ms = 120_000 });
    const aid = try insertApprovalToDb(st.db_conn, "t1", "tarjeta de ejecución", 1, "shell_command", "powershell", args_buf.written(), db_id);
    {
        const upd = try st.db_conn.prepare("UPDATE approvals SET resolved = 1, approved = 1 WHERE id = ?");
        defer st.db_conn.finalize(upd);
        try db.bindInt(upd, 1, aid);
        _ = db.c.sqlite3_step(upd);
    }

    // Hilo observador: espera al marcador (el hijo corre de verdad) y cancela
    // por la API PÚBLICA da_order_cancel — no por registry.requestCancel.
    const Watch = struct {
        handle: ?*anyopaque,
        order: ?*anyopaque,
        marker: [*:0]const u8,
        fired: *std.atomic.Value(bool),
        cancel_rc: *std.atomic.Value(i32),
        fn run(self: @This()) void {
            var waited: u32 = 0;
            while (waited < 4000) : (waited += 1) {
                if (GetFileAttributesA(self.marker) != INVALID_FILE_ATTRIBUTES) {
                    self.cancel_rc.store(da_order_cancel(self.handle, self.order), .release);
                    self.fired.store(true, .release);
                    return;
                }
                Sleep(5);
            }
        }
    };
    var fired = std.atomic.Value(bool).init(false);
    var cancel_rc = std.atomic.Value(i32).init(-999);
    const watcher = try std.Thread.spawn(.{}, Watch.run, .{Watch{
        .handle = handle,
        .order = order,
        .marker = marker_z.ptr,
        .fired = &fired,
        .cancel_rc = &cancel_rc,
    }});
    defer watcher.join();

    const started = GetTickCount64();
    try resumeExecutionApproval(st, aa, aid, null);
    const elapsed = GetTickCount64() - started;

    try std.testing.expect(fired.load(.acquire));
    try std.testing.expectEqual(@as(c_int, 0), @as(c_int, cancel_rc.load(.acquire)));
    try std.testing.expect(elapsed < 8000);

    const stmt = try st.db_conn.prepare("SELECT status FROM orders WHERE id = ?");
    defer st.db_conn.finalize(stmt);
    try db.bindInt(stmt, 1, db_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
    try std.testing.expectEqualStrings("cancelled", std.mem.span(db.c.sqlite3_column_text(stmt, 0)));
    try std.testing.expectEqual(superagent.OrderStatus.cancelled, findOrder(st, order_id).?.status);

    const ev = try st.db_conn.prepare("SELECT payload_json FROM events WHERE kind = 'shell_command' AND order_id = ? ORDER BY id DESC LIMIT 1");
    defer st.db_conn.finalize(ev);
    try db.bindInt(ev, 1, order_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(ev));
    const payload = std.mem.span(db.c.sqlite3_column_text(ev, 0));
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"cancelled\":true") != null);
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"exit_code\":130") != null);

    try std.testing.expect(GetFileAttributesA(marker_z.ptr) != INVALID_FILE_ATTRIBUTES);
}

test "CK-CAB-019 r6 c_api: approved_detached con la orden cancelada antes de lanzar no invoca runDetached" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "crea un modulo de logging en C", "test", null, &order));
    const order_id = orderHandleToId(order).?;
    const db_id = findOrder(st, order_id).?.db_id orelse order_id;

    const aid = try insertApprovalToDb(st.db_conn, "t1", "tarjeta detached", 1, "shell_command", "definitely-not-a-real-exe-xyz", "{\"args\":[\"-c\",\"print('CAB019')\"],\"detached\":true}", db_id);
    {
        const upd = try st.db_conn.prepare("UPDATE approvals SET resolved = 1, approved = 1 WHERE id = ?");
        defer st.db_conn.finalize(upd);
        try db.bindInt(upd, 1, aid);
        _ = db.c.sqlite3_step(upd);
    }

    // Carrera determinista de P1-a: la orden pasa a terminal justo DESPUÉS de
    // que la transacción del evento `running` la compruebe (el trigger dispara
    // con ese INSERT) y ANTES de que la rama detached lance nada — la ventana
    // exacta del hallazgo. Sin la comprobación previa, runDetached se invoca y,
    // con este exe fuera del allowlist, emite un `failed` en vez del cierre
    // cancelado.
    const trig_sql = try std.fmt.allocPrint(aa, "CREATE TRIGGER cab019_r6_detached_cancel AFTER INSERT ON events WHEN NEW.kind = 'shell_command' AND NEW.order_id = {d} BEGIN UPDATE orders SET status = 'cancelled' WHERE id = NEW.order_id; END", .{db_id});
    defer aa.free(trig_sql);
    try st.db_conn.exec(trig_sql);

    try resumeExecutionApproval(st, aa, aid, null);

    try std.testing.expectEqual(superagent.OrderStatus.cancelled, findOrder(st, order_id).?.status);
    const status_stmt = try st.db_conn.prepare("SELECT status FROM orders WHERE id = ?");
    defer st.db_conn.finalize(status_stmt);
    try db.bindInt(status_stmt, 1, db_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(status_stmt));
    try std.testing.expectEqualStrings("cancelled", std.mem.span(db.c.sqlite3_column_text(status_stmt, 0)));

    const ev = try st.db_conn.prepare("SELECT payload_json FROM events WHERE kind = 'shell_command' AND order_id = ? ORDER BY id DESC LIMIT 1");
    defer st.db_conn.finalize(ev);
    try db.bindInt(ev, 1, order_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(ev));
    const payload = std.mem.span(db.c.sqlite3_column_text(ev, 0));
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"cancelled\":true") != null);
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"exit_code\":130") != null);
    try std.testing.expect(std.mem.indexOf(u8, payload, "ExeNotAllowed") == null);
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"status\":\"failed\"") == null);
}

test "TERMINAL-P0 c_api: dispatch_poll timeout watchdog never stomps an already-committed terminal" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);

    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "crea un modulo de logging en C", "test", null, &order));

    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order).?;

    // La orden YA terminó de verdad (p. ej. el hilo de dispatch commiteó "done"
    // justo antes de que el watchdog de timeout despertara — una carrera legítima:
    // el hilo real sigue corriendo hasta el join, dispatch_done aún no se reflejó).
    const won = try st.db_conn.tryCommitTerminal(order_id, "done", "order_done", "superagente", "{}", health.nowMillis(st.db_conn));
    try std.testing.expect(won);
    if (findOrder(st, order_id)) |r| r.status = .done;

    // C3-REGISTRY: simula un despacho en vuelo (sin hilo real) directamente vía
    // el registro, igual que da_order_dispatch_async lo haría salvo por el spawn.
    try st.dispatch_registry.begin(order_id, false, GetTickCount64() - DISPATCH_TIMEOUT_MS - 1000);

    var done: c_int = 0;
    var ok_flag: c_int = -1;
    try std.testing.expectEqual(@as(c_int, 0), da_order_dispatch_poll(handle, order, &done, &ok_flag));
    try std.testing.expectEqual(@as(c_int, 1), done);

    // El terminal ganador (done) sigue intacto — el watchdog NO lo pisó.
    const stmt = try st.db_conn.prepare("SELECT status FROM orders WHERE id = ?");
    defer st.db_conn.finalize(stmt);
    try db.bindInt(stmt, 1, order_id);
    try std.testing.expect(db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW);
    try std.testing.expectEqualStrings("done", std.mem.span(db.c.sqlite3_column_text(stmt, 0)));

    // Sigue habiendo exactamente UN evento terminal (el order_done original) — el
    // dispatch_failed informativo del watchdog no compite por la autoridad terminal.
    const terminal_stmt = try st.db_conn.prepare(
        "SELECT COUNT(*) FROM events WHERE order_id = ? AND kind IN ('order_done','order_failed','order_cancelled')",
    );
    defer st.db_conn.finalize(terminal_stmt);
    try db.bindInt(terminal_stmt, 1, order_id);
    try std.testing.expect(db.c.sqlite3_step(terminal_stmt) == db.c.SQLITE_ROW);
    try std.testing.expectEqual(@as(c_int, 1), db.c.sqlite3_column_int(terminal_stmt, 0));
}

test "TERMINAL-P0 c_api: dispatch watchdog cancels the live worker so a timed out order can terminate" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);

    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "crea un modulo de logging en C", "test", null, &order));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order).?;
    try st.dispatch_registry.begin(order_id, false, GetTickCount64() - DISPATCH_TIMEOUT_MS - 1000);

    const token = try live_worker.CancellationToken.create(std.testing.allocator);
    defer token.release();
    try std.testing.expect(st.dispatch_registry.attachCancellationToken(order_id, token));

    var done: c_int = 0;
    var ok_flag: c_int = -1;
    try std.testing.expectEqual(@as(c_int, 0), da_order_dispatch_poll(handle, order, &done, &ok_flag));
    try std.testing.expectEqual(@as(c_int, 1), done);
    try std.testing.expect(token.isCancelled());
}

/// SEC2 R6/H1: mensaje unico cuando un nucleo MCP intenta resolver una aprobacion.
const mcp_resolve_denied = "las aprobaciones las resuelve solo la cabina; un cliente MCP no puede decidir por el humano";

pub export fn da_approval_resolve(handle: ?*anyopaque, approval_id: i64, approved: c_int) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_approval_resolve: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    // SEC2 R6/H1: ninguna via MCP (ni el servidor remoto montado sobre este
    // nucleo) decide por el humano. La cabina corre en su propio proceso/nucleo,
    // sin mcp_surface (shell/host/core_client.cpp solo llama da_core_init).
    if (st.mcp_surface) return @intFromEnum(err(.invalid_state, mcp_resolve_denied));
    const aa = st.arena.child_allocator;

    // (auditoría el segundo auditor, punto 1): antes de aprobar, si la orden de la
    // aprobación ya es terminal —o, cuando la aprobación ejecuta un comando,
    // inexistente— se cierra la tarjeta y NO se re-ejecuta nada. Sin esto,
    // aprobar una fila que quedó pendiente cuando su orden terminó (p. ej. la
    // #748, ExeNotResolved) volvía a lanzar el hijo vía resumeExecutionApproval.
    if (approved != 0) {
        var guard_order_id: i64 = 0;
        var guard_is_exec = false;
        var guard_have = false;
        if (st.db_conn.prepare("SELECT order_id, command_prefix FROM approvals WHERE id = ? AND resolved = 0")) |sel| {
            defer st.db_conn.finalize(sel);
            db.bindInt(sel, 1, approval_id) catch {};
            if (db.c.sqlite3_step(sel) == db.c.SQLITE_ROW) {
                guard_have = true;
                guard_order_id = db.c.sqlite3_column_int64(sel, 0);
                const p = approvalColText(sel, 1);
                guard_is_exec = std.mem.eql(u8, p, "shell_command") or std.mem.eql(u8, p, command_approval.PREFIX);
            }
        } else |_| {}
        if (!guard_have) {
            st.output_mutex.lock();
            for (st.approvals.items) |a| {
                if (a.id == approval_id and !a.resolved) {
                    guard_order_id = a.order_id;
                    if (a.command_prefix) |p| guard_is_exec = std.mem.eql(u8, p, "shell_command") or std.mem.eql(u8, p, command_approval.PREFIX);
                    break;
                }
            }
            st.output_mutex.unlock();
        }
        if (guard_order_id > 0) {
            const live = orderLiveness(st.db_conn, guard_order_id);
            // r3 (auditoría el segundo auditor): para las tarjetas de EJECUCIÓN el
            // estado terminal lo decide de forma atómica la reclamación
            // (claimCommandApproval) — aquí no se adelanta, para no dejar una
            // ventana entre comprobar y reclamar. Solo se cierran aquí las que
            // NO ejecutan (cualquier terminal) y las que ejecutan apuntando a
            // una orden inexistente (nunca podrán reclamarse).
            const close_now = (live == .terminal and !guard_is_exec) or (live == .missing and guard_is_exec);
            if (close_now) {
                _ = closeStaleApprovalById(st, st.db_conn, approval_id, guard_order_id, health.nowMillis(st.db_conn), "orden terminada o inexistente");
                return @intFromEnum(err(.invalid_state, "da_approval_resolve: la orden de la aprobación ya terminó o no existe"));
            }
        }
    }

    var has_exe = false;
    var is_capture = false;
    var order_id: i64 = 0;
    var found = false;

    st.output_mutex.lock();
    for (st.approvals.items) |*a| {
        if (a.id == approval_id) {
            found = true;
            if (a.resolved) {
                st.output_mutex.unlock();
                return @intFromEnum(err(.invalid_state, "da_approval_resolve: already resolved"));
            }
            const exact = if (a.command_prefix) |prefix| std.mem.eql(u8, prefix, "shell_command") or std.mem.eql(u8, prefix, command_approval.PREFIX) else false;
            if (exact) {
                const outcome = claimCommandApproval(st, approval_id, approved != 0) catch |e| {
                    st.output_mutex.unlock();
                    return @intFromEnum(err(.internal, @errorName(e)));
                };
                if (outcome == .order_terminal or outcome == .order_missing) {
                    const oid = a.order_id;
                    st.output_mutex.unlock();
                    const reason = if (outcome == .order_missing) "orden inexistente" else "orden terminada";
                    _ = closeStaleApprovalById(st, st.db_conn, approval_id, oid, health.nowMillis(st.db_conn), reason);
                    return @intFromEnum(err(.invalid_state, "da_approval_resolve: la orden de la aprobación ya terminó o no existe"));
                }
                if (outcome != .won) {
                    st.output_mutex.unlock();
                    return @intFromEnum(err(.invalid_state, "da_approval_resolve: already resolved"));
                }
            }
            a.approved = approved != 0;
            a.resolved = true;
            has_exe = a.exe != null;
            order_id = a.order_id;
            if (a.command_prefix) |p| is_capture = std.mem.eql(u8, p, SCREEN_CAPTURE_PREFIX);
            if (!exact) updateApprovalResolved(st, approval_id, a.approved) catch {};
            // E5.04/una aprobación 'worktree_script' concede el par
            // (proyecto, sha256) del script — la próxima orden lo corre sin
            // volver a preguntar (y si el hash cambia, se pedirá otra vez).
            if (a.approved and a.command_prefix != null and
                std.mem.eql(u8, a.command_prefix.?, worktree_prepare.APPROVAL_PREFIX))
            {
                worktree_prepare.grantFromApprovalJson(st.db_conn, aa, a.args_json orelse "{}") catch {};
            }
            break;
        }
    }
    st.output_mutex.unlock();

    // E5.05: una aprobación 'worktree_script' vive SOLO en la tabla (la
    // preparación la inserta fuera de la lista en memoria) — sin este
    // fallback, approvals_resolve la ignoraba y el grant nunca se escribía.
    if (!found) {
        const sel = st.db_conn.prepare(
            "SELECT resolved, command_prefix, args_json, order_id FROM approvals WHERE id = ?",
        ) catch null;
        if (sel) |s| {
            defer st.db_conn.finalize(s);
            db.bindInt(s, 1, approval_id) catch {};
            if (db.c.sqlite3_step(s) == db.c.SQLITE_ROW) {
                if (db.c.sqlite3_column_int(s, 0) != 0)
                    return @intFromEnum(err(.invalid_state, "da_approval_resolve: already resolved"));
                const prefix = approvalColText(s, 1);
                const args_json = approvalColText(s, 2);
                order_id = db.c.sqlite3_column_int64(s, 3);
                if (std.mem.eql(u8, prefix, "shell_command") or std.mem.eql(u8, prefix, command_approval.PREFIX)) {
                    const outcome = claimCommandApproval(st, approval_id, approved != 0) catch |e| return @intFromEnum(err(.internal, @errorName(e)));
                    if (outcome == .order_terminal or outcome == .order_missing) {
                        const reason = if (outcome == .order_missing) "orden inexistente" else "orden terminada";
                        _ = closeStaleApprovalById(st, st.db_conn, approval_id, order_id, health.nowMillis(st.db_conn), reason);
                        return @intFromEnum(err(.invalid_state, "da_approval_resolve: la orden de la aprobación ya terminó o no existe"));
                    }
                    if (outcome != .won) return @intFromEnum(err(.invalid_state, "da_approval_resolve: already resolved"));
                } else {
                    updateApprovalResolved(st, approval_id, approved != 0) catch |e| return @intFromEnum(err(.internal, @errorName(e)));
                }
                has_exe = std.mem.eql(u8, prefix, "shell_command");
                is_capture = std.mem.eql(u8, prefix, SCREEN_CAPTURE_PREFIX);
                if (approved != 0 and std.mem.eql(u8, prefix, worktree_prepare.APPROVAL_PREFIX))
                    worktree_prepare.grantFromApprovalJson(st.db_conn, aa, args_json) catch {};
            }
        }
    }

    // P-EXEC-4: si es una aprobación de ejecución aprobada, re-ejecutar el comando.
    if (approved != 0 and has_exe) {
        resumeExecutionApproval(st, aa, approval_id, null) catch |e| return @intFromEnum(err(.internal, @errorName(e)));
    }
    // QA-B H4: la captura pedida por MCP se toma aquí, en la cabina, y solo
    // tras el «sí» humano.
    if (approved != 0 and is_capture) {
        runApprovedScreenCapture(st, aa, approval_id) catch |e| return @intFromEnum(err(.internal, @errorName(e)));
    }
    // la re-evaluación corre también al DENEGAR — antes solo se llamaba
    // en el "sí", así que un "no" dejaba la orden en awaiting_approval para
    // siempre (ni avanza ni puede cancelarse: no hay dispatch activo).
    // checkAndAdvanceOrder es no-op si la orden no sigue en awaiting_approval
    // o si quedan más aprobaciones de ejecución sin resolver.
    emitApprovalResolved(st.db_conn, approval_id, order_id, approved != 0);
    if (order_id != 0) checkAndAdvanceOrder(st, order_id);

    return @intFromEnum(ok());
}

/// P2: establece el modo de permisos y las listas allow/deny.
/// `config_json`: {"mode":"normal|accept_edits|bypass|autonomous","allow":["git","python"],"deny":["rm","sudo"]}
/// Configura los hooks de ciclo de vida (ver core/src/hooks.zig).
///
/// `config_json`:
/// `{"enabled":true,"preCommand":"","postCommand":"","preEdit":"","postEdit":"",
///   "timeoutMs":15000}`
///
/// Es un REEMPLAZO completo: los campos que falten quedan vacíos. La
/// configuración vive en el módulo `hooks`, no en `CoreState`, porque los dos
/// puntos donde se dispara (`executor.runGoverned` y `workspace.persistTask`)
/// son funciones libres sin acceso al estado del motor.
/// Marca o desmarca un modelo como favorito.
///
/// Hasta ahora `is_favorite` solo lo ponía la curaduría automática del router
/// al descubrir modelos, y el usuario no tenía forma de opinar: la columna
/// "Favorito" del catálogo era de solo lectura. El router sigue usando el mismo
/// campo como prior (`ORDER BY m.is_favorite DESC`), así que marcar un modelo a
/// mano lo asciende de verdad, no es un adorno.
///
/// OJO: `da_models_discover` reescribe la fila con `is_favorite = excluded.
/// is_favorite`, así que un redescubrimiento puede pisar la elección manual.
/// Es una limitación conocida, no un olvido.
pub export fn da_model_set_favorite(
    handle: ?*anyopaque,
    provider: [*:0]const u8,
    model: [*:0]const u8,
    favorite: c_int,
) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_model_set_favorite: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const stmt = st.catalog.db.prepare(
        \\UPDATE models SET is_favorite = ?
        \\WHERE model_name = ?
        \\  AND provider_id = (SELECT id FROM providers WHERE name = ?)
    ) catch return @intFromEnum(err(.internal, "da_model_set_favorite: prepare"));
    defer st.catalog.db.finalize(stmt);

    db.bindInt(stmt, 1, if (favorite != 0) 1 else 0) catch
        return @intFromEnum(err(.internal, "da_model_set_favorite: bind"));
    db.bindText(stmt, 2, std.mem.span(model)) catch
        return @intFromEnum(err(.internal, "da_model_set_favorite: bind"));
    db.bindText(stmt, 3, std.mem.span(provider)) catch
        return @intFromEnum(err(.internal, "da_model_set_favorite: bind"));

    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE) {
        return @intFromEnum(err(.internal, "da_model_set_favorite: step"));
    }
    return @intFromEnum(ok());
}

/// Fija el modo de gobernanza que USA EL ROUTER ("free"/"paid"/"hybrid").
///
/// Existía un split-brain real: la cabina guardaba el modo en un archivo de
/// texto del host (`governance.txt`) y nunca se lo contaba al motor, mientras
/// que `Router.getGovernanceMode()` lee `settings.governance_mode` del catálogo.
/// Resultado: la interfaz decía "Prioriza pago" y el router seguía enrutando en
/// `hybrid`, es decir, con modelos gratuitos por delante. Elegir el modo no
/// cambiaba absolutamente nada en el ruteo.
pub export fn da_set_governance_mode(handle: ?*anyopaque, mode: [*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_set_governance_mode: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const parsed = model_router.GovernanceMode.parse(std.mem.span(mode));
    const stmt = st.catalog.db.prepare(
        \\INSERT INTO settings (key, value) VALUES ('governance_mode', ?)
        \\ON CONFLICT(key) DO UPDATE SET value=excluded.value
    ) catch return @intFromEnum(err(.internal, "da_set_governance_mode: prepare falló"));
    defer st.catalog.db.finalize(stmt);
    db.bindText(stmt, 1, parsed.toText()) catch
        return @intFromEnum(err(.internal, "da_set_governance_mode: bind falló"));
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE)
        return @intFromEnum(err(.internal, "da_set_governance_mode: no se pudo guardar"));
    return @intFromEnum(ok());
}

/// Modo de gobernanza vigente PARA EL ROUTER. El caller libera con da_string_free.
pub export fn da_get_governance_mode(handle: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_get_governance_mode: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    var value: []const u8 = "hybrid";
    const stmt = st.catalog.db.prepare("SELECT value FROM settings WHERE key='governance_mode'") catch {
        out_json.* = ownedCStr("hybrid") orelse return @intFromEnum(err(.oom, "da_get_governance_mode: OOM"));
        return @intFromEnum(ok());
    };
    defer st.catalog.db.finalize(stmt);
    if (db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW) {
        const ptr = db.c.sqlite3_column_text(stmt, 0);
        if (ptr != null) value = ptr[0..std.mem.len(ptr)];
    }
    out_json.* = ownedCStr(value) orelse return @intFromEnum(err(.oom, "da_get_governance_mode: OOM"));
    return @intFromEnum(ok());
}

/// E1.18/F4: estado del presupuesto de pago, para mostrarlo en la cabina.
/// {"authorized":N,"spent":N,"remaining":N} — el caller libera con da_string_free.
pub export fn da_budget_state_json(handle: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_budget_state_json: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const est = spend_budget.estado(st.catalog.db);
    const buf = std.fmt.allocPrint(
        st.arena.child_allocator,
        "{{\"authorized\":{d},\"spent\":{d},\"remaining\":{d}}}",
        .{ est.autorizadas, est.consumidas, est.restantes() },
    ) catch return @intFromEnum(err(.oom, "da_budget_state_json: OOM"));
    defer st.arena.child_allocator.free(buf);
    out_json.* = ownedCStr(buf) orelse return @intFromEnum(err(.oom, "da_budget_state_json: OOM"));
    return @intFromEnum(ok());
}

/// E1.18/F4: autoriza N llamadas de pago (0 = corte total, el gate cierra solo).
/// Persiste en `settings` del catálogo — el mismo sitio que lee el gate de
/// spend_budget antes de cada llamada a un modelo no-gratuito.
pub export fn da_budget_set_authorized(handle: ?*anyopaque, authorized: c_int) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_budget_set_authorized: null handle"));
    if (authorized < 0) return @intFromEnum(err(.invalid_arg, "da_budget_set_authorized: valor negativo"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    // SEC2 R7/N1: autorizar gasto de pago es decision humana. Un cliente MCP solo
    // puede ENDURECER (bajar o quitar el cupo), como set_permission_config.
    if (st.mcp_surface and @as(u64, @intCast(authorized)) > spend_budget.estado(st.catalog.db).autorizadas)
        return @intFromEnum(err(.invalid_state, "da_budget_set_authorized: un cliente MCP solo puede reducir el cupo de pago; ampliarlo requiere la cabina"));
    spend_budget.autorizar(st.catalog.db, @intCast(authorized)) catch return @intFromEnum(err(.internal, "da_budget_set_authorized: no se pudo guardar la autorizacion de pago"));
    return @intFromEnum(ok());
}

test "ORDENES R3 C ABI budget authorization reports persistence failure" {
    try std.testing.expect(da_budget_set_authorized(null, 1) != 0);
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    try std.testing.expect(da_budget_set_authorized(handle, -1) != 0);
    try std.testing.expectEqual(@as(c_int, 0), da_budget_set_authorized(handle, 1));
    try st.catalog.db.exec("PRAGMA query_only=ON");
    try std.testing.expect(da_budget_set_authorized(handle, 2) != 0);
    try std.testing.expectEqual(@as(u64, 1), spend_budget.estado(st.catalog.db).autorizadas);
    try st.catalog.db.exec("PRAGMA query_only=OFF");
    try std.testing.expectEqual(@as(c_int, 0), da_budget_set_authorized(handle, 2));
}

/// E1.16/F4: medidor de uso del plan — ventana móvil de 7 días sobre
/// `usage_records` (runtime.db) más las claves que están enfriando o en error
/// (catalog.db), que es el aviso de rate-limit que la fila pide.
/// {"since_ms":N,"calls":N,"prompt":N,"completion":N,"total":N,
///  "by_model":[{provider,model,total}...],
///  "limited_keys":[{provider,label,status}...]}
pub export fn da_usage_week_json(handle: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_usage_week_json: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    const now = health.nowMillis(st.db_conn);
    const since = now - 7 * 24 * 60 * 60 * 1000;

    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginObject() catch return @intFromEnum(err(.oom, "da_usage_week_json: OOM"));
    js.objectField("since_ms") catch return @intFromEnum(err(.oom, "da_usage_week_json: OOM"));
    js.write(since) catch return @intFromEnum(err(.oom, "da_usage_week_json: OOM"));

    var calls: i64 = 0;
    var prompt: i64 = 0;
    var completion: i64 = 0;
    var total: i64 = 0;
    {
        const stmt = st.db_conn.prepare("SELECT COUNT(*), COALESCE(SUM(prompt_tokens),0), COALESCE(SUM(completion_tokens),0), COALESCE(SUM(total_tokens),0) FROM usage_records WHERE timestamp >= ?") catch return @intFromEnum(err(.internal, "da_usage_week_json: prepare total"));
        defer st.db_conn.finalize(stmt);
        _ = db.bindInt(stmt, 1, since) catch {};
        if (db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW) {
            calls = db.c.sqlite3_column_int64(stmt, 0);
            prompt = db.c.sqlite3_column_int64(stmt, 1);
            completion = db.c.sqlite3_column_int64(stmt, 2);
            total = db.c.sqlite3_column_int64(stmt, 3);
        }
    }
    js.objectField("calls") catch return @intFromEnum(err(.oom, "da_usage_week_json: OOM"));
    js.write(calls) catch return @intFromEnum(err(.oom, "da_usage_week_json: OOM"));
    js.objectField("prompt") catch return @intFromEnum(err(.oom, "da_usage_week_json: OOM"));
    js.write(prompt) catch return @intFromEnum(err(.oom, "da_usage_week_json: OOM"));
    js.objectField("completion") catch return @intFromEnum(err(.oom, "da_usage_week_json: OOM"));
    js.write(completion) catch return @intFromEnum(err(.oom, "da_usage_week_json: OOM"));
    js.objectField("total") catch return @intFromEnum(err(.oom, "da_usage_week_json: OOM"));
    js.write(total) catch return @intFromEnum(err(.oom, "da_usage_week_json: OOM"));

    js.objectField("by_model") catch return @intFromEnum(err(.oom, "da_usage_week_json: OOM"));
    js.beginArray() catch return @intFromEnum(err(.oom, "da_usage_week_json: OOM"));
    {
        const stmt = st.db_conn.prepare("SELECT provider, model, SUM(total_tokens) FROM usage_records WHERE timestamp >= ? GROUP BY provider, model ORDER BY SUM(total_tokens) DESC") catch return @intFromEnum(err(.internal, "da_usage_week_json: prepare model"));
        defer st.db_conn.finalize(stmt);
        _ = db.bindInt(stmt, 1, since) catch {};
        while (db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW) {
            const prov = db.c.sqlite3_column_text(stmt, 0);
            const mod = db.c.sqlite3_column_text(stmt, 1);
            js.beginObject() catch break;
            js.objectField("provider") catch break;
            js.write(if (prov != null) std.mem.span(prov) else "") catch break;
            js.objectField("model") catch break;
            js.write(if (mod != null) std.mem.span(mod) else "") catch break;
            js.objectField("total") catch break;
            js.write(db.c.sqlite3_column_int64(stmt, 2)) catch break;
            js.endObject() catch break;
        }
    }
    js.endArray() catch return @intFromEnum(err(.oom, "da_usage_week_json: OOM"));

    // Aviso de rate-limit: claves cuyo estado NO es 'active' (enfriando,
    // agotada, revocada, error) con su cuota — es lo que el usuario tiene que
    // ver antes de lanzar la siguiente orden.
    js.objectField("limited_keys") catch return @intFromEnum(err(.oom, "da_usage_week_json: OOM"));
    js.beginArray() catch return @intFromEnum(err(.oom, "da_usage_week_json: OOM"));
    {
        const stmt = st.catalog.db.prepare(
            \\SELECT p.name, k.label, k.status, COALESCE(k.quota_limit,0), COALESCE(k.quota_used,0)
            \\FROM api_keys k JOIN providers p ON p.id = k.provider_id
            \\WHERE k.status != 'active' ORDER BY p.name, k.label
        ) catch return @intFromEnum(err(.internal, "da_usage_week_json: prepare keys"));
        defer st.catalog.db.finalize(stmt);
        while (db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW) {
            const prov = db.c.sqlite3_column_text(stmt, 0);
            const lab = db.c.sqlite3_column_text(stmt, 1);
            const stt = db.c.sqlite3_column_text(stmt, 2);
            js.beginObject() catch break;
            js.objectField("provider") catch break;
            js.write(if (prov != null) std.mem.span(prov) else "") catch break;
            js.objectField("label") catch break;
            js.write(if (lab != null) std.mem.span(lab) else "") catch break;
            js.objectField("status") catch break;
            js.write(if (stt != null) std.mem.span(stt) else "") catch break;
            js.objectField("quota_limit") catch break;
            js.write(db.c.sqlite3_column_int64(stmt, 3)) catch break;
            js.objectField("quota_used") catch break;
            js.write(db.c.sqlite3_column_int64(stmt, 4)) catch break;
            js.endObject() catch break;
        }
    }
    js.endArray() catch return @intFromEnum(err(.oom, "da_usage_week_json: OOM"));

    js.endObject() catch return @intFromEnum(err(.oom, "da_usage_week_json: OOM"));
    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_usage_week_json: OOM"));
    return @intFromEnum(ok());
}

/// Fija el nivel de esfuerzo de razonamiento ("low"/"medium"/"high").
/// Cadena vacía = devolver el control al valor por defecto del proveedor.
pub export fn da_set_reasoning_effort(handle: ?*anyopaque, effort: [*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_set_reasoning_effort: null handle"));
    const v = std.mem.span(effort);
    if (v.len != 0 and
        !std.mem.eql(u8, v, "low") and
        !std.mem.eql(u8, v, "medium") and
        !std.mem.eql(u8, v, "high"))
    {
        return @intFromEnum(err(.invalid_arg, "da_set_reasoning_effort: valor no admitido"));
    }
    live_worker.setReasoningEffort(v);
    return @intFromEnum(ok());
}

pub export fn da_set_hooks_config(handle: ?*anyopaque, config_json: [*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_set_hooks_config: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    hooks.applyJson(aa, std.mem.span(config_json)) catch |e| {
        const message = std.fmt.allocPrint(aa, "da_set_hooks_config: {s}", .{@errorName(e)}) catch return @intFromEnum(err(.oom, "da_set_hooks_config: OOM"));
        defer aa.free(message);
        return @intFromEnum(err(.invalid_arg, message));
    };
    return 0;
}

pub export fn da_set_permission_config(handle: ?*anyopaque, config_json: [*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_set_permission_config: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    const json_str = std.mem.span(config_json);

    var parsed = std.json.parseFromSlice(std.json.Value, aa, json_str, .{}) catch {
        return @intFromEnum(err(.invalid_arg, "da_set_permission_config: invalid JSON"));
    };
    defer parsed.deinit();

    const obj = switch (parsed.value) {
        .object => |o| o,
        else => return @intFromEnum(err(.invalid_arg, "da_set_permission_config: expected object")),
    };

    // Un cliente MCP puede endurecer, nunca relajar: solo modo normal, sin
    // allowlist y con una denylist que conserve las entradas vigentes.
    if (st.mcp_surface) {
        const relaxed = "da_set_permission_config: un cliente MCP no puede relajar permisos (solo mode=normal, sin allow y deny ampliando la lista); usa la cabina";
        if (obj.get("mode")) |mode_val| {
            if (mode_val != .string or !std.mem.eql(u8, mode_val.string, "normal")) return @intFromEnum(err(.invalid_state, relaxed));
        }
        if (obj.get("allow")) |allow_val| {
            if (allow_val != .array or allow_val.array.items.len != 0) return @intFromEnum(err(.invalid_state, relaxed));
        }
        if (obj.get("deny")) |deny_val| {
            if (deny_val != .array) return @intFromEnum(err(.invalid_state, relaxed));
            st.perm_mutex.lock();
            defer st.perm_mutex.unlock();
            for (st.perm_deny.items) |current| {
                var kept = false;
                for (deny_val.array.items) |item| {
                    if (item == .string and std.mem.eql(u8, item.string, current)) kept = true;
                }
                if (!kept) return @intFromEnum(err(.invalid_state, relaxed));
            }
        }
    }

    {
        st.perm_mutex.lock();
        defer st.perm_mutex.unlock();
        applyPermissionObject(st, aa, obj);
    }
    persistPermissionConfig(st, aa);
    return @intFromEnum(ok());
}

/// 10-nov: la configuración de permisos vivía solo en memoria y la cabina, sin
/// forma de leerla, la reaplicaba al abrir Configuración › Permisos (diálogo de
/// autorización del host a cada arranque) y su chip podía decir «Aceptar
/// ediciones» con el motor en «Normal». Ahora se guarda en `settings` del
/// catálogo tras cada cambio autorizado y se recarga en `da_core_init`.
const PERMISSION_SETTINGS_KEY = "permission_config";

fn permissionConfigJson(st: *CoreState, a: std.mem.Allocator) ![]u8 {
    st.perm_mutex.lock();
    defer st.perm_mutex.unlock();
    return std.json.Stringify.valueAlloc(a, .{
        .mode = @tagName(st.perm_mode),
        .allow = st.perm_allow.items,
        .deny = st.perm_deny.items,
    }, .{});
}

fn persistPermissionConfig(st: *CoreState, a: std.mem.Allocator) void {
    const text = permissionConfigJson(st, a) catch return;
    defer a.free(text);
    const stmt = st.catalog.db.prepare(
        \\INSERT INTO settings (key, value) VALUES ('permission_config', ?)
        \\ON CONFLICT(key) DO UPDATE SET value=excluded.value
    ) catch return;
    defer st.catalog.db.finalize(stmt);
    db.bindText(stmt, 1, text) catch return;
    _ = db.c.sqlite3_step(stmt);
}

fn loadPersistedPermissionConfig(st: *CoreState, a: std.mem.Allocator) void {
    const stmt = st.catalog.db.prepare("SELECT value FROM settings WHERE key='" ++ PERMISSION_SETTINGS_KEY ++ "'") catch return;
    defer st.catalog.db.finalize(stmt);
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) return;
    const ptr = db.c.sqlite3_column_text(stmt, 0);
    if (ptr == null) return;
    var parsed = std.json.parseFromSlice(std.json.Value, a, ptr[0..std.mem.len(ptr)], .{}) catch return;
    defer parsed.deinit();
    if (parsed.value != .object) return;
    st.perm_mutex.lock();
    defer st.perm_mutex.unlock();
    applyPermissionObject(st, a, parsed.value.object);
}

/// Configuración de permisos vigente: {"mode","allow","deny"}. Lectura pura,
/// sin privilegio. El caller libera con da_string_free.
pub export fn da_get_permission_config(handle: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_get_permission_config: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    const text = permissionConfigJson(st, aa) catch return @intFromEnum(err(.oom, "da_get_permission_config: OOM"));
    defer aa.free(text);
    out_json.* = ownedCStr(text) orelse return @intFromEnum(err(.oom, "da_get_permission_config: OOM"));
    return @intFromEnum(ok());
}

/// Aplica modo y listas de un objeto JSON. El llamador sujeta `perm_mutex`.
fn applyPermissionObject(st: *CoreState, aa: std.mem.Allocator, obj: std.json.ObjectMap) void {
    // Mode
    if (obj.get("mode")) |mode_val| {
        if (mode_val == .string) {
            const mode_str = mode_val.string;
            if (std.mem.eql(u8, mode_str, "normal")) st.perm_mode = .normal else if (std.mem.eql(u8, mode_str, "accept_edits")) st.perm_mode = .accept_edits else if (std.mem.eql(u8, mode_str, "bypass")) st.perm_mode = .bypass else if (std.mem.eql(u8, mode_str, "autonomous")) st.perm_mode = .autonomous;
        }
    }

    // Allow list
    if (obj.get("allow")) |allow_val| {
        if (allow_val == .array) {
            for (st.perm_allow.items) |s| aa.free(s);
            st.perm_allow.clearRetainingCapacity();
            for (allow_val.array.items) |item| {
                if (item == .string) {
                    const dup = aa.dupe(u8, item.string) catch continue;
                    st.perm_allow.append(aa, dup) catch {
                        aa.free(dup);
                    };
                }
            }
        }
    }

    // Deny list
    if (obj.get("deny")) |deny_val| {
        if (deny_val == .array) {
            for (st.perm_deny.items) |s| aa.free(s);
            st.perm_deny.clearRetainingCapacity();
            for (deny_val.array.items) |item| {
                if (item == .string) {
                    const dup = aa.dupe(u8, item.string) catch continue;
                    st.perm_deny.append(aa, dup) catch {
                        aa.free(dup);
                    };
                }
            }
        }
    }
}

/// P2: resuelve una aprobación con alcance. scope: 0=una vez, 1=sesión, 2=siempre.
/// Para sesión/siempre, añade el command_prefix de la aprobación al set correspondiente.
pub export fn da_approval_resolve_scoped(handle: ?*anyopaque, approval_id: i64, approved: c_int, scope: c_int) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_approval_resolve_scoped: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    // SEC2 R6/H1: ver da_approval_resolve.
    if (st.mcp_surface) return @intFromEnum(err(.invalid_state, mcp_resolve_denied));
    const aa = st.arena.child_allocator;

    // Las tarjetas de comando exacto jamás conceden una capacidad persistente.
    {
        const query = st.db_conn.prepare("SELECT command_prefix FROM approvals WHERE id=?") catch return @intFromEnum(err(.internal, "approval lookup failed"));
        defer st.db_conn.finalize(query);
        db.bindInt(query, 1, approval_id) catch return @intFromEnum(err(.internal, "approval bind failed"));
        if (db.c.sqlite3_step(query) == db.c.SQLITE_ROW) {
            const prefix = approvalColText(query, 0);
            // QA-B H4: cada captura de pantalla también se aprueba una vez.
            if (std.mem.eql(u8, prefix, command_approval.PREFIX) or std.mem.eql(u8, prefix, "shell_command") or std.mem.eql(u8, prefix, SCREEN_CAPTURE_PREFIX)) {
                if (scope != 0) return @intFromEnum(err(.invalid_arg, "este comando exige aprobacion una sola vez (scope=0)"));
                return da_approval_resolve(handle, approval_id, approved);
            }
        }
    }

    var prefix_dup: ?[]const u8 = null;
    var has_exe = false;
    var order_id: i64 = 0;
    st.output_mutex.lock();
    for (st.approvals.items) |*a| {
        if (a.id == approval_id) {
            if (a.resolved) {
                st.output_mutex.unlock();
                return @intFromEnum(err(.invalid_state, "da_approval_resolve_scoped: already resolved"));
            }
            a.approved = approved != 0;
            a.resolved = true;
            if (a.command_prefix) |p| prefix_dup = aa.dupe(u8, p) catch null;
            has_exe = a.exe != null;
            order_id = a.order_id;
            updateApprovalResolved(st, approval_id, a.approved) catch {};
            break;
        }
    }
    st.output_mutex.unlock();

    // Si se aprueba con scope sesión o siempre, añadir el prefix al set correspondiente.
    if (approved != 0 and prefix_dup != null) {
        const p = prefix_dup.?;
        if (scope == 1) {
            // sesión
            st.perm_mutex.lock();
            st.perm_session_allow.append(aa, p) catch {
                aa.free(p);
            };
            st.perm_mutex.unlock();
        } else if (scope == 2) {
            // siempre (persistente)
            st.perm_mutex.lock();
            st.perm_allow.append(aa, p) catch {
                aa.free(p);
            };
            st.perm_mutex.unlock();
        } else {
            aa.free(p);
        }
    } else if (prefix_dup) |p| {
        aa.free(p);
    }

    // P-EXEC-4: si es una aprobación de ejecución aprobada, re-ejecutar el comando.
    if (approved != 0 and has_exe) {
        resumeExecutionApproval(st, aa, approval_id, null) catch |e| return @intFromEnum(err(.internal, @errorName(e)));
    }
    // la re-evaluación corre también al DENEGAR (ver da_approval_resolve).
    emitApprovalResolved(st.db_conn, approval_id, order_id, approved != 0);
    if (order_id != 0) checkAndAdvanceOrder(st, order_id);

    return @intFromEnum(ok());
}

pub export fn da_last_error(out_error: *[*:0]u8) callconv(.c) c_int {
    // Copia propiedad-del-caller (antes devolvía un puntero al buffer estático
    // last_error_buf, que da_string_free no podía liberar; ahora es coherente).
    const src: []const u8 = if (last_error_len == 0) "" else last_error_buf[0..last_error_len];
    out_error.* = ownedCStr(src) orelse return @intFromEnum(DaResult.oom);
    return @intFromEnum(ok());
}

pub export fn da_string_free(str: [*:0]u8) callconv(.c) void {
    // F1: libera con el MISMO allocator que asignó la cadena (ownedCStr usa
    // c_allocator). Toda cadena que cruza el borde es ahora propiedad del caller.
    std.heap.c_allocator.free(std.mem.span(str));
}

/// Additive, initialization-free C ABI v1 handshake. The suffix includes the
/// C ABI, bus and WebUI protocol revisions; old DLLs lack this export.
pub export fn da_build_identity_v1() callconv(.c) [*:0]const u8 {
    return @import("version.zig").identity;
}

pub export fn da_core_version() callconv(.c) [*:0]const u8 {
    // una sola versión de producto, la de root.zig VERSION.
    return @import("root.zig").VERSION;
}

pub export fn da_provider_add(handle: ?*anyopaque, name: [*:0]const u8, api_style: [*:0]const u8, base_url: [*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_provider_add: null handle"));
    providers.http_client.validateCredentialUrl(std.mem.span(base_url)) catch |e| return @intFromEnum(err(.invalid_arg, @errorName(e)));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    var cm = credentials.CredentialManager.init(aa, st.catalog_path) catch {
        return @intFromEnum(err(.internal, "da_provider_add: failed to init credential manager"));
    };
    defer cm.deinit();
    cm.addProvider(std.mem.span(name), std.mem.span(base_url), std.mem.span(api_style), true) catch |e| {
        return @intFromEnum(err(.internal, @errorName(e)));
    };
    return @intFromEnum(ok());
}

pub export fn da_key_add(handle: ?*anyopaque, provider: [*:0]const u8, label: [*:0]const u8, key: [*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_key_add: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    var cm = credentials.CredentialManager.init(aa, st.catalog_path) catch |e| {
        var message: [256]u8 = undefined;
        const detail = std.fmt.bufPrint(&message, "da_key_add: stage=init error={s}", .{@errorName(e)}) catch "da_key_add: init diagnostic overflow";
        return @intFromEnum(err(.internal, detail));
    };
    defer cm.deinit();
    cm.addKey(std.mem.span(provider), std.mem.span(label), std.mem.span(key)) catch |e| {
        var message: [512]u8 = undefined;
        const d = cm.key_error;
        const detail = std.fmt.bufPrint(&message, "da_key_add: stage={s} error={s} sqlite={d} extended={d} sqlite_text={s} win32={d}", .{
            @tagName(d.stage),                                    @errorName(e), d.sqlite_code, d.sqlite_extended,
            std.mem.span(db.c.sqlite3_errstr(d.sqlite_extended)), d.win32,
        }) catch "da_key_add: diagnostic overflow";
        return @intFromEnum(err(.internal, detail));
    };
    // GOBERNANZA-FIABILIDAD: añadir/reemplazar una clave = credencial nueva → el
    // historial de fallos del proveedor (registrado contra la clave ANTERIOR) ya no
    // aplica. Sin esto, un proveedor cuya clave vieja falló mucho quedaba vetado del
    // router (health < min_health) para siempre, aunque la clave nueva funcione. Ver
    // health.resetProvider. Best-effort: st.db_conn es runtime.db (contiene model_health).
    health.resetProvider(st.db_conn, std.mem.span(provider));

    // M6: descubrir los modelos de ESTE proveedor nada más registrar su clave.
    //
    // Sin esto, quien añadía una clave se quedaba mirando un catálogo vacío y
    // un router sin candidatos hasta que encontraba, por su cuenta, el botón de
    // «Actualizar» del panel de Modelos. La clave ya está guardada y la función
    // ya ha devuelto lo suyo: si el descubrimiento falla (proveedor caído, red
    // sin salida), se sigue devolviendo OK — registrar la clave SÍ funcionó.
    //
    // Que esto haga red no congela la cabina: `core.*` va por la cola del hilo
    // del motor (shell/host/main.cpp), no por el hilo de UI.
    const prov_name = std.mem.span(provider);
    for (providers.providers.ALL_PROVIDERS) |cfg| {
        if (!std.mem.eql(u8, cfg.name, prov_name)) continue;
        var dcm = credentials.CredentialManager.init(aa, st.catalog_path) catch break;
        defer dcm.deinit();
        _ = discoverOneProvider(st, aa, &dcm, cfg);
        break;
    }
    return @intFromEnum(ok());
}

/// Elimina claves de un proveedor. `label` vacío ("") → borra TODAS las del proveedor;
/// con etiqueta → borra solo esa (multi-cuenta). Expuesta como tool MCP `remove_key`
/// para gestionar claves desde Configuración sin key-admin.exe (evita DbSchemaAhead).
pub export fn da_key_remove(handle: ?*anyopaque, provider: [*:0]const u8, label: [*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_key_remove: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    var cm = credentials.CredentialManager.init(aa, st.catalog_path) catch {
        return @intFromEnum(err(.internal, "da_key_remove: failed to init credential manager"));
    };
    defer cm.deinit();
    const label_slice = std.mem.span(label);
    const label_opt: ?[]const u8 = if (label_slice.len == 0) null else label_slice;
    const removed = cm.removeKey(std.mem.span(provider), label_opt) catch |e| {
        return @intFromEnum(err(.internal, @errorName(e)));
    };
    // QA-A H15: borrar algo que no existe no es un éxito. Antes respondía
    // {"ok":true} y quien llamaba creía haber quitado una clave.
    if (removed == 0) {
        const msg = if (label_opt) |l|
            std.fmt.allocPrint(aa, "da_key_remove: no hay ninguna clave con la etiqueta «{s}» para el proveedor «{s}»; nada que borrar (míralas con list_keys)", .{ l, std.mem.span(provider) })
        else
            std.fmt.allocPrint(aa, "da_key_remove: el proveedor «{s}» no tiene claves guardadas; nada que borrar (míralas con list_keys)", .{std.mem.span(provider)});
        const text = msg catch return @intFromEnum(err(.oom, "da_key_remove: OOM"));
        defer aa.free(text);
        return @intFromEnum(err(.not_found, text));
    }
    return @intFromEnum(ok());
}

/// JSON array de claves registradas (SIN secreto): [{provider,label,status}]. Tool MCP
/// `list_keys` — permite a la vista de Configuración mostrar y eliminar claves por etiqueta.
pub export fn da_keys_json(handle: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_keys_json: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    var cm = credentials.CredentialManager.init(aa, st.catalog_path) catch {
        return @intFromEnum(err(.internal, "da_keys_json: failed to init credential manager"));
    };
    defer cm.deinit();
    const json = cm.keysJson(aa) catch |e| {
        return @intFromEnum(err(.internal, @errorName(e)));
    };
    defer aa.free(json);
    out_json.* = ownedCStr(json) orelse return @intFromEnum(err(.oom, "da_keys_json: OOM"));
    return @intFromEnum(ok());
}

/// E1.13 multi-cuenta: edita prioridad/cuota/estado de una clave.
/// `priority`/`quota_limit` <0 = no tocar; `status` null/vacío = no tocar.
pub export fn da_key_set_meta(handle: ?*anyopaque, provider: [*:0]const u8, label: [*:0]const u8, priority: c_int, quota_limit: c_int, status: ?[*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_key_set_meta: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    var cm = credentials.CredentialManager.init(aa, st.catalog_path) catch {
        return @intFromEnum(err(.internal, "da_key_set_meta: failed to init credential manager"));
    };
    defer cm.deinit();
    const status_slice: []const u8 = if (status) |s| std.mem.span(s) else "";
    const found = cm.updateKeyMeta(std.mem.span(provider), std.mem.span(label), priority, quota_limit, status_slice) catch |e| {
        return @intFromEnum(err(.internal, @errorName(e)));
    };
    if (!found) return @intFromEnum(err(.not_found, "da_key_set_meta: key not found"));
    return @intFromEnum(ok());
}

pub export fn da_model_register(handle: ?*anyopaque, provider: [*:0]const u8, model: [*:0]const u8, context: c_int, is_free: c_int) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_model_register: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const ctx: ?i32 = if (context > 0) @intCast(context) else null;
    st.catalog.registerModel(std.mem.span(provider), std.mem.span(model), ctx, is_free != 0) catch |e| {
        return @intFromEnum(err(.internal, @errorName(e)));
    };
    return @intFromEnum(ok());
}

pub export fn da_model_prioritize(handle: ?*anyopaque, provider: [*:0]const u8, model: [*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_model_prioritize: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));

    const sql_id = "SELECT m.id FROM models m JOIN providers p ON m.provider_id = p.id WHERE p.name = ? AND m.model_name = ?";
    const stmt = st.catalog.db.prepare(sql_id) catch |e| return @intFromEnum(err(.internal, @errorName(e)));
    defer st.catalog.db.finalize(stmt);

    const prov_span = std.mem.span(provider);
    const model_span = std.mem.span(model);

    db.bindText(stmt, 1, prov_span) catch |e| return @intFromEnum(err(.internal, @errorName(e)));
    db.bindText(stmt, 2, model_span) catch |e| return @intFromEnum(err(.internal, @errorName(e)));

    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) {
        return @intFromEnum(err(.invalid_arg, "da_model_prioritize: model not found in catalog"));
    }
    const model_id = db.c.sqlite3_column_int64(stmt, 0);

    st.catalog.db.exec("UPDATE model_scores SET score = 0.50 WHERE task_type = 'planificar'") catch |e| {
        return @intFromEnum(err(.internal, @errorName(e)));
    };

    const sql_set =
        \\INSERT INTO model_scores (model_id, task_type, score, sample_count, updated_at)
        \\VALUES (?, 'planificar', 1.0, 1, strftime('%s','now'))
        \\ON CONFLICT(model_id, task_type) DO UPDATE SET score=1.0, sample_count=sample_count + 1, updated_at=strftime('%s','now')
    ;
    const stmt_set = st.catalog.db.prepare(sql_set) catch |e| return @intFromEnum(err(.internal, @errorName(e)));
    defer st.catalog.db.finalize(stmt_set);
    db.bindInt(stmt_set, 1, model_id) catch |e| return @intFromEnum(err(.internal, @errorName(e)));
    if (db.c.sqlite3_step(stmt_set) != db.c.SQLITE_DONE) {
        return @intFromEnum(err(.internal, "da_model_prioritize: score update failed"));
    }

    return @intFromEnum(ok());
}

/// Descubrimiento VIVO del catálogo: para cada proveedor con clave activa, pide su
/// /models real (conector F2) y puebla la tabla `models`. Reemplaza el contenido
/// previo (refresco). Devuelve el nº de modelos descubiertos en out_count. Best-effort:
/// proveedores que fallan (429/red) se saltan sin abortar.
/// M6: descubre los modelos de UN proveedor. Extraído del cuerpo del bucle de
/// `da_models_discover` para que `da_key_add` pueda descubrir solo el proveedor
/// cuya clave se acaba de registrar, en vez de recorrer los diecisiete.
///
/// Best-effort por diseño: cualquier tropiezo (sin clave, HTTP caído, JSON
/// ilegible) devuelve 0 y NO es un error del llamador. Registrar una clave debe
/// funcionar aunque el proveedor esté caído en ese momento.
fn discoverOneProvider(
    st: *CoreState,
    aa: std.mem.Allocator,
    cm: *credentials.CredentialManager,
    cfg: providers.providers.ProviderConfig,
) usize {
    // MODELO-LOCAL: los proveedores de la máquina (Ollama) no tienen clave. Si
    // el usuario registró una (un proxy local con auth, p.ej.), se usa; si no,
    // el descubrimiento corre igualmente con credencial vacía — el adaptador
    // omite el header Authorization cuando la clave es "".
    const key_opt = (cm.getKey(cfg.name) catch null);
    defer if (key_opt) |k| aa.free(k);
    if (key_opt == null and !cfg.is_local) return 0;
    const key: []const u8 = key_opt orelse "";

    // P3 / Cloudflare: el base_url trae el placeholder {account_id} que el conector
    // jamás sustituye → toda peticion 404 → 0 modelos. Se acepta la clave en forma
    // "<account_id>:<token>" y se sustituye; sin account_id NO se puede descubrir (el
    // endpoint exige la cuenta) → se omite limpiamente en vez de hacer una request fallida.
    var eff_cfg = cfg;
    // MODELO-LOCAL: la URL efectiva respeta DEVAGENTS_OLLAMA_URL.
    eff_cfg.base_url = providers.providers.effectiveBaseUrl(cfg);
    var eff_key: []const u8 = key;
    var sub_url: ?[]u8 = null;
    defer if (sub_url) |b| aa.free(b);
    if (std.mem.indexOf(u8, cfg.base_url, "{account_id}") != null) {
        const colon = std.mem.indexOfScalar(u8, key, ':') orelse return 0;
        const account_id = key[0..colon];
        eff_key = key[colon + 1 ..];
        sub_url = std.mem.replaceOwned(u8, aa, cfg.base_url, "{account_id}", account_id) catch return 0;
        eff_cfg.base_url = sub_url.?;
    }

    // HttpClient fresco por proveedor: un fallo no contamina al siguiente.
    var http = providers.http_client.HttpClient.init(aa) catch return 0;
    defer http.deinit();
    const conn = providers.providers.createConnector(aa, &http, eff_cfg, eff_key) catch return 0;
    defer conn.deinit();
    const json = conn.listModels(aa) catch return 0;
    defer aa.free(json);
    const n = st.catalog.discoverFromJson(cfg.name, json, cfg.is_free_tier) catch return 0;
    if (n == 0) return 0;

    var persisted_health = std.StringHashMap(providers.discovery_registry.HealthStatus).init(aa);
    defer persisted_health.deinit();
    var timestamp_buf: [32]u8 = undefined;
    const updated_at = std.fmt.bufPrint(&timestamp_buf, "{d}", .{health.nowSeconds(st.db_conn)}) catch "";
    discovery_persistence.normalizeAndSaveProviderSnapshot(
        aa,
        st.catalog.db,
        json,
        .{
            .provider = cfg.name,
            .api_style = @tagName(cfg.api_style),
            .metadata_source = "live_api_discovery",
            .metadata_updated_at = updated_at,
            .metadata_payload_type = .captured_real,
        },
        eff_cfg.base_url,
        cfg.is_free_tier,
        &persisted_health,
    ) catch {};

    // P4 / NVIDIA: un proveedor cuya clave funciona y devuelve modelos debe quedar
    // habilitado (catalogo y router filtran enabled=1). Auto-habilitar tras descubrir ≥1.
    st.catalog.setProviderEnabled(cfg.name, true) catch {};
    return n;
}

pub export fn da_models_discover(handle: ?*anyopaque, out_count: *c_int) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_models_discover: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    var cm = credentials.CredentialManager.init(aa, st.catalog_path) catch {
        return @intFromEnum(err(.internal, "da_models_discover: failed to init credential manager"));
    };
    defer cm.deinit();

    // Fix provider-removal (HALLAZGO opus 2026-06-17): NO borrar todos los modelos aquí.
    // Antes este DELETE global hacía que, al añadir/auto-detectar la clave de un proveedor,
    // se borraran los modelos de TODOS y solo se repoblaran los que respondían en ese
    // instante → un proveedor con 429/auth caído "desaparecía". Ahora discoverFromJson
    // reemplaza por-proveedor y solo ante respuesta válida (no destructivo).

    var total: c_int = 0;
    for (providers.providers.ALL_PROVIDERS) |cfg| {
        total += @intCast(discoverOneProvider(st, aa, &cm, cfg));
    }
    out_count.* = total;
    return @intFromEnum(ok());
}

// ── Shell interactiva gobernada (UX-11) ────────────────────────────────
// La ejecución pasa SIEMPRE por executor.runGoverned (misma política,
// allowlist y Job Object que los workers). Antes de spawn se aplica un
// escáner de argumentos que bloquea operaciones destructivas a *.db y otros
// patrones peligrosos; el bloqueo se devuelve visible en el JSON de salida.

const ShellRunResult = struct {
    exit_code: i32 = 0,
    stdout: []const u8 = &.{},
    stderr: []const u8 = &.{},
    blocked: bool = false,
    block_reason: []const u8 = "",
    approval_id: ?i64 = null,
    /// E3.16: bytes reales leídos del pipe antes del cap. Cuando exceden
    /// stdout/stderr, la salida devuelta está truncada y el llamador lo ve.
    stdout_total_bytes: usize = 0,
    stderr_total_bytes: usize = 0,

    pub fn deinit(self: ShellRunResult, allocator: std.mem.Allocator) void {
        allocator.free(self.stdout);
        allocator.free(self.stderr);
        allocator.free(self.block_reason);
    }

    pub fn toJson(self: ShellRunResult, allocator: std.mem.Allocator) ![]const u8 {
        var out: std.Io.Writer.Allocating = .init(allocator);
        defer out.deinit();
        var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
        try js.beginObject();
        try js.objectField("blocked");
        try js.write(self.blocked);
        try js.objectField("block_reason");
        try js.write(self.block_reason);
        try js.objectField("approval_id");
        try js.write(self.approval_id);
        try js.objectField("exit_code");
        try js.write(self.exit_code);
        try js.objectField("stdout");
        try js.write(self.stdout);
        try js.objectField("stderr");
        try js.write(self.stderr);
        try js.objectField("stdout_truncated");
        try js.write(self.stdout_total_bytes > self.stdout.len);
        try js.objectField("stdout_total_bytes");
        try js.write(self.stdout_total_bytes);
        try js.objectField("stderr_truncated");
        try js.write(self.stderr_total_bytes > self.stderr.len);
        try js.objectField("stderr_total_bytes");
        try js.write(self.stderr_total_bytes);
        try js.endObject();
        return allocator.dupe(u8, out.written());
    }
};

fn containsIgnoreCase(haystack: []const u8, needle: []const u8) bool {
    if (needle.len == 0) return true;
    if (needle.len > haystack.len) return false;
    var i: usize = 0;
    while (i <= haystack.len - needle.len) : (i += 1) {
        var j: usize = 0;
        while (j < needle.len) : (j += 1) {
            if (std.ascii.toLower(haystack[i + j]) != needle[j]) break;
        }
        if (j == needle.len) return true;
    }
    return false;
}

/// Escáner mínimo de seguridad para input interactivo. NO reemplaza un jail de
/// SO (EXEC-03), pero cierra el gap inmediato de comandos destructivos a *.db.
fn isShellBlocked(args: []const []const u8) ?[]const u8 {
    const bad_substrings = &[_][]const u8{".db"};
    const bad_tokens = &[_][]const u8{ "del", "erase", "format", "rmdir", "remove", "unlink", "delete" };
    for (args) |a| {
        for (bad_substrings) |s| {
            if (containsIgnoreCase(a, s)) return s;
        }
        for (bad_tokens) |t| {
            if (containsIgnoreCase(a, t)) return t;
        }
    }
    return null;
}

/// QA-A H2: la raíz efectiva de un proyecto nuevo (`<proyecto>\devagents-
/// workspace`) no existe hasta la primera orden, y CreateProcess fallaba con
/// «politica: SpawnFailed» en todo `shell_run` por MCP o C-ABI. Se crea igual
/// que la crea la cabina al escribir la primera orden (`persistTaskFiles` →
/// `confined_fs.createRoot`, permisos heredados de la carpeta del proyecto).
/// Devuelve null si existe o se creó; si no, la causa para el usuario.
fn ensureShellWorkspaceRoot(allocator: std.mem.Allocator, ws_root: []const u8) !?[]u8 {
    if (pathIsDirectory(allocator, ws_root)) return null;
    var root = confined_fs.createRoot(allocator, ws_root) catch |e|
        return try std.fmt.allocPrint(allocator, "no se pudo crear la carpeta de trabajo {s}: {s}", .{ ws_root, @errorName(e) });
    root.deinit();
    return null;
}

fn pathIsDirectory(allocator: std.mem.Allocator, path: []const u8) bool {
    const z = allocator.dupeZ(u8, path) catch return false;
    defer allocator.free(z);
    const attrs = GetFileAttributesA(z);
    return attrs != 0xFFFFFFFF and attrs & 0x10 != 0;
}

/// QA-A H2: el motivo de un lanzamiento que no se pudo hacer, en palabras.
/// `SpawnFailed` con un cwd que no existe es «la carpeta de trabajo no
/// existe», que es lo que de verdad pasa.
fn spawnFailureReason(allocator: std.mem.Allocator, e: anyerror, spawn_cwd: []const u8) ![]u8 {
    if (e == error.SpawnFailed and !pathIsDirectory(allocator, spawn_cwd))
        return std.fmt.allocPrint(allocator, "la carpeta de trabajo no existe: {s}", .{spawn_cwd});
    return std.fmt.allocPrint(allocator, "politica: {s}", .{@errorName(e)});
}

/// QA-A H2: PathOutsideSandbox diciendo cuál es la raíz permitida.
fn outsideSandboxReason(allocator: std.mem.Allocator, spawn_cwd: []const u8, ws_root: []const u8) ![]u8 {
    return std.fmt.allocPrint(allocator, "politica: PathOutsideSandbox: {s} está fuera de la raíz permitida {s}; usa un cwd relativo o una carpeta dentro de ella", .{ spawn_cwd, ws_root });
}

fn requestExecutionApproval(allocator: std.mem.Allocator, st: ?*CoreState, exe: []const u8, args: []const []const u8, cwd: []const u8, timeout_ms: u32, detached: bool) !ShellRunResult {
    const state = st orelse return .{ .blocked = true, .block_reason = try allocator.dupe(u8, "PermissionRequired: aprobacion humana desde la UI") };
    const payload = try std.json.Stringify.valueAlloc(allocator, .{ .args = args, .cwd = cwd, .timeout_ms = timeout_ms, .detached = detached }, .{});
    defer allocator.free(payload);
    const display = try executor.renderCommandLine(allocator, exe, args);
    defer allocator.free(display);
    const plain = try std.fmt.allocPrint(allocator, "Ejecutar {s} en {s}: requiere aprobacion humana", .{ display, cwd });
    defer allocator.free(plain);
    // T12 M5: si un cliente MCP escribió archivos del proyecto hace poco, la
    // tarjeta lo dice (el comando puede ejecutar lo que escribió).
    var mcp_root_buf: [4096]u8 = undefined;
    const description = if (state.mcp_surface) try withRecentMcpWritesNote(allocator, state.db_conn, plain, workspace.projectOrEffectiveRoot(&mcp_root_buf)) else try allocator.dupe(u8, plain);
    defer allocator.free(description);
    var app = try aprobacionDesdePeticion(allocator, 0, .{
        .task_id = if (detached) "run_detached" else "shell_run",
        .description = description,
        .command_prefix = "shell_command",
        .exe = exe,
        .args_json = payload,
    }, 0);
    errdefer app.deinit(allocator);
    state.output_mutex.lock();
    defer state.output_mutex.unlock();
    try state.approvals.ensureUnusedCapacity(allocator, 1);
    if (state.mcp_surface) try state.mcp_owned_approvals.ensureUnusedCapacity(state.arena.child_allocator, 1);
    const reason = try allocator.dupe(u8, "PermissionRequired: aprobacion humana desde la UI");
    errdefer allocator.free(reason);
    app.id = try insertApprovalToDbOrigin(state.db_conn, app.task_id, app.description, health.nowMillis(state.db_conn), app.command_prefix, app.exe, app.args_json, 0, if (state.mcp_surface) state.mcp_origin else "");
    state.approvals.appendAssumeCapacity(app);
    if (state.mcp_surface) state.mcp_owned_approvals.appendAssumeCapacity(app.id);
    if (app.id > state.last_approval_id) state.last_approval_id = app.id;
    insertApprovalEvent(state.db_conn, allocator, 0, app.id, app.task_id, app.description, app.command_prefix);
    return .{ .blocked = true, .block_reason = reason, .approval_id = app.id };
}

/// QA-B H4: prefijo de la aprobación de una captura de pantalla pedida por MCP.
pub const SCREEN_CAPTURE_PREFIX = "screen_capture";

/// QA-B H4: registra la tarjeta «capturar la pantalla» (misma tabla y misma
/// tarjeta que shell_run) y devuelve su id. La captura la hace quien la
/// aprueba (`da_approval_resolve` en la cabina), no quien la pide.
fn requestScreenCaptureApproval(st: *CoreState, allocator: std.mem.Allocator) !i64 {
    var app = try aprobacionDesdePeticion(allocator, 0, .{
        .task_id = "capture_screenshot",
        .description = "Capturar la pantalla completa (la pide un cliente MCP): la imagen se guarda en .screenshots y el cliente recibe su ruta",
        .command_prefix = SCREEN_CAPTURE_PREFIX,
        .exe = null,
        .args_json = null,
    }, 0);
    errdefer app.deinit(allocator);
    st.output_mutex.lock();
    defer st.output_mutex.unlock();
    try st.approvals.ensureUnusedCapacity(allocator, 1);
    if (st.mcp_surface) try st.mcp_owned_approvals.ensureUnusedCapacity(st.arena.child_allocator, 1);
    app.id = try insertApprovalToDbOrigin(st.db_conn, app.task_id, app.description, health.nowMillis(st.db_conn), app.command_prefix, null, null, 0, if (st.mcp_surface) st.mcp_origin else "");
    st.approvals.appendAssumeCapacity(app);
    if (st.mcp_surface) st.mcp_owned_approvals.appendAssumeCapacity(app.id);
    if (app.id > st.last_approval_id) st.last_approval_id = app.id;
    insertApprovalEvent(st.db_conn, allocator, 0, app.id, app.task_id, app.description, app.command_prefix);
    return app.id;
}

/// QA-B H4: la cabina aprobó una captura pedida por MCP. Se toma y el
/// resultado queda en el evento `screen_capture` con su approval_id.
fn runApprovedScreenCapture(st: *CoreState, aa: std.mem.Allocator, approval_id: i64) !void {
    const result = try captureScreenJson(aa);
    defer aa.free(result);
    const payload = try std.fmt.allocPrint(aa, "{{\"approval_id\":{d},\"status\":\"done\",\"result\":{s}}}", .{ approval_id, result });
    defer aa.free(payload);
    const stmt = try st.db_conn.prepare("INSERT INTO events (ts, source, kind, payload_json, order_id) VALUES (?, 'executor', 'screen_capture', ?, 0)");
    defer st.db_conn.finalize(stmt);
    try db.bindInt(stmt, 1, health.nowMillis(st.db_conn));
    try db.bindText(stmt, 2, payload);
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE) return error.StepFailed;
}

/// QA-B 2a/H4: estado de una aprobación pedida por MCP y, si ya se ejecutó,
/// su resultado acotado. Solo lee: quien aprueba sigue siendo la cabina.
/// {approval_id, status: pending|approved|denied|unknown, kind, executed,
///  result?: {exit_code, stdout, stderr, …} | {ok, path, width, height}}
pub const APPROVAL_RESULT_MAX_BYTES: usize = 16 * 1024;

fn approvalResultJson(st: *CoreState, aa: std.mem.Allocator, approval_id: i64) ![]u8 {
    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    try js.beginObject();
    try js.objectField("approval_id");
    try js.write(approval_id);
    const q = try st.db_conn.prepare("SELECT resolved, approved, COALESCE(command_prefix,''), task_id FROM approvals WHERE id = ?");
    defer st.db_conn.finalize(q);
    try db.bindInt(q, 1, approval_id);
    if (db.c.sqlite3_step(q) != db.c.SQLITE_ROW) {
        try js.objectField("status");
        try js.write("unknown");
        try js.objectField("message");
        try js.write("no existe una aprobación con ese id");
        try js.endObject();
        return aa.dupe(u8, out.written());
    }
    const resolved = db.c.sqlite3_column_int(q, 0) != 0;
    const approved = db.c.sqlite3_column_int(q, 1) != 0;
    const prefix = try aa.dupe(u8, approvalColText(q, 2));
    defer aa.free(prefix);
    const is_capture = std.mem.eql(u8, prefix, SCREEN_CAPTURE_PREFIX);
    try js.objectField("kind");
    try js.write(if (is_capture) "screen_capture" else if (std.mem.eql(u8, prefix, "shell_command")) "shell_command" else prefix);
    try js.objectField("status");
    try js.write(if (!resolved) "pending" else if (approved) "approved" else "denied");
    // El último evento con este approval_id: `done`/`failed` del comando o
    // la captura. `running` = aprobada y aún en marcha.
    const ev = try st.db_conn.prepare(
        \\SELECT payload_json FROM events
        \\WHERE kind IN ('shell_command','screen_capture')
        \\  AND json_valid(payload_json) AND json_extract(payload_json,'$.approval_id') = ?
        \\  AND COALESCE(json_extract(payload_json,'$.status'),'') <> 'delta'
        \\ORDER BY rowid DESC LIMIT 1
    );
    defer st.db_conn.finalize(ev);
    try db.bindInt(ev, 1, approval_id);
    var executed = false;
    if (resolved and approved and db.c.sqlite3_step(ev) == db.c.SQLITE_ROW) {
        var parsed = try std.json.parseFromSlice(std.json.Value, aa, approvalColText(ev, 0), .{});
        defer parsed.deinit();
        if (parsed.value == .object) {
            const obj = parsed.value.object;
            const state = if (obj.get("status")) |v| (if (v == .string) v.string else "") else "";
            executed = std.mem.eql(u8, state, "done") or std.mem.eql(u8, state, "failed");
            try js.objectField("run_status");
            try js.write(state);
            if (executed) {
                try js.objectField("result");
                if (is_capture) {
                    try js.write(obj.get("result") orelse std.json.Value{ .null = {} });
                } else {
                    try js.beginObject();
                    inline for (.{ "exit_code", "cancelled", "stdout_truncated", "stderr_truncated", "stdout_total_bytes", "stderr_total_bytes", "pid", "detached" }) |key| {
                        if (obj.get(key)) |v| {
                            try js.objectField(key);
                            try js.write(v);
                        }
                    }
                    inline for (.{ "stdout", "stderr" }) |key| {
                        const text = if (obj.get(key)) |v| (if (v == .string) v.string else "") else "";
                        try js.objectField(key);
                        try js.write(text[0..@min(text.len, APPROVAL_RESULT_MAX_BYTES)]);
                        if (text.len > APPROVAL_RESULT_MAX_BYTES) {
                            try js.objectField(key ++ "_cut_at");
                            try js.write(APPROVAL_RESULT_MAX_BYTES);
                        }
                    }
                    try js.endObject();
                }
            }
        }
    }
    try js.objectField("executed");
    try js.write(executed);
    try js.endObject();
    return aa.dupe(u8, out.written());
}

fn mcpOwnsApproval(st: *CoreState, approval_id: i64) bool {
    st.output_mutex.lock();
    defer st.output_mutex.unlock();
    if (std.mem.indexOfScalar(i64, st.mcp_owned_approvals.items, approval_id) != null) return true;
    // T12B B-2 (auditor 3): la lista en memoria se pierde al reiniciar el
    // proceso; el origen guardado en la tabla es la fuente que lo sobrevive.
    if (st.mcp_origin.len == 0) return false;
    const q = st.db_conn.prepare("SELECT origin FROM approvals WHERE id = ?") catch return false;
    defer st.db_conn.finalize(q);
    db.bindInt(q, 1, approval_id) catch return false;
    if (db.c.sqlite3_step(q) != db.c.SQLITE_ROW) return false;
    return std.mem.eql(u8, approvalColText(q, 0), st.mcp_origin);
}

/// QA-B 2a/H4: C-ABI de solo lectura para `approval_result` del MCP.
pub export fn da_approval_result_json(handle: ?*anyopaque, approval_id: i64, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_approval_result_json: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    if (approval_id <= 0) return @intFromEnum(err(.invalid_arg, "da_approval_result_json: approval_id debe ser > 0"));
    // T12 L1: un cliente MCP solo ve el estado y el resultado de las
    // aprobaciones que pidió él (otra sesión, aunque tenga token, no).
    if (st.mcp_surface and !mcpOwnsApproval(st, approval_id))
        return @intFromEnum(err(.invalid_state, "da_approval_result_json: esa aprobación no la pidió esta sesión MCP; solo se puede consultar el resultado de las propias"));
    const body = approvalResultJson(st, aa, approval_id) catch |e| {
        setLastError(@errorName(e));
        return @intFromEnum(err(.internal, "da_approval_result_json: no se pudo leer la aprobación"));
    };
    defer aa.free(body);
    out_json.* = ownedCStr(body) orelse return @intFromEnum(err(.oom, "da_approval_result_json: OOM"));
    return @intFromEnum(ok());
}

fn shellRunJson(
    allocator: std.mem.Allocator,
    json_str: []const u8,
    spawn_fn: ?executor.SpawnFn,
    st: ?*CoreState,
) !ShellRunResult {
    var parsed = std.json.parseFromSlice(std.json.Value, allocator, json_str, .{}) catch return error.InvalidJson;
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidJson;
    const o = parsed.value.object;

    const exe_v = o.get("exe") orelse return error.InvalidJson;
    const args_v = o.get("args") orelse return error.InvalidJson;
    if (exe_v != .string or args_v != .array) return error.InvalidJson;
    const exe = exe_v.string;
    if (exe.len == 0 or exe.len > 260 or std.mem.indexOfAny(u8, exe, "\\/\x00") != null or !executor.isAllowlisted(command_policy.commandName(exe))) {
        return .{ .blocked = true, .block_reason = try allocator.dupe(u8, "politica: ExeNotAllowed") };
    }
    if (args_v.array.items.len > 128) return error.InvalidJson;

    var args = std.ArrayList([]const u8).empty;
    defer args.deinit(allocator);
    for (args_v.array.items) |av| {
        if (av != .string or av.string.len > 32 * 1024 or std.mem.indexOfScalar(u8, av.string, 0) != null) return error.InvalidJson;
        try args.append(allocator, av.string);
    }

    if (isShellBlocked(args.items)) |reason| {
        return ShellRunResult{
            .blocked = true,
            .block_reason = try std.fmt.allocPrint(allocator, "patron bloqueado: {s}", .{reason}),
        };
    }

    const cwd_v = o.get("cwd");
    const cwd: []const u8 = if (cwd_v) |v| (if (v == .string and v.string.len > 0 and v.string.len <= 4096 and std.mem.indexOfScalar(u8, v.string, 0) == null) v.string else return error.InvalidJson) else ".";
    const timeout_ms: u32 = blk: {
        const t = o.get("timeout_ms");
        if (t) |v| {
            if (v == .integer and v.integer > 0 and v.integer <= 300_000) break :blk @intCast(v.integer);
            return error.InvalidJson;
        }
        break :blk 10_000;
    };

    // E3.34 (V8): la política por defecto usaba la raíz LITERAL "devagents-workspace",
    // así que el sandbox validaba `cwd` contra un ancla ficticia mientras
    // lpCurrentDirectory lo resolvía contra el cwd real del proceso — `cwd:"tools"`
    // ejecutaba fuera de todo devagents-workspace. Se resuelve el cwd a ruta
    // absoluta bajo effectiveRoot ANTES de validar y de spawnear: lo que el
    // sandbox aprueba es exactamente lo que el proceso ejecuta.
    // QA-B 2b: `"root":"project"` ancla en la carpeta del proyecto elegida
    // (como Directo y las tools git_* del MCP); sin él, la raíz efectiva de
    // siempre (QA-A H2). Mismas reglas de aprobación en las dos.
    const project_root = if (o.get("root")) |v| blk: {
        if (v != .string) return error.InvalidJson;
        if (std.mem.eql(u8, v.string, "project")) break :blk true;
        if (std.mem.eql(u8, v.string, "workspace")) break :blk false;
        return error.InvalidJson;
    } else false;
    var er_buf: [4096]u8 = undefined;
    const ws_root = if (project_root) workspace.projectOrEffectiveRoot(&er_buf) else workspace.effectiveRoot(&er_buf);
    const spawn_cwd: []const u8 = if (if (@import("builtin").os.tag == .windows) executor.isAbsoluteWin(cwd) else std.fs.path.isAbsolutePosix(cwd))
        try allocator.dupe(u8, cwd)
    else
        try std.fmt.allocPrint(allocator, "{s}" ++ std.fs.path.sep_str ++ "{s}", .{ ws_root, cwd });
    defer allocator.free(spawn_cwd);

    var sb = try sandbox.Sandbox.init(allocator, ws_root);
    defer sb.deinit();
    if (!sb.isAllowed(spawn_cwd)) return .{ .blocked = true, .block_reason = try outsideSandboxReason(allocator, spawn_cwd, ws_root) };

    var requires_human: bool = undefined;
    if (st) |state| {
        state.perm_mutex.lock();
        requires_human = command_policy.decide(exe, args.items, state.perm_deny.items, .{ .allocator = allocator, .workspace_root = ws_root, .cwd = spawn_cwd, .read_only_only = true }) != .exempt;
        state.perm_mutex.unlock();
    } else {
        requires_human = command_policy.decide(exe, args.items, &.{}, .{ .allocator = allocator, .workspace_root = ws_root, .cwd = spawn_cwd, .read_only_only = true }) != .exempt;
    }
    if (requires_human) {
        // MCP no puede conceder esta aprobación: la UI recibe el argv/cwd
        // exactos y la resolución ejecuta SOLO el comando almacenado.
        return requestExecutionApproval(allocator, st, exe, args.items, spawn_cwd, timeout_ms, false);
    }

    if (try ensureShellWorkspaceRoot(allocator, ws_root)) |reason| return .{ .blocked = true, .block_reason = reason };
    const er = executor.runGoverned(allocator, executor.Policy{ .timeout_ms = timeout_ms, .workspace_root = ws_root }, exe, args.items, spawn_cwd, spawn_fn, null, null) catch |e| {
        return ShellRunResult{
            .blocked = true,
            .block_reason = try spawnFailureReason(allocator, e, spawn_cwd),
        };
    };
    defer er.deinit(allocator);
    return ShellRunResult{
        .exit_code = er.exit_code,
        .stdout = try allocator.dupe(u8, er.stdout),
        .stderr = try allocator.dupe(u8, er.stderr),
        .stdout_total_bytes = er.stdout_total_bytes,
        .stderr_total_bytes = er.stderr_total_bytes,
    };
}

/// Ejecuta un comando gobernado por la política del executor. `command_json`:
///   {"exe":"python","args":["-c","print(1)"],"cwd":".","timeout_ms":10000}
/// `out_json` (liberar con da_string_free):
///   {"blocked":false,"block_reason":"","exit_code":0,"stdout":"...","stderr":"..."}
pub export fn da_shell_run(handle: ?*anyopaque, command_json: [*:0]const u8, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_shell_run: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    const json_str = std.mem.span(command_json);
    if (json_str.len == 0) return @intFromEnum(err(.invalid_arg, "da_shell_run: empty command json"));

    const res = shellRunJson(aa, json_str, null, st) catch |e| {
        setLastError(@errorName(e));
        return @intFromEnum(err(.internal, "da_shell_run: failed to run command"));
    };
    defer res.deinit(aa);
    const json_out = res.toJson(aa) catch {
        return @intFromEnum(err(.oom, "da_shell_run: OOM"));
    };
    out_json.* = ownedCStr(json_out) orelse return @intFromEnum(err(.oom, "da_shell_run: OOM"));
    return @intFromEnum(ok());
}

// ── Ejecución detached (GUI / self-contained apps) ─────────────────────────────

const RunDetachedResult = struct {
    ok: bool = false,
    pid: u32 = 0,
    err_msg: []const u8 = "",
    approval_id: ?i64 = null,

    pub fn deinit(self: RunDetachedResult, allocator: std.mem.Allocator) void {
        allocator.free(self.err_msg);
    }

    pub fn toJson(self: RunDetachedResult, allocator: std.mem.Allocator) ![]const u8 {
        var out: std.Io.Writer.Allocating = .init(allocator);
        defer out.deinit();
        var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
        try js.beginObject();
        try js.objectField("ok");
        try js.write(self.ok);
        try js.objectField("pid");
        try js.write(self.pid);
        try js.objectField("error");
        try js.write(self.err_msg);
        try js.objectField("approval_id");
        try js.write(self.approval_id);
        try js.endObject();
        return allocator.dupe(u8, out.written());
    }
};

fn runDetachedJson(
    allocator: std.mem.Allocator,
    json_str: []const u8,
    st: ?*CoreState,
) !RunDetachedResult {
    var parsed = std.json.parseFromSlice(std.json.Value, allocator, json_str, .{}) catch return error.InvalidJson;
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidJson;
    const o = parsed.value.object;

    const exe_v = o.get("exe");
    const exe: []const u8 = if (exe_v) |v| (if (v == .string) v.string else "") else "";
    if (exe.len == 0) return error.MissingExe;
    if (exe.len > 260 or std.mem.indexOfAny(u8, exe, "\\/\x00") != null or !executor.isAllowlisted(command_policy.commandName(exe))) {
        return .{ .err_msg = try allocator.dupe(u8, "politica: ExeNotAllowed") };
    }

    var args: std.ArrayList([]const u8) = .empty;
    defer args.deinit(allocator);
    if (o.get("args")) |v| {
        if (v != .array or v.array.items.len > 128) return error.InvalidJson;
        for (v.array.items) |item| {
            if (item != .string or item.string.len > 32 * 1024 or std.mem.indexOfScalar(u8, item.string, 0) != null) return error.InvalidJson;
            try args.append(allocator, item.string);
        }
    }

    if (isShellBlocked(args.items)) |reason| {
        return RunDetachedResult{
            .err_msg = try std.fmt.allocPrint(allocator, "patron bloqueado: {s}", .{reason}),
        };
    }

    const cwd_v = o.get("cwd");
    const cwd: []const u8 = if (cwd_v) |v| (if (v == .string and v.string.len > 0 and v.string.len <= 4096 and std.mem.indexOfScalar(u8, v.string, 0) == null) v.string else return error.InvalidJson) else ".";

    // E3.34 (V8): mismo defecto de ancla que shellRunJson — el cwd se resuelve
    // a absoluto bajo effectiveRoot antes de validar y lanzar.
    var er_buf: [4096]u8 = undefined;
    const ws_root = workspace.effectiveRoot(&er_buf);
    const spawn_cwd: []const u8 = if (if (@import("builtin").os.tag == .windows) executor.isAbsoluteWin(cwd) else std.fs.path.isAbsolutePosix(cwd))
        try allocator.dupe(u8, cwd)
    else
        try std.fmt.allocPrint(allocator, "{s}" ++ std.fs.path.sep_str ++ "{s}", .{ ws_root, cwd });
    defer allocator.free(spawn_cwd);

    var sb = try sandbox.Sandbox.init(allocator, ws_root);
    defer sb.deinit();
    if (!sb.isAllowed(spawn_cwd)) return .{ .err_msg = try outsideSandboxReason(allocator, spawn_cwd, ws_root) };
    var requires_human: bool = undefined;
    if (st) |state| {
        state.perm_mutex.lock();
        requires_human = command_policy.decide(exe, args.items, state.perm_deny.items, .{ .allocator = allocator, .workspace_root = ws_root, .cwd = spawn_cwd, .read_only_only = true }) != .exempt;
        state.perm_mutex.unlock();
    } else {
        requires_human = command_policy.decide(exe, args.items, &.{}, .{ .allocator = allocator, .workspace_root = ws_root, .cwd = spawn_cwd, .read_only_only = true }) != .exempt;
    }
    if (requires_human) {
        const pending = try requestExecutionApproval(allocator, st, exe, args.items, spawn_cwd, 10_000, true);
        return .{ .err_msg = pending.block_reason, .approval_id = pending.approval_id };
    }

    if (try ensureShellWorkspaceRoot(allocator, ws_root)) |reason| return .{ .err_msg = reason };
    const dr = executor.runDetached(allocator, executor.Policy{ .workspace_root = ws_root }, exe, args.items, spawn_cwd) catch |e| {
        return RunDetachedResult{
            .err_msg = try spawnFailureReason(allocator, e, spawn_cwd),
        };
    };
    return RunDetachedResult{
        .ok = true,
        .pid = dr.pid,
    };
}

/// Lanza un proceso independiente (detached) para apps GUI/autocontenidas.
/// `command_json`: {"exe":"python","args":["clock.py"],"cwd":"devagents-workspace\\orden-1"}
/// `out_json` (liberar con da_string_free):
///   {"ok":true,"pid":12345,"error":""} o {"ok":false,"pid":0,"error":"..."}
pub export fn da_run_detached(handle: ?*anyopaque, command_json: [*:0]const u8, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_run_detached: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    const json_str = std.mem.span(command_json);
    if (json_str.len == 0) return @intFromEnum(err(.invalid_arg, "da_run_detached: empty command json"));

    const res = runDetachedJson(aa, json_str, st) catch |e| {
        setLastError(@errorName(e));
        return @intFromEnum(err(.internal, "da_run_detached: failed to launch"));
    };
    defer res.deinit(aa);
    const json_out = res.toJson(aa) catch {
        return @intFromEnum(err(.oom, "da_run_detached: OOM"));
    };
    out_json.* = ownedCStr(json_out) orelse return @intFromEnum(err(.oom, "da_run_detached: OOM"));
    return @intFromEnum(ok());
}

// ═══════════════════════════════════════════════════════════════════════════════
// OD-MCP-01: Open Design MCP integration C-API
// ═══════════════════════════════════════════════════════════════════════════════

/// Conecta al servidor MCP de open-design-bridge.
/// `argv_json`: array JSON de strings (ej. ["python","-m","od_bridge.mcp_server"]).
/// `cwd`: directorio de trabajo (puede ser NULL).
/// Env vars: el caller DEBE setear `OD_WSL_DISTRO` y `OD_HOME` en el entorno del
/// proceso antes de llamar a esta función (la C-API no manipula env).
pub export fn da_mcp_connect(handle: ?*anyopaque, argv_json: [*:0]const u8, cwd: ?[*:0]const u8, timeout_ms: c_int) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_mcp_connect: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    // Conectar lanza `argv` como proceso hijo: un cliente MCP no puede pedirlo
    // sin humano. La cabina (proceso sin mcp_surface) sigue conectando.
    if (st.mcp_surface) return @intFromEnum(err(.invalid_state, "da_mcp_connect: lanza un proceso y no esta disponible para clientes MCP; conecta desde la cabina"));

    var parsed = std.json.parseFromSlice(std.json.Value, aa, std.mem.span(argv_json), .{}) catch
        return @intFromEnum(err(.invalid_arg, "da_mcp_connect: invalid argv JSON"));
    defer parsed.deinit();
    if (parsed.value != .array) return @intFromEnum(err(.invalid_arg, "da_mcp_connect: argv must be a JSON array"));

    var argv_list = std.ArrayList([]const u8).empty;
    defer {
        for (argv_list.items) |a| aa.free(a);
        argv_list.deinit(aa);
    }
    for (parsed.value.array.items) |v| {
        if (v != .string) return @intFromEnum(err(.invalid_arg, "da_mcp_connect: argv items must be strings"));
        argv_list.append(aa, aa.dupe(u8, v.string) catch return @intFromEnum(err(.oom, "da_mcp_connect: OOM"))) catch
            return @intFromEnum(err(.oom, "da_mcp_connect: OOM"));
    }
    const argv_slice = argv_list.toOwnedSlice(aa) catch return @intFromEnum(err(.oom, "da_mcp_connect: OOM"));
    errdefer aa.free(argv_slice);

    const cwd_slice: ?[]const u8 = if (cwd) |c| aa.dupe(u8, std.mem.span(c)) catch
        return @intFromEnum(err(.oom, "da_mcp_connect: OOM")) else null;
    errdefer if (cwd_slice) |c| aa.free(c);

    // el runtime io pertenece al transporte (StdioTransport.owned_io) —
    // uno local moría al volver de esta función y wedgeaba todo el bridge.
    // MCP-AUTH: el canal propio presenta el token del motor en `initialize` —
    // la cabina sigue pudiendo invocar tools privilegiadas del propio servidor.
    st.od_mcp_state.connect(argv_slice, cwd_slice, @as(u64, @intCast(@max(timeout_ms, 0))), st.mcp_token) catch |e| switch (e) {
        error.AlreadyConnected => return @intFromEnum(err(.invalid_state, "da_mcp_connect: already connected")),
        error.SpawnFailed => return @intFromEnum(err(.internal, "da_mcp_connect: failed to spawn MCP server")),
        error.ProtocolError => return @intFromEnum(err(.internal, "da_mcp_connect: MCP handshake failed")),
        error.OutOfMemory => return @intFromEnum(err(.oom, "da_mcp_connect: OOM")),
        else => return @intFromEnum(err(.internal, "da_mcp_connect: unknown error")),
    };
    return @intFromEnum(ok());
}

/// Marca este nucleo como servidor para un cliente MCP (devagents-mcp). Irreversible
/// durante la vida del nucleo: ver CoreState.mcp_surface.
pub export fn da_set_mcp_surface(handle: ?*anyopaque) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_set_mcp_surface: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    st.mcp_surface = true;
    return @intFromEnum(ok());
}

/// T12B B-2 (auditor 3): fija el origen persistente de esta sesión MCP. El
/// servidor pasa el digest de credencial e identidad del cliente; las tarjetas
/// que cree esta sesión quedan marcadas con él en `approvals.origin`.
pub export fn da_set_mcp_session(handle: ?*anyopaque, tag: [*:0]const u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_set_mcp_session: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    st.output_mutex.lock();
    defer st.output_mutex.unlock();
    const t = std.mem.span(tag);
    if (t.len == 0 or t.len > 128) return @intFromEnum(err(.invalid_arg, "da_set_mcp_session: origen vacío o demasiado largo"));
    const aa = st.arena.child_allocator;
    const copy = aa.dupe(u8, t) catch return @intFromEnum(err(.oom, "da_set_mcp_session: OOM"));
    if (st.mcp_origin.len > 0) aa.free(st.mcp_origin);
    st.mcp_origin = copy;
    return @intFromEnum(ok());
}

/// Desconecta del servidor MCP de Open Design.
pub export fn da_mcp_disconnect(handle: ?*anyopaque) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_mcp_disconnect: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    st.od_mcp_state.disconnect();
    return @intFromEnum(ok());
}

/// MCP-AUTH: devuelve el token de autenticación del servidor MCP como JSON
/// {"token": "...", "file": "<ruta del archivo mcp_token>"}. El panel MCP lo
/// muestra para que el usuario configure clientes externos (IDEs, agentes).
/// El llamador libera con da_string_free.
pub export fn da_mcp_auth_token(handle: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_mcp_auth_token: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    const tok = st.mcp_token orelse return @intFromEnum(err(.invalid_state, "da_mcp_auth_token: token not initialized"));
    const file_path: []const u8 = blk: {
        if (std.mem.eql(u8, st.runtime_path, ":memory:")) break :blk "";
        const dir = std.fs.path.dirname(st.runtime_path) orelse break :blk "";
        break :blk std.fmt.allocPrint(aa, "{s}" ++ std.fs.path.sep_str ++ "mcp_token", .{dir}) catch break :blk "";
    };
    // Serialización JSON correcta (la ruta Windows lleva '\' que hay que escapar).
    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginObject() catch return @intFromEnum(err(.oom, "da_mcp_auth_token: OOM"));
    js.objectField("token") catch return @intFromEnum(err(.oom, "da_mcp_auth_token: OOM"));
    js.write(tok) catch return @intFromEnum(err(.oom, "da_mcp_auth_token: OOM"));
    js.objectField("file") catch return @intFromEnum(err(.oom, "da_mcp_auth_token: OOM"));
    js.write(file_path) catch return @intFromEnum(err(.oom, "da_mcp_auth_token: OOM"));
    js.endObject() catch return @intFromEnum(err(.oom, "da_mcp_auth_token: OOM"));
    const json = out.written();
    out_json.* = ownedCStr(json) orelse return @intFromEnum(err(.oom, "da_mcp_auth_token: OOM"));
    return @intFromEnum(ok());
}

/// Devuelve el estado de conexión: 1 = conectado, 0 = desconectado.
pub export fn da_mcp_is_connected(handle: ?*anyopaque, out_connected: *c_int) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_mcp_is_connected: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    st.od_mcp_state.mutex.lock();
    const c = st.od_mcp_state.connected;
    st.od_mcp_state.mutex.unlock();
    out_connected.* = if (c) 1 else 0;
    return @intFromEnum(ok());
}

/// Lista las tools del servidor MCP como JSON array.
/// El llamador libera con da_string_free.
pub export fn da_mcp_tools_json(handle: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_mcp_tools_json: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    const json = st.od_mcp_state.listToolsJson(aa) catch |e| switch (e) {
        error.NotConnected => return @intFromEnum(err(.invalid_state, "da_mcp_tools_json: not connected")),
        error.ProtocolError => return @intFromEnum(err(.internal, "da_mcp_tools_json: protocol error")),
        error.OutOfMemory => return @intFromEnum(err(.oom, "da_mcp_tools_json: OOM")),
        else => return @intFromEnum(err(.internal, "da_mcp_tools_json: unknown error")),
    };
    out_json.* = ownedCStr(json) orelse return @intFromEnum(err(.oom, "da_mcp_tools_json: OOM"));
    aa.free(json);
    return @intFromEnum(ok());
}

/// Llama una tool del servidor MCP.
/// `name`: nombre de la tool.
/// `args_json`: objeto JSON con argumentos.
/// Devuelve objeto JSON {"content":"...","is_error":bool}.
/// El llamador libera con da_string_free.
pub export fn da_mcp_call_tool(handle: ?*anyopaque, name: [*:0]const u8, args_json: [*:0]const u8, out_result: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_mcp_call_tool: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    const result = st.od_mcp_state.callToolJson(aa, std.mem.span(name), std.mem.span(args_json)) catch |e| switch (e) {
        error.NotConnected => return @intFromEnum(err(.invalid_state, "da_mcp_call_tool: not connected")),
        error.ProtocolError => return @intFromEnum(err(.internal, "da_mcp_call_tool: protocol error")),
        error.OutOfMemory => return @intFromEnum(err(.oom, "da_mcp_call_tool: OOM")),
        else => return @intFromEnum(err(.internal, "da_mcp_call_tool: unknown error")),
    };
    out_result.* = ownedCStr(result) orelse return @intFromEnum(err(.oom, "da_mcp_call_tool: OOM"));
    aa.free(result);
    return @intFromEnum(ok());
}

// ── Token Usage Summary (P08) ───────────────────────────────────────────

/// Devuelve un resumen JSON de tokens consumidos.
/// order_id = 0 → totales globales; order_id > 0 → filtrado por orden.
/// JSON: {"order_id":N,"total_prompt":I,"total_completion":I,"total_tokens":I,
///         "last_prompt":I,"last_provider":"...","last_model":"...",
///         "by_model":[{"provider":"...","model":"...","prompt":I,"completion":I,"total":I}]}
/// El llamador libera con da_string_free.
pub export fn da_usage_summary_json(handle: ?*anyopaque, order_id: c_int, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_usage_summary_json: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    const oid: i64 = @intCast(order_id);

    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginObject() catch return @intFromEnum(err(.oom, "da_usage_summary_json: OOM"));
    js.objectField("order_id") catch return @intFromEnum(err(.oom, "da_usage_summary_json: OOM"));
    js.write(oid) catch return @intFromEnum(err(.oom, "da_usage_summary_json: OOM"));

    // Totales globales (o por orden).
    const total_sql = if (oid > 0)
        "SELECT COALESCE(SUM(prompt_tokens),0), COALESCE(SUM(completion_tokens),0), COALESCE(SUM(total_tokens),0) FROM usage_records WHERE order_id = ?"
    else
        "SELECT COALESCE(SUM(prompt_tokens),0), COALESCE(SUM(completion_tokens),0), COALESCE(SUM(total_tokens),0) FROM usage_records";

    var total_prompt: i64 = 0;
    var total_completion: i64 = 0;
    var total_total: i64 = 0;
    {
        const stmt = st.db_conn.prepare(total_sql) catch return @intFromEnum(err(.internal, "da_usage_summary_json: prepare total"));
        defer st.db_conn.finalize(stmt);
        if (oid > 0) _ = db.bindInt(stmt, 1, oid) catch {};
        if (db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW) {
            total_prompt = db.c.sqlite3_column_int64(stmt, 0);
            total_completion = db.c.sqlite3_column_int64(stmt, 1);
            total_total = db.c.sqlite3_column_int64(stmt, 2);
        }
    }

    js.objectField("total_prompt") catch return @intFromEnum(err(.oom, "da_usage_summary_json: OOM"));
    js.write(total_prompt) catch return @intFromEnum(err(.oom, "da_usage_summary_json: OOM"));
    js.objectField("total_completion") catch return @intFromEnum(err(.oom, "da_usage_summary_json: OOM"));
    js.write(total_completion) catch return @intFromEnum(err(.oom, "da_usage_summary_json: OOM"));
    js.objectField("total_tokens") catch return @intFromEnum(err(.oom, "da_usage_summary_json: OOM"));
    js.write(total_total) catch return @intFromEnum(err(.oom, "da_usage_summary_json: OOM"));

    // r2: ultima llamada con tokens de prompt medidos. El porcentaje
    // de «Contexto» es prompt_tokens de LA ULTIMA llamada / ventana del modelo,
    // no la suma de la orden (esa cuenta cada llamada y supera cualquier
    // ventana). Sin llamadas medidas: 0 y cadenas vacias; la UI dice «estimado».
    var last_prompt: i64 = 0;
    var last_provider_buf: [128]u8 = undefined;
    var last_model_buf: [256]u8 = undefined;
    var last_provider_len: usize = 0;
    var last_model_len: usize = 0;
    {
        const last_sql = if (oid > 0)
            "SELECT prompt_tokens, provider, model FROM usage_records WHERE order_id = ? AND prompt_tokens > 0 ORDER BY id DESC LIMIT 1"
        else
            "SELECT prompt_tokens, provider, model FROM usage_records WHERE prompt_tokens > 0 ORDER BY id DESC LIMIT 1";
        const stmt = st.db_conn.prepare(last_sql) catch return @intFromEnum(err(.internal, "da_usage_summary_json: prepare last"));
        defer st.db_conn.finalize(stmt);
        if (oid > 0) _ = db.bindInt(stmt, 1, oid) catch {};
        if (db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW) {
            last_prompt = db.c.sqlite3_column_int64(stmt, 0);
            const prov = std.mem.span(db.c.sqlite3_column_text(stmt, 1));
            const mod = std.mem.span(db.c.sqlite3_column_text(stmt, 2));
            last_provider_len = @min(prov.len, last_provider_buf.len);
            last_model_len = @min(mod.len, last_model_buf.len);
            @memcpy(last_provider_buf[0..last_provider_len], prov[0..last_provider_len]);
            @memcpy(last_model_buf[0..last_model_len], mod[0..last_model_len]);
        }
    }
    js.objectField("last_prompt") catch return @intFromEnum(err(.oom, "da_usage_summary_json: OOM"));
    js.write(last_prompt) catch return @intFromEnum(err(.oom, "da_usage_summary_json: OOM"));
    js.objectField("last_provider") catch return @intFromEnum(err(.oom, "da_usage_summary_json: OOM"));
    js.write(last_provider_buf[0..last_provider_len]) catch return @intFromEnum(err(.oom, "da_usage_summary_json: OOM"));
    js.objectField("last_model") catch return @intFromEnum(err(.oom, "da_usage_summary_json: OOM"));
    js.write(last_model_buf[0..last_model_len]) catch return @intFromEnum(err(.oom, "da_usage_summary_json: OOM"));

    // Desglose por provider+model.
    js.objectField("by_model") catch return @intFromEnum(err(.oom, "da_usage_summary_json: OOM"));
    js.beginArray() catch return @intFromEnum(err(.oom, "da_usage_summary_json: OOM"));

    const model_sql = if (oid > 0)
        "SELECT provider, model, SUM(prompt_tokens), SUM(completion_tokens), SUM(total_tokens) FROM usage_records WHERE order_id = ? GROUP BY provider, model ORDER BY total_tokens DESC"
    else
        "SELECT provider, model, SUM(prompt_tokens), SUM(completion_tokens), SUM(total_tokens) FROM usage_records GROUP BY provider, model ORDER BY total_tokens DESC";

    {
        const stmt = st.db_conn.prepare(model_sql) catch return @intFromEnum(err(.internal, "da_usage_summary_json: prepare model"));
        defer st.db_conn.finalize(stmt);
        if (oid > 0) _ = db.bindInt(stmt, 1, oid) catch {};
        while (db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW) {
            const prov = db.c.sqlite3_column_text(stmt, 0);
            const mod = db.c.sqlite3_column_text(stmt, 1);
            const pt = db.c.sqlite3_column_int64(stmt, 2);
            const ct = db.c.sqlite3_column_int64(stmt, 3);
            const tt = db.c.sqlite3_column_int64(stmt, 4);
            js.beginObject() catch break;
            js.objectField("provider") catch break;
            js.write(std.mem.span(prov)) catch break;
            js.objectField("model") catch break;
            js.write(std.mem.span(mod)) catch break;
            js.objectField("prompt") catch break;
            js.write(pt) catch break;
            js.objectField("completion") catch break;
            js.write(ct) catch break;
            js.objectField("total") catch break;
            js.write(tt) catch break;
            js.endObject() catch break;
        }
    }

    js.endArray() catch return @intFromEnum(err(.oom, "da_usage_summary_json: OOM"));
    js.endObject() catch return @intFromEnum(err(.oom, "da_usage_summary_json: OOM"));

    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_usage_summary_json: OOM"));
    return @intFromEnum(ok());
}

// ── Web Search (F2) ────────────────────────────────────────────────────

/// Busca en la web usando Tavily (con clave), Brave Search (con clave) o
/// DuckDuckGo (sin clave, default). Devuelve JSON:
/// {"provider":"DuckDuckGo","results":[{"title":"...","url":"...","snippet":"..."}]}
/// Best-effort: en caso de error devuelve {"provider":"...","results":[],"error":"..."}.
/// NUNCA incluye la clave en el output. El caller libera con da_string_free.
pub export fn da_web_search(handle: ?*anyopaque, query: [*:0]const u8, max_results: c_int, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_web_search: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    const query_slice = std.mem.span(query);
    const max: usize = if (max_results > 0) @intCast(max_results) else 5;

    // Determinar proveedor: Tavily → Brave → DuckDuckGo (keyless).
    var provider_name: ?[]const u8 = null;
    var provider_key: ?[]const u8 = null;
    var key_owned: ?[]const u8 = null;
    defer if (key_owned) |k| aa.free(k);

    if (st.catalog_path.len > 0) {
        var cm = credentials.CredentialManager.init(aa, st.catalog_path) catch null;
        if (cm) |*cm_val| {
            defer cm_val.deinit();
            if (cm_val.getKey("Tavily") catch null) |k| {
                key_owned = k;
                provider_name = "Tavily";
                provider_key = k;
            }
            if (provider_key == null) {
                if (cm_val.getKey("Brave Search") catch null) |k| {
                    key_owned = k;
                    provider_name = "Brave Search";
                    provider_key = k;
                }
            }
        }
    }

    // Realizar la búsqueda (best-effort).
    var results: []providers.web_search.SearchResult = &.{};
    var search_error: ?[]const u8 = null;

    {
        var http_opt: ?providers.http_client.HttpClient = providers.http_client.HttpClient.init(aa) catch null;
        if (http_opt) |*http| {
            defer http.deinit();
            if (providers.web_search.search(aa, http, provider_name, provider_key, query_slice, max)) |res| {
                results = res;
            } else |e| {
                search_error = @errorName(e);
            }
        } else {
            search_error = "http init failed";
        }
    }

    // Serializar JSON con el patrón &out.writer (FIX-ENGINE-11: nunca copiar).
    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };

    js.beginObject() catch {
        out_json.* = ownedCStr("{\"provider\":\"\",\"results\":[]}") orelse return @intFromEnum(err(.oom, "da_web_search: OOM"));
        return @intFromEnum(ok());
    };
    js.objectField("provider") catch {};
    js.write(provider_name orelse "DuckDuckGo") catch {};
    js.objectField("results") catch {};
    js.beginArray() catch {};
    for (results) |r| {
        js.beginObject() catch continue;
        js.objectField("title") catch continue;
        js.write(r.title) catch continue;
        js.objectField("url") catch continue;
        js.write(r.url) catch continue;
        js.objectField("snippet") catch continue;
        js.write(r.snippet) catch continue;
        js.endObject() catch continue;
    }
    js.endArray() catch {};
    if (search_error) |se| {
        js.objectField("error") catch {};
        js.write(se) catch {};
    }
    js.endObject() catch {};

    // Liberar resultados.
    for (results) |r| r.deinit(aa);
    if (results.len > 0) aa.free(results);

    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_web_search: OOM"));
    return @intFromEnum(ok());
}

/// P10-T1: Revalida pricing free/pago de los modelos del catálogo usando web_search.
/// Devuelve changes y suggestions; pago→gratis nunca se aplica automáticamente.
/// Best-effort: errores de red no abortan; saltan modelos individuales.
/// El caller libera con da_string_free.
pub export fn da_pricing_revalidate(handle: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_pricing_revalidate: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    var rv = pricingRevalidatorForState(st);
    var result = rv.revalidate(st.catalog_path) catch |e| return pricingRevalidationError(e);
    defer result.deinit(aa);

    out_json.* = ownedCStr(result.changes_json) orelse return @intFromEnum(err(.oom, "da_pricing_revalidate: OOM"));
    return @intFromEnum(ok());
}

// Seam de mapeo compartido por la exportada; no requiere claves ni red.
fn pricingRevalidationError(e: anyerror) c_int {
    var message: [256]u8 = undefined;
    const text = std.fmt.bufPrint(&message, "da_pricing_revalidate: falló la revalidación de precios: {s}", .{@errorName(e)}) catch
        return @intFromEnum(err(.internal, "da_pricing_revalidate: falló el formato del error"));
    return @intFromEnum(err(if (e == error.OutOfMemory) .oom else .internal, text));
}

fn pricingRevalidatorForState(st: *CoreState) pricing_revalidator.PricingRevalidator {
    var rv = pricing_revalidator.PricingRevalidator.init(st.arena.child_allocator, st.catalog.db, st.db_conn);
    // N6: la frontera C ABI debe imponer la superficie, no confiar en el servidor
    // MCP. Sus snippets no autorizan convertir pago en gratis ni eludir el cupo.
    // El núcleo también prohíbe esa promoción automática fuera de MCP.
    if (st.mcp_surface) rv.surface = .mcp;
    return rv;
}

/// P10-T5: Resumen evolutivo del motor (top modelos, cambios pricing, lecciones, último probe).
/// Devuelve JSON consolidado read-only. El caller libera con da_string_free.
pub export fn da_evolution_summary_json(handle: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_evolution_summary_json: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;

    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginObject() catch {
        out_json.* = ownedCStr("{}") orelse return @intFromEnum(err(.oom, "da_evolution_summary_json: OOM"));
        return @intFromEnum(ok());
    };

    // model_scores: top 10 modelos por score (catalog.db)
    js.objectField("top_models") catch {};
    js.beginArray() catch {};
    {
        const stmt = st.catalog.db.prepare("SELECT m.model_name, p.name, ms.task_type, ms.score, ms.sample_count FROM model_scores ms JOIN models m ON ms.model_id = m.id JOIN providers p ON m.provider_id = p.id ORDER BY ms.score DESC LIMIT 10") catch null;
        if (stmt) |s| {
            defer st.catalog.db.finalize(s);
            while (db.c.sqlite3_step(s) == db.c.SQLITE_ROW) {
                js.beginObject() catch continue;
                js.objectField("model") catch continue;
                const mptr = db.c.sqlite3_column_text(s, 0);
                const mlen = db.c.sqlite3_column_bytes(s, 0);
                js.write(if (mptr != null) mptr[0..@intCast(mlen)] else "") catch continue;
                js.objectField("provider") catch continue;
                const pptr = db.c.sqlite3_column_text(s, 1);
                const plen = db.c.sqlite3_column_bytes(s, 1);
                js.write(if (pptr != null) pptr[0..@intCast(plen)] else "") catch continue;
                js.objectField("task_type") catch continue;
                const tptr = db.c.sqlite3_column_text(s, 2);
                const tlen = db.c.sqlite3_column_bytes(s, 2);
                js.write(if (tptr != null) tptr[0..@intCast(tlen)] else "") catch continue;
                js.objectField("score") catch continue;
                js.write(db.c.sqlite3_column_double(s, 3)) catch continue;
                js.objectField("samples") catch continue;
                js.write(db.c.sqlite3_column_int64(s, 4)) catch continue;
                js.endObject() catch continue;
            }
        }
    }
    js.endArray() catch {};

    // pricing_revalidated events (runtime.db) — últimos 20
    js.objectField("pricing_changes") catch {};
    js.beginArray() catch {};
    {
        const stmt = st.db_conn.prepare("SELECT payload_json FROM events WHERE kind = 'pricing_revalidated' ORDER BY ts DESC LIMIT 20") catch null;
        if (stmt) |s| {
            defer st.db_conn.finalize(s);
            while (db.c.sqlite3_step(s) == db.c.SQLITE_ROW) {
                const pptr = db.c.sqlite3_column_text(s, 0);
                const plen = db.c.sqlite3_column_bytes(s, 0);
                const payload = if (pptr != null) pptr[0..@intCast(plen)] else "";
                // Embed raw payload JSON as object
                js.write(std.json.Value{ .string = payload }) catch continue;
            }
        }
    }
    js.endArray() catch {};

    // lessons (memory_findings type='lesson') — últimas 10
    js.objectField("lessons") catch {};
    js.beginArray() catch {};
    {
        const stmt = st.db_conn.prepare("SELECT id, content, created_at FROM memory_findings WHERE type = 'lesson' ORDER BY created_at DESC LIMIT 10") catch null;
        if (stmt) |s| {
            defer st.db_conn.finalize(s);
            while (db.c.sqlite3_step(s) == db.c.SQLITE_ROW) {
                js.beginObject() catch continue;
                js.objectField("id") catch continue;
                js.write(db.c.sqlite3_column_int64(s, 0)) catch continue;
                js.objectField("content") catch continue;
                const cptr = db.c.sqlite3_column_text(s, 1);
                const clen = db.c.sqlite3_column_bytes(s, 1);
                js.write(if (cptr != null) cptr[0..@intCast(clen)] else "") catch continue;
                js.objectField("created_at") catch continue;
                js.write(db.c.sqlite3_column_int64(s, 2)) catch continue;
                js.endObject() catch continue;
            }
        }
    }
    js.endArray() catch {};

    // last_probe: max(ts) from model_health
    js.objectField("last_probe_ts") catch {};
    {
        var last_probe: i64 = 0;
        const stmt = st.db_conn.prepare("SELECT MAX(COALESCE(last_ok_at, last_err_at)) FROM model_health") catch null;
        if (stmt) |s| {
            defer st.db_conn.finalize(s);
            if (db.c.sqlite3_step(s) == db.c.SQLITE_ROW) {
                last_probe = db.c.sqlite3_column_int64(s, 0);
            }
        }
        js.write(last_probe) catch {};
    }

    // last_pricing_sweep: max(ts) from events where kind='pricing_revalidated'
    js.objectField("last_pricing_sweep_ts") catch {};
    {
        var last_sweep: i64 = 0;
        const stmt = st.db_conn.prepare("SELECT MAX(ts) FROM events WHERE kind = 'pricing_revalidated'") catch null;
        if (stmt) |s| {
            defer st.db_conn.finalize(s);
            if (db.c.sqlite3_step(s) == db.c.SQLITE_ROW) {
                last_sweep = db.c.sqlite3_column_int64(s, 0);
            }
        }
        js.write(last_sweep) catch {};
    }

    // order_count: total orders processed
    js.objectField("order_count") catch {};
    {
        var order_count: i64 = 0;
        const stmt = st.db_conn.prepare("SELECT COUNT(*) FROM orders") catch null;
        if (stmt) |s| {
            defer st.db_conn.finalize(s);
            if (db.c.sqlite3_step(s) == db.c.SQLITE_ROW) {
                order_count = db.c.sqlite3_column_int64(s, 0);
            }
        }
        js.write(order_count) catch {};
    }

    // lesson_count: total lessons persisted
    js.objectField("lesson_count") catch {};
    {
        var lesson_count: i64 = 0;
        const stmt = st.db_conn.prepare("SELECT COUNT(*) FROM memory_findings WHERE type = 'lesson'") catch null;
        if (stmt) |s| {
            defer st.db_conn.finalize(s);
            if (db.c.sqlite3_step(s) == db.c.SQLITE_ROW) {
                lesson_count = db.c.sqlite3_column_int64(s, 0);
            }
        }
        js.write(lesson_count) catch {};
    }

    js.endObject() catch {};

    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_evolution_summary_json: OOM"));
    return @intFromEnum(ok());
}

// ── P10-T4: Windows GDI for screenshot capture ────────────────────────
const HDC = ?*anyopaque;
const HBITMAP = ?*anyopaque;
const HGDIOBJ = ?*anyopaque;
const HWND = ?*anyopaque;

extern "user32" fn GetDC(hwnd: HWND) HDC;
extern "user32" fn ReleaseDC(hwnd: HWND, hdc: HDC) c_int;
extern "user32" fn GetSystemMetrics(nIndex: c_int) c_int;
extern "gdi32" fn CreateCompatibleDC(hdc: HDC) HDC;
extern "gdi32" fn CreateCompatibleBitmap(hdc: HDC, w: c_int, h: c_int) HBITMAP;
extern "gdi32" fn SelectObject(hdc: HDC, h: HGDIOBJ) HGDIOBJ;
extern "gdi32" fn DeleteObject(h: HGDIOBJ) c_int;
extern "gdi32" fn DeleteDC(hdc: HDC) c_int;
extern "gdi32" fn BitBlt(hdcDest: HDC, xDest: c_int, yDest: c_int, w: c_int, h: c_int, hdcSrc: HDC, xSrc: c_int, ySrc: c_int, rop: u32) c_int;
extern "gdi32" fn GetDIBits(hdc: HDC, hbmp: HBITMAP, uStartScan: u32, cScanLines: u32, lpvBits: ?[*]u8, lpbi: *BitmapInfo, uUsage: u32) c_int;
const WriteFile = if (@import("builtin").os.tag == .windows) struct {
    extern "kernel32" fn WriteFile(hFile: windows.HANDLE, lpBuffer: [*]const u8, nNumberOfBytesToWrite: u32, lpNumberOfBytesWritten: *u32, lpOverlapped: ?*anyopaque) c_int;
}.WriteFile else @import("providers").posix_files.WriteFile;

const BitmapInfoHeader = extern struct {
    biSize: u32 = @sizeOf(BitmapInfoHeader),
    biWidth: i32 = 0,
    biHeight: i32 = 0,
    biPlanes: u16 = 1,
    biBitCount: u16 = 24,
    biCompression: u32 = 0,
    biSizeImage: u32 = 0,
    biXPelsPerMeter: i32 = 0,
    biYPelsPerMeter: i32 = 0,
    biClrUsed: u32 = 0,
    biClrImportant: u32 = 0,
};

const BitmapInfo = extern struct {
    bmiHeader: BitmapInfoHeader = .{},
    bmiColors: [4]u8 = .{ 0, 0, 0, 0 },
};

/// P10-T4: Captura la pantalla primaria y la guarda en `.screenshots/`.
///
/// El formato es **BMP de 24 bits sin comprimir**, no PNG: se escriben a mano
/// la cabecera de 14 bytes y la DIB de 40, y detras los pixeles crudos de
/// GetDIBits. El comentario anterior decia PNG y la extension siempre ha sido
/// `.bmp`; se corrige la descripcion, no el formato, porque codificar PNG
/// exigiria zlib y aqui no aporta nada.
///
/// `path` sale ABSOLUTA. Antes se devolvia `.screenshots/screenshot_N.bmp`
/// tal cual, relativa al directorio de trabajo del proceso, que no es el mismo
/// que el del usuario: quien recibia esa ruta no podia abrir el archivo.
///
/// Devuelve JSON {ok, path, width, height} o {ok:false, error}.
pub export fn da_capture_screenshot(handle: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_capture_screenshot: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    // QA-B H4 (14-nov): un cliente MCP no ve la pantalla sin permiso humano
    // (como Claude Code con computer use o Codex). Se registra la misma
    // tarjeta que shell_run y la captura la hace la cabina al aprobarla; el
    // resultado se recoge con `approval_result`. Nada se escribe aquí.
    if (st.mcp_surface) {
        const id = requestScreenCaptureApproval(st, aa) catch |e| {
            setLastError(@errorName(e));
            return @intFromEnum(err(.internal, "da_capture_screenshot: no se pudo registrar la aprobación"));
        };
        const pending = std.fmt.allocPrint(aa, "{{\"ok\":false,\"status\":\"pending\",\"approval_id\":{d},\"message\":\"captura de pantalla pendiente de aprobación humana en la cabina; no se tomó. Consulta approval_result con este approval_id.\"}}", .{id}) catch return @intFromEnum(err(.oom, "da_capture_screenshot: OOM"));
        defer aa.free(pending);
        out_json.* = ownedCStr(pending) orelse return @intFromEnum(err(.oom, "da_capture_screenshot: OOM"));
        return @intFromEnum(ok());
    }
    const json = captureScreenJson(aa) catch return @intFromEnum(err(.oom, "da_capture_screenshot: OOM"));
    defer aa.free(json);
    out_json.* = ownedCStr(json) orelse return @intFromEnum(err(.oom, "da_capture_screenshot: OOM"));
    return @intFromEnum(ok());
}

/// Captura la pantalla primaria a `.screenshots/` (ver da_capture_screenshot)
/// y devuelve el JSON {ok, path, width, height} o {ok:false, error}.
fn captureScreenJson(aa: std.mem.Allocator) ![]u8 {
    // T9: captura GDI; en Linux no existe en esta version y se dice.
    if (@import("builtin").os.tag != .windows) return aa.dupe(u8, "{\"ok\":false,\"error\":\"screen_capture_unavailable_on_linux\"}");
    const screen_w = GetSystemMetrics(0);
    const screen_h = GetSystemMetrics(1);
    if (screen_w <= 0 or screen_h <= 0) {
        return aa.dupe(u8, "{\"ok\":false,\"error\":\"screen_metrics_failed\"}");
    }

    const hdc_screen = GetDC(null);
    if (hdc_screen == null) {
        return aa.dupe(u8, "{\"ok\":false,\"error\":\"getdc_failed\"}");
    }
    defer _ = ReleaseDC(null, hdc_screen);

    const hdc_mem = CreateCompatibleDC(hdc_screen);
    if (hdc_mem == null) {
        return aa.dupe(u8, "{\"ok\":false,\"error\":\"create_compatible_dc_failed\"}");
    }
    defer _ = DeleteDC(hdc_mem);

    const hbmp = CreateCompatibleBitmap(hdc_screen, screen_w, screen_h);
    if (hbmp == null) {
        return aa.dupe(u8, "{\"ok\":false,\"error\":\"create_bitmap_failed\"}");
    }
    defer _ = DeleteObject(hbmp);

    _ = SelectObject(hdc_mem, hbmp);
    if (BitBlt(hdc_mem, 0, 0, screen_w, screen_h, hdc_screen, 0, 0, 0x00CC0020) == 0) {
        return aa.dupe(u8, "{\"ok\":false,\"error\":\"bitblt_failed\"}");
    }

    const row_bytes_raw: usize = @intCast(screen_w * 3);
    const row_bytes: usize = (row_bytes_raw + 3) & ~@as(usize, 3);
    const total_pixels: usize = row_bytes * @as(usize, @intCast(screen_h));
    const pixel_buf = aa.alloc(u8, total_pixels) catch {
        return aa.dupe(u8, "{\"ok\":false,\"error\":\"oom_pixels\"}");
    };
    defer aa.free(pixel_buf);

    var bi: BitmapInfo = .{};
    bi.bmiHeader.biWidth = screen_w;
    bi.bmiHeader.biHeight = screen_h;
    bi.bmiHeader.biBitCount = 24;
    bi.bmiHeader.biSize = @sizeOf(BitmapInfoHeader);

    const lines = GetDIBits(hdc_mem, hbmp, 0, @intCast(screen_h), pixel_buf.ptr, &bi, 0);
    if (lines == 0) {
        return aa.dupe(u8, "{\"ok\":false,\"error\":\"getdibits_failed\"}");
    }

    // Write BMP (simplified: raw BMP file, no PNG encoding needed for evidence).
    _ = CreateDirectoryA(".screenshots", null);
    const ts = GetTickCount64();
    const filename = std.fmt.allocPrint(aa, ".screenshots/screenshot_{d}.bmp", .{ts}) catch {
        return aa.dupe(u8, "{\"ok\":false,\"error\":\"oom_filename\"}");
    };
    defer aa.free(filename);
    const filename_z = aa.dupeZ(u8, filename) catch {
        return aa.dupe(u8, "{\"ok\":false,\"error\":\"oom_filename_z\"}");
    };
    defer aa.free(filename_z);

    const INVALID_HANDLE: windows.HANDLE = @ptrFromInt(~@as(usize, 0));
    const file_handle = CreateFileA(filename_z, 0x40000000, 0, null, 2, 0x80, null);
    if (file_handle == INVALID_HANDLE) {
        return aa.dupe(u8, "{\"ok\":false,\"error\":\"create_file_failed\"}");
    }
    defer _ = CloseHandle(file_handle);

    // BMP file header (14 bytes) + DIB header (40 bytes) + pixel data.
    const file_size: u32 = 14 + 40 + @as(u32, @intCast(total_pixels));
    var bmp_header: [14]u8 = .{ 0x42, 0x4D, 0, 0, 0, 0, 0, 0, 0, 0, 54, 0, 0, 0 };
    std.mem.writeInt(u32, bmp_header[2..6], file_size, .little);
    var dib_header: [40]u8 = .{0} ** 40;
    std.mem.writeInt(u32, dib_header[0..4], 40, .little);
    std.mem.writeInt(i32, dib_header[4..8], screen_w, .little);
    std.mem.writeInt(i32, dib_header[8..12], screen_h, .little);
    std.mem.writeInt(u16, dib_header[12..14], 1, .little);
    std.mem.writeInt(u16, dib_header[14..16], 24, .little);

    var written: u32 = 0;
    _ = WriteFile(file_handle, &bmp_header, 14, &written, null);
    _ = WriteFile(file_handle, &dib_header, 40, &written, null);
    _ = WriteFile(file_handle, pixel_buf.ptr, @intCast(total_pixels), &written, null);

    // Build JSON response.
    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    try js.beginObject();
    try js.objectField("ok");
    try js.write(true);
    try js.objectField("path");
    // Ruta absoluta: `filename` es relativa al CWD del proceso, que para la
    // cabina no es el directorio del usuario. Se resuelve con GetFullPathNameA,
    // que es lo que ya usan c_api, cli y superagent para lo mismo; si falla se
    // devuelve la relativa antes que nada.
    var abs_buf: [4096]u8 = undefined;
    const abs_len = GetFullPathNameA(filename_z.ptr, abs_buf.len, @as([*:0]u8, @ptrCast(&abs_buf[0])), null);
    const abs_path = if (abs_len > 0 and abs_len < abs_buf.len) abs_buf[0..abs_len] else filename;
    try js.write(abs_path);
    try js.objectField("width");
    try js.write(screen_w);
    try js.objectField("height");
    try js.write(screen_h);
    try js.endObject();
    return aa.dupe(u8, out.written());
}

/// E5.30: one restricted dispatcher used by standalone engine HTTP and the
/// cabina's local pipe broker. Authentication belongs to the engine HTTP layer.
/// The broker is a private, current-user-only pipe; this is not a public HTTP API.
pub export fn da_remote_request_json(handle: ?*anyopaque, request_json: ?[*:0]const u8, out_json: *?[*:0]u8) callconv(.c) c_int {
    out_json.* = null;
    if (handle == null or request_json == null) return @intFromEnum(err(.invalid_arg, "remote: core and request required"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const allocator = st.arena.child_allocator;
    const json = std.mem.span(request_json.?);
    if (json.len > 16384) return remoteResponse(out_json, 413, "{\"error\":\"cuerpo demasiado grande\"}");
    // `origin` solo lo fija el anfitrión local (la cabina); el servidor remoto
    // construye su petición con tres campos, así que un cliente HTTP no puede
    // declararse «cabina».
    const Request = struct { method: []const u8, path: []const u8, body: []const u8, origin: []const u8 = "http_remoto" };
    const parsed = std.json.parseFromSlice(Request, allocator, json, .{}) catch return remoteResponse(out_json, 400, "{\"error\":\"peticion invalida\"}");
    defer parsed.deinit();
    const request = parsed.value;
    if (request.path.len > 2048 or request.body.len > 8192) return remoteResponse(out_json, 413, "{\"error\":\"cuerpo demasiado grande\"}");
    if (!std.mem.eql(u8, request.method, "GET") and !std.mem.eql(u8, request.method, "POST")) return remoteResponse(out_json, 405, "{\"error\":\"metodo no permitido\"}");
    const is_get = std.mem.eql(u8, request.method, "GET");
    if (is_get and request.body.len != 0) return remoteResponse(out_json, 400, "{\"error\":\"GET no admite cuerpo\"}");
    // SEC2 R6/H1: el servidor remoto lanzado desde MCP (remote_start) es de solo
    // lectura. Todo POST (aprobar/denegar tarjetas, aprobar o cancelar ordenes,
    // restaurar permisos) equivale a una decision humana y exige la cabina.
    if (st.mcp_surface and !is_get) return remoteResponse(out_json, 403, "{\"error\":\"acceso remoto desde MCP es de solo lectura: aprobar, cancelar o restaurar exige la cabina\"}");
    if (std.mem.eql(u8, request.path, "/api/orders") and is_get) {
        var output: [*:0]u8 = undefined;
        const rc = da_sessions_json(handle, &output);
        if (rc != 0) return rc;
        defer da_string_free(output);
        return remoteResponse(out_json, 200, std.mem.span(output));
    }
    if (std.mem.eql(u8, request.path, "/api/approvals") and is_get) {
        var output: [*:0]u8 = undefined;
        const rc = da_approval_pending_json(handle, &output);
        if (rc != 0) return rc;
        defer da_string_free(output);
        return remoteResponse(out_json, 200, std.mem.span(output));
    }
    if (std.mem.startsWith(u8, request.path, "/api/approvals/") and !is_get) {
        const id = std.fmt.parseInt(i64, request.path[15..], 10) catch return remoteResponse(out_json, 400, "{\"error\":\"id invalido\"}");
        if (id <= 0) return remoteResponse(out_json, 400, "{\"error\":\"id invalido\"}");
        const answer = std.json.parseFromSlice(struct { approved: bool }, allocator, request.body, .{}) catch return remoteResponse(out_json, 400, "{\"error\":\"JSON aprobado requerido\"}");
        defer answer.deinit();
        const approval = st.db_conn.prepare("SELECT order_id, resolved FROM approvals WHERE id=?") catch return @intFromEnum(err(.invalid_state, "remote: approval query failed"));
        defer st.db_conn.finalize(approval);
        db.bindInt(approval, 1, id) catch return @intFromEnum(err(.invalid_state, "remote: approval binding failed"));
        if (db.c.sqlite3_step(approval) != db.c.SQLITE_ROW) return remoteResponse(out_json, 404, "{\"error\":\"aprobacion no encontrada\"}");
        if (db.c.sqlite3_column_int(approval, 1) != 0) return remoteResponse(out_json, 409, "{\"error\":\"aprobacion ya resuelta\"}");
        const order_id = db.c.sqlite3_column_int64(approval, 0);
        remoteAction(st, order_id, if (answer.value.approved) "approve" else "deny") catch return @intFromEnum(err(.invalid_state, "remote: event write failed"));
        const rc = da_approval_resolve(handle, id, if (answer.value.approved) 1 else 0);
        return remoteResponse(out_json, if (rc == 0) 200 else 409, if (rc == 0) "{\"ok\":true}" else "{\"error\":\"el motor rechazo la accion\"}");
    }
    if (!std.mem.startsWith(u8, request.path, "/api/orders/")) return remoteResponse(out_json, 404, "{\"error\":\"ruta no encontrada\"}");
    const tail = request.path[12..];
    const split = std.mem.indexOfScalar(u8, tail, '/') orelse tail.len;
    const id = std.fmt.parseInt(i64, tail[0..split], 10) catch return remoteResponse(out_json, 400, "{\"error\":\"id invalido\"}");
    if (id <= 0) return remoteResponse(out_json, 400, "{\"error\":\"id invalido\"}");
    const rec = findOrder(st, id) orelse return remoteResponse(out_json, 404, "{\"error\":\"orden no encontrada\"}");
    const rest = tail[split..];
    if (std.mem.eql(u8, rest, "/workspace/restore_permissions")) {
        if (is_get) return remoteResponse(out_json, 405, "{\"error\":\"restaurar requiere POST explicito\"}");
        const body = std.json.parseFromSlice(struct { explicit: bool }, allocator, request.body, .{}) catch return remoteResponse(out_json, 400, "{\"error\":\"explicit=true requerido; no se admiten rutas\"}");
        defer body.deinit();
        if (!body.value.explicit) return remoteResponse(out_json, 400, "{\"error\":\"restaurar requiere una accion explicita\"}");
        if (rec.status != .failed) return remoteResponse(out_json, 409, "{\"error\":\"la orden debe haber fallado por permisos del espacio\"}");
        const requested_by: []const u8 = if (std.mem.eql(u8, request.origin, "cabina")) "cabina" else "http_remoto";
        // El código nativo lo fija la propia reparación en el instante del
        // fallo: leerlo aquí, tras asignar memoria, podría ser otro error.
        var win32: u32 = 0;
        const restored = restoreOrderWorkspacePermissions(st, rec.db_id orelse rec.id, requested_by, &win32) catch |e| {
            const message = std.json.Stringify.valueAlloc(allocator, .{ .@"error" = @errorName(e), .causa = workspaceRepairCause(e), .win32 = win32 }, .{}) catch return @intFromEnum(err(.oom, "OOM"));
            defer allocator.free(message);
            return remoteResponse(out_json, 409, message);
        };
        defer allocator.free(restored);
        return remoteResponse(out_json, 200, restored);
    }
    if (rest.len == 0 and is_get) {
        var output: [*:0]u8 = undefined;
        const rc = da_sessions_json(handle, &output);
        if (rc != 0) return rc;
        defer da_string_free(output);
        const list = std.json.parseFromSlice(std.json.Value, allocator, std.mem.span(output), .{}) catch return @intFromEnum(err(.invalid_state, "remote: session JSON invalid"));
        defer list.deinit();
        for (list.value.array.items) |session| {
            const session_id = session.object.get("id") orelse continue;
            if (session_id.integer != rec.id) continue;
            const detail = std.json.Stringify.valueAlloc(allocator, session, .{}) catch return @intFromEnum(err(.oom, "remote: detail OOM"));
            defer allocator.free(detail);
            return remoteResponse(out_json, 200, detail);
        }
        return remoteResponse(out_json, 404, "{\"error\":\"orden no encontrada\"}");
    }
    if (std.mem.startsWith(u8, rest, "/events?since=") and is_get) {
        const since = std.fmt.parseInt(i64, rest[14..], 10) catch return remoteResponse(out_json, 400, "{\"error\":\"cursor invalido\"}");
        if (since < 0) return remoteResponse(out_json, 400, "{\"error\":\"cursor invalido\"}");
        var output: [*:0]u8 = undefined;
        const rc = da_order_events_json(handle, orderIdToHandle(rec.id), since, &output);
        if (rc != 0) return rc;
        defer da_string_free(output);
        return remoteResponse(out_json, 200, std.mem.span(output));
    }
    if (!is_get and (std.mem.eql(u8, rest, "/cancel") or std.mem.eql(u8, rest, "/approve"))) {
        const body = std.json.parseFromSlice(struct {}, allocator, request.body, .{}) catch return remoteResponse(out_json, 400, "{\"error\":\"objeto JSON vacio requerido\"}");
        defer body.deinit();
        remoteAction(st, rec.db_id orelse rec.id, rest[1..]) catch return @intFromEnum(err(.invalid_state, "remote: event write failed"));
        const rc = if (std.mem.eql(u8, rest, "/cancel")) da_order_cancel(handle, orderIdToHandle(rec.id)) else da_order_dispatch_async(handle, orderIdToHandle(rec.id));
        return remoteResponse(out_json, if (rc == 0) 200 else 409, if (rc == 0) "{\"ok\":true}" else "{\"error\":\"el motor rechazo la accion\"}");
    }
    return remoteResponse(out_json, 404, "{\"error\":\"ruta no encontrada\"}");
}

fn remoteAction(st: *CoreState, order_id: i64, action: []const u8) !void {
    const payload = try std.json.Stringify.valueAlloc(st.arena.child_allocator, .{ .action = action, .phase = "requested" }, .{});
    defer st.arena.child_allocator.free(payload);
    const stmt = try st.db_conn.prepare("INSERT INTO events(ts,source,kind,payload_json,order_id) VALUES(?,'remote','remote_action',?,?)");
    defer st.db_conn.finalize(stmt);
    try db.bindInt(stmt, 1, health.nowMillis(st.db_conn));
    try db.bindText(stmt, 2, payload);
    try db.bindInt(stmt, 3, order_id);
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE) return error.EventWrite;
}

/// Campos del evento de fallo que identifican el espacio a reparar. La raíz y
/// su identidad (volumen + FileId) las graba el motor al rechazar la raíz.
const RepairEvent = struct {
    @"error": []const u8 = "",
    workspace_root: []const u8 = "",
    workspace_id: []const u8 = "",
};

const root_rejection_prefix = "snapshot: fallo; etapa=raiz; ruta=.; error=CliWritableByOthers;";

/// Solo el rechazo de raíz con escritores ajenos, con la acción nativa y con la
/// raíz/identidad registradas ofrece reparar. Cualquier otra causa (proveedor,
/// binario, perfil, evento sin raíz o sin payload) no autoriza tocar ACL.
fn parseRepairEvent(a: std.mem.Allocator, payload: ?[]const u8) !std.json.Parsed(RepairEvent) {
    const text = payload orelse return error.WorkspaceRestoreNotOffered;
    const parsed = std.json.parseFromSlice(RepairEvent, a, text, .{ .ignore_unknown_fields = true }) catch return error.WorkspaceRestoreNotOffered;
    errdefer parsed.deinit();
    const event = parsed.value;
    if (!std.mem.startsWith(u8, event.@"error", root_rejection_prefix) or std.mem.indexOf(u8, event.@"error", "accion=workspace_acl_restore") == null) return error.WorkspaceRestoreNotOffered;
    if (event.workspace_root.len == 0 or event.workspace_id.len == 0) return error.WorkspaceRestoreNotOffered;
    return parsed;
}

fn workspaceRepairCause(e: anyerror) []const u8 {
    return switch (e) {
        error.WorkspaceRestoreNotOffered => "La última falla de la orden no ofrece restaurar este espacio (o no registró su raíz); no se modificó nada.",
        error.WorkspaceRootChanged => "El espacio que falló ya no es el mismo (otra carpeta o reemplazado); no se modificó nada.",
        error.WorkspacePermissionsAlreadyPrivate => "El espacio ya es privado; no hay nada que restaurar.",
        error.WorkspaceTreeHasLinks => "Se restauró la raíz, pero el espacio contiene enlaces (junction, symlink o vínculo físico) y no se tocaron los hijos. Elimínalos y reintenta.",
        error.WorkspacePermissionsRestoreFailed => "No se pudieron restaurar los permisos del espacio (ver win32).",
        error.HumanDecisionRequired => "Restaurar permisos del espacio es una decision humana: solo la cabina puede pedirla.",
        else => "No se pudo restaurar los permisos del espacio.",
    };
}

fn recordWorkspaceRepairEvent(st: *CoreState, order_id: i64, payload: []const u8) !void {
    const stmt = try st.db_conn.prepare("INSERT INTO events(ts,source,kind,payload_json,order_id) VALUES(?,'workspace','workspace_permissions_restore',?,?)");
    defer st.db_conn.finalize(stmt);
    try db.bindInt(stmt, 1, health.nowMillis(st.db_conn));
    try db.bindText(stmt, 2, payload);
    try db.bindInt(stmt, 3, order_id);
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE) return error.EventWrite;
}

/// Reparación explícita del espacio de una orden. El destino es SIEMPRE el que
/// grabó el evento de fallo (raíz canónica + identidad), nunca el espacio
/// efectivo actual: con otro proyecto abierto no se repararía otra carpeta.
/// Deja un evento previo (SDDL anterior y quién la pidió) para auditarla y
/// poder deshacerla, y otro con el resultado. `win32` recibe el código nativo
/// del fallo de restauración.
///
/// Límite conocido: la reparación exige que la orden esté `failed`, pero no
/// excluye a OTRA orden en curso sobre la misma raíz; si la hubiera, su CLI
/// verá los permisos cambiar bajo sus pies (el efecto es solo cerrar acceso
/// ajeno, nunca abrirlo).
fn restoreOrderWorkspacePermissions(st: *CoreState, order_id: i64, requested_by: []const u8, win32: *u32) ![]u8 {
    // SEC2 R6/H1: defensa en profundidad; la ruta remota ya rechaza todo POST con mcp_surface.
    if (st.mcp_surface) return error.HumanDecisionRequired;
    const a = st.arena.child_allocator;
    const acl = @import("workspace_acl.zig");
    const q = try st.db_conn.prepare("SELECT payload_json FROM events WHERE order_id=? AND kind='external_agent_finished' ORDER BY id DESC LIMIT 1");
    defer st.db_conn.finalize(q);
    try db.bindInt(q, 1, order_id);
    if (db.c.sqlite3_step(q) != db.c.SQLITE_ROW) return error.WorkspaceRestoreNotOffered;
    const raw = db.c.sqlite3_column_text(q, 0);
    const event = try parseRepairEvent(a, if (raw == null) null else std.mem.span(raw));
    defer event.deinit();
    const root = event.value.workspace_root;
    if (!acl.isGoverned(root)) return error.WorkspaceRestoreNotOffered;
    // Retain the governed directory and every ancestor while the path-based
    // repair opens it, and prove it is the very directory that failed.
    var retained = try @import("confined_fs.zig").Root.initSecurity(a, root);
    defer retained.deinit();
    var current = try acl.identity(a, root);
    defer current.deinit(a);
    if (!std.ascii.eqlIgnoreCase(current.canonical, root) or !std.mem.eql(u8, current.id, event.value.workspace_id)) return error.WorkspaceRootChanged;
    // Revalidate the current gate; never repair another cause.
    if (@import("external_cli_policy.zig").checkAcl(retained.dir().handle)) |_| {
        return error.WorkspacePermissionsAlreadyPrivate;
    } else |e| if (e != error.CliWritableByOthers) return e;
    var snapshot = try acl.Snapshot.init(a, root);
    defer snapshot.deinit();
    const previous = try snapshot.sddl(a);
    defer a.free(previous);
    // Sin evento de auditoría no se cambia ningún permiso.
    const requested = try std.json.Stringify.valueAlloc(a, .{ .action = "restore_workspace_permissions", .phase = "requested", .requested_by = requested_by, .root = root, .id = current.id, .previous_sddl = previous }, .{});
    defer a.free(requested);
    try recordWorkspaceRepairEvent(st, order_id, requested);
    // Allocate the response before changing permissions: OOM must not report a
    // rejected action after its side effect has already occurred.
    const result = try std.json.Stringify.valueAlloc(a, .{ .restored = true, .root = root, .message = "Permisos del espacio restaurados. La orden sigue detenida; reintenta explicitamente." }, .{});
    errdefer a.free(result);
    acl.restorePrivate(a, root) catch |e| {
        win32.* = if (e == error.WorkspaceTreeHasLinks) acl.tree_links_code else acl.lastError();
        // La raíz pudo quedar restaurada aunque los hijos no (enlaces): se anota.
        const failed = std.json.Stringify.valueAlloc(a, .{ .action = "restore_workspace_permissions", .phase = "failed", .requested_by = requested_by, .root = root, .id = current.id, .@"error" = @errorName(e), .win32 = win32.* }, .{}) catch return e;
        defer a.free(failed);
        recordWorkspaceRepairEvent(st, order_id, failed) catch |event_error| std.log.warn("workspace repair audit (failed) not recorded: {s}", .{@errorName(event_error)});
        return e;
    };
    const after = snapshot.sddl(a) catch null;
    defer if (after) |value| a.free(value);
    // El cambio ya ocurrió: un evento final que no se pueda escribir no revierte
    // la reparación, pero se registra en el log en vez de ignorarse.
    const done = std.json.Stringify.valueAlloc(a, .{ .action = "restore_workspace_permissions", .phase = "restored", .requested_by = requested_by, .root = root, .id = current.id, .sddl = after }, .{}) catch |event_error| {
        std.log.warn("workspace repair audit (restored) not built: {s}", .{@errorName(event_error)});
        return result;
    };
    defer a.free(done);
    recordWorkspaceRepairEvent(st, order_id, done) catch |event_error| std.log.warn("workspace repair audit (restored) not recorded: {s}", .{@errorName(event_error)});
    return result;
}

fn remoteResponse(out: *?[*:0]u8, status: u16, body: []const u8) c_int {
    if (body.len > 1024 * 1024) return remoteResponse(out, 413, "{\"error\":\"respuesta demasiado grande\"}");
    const allocator = std.heap.page_allocator;
    const json = std.json.Stringify.valueAlloc(allocator, .{ .status = status, .body = body }, .{}) catch return @intFromEnum(err(.oom, "remote: response OOM"));
    defer allocator.free(json);
    out.* = ownedCStr(json) orelse return @intFromEnum(err(.oom, "remote: response OOM"));
    return @intFromEnum(ok());
}

test "E5.30 remote response bounded before serialization" {
    const allocator = std.testing.allocator;
    const body = try allocator.alloc(u8, 1024 * 1024 + 1);
    defer allocator.free(body);
    @memset(body, 'x');
    var output: ?[*:0]u8 = null;
    try std.testing.expectEqual(@as(c_int, 0), remoteResponse(&output, 200, body));
    defer da_string_free(output.?);
    const result = try std.json.parseFromSlice(struct { status: u16, body: []const u8 }, allocator, std.mem.span(output.?), .{});
    defer result.deinit();
    try std.testing.expectEqual(@as(u16, 413), result.value.status);
    try std.testing.expect(result.value.body.len < 100);
}

fn expectRemote(handle: ?*anyopaque, method: []const u8, path: []const u8, body: []const u8, status: u16) ![]u8 {
    return expectRemoteFrom(handle, method, path, body, null, status);
}

/// `origin` solo existe cuando el anfitrión local (cabina) habla con el motor.
fn expectRemoteFrom(handle: ?*anyopaque, method: []const u8, path: []const u8, body: []const u8, origin: ?[]const u8, status: u16) ![]u8 {
    const allocator = std.testing.allocator;
    const request = if (origin) |value|
        try std.json.Stringify.valueAlloc(allocator, .{ .method = method, .path = path, .body = body, .origin = value }, .{})
    else
        try std.json.Stringify.valueAlloc(allocator, .{ .method = method, .path = path, .body = body }, .{});
    defer allocator.free(request);
    const z = try allocator.dupeZ(u8, request);
    defer allocator.free(z);
    var output: ?[*:0]u8 = null;
    try std.testing.expectEqual(@as(c_int, 0), da_remote_request_json(handle, z, &output));
    const string = output orelse return error.TestExpectedEqual;
    defer da_string_free(string);
    const parsed = try std.json.parseFromSlice(struct { status: u16, body: []const u8 }, allocator, std.mem.span(string), .{});
    defer parsed.deinit();
    try std.testing.expectEqual(status, parsed.value.status);
    return allocator.dupe(u8, parsed.value.body);
}

/// Espacio gobernado contaminado: devagents-workspace con «Todos» con control total.
fn contaminatedGovernedRoot(a: std.mem.Allocator, io: std.Io, project: []const u8) ![]u8 {
    try std.Io.Dir.cwd().createDirPath(io, project);
    const root = try std.fmt.allocPrint(a, "{s}" ++ std.fs.path.sep_str ++ "devagents-workspace", .{project});
    errdefer a.free(root);
    try @import("external_cli_policy.zig").createPrivateDirectory(a, root);
    var grant = try headless_adapter.defaultCapture(a, &.{ "icacls.exe", root, "/grant", "*S-1-1-0:(F)" }, null);
    defer grant.deinit(a);
    try std.testing.expectEqual(@as(u32, 0), grant.exit_code);
    return root;
}

/// Evento de fallo de raíz tal como lo graba superagent: causa + raíz e identidad.
fn insertRootRejection(st: *CoreState, order_id: i64, root: []const u8, identity: []const u8) !void {
    const a = st.arena.child_allocator;
    const payload = try std.json.Stringify.valueAlloc(a, .{
        .@"error" = "snapshot: fallo; etapa=raiz; ruta=.; error=CliWritableByOthers; win32=0; escritores=otro escritor; accion=workspace_acl_restore",
        .workspace_root = root,
        .workspace_id = identity,
    }, .{});
    defer a.free(payload);
    const insert = try st.db_conn.prepare("INSERT INTO events(ts,source,kind,payload_json,order_id) VALUES(0,'fixture','external_agent_finished',?,?)");
    defer st.db_conn.finalize(insert);
    try db.bindText(insert, 1, payload);
    try db.bindInt(insert, 2, order_id);
    try std.testing.expectEqual(db.c.SQLITE_DONE, db.c.sqlite3_step(insert));
}

test "SNAP B2 workspace permissions repair is explicit governed and retains user files" {
    if (@import("builtin").os.tag != .windows) return @import("platform.zig").skip("T9: SDDL y ACE de Windows; los permisos del espacio de trabajo no existen en Linux (WorkspacePermissionsUnavailableOnLinux)");
    const a = std.testing.allocator;
    var threaded = std.Io.Threaded.init(a, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const project = try isolatedTestPath(&tmp, "snap-b2-project");
    defer a.free(project);
    const root = try contaminatedGovernedRoot(a, io, project);
    defer a.free(root);
    const sentinel = try std.fmt.allocPrint(a, "{s}" ++ std.fs.path.sep_str ++ "user.txt", .{root});
    defer a.free(sentinel);
    try std.Io.Dir.cwd().writeFile(io, .{ .sub_path = sentinel, .data = "user data unchanged" });
    const other = try isolatedTestPath(&tmp, "snap-b2-other");
    defer a.free(other);
    try std.Io.Dir.cwd().createDirPath(io, other);
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    defer workspace.setWorkspaceRoot(workspace.WORKSPACE_ROOT);
    try workspace.setWorkspaceRootChecked(project);
    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "fixture repair", "snap-b2", null, &order));
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    const id = orderHandleToId(order).?;
    const rec = findOrder(st, id).?;
    const order_db_id = rec.db_id orelse rec.id;
    rec.status = .failed;
    const route = try std.fmt.allocPrint(a, "/api/orders/{d}/workspace/restore_permissions", .{id});
    defer a.free(route);
    const absent = try expectRemote(handle, "POST", route, "{\"explicit\":true}", 409);
    defer a.free(absent);
    var identity = try @import("workspace_acl.zig").identity(a, root);
    defer identity.deinit(a);
    try insertRootRejection(st, order_db_id, identity.canonical, identity.id);
    for ([_]struct { method: []const u8 = "POST", body: []const u8, status: u16 = 400 }{
        .{ .method = "GET", .body = "", .status = 405 },
        .{ .body = "{}" },
        .{ .body = "{\"explicit\":false}" },
        .{ .body = "{\"explicit\":true,\"root\":\"C:/arbitrary\"}" },
    }) |request| {
        const response = try expectRemote(handle, request.method, route, request.body, request.status);
        a.free(response);
        try std.testing.expectError(error.CliWritableByOthers, workspace.ensureExternalRoot(a, io, root));
    }
    // Una orden que no falló nunca ofrece la reparación.
    for ([_]superagent.OrderStatus{ .done, .running, .pending }) |state| {
        rec.status = state;
        const response = try expectRemote(handle, "POST", route, "{\"explicit\":true}", 409);
        a.free(response);
        try std.testing.expectError(error.CliWritableByOthers, workspace.ensureExternalRoot(a, io, root));
    }
    rec.status = .failed;
    // Identidad distinta (carpeta reemplazada): cause visible y sin cambios.
    try insertRootRejection(st, order_db_id, identity.canonical, "0000000000000000-00000000000000000000000000000000");
    const changed = try expectRemote(handle, "POST", route, "{\"explicit\":true}", 409);
    defer a.free(changed);
    try std.testing.expect(std.mem.indexOf(u8, changed, "WorkspaceRootChanged") != null);
    try std.testing.expect(std.mem.indexOf(u8, changed, "no se modificó nada") != null);
    try std.testing.expectError(error.CliWritableByOthers, workspace.ensureExternalRoot(a, io, root));
    // Con otro proyecto abierto, la reparación sigue siendo de la raíz que falló.
    try insertRootRejection(st, order_db_id, identity.canonical, identity.id);
    try workspace.setWorkspaceRootChecked(other);
    const result = try expectRemote(handle, "POST", route, "{\"explicit\":true}", 200);
    defer a.free(result);
    try std.testing.expect(std.mem.indexOf(u8, result, "\"restored\":true") != null);
    try workspace.ensureExternalRoot(a, io, root);
    const data = try std.Io.Dir.cwd().readFileAlloc(io, sentinel, a, .limited(100));
    defer a.free(data);
    try std.testing.expectEqualStrings("user data unchanged", data);
    try std.testing.expectEqual(superagent.OrderStatus.failed, rec.status);
    // Ya privado: no hay nada que restaurar.
    const private = try expectRemote(handle, "POST", route, "{\"explicit\":true}", 409);
    defer a.free(private);
    try std.testing.expect(std.mem.indexOf(u8, private, "WorkspacePermissionsAlreadyPrivate") != null);
    // Auditoría: SDDL previo y quién la pidió, antes y después del cambio.
    const audit = try st.db_conn.prepare("SELECT payload_json FROM events WHERE order_id=? AND kind='workspace_permissions_restore' ORDER BY id");
    defer st.db_conn.finalize(audit);
    try db.bindInt(audit, 1, order_db_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(audit));
    const requested = std.mem.span(db.c.sqlite3_column_text(audit, 0));
    try std.testing.expect(std.mem.indexOf(u8, requested, "\"phase\":\"requested\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, requested, "\"requested_by\":\"http_remoto\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, requested, "\"previous_sddl\":\"O:") != null);
    try std.testing.expect(std.mem.indexOf(u8, requested, ";WD)") != null);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(audit));
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(db.c.sqlite3_column_text(audit, 0)), "\"phase\":\"restored\"") != null);
    try std.testing.expectEqual(db.c.SQLITE_DONE, db.c.sqlite3_step(audit));
}

test "SNAP B2 workspace repair rejects a root that is not the governed workspace and records the cabina origin" {
    if (@import("builtin").os.tag != .windows) return @import("platform.zig").skip("T9: SDDL y ACE de Windows; los permisos del espacio de trabajo no existen en Linux (WorkspacePermissionsUnavailableOnLinux)");
    const a = std.testing.allocator;
    var threaded = std.Io.Threaded.init(a, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const project = try isolatedTestPath(&tmp, "snap-b2-name");
    defer a.free(project);
    // Carpeta de usuario cualquiera (no se llama devagents-workspace) con ACL ajena.
    const foreign = try std.fmt.allocPrint(a, "{s}" ++ std.fs.path.sep_str ++ "proyecto", .{project});
    defer a.free(foreign);
    try std.Io.Dir.cwd().createDirPath(io, foreign);
    var grant = try headless_adapter.defaultCapture(a, &.{ "icacls.exe", foreign, "/grant", "*S-1-1-0:(F)" }, null);
    defer grant.deinit(a);
    try std.testing.expectEqual(@as(u32, 0), grant.exit_code);
    const governed_project = try std.fmt.allocPrint(a, "{s}" ++ std.fs.path.sep_str ++ "gobernado", .{project});
    defer a.free(governed_project);
    const governed = try contaminatedGovernedRoot(a, io, governed_project);
    defer a.free(governed);
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "fixture name", "snap-b2-name", null, &order));
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    const id = orderHandleToId(order).?;
    const rec = findOrder(st, id).?;
    const order_db_id = rec.db_id orelse rec.id;
    rec.status = .failed;
    const route = try std.fmt.allocPrint(a, "/api/orders/{d}/workspace/restore_permissions", .{id});
    defer a.free(route);
    var foreign_identity = try @import("workspace_acl.zig").identity(a, foreign);
    defer foreign_identity.deinit(a);
    try insertRootRejection(st, order_db_id, foreign_identity.canonical, foreign_identity.id);
    const refused = try expectRemote(handle, "POST", route, "{\"explicit\":true}", 409);
    defer a.free(refused);
    try std.testing.expect(std.mem.indexOf(u8, refused, "WorkspaceRestoreNotOffered") != null);
    var after = try @import("workspace_acl.zig").Snapshot.init(a, foreign);
    defer after.deinit();
    const foreign_sddl = try after.sddl(a);
    defer a.free(foreign_sddl);
    try std.testing.expect(std.mem.indexOf(u8, foreign_sddl, ";WD)") != null);
    // La cabina se declara «cabina»; un cliente HTTP no puede hacerlo.
    var identity = try @import("workspace_acl.zig").identity(a, governed);
    defer identity.deinit(a);
    try insertRootRejection(st, order_db_id, identity.canonical, identity.id);
    const result = try expectRemoteFrom(handle, "POST", route, "{\"explicit\":true}", "cabina", 200);
    defer a.free(result);
    const audit = try st.db_conn.prepare("SELECT payload_json FROM events WHERE order_id=? AND kind='workspace_permissions_restore' ORDER BY id LIMIT 1");
    defer st.db_conn.finalize(audit);
    try db.bindInt(audit, 1, order_db_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(audit));
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(db.c.sqlite3_column_text(audit, 0)), "\"requested_by\":\"cabina\"") != null);
}

test "SNAP B2 repair event without payload or without a recorded root is never offered" {
