        "{\"error\":\"snapshot: fallo; etapa=raiz; ruta=.; error=CliWritableByOthers; win32=0\",\"workspace_root\":\"C:\\\\x\\\\devagents-workspace\",\"workspace_id\":\"1-2\"}",
    }) |payload| try std.testing.expectError(error.WorkspaceRestoreNotOffered, parseRepairEvent(a, payload));
    const offered = try parseRepairEvent(a, "{\"error\":\"snapshot: fallo; etapa=raiz; ruta=.; error=CliWritableByOthers; win32=0; accion=workspace_acl_restore\",\"workspace_root\":\"C:\\\\x\\\\devagents-workspace\",\"workspace_id\":\"1-2\"}");
