}

test "E5.30 remote dispatcher rejects input and restricted routes" {
    var output: ?[*:0]u8 = null;
    try std.testing.expect(da_remote_request_json(null, "{}", &output) != 0);
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    try std.testing.expect(da_remote_request_json(handle, null, &output) != 0);
    try std.testing.expectEqual(@as(c_int, 0), da_remote_request_json(handle, "malformed", &output));
    da_string_free(output.?);
    for ([_]struct { method: []const u8, path: []const u8, body: []const u8 = "", status: u16 }{
        .{ .method = "PUT", .path = "/api/orders", .status = 405 },
        .{ .method = "GET", .path = "/api/orders", .body = "{}", .status = 400 },
        .{ .method = "GET", .path = "/api/providers", .status = 404 },
        .{ .method = "GET", .path = "/api/orders/999999", .status = 404 },
        .{ .method = "GET", .path = "/api/orders/0", .status = 400 },
        .{ .method = "GET", .path = "/api/orders/invalid", .status = 400 },
        .{ .method = "POST", .path = "/api/approvals/0", .body = "{}", .status = 400 },
        .{ .method = "POST", .path = "/api/approvals/999", .body = "{\"approved\":true}", .status = 404 },
        .{ .method = "POST", .path = "/api/approvals/999", .body = "{\"approved\":true,\"extra\":1}", .status = 400 },
    }) |request| {
        const response = try expectRemote(handle, request.method, request.path, request.body, request.status);
        std.testing.allocator.free(response);
    }
    const huge = try std.testing.allocator.alloc(u8, 8193);
    defer std.testing.allocator.free(huge);
    @memset(huge, 'x');
    const response = try expectRemote(handle, "POST", "/api/orders", huge, 413);
    defer std.testing.allocator.free(response);
}

