test "c_api: planToJson emite owns y deliverable y planFromJson los recupera" {
    const allocator = std.testing.allocator;
    var owns = [_][]const u8{"index.html"};
    var owns2 = [_][]const u8{"app.js"};
    var tasks = [_]planner.PlannedTask{
        .{ .id = "t1", .task_type = .programar, .department = "programacion", .description = "Crear index.html", .contract_fields = &.{}, .depends_on = &.{}, .owns = owns[0..], .deliverable = "pagina" },
        .{ .id = "t2", .task_type = .programar, .department = "programacion", .description = "Crear app.js", .contract_fields = &.{}, .depends_on = &.{}, .owns = owns2[0..], .deliverable = "pagina" },
    };
    const questions = try allocator.alloc(planner.ClarificationQuestion, 0);
    defer allocator.free(questions);
    var plan = planner.Plan{ .allocator = allocator, .understanding = "web", .questions = questions, .tasks = tasks[0..] };

    const json = try planToJson(allocator, &plan);
    defer allocator.free(json);
    try std.testing.expect(std.mem.indexOf(u8, json, "\"owns\":[\"index.html\"]") != null);
    try std.testing.expect(std.mem.indexOf(u8, json, "\"deliverable\":\"pagina\"") != null);

    var restored = try planFromJson(allocator, json);
    defer restored.deinit();
    try std.testing.expectEqual(@as(usize, 2), restored.tasks.len);
    try std.testing.expectEqual(@as(usize, 1), restored.tasks[0].owns.len);
    try std.testing.expectEqualStrings("index.html", restored.tasks[0].owns[0]);
    try std.testing.expectEqualStrings("pagina", restored.tasks[0].deliverable.?);
}

test "c_api: planFromJson inyecta verdict required en tareas auditar sin él" {
    const allocator = std.testing.allocator;
    var plan = try planFromJson(allocator,
        \\{"understanding":"auditar","tasks":[
        \\ {"id":"t1","task_type":"auditar","department":"auditoria","description":"auditar el motor","depends_on":[],"contract_fields":[{"name":"source","type":"string","required":true},{"name":"filename","type":"string","required":true,"value":"audit.md"}]},
        \\ {"id":"t2","task_type":"auditar","department":"auditoria","description":"auditar la cabina","depends_on":[],"contract_fields":[{"name":"Verdict","type":"string","required":true}]},
        \\ {"id":"t3","task_type":"programar","department":"programacion","description":"codigo","depends_on":[],"contract_fields":[{"name":"source","type":"string","required":true}]}
        \\]}
    );
    defer plan.deinit();
    // t1: el plan LLM no traía verdict — debe inyectarse como required.
    const t1 = plan.tasks[0];
    try std.testing.expectEqual(@as(usize, 3), t1.contract_fields.len);
    const v = t1.contract_fields[2];
    try std.testing.expectEqualStrings("verdict", v.name);
    try std.testing.expect(v.required);
    try std.testing.expectEqual(@as(?[]const u8, null), v.value);
    // t2: ya traía Verdict (cualquier casing) — no se duplica.
    try std.testing.expectEqual(@as(usize, 1), plan.tasks[1].contract_fields.len);
    // t3: no es auditar — intacto.
    try std.testing.expectEqual(@as(usize, 1), plan.tasks[2].contract_fields.len);
    try std.testing.expectEqualStrings("source", plan.tasks[2].contract_fields[0].name);
}

