const DeleteFileA = if (@import("builtin").os.tag == .windows) struct {
    extern "kernel32" fn DeleteFileA(lpFileName: [*:0]const u8) callconv(.winapi) std.os.windows.BOOL;
}.DeleteFileA else @import("providers").posix_files.DeleteFileA;

fn isolatedTestPath(tmp: *const std.testing.TmpDir, filename: []const u8) ![:0]u8 {
    // runtime, catalog y ledger deben tener un directorio propio: un nombre
    // runtime único en %TEMP% aún compartía catalog.db con otros procesos.
    var threaded = std.Io.Threaded.init(std.testing.allocator, .{});
    defer threaded.deinit();
    const directory = try tmp.dir.realPathFileAlloc(threaded.io(), ".", std.testing.allocator);
    defer std.testing.allocator.free(directory);
    const path = try std.fmt.allocPrint(
        std.testing.allocator,
        "{s}" ++ std.fs.path.sep_str ++ "{s}",
        .{ directory, filename },
    );
    defer std.testing.allocator.free(path);
    return std.testing.allocator.dupeZ(u8, path);
}

test "B7 isolation: file-backed fixtures own runtime catalog and ledger directory" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try tmp.dir.realPathFileAlloc(std.testing.io, ".", std.testing.allocator);
    defer std.testing.allocator.free(root);
    const runtime = try isolatedTestPath(&tmp, "runtime.db");
    defer std.testing.allocator.free(runtime);
    try std.testing.expectEqualStrings(root, std.fs.path.dirname(runtime).?);
    for ([_][]const u8{ "catalog.db", "ledger.db" }) |filename| {
        const fixture = try isolatedTestPath(&tmp, filename);
        defer std.testing.allocator.free(fixture);
        const sibling = try deriveSiblingPath(std.testing.allocator, runtime, filename);
        defer std.testing.allocator.free(sibling);
        try std.testing.expectEqualStrings(fixture, sibling);
    }
    var other = std.testing.tmpDir(.{});
    defer other.cleanup();
    const other_catalog = try isolatedTestPath(&other, "catalog.db");
    defer std.testing.allocator.free(other_catalog);
    const catalog = try isolatedTestPath(&tmp, "catalog.db");
    defer std.testing.allocator.free(catalog);
    try std.testing.expect(!std.mem.eql(u8, catalog, other_catalog));
}

