const SetEnvironmentVariableA = if (@import("builtin").os.tag == .windows) struct {
    extern "kernel32" fn SetEnvironmentVariableA(lpName: [*:0]const u8, lpValue: ?[*:0]const u8) c_int;
}.SetEnvironmentVariableA else @import("providers").posix_files.SetEnvironmentVariableA;

test "CK-PLT-007: da_core_init con nombre simple abre runtime.db en BEATS_DATA_DIR" {
    const allocator = std.testing.allocator;
    var prev_beats: [4096:0]u8 = undefined;
    var prev_alias: [4096:0]u8 = undefined;
    const beats_len = GetEnvironmentVariableA("BEATS_DATA_DIR", &prev_beats, prev_beats.len);
    const alias_len = GetEnvironmentVariableA("DEVAGENTS_DATA_DIR", &prev_alias, prev_alias.len);
    defer {
        _ = SetEnvironmentVariableA("BEATS_DATA_DIR", if (beats_len > 0) prev_beats[0..beats_len :0].ptr else null);
        _ = SetEnvironmentVariableA("DEVAGENTS_DATA_DIR", if (alias_len > 0) prev_alias[0..alias_len :0].ptr else null);
    }
    _ = SetEnvironmentVariableA("DEVAGENTS_DATA_DIR", null);

    // Carpeta de datos temporal bajo .zig-cache, dentro del propio arbol del
    // worktree (el encargo prohíbe fijar variables de datos en los comandos:
    // la fija este codigo de prueba).
    const io = std.testing.io;
    const cwd = try std.Io.Dir.cwd().realPathFileAlloc(io, ".", allocator);
    defer allocator.free(cwd);
    const dir_plain = try std.fmt.allocPrint(allocator, "{s}" ++ std.fs.path.sep_str ++ ".zig-cache" ++ std.fs.path.sep_str ++ "CK-PLT-007-core", .{cwd});
    defer allocator.free(dir_plain);
    const dir = try allocator.dupeZ(u8, dir_plain);
    defer allocator.free(dir);
    try std.Io.Dir.cwd().createDirPath(io, dir);
    defer std.Io.Dir.cwd().deleteTree(io, dir) catch {};

    _ = SetEnvironmentVariableA("BEATS_DATA_DIR", dir.ptr);

    // Antes de abrir: si no hay runtime.db en el cwd de la suite, tampoco debe
    // aparecer tras el init (la base NO se abre relativa al cwd). Se comprueba
    // "antes y despues" porque el cwd de la suite es compartido por toda la
    // corrida y otros tests pueden dejar un runtime.db ahi (fallo observado en
    // la regresion completa de r2).
    const cwd_runtime = try std.fmt.allocPrint(allocator, "{s}" ++ std.fs.path.sep_str ++ "runtime.db", .{cwd});
    defer allocator.free(cwd_runtime);
    const cwd_runtime_z = try allocator.dupeZ(u8, cwd_runtime);
    defer allocator.free(cwd_runtime_z);
    const cwd_tenia_db = GetFileAttributesA(cwd_runtime_z) != 0xFFFFFFFF;

    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, "runtime.db"));
    defer _ = da_core_shutdown(handle);

    // La base real se abrio en la carpeta del override, no relativa al cwd.
    const runtime_plain = try std.fmt.allocPrint(allocator, "{s}" ++ std.fs.path.sep_str ++ "runtime.db", .{dir});
    defer allocator.free(runtime_plain);
    const runtime_in_dir = try allocator.dupeZ(u8, runtime_plain);
    defer allocator.free(runtime_in_dir);
    try std.testing.expect(GetFileAttributesA(runtime_in_dir) != 0xFFFFFFFF);
    const catalog_plain = try std.fmt.allocPrint(allocator, "{s}" ++ std.fs.path.sep_str ++ "catalog.db", .{dir});
    defer allocator.free(catalog_plain);
    const catalog_in_dir = try allocator.dupeZ(u8, catalog_plain);
    defer allocator.free(catalog_in_dir);
    try std.testing.expect(GetFileAttributesA(catalog_in_dir) != 0xFFFFFFFF);
    if (!cwd_tenia_db) {
        try std.testing.expect(GetFileAttributesA(cwd_runtime_z) == 0xFFFFFFFF);
    }
}

test "c_api: provider add, key add, model register" {
    // Usa archivo real (no :memory:) porque CredentialManager y ModelCatalog
    // abren conexiones separadas; en :memory: cada open es una BD distinta
    // y el proveedor añadido por CredentialManager no es visible al ModelCatalog.
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try isolatedTestPath(&tmp, "runtime.db");
    defer std.testing.allocator.free(path);
    const catalog_path = try isolatedTestPath(&tmp, "catalog.db");
    defer std.testing.allocator.free(catalog_path);
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, path));
    defer _ = da_core_shutdown(handle);

    try std.testing.expectEqual(@as(c_int, 0), da_provider_add(handle, "TestProv", "openai", "https://test.com/v1"));
    try std.testing.expectEqual(@as(c_int, 0), da_key_add(handle, "TestProv", "default", "sk-test123"));
    try std.testing.expectEqual(@as(c_int, 0), da_model_register(handle, "TestProv", "gpt-test", 128000, 1));

    var models: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_models_list_json(handle, &models));
    const models_str = std.mem.span(models);
    try std.testing.expect(std.mem.indexOf(u8, models_str, "gpt-test") != null);
    da_string_free(models);

    // El catálogo está dentro de tmp.dir; comprobar la limpieza sin ocultar errores.
    var clean = try model_catalog.ModelCatalog.init(std.testing.allocator, catalog_path);
    defer clean.deinit();
    try clean.db.exec("DELETE FROM api_keys WHERE provider_id IN (SELECT id FROM providers WHERE name='TestProv')");
    try clean.db.exec("DELETE FROM models WHERE provider_id IN (SELECT id FROM providers WHERE name='TestProv')");
    try clean.db.exec("DELETE FROM providers WHERE name='TestProv'");
}

