test "c_api: da_key_set_meta edita prioridad y cuota y keys_json las expone (E1.13)" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try isolatedTestPath(&tmp, "runtime.db");
    defer std.testing.allocator.free(path);
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, path));
    defer _ = da_core_shutdown(handle);

    try std.testing.expectEqual(@as(c_int, 0), da_provider_add(handle, "MetaProv", "openai", "https://meta.test/v1"));
    try std.testing.expectEqual(@as(c_int, 0), da_key_add(handle, "MetaProv", "KEY_A", "sk-meta-a"));
    try std.testing.expectEqual(@as(c_int, 0), da_key_add(handle, "MetaProv", "KEY_B", "sk-meta-b"));

    // E1.13: sin set_meta, keys_json expone priority/quota_limit = 0.
    var json0: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_keys_json(handle, &json0));
    const s0 = std.mem.span(json0);
    try std.testing.expect(std.mem.indexOf(u8, s0, "\"priority\":0") != null);
    da_string_free(json0);

    // Edita prioridad/cuota/estado de KEY_A solamente.
    try std.testing.expectEqual(@as(c_int, 0), da_key_set_meta(handle, "MetaProv", "KEY_A", 7, 500, "cooling"));

    // -1/-1/vacío = no tocar: una llamada neutra no debe pisar lo escrito.
    try std.testing.expectEqual(@as(c_int, 0), da_key_set_meta(handle, "MetaProv", "KEY_A", -1, -1, null));

    var json: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_keys_json(handle, &json));
    defer da_string_free(json);
    const s = std.mem.span(json);
    // KEY_A refleja la edición; KEY_B quedó intacta.
    try std.testing.expect(std.mem.indexOf(u8, s, "\"label\":\"KEY_A\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, s, "\"priority\":7") != null);
    try std.testing.expect(std.mem.indexOf(u8, s, "\"quota_limit\":500") != null);
    try std.testing.expect(std.mem.indexOf(u8, s, "\"status\":\"cooling\"") != null);

    // Clave inexistente → not_found, no éxito falso.
    try std.testing.expect(da_key_set_meta(handle, "MetaProv", "NO_EXISTE", 1, 1, null) != 0);
}

test "c_api: da_string_free libera (F1) y los strings cruzan NUL-terminados (F2)" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);

    // F2: cada string debe estar NUL-terminado → span no lee fuera del buffer.
    var models: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_models_list_json(handle, &models));
    try std.testing.expect(std.mem.span(models).len >= 2); // al menos "[]"
    da_string_free(models); // F1: libera de c_allocator sin crashear

    var hjson: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_health_summary_json(handle, &hjson));
    da_string_free(hjson);

    var approvals: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_approval_pending_json(handle, &approvals));
    da_string_free(approvals);

    var memjson: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_memory_context_json(handle, "p", &memjson));
    da_string_free(memjson);

    // Ciclo asignar→liberar repetido: si da_string_free volviera a ser no-op, sería
    // fuga; si liberara con un allocator distinto al de ownedCStr, sería UB/crash.
    var i: usize = 0;
    while (i < 200) : (i += 1) {
        var w: [*:0]u8 = undefined;
        try std.testing.expectEqual(@as(c_int, 0), da_worker_output_poll(handle, 0, &w));
        da_string_free(w);
    }
}

