test "c_api: da_sessions_json live title uses user prompt over understanding (P1) with ellipsis at 80 (P4)" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);

    var order1: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "Hola", "test", null, &order1));

    // El planificador creyo entender otra cosa. Antes las sesiones VIVAS se
    // titulaban con ese entendimiento («El usuario solicita crear…») mientras
    // las persistidas ya usaban el prompt: la fila cambiaba de nombre al pasar
    // a la base. Se inserta un entendimiento distinto para forzar el desempate
    // y comprobar que gana el texto del usuario (title > prompt > entendimiento).
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const rec = st.orders.items[st.orders.items.len - 1];
    const db_id: i64 = rec.db_id orelse rec.id;
    const ins = try st.db_conn.prepare("INSERT INTO plans (order_id, understanding, clarifications_json, approved, created_at) VALUES (?, ?, '[]', 0, 1)");
    defer st.db_conn.finalize(ins);
    try db.bindInt(ins, 1, db_id);
    try db.bindText(ins, 2, "El usuario solicita crear un archivo de configuracion");
    try std.testing.expect(db.c.sqlite3_step(ins) == db.c.SQLITE_DONE);

    var json: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_sessions_json(handle, &json));
    const str = std.mem.span(json);
    try std.testing.expect(std.mem.indexOf(u8, str, "\"title\":\"Hola\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, str, "El usuario solicita crear") == null);
    da_string_free(json);

    // P4: prompt multilinea largo; el primer renglon ya pasa de 80, asi que el
    // recorte cae dentro del y se cierra con «…»; la segunda linea no asoma.
    const largo = "crea una aplicacion web con un contador que suba y baje con dos botones grandes ahora\nsegunda linea que no debe aparecer en el titulo";
    var order2: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, largo, "test", null, &order2));

    var json2: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_sessions_json(handle, &json2));
    const str2 = std.mem.span(json2);
    try std.testing.expect(std.mem.indexOf(u8, str2, "\u{2026}") != null);
    try std.testing.expect(std.mem.indexOf(u8, str2, "segunda linea") == null);
    da_string_free(json2);
}

