    _ = da_plan_get_json(handle, order, &json);
    if (std.mem.indexOf(u8, std.mem.span(json), "needs_clarification\":true") != null) {
        _ = da_order_answer(handle, order, "[{\"question_id\":\"q1\",\"answer\":\"en C\"}]");
        da_string_free(json);
        _ = da_plan_get_json(handle, order, &json);
        da_string_free(json);
    }

    const rc = da_order_confirm_json(handle, order, "{\"bad\":1}");
    try std.testing.expect(rc != 0);
}

