test "c_api: shell run innocent command via mock spawn" {
    const Mock = struct {
        fn spawn(a: std.mem.Allocator, exe: []const u8, args: []const []const u8, cwd: []const u8, timeout_ms: u32, cap: usize, sink: ?executor.StreamSink, sink_ctx: ?*anyopaque, _: []const u8) !executor.RunResult {
            _ = timeout_ms;
            _ = cap;
            _ = sink;
            _ = sink_ctx;
            const stdout = try std.fmt.allocPrint(a, "exe={s} cwd={s} args={d}", .{ exe, cwd, args.len });
            return executor.RunResult{
                .exit_code = 0,
                .stdout = stdout,
                .stderr = try a.dupe(u8, ""),
            };
        }
    };

    // MCP solo auto-ejecuta consultas acotadas: `zig version` lo es, `zig --version` no.
    const cmd = "{\"exe\":\"zig\",\"args\":[\"version\"],\"cwd\":\"devagents-workspace\",\"timeout_ms\":5000}";
    const res = try shellRunJson(std.testing.allocator, cmd, Mock.spawn, null);
    defer res.deinit(std.testing.allocator);

    try std.testing.expect(!res.blocked);
    try std.testing.expectEqual(@as(i32, 0), res.exit_code);
    try std.testing.expect(std.mem.indexOf(u8, res.stdout, "exe=zig") != null);
    try std.testing.expect(std.mem.indexOf(u8, res.stdout, "args=1") != null);
}

test "QA-A H2: shell_run en un proyecto nuevo crea devagents-workspace, ejecuta y explica cwd fuera o inexistente" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const project = try tmp.dir.realPathFileAlloc(std.testing.io, ".", a);
    defer a.free(project);
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    defer workspace.setWorkspaceRoot(workspace.WORKSPACE_ROOT);
    try workspace.setWorkspaceRootChecked(project);
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    const ws = try std.fmt.allocPrint(a, "{s}" ++ std.fs.path.sep_str ++ "devagents-workspace", .{project});
    defer a.free(ws);
    // Proyecto recién elegido: la carpeta S2 todavía no existe.
    try std.testing.expect(!pathIsDirectory(a, ws));

    // (1) Antes: «politica: SpawnFailed». Ahora se crea la carpeta y corre.
    {
        const res = try shellRunJson(aa, "{\"exe\":\"git\",\"args\":[\"--version\"]}", null, st);
        defer res.deinit(aa);
        if (res.blocked and std.mem.indexOf(u8, res.block_reason, "ExeNotResolved") != null) {
            std.debug.print("OMITIDA: git no está en el PATH ({s})\n", .{res.block_reason});
            return error.SkipZigTest;
        }
        if (res.blocked) {
            std.debug.print("FALLO: shell_run bloqueado en un proyecto nuevo: {s}\n", .{res.block_reason});
            return error.TestUnexpectedResult;
        }
        try std.testing.expectEqual(@as(i32, 0), res.exit_code);
        try std.testing.expect(std.mem.indexOf(u8, res.stdout, "git version") != null);
        try std.testing.expect(pathIsDirectory(a, ws));
    }
    // (2) Un cwd fuera de la raíz dice cuál es la raíz permitida.
    {
        const cmd = try std.json.Stringify.valueAlloc(a, .{ .exe = "git", .args = &[_][]const u8{"--version"}, .cwd = project }, .{});
        defer a.free(cmd);
        const res = try shellRunJson(aa, cmd, null, st);
        defer res.deinit(aa);
        try std.testing.expect(res.blocked);
        try std.testing.expect(std.mem.indexOf(u8, res.block_reason, "PathOutsideSandbox") != null);
        try std.testing.expect(std.mem.indexOf(u8, res.block_reason, ws) != null);
    }
    // (3) Un cwd relativo que no existe lo dice así, no «SpawnFailed».
    {
        const res = try shellRunJson(aa, "{\"exe\":\"git\",\"args\":[\"--version\"],\"cwd\":\"no-existe\"}", null, st);
        defer res.deinit(aa);
        try std.testing.expect(res.blocked);
        try std.testing.expect(std.mem.indexOf(u8, res.block_reason, "la carpeta de trabajo no existe") != null);
        try std.testing.expect(std.mem.indexOf(u8, res.block_reason, "no-existe") != null);
    }
}

fn qaBScreenshotCount() !usize {
    var dir = std.Io.Dir.cwd().openDir(std.testing.io, ".screenshots", .{ .iterate = true }) catch |e| switch (e) {
        error.FileNotFound => return 0,
        else => return e,
    };
    defer dir.close(std.testing.io);
    var it = dir.iterate();
    var n: usize = 0;
    while (try it.next(std.testing.io)) |entry| {
        if (std.mem.endsWith(u8, entry.name, ".bmp")) n += 1;
    }
    return n;
}

test "QA-B 2a/H4: por MCP la captura y los comandos esperan al humano; approval_result da estado y salida" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.createDirPath(std.testing.io, "proyecto");
    const base = try tmp.dir.realPathFileAlloc(std.testing.io, ".", a);
    defer a.free(base);
    const project = try std.fmt.allocPrint(a, "{s}" ++ std.fs.path.sep_str ++ "proyecto", .{base});
    defer a.free(project);
    const db_path = try std.fmt.allocPrintSentinel(a, "{s}" ++ std.fs.path.sep_str ++ "runtime.db", .{base}, 0);
    defer a.free(db_path);
    defer workspace.setWorkspaceRoot(workspace.WORKSPACE_ROOT);
    try workspace.setWorkspaceRootChecked(project);

    // Núcleo del MCP (superficie MCP) y de la cabina, sobre la misma base.
    var mcp: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&mcp, db_path));
    defer _ = da_core_shutdown(mcp);
    try std.testing.expectEqual(@as(c_int, 0), da_set_mcp_surface(mcp));
    var cabin: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&cabin, db_path));
    defer _ = da_core_shutdown(cabin);

    // H4: pedir la captura por MCP no captura: deja una tarjeta pendiente.
    const shots_before = try qaBScreenshotCount();
    var shot: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_capture_screenshot(mcp, &shot));
    var shot_json = try std.json.parseFromSlice(std.json.Value, a, std.mem.span(shot), .{});
    da_string_free(shot);
    defer shot_json.deinit();
    try std.testing.expectEqualStrings("pending", shot_json.value.object.get("status").?.string);
    const shot_id = shot_json.value.object.get("approval_id").?.integer;
    try std.testing.expectEqual(shots_before, try qaBScreenshotCount());
    const shot_pending = try approvalResultJson(@ptrCast(@alignCast(mcp.?)), a, shot_id);
    defer a.free(shot_pending);
    try std.testing.expect(std.mem.indexOf(u8, shot_pending, "\"status\":\"pending\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, shot_pending, "\"kind\":\"screen_capture\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, shot_pending, "\"executed\":false") != null);
    // El MCP no puede aprobarla; la cabina la deniega y no se captura nada.
    try std.testing.expect(da_approval_resolve(mcp, shot_id, 1) != 0);
    try std.testing.expectEqual(@as(c_int, 0), da_approval_resolve(cabin, shot_id, 0));
    const shot_denied = try approvalResultJson(@ptrCast(@alignCast(mcp.?)), a, shot_id);
    defer a.free(shot_denied);
    try std.testing.expect(std.mem.indexOf(u8, shot_denied, "\"status\":\"denied\"") != null);
    try std.testing.expectEqual(shots_before, try qaBScreenshotCount());

    // 2a: un comando que pide aprobación devuelve approval_id; la cabina lo
    // aprueba y approval_result trae su salida acotada.
    const st_mcp: *CoreState = @ptrCast(@alignCast(mcp.?));
    const aa = st_mcp.arena.child_allocator;
    try tmp.dir.createDirPath(std.testing.io, "proyecto" ++ std.fs.path.sep_str ++ "devagents-workspace");
    // `git --version --build-options` no es la consulta exenta: pide humano.
    const res = try shellRunJson(aa, "{\"exe\":\"git\",\"args\":[\"--version\",\"--build-options\"]}", null, st_mcp);
    defer res.deinit(aa);
    if (res.blocked and std.mem.indexOf(u8, res.block_reason, "ExeNotResolved") != null) return error.SkipZigTest;
    try std.testing.expect(res.blocked);
    const cmd_id = res.approval_id.?;
    const cmd_pending = try approvalResultJson(st_mcp, a, cmd_id);
    defer a.free(cmd_pending);
    try std.testing.expect(std.mem.indexOf(u8, cmd_pending, "\"status\":\"pending\"") != null);
    try std.testing.expectEqual(@as(c_int, 0), da_approval_resolve(cabin, cmd_id, 1));
    const cmd_done = try approvalResultJson(st_mcp, a, cmd_id);
    defer a.free(cmd_done);
    std.debug.print("QA-B 2a approval_result tras aprobar: {s}\n", .{cmd_done[0..@min(cmd_done.len, 400)]});
    try std.testing.expect(std.mem.indexOf(u8, cmd_done, "\"status\":\"approved\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, cmd_done, "\"executed\":true") != null);
    try std.testing.expect(std.mem.indexOf(u8, cmd_done, "\"exit_code\":0") != null);
    try std.testing.expect(std.mem.indexOf(u8, cmd_done, "git version") != null);
    // Un id que no existe se dice así.
    const unknown = try approvalResultJson(st_mcp, a, 987654);
    defer a.free(unknown);
    try std.testing.expect(std.mem.indexOf(u8, unknown, "\"status\":\"unknown\"") != null);

    // 2a: la consulta git domesticada corre sin tarjeta y devuelve su salida.
    const domesticated = try std.json.Stringify.valueAlloc(a, .{ .exe = "git", .args = command_policy.GIT_SAFE_PREFIX ++ [_][]const u8{ "status", "--porcelain=v1", "--branch", "--untracked-files=normal" }, .cwd = project, .root = "project" }, .{});
    defer a.free(domesticated);
    const quick = try shellRunJson(aa, domesticated, null, st_mcp);
    defer quick.deinit(aa);
    try std.testing.expect(!quick.blocked);
    try std.testing.expect(quick.approval_id == null);
}

test "T12 L1: approval_result solo devuelve a cada sesión MCP las aprobaciones que pidió ella" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const base = try tmp.dir.realPathFileAlloc(std.testing.io, ".", a);
    defer a.free(base);
    const db_path = try std.fmt.allocPrintSentinel(a, "{s}" ++ std.fs.path.sep_str ++ "runtime.db", .{base}, 0);
    defer a.free(db_path);
    // Dos clientes MCP (dos procesos devagents-mcp) y la cabina, misma base.
    var mcp_a: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&mcp_a, db_path));
    defer _ = da_core_shutdown(mcp_a);
    try std.testing.expectEqual(@as(c_int, 0), da_set_mcp_surface(mcp_a));
    var mcp_b: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&mcp_b, db_path));
    defer _ = da_core_shutdown(mcp_b);
    try std.testing.expectEqual(@as(c_int, 0), da_set_mcp_surface(mcp_b));
    var cabin: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&cabin, db_path));
    defer _ = da_core_shutdown(cabin);

    // La sesión A pide una captura y un comando (ninguno se ejecuta).
    var shot: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_capture_screenshot(mcp_a, &shot));
    var shot_json = try std.json.parseFromSlice(std.json.Value, a, std.mem.span(shot), .{});
    da_string_free(shot);
    defer shot_json.deinit();
    const shot_id = shot_json.value.object.get("approval_id").?.integer;
    const st_a: *CoreState = @ptrCast(@alignCast(mcp_a.?));
    const res = try shellRunJson(st_a.arena.child_allocator, "{\"exe\":\"touch\",\"args\":[\"T12-L1-never-created\"]}", null, st_a);
    defer res.deinit(st_a.arena.child_allocator);
    const cmd_id = res.approval_id.?;

    for ([_]i64{ shot_id, cmd_id }) |id| {
        // A ve lo suyo.
        var own: [*:0]u8 = undefined;
        try std.testing.expectEqual(@as(c_int, 0), da_approval_result_json(mcp_a, id, &own));
        defer da_string_free(own);
        try std.testing.expect(std.mem.indexOf(u8, std.mem.span(own), "\"status\":\"pending\"") != null);
        // B, con su propio token, no: ni estado ni resultado.
        var other: [*:0]u8 = undefined;
        try std.testing.expect(da_approval_result_json(mcp_b, id, &other) != 0);
        var message: [*:0]u8 = undefined;
        try std.testing.expectEqual(@as(c_int, 0), da_last_error(&message));
        defer da_string_free(message);
        try std.testing.expect(std.mem.indexOf(u8, std.mem.span(message), "no la pidió esta sesión MCP") != null);
        // La cabina (sin superficie MCP) sí lo ve todo: es quien aprueba.
        var cab: [*:0]u8 = undefined;
        try std.testing.expectEqual(@as(c_int, 0), da_approval_result_json(cabin, id, &cab));
        da_string_free(cab);
    }
    // Ni siquiera tras aprobarse: B sigue sin ver el resultado de A.
    try std.testing.expectEqual(@as(c_int, 0), da_approval_resolve(cabin, shot_id, 0));
    var after: [*:0]u8 = undefined;
    try std.testing.expect(da_approval_result_json(mcp_b, shot_id, &after) != 0);
    // Un id que nadie de esta sesión pidió (aunque no exista) tampoco se sondea.
    try std.testing.expect(da_approval_result_json(mcp_b, 987654, &after) != 0);
}

test "T12B B-2: la propiedad de una tarjeta MCP sobrevive al reinicio y no se comparte" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const base = try tmp.dir.realPathFileAlloc(std.testing.io, ".", a);
    defer a.free(base);
    const db_path = try std.fmt.allocPrintSentinel(a, "{s}\\runtime.db", .{base}, 0);
    defer a.free(db_path);

    // La sesión 1 pide un comando que exige aprobación (no se ejecuta).
    var mcp_a: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&mcp_a, db_path));
    try std.testing.expectEqual(@as(c_int, 0), da_set_mcp_surface(mcp_a));
    try std.testing.expectEqual(@as(c_int, 0), da_set_mcp_session(mcp_a, "sess-1"));
    const st_a: *CoreState = @ptrCast(@alignCast(mcp_a.?));
    const dispatch_id = try insertApprovalToDbOrigin(st_a.db_conn, "t-dispatch", "paso del despacho MCP", 1, "plan_step", null, null, 0, st_a.mcp_origin);
    const capture_id = try requestScreenCaptureApproval(st_a, st_a.arena.child_allocator);
    const res = try shellRunJson(st_a.arena.child_allocator, "{\"exe\":\"touch\",\"args\":[\"T12B-B2-never-created\"]}", null, st_a);
    try std.testing.expect(res.blocked);
    const id = res.approval_id.?;
    res.deinit(st_a.arena.child_allocator);
    {
        const q = try st_a.db_conn.prepare("SELECT origin FROM approvals WHERE id = ?");
        defer st_a.db_conn.finalize(q);
        try db.bindInt(q, 1, id);
        try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(q));
        try std.testing.expectEqualStrings("sess-1", approvalColText(q, 0));
    }
    try std.testing.expectEqual(@as(c_int, 0), da_core_shutdown(mcp_a));

    // Reinicio: otro proceso con el mismo origen sigue siendo propietario de la suya.
    var mcp_a2: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&mcp_a2, db_path));
    defer _ = da_core_shutdown(mcp_a2);
    try std.testing.expectEqual(@as(c_int, 0), da_set_mcp_surface(mcp_a2));
    try std.testing.expectEqual(@as(c_int, 0), da_set_mcp_session(mcp_a2, "sess-1"));
    var own: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_approval_result_json(mcp_a2, id, &own));
    defer da_string_free(own);
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(own), "\"status\":\"pending\"") != null);
    var pending: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_approval_pending_json(mcp_a2, &pending));
    defer da_string_free(pending);
    const id_text = try std.fmt.allocPrint(a, "\"id\":{d}", .{id});
    defer a.free(id_text);
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(pending), id_text) != null);
    for ([_]i64{ dispatch_id, capture_id }) |persisted_id| {
        const needle = try std.fmt.allocPrint(a, "\"id\":{d}", .{persisted_id});
        defer a.free(needle);
        try std.testing.expect(std.mem.indexOf(u8, std.mem.span(pending), needle) != null);
        var result: [*:0]u8 = undefined;
        try std.testing.expectEqual(@as(c_int, 0), da_approval_result_json(mcp_a2, persisted_id, &result));
        da_string_free(result);
    }

    // Otra sesión (token distinto) no la ve ni la puede consultar.
    var mcp_b: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&mcp_b, db_path));
    defer _ = da_core_shutdown(mcp_b);
    try std.testing.expectEqual(@as(c_int, 0), da_set_mcp_surface(mcp_b));
    try std.testing.expectEqual(@as(c_int, 0), da_set_mcp_session(mcp_b, "sess-2"));
    var other: [*:0]u8 = undefined;
    try std.testing.expect(da_approval_result_json(mcp_b, id, &other) != 0);
    var message: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_last_error(&message));
    defer da_string_free(message);
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(message), "no la pidió esta sesión MCP") != null);
    var b_pending: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_approval_pending_json(mcp_b, &b_pending));
    defer da_string_free(b_pending);
    try std.testing.expectEqualStrings("[]", std.mem.span(b_pending));

    // Una tarjeta sin sesión (la inserta la cabina) no la ve ninguna sesión MCP.
    const st_a2: *CoreState = @ptrCast(@alignCast(mcp_a2.?));
    const cabin_id = try insertApprovalToDb(st_a2.db_conn, "t1", "tarjeta de la cabina", 1, command_approval.PREFIX, null, null, 0);
    var cabin_pending: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_approval_pending_json(mcp_a2, &cabin_pending));
    defer da_string_free(cabin_pending);
    const cabin_text = try std.fmt.allocPrint(a, "\"id\":{d}", .{cabin_id});
    defer a.free(cabin_text);
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(cabin_pending), cabin_text) == null);
    // ...pero la cabina (sin superficie MCP) sí ve todas.
    var cabin: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&cabin, db_path));
    defer _ = da_core_shutdown(cabin);
    var cab_all: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_approval_pending_json(cabin, &cab_all));
    defer da_string_free(cab_all);
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(cab_all), cabin_text) != null);
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(cab_all), id_text) != null);
}

test "T12 M5: la tarjeta de un comando pedido por MCP avisa de los archivos que un cliente MCP escribió hace poco" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const base = try tmp.dir.realPathFileAlloc(std.testing.io, ".", a);
    defer a.free(base);
    const db_path = try std.fmt.allocPrintSentinel(a, "{s}" ++ std.fs.path.sep_str ++ "runtime.db", .{base}, 0);
    defer a.free(db_path);
    var mcp: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&mcp, db_path));
    defer _ = da_core_shutdown(mcp);
    var cabin: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&cabin, db_path));
    defer _ = da_core_shutdown(cabin);
    // La cabina no anota escrituras MCP.
    try std.testing.expect(da_mcp_file_written(cabin, "package.json") != 0);
    try std.testing.expectEqual(@as(c_int, 0), da_set_mcp_surface(mcp));
    const st: *CoreState = @ptrCast(@alignCast(mcp.?));
    const aa = st.arena.child_allocator;

    // Sin escrituras: tarjeta sin aviso.
    const quiet = try shellRunJson(aa, "{\"exe\":\"touch\",\"args\":[\"T12-M5-a\"]}", null, st);
    defer quiet.deinit(aa);
    try std.testing.expect(std.mem.indexOf(u8, st.approvals.items[st.approvals.items.len - 1].description, "cliente MCP escribió") == null);

    // Escribe package.json (dos veces) y un script; el comando siguiente avisa.
    try std.testing.expectEqual(@as(c_int, 0), da_mcp_file_written(mcp, "package.json"));
    try std.testing.expectEqual(@as(c_int, 0), da_mcp_file_written(mcp, "scripts\\dev.cmd"));
    try std.testing.expectEqual(@as(c_int, 0), da_mcp_file_written(mcp, "package.json"));
    const noted = try shellRunJson(aa, "{\"exe\":\"touch\",\"args\":[\"T12-M5-b\"]}", null, st);
    defer noted.deinit(aa);
    const card = st.approvals.items[st.approvals.items.len - 1].description;
    try std.testing.expect(std.mem.indexOf(u8, card, "un cliente MCP escribió 2 archivo(s) del proyecto en los últimos 10 min") != null);
    try std.testing.expect(std.mem.indexOf(u8, card, "package.json") != null);
    try std.testing.expect(std.mem.indexOf(u8, card, "scripts\\dev.cmd") != null);
    // La cabina ve el mismo texto en su bandeja (la tarjeta sale de la base).
    var pending: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_approval_pending_json(cabin, &pending));
    defer da_string_free(pending);
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(pending), "cliente MCP escribi") != null);

    // Pasada la ventana, ya no se avisa.
    const old = try st.db_conn.prepare("UPDATE events SET ts = ts - ? WHERE kind = 'mcp_file_written_v1'");
    defer st.db_conn.finalize(old);
    try db.bindInt(old, 1, MCP_WRITES_NOTE_WINDOW_MS + 1000);
    try std.testing.expectEqual(db.c.SQLITE_DONE, db.c.sqlite3_step(old));
    const later = try shellRunJson(aa, "{\"exe\":\"touch\",\"args\":[\"T12-M5-c\"]}", null, st);
    defer later.deinit(aa);
    try std.testing.expect(std.mem.indexOf(u8, st.approvals.items[st.approvals.items.len - 1].description, "cliente MCP escribió") == null);
}

