    const base = try tmp.dir.realPathFileAlloc(std.testing.io, ".", a);
    defer a.free(base);
    const db_path = try std.fmt.allocPrintSentinel(a, "{s}" ++ std.fs.path.sep_str ++ "runtime.db", .{base}, 0);
    defer a.free(db_path);
