    try std.testing.expectEqual(@as(c_int, 0), da_mcp_file_written(mcp, "scripts\\build.ps1"));
    const st: *CoreState = @ptrCast(@alignCast(mcp.?));
    // El agente pide un comando y la orden se cancela enseguida: la tarjeta
    // queda escrita (caducada) y se lee su texto.
