    try std.testing.expect(std.mem.indexOf(u8, text, "Aprobar este comando exacto") != null);
    try std.testing.expect(std.mem.indexOf(u8, text, "un cliente MCP escribió 1 archivo(s) del proyecto") != null);
    try std.testing.expect(std.mem.indexOf(u8, text, "scripts\\build.ps1") != null);
}

