test "SEC2 worker inline approval is visible and resolved only once by UI" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const Ui = struct {
        handle: ?*anyopaque,
        count: usize = 0,
        failed: bool = false,
        fn resolve(raw: ?*anyopaque) bool {
            const self: *@This() = @ptrCast(@alignCast(raw.?));
            var json: [*:0]u8 = undefined;
            if (da_approval_pending_json(self.handle, &json) != 0) {
                self.failed = true;
                return true;
            }
            defer da_string_free(json);
            if (std.mem.eql(u8, std.mem.span(json), "[]")) return false;
            self.count += 1;
            if (std.mem.indexOf(u8, std.mem.span(json), command_approval.PREFIX) == null) self.failed = true;
            const state: *CoreState = @ptrCast(@alignCast(self.handle.?));
            var parsed = std.json.parseFromSlice(std.json.Value, state.arena.child_allocator, std.mem.span(json), .{}) catch {
                self.failed = true;
                return true;
            };
            defer parsed.deinit();
            const id = parsed.value.array.items[0].object.get("id").?.integer;
            if (da_approval_resolve_scoped(self.handle, id, 1, 1) == 0) self.failed = true;
            if (da_approval_resolve_scoped(self.handle, id, 1, 0) != 0) self.failed = true;
            return self.failed;
        }
    };
    var ui = Ui{ .handle = handle };
    for (0..2) |_| {
        try std.testing.expect(try command_approval.waitForHuman(st.arena.child_allocator, st.db_conn, 0, "worker", "python", &.{ "-c", "print(1)" }, ".", ".", Ui.resolve, &ui));
    }
    try std.testing.expect(!ui.failed);
    try std.testing.expectEqual(@as(usize, 2), ui.count);
    const query = try st.db_conn.prepare("SELECT COUNT(*) FROM events WHERE kind='approval_needed'");
    defer st.db_conn.finalize(query);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(query));
    try std.testing.expectEqual(@as(c_int, 2), db.c.sqlite3_column_int(query, 0));
}

