    defer _ = da_core_shutdown(ui_handle);
    var response: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_shell_run(mcp_handle, "{\"exe\":\"powershell\",\"args\":[\"-NoProfile\",\"-NonInteractive\",\"-Command\",\"[System.IO.File]::AppendAllText('approved-once.txt','x')\"]}", &response));
    defer da_string_free(response);
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(response), "PermissionRequired") != null);
    try std.testing.expectError(error.FileNotFound, tmp.dir.statFile(io, "approved-once.txt", .{}));
    var pending: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_approval_pending_json(ui_handle, &pending));
    defer da_string_free(pending);
    var parsed = try std.json.parseFromSlice(std.json.Value, allocator, std.mem.span(pending), .{});
    defer parsed.deinit();
    try std.testing.expectEqual(@as(usize, 1), parsed.value.array.items.len);
    const app = parsed.value.array.items[0].object;
    try std.testing.expectEqualStrings("powershell", app.get("exe").?.string);
    try std.testing.expect(std.mem.indexOf(u8, app.get("description").?.string, "AppendAllText") != null);
    const id = app.get("id").?.integer;
    try std.testing.expectEqual(@as(c_int, 0), da_approval_resolve_scoped(ui_handle, id, 1, 0));
    try std.testing.expect(da_approval_resolve(ui_handle, id, 1) != 0);
    try std.testing.expect(da_approval_resolve(mcp_handle, id, 1) != 0);
    const content = try tmp.dir.readFileAlloc(io, "approved-once.txt", allocator, .limited(32));
    defer allocator.free(content);
    try std.testing.expectEqualStrings("x", content);
    var after: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_approval_pending_json(mcp_handle, &after));
    defer da_string_free(after);
    try std.testing.expectEqualStrings("[]", std.mem.span(after));
}

var approval_resume_spawn_count: usize = 0;
var approval_resume_argv_complete: bool = false;

fn approvalResumeMock(_: std.mem.Allocator, exe: []const u8, args: []const []const u8, _: []const u8, _: u32, _: usize, _: ?executor.StreamSink, _: ?*anyopaque, _: []const u8) executor.ExecutorError!executor.RunResult {
    approval_resume_spawn_count += 1;
    approval_resume_argv_complete = std.mem.eql(u8, exe, "python") and args.len == 3 and
        std.mem.eql(u8, args[0], "-c") and std.mem.eql(u8, args[1], "print('SEC2')") and std.mem.eql(u8, args[2], "final");
    return .{ .exit_code = 0, .stdout = &.{}, .stderr = &.{} };
}

test "SEC2 approval resume OOM never launches a partial argv" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const aa = st.arena.child_allocator;
    const res = try shellRunJson(aa, "{\"exe\":\"python\",\"args\":[\"-c\",\"print('SEC2')\",\"final\"]}", null, st);
    defer res.deinit(aa);
    var failures_before_spawn: usize = 0;
    var reached_spawn = false;
    for (0..64) |index| {
        approval_resume_spawn_count = 0;
        approval_resume_argv_complete = false;
        var failing = std.testing.FailingAllocator.init(aa, .{ .fail_index = index });
        const result = resumeExecutionApproval(st, failing.allocator(), res.approval_id.?, approvalResumeMock);
        if (approval_resume_spawn_count != 0) {
            // El primer spawn posible debe recibir TODOS los argumentos.
            try std.testing.expect(approval_resume_argv_complete);
            try std.testing.expectEqual(@as(usize, 1), approval_resume_spawn_count);
            try result;
            reached_spawn = true;
            break;
        }
        // Writer.Allocating convierte OOM en WriteFailed al renderizar el
        // comando; ambas rutas deben abortar antes de entregar argv al spawn.
        if (index < 3) try std.testing.expectError(error.OutOfMemory, result) else result catch |e| try std.testing.expect(e == error.OutOfMemory or e == error.WriteFailed);
        try std.testing.expect(failing.has_induced_failure);
        try std.testing.expectEqual(failing.allocated_bytes, failing.freed_bytes);
        failures_before_spawn += 1;
    }
    try std.testing.expect(reached_spawn);
    try std.testing.expect(failures_before_spawn >= 6);
}

