var shell_run_seen_cwd: ?[]u8 = null;

fn shellRunSeenCwdSpawn(
    a: std.mem.Allocator,
    exe: []const u8,
    args: []const []const u8,
    cwd: []const u8,
    timeout_ms: u32,
    cap: usize,
    sink: ?executor.StreamSink,
    sink_ctx: ?*anyopaque,
    _: []const u8,
) executor.ExecutorError!executor.RunResult {
    _ = exe;
    _ = args;
    _ = timeout_ms;
    _ = cap;
    _ = sink;
    _ = sink_ctx;
    shell_run_seen_cwd = a.dupe(u8, cwd) catch null;
    return .{
        .exit_code = 0,
        .stdout = try a.dupe(u8, ""),
        .stderr = try a.dupe(u8, ""),
    };
}

test "c_api: shell run anchors relative cwd to effective root, not process cwd" {
    // E3.34 (V8): antes el sandbox validaba "tools" como si colgara de
    // "devagents-workspace" pero el proceso lo resolvía contra su propio cwd —
    // el hijo aterrizaba fuera de todo devagents-workspace. Ahora el spawn debe
    // recibir la ruta absoluta bajo effectiveRoot.
    shell_run_seen_cwd = null;
    defer if (shell_run_seen_cwd) |c| std.testing.allocator.free(c);

    var er_buf: [4096]u8 = undefined;
    const root = workspace.effectiveRoot(&er_buf);
    const expected = try std.fmt.allocPrint(std.testing.allocator, "{s}" ++ std.fs.path.sep_str ++ "tools", .{root});
    defer std.testing.allocator.free(expected);

    const cmd = "{\"exe\":\"zig\",\"args\":[\"version\"],\"cwd\":\"tools\"}";
    const res = try shellRunJson(std.testing.allocator, cmd, shellRunSeenCwdSpawn, null);
    defer res.deinit(std.testing.allocator);

    try std.testing.expect(!res.blocked);
    try std.testing.expect(shell_run_seen_cwd != null);
    try std.testing.expectEqualStrings(expected, shell_run_seen_cwd.?);
}

test "c_api: shell run anchors dot cwd to effective root" {
    shell_run_seen_cwd = null;
    defer if (shell_run_seen_cwd) |c| std.testing.allocator.free(c);

    var er_buf: [4096]u8 = undefined;
    const root = workspace.effectiveRoot(&er_buf);

    const cmd = "{\"exe\":\"zig\",\"args\":[\"version\"],\"cwd\":\".\"}";
    const res = try shellRunJson(std.testing.allocator, cmd, shellRunSeenCwdSpawn, null);
    defer res.deinit(std.testing.allocator);

    try std.testing.expect(!res.blocked);
    try std.testing.expect(shell_run_seen_cwd != null);
    // "." se cuelga de la raíz: <effectiveRoot>\. — el OS lo resuelve al propio
    // effectiveRoot (nunca al cwd del proceso host).
    const expected = try std.fmt.allocPrint(std.testing.allocator, "{s}" ++ std.fs.path.sep_str ++ ".", .{root});
    defer std.testing.allocator.free(expected);
    try std.testing.expectEqualStrings(expected, shell_run_seen_cwd.?);
}

