test "c_api: da_order_events_json incremental polling with since_event_id" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);

    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "crea un modulo de logging en C", "test", null, &order));

    var json: [*:0]u8 = undefined;
    _ = da_plan_get_json(handle, order, &json);
    if (std.mem.indexOf(u8, std.mem.span(json), "needs_clarification\":true") != null) {
        _ = da_order_answer(handle, order, "[{\"question_id\":\"q1\",\"answer\":\"en C\"}]");
        da_string_free(json);
        _ = da_plan_get_json(handle, order, &json);
    }
    _ = da_order_confirm_json(handle, order, json);
    da_string_free(json);

    var first: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_order_events_json(handle, order, 0, &first));
    defer da_string_free(first);

    // La segunda consulta con since_event_id = max_id debe devolver [] (sin parpadeos ni recomputar).
    var max_id: i64 = 0;
    {
        const doc = std.json.parseFromSlice(std.json.Value, std.testing.allocator, std.mem.span(first), .{}) catch return;
        defer doc.deinit();
        if (doc.value == .array) {
            for (doc.value.array.items) |ev| {
                if (ev == .object) {
                    if (ev.object.get("id")) |idv| {
                        if (idv == .integer and idv.integer > max_id) max_id = @intCast(idv.integer);
                    }
                }
            }
        }
    }

    var second: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_order_events_json(handle, order, max_id, &second));
    defer da_string_free(second);
    try std.testing.expectEqualStrings("[]", std.mem.span(second));
}

