// — doble del proveedor para el sondeo automático. No hace red:
// devuelve el estado configurado y escribe la salud en la conexión recibida,
// igual que hace live_worker.probeModel con la conexión de runtime.
const CkPrv008Fake = struct {
    var calls: usize = 0;
    var ok_model: ?[]const u8 = null;
    var fail_status: health.Status = .timeout;

    fn reset(ok_model_arg: ?[]const u8, fail_status_arg: health.Status) void {
        calls = 0;
        ok_model = ok_model_arg;
        fail_status = fail_status_arg;
    }
};

fn ckPrv008Probe(
    allocator: std.mem.Allocator,
    catalog_path: []const u8,
    runtime: db.Connection,
    provider_name: []const u8,
    model_name: []const u8,
    prompt: []const u8,
) ?health.Status {
    _ = allocator;
    _ = catalog_path;
    _ = prompt;
    CkPrv008Fake.calls += 1;
    const status: health.Status = if (CkPrv008Fake.ok_model) |ok_name|
        (if (std.mem.eql(u8, ok_name, model_name)) .ok else CkPrv008Fake.fail_status)
    else
        CkPrv008Fake.fail_status;
    health.recordForKey(runtime, provider_name, model_name, "", status, 0) catch {};
    return status;
}

fn ckPrv008SeedFreeModel(st: *CoreState, model_name: []const u8) !void {
    const aa = st.arena.child_allocator;
    const sql = try std.fmt.allocPrint(
        aa,
        "INSERT INTO models(provider_id,model_name,is_free,available) SELECT id,'{s}',1,1 FROM providers WHERE name='OpenRouter'",
        .{model_name},
    );
    defer aa.free(sql);
    try st.catalog.db.exec(sql);
}

fn ckPrv008Scalar(conn: db.Connection, sql: []const u8) !i64 {
    const stmt = try conn.prepare(sql);
    defer conn.finalize(stmt);
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) return error.StepFailed;
    return db.c.sqlite3_column_int64(stmt, 0);
}

test "CK-PRV-008 a: auto probe is not repeated within the cooldown interval" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    try ckPrv008SeedFreeModel(st, "ck-prv-008-a");
    CkPrv008Fake.reset(null, .timeout);
    defer CkPrv008Fake.reset(null, .timeout);
    st.auto_verify_probe_fn = ckPrv008Probe;

    noteDispatchFailureAndMaybeAutoVerify(st, 123, st.db_conn);
    noteDispatchFailureAndMaybeAutoVerify(st, 123, st.db_conn);
    noteDispatchFailureAndMaybeAutoVerify(st, 123, st.db_conn);
    try std.testing.expectEqual(@as(usize, 1), CkPrv008Fake.calls);

    // Segunda racha inmediata: el enfriamiento impide otra ronda de sondeo.
    noteDispatchFailureAndMaybeAutoVerify(st, 123, st.db_conn);
    noteDispatchFailureAndMaybeAutoVerify(st, 123, st.db_conn);
    noteDispatchFailureAndMaybeAutoVerify(st, 123, st.db_conn);
    try std.testing.expectEqual(@as(usize, 1), CkPrv008Fake.calls);
    try std.testing.expectEqual(
        @as(i64, 1),
        try ckPrv008Scalar(st.db_conn, "SELECT COUNT(*) FROM events WHERE kind='auto_verify_cooled_down'"),
    );

    // Vencido el intervalo, una tercera racha sí vuelve a sondear.
    st.last_auto_verify_ms = health.nowMillis(st.db_conn) - AUTO_VERIFY_MIN_INTERVAL_MS - 1;
    noteDispatchFailureAndMaybeAutoVerify(st, 123, st.db_conn);
    noteDispatchFailureAndMaybeAutoVerify(st, 123, st.db_conn);
    noteDispatchFailureAndMaybeAutoVerify(st, 123, st.db_conn);
    try std.testing.expectEqual(@as(usize, 2), CkPrv008Fake.calls);
}

