test "CK-PRV-008 r3: a failed merge returns the concrete error to the caller, with partial result" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle.?));

    // El volcado falla SOLO para la fila "bad": la fusión de la otra sí ocurre.
    try st.db_conn.exec(
        \\CREATE TRIGGER ck_prv008_block_one BEFORE INSERT ON model_health
        \\WHEN NEW.model_id = 'OpenRouter/ck-prv-008-r3-bad'
        \\BEGIN SELECT RAISE(ABORT, 'ck-prv-008'); END
    );

    var bad_model = "OpenRouter/ck-prv-008-r3-bad".*;
    var good_model = "OpenRouter/ck-prv-008-r3-good".*;
    var empty_key = "".*;
    var rows = [_]health.StagedHealthRow{
        .{ .model_id = &bad_model, .key_label = &empty_key, .ok_count = 0, .err_count = 0, .timeout_count = 1, .last_ok_at = null, .last_err_at = null, .last_err_kind = null },
        .{ .model_id = &good_model, .key_label = &empty_key, .ok_count = 1, .err_count = 0, .timeout_count = 0, .last_ok_at = null, .last_err_at = null, .last_err_kind = null },
    };
    const summary = ProbeAllSummary{ .candidates = 2, .probed = 2, .ok = 1, .failed = 1 };

    const outcome = mergeStagedHealth(st, st.db_conn, &rows, summary, 128, 3);

    // El llamador recibe el resultado parcial y el error concreto (no solo un evento).
    try std.testing.expectEqual(@as(usize, 1), outcome.merged);
    try std.testing.expectEqual(@as(usize, 1), outcome.failed);
    try std.testing.expectEqual(@as(?db.DbError, error.StepFailed), outcome.first_error);

    // Solo se fusionó la fila que no falló: la ronda no es un éxito completo.
    try std.testing.expectEqual(@as(i64, 1), try ckPrv008Scalar(st.db_conn, "SELECT COUNT(*) FROM model_health"));
    try std.testing.expectEqual(@as(i64, 1), try ckPrv008Scalar(st.db_conn, "SELECT COUNT(*) FROM model_health WHERE model_id='OpenRouter/ck-prv-008-r3-good'"));

    // El evento lleva el error concreto (nombre) y la fila, no solo "merge_failed".
    try std.testing.expectEqual(@as(i64, 1), try ckPrv008Scalar(st.db_conn, "SELECT COUNT(*) FROM events WHERE kind='auto_verify_merge_failed' AND order_id=128 AND payload_json LIKE '%merge_failed%'"));
    try std.testing.expectEqual(@as(i64, 1), try ckPrv008Scalar(st.db_conn, "SELECT COUNT(*) FROM events WHERE kind='auto_verify_merge_failed' AND order_id=128 AND payload_json LIKE '%StepFailed%'"));
    try std.testing.expectEqual(@as(i64, 1), try ckPrv008Scalar(st.db_conn, "SELECT COUNT(*) FROM events WHERE kind='auto_verify_merge_failed' AND order_id=128 AND payload_json LIKE '%ck-prv-008-r3-bad%'"));
}

test "CK-PRV-008 r3: a partial merge is not reported as a successful round" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    try ckPrv008SeedFreeModel(st, "ck-prv-008-r3-int-bad");
    try ckPrv008SeedFreeModel(st, "ck-prv-008-r3-int-good");
    CkPrv008Fake.reset("ck-prv-008-r3-int-good", .timeout);
    defer CkPrv008Fake.reset(null, .timeout);
    st.auto_verify_probe_fn = ckPrv008Probe;

    try st.db_conn.exec(
        \\CREATE TRIGGER ck_prv008_block_int BEFORE INSERT ON model_health
        \\WHEN NEW.model_id = 'OpenRouter/ck-prv-008-r3-int-bad'
        \\BEGIN SELECT RAISE(ABORT, 'ck-prv-008'); END
    );

    noteDispatchFailureAndMaybeAutoVerify(st, 129, st.db_conn);
    noteDispatchFailureAndMaybeAutoVerify(st, 129, st.db_conn);
    noteDispatchFailureAndMaybeAutoVerify(st, 129, st.db_conn);

    // La fila que sí se pudo fusionar quedó escrita; la que falló, no.
    try std.testing.expectEqual(@as(i64, 1), try ckPrv008Scalar(st.db_conn, "SELECT COUNT(*) FROM model_health"));
    // La ronda no se presenta como éxito: merge_failed>0 en el evento de ronda
    // y el evento de fallo con el error concreto y la fila afectada.
    try std.testing.expectEqual(@as(i64, 1), try ckPrv008Scalar(st.db_conn, "SELECT COUNT(*) FROM events WHERE kind='auto_verify_triggered' AND order_id=129 AND payload_json LIKE '%\"merge_failed\":1%'"));
    try std.testing.expectEqual(@as(i64, 1), try ckPrv008Scalar(st.db_conn, "SELECT COUNT(*) FROM events WHERE kind='auto_verify_merge_failed' AND order_id=129 AND payload_json LIKE '%StepFailed%' AND payload_json LIKE '%ck-prv-008-r3-int-bad%'"));
}

test "CK-PRV-008 r4: every failed merge row is identified in the result and its own event" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle.?));

    // TRES filas: dos fallan (filas y etiquetas distintas) y una se fusiona.
    try st.db_conn.exec(
        \\CREATE TRIGGER ck_prv008_block_two BEFORE INSERT ON model_health
        \\WHEN NEW.model_id IN ('OpenRouter/ck-prv-008-r4-bad-a','OpenRouter/ck-prv-008-r4-bad-b')
        \\BEGIN SELECT RAISE(ABORT, 'ck-prv-008'); END
    );

    var bad_a = "OpenRouter/ck-prv-008-r4-bad-a".*;
    var bad_b = "OpenRouter/ck-prv-008-r4-bad-b".*;
    var good = "OpenRouter/ck-prv-008-r4-good".*;
    var key_a = "alpha".*;
    var key_b = "beta".*;
    var empty_key = "".*;
    var rows = [_]health.StagedHealthRow{
        .{ .model_id = &bad_a, .key_label = &key_a, .ok_count = 0, .err_count = 0, .timeout_count = 1, .last_ok_at = null, .last_err_at = null, .last_err_kind = null },
        .{ .model_id = &good, .key_label = &empty_key, .ok_count = 1, .err_count = 0, .timeout_count = 0, .last_ok_at = null, .last_err_at = null, .last_err_kind = null },
        .{ .model_id = &bad_b, .key_label = &key_b, .ok_count = 0, .err_count = 1, .timeout_count = 0, .last_ok_at = null, .last_err_at = null, .last_err_kind = null },
    };
    const summary = ProbeAllSummary{ .candidates = 3, .probed = 3, .ok = 1, .failed = 2 };

    const outcome = mergeStagedHealth(st, st.db_conn, &rows, summary, 130, 3);

    // El resultado cuenta la fusionada e identifica las DOS fallidas una a una.
    try std.testing.expectEqual(@as(usize, 1), outcome.merged);
    try std.testing.expectEqual(@as(usize, 2), outcome.failed);
    try std.testing.expectEqual(@as(?db.DbError, error.StepFailed), outcome.first_error);
    try std.testing.expectEqual(@as(usize, 2), outcome.failure_len);
    try std.testing.expectEqualStrings("OpenRouter/ck-prv-008-r4-bad-a", outcome.failures[0].model_id);
    try std.testing.expectEqualStrings("alpha", outcome.failures[0].key_label);
    try std.testing.expectEqual(error.StepFailed, outcome.failures[0].err);
    try std.testing.expectEqualStrings("OpenRouter/ck-prv-008-r4-bad-b", outcome.failures[1].model_id);
    try std.testing.expectEqualStrings("beta", outcome.failures[1].key_label);
    try std.testing.expectEqual(error.StepFailed, outcome.failures[1].err);

    // Solo la buena quedó en model_health.
    try std.testing.expectEqual(@as(i64, 1), try ckPrv008Scalar(st.db_conn, "SELECT COUNT(*) FROM model_health"));
    try std.testing.expectEqual(@as(i64, 1), try ckPrv008Scalar(st.db_conn, "SELECT COUNT(*) FROM model_health WHERE model_id='OpenRouter/ck-prv-008-r4-good'"));

    // Un evento POR FILA fallida, cada uno con su model_id, su key_label y el
    // nombre del error concreto; los conteos finales viajan en ambos.
    try std.testing.expectEqual(@as(i64, 2), try ckPrv008Scalar(st.db_conn, "SELECT COUNT(*) FROM events WHERE kind='auto_verify_merge_failed' AND order_id=130"));
    try std.testing.expectEqual(@as(i64, 1), try ckPrv008Scalar(st.db_conn, "SELECT COUNT(*) FROM events WHERE kind='auto_verify_merge_failed' AND order_id=130 AND payload_json LIKE '%ck-prv-008-r4-bad-a%' AND payload_json LIKE '%\"key_label\":\"alpha\"%' AND payload_json LIKE '%StepFailed%'"));
    try std.testing.expectEqual(@as(i64, 1), try ckPrv008Scalar(st.db_conn, "SELECT COUNT(*) FROM events WHERE kind='auto_verify_merge_failed' AND order_id=130 AND payload_json LIKE '%ck-prv-008-r4-bad-b%' AND payload_json LIKE '%\"key_label\":\"beta\"%' AND payload_json LIKE '%StepFailed%'"));
    try std.testing.expectEqual(@as(i64, 2), try ckPrv008Scalar(st.db_conn, "SELECT COUNT(*) FROM events WHERE kind='auto_verify_merge_failed' AND order_id=130 AND payload_json LIKE '%\"merge_ok\":1%' AND payload_json LIKE '%\"merge_failed\":2%'"));
    // La fila fusionada no aparece como fallida.
    try std.testing.expectEqual(@as(i64, 0), try ckPrv008Scalar(st.db_conn, "SELECT COUNT(*) FROM events WHERE kind='auto_verify_merge_failed' AND order_id=130 AND payload_json LIKE '%ck-prv-008-r4-good%'"));
}

