test "c_api: sessions persist and rehydrate after reinit (SESSIONS-PERSIST-06)" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try isolatedTestPath(&tmp, "runtime.db");
    defer std.testing.allocator.free(path);

    // Fase 1: primera vida — submit de 2 órdenes.
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, path));

    var order1: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "construye una calculadora CLI en C con tests", "proj-a", null, &order1));
    try std.testing.expect(order1 != null);

    var order2: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "revisa codigo en zig", "proj-b", null, &order2));
    try std.testing.expect(order2 != null);

    // Verificar mensajes de la primera orden.
    var msg_json: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_session_messages_json(handle, order1, &msg_json));
    const msg_str = std.mem.span(msg_json);
    try std.testing.expect(std.mem.indexOf(u8, msg_str, "user") != null);
    try std.testing.expect(std.mem.indexOf(u8, msg_str, "agent") != null);
    da_string_free(msg_json);

    _ = da_core_shutdown(handle);

    // Fase 2: rehidratar sobre el MISMO archivo.
    var handle2: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle2, path));

    // Verificar que las 2 sesiones están listadas.
    var sessions_json: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_sessions_json(handle2, &sessions_json));
    const sessions_str = std.mem.span(sessions_json);
    // Debe haber 2 órdenes.
    var count: usize = 0;
    for (sessions_str) |_| {
        if (std.mem.indexOf(u8, sessions_str[count..], "\"id\"") != null) count += 1;
    }
    // Conteo simple: verificamos que aparecen ambos IDs en el JSON.
    try std.testing.expect(std.mem.indexOf(u8, sessions_str, "\"id\"") != null);
    da_string_free(sessions_json);

    // Rehidratar mensajes de la primera orden (el handle es el ID real de BD).
    // Necesitamos encontrar el order handle correspondiente. En rehidratación,
    // id == db_id, así que orderHandleFromId del primer ID de BD recuperado.
    var msg_json2: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_session_messages_json(handle2, order1, &msg_json2));
    const msg_str2 = std.mem.span(msg_json2);
    try std.testing.expect(std.mem.indexOf(u8, msg_str2, "user") != null);
    try std.testing.expect(std.mem.indexOf(u8, msg_str2, "agent") != null);
    da_string_free(msg_json2);

    // Renombrar sesión.
    try std.testing.expectEqual(@as(c_int, 0), da_session_rename(handle2, order1, "Calc CLI Renombrada"));
    var sessions_json3: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_sessions_json(handle2, &sessions_json3));
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(sessions_json3), "Calc CLI Renombrada") != null);
    da_string_free(sessions_json3);

    _ = da_core_shutdown(handle2);
}

