}

test "REHYDRATE-P0: edited plan persists atomically and reopens exactly" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try isolatedTestPath(&tmp, "rehydrate_edited.db");
    defer std.testing.allocator.free(path);

    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, path));
    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "crea un modulo de logging en C", "rehydrate-edit", null, &order));
    const order_id = orderHandleToId(order).?;
    const before_state: *CoreState = @ptrCast(@alignCast(handle.?));
    const old_plan_id = findOrder(before_state, order_id).?.outcome.?.plan_id.?;
    const edited =
        \\{"understanding":"plan editado exacto","tasks":[{"id":"edit-a","task_type":"programar","department":"programacion","description":"Primera editada","depends_on":[],"contract_fields":[{"name":"archivo","type":"string","required":true,"value":"src/edit.c"}]},{"id":"edit-b","task_type":"testear","department":"testing","description":"Segunda editada","depends_on":["edit-a"],"contract_fields":[{"name":"resultado","type":"string","required":true,"value":"ok"}]}]}
    ;
    try std.testing.expectEqual(@as(c_int, 0), da_order_plan_set_json(handle, order, edited));
    _ = da_core_shutdown(handle);

    var restored_handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&restored_handle, path));
    defer _ = da_core_shutdown(restored_handle);
    const restored: *CoreState = @ptrCast(@alignCast(restored_handle.?));
    const rec = findOrder(restored, order_id).?;
    try std.testing.expect(rec.outcome.?.plan_id.? != old_plan_id);
    const plan = &rec.outcome.?.plan;
    try std.testing.expectEqualStrings("plan editado exacto", plan.understanding);
    try std.testing.expectEqual(@as(usize, 2), plan.tasks.len);
    try std.testing.expectEqualStrings("edit-a", plan.tasks[0].id);
    try std.testing.expectEqualStrings("Primera editada", plan.tasks[0].description);
    try std.testing.expectEqualStrings("src/edit.c", plan.tasks[0].contract_fields[0].value.?);
    try std.testing.expectEqualStrings("edit-b", plan.tasks[1].id);
    try std.testing.expectEqual(@as(usize, 1), plan.tasks[1].depends_on.len);
    try std.testing.expectEqualStrings("edit-a", plan.tasks[1].depends_on[0]);
    try std.testing.expectEqualStrings("ok", plan.tasks[1].contract_fields[0].value.?);
    const provenance = try restored.db_conn.prepare("SELECT payload_json FROM events WHERE order_id = ? AND kind = 'plan_edited'");
    defer restored.db_conn.finalize(provenance);
    try db.bindInt(provenance, 1, order_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(provenance));
    const edit_json = std.mem.span(db.c.sqlite3_column_text(provenance, 0).?);
    var edit_parsed = try std.json.parseFromSlice(std.json.Value, std.testing.allocator, edit_json, .{});
    defer edit_parsed.deinit();
    try std.testing.expectEqual(rec.outcome.?.plan_id.?, edit_parsed.value.object.get("plan_id").?.integer);
    try std.testing.expectEqual(old_plan_id, edit_parsed.value.object.get("previous_plan_id").?.integer);
    try std.testing.expectEqual(db.c.SQLITE_DONE, db.c.sqlite3_step(provenance));
    const versions = try restored.db_conn.prepare("SELECT COUNT(*) FROM plans WHERE order_id = ?");
    defer restored.db_conn.finalize(versions);
    try db.bindInt(versions, 1, order_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(versions));
    try std.testing.expectEqual(@as(i64, 2), db.c.sqlite3_column_int64(versions, 0));
    const old_tasks = try restored.db_conn.prepare("SELECT COUNT(*) FROM tasks WHERE plan_id = ?");
    defer restored.db_conn.finalize(old_tasks);
    try db.bindInt(old_tasks, 1, old_plan_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(old_tasks));
    try std.testing.expect(db.c.sqlite3_column_int64(old_tasks, 0) > 0);
}

test "REHYDRATE-P0: concurrent editors reject a stale plan revision without writes" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try isolatedTestPath(&tmp, "rehydrate_stale_edit.db");
    defer std.testing.allocator.free(path);

    var first_handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&first_handle, path));
    defer _ = da_core_shutdown(first_handle);
    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(first_handle, "crea un modulo de logging en C", "stale-edit", null, &order));
    const order_id = orderHandleToId(order).?;

    var second_handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&second_handle, path));
    defer _ = da_core_shutdown(second_handle);
    const first_edit =
        \\{"understanding":"primera revision","tasks":[{"id":"winner","task_type":"programar","department":"programacion","description":"ganadora","depends_on":[],"contract_fields":[{"name":"archivo","type":"string","required":true,"value":"winner.c"}]}]}
    ;
    const stale_edit =
        \\{"understanding":"revision obsoleta","tasks":[{"id":"stale","task_type":"programar","department":"programacion","description":"no persistir","depends_on":[],"contract_fields":[{"name":"archivo","type":"string","required":true,"value":"stale.c"}]}]}
    ;
    try std.testing.expectEqual(@as(c_int, 0), da_order_plan_set_json(first_handle, order, first_edit));
    try std.testing.expectEqual(
        @intFromEnum(DaResult.invalid_state),
        da_order_plan_set_json(second_handle, orderIdToHandle(order_id), stale_edit),
    );

    const first: *CoreState = @ptrCast(@alignCast(first_handle.?));
    const versions = try first.db_conn.prepare("SELECT COUNT(*), MAX(CASE WHEN understanding = 'revision obsoleta' THEN 1 ELSE 0 END) FROM plans WHERE order_id = ?");
    defer first.db_conn.finalize(versions);
    try db.bindInt(versions, 1, order_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(versions));
    try std.testing.expectEqual(@as(i64, 2), db.c.sqlite3_column_int64(versions, 0));
    try std.testing.expectEqual(@as(i64, 0), db.c.sqlite3_column_int64(versions, 1));
}

