test "c_api: ensureInventory scans active mounts and caches result" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle));

    // Sin mounts activos, ensureInventory crea un inventory vacío (no null).
    const disc = ensureInventory(st);
    _ = disc;
    try std.testing.expect(st.inventory != null);
    try std.testing.expectEqual(@as(usize, 0), st.inventory.?.resources.len);

    // Agregar un mount y verificar que el inventory ahora tiene recursos.
    try std.testing.expectEqual(@as(c_int, 0), da_mount_add(handle, "tests/fixtures/discovery"));
    // Reset inventory para forzar reescaneo con el nuevo mount.
    if (st.inventory) |*inv| inv.deinit(st.arena.child_allocator);
    st.inventory = null;
    const disc2 = ensureInventory(st);
    _ = disc2;
    try std.testing.expect(st.inventory != null);
    try std.testing.expect(st.inventory.?.resources.len > 0);
}

// Regresión ENGRAM-WIRE-07: da_order_submit session-summary fallback liberaba
// literal estático en rama OOM (allocPrint catch "orden completada" + defer free).
// std.testing.allocator detecta InvalidFree cuando se libera memoria que no posee.
//
// Estrategia: contar asignaciones del patrón exacto con FailingAllocator que nunca
// falla; segunda pasada falla EXACTAMENTE en la asignación de allocPrint. Con el
// código viejo (defer aa.free(summary) donde summary es literal estático) el test
// abortaría por InvalidFree. Con el fix no se libera nada y pasa limpio.
test "c_api: session summary allocPrint OOM does not invalid-free static literal" {
    const base = std.testing.allocator;

    // Pasada 1: contar asignaciones del patrón exacto.
    var counter = std.testing.FailingAllocator.init(base, .{});
    {
        const aa = counter.allocator();
        const summary_opt: ?[]u8 = std.fmt.allocPrint(aa, "Orden {d}: {d} completadas, {d} fallidas, {d} aprobadas pendientes", .{
            @as(u64, 1), @as(u64, 0), @as(u64, 0), @as(u64, 0),
        }) catch null;
        defer if (summary_opt) |s| aa.free(s);
    }

    // Pasada 2: fallar EXACTAMENTE en la asignación de allocPrint.
    var failing = std.testing.FailingAllocator.init(base, .{ .fail_index = counter.alloc_index - 1 });
    {
        const aa = failing.allocator();
        const summary_opt: ?[]u8 = std.fmt.allocPrint(aa, "Orden {d}: {d} completadas, {d} fallidas, {d} aprobadas pendientes", .{
            @as(u64, 1), @as(u64, 0), @as(u64, 0), @as(u64, 0),
        }) catch null;
        defer if (summary_opt) |s| aa.free(s);
        const summary = summary_opt orelse "orden completada";
        try std.testing.expectEqualStrings("orden completada", summary);
    }
    // Si hubiera invalid-free o fuga, std.testing.allocator (base) lo reportaría.
}

