test "c_api: A4 — dispatch_async + dispatch_poll roundtrip without deadlock" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    useTestDoneLlm(@ptrCast(@alignCast(handle.?))); // auditoría con veredicto real (P0.1)

    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "crea un modulo de logging en C", "test", null, &order));

    var json: [*:0]u8 = undefined;
    _ = da_plan_get_json(handle, order, &json);
    if (std.mem.indexOf(u8, std.mem.span(json), "needs_clarification\":true") != null) {
        _ = da_order_answer(handle, order, "[{\"question_id\":\"q1\",\"answer\":\"en C\"}]");
        da_string_free(json);
        _ = da_plan_get_json(handle, order, &json);
    }

    // Guardar el plan sin despachar (prepara la orden para dispatch_async).
    const rc_set = da_order_plan_set_json(handle, order, json);
    try std.testing.expectEqual(@as(c_int, 0), rc_set);
    da_string_free(json);

    // Lanzar despacho asíncrono.
    const rc_async = da_order_dispatch_async(handle, order);
    try std.testing.expectEqual(@as(c_int, 0), rc_async);

    // Poll hasta que termine (con timeout de seguridad). El techo existe para
    // cazar deadlocks —un despacho colgado no termina NUNCA—, no para medir
    // latencia: bajo `zig build` con caché fría el despacho puede pasar de 1 s
    // en una máquina cargada sin que nada esté roto (medido 2026-09-16).
    var done: c_int = 0;
    var ok_flag: c_int = 0;
    var attempts: u32 = 0;
    while (done == 0 and attempts < 600) : (attempts += 1) {
        Sleep(10); // 10ms
        _ = da_order_dispatch_poll(handle, order, &done, &ok_flag);
    }
    try std.testing.expect(done == 1);

    // Verificar que el status final es done.
    var status: c_int = -1;
    _ = da_order_status(handle, order, &status);
    try std.testing.expectEqual(@as(c_int, @intFromEnum(DaOrderStatus.done)), status);

    // Verificar que los eventos de lifecycle están presentes.
    var events: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_order_events_json(handle, order, 0, &events));
    defer da_string_free(events);
    const s = std.mem.span(events);
    try std.testing.expect(std.mem.indexOf(u8, s, "\"kind\":\"order_done\"") != null);

    // Worker output polling no debe deadlockear tras el despacho.
    var output: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_worker_output_poll(handle, 0, &output));
    da_string_free(output);
}

test "c_api: A5 — dispatch_async sets running early and always reaches done=1" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    useTestDoneLlm(@ptrCast(@alignCast(handle.?))); // auditoría con veredicto real (P0.1)

    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "crea un modulo de logging en C", "test", null, &order));

    var json: [*:0]u8 = undefined;
    _ = da_plan_get_json(handle, order, &json);
    if (std.mem.indexOf(u8, std.mem.span(json), "needs_clarification\":true") != null) {
        _ = da_order_answer(handle, order, "[{\"question_id\":\"q1\",\"answer\":\"en C\"}]");
        da_string_free(json);
        _ = da_plan_get_json(handle, order, &json);
    }

    const rc_set = da_order_plan_set_json(handle, order, json);
    try std.testing.expectEqual(@as(c_int, 0), rc_set);
    da_string_free(json);

    // Lanzar despacho asíncrono.
    const rc_async = da_order_dispatch_async(handle, order);
    try std.testing.expectEqual(@as(c_int, 0), rc_async);

    // Verificar que el status sale de planned. El chequeo es transitorio:
    // bajo la carga de la suite completa el hilo de dispatch puede tardar
    // >5 ms en arrancar (/E3-33) — lo que se verifica es que NO queda
    // planned para siempre, no la latencia de arranque. Techo 2 s.
    var status_mid: c_int = -1;
    var mid_attempts: u32 = 0;
    while (mid_attempts < 200) : (mid_attempts += 1) {
        _ = da_order_status(handle, order, &status_mid);
        if (status_mid != @intFromEnum(DaOrderStatus.planned)) break;
        Sleep(10);
    }
    // Debe ser running (4) o ya done/failed (5/6), pero NUNCA planned (2).
    try std.testing.expect(status_mid != @intFromEnum(DaOrderStatus.planned));

    // Poll hasta que termine. Presupuesto 6 s — el mismo que A4/A7: el techo
    // existe para cazar deadlocks, no para medir latencia (/E3-33: el
    // flake era la ventana de 2 s, no la aserción).
    var done: c_int = 0;
    var ok_flag: c_int = 0;
    var attempts: u32 = 0;
    while (done == 0 and attempts < 600) : (attempts += 1) {
        Sleep(10);
        _ = da_order_dispatch_poll(handle, order, &done, &ok_flag);
    }
    // FIX-DISPATCH-P0: dispatch_poll SIEMPRE debe llegar a done=1.
    try std.testing.expect(done == 1);

    // El status final debe ser done o failed, nunca planned.
    var status: c_int = -1;
    _ = da_order_status(handle, order, &status);
    try std.testing.expect(status != @intFromEnum(DaOrderStatus.planned));
    try std.testing.expect(status == @intFromEnum(DaOrderStatus.done) or
        status == @intFromEnum(DaOrderStatus.failed) or
        status == @intFromEnum(DaOrderStatus.awaiting_approval));
}

