test "AUDIT-UNAVAILABLE-P0 c_api: resume_async acepta audit_unavailable y ship la rechaza" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);

    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "crea un modulo de logging en C", "audit-unavailable-api", null, &order));
    const order_id = orderHandleToId(order).?;

    // Simular el cierre audit_unavailable: status en DB + copia en memoria
    // (lo mismo que deja commitTerminal + syncRecStatusFromDb tras el despacho).
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    {
        const stmt = try st.db_conn.prepare("UPDATE orders SET status = 'audit_unavailable' WHERE id = ?");
        defer st.db_conn.finalize(stmt);
        try db.bindInt(stmt, 1, order_id);
        _ = db.c.sqlite3_step(stmt);
    }
    const rec = findOrder(st, order_id).?;
    rec.status = .audit_unavailable;
    // Post-reinicio la orden NO tiene outcome en memoria (loadOrdersFromDb solo
    // rehidrata las .planned) — la forma real en que llega un audit_unavailable
    // a resume después de cerrar y abrir la aplicación.
    rec.outcome = null;

    // Ship bloqueado: solo 'done' entrega. Un audit_unavailable no es
    // un terminado — el PR no se abre aunque el usuario lo intente.
    var out_json: [*:0]u8 = undefined;
    const rc_ship = da_order_ship_json(handle, order, &out_json);
    try std.testing.expect(rc_ship != 0);
    const ship_err = std.mem.sliceTo(&last_error_buf, 0);
    try std.testing.expect(std.mem.indexOf(u8, ship_err, "done") != null);

    // Resume acepta el estado: pasa la guarda de status y llega hasta la
    // comprobación de plan persistido — el error ya no es el de estado
    // inválido sino el de plan no rehidratable (esta orden de test nunca tuvo
    // un plan persistido con approved=1).
    const rc_resume = da_order_resume_async(handle, order);
    try std.testing.expect(rc_resume != 0);
    const resume_err = std.mem.sliceTo(&last_error_buf, 0);
    try std.testing.expect(std.mem.indexOf(u8, resume_err, "no resumable persisted plan") != null);
}

test "CHECKPOINT-T2 c_api: resume_async reanuda una orden interrumpida desde el checkpoint por tarea" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try isolatedTestPath(&tmp, "resume_e2e.db");
    defer std.testing.allocator.free(path);

    // Fase 1: orden despachada a término; luego simular la muerte a medias —
    // todas las tareas completadas salvo una que quedó 'running', y la orden
    // marcada 'interrupted' (lo que escribe la reconciliación de arranque
    // cuando el hilo muere con el proceso).
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, path));
    useTestDoneLlm(@ptrCast(@alignCast(handle.?))); // auditoría con veredicto real (P0.1)
    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "crea un modulo de logging en C", "resume-e2e", null, &order));
    const order_id = orderHandleToId(order).?;

    var json: [*:0]u8 = undefined;
    _ = da_plan_get_json(handle, order, &json);
    if (std.mem.indexOf(u8, std.mem.span(json), "needs_clarification\":true") != null) {
        _ = da_order_answer(handle, order, "[{\"question_id\":\"q1\",\"answer\":\"en C\"}]");
        da_string_free(json);
        _ = da_plan_get_json(handle, order, &json);
    }
    try std.testing.expectEqual(@as(c_int, 0), da_order_plan_set_json(handle, order, json));
    da_string_free(json);
    try std.testing.expectEqual(@as(c_int, 0), da_order_dispatch_async(handle, order));
    var done: c_int = 0;
    var ok_flag: c_int = 0;
    var attempts: u32 = 0;
    while (done == 0 and attempts < 600) : (attempts += 1) {
        Sleep(10);
        _ = da_order_dispatch_poll(handle, order, &done, &ok_flag);
    }
    try std.testing.expect(done == 1);

    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    {
        // La última tarea del plan quedó 'running': a medias, sin continuidad
        // interna — la reanudación debe re-ejecutarla ENTERA.
        const tstmt = try st.db_conn.prepare("UPDATE tasks SET status = 'running' WHERE id = (SELECT id FROM tasks WHERE plan_id = (SELECT MAX(id) FROM plans WHERE order_id = ?) ORDER BY id DESC LIMIT 1)");
        defer st.db_conn.finalize(tstmt);
        try db.bindInt(tstmt, 1, order_id);
        _ = db.c.sqlite3_step(tstmt);
        const ostmt = try st.db_conn.prepare("UPDATE orders SET status = 'interrupted' WHERE id = ?");
        defer st.db_conn.finalize(ostmt);
        try db.bindInt(ostmt, 1, order_id);
        _ = db.c.sqlite3_step(ostmt);
        // La muerte simulada ocurre ANTES del commit terminal: una orden
        // interrumpida real nunca tiene order_done/order_failed (el índice
        // único idx_events_terminal_order garantiza un solo terminal). Sin
        // este DELETE la fase 2 chocaría con un evento imposible.
        const estmt = try st.db_conn.prepare("DELETE FROM events WHERE order_id = ? AND kind IN ('order_done','order_failed','order_cancelled')");
        defer st.db_conn.finalize(estmt);
        try db.bindInt(estmt, 1, order_id);
        _ = db.c.sqlite3_step(estmt);
    }
    _ = da_core_shutdown(handle);

    // Fase 2: arranque — la orden vuelve 'interrupted' y SIN outcome en
    // memoria (solo las .planned se rehidratan); resume debe reconstruir el
    // plan aprobado y re-ejecutar solo lo incompleto.
    var handle2: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle2, path));
    defer _ = da_core_shutdown(handle2);
    useTestDoneLlm(@ptrCast(@alignCast(handle2.?))); // idem tras el reinicio simulado
    const st2: *CoreState = @ptrCast(@alignCast(handle2.?));
    const rec2 = findOrder(st2, order_id).?;
    try std.testing.expectEqual(superagent.OrderStatus.interrupted, rec2.status);
    try std.testing.expect(rec2.outcome == null);

    try std.testing.expectEqual(@as(c_int, 0), da_order_resume_async(handle2, order));
    done = 0;
    ok_flag = 0;
    attempts = 0;
    while (done == 0 and attempts < 600) : (attempts += 1) {
        Sleep(10);
        _ = da_order_dispatch_poll(handle2, order, &done, &ok_flag);
    }
    try std.testing.expect(done == 1);

    var status: c_int = -1;
    _ = da_order_status(handle2, order, &status);
    if (status != @intFromEnum(DaOrderStatus.done)) {
        std.debug.print("status={d} ok_flag={d}\n", .{ status, ok_flag });
        const dstmt = st2.db_conn.prepare("SELECT kind, payload_json FROM events WHERE order_id = ?") catch null;
        if (dstmt) |d| {
            defer st2.db_conn.finalize(d);
            _ = db.c.sqlite3_bind_int64(d, 1, order_id);
            while (db.c.sqlite3_step(d) == db.c.SQLITE_ROW) {
                const kp = db.c.sqlite3_column_text(d, 0);
                const kl = db.c.sqlite3_column_bytes(d, 0);
                const pp = db.c.sqlite3_column_text(d, 1);
                const pl = db.c.sqlite3_column_bytes(d, 1);
                std.debug.print("ev {s} :: {s}\n", .{ kp[0..@intCast(kl)], pp[0..@intCast(@min(pl, 400))] });
            }
        }
        const tstmt = st2.db_conn.prepare("SELECT c.name, t.status FROM tasks t JOIN contracts c ON c.id = t.contract_id WHERE t.plan_id = (SELECT MAX(id) FROM plans WHERE order_id = ?)") catch null;
        if (tstmt) |d| {
            defer st2.db_conn.finalize(d);
            _ = db.c.sqlite3_bind_int64(d, 1, order_id);
            while (db.c.sqlite3_step(d) == db.c.SQLITE_ROW) {
                const np = db.c.sqlite3_column_text(d, 0);
                const nl = db.c.sqlite3_column_bytes(d, 0);
                const sp = db.c.sqlite3_column_text(d, 1);
                const sl = db.c.sqlite3_column_bytes(d, 1);
                std.debug.print("task {s} :: {s}\n", .{ np[0..@intCast(nl)], sp[0..@intCast(sl)] });
            }
        }
    }
    try std.testing.expectEqual(@as(c_int, @intFromEnum(DaOrderStatus.done)), status);

    // La traza declara la reanudación: tareas restauradas y la que quedó a
    // medias reportada como interrumpida (re-ejecutada entera).
    var events: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_order_events_json(handle2, order, 0, &events));
    defer da_string_free(events);
    const s = std.mem.span(events);
    try std.testing.expect(std.mem.indexOf(u8, s, "\"kind\":\"order_resumed\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, s, "interrupted_tasks") != null);
    try std.testing.expect(std.mem.indexOf(u8, s, "\"kind\":\"order_done\"") != null);
}

