test "CK-VER1-002: pedir cambios crea revision sin worker ni archivo y aprobar ejecuta" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var threaded = std.Io.Threaded.init(a, .{});
    defer threaded.deinit();
    const root = try tmp.dir.realPathFileAlloc(threaded.io(), ".", a);
    defer a.free(root);
    workspace.setOrderRootOverride(root);
    defer workspace.setOrderRootOverride(null);
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    const Worker = struct {
        calls: usize = 0,
        fn call(ctx: *anyopaque, _: []const u8, _: []const u8) []const u8 {
            const self: *@This() = @ptrCast(@alignCast(ctx));
            self.calls += 1;
            return "[{\"field\":\"filename\",\"content\":\"estilos.css\"},{\"field\":\"source\",\"content\":\"body { color: blue; margin: 12px; }\"},{\"field\":\"exit_code\",\"content\":\"0\"},{\"field\":\"tests_passed\",\"content\":\"1\"},{\"field\":\"verdict\",\"content\":\"PASS\"}]";
        }
    };
    var worker = Worker{};
    st.test_llm_fn = Worker.call;
    st.test_llm_ctx = &worker;
    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit_options_async(handle, "crea el archivo estilos.css en C", "plan-test", null, null, "{\"wait_for_plan_approval\":true}", &order));
    try waitForPlanTest(handle);
    try settleClarification(handle, order);
    const rec = findOrder(st, orderHandleToId(order).?).?;
    const first_plan = rec.outcome.?.plan_id.?;
    const order_dir = try std.fmt.allocPrint(a, "{s}" ++ std.fs.path.sep_str ++ "orden-{d}", .{ root, rec.id });
    defer a.free(order_dir);
    const files_before = try workspace.listOrderFilesIn(a, order_dir);
    defer {
        for (files_before) |file| file.deinit(a);
        a.free(files_before);
    }
    try std.testing.expectEqual(@as(usize, 0), files_before.len);
    try std.testing.expectEqual(@as(usize, 0), worker.calls);
    try std.testing.expectEqual(@as(c_int, 0), da_order_replan_async(handle, order, "Conserva estilos.css y usa azul; implementa en C"));
    try waitForPlanTest(handle);
    try settleClarification(handle, order);
    try std.testing.expectEqual(superagent.OrderStatus.planned, rec.status);
    try std.testing.expect(rec.outcome.?.plan_id.? > first_plan);
    try std.testing.expectEqual(@as(usize, 0), worker.calls);
    const files_replanned = try workspace.listOrderFilesIn(a, order_dir);
    defer {
        for (files_replanned) |file| file.deinit(a);
        a.free(files_replanned);
    }
    try std.testing.expectEqual(@as(usize, 0), files_replanned.len);
    try std.testing.expectEqual(@as(c_int, 0), da_order_approve(handle, order));
    try std.testing.expect(worker.calls > 0);
    const files_after = try workspace.listOrderFilesIn(a, order_dir);
    defer {
        for (files_after) |file| file.deinit(a);
        a.free(files_after);
    }
    if (files_after.len == 0) {
        var diagnostic: [*:0]u8 = undefined;
        if (da_order_events_json(handle, order, 0, &diagnostic) == 0) {
            defer da_string_free(diagnostic);
            std.debug.print("PLAN TEST: root={s} status={s} events={s}\n", .{ root, rec.status.toText(), std.mem.span(diagnostic) });
        }
    }
    try std.testing.expect(files_after.len > 0);
    var wrote_styles = false;
    for (files_after) |file| {
        if (std.mem.eql(u8, file.name, "estilos.css")) wrote_styles = true;
    }
    try std.testing.expect(wrote_styles);
    try std.testing.expect(da_order_replan_async(handle, order, "otra revision") != 0);
}

