    try std.testing.expect(v.value.same_row);
    try std.testing.expectEqualStrings("Conserva estilos.css y usa azul; implementa en C", v.value.changes);
    // Un solo replan: un solo evento.
    try std.testing.expect(db.c.sqlite3_step(q) != db.c.SQLITE_ROW);
}

