/// SEMANTIC-GATE-T3: resuelve la clarificación del planner hasta que el plan
/// quede listo para aprobar (acotado — una orden que sigue aclarando tras
/// varias respuestas es un fallo honesto del test, no un bucle infinito).
/// Tras da_order_answer la orden queda .planned: se despacha con
/// da_order_approve, NO con plan_set_json (que es para planes EDITADOS — tras
/// answer el outcome vive bajo otro order_id y el check anti-stale lo marca).
fn settleClarification(handle: ?*anyopaque, order: ?*anyopaque) !void {
    var rounds: u32 = 0;
    while (rounds < 6) : (rounds += 1) {
        var status: c_int = -1;
        try std.testing.expectEqual(@as(c_int, 0), da_order_status(handle, order, &status));
        if (status == @intFromEnum(DaOrderStatus.planned)) return;
        if (status != @intFromEnum(DaOrderStatus.clarifying)) return error.UnexpectedOrderState;
        // El MockPlanner pregunta 'target-language' cuando la orden no nombra
        // un lenguaje; responder con otro id no la resuelve.
        try std.testing.expectEqual(@as(c_int, 0), da_order_answer(handle, order, "[{\"question_id\":\"target-language\",\"answer\":\"en C\"}]"));
    }
    return error.StillClarifying;
}

test "SEMANTIC-GATE-T3 c_api: el observable declarado manda sobre el veredicto (pass=done, fail=failed)" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    // AUDIT-UNAVAILABLE-P0: veredicto real para la auditoría — sin clave el
    // MockWorker produciría "mock-value" y toda orden cerraría audit_unavailable.
    useTestDoneLlm(@ptrCast(@alignCast(handle.?)));

    // Orden 1 — observable SATISFECHO: el MockWorker escribe "mock-value" en
    // estilos.css (extractRequestedBasename saca el nombre de la propia orden;
    // .css no tiene comando de ejecución — el gate de ejecución no interfiere).
    var order_ok: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "crea el archivo estilos.css", "sem-ok", null, &order_ok));
    const ok_id = orderHandleToId(order_ok).?;
    try settleClarification(handle, order_ok);
    try std.testing.expectEqual(@as(c_int, 0), da_order_set_expected(handle, order_ok, "[{\"kind\":\"file_exists\",\"path\":\"estilos.css\"},{\"kind\":\"file_contains\",\"path\":\"estilos.css\",\"needle\":\"mock-value\"}]"));
    // da_order_approve despacha de forma SÍNCRONA: al volver la orden ya es terminal.
    try std.testing.expectEqual(@as(c_int, 0), da_order_approve(handle, order_ok));
    var status: c_int = -1;
    _ = da_order_status(handle, order_ok, &status);
    try std.testing.expectEqual(@as(c_int, @intFromEnum(DaOrderStatus.done)), status);

    // Orden 2 — observable INCUMPLIDO: mismo gate de ejecución verde, pero el
    // literal declarado no está en el archivo → la orden NO puede ser done.
    var order_fail: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "crea el archivo estilos.css", "sem-fail", null, &order_fail));
    const fail_id = orderHandleToId(order_fail).?;
    try settleClarification(handle, order_fail);
    try std.testing.expectEqual(@as(c_int, 0), da_order_set_expected(handle, order_fail, "[{\"kind\":\"file_contains\",\"path\":\"estilos.css\",\"needle\":\"EL RESULTADO ES 9\"}]"));
    try std.testing.expectEqual(@as(c_int, 0), da_order_approve(handle, order_fail));
    status = -1;
    _ = da_order_status(handle, order_fail, &status);
    try std.testing.expectEqual(@as(c_int, @intFromEnum(DaOrderStatus.failed)), status);

    // La traza lo dice con la causa semántica y la diferencia concreta.
    var events: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_order_events_json(handle, order_fail, 0, &events));
    defer da_string_free(events);
    const es = std.mem.span(events);
    try std.testing.expect(std.mem.indexOf(u8, es, "semantic_gate_failed") != null);
    try std.testing.expect(std.mem.indexOf(u8, es, "EL RESULTADO ES 9") != null);

    // Una orden terminada ya no acepta declaraciones.
    try std.testing.expect(da_order_set_expected(handle, order_fail, "[{\"kind\":\"file_exists\",\"path\":\"x.c\"}]") != 0);

    // Limpieza de los artefactos escritos por ambos despachos.
    for ([_]i64{ ok_id, fail_id }) |oid| {
        const fp = try std.fmt.allocPrint(std.testing.allocator, "devagents-workspace\\orden-{d}\\estilos.css", .{oid});
        defer std.testing.allocator.free(fp);
        const fz = std.testing.allocator.dupeZ(u8, fp) catch continue;
        defer std.testing.allocator.free(fz);
        _ = DeleteFileA(fz.ptr);
    }
}

test "TERMINAL-P0 c_api: A6 — dispatch_poll timeout detection without detached thread nor status override" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);

    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "crea un modulo de logging en C", "test", null, &order));

    var json: [*:0]u8 = undefined;
    _ = da_plan_get_json(handle, order, &json);
    if (std.mem.indexOf(u8, std.mem.span(json), "needs_clarification\":true") != null) {
        _ = da_order_answer(handle, order, "[{\"question_id\":\"q1\",\"answer\":\"en C\"}]");
        da_string_free(json);
        _ = da_plan_get_json(handle, order, &json);
    }
    const rc_set = da_order_plan_set_json(handle, order, json);
    try std.testing.expectEqual(@as(c_int, 0), rc_set);
    da_string_free(json);

    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order).?;

    // Simular un despacho REAL en curso que ha excedido el timeout, sin lanzar un
    // hilo real. rec.status=.running replica lo que dispatchApprovedOrder ya habría
    // marcado al arrancar (ver rec.status = .running ahí); sin esto la orden se
    // hubiera quedado en 'planned' y la prueba no distinguiría "el watchdog no tocó
    // el status" de "nada tocó nunca el status".
    if (findOrder(st, order_id)) |r| r.status = .running;
    {
        const stmt = try st.db_conn.prepare("UPDATE orders SET status = 'running' WHERE id = ?");
        defer st.db_conn.finalize(stmt);
        try db.bindInt(stmt, 1, order_id);
        _ = db.c.sqlite3_step(stmt);
    }
    // C3-REGISTRY: simula un despacho en vuelo (sin hilo real) directamente vía
    // el registro, igual que da_order_dispatch_async lo haría salvo por el spawn.
    try st.dispatch_registry.begin(order_id, false, GetTickCount64() - DISPATCH_TIMEOUT_MS - 1000);

    // dispatch_poll debe detectar el timeout y reportar done=1, ok=0 — su PROPIO
    // contrato — sin necesidad de tocar orders.status para lograrlo.
    var done: c_int = 0;
    var ok_flag: c_int = -1;
    try std.testing.expectEqual(@as(c_int, 0), da_order_dispatch_poll(handle, order, &done, &ok_flag));
    try std.testing.expectEqual(@as(c_int, 1), done);
    try std.testing.expectEqual(@as(c_int, 0), ok_flag);

    // TERMINAL-STATE-DESIGN-2026-07-12 (P0 cierre): dispatch_failed/el watchdog de
    // timeout ya NO fuerzan orders.status — la orden sigue 'running' (memoria Y DB),
    // no 'failed'. El contrato done=1/ok=0 de arriba es la señal real para el cliente.
    var status: c_int = -1;
    _ = da_order_status(handle, order, &status);
    try std.testing.expectEqual(@as(c_int, @intFromEnum(DaOrderStatus.running)), status);
    {
        const stmt = try st.db_conn.prepare("SELECT status FROM orders WHERE id = ?");
        defer st.db_conn.finalize(stmt);
        try db.bindInt(stmt, 1, order_id);
        try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
        const ptr = db.c.sqlite3_column_text(stmt, 0) orelse return error.TestUnexpectedNull;
        const len = db.c.sqlite3_column_bytes(stmt, 0);
        try std.testing.expectEqualStrings("running", ptr[0..@intCast(len)]);
    }

    // Debe existir un evento dispatch_failed con error=dispatch_timeout.
    var events: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_order_events_json(handle, order, 0, &events));
    defer da_string_free(events);
    const s = std.mem.span(events);
    try std.testing.expect(std.mem.indexOf(u8, s, "dispatch_failed") != null);
    try std.testing.expect(std.mem.indexOf(u8, s, "dispatch_timeout") != null);

    // No debe quedar ningún thread detached: la entrada ya no conserva su handle.
    try std.testing.expect(!st.dispatch_registry.snapshot(order_id).has_thread);
    // timed_out debe ser true (no se re-declara timeout).
    try std.testing.expect(st.dispatch_registry.snapshot(order_id).timed_out);

    // Un segundo poll no debe cambiar el resultado ni re-declarar timeout.
    var done2: c_int = 0;
    var ok2: c_int = -1;
    try std.testing.expectEqual(@as(c_int, 0), da_order_dispatch_poll(handle, order, &done2, &ok2));
    try std.testing.expectEqual(@as(c_int, 1), done2);
    try std.testing.expectEqual(@as(c_int, 0), ok2);
}

test "c_api: A7 — normal dispatch leaves no detached thread (join verification)" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);

    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "crea un modulo de logging en C", "test", null, &order));

    var json: [*:0]u8 = undefined;
    _ = da_plan_get_json(handle, order, &json);
    if (std.mem.indexOf(u8, std.mem.span(json), "needs_clarification\":true") != null) {
        _ = da_order_answer(handle, order, "[{\"question_id\":\"q1\",\"answer\":\"en C\"}]");
        da_string_free(json);
        _ = da_plan_get_json(handle, order, &json);
    }
    const rc_set = da_order_plan_set_json(handle, order, json);
    try std.testing.expectEqual(@as(c_int, 0), rc_set);
    da_string_free(json);

    const st: *CoreState = @ptrCast(@alignCast(handle));

    // Lanzar despacho asíncrono.
    const rc_async = da_order_dispatch_async(handle, order);
    try std.testing.expectEqual(@as(c_int, 0), rc_async);

    // Poll hasta que termine. Presupuesto 6 s — el mismo que el test hermano
    // A4: bajo la carga de la suite completa el hilo de dispatch puede tardar
    // >2 s sin que eso sea un fallo (/E3-33: el flake era la ventana, no
    // la aserción). Lo que se verifica es el join, no la velocidad.
    var done: c_int = 0;
    var ok_flag: c_int = 0;
    var attempts: u32 = 0;
    while (done == 0 and attempts < 600) : (attempts += 1) {
        Sleep(10);
        _ = da_order_dispatch_poll(handle, order, &done, &ok_flag);
    }
    try std.testing.expect(done == 1);

    // Después del poll que reporta done=1, la entrada ya no conserva su thread
    // handle (fue joined, no detached).
    const order_id = orderHandleToId(order).?;
    try std.testing.expect(!st.dispatch_registry.snapshot(order_id).has_thread);

    // El status final debe ser done, failed o awaiting_approval, nunca planned.
    var status: c_int = -1;
    _ = da_order_status(handle, order, &status);
    try std.testing.expect(status != @intFromEnum(DaOrderStatus.planned));
}

test "TERMINAL-P0 c_api: dispatch failure (catch-block) marks tasks failed but leaves order status untouched, then a real terminal still wins" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);

    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "crea un modulo de logging en C", "test", null, &order));

    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order).?;
    const rec = findOrder(st, order_id) orelse return error.TestExpectedEqual;
    const original_plan_id = rec.outcome.?.plan_id;
    rec.outcome.?.plan_id = null;
    defer rec.outcome.?.plan_id = original_plan_id;

    const order_status_stmt = try st.db_conn.prepare("SELECT status FROM orders WHERE id = ?");
    defer st.db_conn.finalize(order_status_stmt);
    try db.bindInt(order_status_stmt, 1, order_id);
    try std.testing.expect(db.c.sqlite3_step(order_status_stmt) == db.c.SQLITE_ROW);
    const status_before = try std.testing.allocator.dupe(u8, std.mem.span(db.c.sqlite3_column_text(order_status_stmt, 0)));
    defer std.testing.allocator.free(status_before);
    _ = db.c.sqlite3_reset(order_status_stmt);

    // Fuerza el error real (error.NoPlanToApprove) que dispara el catch-block de
    // dispatchApprovedOrder — el mismo watchdog que ya no debe tocar orders.status.
    const rc = da_order_approve(handle, order);
    try std.testing.expect(rc != 0);

    // TERMINAL-STATE-DESIGN-2026-07-12 (P0 cierre): el status de la orden NO cambió
    // — ni a "failed" ni a ningún otro valor. dispatch_failed es puramente
    // informativo (el evento de abajo sigue existiendo); las tareas huérfanas sí
    // se marcan (segunda aserción, comportamiento sin cambios).
    try db.bindInt(order_status_stmt, 1, order_id);
    try std.testing.expect(db.c.sqlite3_step(order_status_stmt) == db.c.SQLITE_ROW);
    const status_after = std.mem.span(db.c.sqlite3_column_text(order_status_stmt, 0));
    try std.testing.expectEqualStrings(status_before, status_after);

    const open_tasks_stmt = try st.db_conn.prepare(
        \\SELECT COUNT(*)
        \\FROM tasks t
        \\JOIN plans p ON p.id = t.plan_id
        \\WHERE p.order_id = ? AND t.status <> 'failed'
    );
    defer st.db_conn.finalize(open_tasks_stmt);
    try db.bindInt(open_tasks_stmt, 1, order_id);
    try std.testing.expect(db.c.sqlite3_step(open_tasks_stmt) == db.c.SQLITE_ROW);
    try std.testing.expectEqual(@as(c_int, 0), db.c.sqlite3_column_int(open_tasks_stmt, 0));

    // El evento dispatch_failed existe (sigue siendo informativo)...
    const kind_stmt = try st.db_conn.prepare("SELECT COUNT(*) FROM events WHERE order_id = ? AND kind = 'dispatch_failed'");
    defer st.db_conn.finalize(kind_stmt);
    try db.bindInt(kind_stmt, 1, order_id);
    try std.testing.expect(db.c.sqlite3_step(kind_stmt) == db.c.SQLITE_ROW);
    try std.testing.expectEqual(@as(c_int, 1), db.c.sqlite3_column_int(kind_stmt, 0));

    // ...pero no bloquea un terminal real posterior (dispatch_failed→order_done):
    // un commit atómico legítimo todavía puede ganar esta orden.
    const won = try st.db_conn.tryCommitTerminal(order_id, "done", "order_done", "superagente", "{}", health.nowMillis(st.db_conn));
    try std.testing.expect(won);
}

test "c_api: HOTFIX-dispatch-uaf — boxed OrderRecord survives ArrayList realloc" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);

    var order1: ?*anyopaque = null;
