    try std.testing.expect(order1 != null);

    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id1 = orderHandleToId(order1).?;
    const rec1 = findOrder(st, order_id1);
    try std.testing.expect(rec1 != null);
    const rec1_ptr = rec1.?;
    const orig_id = rec1_ptr.id;
    const orig_status = rec1_ptr.status;

    // Append 32 orders to force >=1 ArrayList reallocation.
    var i: u32 = 0;
    while (i < 32) : (i += 1) {
        var dummy_order: ?*anyopaque = null;
