    }

    // The boxed pointer must still be valid (address stable, not moved by realloc).
    try std.testing.expectEqual(orig_id, rec1_ptr.id);
    try std.testing.expectEqual(orig_status, rec1_ptr.status);
}

// ── MULTISESSION-P0 (2026-07-12): Connection propia por hilo de dispatch ──────
// C3-DECISIONS-MULTISESSION-2026-07-12: elimina el uso concurrente inseguro del
// mismo sqlite3* de runtime.db entre el hilo principal y el hilo de dispatch.

test "MULTISESSION-P0 A: two threads write events with independent connections and both survive" {
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try isolatedTestPath(&tmp, "multisession-a.db");
    defer allocator.free(path);

    {
        var setup = try db.Connection.open(allocator, path);
        defer setup.close();
        var migrator = db.Migrator.init(allocator);
        try migrator.migrate(setup, &db.runtime_schema);
        try setup.exec("INSERT INTO orders (id, project_id, user_prompt, status, created_at) VALUES (1, 'p', 'hi', 'running', 1)");
    }

    const WriterCtx = struct {
        path: [:0]const u8,
        kind: []const u8,
        ok: bool = false,

        fn run(self: *@This()) void {
            var conn = db.Connection.open(std.testing.allocator, self.path) catch return;
            defer conn.close();
            const stmt = conn.prepare("INSERT INTO events (ts, source, kind, payload_json, order_id) VALUES (1, 'test', ?, '{}', 1)") catch return;
            defer conn.finalize(stmt);
            db.bindText(stmt, 1, self.kind) catch return;
            self.ok = db.c.sqlite3_step(stmt) == db.c.SQLITE_DONE;
        }
    };

    var ctx1 = WriterCtx{ .path = path, .kind = "thread_one" };
    var ctx2 = WriterCtx{ .path = path, .kind = "thread_two" };
    const t1 = try std.Thread.spawn(.{}, WriterCtx.run, .{&ctx1});
    const t2 = try std.Thread.spawn(.{}, WriterCtx.run, .{&ctx2});
    t1.join();
    t2.join();

    try std.testing.expect(ctx1.ok);
    try std.testing.expect(ctx2.ok);

    var verify = try db.Connection.open(allocator, path);
    defer verify.close();
    const stmt = try verify.prepare("SELECT COUNT(*) FROM events WHERE order_id = 1 AND kind IN ('thread_one','thread_two')");
    defer verify.finalize(stmt);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
    try std.testing.expectEqual(@as(c_int, 2), db.c.sqlite3_column_int(stmt, 0));
}

test "MULTISESSION-P0 B: main thread reads via its own connection while a writer thread writes via a different one" {
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try isolatedTestPath(&tmp, "multisession-b.db");
    defer allocator.free(path);

    {
        var setup = try db.Connection.open(allocator, path);
        defer setup.close();
        var migrator = db.Migrator.init(allocator);
        try migrator.migrate(setup, &db.runtime_schema);
        try setup.exec("INSERT INTO orders (id, project_id, user_prompt, status, created_at) VALUES (1, 'p', 'hi', 'running', 1)");
    }

    const WriterCtx = struct {
        path: [:0]const u8,
        written: usize = 0,

        fn run(self: *@This()) void {
            var conn = db.Connection.open(std.testing.allocator, self.path) catch return;
            defer conn.close();
            var i: usize = 0;
            while (i < 100) : (i += 1) {
                const stmt = conn.prepare("INSERT INTO events (ts, source, kind, payload_json, order_id) VALUES (1, 'writer', 'progress', '{}', 1)") catch continue;
                defer conn.finalize(stmt);
                if (db.c.sqlite3_step(stmt) == db.c.SQLITE_DONE) self.written += 1;
            }
        }
    };
    var wctx = WriterCtx{ .path = path };
    const writer_thread = try std.Thread.spawn(.{}, WriterCtx.run, .{&wctx});

    // "Main" usa su PROPIA conexión — jamás la del hilo escritor.
    var main_conn = try db.Connection.open(allocator, path);
    defer main_conn.close();
    var reads: usize = 0;
    while (reads < 50) : (reads += 1) {
        const stmt = main_conn.prepare("SELECT COUNT(*) FROM events WHERE order_id = 1") catch continue;
        defer main_conn.finalize(stmt);
        _ = db.c.sqlite3_step(stmt);
    }

    writer_thread.join();
    try std.testing.expectEqual(@as(usize, 100), wctx.written);

    const final_stmt = try main_conn.prepare("SELECT COUNT(*) FROM events WHERE order_id = 1 AND kind = 'progress'");
    defer main_conn.finalize(final_stmt);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(final_stmt));
    try std.testing.expectEqual(@as(c_int, 100), db.c.sqlite3_column_int(final_stmt, 0));
}

test "MULTISESSION-P0 C: concurrent terminal commit from independent connections keeps exactly one winner" {
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try isolatedTestPath(&tmp, "multisession-c.db");
    defer allocator.free(path);

    {
        var setup = try db.Connection.open(allocator, path);
        defer setup.close();
        var migrator = db.Migrator.init(allocator);
        try migrator.migrate(setup, &db.runtime_schema);
        try setup.exec("INSERT INTO orders (id, project_id, user_prompt, status, created_at) VALUES (1, 'p', 'hi', 'running', 1)");
    }

    const RaceCtx = struct {
        path: [:0]const u8,
        status: []const u8,
        kind: []const u8,
        result: bool = false,

        fn run(self: *@This()) void {
            var conn = db.Connection.open(std.testing.allocator, self.path) catch return;
            defer conn.close();
            self.result = conn.tryCommitTerminal(1, self.status, self.kind, "test", "{}", 1) catch false;
        }
    };
    var ctx_done = RaceCtx{ .path = path, .status = "done", .kind = "order_done" };
    var ctx_failed = RaceCtx{ .path = path, .status = "failed", .kind = "order_failed" };
    const t1 = try std.Thread.spawn(.{}, RaceCtx.run, .{&ctx_done});
    const t2 = try std.Thread.spawn(.{}, RaceCtx.run, .{&ctx_failed});
    t1.join();
    t2.join();

    try std.testing.expect(ctx_done.result != ctx_failed.result);

    var verify = try db.Connection.open(allocator, path);
    defer verify.close();
    const stmt = try verify.prepare("SELECT COUNT(*) FROM events WHERE order_id = 1 AND kind IN ('order_done','order_failed')");
    defer verify.finalize(stmt);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
    try std.testing.expectEqual(@as(c_int, 1), db.c.sqlite3_column_int(stmt, 0));
}

fn planAndApproveHelperOrder(handle: ?*anyopaque) !?*anyopaque {
    // AUDIT-UNAVAILABLE-P0: las órdenes auxiliares de los tests MULTISESSION
    // reciben un veredicto de auditoría real — sin clave, MockWorker produciría
    // "mock-value" y toda orden cerraría audit_unavailable.
    useTestDoneLlm(@ptrCast(@alignCast(handle.?)));
    var order: ?*anyopaque = null;
    if (da_order_submit(handle, "crea un modulo de logging en C", "test", null, &order) != 0) return error.SubmitFailed;
    var json: [*:0]u8 = undefined;
    _ = da_plan_get_json(handle, order, &json);
    if (std.mem.indexOf(u8, std.mem.span(json), "needs_clarification\":true") != null) {
        _ = da_order_answer(handle, order, "[{\"question_id\":\"q1\",\"answer\":\"en C\"}]");
        da_string_free(json);
        _ = da_plan_get_json(handle, order, &json);
    }
    if (da_order_plan_set_json(handle, order, json) != 0) {
        da_string_free(json);
        return error.PlanSetFailed;
    }
    da_string_free(json);
    return order;
}

test "MULTISESSION-P0 D: dispatch thread closes its own connection when it finishes (no lingering lock)" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try isolatedTestPath(&tmp, "multisession-d.db");
    defer std.testing.allocator.free(path);

    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, path));
    defer _ = da_core_shutdown(handle);

    const order = try planAndApproveHelperOrder(handle);

    try std.testing.expectEqual(@as(c_int, 0), da_order_dispatch_async(handle, order));
    var done: c_int = 0;
    var ok_flag: c_int = 0;
    var waited: usize = 0;
    // N-6/ventana uniforme 6 s (600×10 ms) — el poll caza deadlocks,
    // no mide latencia; el despacho real (Connection.open+migrate+superagent)
    // bajo carga de suite excede los 2 s sin ser un fallo.
    while (done == 0 and waited < 600) : (waited += 1) {
        _ = da_order_dispatch_poll(handle, order, &done, &ok_flag);
        if (done == 0) Sleep(10);
    }
    try std.testing.expectEqual(@as(c_int, 1), done);

    // No esperar por un lock: un lock superviviente debe producir SQLITE_BUSY,
    // aunque el SO desaloje el hilo de prueba durante más de un segundo.
    var fresh = try db.Connection.open(std.testing.allocator, path);
    defer fresh.close();
    try fresh.exec("PRAGMA busy_timeout = 0");
    try fresh.exec("UPDATE orders SET title = 'probe' WHERE id = 1");
}

test "MULTISESSION-P0 E: the context's owned path copy survives the source buffer being freed" {
    const allocator = std.testing.allocator;
    const original = try allocator.dupeZ(u8, "C:\\some\\fake\\runtime.db");
    // Simula exactamente el patrón de da_order_dispatch_async: el contexto
    // duplica OTRA VEZ desde el campo ya-owned de CoreState (aquí, `original`).
    const owned = try allocator.dupeZ(u8, original);
    allocator.free(original);
    // `original` ahora es memoria liberada; `owned` no debe depender de ella.
    defer allocator.free(owned);
    try std.testing.expectEqualStrings("C:\\some\\fake\\runtime.db", owned);
}

