    var done: c_int = 0;
    var ok_flag: c_int = 0;
    var waited: usize = 0;
    // N-6/ventana uniforme 6 s (600×10 ms) — el poll caza deadlocks,
    // no mide latencia; el despacho real (Connection.open+migrate+superagent)
    // bajo carga de suite excede los 2 s sin ser un fallo.
    while (done == 0 and waited < 600) : (waited += 1) {
        _ = da_order_dispatch_poll(handle, order, &done, &ok_flag);
        if (done == 0) Sleep(10);
    }
    try std.testing.expectEqual(@as(c_int, 1), done);

    // Si el hilo hubiera abierto silenciosamente OTRA ":memory:" desconectada,
    // st.db_conn (la del hilo principal, leída aquí) no vería ningún evento de
    // ciclo de vida de la orden.
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const stmt = try st.db_conn.prepare("SELECT COUNT(*) FROM events WHERE order_id = ?");
    defer st.db_conn.finalize(stmt);
    try db.bindInt(stmt, 1, order_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
    try std.testing.expect(db.c.sqlite3_column_int(stmt, 0) > 0);
}

test "MULTISESSION-P0 H: two simultaneous per-thread dispatch connections never mix order_id/events" {
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try isolatedTestPath(&tmp, "multisession-h.db");
    defer allocator.free(path);

    {
        var setup = try db.Connection.open(allocator, path);
        defer setup.close();
        var migrator = db.Migrator.init(allocator);
        try migrator.migrate(setup, &db.runtime_schema);
        try setup.exec("INSERT INTO orders (id, project_id, user_prompt, status, created_at) VALUES (100, 'p', 'a', 'running', 1)");
        try setup.exec("INSERT INTO orders (id, project_id, user_prompt, status, created_at) VALUES (200, 'p', 'b', 'running', 1)");
    }

    const OrderCtx = struct {
        path: [:0]const u8,
        order_id: i64,

        fn run(self: *@This()) void {
            var conn = db.Connection.open(std.testing.allocator, self.path) catch return;
            defer conn.close();
            var i: usize = 0;
            while (i < 20) : (i += 1) {
                const stmt = conn.prepare("INSERT INTO events (ts, source, kind, payload_json, order_id) VALUES (1, 'test', 'progress', '{}', ?)") catch continue;
                defer conn.finalize(stmt);
                db.bindInt(stmt, 1, self.order_id) catch continue;
                _ = db.c.sqlite3_step(stmt);
            }
        }
    };
    var ctx100 = OrderCtx{ .path = path, .order_id = 100 };
    var ctx200 = OrderCtx{ .path = path, .order_id = 200 };
    const t1 = try std.Thread.spawn(.{}, OrderCtx.run, .{&ctx100});
    const t2 = try std.Thread.spawn(.{}, OrderCtx.run, .{&ctx200});
    t1.join();
    t2.join();

    var verify = try db.Connection.open(allocator, path);
    defer verify.close();
    for ([_]i64{ 100, 200 }) |oid| {
        const stmt = try verify.prepare("SELECT COUNT(*) FROM events WHERE order_id = ?");
        defer verify.finalize(stmt);
        try db.bindInt(stmt, 1, oid);
        try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
        try std.testing.expectEqual(@as(c_int, 20), db.c.sqlite3_column_int(stmt, 0));
    }
    const total_stmt = try verify.prepare("SELECT COUNT(*) FROM events WHERE order_id IN (100, 200)");
    defer verify.finalize(total_stmt);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(total_stmt));
    try std.testing.expectEqual(@as(c_int, 40), db.c.sqlite3_column_int(total_stmt, 0));
}

test "MULTISESSION-P0 I: flushAuditQueue-triggering reads never race the dispatch thread's own connection" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try isolatedTestPath(&tmp, "multisession-i.db");
    defer std.testing.allocator.free(path);

    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, path));
    defer _ = da_core_shutdown(handle);

    const order = try planAndApproveHelperOrder(handle);

    try std.testing.expectEqual(@as(c_int, 0), da_order_dispatch_async(handle, order));

    // Mientras el hilo de dispatch corre (usa SU PROPIA conexión), el hilo
    // principal llama repetidamente rutas que ANTES no tenían guardia contra el
    // hilo de dispatch (da_ledger_escalations_json/da_audit_ledger_json llaman
    // flushAuditQueue incondicionalmente, que lee st.db_conn vía health.nowMillis).
    // Ya no puede haber carrera: el hilo de dispatch no toca st.db_conn en absoluto.
    var i: usize = 0;
    while (i < 30) : (i += 1) {
        var out1: [*:0]u8 = undefined;
        if (da_ledger_escalations_json(handle, &out1) == 0) da_string_free(out1);
        var out2: [*:0]u8 = undefined;
        if (da_audit_ledger_json(handle, &out2) == 0) da_string_free(out2);
    }

    var done: c_int = 0;
    var ok_flag: c_int = 0;
    var waited: usize = 0;
    // N-6/ventana uniforme 6 s (600×10 ms) — el poll caza deadlocks,
    // no mide latencia; el despacho real (Connection.open+migrate+superagent)
    // bajo carga de suite excede los 2 s sin ser un fallo.
    while (done == 0 and waited < 600) : (waited += 1) {
        _ = da_order_dispatch_poll(handle, order, &done, &ok_flag);
        if (done == 0) Sleep(10);
    }
    try std.testing.expectEqual(@as(c_int, 1), done);
}

