test "MULTISESSION-P0 E: two sequential file-backed dispatches never share a sqlite3* nor cross-contaminate memory" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try isolatedTestPath(&tmp, "multisession-e.db");
    defer std.testing.allocator.free(path);

    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, path));
    defer _ = da_core_shutdown(handle);

    // C3-REGISTRY: este test corre las dos órdenes SECUENCIALMENTE a propósito
    // (aunque el registro ya permitiría despacharlas en paralelo, al ser
    // órdenes DISTINTAS) — el objetivo aquí es probar que reabrir una Connection
    // fresca por hilo, dos veces seguidas sobre el mismo archivo, nunca reutiliza
    // un handle del despacho previo ni deja estado cruzado.
    const order1 = try planAndApproveHelperOrder(handle);
    try std.testing.expectEqual(@as(c_int, 0), da_order_dispatch_async(handle, order1));
    var done: c_int = 0;
    var ok_flag: c_int = 0;
    var waited: usize = 0;
    // N-6/ventana uniforme 6 s (600×10 ms) — el poll caza deadlocks,
    // no mide latencia; el despacho real (Connection.open+migrate+superagent)
    // bajo carga de suite excede los 2 s sin ser un fallo.
    while (done == 0 and waited < 600) : (waited += 1) {
        _ = da_order_dispatch_poll(handle, order1, &done, &ok_flag);
        if (done == 0) Sleep(10);
    }
    try std.testing.expectEqual(@as(c_int, 1), done);

    const order2 = try planAndApproveHelperOrder(handle);
    try std.testing.expectEqual(@as(c_int, 0), da_order_dispatch_async(handle, order2));
    done = 0;
    ok_flag = 0;
    waited = 0;
    // N-6/ventana uniforme 6 s (600×10 ms) — el poll caza deadlocks,
    // no mide latencia; el despacho real (Connection.open+migrate+superagent)
    // bajo carga de suite excede los 2 s sin ser un fallo.
    while (done == 0 and waited < 600) : (waited += 1) {
        _ = da_order_dispatch_poll(handle, order2, &done, &ok_flag);
        if (done == 0) Sleep(10);
    }
    try std.testing.expectEqual(@as(c_int, 1), done);

    // Ambas órdenes terminaron con su propio evento terminal, sin mezclar
    // order_id — prueba que reabrir una Connection fresca por hilo, dos veces
    // seguidas sobre el mismo archivo, no deja estado cruzado ni corrupción.
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const id1 = orderHandleToId(order1).?;
    const id2 = orderHandleToId(order2).?;
    try std.testing.expect(id1 != id2);
    for ([_]i64{ id1, id2 }) |oid| {
        const stmt = try st.db_conn.prepare("SELECT COUNT(*) FROM events WHERE order_id = ? AND kind IN ('order_done','order_failed')");
        defer st.db_conn.finalize(stmt);
        try db.bindInt(stmt, 1, oid);
        try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
        try std.testing.expectEqual(@as(c_int, 1), db.c.sqlite3_column_int(stmt, 0));
    }
}

test "MULTISESSION-P0 F: :memory: dispatch prevents real concurrency over the shared handle" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);

    const order = try planAndApproveHelperOrder(handle);

    // Dos hilos intentan da_order_dispatch_async CASI simultáneamente sobre la
    // MISMA orden ":memory:" (que comparte st.db_conn a propósito). Esto es
    // seguro ÚNICAMENTE si DispatchRegistry.begin() garantiza que como mucho
    // UNO progresa (aquí vía DuplicateOrder — mismo order_id — pero el mismo
    // registro también rechazaría una orden DISTINTA bajo `:memory:` vía
    // MemoryBusy, ver test C3-REGISTRY E) — exactamente lo que este test verifica.
    const RaceCtx = struct {
        handle: ?*anyopaque,
        order: ?*anyopaque,
        rc: c_int = -1,

        fn run(self: *@This()) void {
            self.rc = da_order_dispatch_async(self.handle, self.order);
        }
    };
    var ctx1 = RaceCtx{ .handle = handle, .order = order };
    var ctx2 = RaceCtx{ .handle = handle, .order = order };
    const t1 = try std.Thread.spawn(.{}, RaceCtx.run, .{&ctx1});
    const t2 = try std.Thread.spawn(.{}, RaceCtx.run, .{&ctx2});
    t1.join();
    t2.join();

    const wins: u32 = @as(u32, @intFromBool(ctx1.rc == 0)) + @as(u32, @intFromBool(ctx2.rc == 0));
    try std.testing.expectEqual(@as(u32, 1), wins);

    // Drenar el que ganó antes de shutdown.
    var done: c_int = 0;
    var ok_flag: c_int = 0;
    var waited: usize = 0;
    // N-6/ventana uniforme 6 s (600×10 ms) — el poll caza deadlocks,
    // no mide latencia; el despacho real (Connection.open+migrate+superagent)
    // bajo carga de suite excede los 2 s sin ser un fallo.
    while (done == 0 and waited < 600) : (waited += 1) {
        _ = da_order_dispatch_poll(handle, order, &done, &ok_flag);
        if (done == 0) Sleep(10);
    }
    try std.testing.expectEqual(@as(c_int, 1), done);
}

test "MULTISESSION-P0 C3-L: two concurrent file-backed orders complete independently with first-wins terminals, no cross-contamination" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try isolatedTestPath(&tmp, "c3-l.db");
    defer std.testing.allocator.free(path);

    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, path));
    defer _ = da_core_shutdown(handle);

    const order1 = try planAndApproveHelperOrder(handle);
    const order2 = try planAndApproveHelperOrder(handle);

    // Ambos despachos deben ACEPTARSE — órdenes DISTINTAS, file-backed, sin
    // compartir hilo/flags/timeout/Connection: el objetivo central de C3.
    try std.testing.expectEqual(@as(c_int, 0), da_order_dispatch_async(handle, order1));
    try std.testing.expectEqual(@as(c_int, 0), da_order_dispatch_async(handle, order2));

    var done1: c_int = 0;
    var ok1: c_int = 0;
    var done2: c_int = 0;
    var ok2: c_int = 0;
    var saw_both_in_flight = false;
    var waited2: usize = 0;
    // N-6/el poll dual necesita el doble de ventana (12 s) — dos
    // despachos sobre el MISMO archivo SQLite se serializan por los locks de
    // escritura (busy_timeout 5 s por conexión), así que el segundo arranca
    // con el primero a medio camino.
    while ((done1 == 0 or done2 == 0) and waited2 < 1200) : (waited2 += 1) {
        _ = da_order_dispatch_poll(handle, order1, &done1, &ok1);
        _ = da_order_dispatch_poll(handle, order2, &done2, &ok2);
        if (done1 == 0 and done2 == 0) saw_both_in_flight = true;
        if (done1 == 0 or done2 == 0) Sleep(10);
    }
    // Evidencia POSITIVA de concurrencia real (no solo secuencial-por-casualidad):
    // hubo al menos un instante donde NINGUNA de las dos había terminado.
    try std.testing.expect(saw_both_in_flight);
    try std.testing.expectEqual(@as(c_int, 1), done1);
    try std.testing.expectEqual(@as(c_int, 1), done2);

    // Cada orden terminó con EXACTAMENTE un evento terminal propio — first-wins
    // por orden, sin duplicar ni mezclarse con el de la otra.
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const id1 = orderHandleToId(order1).?;
    const id2 = orderHandleToId(order2).?;
    try std.testing.expect(id1 != id2);
    for ([_]i64{ id1, id2 }) |oid| {
        const stmt = try st.db_conn.prepare("SELECT COUNT(*) FROM events WHERE order_id = ? AND kind IN ('order_done','order_failed')");
        defer st.db_conn.finalize(stmt);
        try db.bindInt(stmt, 1, oid);
        try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
        try std.testing.expectEqual(@as(c_int, 1), db.c.sqlite3_column_int(stmt, 0));
    }
}

test "HISTORY-V2: conversation messages cross orders without leaking another thread" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    try st.db_conn.exec("INSERT INTO orders(id,project_id,user_prompt,status,created_at,conversation_id) VALUES (9101,'history-test','first','done',1,'thread-a'),(9102,'history-test','second','done',2,'thread-a'),(9103,'history-test','other','done',3,'thread-b'),(9104,'history-test','legacy','done',4,NULL)");
    const sessions = st.sessions.?;
    try sessions.saveMessageFn(9101, "user", "first turn", 10);
    try sessions.saveMessageFn(9102, "assistant", "second turn", 10);
    try sessions.saveMessageFn(9103, "user", "private other thread", 9);
    try sessions.saveMessageFn(9104, "user", "legacy turn", 11);
    var json: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_session_messages_v2_json(handle, orderIdToHandle(9102), &json));
    defer da_string_free(json);
    const parsed = try std.json.parseFromSlice(std.json.Value, std.testing.allocator, std.mem.span(json), .{});
    defer parsed.deinit();
    try std.testing.expectEqual(@as(usize, 2), parsed.value.array.items.len);
    try std.testing.expectEqualStrings("first turn", parsed.value.array.items[0].object.get("content").?.string);
    try std.testing.expectEqualStrings("second turn", parsed.value.array.items[1].object.get("content").?.string);

    var legacy: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_session_messages_v2_json(handle, orderIdToHandle(9104), &legacy));
    defer da_string_free(legacy);
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(legacy), "legacy turn") != null);
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(legacy), "first turn") == null);
}

/// Version 2: messages from every order in the selected order's conversation.
/// The unversioned API remains order-scoped. Legacy orders remain isolated.
/// Returns [{id,order_id,role,content,created_at}], or a real error on read failure.
pub export fn da_session_messages_v2_json(handle: ?*anyopaque, order: ?*anyopaque, out_json: *[*:0]u8) callconv(.c) c_int {
    if (handle == null) return @intFromEnum(err(.invalid_arg, "da_session_messages_v2_json: null core handle"));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const order_id = orderHandleToId(order) orelse return @intFromEnum(err(.invalid_arg, "da_session_messages_v2_json: null order handle"));
    const aa = st.arena.child_allocator;
    const db_id = if (findOrder(st, order_id)) |rec| (rec.db_id orelse rec.id) else order_id;
    const sessions = st.sessions orelse return @intFromEnum(err(.invalid_state, "da_session_messages_v2_json: session store unavailable"));
    const stmt = st.db_conn.prepare("SELECT COALESCE(conversation_id,'') FROM orders WHERE id = ?") catch
        return @intFromEnum(err(.internal, "da_session_messages_v2_json: cannot read conversation"));
    defer st.db_conn.finalize(stmt);
    db.bindInt(stmt, 1, db_id) catch return @intFromEnum(err(.internal, "da_session_messages_v2_json: cannot bind order"));
    const step = db.c.sqlite3_step(stmt);
    if (step == db.c.SQLITE_DONE) return @intFromEnum(err(.not_found, "da_session_messages_v2_json: order not found"));
    if (step != db.c.SQLITE_ROW) return @intFromEnum(err(.internal, "da_session_messages_v2_json: conversation read failed"));
    const conv_ptr = db.c.sqlite3_column_text(stmt, 0);
    const conv_len: usize = @intCast(db.c.sqlite3_column_bytes(stmt, 0));
    const msgs = (if (conv_len > 0)
        sessions.loadConversationMessagesFn(aa, conv_ptr[0..conv_len])
    else
        sessions.loadMessagesFn(aa, db_id)) catch
        return @intFromEnum(err(.internal, "da_session_messages_v2_json: message read failed"));
    defer {
        for (msgs) |m| {
            aa.free(m.role);
            aa.free(m.content);
        }
        aa.free(msgs);
    }
    var out: std.Io.Writer.Allocating = .init(aa);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.write(msgs) catch return @intFromEnum(err(.oom, "da_session_messages_v2_json: serialization failed"));
    out_json.* = ownedCStr(out.written()) orelse return @intFromEnum(err(.oom, "da_session_messages_v2_json: OOM"));
    return @intFromEnum(ok());
}

