test "SESSION-DELETE API: active registry and persistent status preserve order; stale approval is rejected" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle));
    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "crea un modulo de logging en C", "test", null, &order));
    const id = orderHandleToId(order).?;
    const rec = findOrder(st, id).?;
    const update = try st.db_conn.prepare("UPDATE orders SET status=? WHERE id=?");
    defer st.db_conn.finalize(update);
    try db.bindInt(update, 2, rec.db_id orelse rec.id);
    try db.bindText(update, 1, "running");
    try std.testing.expectEqual(db.c.SQLITE_DONE, db.c.sqlite3_step(update));
    rec.status = .planned; // Another connection owns the persisted running order.
    try std.testing.expectEqual(@intFromEnum(DaResult.invalid_state), da_session_delete(handle, order));
    _ = db.c.sqlite3_reset(update);
    try db.bindText(update, 1, "planned");
    try std.testing.expectEqual(db.c.SQLITE_DONE, db.c.sqlite3_step(update));
    try st.dispatch_registry.begin(id, false, 0);
    try std.testing.expectEqual(@intFromEnum(DaResult.invalid_state), da_session_delete(handle, order));
    st.dispatch_registry.abortNeverStarted(id);
    try std.testing.expectEqual(@as(c_int, 0), da_session_delete(handle, order));
    try std.testing.expectEqual(@intFromEnum(DaResult.invalid_state), da_order_approve(handle, order));
    const verify = try st.db_conn.prepare("SELECT COUNT(*) FROM orders WHERE id=?");
    defer st.db_conn.finalize(verify);
    try db.bindInt(verify, 1, rec.db_id orelse rec.id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(verify));
    try std.testing.expectEqual(@as(c_int, 0), db.c.sqlite3_column_int(verify, 0));
    // E2.5: la sesión borrada no reaparece en da_sessions_json como «rejected»
    // — el registro sigue vivo por handles obsoletos pero está marcado deleted.
    var sessions: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_sessions_json(handle, &sessions));
    defer da_string_free(sessions);
    const listed = std.mem.span(sessions);
    const needle = try std.fmt.allocPrint(std.testing.allocator, "\"id\":{}", .{id});
    defer std.testing.allocator.free(needle);
    try std.testing.expect(std.mem.indexOf(u8, listed, needle) == null);
}

test "ORDENES DISPATCH-V1 unavailable deterministic pin never dispatches a mock" {
    // Keep dispatch's workspace preparation away from the repository's shared
    // devagents/orden-1 branch (beats/orden-1 before 10-nov); this test
    // exercises model availability, not Git.
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const directory = try tmp.dir.realPathFileAlloc(std.testing.io, ".", a);
    defer a.free(directory);
    workspace.setOrderRootOverride(directory);
    defer workspace.setOrderRootOverride(null);
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "Crea fixture.c en C", "pin-fixture", null, &order));
    try std.testing.expectEqual(@as(c_int, 0), da_plan_set_model(handle, "UnavailableFixtureProvider", "UnavailableFixtureModel"));
    try std.testing.expectEqual(@as(c_int, 0), da_set_deterministic_mode(handle, 1));
    try std.testing.expect(da_order_approve(handle, order) != 0);
    var status: c_int = -1;
    try std.testing.expectEqual(@as(c_int, 0), da_order_status(handle, order, &status));
    try std.testing.expectEqual(@as(c_int, @intFromEnum(DaOrderStatus.failed)), status);
    var events: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_order_events_json(handle, order, 0, &events));
    defer da_string_free(events);
    const text = std.mem.span(events);
    try std.testing.expect(std.mem.indexOf(u8, text, "selected_model_unavailable") != null);
    try std.testing.expect(std.mem.indexOf(u8, text, "task_started") == null);
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const stmt = try st.db_conn.prepare("SELECT status FROM orders WHERE id=?");
    defer st.db_conn.finalize(stmt);
    try db.bindInt(stmt, 1, orderHandleToId(order).?);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
    try std.testing.expectEqualStrings("failed", std.mem.span(db.c.sqlite3_column_text(stmt, 0).?));
}

test "ROLES-MODELO: pins exec/audit por C-API — set/get y resolución contra el pin de la orden" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);

    var prov: ?[*:0]const u8 = null;
    var model: ?[*:0]const u8 = null;

    // Sin nada fijado: los getters de rol devuelven NULL (siguen al de la orden).
    try std.testing.expectEqual(@as(c_int, 0), da_exec_get_model(handle, &prov, &model));
    try std.testing.expect(prov == null and model == null);
    try std.testing.expectEqual(@as(c_int, 0), da_audit_get_model(handle, &prov, &model));
    try std.testing.expect(prov == null and model == null);

    // Pin de ejecutor solo: get lo devuelve; el auditor queda NULL — jamás
    // hereda del ejecutor.
    try std.testing.expectEqual(@as(c_int, 0), da_exec_set_model(handle, "GPT", "gpt-fixture"));
    try std.testing.expectEqual(@as(c_int, 0), da_exec_get_model(handle, &prov, &model));
    try std.testing.expectEqualStrings("GPT", std.mem.span(prov.?));
    da_string_free(@constCast(prov.?));
    try std.testing.expectEqualStrings("gpt-fixture", std.mem.span(model.?));
    da_string_free(@constCast(model.?));
    prov = null;
    model = null;
    try std.testing.expectEqual(@as(c_int, 0), da_audit_get_model(handle, &prov, &model));
    try std.testing.expect(prov == null and model == null);

    // Resolución efectiva: exec pin solo → audit_eff = plan(null) → null.
    const st: *CoreState = @ptrCast(@alignCast(handle));
    var sel = try captureModelSelection(st, std.testing.allocator);
    try std.testing.expectEqualStrings("GPT", sel.exec_provider.?);
    try std.testing.expect(sel.audit_provider == null);
    sel.deinit(std.testing.allocator);

    // Con pin de orden + exec: el auditor sigue automático e independiente.
    try std.testing.expectEqual(@as(c_int, 0), da_plan_set_model(handle, "Cohere", "command-fixture"));
    var sel2 = try captureModelSelection(st, std.testing.allocator);
    try std.testing.expectEqualStrings("GPT", sel2.exec_provider.?);
    try std.testing.expect(sel2.audit_provider == null);
    try std.testing.expect(sel2.audit_model == null);
    sel2.deinit(std.testing.allocator);

    // Pin de auditor explícito gana al de la orden.
    try std.testing.expectEqual(@as(c_int, 0), da_audit_set_model(handle, "Google AI Studio", "gemini-fixture"));
    var sel3 = try captureModelSelection(st, std.testing.allocator);
    try std.testing.expectEqualStrings("Google AI Studio", sel3.audit_provider.?);
    sel3.deinit(std.testing.allocator);

    // Limpiar el pin de ejecutor: vuelve a heredar el de la orden.
    try std.testing.expectEqual(@as(c_int, 0), da_exec_set_model(handle, null, null));
    var sel4 = try captureModelSelection(st, std.testing.allocator);
    try std.testing.expectEqualStrings("Cohere", sel4.exec_provider.?);
    sel4.deinit(std.testing.allocator);
}

test "ENJAMBRE: da_swarm_set_models_json valida forma, normaliza y captura por orden" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);

    var out: ?[*:0]const u8 = null;
    // Sin fijar: "[]" = Automático.
    try std.testing.expectEqual(@as(c_int, 0), da_swarm_get_models_json(handle, &out));
    try std.testing.expectEqualStrings("[]", std.mem.span(out.?));
    da_string_free(@constCast(out.?));
    out = null;

    // Forma inválida: no-array, miembro sin model, JSON roto, más de 8 → error
    // y el conjunto previo queda intacto.
    try std.testing.expect(da_swarm_set_models_json(handle, "{\"a\":1}") != 0);
    try std.testing.expect(da_swarm_set_models_json(handle, "[{\"provider\":\"p\"}]") != 0);
    try std.testing.expect(da_swarm_set_models_json(handle, "no-json") != 0);
    try std.testing.expect(da_swarm_set_models_json(handle, "[\"p|m\"]") != 0);
    try std.testing.expect(da_swarm_set_models_json(handle, "[{\"provider\":\"p\",\"model\":\"m\"},{\"provider\":\"p\",\"model\":\"m\"},{\"provider\":\"p\",\"model\":\"m\"},{\"provider\":\"p\",\"model\":\"m\"},{\"provider\":\"p\",\"model\":\"m\"},{\"provider\":\"p\",\"model\":\"m\"},{\"provider\":\"p\",\"model\":\"m\"},{\"provider\":\"p\",\"model\":\"m\"},{\"provider\":\"p\",\"model\":\"m\"}]") != 0);

    // Válido: se normaliza (campos extra caen) y get devuelve solo provider/model.
    try std.testing.expectEqual(@as(c_int, 0), da_swarm_set_models_json(handle, "[{\"provider\":\"OpenRouter\",\"model\":\"a\",\"extra\":1},{\"provider\":\"Cohere\",\"model\":\"b\"}]"));
    try std.testing.expectEqual(@as(c_int, 0), da_swarm_get_models_json(handle, &out));
    try std.testing.expectEqualStrings("[{\"provider\":\"OpenRouter\",\"model\":\"a\"},{\"provider\":\"Cohere\",\"model\":\"b\"}]", std.mem.span(out.?));
    da_string_free(@constCast(out.?));
    out = null;

    // El snapshot por orden lo captura junto a los pines.
    const st: *CoreState = @ptrCast(@alignCast(handle));
    var sel = try captureModelSelection(st, std.testing.allocator);
    try std.testing.expectEqualStrings("[{\"provider\":\"OpenRouter\",\"model\":\"a\"},{\"provider\":\"Cohere\",\"model\":\"b\"}]", sel.swarm_json.?);
    sel.deinit(std.testing.allocator);

    // "[]" y NULL → Automático (conjunto liberado).
    try std.testing.expectEqual(@as(c_int, 0), da_swarm_set_models_json(handle, "[]"));
    try std.testing.expect(st.swarm_models_json == null);
    try std.testing.expectEqual(@as(c_int, 0), da_swarm_set_models_json(handle, null));
    try std.testing.expect(st.swarm_models_json == null);
}

test "DISPATCH-V1 multi-task watchdog does not expire at old four-minute limit" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle));
    try st.dispatch_registry.beginWithTimeout(991, false, GetTickCount64() - 241_000, 900_000);
    var done: c_int = -1;
    var succeeded: c_int = -1;
    try std.testing.expectEqual(@as(c_int, 0), da_order_dispatch_poll(handle, @ptrFromInt(991), &done, &succeeded));
    try std.testing.expectEqual(@as(c_int, 0), done);
    try std.testing.expect(!st.dispatch_registry.snapshot(991).timed_out);
}

test "c_api: D8 clarification round trip resolves ambiguous order" {
    var handle: ?*anyopaque = null;
    _ = da_core_init(&handle, ":memory:");
    defer _ = da_core_shutdown(handle);

    var order: ?*anyopaque = null;
    _ = da_order_submit(handle, "crea un proyecto", "test", null, &order);

    var status: c_int = -1;
    _ = da_order_status(handle, order, &status);
    try std.testing.expectEqual(@as(c_int, @intFromEnum(DaOrderStatus.clarifying)), status);

    var json: [*:0]u8 = undefined;
    _ = da_plan_get_json(handle, order, &json);
    const plan_str = std.mem.span(json);
    try std.testing.expect(std.mem.indexOf(u8, plan_str, "needs_clarification\":true") != null);
    try std.testing.expect(std.mem.indexOf(u8, plan_str, "\"id\":\"target-language\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, plan_str, "\"text\":") != null);

    const answers = "[{\"question_id\":\"target-language\",\"answer\":\"Zig\"}]";
    try std.testing.expectEqual(@as(c_int, 0), da_order_answer(handle, order, answers));

    var status2: c_int = -1;
    _ = da_order_status(handle, order, &status2);
    try std.testing.expect(status2 != @as(c_int, @intFromEnum(DaOrderStatus.clarifying)));
    try std.testing.expect(status2 != @as(c_int, @intFromEnum(DaOrderStatus.failed)));
}

test "c_api: D8 clarification answer rejects dict payload" {
    var handle: ?*anyopaque = null;
    _ = da_core_init(&handle, ":memory:");
    defer _ = da_core_shutdown(handle);

    var order: ?*anyopaque = null;
    _ = da_order_submit(handle, "crea un proyecto", "test", null, &order);

    var status: c_int = -1;
    _ = da_order_status(handle, order, &status);
    try std.testing.expectEqual(@as(c_int, @intFromEnum(DaOrderStatus.clarifying)), status);

    const dict_payload = "{\"target-language\":\"Zig\"}";
    const rc = da_order_answer(handle, order, dict_payload);
    try std.testing.expect(rc != 0);

    var status2: c_int = -1;
    _ = da_order_status(handle, order, &status2);
    try std.testing.expectEqual(@as(c_int, @intFromEnum(DaOrderStatus.clarifying)), status2);
}

test "c_api: D8 clarify cap fails order after two rounds" {
    var handle: ?*anyopaque = null;
    _ = da_core_init(&handle, ":memory:");
    defer _ = da_core_shutdown(handle);

    var order: ?*anyopaque = null;
    _ = da_order_submit(handle, "crea un proyecto", "test", null, &order);

    var status: c_int = -1;
    _ = da_order_status(handle, order, &status);
    try std.testing.expectEqual(@as(c_int, @intFromEnum(DaOrderStatus.clarifying)), status);

    // submit ya consumio la ronda 1 (la orden nacio clarifying). La primera
    // respuesta vaga produce la ronda 2; la siguiente re-plan excede el tope.
    const vague = "[{\"question_id\":\"target-language\",\"answer\":\"no lo se\"}]";
    _ = da_order_answer(handle, order, vague);
    _ = da_order_status(handle, order, &status);
    try std.testing.expectEqual(@as(c_int, @intFromEnum(DaOrderStatus.clarifying)), status);

    _ = da_order_answer(handle, order, vague);
    _ = da_order_status(handle, order, &status);
    try std.testing.expectEqual(@as(c_int, @intFromEnum(DaOrderStatus.failed)), status);
}

fn contarOrdenes(handle: ?*anyopaque) !i64 {
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const stmt = try st.db_conn.prepare("SELECT COUNT(*) FROM orders");
    defer st.db_conn.finalize(stmt);
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) return error.SinFila;
    return db.c.sqlite3_column_int64(stmt, 0);
}

test "c_api: E-88 una aclaracion replanifica sobre la MISMA fila, sin huerfanas" {
    var handle: ?*anyopaque = null;
    _ = da_core_init(&handle, ":memory:");
    defer _ = da_core_shutdown(handle);

    var order: ?*anyopaque = null;
    _ = da_order_submit(handle, "crea un proyecto", "test", null, &order);
    try std.testing.expectEqual(@as(i64, 1), try contarOrdenes(handle));

    const answers = "[{\"question_id\":\"target-language\",\"answer\":\"Zig\"}]";
    try std.testing.expectEqual(@as(c_int, 0), da_order_answer(handle, order, answers));

    // Antes: 2 filas, la primera `clarifying` para siempre.
    try std.testing.expectEqual(@as(i64, 1), try contarOrdenes(handle));
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const stmt = try st.db_conn.prepare("SELECT COUNT(*) FROM orders WHERE status = 'clarifying'");
    defer st.db_conn.finalize(stmt);
    try std.testing.expectEqual(@as(c_int, db.c.SQLITE_ROW), db.c.sqlite3_step(stmt));
    try std.testing.expectEqual(@as(i64, 0), db.c.sqlite3_column_int64(stmt, 0));
}

test "c_api: E-88 el id del submit async es el rowid real de la orden" {
    var handle: ?*anyopaque = null;
    _ = da_core_init(&handle, ":memory:");
    defer _ = da_core_shutdown(handle);

    // Otra orden antes, como la que dejaría otro proceso en la misma base: el
    // contador en memoria de ESTE proceso no la conoce.
    const st: *CoreState = @ptrCast(@alignCast(handle));
    _ = try superagent.Superagent.insertOrderRow(st.db_conn, "otro", "de otro proceso", "done", 1);
    _ = try superagent.Superagent.insertOrderRow(st.db_conn, "otro", "de otro proceso", "done", 1);

    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit_async(handle, "hola", "test", null, &order));
    const devuelto = orderHandleToId(order).?;

    const stmt = try st.db_conn.prepare("SELECT MAX(id) FROM orders WHERE user_prompt = 'hola'");
    defer st.db_conn.finalize(stmt);
    try std.testing.expectEqual(@as(c_int, db.c.SQLITE_ROW), db.c.sqlite3_step(stmt));
    try std.testing.expectEqual(db.c.sqlite3_column_int64(stmt, 0), devuelto);

    // Esperar a que el hilo de planificación termine antes del shutdown, y que
    // no haya creado una segunda fila para la misma orden.
    var done: c_int = 0;
    var plan_ok: c_int = 0;
    var i: usize = 0;
    while (i < 200 and done == 0) : (i += 1) {
        _ = da_order_plan_poll(handle, &done, &plan_ok);
        if (done == 0) Sleep(25);
    }
    try std.testing.expectEqual(@as(c_int, 1), done);
    try std.testing.expectEqual(@as(i64, 3), try contarOrdenes(handle));
}

test "T2d-D1 c_api: una orden de Directo lleva al agente el modo de permisos fijado en la cabina" {
    if (@import("builtin").os.tag != .windows) return @import("platform.zig").skip("T9: CLI externa (Codex, OpenCode, Claude, Gemini) no disponible en Linux en esta version (ExternalCliUnavailableOnLinux en external_cli_policy)");
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle));
    // Detección guardada con OpenCode (la que deja «Volver a detectar»); sin
    // ella la comprobación previa al envío rechaza el ejecutor.
    try external_registry.store(st.catalog.db, "[{\"provider\":\"agent:opencode\",\"cli\":\"opencode\",\"exe\":\"C:/app/opencode.exe\",\"version\":\"1.18.25\",\"session\":\"api_key\",\"models\":[{\"slug\":\"opencode/x-free\",\"zero_cost\":true}]}]", health.nowSeconds(st.catalog.db));
    // Mismo camino que la cabina: core.permissions.set, modo de trabajo y
    // «Modelo de la orden» con una CLI ejecutora.
    try std.testing.expectEqual(@as(c_int, 0), da_set_permission_config(handle, "{\"mode\":\"autonomous\"}"));
    try std.testing.expectEqual(@as(c_int, 0), da_set_direct_mode(handle, 1));
    try std.testing.expectEqual(@as(c_int, 0), da_exec_set_model(handle, "agent:opencode", "opencode/x-free"));

    var order: ?*anyopaque = null;
    const rc = da_order_submit_async(handle, "crea ok.txt", "test", null, &order);
    if (rc != 0) {
        var why: [*:0]u8 = undefined;
        if (da_last_error(&why) == 0) {
            defer da_string_free(why);
            std.debug.print("T2d-D1 submit rechazado: {s}\n", .{why});
        }
    }
    try std.testing.expectEqual(@as(c_int, 0), rc);
    var done: c_int = 0;
    var plan_ok: c_int = 0;
    var i: usize = 0;
    while (i < 400 and done == 0) : (i += 1) {
        _ = da_order_plan_poll(handle, &done, &plan_ok);
        if (done == 0) Sleep(25);
    }
    try std.testing.expectEqual(@as(c_int, 1), done);

    const stmt = try st.db_conn.prepare("SELECT payload_json FROM events WHERE kind = 'directo_started_v1'");
    defer st.db_conn.finalize(stmt);
    try std.testing.expectEqual(@as(c_int, db.c.SQLITE_ROW), db.c.sqlite3_step(stmt));
    const payload = std.mem.span(@as([*:0]const u8, @ptrCast(db.c.sqlite3_column_text(stmt, 0))));
    var parsed = try std.json.parseFromSlice(std.json.Value, std.testing.allocator, payload, .{});
    defer parsed.deinit();
    // Antes: "normal" siempre (la foto de permisos descartaba el modo).
    try std.testing.expectEqualStrings("autonomous", parsed.value.object.get("permission_mode").?.string);
    try std.testing.expectEqualStrings("agent:opencode", parsed.value.object.get("provider").?.string);
}

test "c_api: una orden viva lista su created_at en segundos de epoca, no en ticks" {
    var handle: ?*anyopaque = null;
    _ = da_core_init(&handle, ":memory:");
    defer _ = da_core_shutdown(handle);

    var order: ?*anyopaque = null;
    _ = da_order_submit(handle, "crea un proyecto", "test", null, &order);

    var out: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_sessions_json(handle, &out));
    defer da_string_free(out);
    var parsed = try std.json.parseFromSlice(std.json.Value, std.testing.allocator, std.mem.span(out), .{});
    defer parsed.deinit();
    try std.testing.expect(parsed.value.array.items.len >= 1);
    const created = parsed.value.array.items[0].object.get("created_at").?.integer;
    // Antes: GetTickCount64() — milisegundos desde el arranque de Windows. La
    // barra lo leía como fecha de 1970 y mandaba la orden recién creada al
    // fondo de «Anteriores» (medido el 22-09 con la #754).
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const ahora = health.nowSeconds(st.db_conn);
    try std.testing.expect(created > ahora - 60 and created <= ahora + 60);
}

test "git credential input: formato correcto y rechazo de inyeccion" {
    const allocator = std.testing.allocator;

    const ok_in = try buildCredentialInput(allocator, "git.4stra.dev", "usuario", "t0k-123");
    defer allocator.free(ok_in);
    try std.testing.expectEqualStrings("protocol=https\nhost=git.4stra.dev\nusername=usuario\npassword=t0k-123\n\n", ok_in);

    // Inyeccion por salto de linea: un campo con \n crearia pares extra.
    try std.testing.expectError(error.InvalidField, buildCredentialInput(allocator, "git.4stra.dev", "u\npassword=x", "p"));
    try std.testing.expectError(error.InvalidField, buildCredentialInput(allocator, "git.4stra.dev", "u", "p\r\nhost=evil"));
    try std.testing.expectError(error.InvalidField, buildCredentialInput(allocator, "", "u", "p"));
    try std.testing.expectError(error.InvalidField, buildCredentialInput(allocator, "h", "u", ""));

    // Host con espacio o path no es un host.
    try std.testing.expectError(error.InvalidHost, buildCredentialInput(allocator, "bad host", "u", "p"));
    try std.testing.expectError(error.InvalidHost, buildCredentialInput(allocator, "evil.com/x", "u", "p"));

    // E3.37 — vectores ampliados del encargo T5-B.8:
    // · Credencial vacía: cualquier campo vacío muere (host, user, pass).
    try std.testing.expectError(error.InvalidField, buildCredentialInput(allocator, "h", "", "p"));
    // · Protocolo raro: el protocolo es literal `https`, no viene del form —
    //   `ssh://x` muere por el '/', y `ssh:x` queda como host literal inerte
    //   (credential fill jamás lo consultará como protocolo).
    try std.testing.expectError(error.InvalidHost, buildCredentialInput(allocator, "ssh://evil", "u", "p"));
    const ssh_in = try buildCredentialInput(allocator, "ssh:raro", "u", "p");
    defer allocator.free(ssh_in);
    try std.testing.expectEqualStrings("protocol=https\nhost=ssh:raro\nusername=u\npassword=p\n\n", ssh_in);
    // · Host con puerto: `:` es parte legítima del authority — se acepta.
    const port_in = try buildCredentialInput(allocator, "git.4stra.dev:8443", "u", "p");
    defer allocator.free(port_in);
    try std.testing.expectEqualStrings("protocol=https\nhost=git.4stra.dev:8443\nusername=u\npassword=p\n\n", port_in);
    // · Unicode: se acepta como host literal UTF-8 (queda bajo esa clave de
    //   store; `fill` sobre el host real jamás la devuelve — inerte, no
    //   inyección: los campos no pueden saltar de línea).
    const uni_in = try buildCredentialInput(allocator, "git\xd2\xbbub.example", "u", "p");
    defer allocator.free(uni_in);
    try std.testing.expect(std.mem.indexOf(u8, uni_in, "host=git") != null);
    // · Igual dentro de valores: `=` no rompe el parseo por líneas.
    const eq_in = try buildCredentialInput(allocator, "h", "user=x", "p");
    defer allocator.free(eq_in);
    try std.testing.expect(std.mem.indexOf(u8, eq_in, "username=user=x") != null);
}

test "E3.18-REG c_api: da_list_artifacts_json devuelve nombres y rutas unicode intactos (E-79)" {
    // Defecto la enumeración ANSI (FindFirstFileA) mutilaba los nombres
    // UTF-8 reales (0/40 intactos en la sonda E3.18) y hacía una RUTA con
    // unicode completamente inaccesible. Esta regresión ejerce la API del
    // producto — si la vía W vuelve a la ANSI, los asserts caen.
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}", .{tmp.sub_path});
    defer a.free(root);

    const GENERIC_WRITE: u32 = 0x40000000;
    const CREATE_ALWAYS: u32 = 2;

    // Caso 1: dir ASCII con NOMBRES unicode — la forma exacta del defecto.
    {
        const s2 = try std.fmt.allocPrint(a, "{s}/devagents-workspace", .{root});
        defer a.free(s2);
        const s2_w = try std.unicode.utf8ToUtf16LeAllocZ(a, s2);
        defer a.free(s2_w);
        try std.testing.expect(CreateDirectoryW(s2_w, null) != 0);
        const dir = try std.fmt.allocPrint(a, "{s}/orden-7777", .{s2});
        defer a.free(dir);
        const dir_w = try std.unicode.utf8ToUtf16LeAllocZ(a, dir);
        defer a.free(dir_w);
        try std.testing.expect(CreateDirectoryW(dir_w, null) != 0);

        const names = [_][]const u8{ "estadísticas-ñ.md", "报告-日.txt", "canción final.txt" };
        for (names) |n| {
            const p = try std.fmt.allocPrint(a, "{s}/{s}", .{ dir, n });
            defer a.free(p);
            const pw = try std.unicode.utf8ToUtf16LeAllocZ(a, p);
            defer a.free(pw);
            const h = CreateFileW(pw, GENERIC_WRITE, 0, null, CREATE_ALWAYS, 0x80, null);
            try std.testing.expect(h != windows.INVALID_HANDLE_VALUE);
            var written: u32 = 0;
            try std.testing.expect(WriteFile(h, "x", 1, &written, null) != 0);
            _ = CloseHandle(h);
        }

        var handle: ?*anyopaque = null;
        try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
        defer _ = da_core_shutdown(handle);
        const root_z = try a.dupeZ(u8, root);
        defer a.free(root_z);
        try std.testing.expectEqual(@as(c_int, 0), da_set_workspace_root(handle, root_z));
        defer _ = da_set_workspace_root(handle, null);

        var json: [*:0]u8 = undefined;
        try std.testing.expectEqual(@as(c_int, 0), da_list_artifacts_json(handle, 0, &json));
        defer da_string_free(json);
        const s = std.mem.span(json);
        for (names) |n| {
            try std.testing.expect(std.mem.indexOf(u8, s, n) != null);
        }
        try std.testing.expect(std.mem.indexOf(u8, s, "\"order_id\":7777") != null);
        // Ningún nombre llegó mutilado a la página ANSI ('?' o bytes sueltos
        // sin su UTF-8): si el nombre exacto aparece, la vía W lo preservó.
    }

    // Caso 2: la RAÍZ misma contiene unicode — la vía ANSI no podía ni
    // direccionarla (INVALID_HANDLE_VALUE en la sonda). Por la API debe listar.
    {
        const uroot = try std.fmt.allocPrint(a, "{s}/árbol-日", .{root});
        defer a.free(uroot);
        const uroot_w = try std.unicode.utf8ToUtf16LeAllocZ(a, uroot);
        defer a.free(uroot_w);
        try std.testing.expect(CreateDirectoryW(uroot_w, null) != 0);
        const us2 = try std.fmt.allocPrint(a, "{s}/devagents-workspace", .{uroot});
        defer a.free(us2);
        const us2_w = try std.unicode.utf8ToUtf16LeAllocZ(a, us2);
        defer a.free(us2_w);
        try std.testing.expect(CreateDirectoryW(us2_w, null) != 0);
        const udir = try std.fmt.allocPrint(a, "{s}/orden-8888", .{us2});
        defer a.free(udir);
        const udir_w = try std.unicode.utf8ToUtf16LeAllocZ(a, udir);
        defer a.free(udir_w);
        try std.testing.expect(CreateDirectoryW(udir_w, null) != 0);
        const fp = try std.fmt.allocPrint(a, "{s}/résumé ñ.txt", .{udir});
        defer a.free(fp);
        const fpw = try std.unicode.utf8ToUtf16LeAllocZ(a, fp);
        defer a.free(fpw);
        const h = CreateFileW(fpw, GENERIC_WRITE, 0, null, CREATE_ALWAYS, 0x80, null);
        try std.testing.expect(h != windows.INVALID_HANDLE_VALUE);
        _ = CloseHandle(h);

        var handle: ?*anyopaque = null;
        try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
        defer _ = da_core_shutdown(handle);
        const uroot_z = try a.dupeZ(u8, uroot);
        defer a.free(uroot_z);
        try std.testing.expectEqual(@as(c_int, 0), da_set_workspace_root(handle, uroot_z));
        defer _ = da_set_workspace_root(handle, null);

        var json: [*:0]u8 = undefined;
        try std.testing.expectEqual(@as(c_int, 0), da_list_artifacts_json(handle, 0, &json));
        defer da_string_free(json);
        const s = std.mem.span(json);
        try std.testing.expect(std.mem.indexOf(u8, s, "résumé ñ.txt") != null);
        try std.testing.expect(std.mem.indexOf(u8, s, "\"order_id\":8888") != null);
    }
}

test "E5.15 embeddings_config: roundtrip set/get y validacion" {
    var handle: ?*anyopaque = null;
    _ = da_core_init(&handle, ":memory:");
    defer _ = da_core_shutdown(handle);

    var out: ?[*:0]u8 = null;
    try std.testing.expectEqual(@as(c_int, 0), da_embeddings_config_json(handle, &out));
    const first = std.mem.span(out.?);
    defer da_string_free(out.?);
    try std.testing.expect(std.mem.indexOf(u8, first, "\"enabled\":false") != null);

    // set completo + get refleja
    try std.testing.expectEqual(@as(c_int, 0), da_embeddings_config_set(handle, "{\"enabled\":true,\"provider\":\"EmbProv\",\"model\":\"emb-v1\"}"));
    var out2: ?[*:0]u8 = null;
    try std.testing.expectEqual(@as(c_int, 0), da_embeddings_config_json(handle, &out2));
    const second = std.mem.span(out2.?);
    defer da_string_free(out2.?);
    try std.testing.expect(std.mem.indexOf(u8, second, "\"enabled\":true") != null);
    try std.testing.expect(std.mem.indexOf(u8, second, "\"provider\":\"EmbProv\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, second, "\"model\":\"emb-v1\"") != null);

    // set parcial conserva provider/model
    try std.testing.expectEqual(@as(c_int, 0), da_embeddings_config_set(handle, "{\"enabled\":false}"));
    var out3: ?[*:0]u8 = null;
    try std.testing.expectEqual(@as(c_int, 0), da_embeddings_config_json(handle, &out3));
    const third = std.mem.span(out3.?);
    defer da_string_free(out3.?);
    try std.testing.expect(std.mem.indexOf(u8, third, "\"enabled\":false") != null);
    try std.testing.expect(std.mem.indexOf(u8, third, "\"provider\":\"EmbProv\"") != null);

    // validaciones
    try std.testing.expect(da_embeddings_config_set(handle, "{\"enabled\":\"yes\"}") != 0); // enabled no bool
    try std.testing.expect(da_embeddings_config_set(handle, "{broken") != 0); // JSON roto
    try std.testing.expect(da_embeddings_config_json(handle, null) != 0);
}

test "E5.15 resolveEmbedder: notas honestas por eslabon ausente" {
    var handle: ?*anyopaque = null;
    _ = da_core_init(&handle, ":memory:");
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    // resolveEmbedder dupea sobre el allocator recibido (en produccion es el
    // arena del CoreState) — el test usa un arena propio para no "leakear".
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    var ctx: *EmbedderCtx = undefined;

    // sin settings -> disabled
    try std.testing.expectEqualStrings("disabled", resolveEmbedder(st, a, &ctx).?);

    // enabled pero provider no esta en catalogo -> provider_missing
    _ = da_embeddings_config_set(handle, "{\"enabled\":true,\"provider\":\"NoExiste\",\"model\":\"m\"}");
    try std.testing.expectEqualStrings("provider_missing", resolveEmbedder(st, a, &ctx).?);

    // provider openai sin clave -> no_key
    try st.catalog.db.exec("INSERT OR IGNORE INTO providers (name, base_url, api_style, is_free_tier) VALUES ('EmbProv', 'https://emb.invalid/v1', 'openai', 1)");
    _ = da_embeddings_config_set(handle, "{\"provider\":\"EmbProv\"}");
    try std.testing.expectEqualStrings("no_key", resolveEmbedder(st, a, &ctx).?);

    // provider cohere (soportado por la capa de compatibilidad OpenAI) sin
    // clave -> no_key: el estilo ya no es el eslabon que falta.
    try st.catalog.db.exec("INSERT OR IGNORE INTO providers (name, base_url, api_style, is_free_tier) VALUES ('EmbCohere', 'https://c.invalid', 'cohere', 1)");
    _ = da_embeddings_config_set(handle, "{\"provider\":\"EmbCohere\"}");
    try std.testing.expectEqualStrings("no_key", resolveEmbedder(st, a, &ctx).?);

    // provider con api_style sin contrato de embeddings -> unsupported_style
    try st.catalog.db.exec("INSERT OR IGNORE INTO providers (name, base_url, api_style, is_free_tier) VALUES ('EmbAnth', 'https://a.invalid', 'anthropic', 1)");
    _ = da_embeddings_config_set(handle, "{\"provider\":\"EmbAnth\"}");
    try std.testing.expectEqualStrings("unsupported_style", resolveEmbedder(st, a, &ctx).?);

    // enabled=false -> disabled aunque el resto este bien
    _ = da_embeddings_config_set(handle, "{\"enabled\":false}");
    try std.testing.expectEqualStrings("disabled", resolveEmbedder(st, a, &ctx).?);
}

test "E5.15 da_repo_search: mode semantic sin embedder -> bm25 + status honesto" {
    var handle: ?*anyopaque = null;
