test "E5.24 C API provider models expose measured vision with absent and prefixed snapshots" {
    const a = std.testing.allocator;
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    try st.catalog.db.exec("INSERT INTO models (provider_id,model_name,is_free,available) SELECT id,'vision-fixture',1,1 FROM providers WHERE name='OpenRouter'");
    for (0..3) |phase| {
        if (phase == 1) try discovery_persistence.persistCapabilityEvidence(st.catalog.db, "OpenRouter", "vision-fixture", "openai", "fixture://vision", .{ .vision = "yes" }, 1800000000);
        if (phase == 2) try st.catalog.db.exec("UPDATE discovery_snapshots_v2 SET model_id='OpenRouter/vision-fixture' WHERE provider='OpenRouter' AND model_id='vision-fixture'");
        var json: [*:0]u8 = undefined;
        try std.testing.expectEqual(@as(c_int, 0), da_providers_list_json(handle, &json));
        defer da_string_free(json);
        var parsed = try std.json.parseFromSlice(std.json.Value, a, std.mem.span(json), .{});
        defer parsed.deinit();
        var found = false;
        for (parsed.value.array.items) |provider| {
            try std.testing.expect(provider.object.get("cap_vision_status") == null);
            if (!std.mem.eql(u8, provider.object.get("name").?.string, "OpenRouter")) continue;
            for (provider.object.get("models").?.array.items) |model| {
                if (!std.mem.eql(u8, model.object.get("name").?.string, "vision-fixture")) continue;
                found = true;
                try std.testing.expectEqualStrings(if (phase == 0) "not_probed" else "yes", model.object.get("cap_vision_status").?.string);
                try std.testing.expectEqualStrings(if (phase == 0) "not_probed" else "live_probe", model.object.get("cap_vision_provenance").?.string);
                try std.testing.expectEqualStrings(if (phase == 0) "not_probed" else "1800000000", model.object.get("cap_vision_updated_at").?.string);
            }
        }
        try std.testing.expect(found);
    }
    try st.catalog.db.exec("DROP TABLE discovery_snapshots_v2");
    var failed_json: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, @intFromEnum(DaResult.internal)), da_providers_list_json(handle, &failed_json));
}

