    try std.testing.expectEqual(@as(?[]u8, null), try issueStoreAuth(st, a, .github, "https://foreign.invalid"));
    try std.testing.expectError(error.CredentialHostMismatch, issueStoreAuth(st, a, .github, "https://enterprise.invalid/"));
    try std.testing.expectEqual(@as(?[]u8, null), try issueStoreAuth(st, a, .gitlab, "https://enterprise.invalid"));
    const hosts = try configuredForgeHosts(st, a);
    defer freeForgeHosts(a, hosts);
    try std.testing.expectEqual(@as(usize, 1), hosts.len);
    try std.testing.expectEqualStrings("enterprise.invalid", hosts[0].host);
    try std.testing.expectEqual(providers.github.Forge.github, hosts[0].forge);
    const callback = (try forgeStoreAuth(a, .github, "enterprise.invalid", st)).?;
    defer a.free(callback);
    try std.testing.expectEqualStrings(auth, callback);
    try std.testing.expectError(error.InvalidContext, forgeStoreAuth(a, .github, "enterprise.invalid", null));
    try std.testing.expectEqual(@as(c_int, 0), da_provider_add(handle, "forge:linear:api.linear.app", "issue_linear", "https://api.linear.app"));
    try std.testing.expectEqual(@as(c_int, 0), da_key_add(handle, "forge:linear:api.linear.app", "test", "synthetic-linear-only"));
    const linear_auth = (try issueStoreAuth(st, a, .linear, "https://api.linear.app")).?;
    defer a.free(linear_auth);
    try std.testing.expectEqualStrings("synthetic-linear-only", linear_auth);
    try std.testing.expectEqual(@as(c_int, 0), da_provider_add(handle, "forge:jira:acme.atlassian.net", "issue_jira", "https://acme.atlassian.net"));
    try std.testing.expectEqual(@as(c_int, 0), da_key_add(handle, "forge:jira:acme.atlassian.net", "test", "test@example.invalid:synthetic-jira-only"));
    const jira_auth = (try issueStoreAuth(st, a, .jira, "https://acme.atlassian.net")).?;
    defer a.free(jira_auth);
    const expected = try providers.gitea.basicAuthHeader(a, "test@example.invalid", "synthetic-jira-only");
    defer a.free(expected);
    try std.testing.expectEqualStrings(expected, jira_auth);
