const ForgeShutdownObserver = struct {
    state: *CoreState,
    ready: std.atomic.Value(bool) = std.atomic.Value(bool).init(false),
    catalog_alive: std.atomic.Value(bool) = std.atomic.Value(bool).init(false),

    fn run(self: *ForgeShutdownObserver) void {
        self.ready.store(true, .release);
        while (!self.state.ship_poll_stop.load(.acquire)) Sleep(1);
        self.catalog_alive.store(self.state.catalog.db.db != null, .release);
    }
};

test "E5.26 forge poller is joined before its catalog closes" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    st.ship_poll_stop.store(true, .release);
    if (st.ship_poll_thread) |thread| thread.join();
    st.ship_poll_thread = null;
    st.ship_poll_stop.store(false, .release);
    var observer = ForgeShutdownObserver{ .state = st };
    st.ship_poll_thread = try std.Thread.spawn(.{}, ForgeShutdownObserver.run, .{&observer});
    while (!observer.ready.load(.acquire)) Sleep(1);
    try std.testing.expectEqual(@as(c_int, 0), da_core_shutdown(handle));
    try std.testing.expect(observer.catalog_alive.load(.acquire));
}

