var sec2_clone_calls: usize = 0;
var sec2_clone_separator: bool = false;
var sec2_clone_target_buf: [4096]u8 = undefined;
var sec2_clone_target_len: usize = 0;
fn sec2CloneCapture(allocator: std.mem.Allocator, argv: []const []const u8, _: ?[]const u8) anyerror!providers.github.CmdCapture {
    sec2_clone_calls += 1;
    sec2_clone_separator = argv.len >= 4 and std.mem.eql(u8, argv[1], "clone") and std.mem.eql(u8, argv[2], "--");
    // argv: git clone -- <url> <target>; H14 replica el destino real.
    if (argv.len >= 5) {
        const copied = @min(argv[4].len, sec2_clone_target_buf.len);
        @memcpy(sec2_clone_target_buf[0..copied], argv[4][0..copied]);
        sec2_clone_target_len = copied;
    }
    return .{ .exit_code = 0, .stdout = try allocator.dupe(u8, ""), .stderr = try allocator.dupe(u8, "") };
}

