test "CK-SEG-012 H14 MCP-facing relative clone targets resolve against the workspace root" {
    if (@import("builtin").os.tag != .windows) return @import("platform.zig").skip("T9: la prueba usa API de Windows (junctions, ACL o SID); omitida en Linux");
    const a = std.testing.allocator;
    var threaded = std.Io.Threaded.init(a, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var tmp = std.testing.tmpDir(.{});
    const project = try isolatedTestPath(&tmp, "sec2-h14-project");
    defer a.free(project);
    const base = try std.fmt.allocPrint(a, "{s}" ++ std.fs.path.sep_str ++ "devagents-workspace", .{project});
    defer a.free(base);
    try std.Io.Dir.cwd().createDirPath(io, base);
    const junction = try std.fmt.allocPrint(a, "{s}" ++ std.fs.path.sep_str ++ "sec2-h14-j", .{base});
    defer a.free(junction);
    const junction_w = try std.unicode.utf8ToUtf16LeAllocZ(a, junction);
    defer a.free(junction_w);
    const Remove = struct {
        extern "kernel32" fn RemoveDirectoryW([*:0]const u16) callconv(.winapi) c_int;
    };
    // La junction se quita explicitamente al final, FUERA de cualquier defer:
    // un `return` dentro de `defer` no compila en Zig 0.16. Hasta que se
    // retire, no se ejecuta ningun borrado recursivo (deleteTree/tmp.cleanup
    // recorrerian el destino fuera de la raiz).
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle));
    defer workspace.setWorkspaceRoot(workspace.WORKSPACE_ROOT);
    try std.testing.expectEqual(@as(c_int, 0), da_set_workspace_root(handle, project));
    try std.testing.expectEqual(@as(c_int, 0), da_set_mcp_surface(handle));
    // Destino relativo: se resuelve contra la raiz (base), no contra el cwd
    // del proceso (aqui el directorio temporario de ejecucion de pruebas).
    st.gh_capture_fn = sec2CloneCapture;
    sec2_clone_calls = 0;
    sec2_clone_target_len = 0;
    try std.testing.expectEqual(@as(c_int, 0), da_repo_clone(handle, "https://github.com/o/r.git", "sec2-h14-rel"));
    try std.testing.expectEqual(@as(usize, 1), sec2_clone_calls);
    const expected_target = try std.fmt.allocPrint(a, "{s}" ++ std.fs.path.sep_str ++ "sec2-h14-rel", .{base});
    defer a.free(expected_target);
    try std.testing.expect(sec2_clone_target_len == expected_target.len);
    try std.testing.expect(std.mem.eql(u8, sec2_clone_target_buf[0..sec2_clone_target_len], expected_target));
    // Junction bajo la raiz que sale fuera: la ruta RESUELTA (base\sec2-h14-j\
    // clonado) atraviesa un reparse point, el clon se rechaza sin llamar a git.
    var mk = try providers.github.runCmdCaptureWin32(a, &.{ "cmd.exe", "/d", "/c", "mklink", "/J", junction, project }, null);
    defer mk.deinit(a);
    try std.testing.expectEqual(@as(u32, 0), mk.exit_code);
    try std.testing.expect(da_repo_clone(handle, "https://github.com/o/r.git", "sec2-h14-j\\clonado") != 0);
    try std.testing.expectEqual(@as(usize, 1), sec2_clone_calls);
    // Retirada explicita ANTES de decidir el borrado. Si RemoveDirectoryW
    // falla, la prueba falla con mensaje claro y NO se llama a deleteTree
    // sobre el temporal que contiene la junction: se deja el temporal y se
    // dice en el mensaje.
    if (Remove.RemoveDirectoryW(junction_w.ptr) == 0) {
        std.debug.print(
            "CK-SEG-012 H14: RemoveDirectoryW fallo al retirar la junction {s}; prueba fallida; temporal conservado en {s} (deleteTree no se ejecuta)\n",
            .{ junction, project },
        );
        return error.RemoveJunctionFailed;
    }
    // Junction ya retirada: los borrados recursivos son seguros. Defers
    // registrados aqui (sin condicion): LIFO, deleteTree y luego tmp.cleanup.
    defer tmp.cleanup();
    defer std.Io.Dir.cwd().deleteTree(io, project) catch |e| std.debug.print("SEC2 H14 cleanup: {s}\n", .{@errorName(e)});
}

test "SEC2 MCP surface clones only inside the workspace root" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle));
    st.gh_capture_fn = sec2CloneCapture;
    try std.testing.expectEqual(@as(c_int, 0), da_set_mcp_surface(handle));
    sec2_clone_calls = 0;
    // H14: el destino relativo se resuelve contra la raiz y la comprobación
    // corre sobre la ruta resuelta (no contra el cwd). Los escapes siguen
    // rechazados sin llamar a git.
    for ([_][*:0]const u8{ (if (@import("builtin").os.tag == .windows) "C:\\Windows\\Temp\\sec2-clone" else "/devagents-outside/sec2-clone"), ".." ++ std.fs.path.sep_str ++ ".." ++ std.fs.path.sep_str ++ "sec2-clone" }) |target| {
        try std.testing.expect(da_repo_clone(handle, "https://github.com/o/r.git", target) != 0);
    }
    try std.testing.expectEqual(@as(usize, 0), sec2_clone_calls);
    // Relativo permitido: <raiz>\sec2-clone, y git recibe la ruta absoluta.
    sec2_clone_target_len = 0;
    try std.testing.expectEqual(@as(c_int, 0), da_repo_clone(handle, "https://github.com/o/r.git", "sec2-clone"));
    try std.testing.expectEqual(@as(usize, 1), sec2_clone_calls);
    var root_buf: [4096]u8 = undefined;
    const root = workspace.effectiveRoot(&root_buf);
    try std.testing.expect(std.mem.startsWith(u8, sec2_clone_target_buf[0..sec2_clone_target_len], root));
    // Absoluto dentro de la raiz: permitido.
    const inside = try std.fmt.allocPrintSentinel(std.testing.allocator, "{s}" ++ std.fs.path.sep_str ++ "sec2-clone-ok", .{root}, 0);
    defer std.testing.allocator.free(inside);
    try std.testing.expectEqual(@as(c_int, 0), da_repo_clone(handle, "https://github.com/o/r.git", inside.ptr));
    try std.testing.expectEqual(@as(usize, 2), sec2_clone_calls);
}

test "SEC2 MCP surface can only harden the permission configuration" {
    var ui: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&ui, ":memory:"));
    defer _ = da_core_shutdown(ui);
    // Control: la cabina (sin superficie MCP) conserva el control completo.
    try std.testing.expectEqual(@as(c_int, 0), da_set_permission_config(ui, "{\"mode\":\"bypass\",\"allow\":[\"git\"]}"));

    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle));
    try std.testing.expectEqual(@as(c_int, 0), da_set_mcp_surface(handle));
    for ([_][*:0]const u8{
        "{\"mode\":\"bypass\"}",
        "{\"mode\":\"autonomous\"}",
        "{\"mode\":\"accept_edits\"}",
        "{\"mode\":\"normal\",\"allow\":[\"python\"]}",
        "{\"allow\":[\"git\"]}",
        "{\"mode\":7}",
    }) |config| {
        try std.testing.expect(da_set_permission_config(handle, config) != 0);
    }
    try std.testing.expectEqual(superagent.executor.PermissionMode.normal, st.perm_mode);
    try std.testing.expectEqual(@as(usize, 0), st.perm_allow.items.len);
    // Endurecer si: modo normal, allow vacia y denylist ampliada.
    try std.testing.expectEqual(@as(c_int, 0), da_set_permission_config(handle, "{\"mode\":\"normal\",\"allow\":[],\"deny\":[\"rm\"]}"));
    try std.testing.expectEqual(@as(c_int, 0), da_set_permission_config(handle, "{\"deny\":[\"rm\",\"del\"]}"));
    // Quitar una entrada de la denylist relaja y se rechaza.
    try std.testing.expect(da_set_permission_config(handle, "{\"deny\":[\"del\"]}") != 0);
    try std.testing.expect(da_set_permission_config(handle, "{\"deny\":[]}") != 0);
    try std.testing.expectEqual(@as(usize, 2), st.perm_deny.items.len);
}

