test "SEC2 MCP client cannot launch an arbitrary process through mcp_connect" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const a = std.testing.allocator;
    const dir = try tmp.dir.realPathFileAlloc(std.testing.io, ".", a);
    defer a.free(dir);
    const marker = try std.fmt.allocPrint(a, "{s}" ++ std.fs.path.sep_str ++ "sec2-mcp-connect-marker", .{dir});
    defer a.free(marker);
    const script = try std.fmt.allocPrint(a, "Set-Content -LiteralPath '{s}' -Value pwned", .{marker});
    defer a.free(script);
    const argv_json = try std.json.Stringify.valueAlloc(a, [_][]const u8{ "powershell.exe", "-NoProfile", "-Command", script }, .{});
    defer a.free(argv_json);
    const argv_z = try a.dupeZ(u8, argv_json);
    defer a.free(argv_z);

    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle));
    try std.testing.expectEqual(@as(c_int, 0), da_set_mcp_surface(handle));
    try std.testing.expect(da_mcp_connect(handle, argv_z.ptr, null, 2000) != 0);
    var message: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_last_error(&message));
    defer da_string_free(message);
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(message), "clientes MCP") != null);
    try std.testing.expect(!st.od_mcp_state.connected);
    tmp.dir.access(std.testing.io, "sec2-mcp-connect-marker", .{}) catch |e| {
        try std.testing.expect(e == error.FileNotFound);
        return;
    };
    return error.TestUnexpectedResult;
}

const Sec2R6Fixture = struct { order_id: i64, approval_id: i64 };

/// Orden sintetica en awaiting_approval con una tarjeta pendiente (misma forma que
/// el test E5.30 de aprobacion remota).
fn sec2R6Fixture(handle: ?*anyopaque, st: *CoreState, project: [*:0]const u8) !Sec2R6Fixture {
    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "crea modulo de logging", project, null, &order));
    const id = orderHandleToId(order).?;
    const rec = findOrder(st, id).?;
    rec.status = .awaiting_approval;
    try st.db_conn.exec("UPDATE orders SET status='awaiting_approval'");
    const aa = st.arena.child_allocator;
    const aid = try insertApprovalToDb(st.db_conn, "t1", "Aprobacion sintetica R6", 1, null, null, null, id);
    try st.approvals.append(aa, .{ .id = aid, .task_id = try aa.dupe(u8, "t1"), .description = try aa.dupe(u8, "Aprobacion sintetica R6"), .approved = false, .resolved = false, .order_id = id });
    return .{ .order_id = id, .approval_id = aid };
}

test "SEC2 R6 H1 MCP-surface core rejects every remote decision route and da_approval_resolve" {
    const allocator = std.testing.allocator;
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle));
    const fixture = try sec2R6Fixture(handle, st, "sec2-r6-h1");
    const rec = findOrder(st, fixture.order_id).?;
    try std.testing.expectEqual(@as(c_int, 0), da_set_mcp_surface(handle));
    const approval_path = try std.fmt.allocPrint(allocator, "/api/approvals/{d}", .{fixture.approval_id});
    defer allocator.free(approval_path);
    const approve_path = try std.fmt.allocPrint(allocator, "/api/orders/{d}/approve", .{fixture.order_id});
    defer allocator.free(approve_path);
    const cancel_path = try std.fmt.allocPrint(allocator, "/api/orders/{d}/cancel", .{fixture.order_id});
    defer allocator.free(cancel_path);
    const restore_path = try std.fmt.allocPrint(allocator, "/api/orders/{d}/workspace/restore_permissions", .{fixture.order_id});
    defer allocator.free(restore_path);
    // Cadena de H1: el bearer de remote_start permite POST {"approved":true}.
    for ([_]struct { path: []const u8, body: []const u8 }{
        .{ .path = approval_path, .body = "{\"approved\":true}" },
        .{ .path = approval_path, .body = "{\"approved\":false}" },
        .{ .path = approve_path, .body = "{}" },
        .{ .path = cancel_path, .body = "{}" },
        .{ .path = restore_path, .body = "{\"explicit\":true}" },
    }) |request| {
        const body = try expectRemote(handle, "POST", request.path, request.body, 403);
        defer allocator.free(body);
        try std.testing.expect(std.mem.indexOf(u8, body, "solo lectura") != null);
    }
    // Nada cambio: ni la tarjeta, ni la orden.
    try std.testing.expect(!st.approvals.items[0].resolved);
    try std.testing.expectEqual(superagent.OrderStatus.awaiting_approval, rec.status);
    // El C-ABI tambien se cierra (cualquier otra via que llegue al nucleo MCP).
    try std.testing.expect(da_approval_resolve(handle, fixture.approval_id, 1) != 0);
    try std.testing.expect(da_approval_resolve_scoped(handle, fixture.approval_id, 1, 0) != 0);
    var message: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_last_error(&message));
    defer da_string_free(message);
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(message), "cabina") != null);
    try std.testing.expect(!st.approvals.items[0].resolved);
    // La lectura sigue disponible: el servidor remoto desde MCP es de solo lectura.
    for ([_][]const u8{ "/api/orders", "/api/approvals" }) |path| {
        const body = try expectRemote(handle, "GET", path, "", 200);
        allocator.free(body);
    }
}

