test "SEC2 R7 N1 MCP-surface core can only lower the paid budget; the cabina can raise it" {
    var ui: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&ui, ":memory:"));
    defer _ = da_core_shutdown(ui);
    const ui_state: *CoreState = @ptrCast(@alignCast(ui));
    // Control: la cabina (sin superficie MCP) puede subir y bajar.
    try std.testing.expectEqual(@as(c_int, 0), da_budget_set_authorized(ui, 10));
    try std.testing.expectEqual(@as(u64, 10), spend_budget.estado(ui_state.catalog.db).autorizadas);

    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle));
    try std.testing.expectEqual(@as(c_int, 0), da_set_mcp_surface(handle));
    // Sin cupo previo: autorizar cualquier gasto por MCP se rechaza y no persiste.
    try std.testing.expect(da_budget_set_authorized(handle, 5) != 0);
    try std.testing.expectEqual(@as(u64, 0), spend_budget.estado(st.catalog.db).autorizadas);
    var message: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_last_error(&message));
    defer da_string_free(message);
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(message), "cabina") != null);
    // La cabina fija un cupo (misma base de catalogo): MCP puede bajarlo, no subirlo.
    try spend_budget.autorizar(st.catalog.db, 10);
    try std.testing.expect(da_budget_set_authorized(handle, 11) != 0);
    try std.testing.expectEqual(@as(u64, 10), spend_budget.estado(st.catalog.db).autorizadas);
    try std.testing.expectEqual(@as(c_int, 0), da_budget_set_authorized(handle, 10));
    try std.testing.expectEqual(@as(c_int, 0), da_budget_set_authorized(handle, 3));
    try std.testing.expectEqual(@as(u64, 3), spend_budget.estado(st.catalog.db).autorizadas);
    // Volver a subir tras bajar tambien se rechaza.
    try std.testing.expect(da_budget_set_authorized(handle, 4) != 0);
    try std.testing.expectEqual(@as(c_int, 0), da_budget_set_authorized(handle, 0));
    try std.testing.expectEqual(@as(u64, 0), spend_budget.estado(st.catalog.db).autorizadas);
    try std.testing.expect(da_budget_set_authorized(handle, 1) != 0);
}

test "CK-SEG-012 H7 MCP external_limits_set only lowers limits and cannot remove the cap; the cabina keeps full control" {
    var ui: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&ui, ":memory:"));
    defer _ = da_core_shutdown(ui);
    const base = "{\"task_timeout_ms\":1000,\"task_max_turns\":10,\"order_timeout_ms\":2000,\"order_max_turns\":20}";
    // Control: la cabina sube, baja y pone 0 sin restriccion adicional.
    try std.testing.expectEqual(@as(c_int, 0), da_external_limits_set(ui, base));
    try std.testing.expectEqual(@as(c_int, 0), da_external_limits_set(ui, "{\"task_timeout_ms\":2000}"));
    try std.testing.expectEqual(@as(c_int, 0), da_external_limits_set(ui, "{\"task_timeout_ms\":0}"));
    try std.testing.expectEqual(@as(c_int, 0), da_external_limits_set(ui, base));

    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    try std.testing.expectEqual(@as(c_int, 0), da_external_limits_set(handle, base));
    try std.testing.expectEqual(@as(c_int, 0), da_set_mcp_surface(handle));
    // Subir cualquier eje o quitar un tope vigente se rechaza y no persiste.
    for ([_][*:0]const u8{
        "{\"task_timeout_ms\":1001}",
        "{\"task_max_turns\":11}",
        "{\"order_timeout_ms\":2001}",
        "{\"order_max_turns\":21}",
        "{\"task_timeout_ms\":0}",
        "{\"order_max_turns\":0}",
    }) |body| {
        try std.testing.expect(da_external_limits_set(handle, body) != 0);
        var message: [*:0]u8 = undefined;
        try std.testing.expectEqual(@as(c_int, 0), da_last_error(&message));
        defer da_string_free(message);
        try std.testing.expect(std.mem.indexOf(u8, std.mem.span(message), "cabina") != null);
    }
    var limits: ?[*:0]const u8 = null;
    try std.testing.expectEqual(@as(c_int, 0), da_external_limits_json(handle, &limits));
    // 10-nov (A3): la respuesta lleva también la herencia de instrucciones.
    const with_inherit = base[0 .. base.len - 1] ++ ",\"inherit_personal_context\":false}";
    try std.testing.expectEqualStrings(with_inherit, std.mem.span(limits.?));
    da_string_free(@constCast(limits.?));
    // MCP puede apagar la herencia, nunca encenderla.
    try std.testing.expect(da_external_limits_set(handle, "{\"inherit_personal_context\":true}") != 0);
    try std.testing.expectEqual(@as(c_int, 0), da_external_limits_set(handle, "{\"inherit_personal_context\":false}"));
    try std.testing.expect(da_external_limits_set(handle, "{\"inherit_personal_context\":\"si\"}") != 0);
    // Bajar si se acepta.
    try std.testing.expectEqual(@as(c_int, 0), da_external_limits_set(handle, "{\"task_timeout_ms\":500,\"task_max_turns\":5}"));
    try std.testing.expectEqual(@as(c_int, 0), da_external_limits_json(handle, &limits));
    defer if (limits) |v| da_string_free(@constCast(v));
    try std.testing.expectEqualStrings("{\"task_timeout_ms\":500,\"task_max_turns\":5,\"order_timeout_ms\":2000,\"order_max_turns\":20,\"inherit_personal_context\":false}", std.mem.span(limits.?));
}

