}

test "CK-SEG-012 H7 MCP external_paths_set can only remove or keep cabin-registered paths; the cabina keeps full control" {
    const seeded = "{\"codex\":\"C:/Tools/codex/codex.exe\"}";
    var ui: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&ui, ":memory:"));
    defer _ = da_core_shutdown(ui);
    const ui_state: *CoreState = @ptrCast(@alignCast(ui));
    // Control: la cabina vacia el registro.
    try ui_state.catalog.db.exec(
        \\UPDATE settings SET value='{"codex":"C:/Tools/codex/codex.exe"}' WHERE key='external_agent_paths'
    );
    try std.testing.expectEqual(@as(c_int, 0), da_external_paths_set(ui, "{}"));
    // Control: una ruta nueva no recibe la guardia MCP; la decide su verificacion CLI.
    try ui_state.catalog.db.exec(
        \\UPDATE settings SET value='{"codex":"C:/Tools/codex/codex.exe"}' WHERE key='external_agent_paths'
    );
    try std.testing.expect(da_external_paths_set(ui, "{\"codex\":\"C:/Other/codex.exe\"}") != 0);
    var message: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_last_error(&message));
    defer da_string_free(message);
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(message), "cabina") == null);
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(message), "CLI") != null);

    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle));
    try st.catalog.db.exec(
        \\UPDATE settings SET value='{"codex":"C:/Tools/codex/codex.exe"}' WHERE key='external_agent_paths'
    );
    try std.testing.expectEqual(@as(c_int, 0), da_set_mcp_surface(handle));
    // Quitar entradas si se permite.
    try std.testing.expectEqual(@as(c_int, 0), da_external_paths_set(handle, "{}"));
    try st.catalog.db.exec(
        \\UPDATE settings SET value='{"codex":"C:/Tools/codex/codex.exe"}' WHERE key='external_agent_paths'
    );
    // Conservar exactamente lo registrado si se permite (sin re-verificar por MCP).
    try std.testing.expectEqual(@as(c_int, 0), da_external_paths_set(handle, seeded));
    // Cambiar la ruta o agregar otra clave se rechaza con mensaje de cabina y no persiste.
    try std.testing.expect(da_external_paths_set(handle, "{\"codex\":\"C:/Other/codex.exe\"}") != 0);
    var mcp_message: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_last_error(&mcp_message));
    defer da_string_free(mcp_message);
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(mcp_message), "cabina") != null);
    try std.testing.expect(da_external_paths_set(handle, "{\"codex\":\"C:/Tools/codex/codex.exe\",\"opencode\":\"C:/Tools/opencode/opencode.exe\"}") != 0);
    var out: ?[*:0]const u8 = null;
    try std.testing.expectEqual(@as(c_int, 0), da_external_paths_json(handle, &out));
    defer if (out) |v| da_string_free(@constCast(v));
    try std.testing.expectEqualStrings(seeded, std.mem.span(out.?));
}

/// H7 r4: filas vivas en la caché de agentes externos (-1 si falla).
fn seg012CacheRows(st: *CoreState) c_int {
    const stmt = st.catalog.db.prepare("SELECT COUNT(*) FROM external_agent_cache") catch return -1;
    defer st.catalog.db.finalize(stmt);
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) return -1;
    return db.c.sqlite3_column_int(stmt, 0);
}

test "CK-SEG-012 H7 external_paths_set invalidates the agent cache inside one transaction" {
    const seeded = "{\"codex\":\"C:/Tools/codex/codex.exe\"}";
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle));
    try st.catalog.db.exec("UPDATE settings SET value='" ++ seeded ++ "' WHERE key='external_agent_paths'");
    try st.catalog.db.exec("INSERT INTO external_agent_cache(id,payload_json,detected_at) VALUES(1,'[]',1000)");
    try std.testing.expectEqual(@as(c_int, 0), da_set_mcp_surface(handle));
    // Un trigger que hace fallar exactamente la invalidación de la caché.
    try st.catalog.db.exec(
        \\CREATE TRIGGER seg012_cache_delete_fails BEFORE DELETE ON external_agent_cache
        \\BEGIN SELECT RAISE(ABORT,'cache-blocked'); END
    );

    const readSetting = struct {
        fn call(core: *CoreState) ![]const u8 {
            const stmt = try core.catalog.db.prepare("SELECT value FROM settings WHERE key='external_agent_paths'");
            defer core.catalog.db.finalize(stmt);
            if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) return error.SettingMissing;
            const ptr = db.c.sqlite3_column_text(stmt, 0);
            const len: usize = @intCast(db.c.sqlite3_column_bytes(stmt, 0));
            const copy = try core.arena.child_allocator.alloc(u8, len);
            @memcpy(copy, ptr[0..len]);
            return copy;
        }
    };
    // La invalidación falla: la reforma tampoco puede quedar a medias.
    try std.testing.expect(da_external_paths_set(handle, "{}") != 0);
    const after_fail = try readSetting.call(st);
    defer st.arena.child_allocator.free(after_fail);
    try std.testing.expectEqualStrings(seeded, after_fail);
    try std.testing.expectEqual(@as(c_int, 1), seg012CacheRows(st));

    // Sin el trigger, la misma operación es atómica y completa.
    try st.catalog.db.exec("DROP TRIGGER seg012_cache_delete_fails");
    try std.testing.expectEqual(@as(c_int, 0), da_external_paths_set(handle, "{}"));
    const after_ok = try readSetting.call(st);
    defer st.arena.child_allocator.free(after_ok);
    try std.testing.expectEqualStrings("{}", after_ok);
    try std.testing.expectEqual(@as(c_int, 0), seg012CacheRows(st));
}

test "CK-SEG-012 H7 MCP mount_add is confined to cabin-registered mounts; the cabina registers new roots" {
    const allocator = std.testing.allocator;
    var threaded = std.Io.Threaded.init(allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const base = try tmp.dir.realPathFileAlloc(io, ".", allocator);
    defer allocator.free(base);
    const registered = try std.fmt.allocPrint(allocator, "{s}" ++ std.fs.path.sep_str ++ "registered", .{base});
    defer allocator.free(registered);
    const sub = try std.fmt.allocPrint(allocator, "{s}" ++ std.fs.path.sep_str ++ "sub", .{registered});
    defer allocator.free(sub);
    const outside = try std.fmt.allocPrint(allocator, "{s}" ++ std.fs.path.sep_str ++ "outside", .{base});
    defer allocator.free(outside);
    try std.Io.Dir.cwd().createDirPath(io, registered);
    try std.Io.Dir.cwd().createDirPath(io, sub);
    try std.Io.Dir.cwd().createDirPath(io, outside);
    const registered_z = try allocator.dupeZ(u8, registered);
    defer allocator.free(registered_z);
    const sub_z = try allocator.dupeZ(u8, sub);
    defer allocator.free(sub_z);
    const outside_z = try allocator.dupeZ(u8, outside);
    defer allocator.free(outside_z);

    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    // Control: la cabina registra una raiz nueva (y puede quitarla).
    try std.testing.expectEqual(@as(c_int, 0), da_mount_add(handle, registered_z.ptr));
    try std.testing.expectEqual(@as(c_int, 0), da_mount_add(handle, outside_z.ptr));
    try std.testing.expectEqual(@as(c_int, 0), da_mount_remove(handle, outside_z.ptr));
    try std.testing.expectEqual(@as(c_int, 0), da_set_mcp_surface(handle));
    // Fuera de todo mount registrado se rechaza con mensaje de cabina.
    try std.testing.expect(da_mount_add(handle, outside_z.ptr) != 0);
    var message: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_last_error(&message));
    defer da_string_free(message);
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(message), "cabina") != null);
    // Dentro de un mount ya registrado si se permite.
    try std.testing.expectEqual(@as(c_int, 0), da_mount_add(handle, sub_z.ptr));
    var out: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_mounts_list_json(handle, &out));
    defer da_string_free(out);
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(out), "registered") != null);
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(out), "outside") == null);
}

/// H7 r4: solo mayúsculas ASCII, para que la variante de caja de una
/// ruta creada por la prueba siga siendo la misma ruta en Windows.
fn seg012AsciiUpper(allocator: std.mem.Allocator, text: []const u8) ![]u8 {
    const out = try allocator.alloc(u8, text.len);
    for (text, 0..) |c, i| {
        out[i] = if (c >= 'a' and c <= 'z') c - ('a' - 'A') else c;
    }
    return out;
}

/// H7 r4: el último error de una superficie MCP debe explicar que
/// la operación corresponde a la cabina. Libera el mensaje (testing.allocator).
fn seg012ExpectCabinaError() !void {
    var message: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_last_error(&message));
    defer da_string_free(message);
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(message), "cabina") != null);
}

test "CK-SEG-012 H7 MCP mount_add normalizes dot segments and case, resolves junctions and refuses UNC" {
    if (@import("builtin").os.tag != .windows) return @import("platform.zig").skip("T9: la prueba usa API de Windows (junctions, ACL o SID); omitida en Linux");
    const allocator = std.testing.allocator;
    var threaded = std.Io.Threaded.init(allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    // `tmp` se limpia en el defer registrado tras crear la junction (abajo).
    var tmp = std.testing.tmpDir(.{});
    const base = try tmp.dir.realPathFileAlloc(io, ".", allocator);
    defer allocator.free(base);
    const registered = try std.fmt.allocPrint(allocator, "{s}" ++ std.fs.path.sep_str ++ "registered", .{base});
    defer allocator.free(registered);
    const control = try std.fmt.allocPrint(allocator, "{s}" ++ std.fs.path.sep_str ++ "control", .{base});
    defer allocator.free(control);
    const sub = try std.fmt.allocPrint(allocator, "{s}" ++ std.fs.path.sep_str ++ "sub", .{registered});
    defer allocator.free(sub);
    const outside = try std.fmt.allocPrint(allocator, "{s}" ++ std.fs.path.sep_str ++ "outside", .{base});
    defer allocator.free(outside);
    const junction = try std.fmt.allocPrint(allocator, "{s}" ++ std.fs.path.sep_str ++ "j", .{registered});
    defer allocator.free(junction);
    try std.Io.Dir.cwd().createDirPath(io, registered);
    try std.Io.Dir.cwd().createDirPath(io, control);
    try std.Io.Dir.cwd().createDirPath(io, sub);
    try std.Io.Dir.cwd().createDirPath(io, outside);
    const registered_z = try allocator.dupeZ(u8, registered);
    defer allocator.free(registered_z);
    const control_z = try allocator.dupeZ(u8, control);
    defer allocator.free(control_z);
    const sub_z = try allocator.dupeZ(u8, sub);
    defer allocator.free(sub_z);
    const junction_z = try allocator.dupeZ(u8, junction);
    defer allocator.free(junction_z);

    var mk = try providers.github.runCmdCaptureWin32(allocator, &.{ "cmd.exe", "/d", "/c", "mklink", "/J", junction, outside }, null);
    defer mk.deinit(allocator);
    try std.testing.expectEqual(@as(u32, 0), mk.exit_code);
    // La junction se retira ANTES de cualquier borrado recursivo (patrón
    // H14: un `try` dentro de un `defer` no compila en Zig 0.16).
    // El destino está dentro de `base`, pero el orden no se delega a la pila.
    const junction_w = try std.unicode.utf8ToUtf16LeAllocZ(allocator, junction);
    defer allocator.free(junction_w);
    const Remove = struct {
        extern "kernel32" fn RemoveDirectoryW([*:0]const u16) callconv(.winapi) c_int;
    };
    defer tmp.cleanup();
    defer {
        _ = Remove.RemoveDirectoryW(junction_w.ptr);
        std.Io.Dir.cwd().deleteTree(io, base) catch |e| std.debug.print("CK-SEG-012 H7 r4 cleanup: {s}\n", .{@errorName(e)});
    }

    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    // Control de la cabina: registra dos raíces nuevas (una dentro de otra
    // no) antes de que exista la marca MCP.
    try std.testing.expectEqual(@as(c_int, 0), da_mount_add(handle, registered_z.ptr));
    try std.testing.expectEqual(@as(c_int, 0), da_mount_add(handle, control_z.ptr));
    try std.testing.expectEqual(@as(c_int, 0), da_set_mcp_surface(handle));

    // (a) `raíz\..\fuera` no confina: la ruta se normaliza antes de comparar.
    const dotdot = try std.fmt.allocPrint(allocator, "{s}" ++ std.fs.path.sep_str ++ ".." ++ std.fs.path.sep_str ++ "outside", .{registered});
    defer allocator.free(dotdot);
    const dotdot_z = try allocator.dupeZ(u8, dotdot);
    defer allocator.free(dotdot_z);
    try std.testing.expect(da_mount_add(handle, dotdot_z.ptr) != 0);
    try seg012ExpectCabinaError();

    // (b) La caja de Windows no cambia la ruta: mayúsculas sí confinan.
    const upper_sub = try seg012AsciiUpper(allocator, registered);
    defer allocator.free(upper_sub);
    const upper_wanted = try std.fmt.allocPrint(allocator, "{s}" ++ std.fs.path.sep_str ++ "SUB", .{upper_sub});
    defer allocator.free(upper_wanted);
    const upper_z = try allocator.dupeZ(u8, upper_wanted);
    defer allocator.free(upper_z);
    try std.testing.expectEqual(@as(c_int, 0), da_mount_add(handle, upper_z.ptr));

    // (c) Una junction que sale de la raíz se resuelve y se rechaza, tanto la
    //     junction como un hijo que aún no existe dentro de ella.
    try std.testing.expect(da_mount_add(handle, junction_z.ptr) != 0);
    const through = try std.fmt.allocPrint(allocator, "{s}" ++ std.fs.path.sep_str ++ "child", .{junction});
    defer allocator.free(through);
    const through_z = try allocator.dupeZ(u8, through);
    defer allocator.free(through_z);
    try std.testing.expect(da_mount_add(handle, through_z.ptr) != 0);
    try seg012ExpectCabinaError();

    // (d) Una ruta UNC no la confina ninguna raíz de unidad (ni viceversa).
    for ([_][*:0]const u8{
        "\\\\server\\share\\sub",
        "\\\\?\\C:\\registered\\sub",
    }) |unc| {
        try std.testing.expect(da_mount_add(handle, unc) != 0);
        try seg012ExpectCabinaError();
    }

    // Nada de lo rechazado llegó al registro; la raíz de control de la cabina,
    // la registrada y la variante en mayúsculas sí.
    var out: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_mounts_list_json(handle, &out));
    defer da_string_free(out);
    const list = std.mem.span(out);
    try std.testing.expect(std.mem.indexOf(u8, list, "control") != null);
    try std.testing.expect(std.mem.indexOf(u8, list, "\\..\\") == null);
    try std.testing.expect(std.mem.indexOf(u8, list, "registered\\j") == null);
    try std.testing.expect(std.mem.indexOf(u8, list, "server\\share") == null);
}

// H7 r5 (auditoría el segundo auditor lote AH, P1-a): si la raíz registrada por la
// cabina todavía no existe, el confinamiento no se queda en la relación léxica.
// Se resuelve el ancestro existente más profundo de la raíz y de la ruta pedida
// (sandbox.canonicalizeExisting, el mismo helper de los reparse points) y se
// comparan canónicos; si el ancestro reescribe la ruta de la raíz (junction
// hacia fuera) o nada es resoluble, el montaje se rechaza (fail closed).
test "CK-SEG-012 H7 r5 MCP mount_add with an absent registered root fails closed unless existing ancestors confirm it" {
    if (@import("builtin").os.tag != .windows) return @import("platform.zig").skip("T9: la prueba usa API de Windows (procesos, ACL, enlaces, atributos o registro); omitida en Linux");
    const allocator = std.testing.allocator;
    var threaded = std.Io.Threaded.init(allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var tmp = std.testing.tmpDir(.{});
    const base = try tmp.dir.realPathFileAlloc(io, ".", allocator);
    defer allocator.free(base);
    const outside = try std.fmt.allocPrint(allocator, "{s}" ++ std.fs.path.sep_str ++ "outside", .{base});
    defer allocator.free(outside);
    const junction = try std.fmt.allocPrint(allocator, "{s}" ++ std.fs.path.sep_str ++ "j", .{base});
    defer allocator.free(junction);
    const ghost_via_junction = try std.fmt.allocPrint(allocator, "{s}" ++ std.fs.path.sep_str ++ "sub" ++ std.fs.path.sep_str ++ "root", .{junction});
    defer allocator.free(ghost_via_junction);
    const ghost_normal = try std.fmt.allocPrint(allocator, "{s}" ++ std.fs.path.sep_str ++ "deep" ++ std.fs.path.sep_str ++ "root", .{base});
    defer allocator.free(ghost_normal);
    try std.Io.Dir.cwd().createDirPath(io, outside);
    var mk = try providers.github.runCmdCaptureWin32(allocator, &.{ "cmd.exe", "/d", "/c", "mklink", "/J", junction, outside }, null);
    defer mk.deinit(allocator);
    try std.testing.expectEqual(@as(u32, 0), mk.exit_code);
    const junction_w = try std.unicode.utf8ToUtf16LeAllocZ(allocator, junction);
    defer allocator.free(junction_w);
    const Remove = struct {
        extern "kernel32" fn RemoveDirectoryW([*:0]const u16) callconv(.winapi) c_int;
    };
    defer tmp.cleanup();
    defer {
        _ = Remove.RemoveDirectoryW(junction_w.ptr);
        std.Io.Dir.cwd().deleteTree(io, base) catch |e| std.debug.print("CK-SEG-012 H7 r5 cleanup: {s}\n", .{@errorName(e)});
    }

    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    // La cabina registra dos raíces fantasma: una bajo la junction (que sale
    // de base) y otra bajo un ancestro normal. Ninguna de las dos existe.
    const ghost_j_z = try allocator.dupeZ(u8, ghost_via_junction);
    defer allocator.free(ghost_j_z);
    try std.testing.expectEqual(@as(c_int, 0), da_mount_add(handle, ghost_j_z.ptr));
    const ghost_n_z = try allocator.dupeZ(u8, ghost_normal);
    defer allocator.free(ghost_n_z);
    try std.testing.expectEqual(@as(c_int, 0), da_mount_add(handle, ghost_n_z.ptr));
    try std.testing.expectEqual(@as(c_int, 0), da_set_mcp_surface(handle));

    // (1) Raíz inexistente bajo un ancestro que es una junction hacia fuera:
    //     el ancestro resuelto reescribe la ruta y no confirma la raíz
    //     registrada → rechazado con mensaje de cabina.
    const child_j = try std.fmt.allocPrint(allocator, "{s}" ++ std.fs.path.sep_str ++ "child", .{ghost_via_junction});
    defer allocator.free(child_j);
    const child_j_z = try allocator.dupeZ(u8, child_j);
    defer allocator.free(child_j_z);
    try std.testing.expect(da_mount_add(handle, child_j_z.ptr) != 0);
    try seg012ExpectCabinaError();

    // (2) Raíz inexistente bajo un ancestro normal: la ruta descendiente se
    //     acepta solo si los canónicos lo confirman (aquí lo confirman).
    const child_n = try std.fmt.allocPrint(allocator, "{s}" ++ std.fs.path.sep_str ++ "child", .{ghost_normal});
    defer allocator.free(child_n);
    const child_n_z = try allocator.dupeZ(u8, child_n);
    defer allocator.free(child_n_z);
    try std.testing.expectEqual(@as(c_int, 0), da_mount_add(handle, child_n_z.ptr));

    // Nada de la rama de la junction llegó al registro.
    var out: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_mounts_list_json(handle, &out));
    defer da_string_free(out);
    const list = std.mem.span(out);
    // El JSON de mounts escapa cada barra inversa como `\\`: las rutas se
    // buscan con el doble separador. Ninguna fila de la rama de la junction
    // (la cabina registró su raíz fantasma, pero el child MCP rechazado no
    // llegó) y el child bajo el ancestro normal sí quedó registrado.
    try std.testing.expect(std.mem.indexOf(u8, list, "j\\\\sub\\\\root\\\\child") == null);
    try std.testing.expect(std.mem.indexOf(u8, list, "deep\\\\root\\\\child") != null);
}

test "CK-SEG-012 H7 MCP webhook_add rejects allow_private; the cabina can still add a private receiver" {
    const private_hook = "{\"url\":\"https://example.test/hook\",\"allow_private\":true}";
    var ui: ?*anyopaque = null;
