    try std.testing.expect(ui_id > 0);

    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    try std.testing.expectEqual(@as(c_int, 0), da_set_mcp_surface(handle));
    var hook_id: i64 = 0;
    try std.testing.expect(da_webhook_add(handle, private_hook, &hook_id) != 0);
    var message: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_last_error(&message));
    defer da_string_free(message);
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(message), "cabina") != null);
    var out: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_webhook_list_json(handle, &out));
    defer da_string_free(out);
    try std.testing.expectEqualStrings("[]", std.mem.span(out));
    // Un webhook publico ordinario sigue permitido por MCP.
    try std.testing.expectEqual(@as(c_int, 0), da_webhook_add(handle, "{\"url\":\"https://example.test/hook\"}", &hook_id));
}

test "SEC2 R7 N2 da_set_workspace_root on the MCP surface compares effective roots" {
    defer workspace.setWorkspaceRoot(workspace.WORKSPACE_ROOT);
    var cwd_buf: [4096]u8 = undefined;
    const cwd_len = GetCurrentDirectoryA(@intCast(cwd_buf.len), &cwd_buf);
    if (cwd_len == 0 or cwd_len >= cwd_buf.len) return error.SkipZigTest;
    const project = cwd_buf[0..cwd_len];
    // La cabina elige un proyecto SIN segmento devagents-workspace.
    var ui: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&ui, ":memory:"));
    defer _ = da_core_shutdown(ui);
    const selected = try std.testing.allocator.dupeZ(u8, project);
    defer std.testing.allocator.free(selected);
