    defer _ = da_core_shutdown(handle);
    try std.testing.expectEqual(@as(c_int, 0), da_set_mcp_surface(handle));
    // Hermana de la efectiva: dentro de la SELECCION, fuera de la EFECTIVA -> rechazada.
    const sibling = try std.fmt.allocPrintSentinel(std.testing.allocator, "{s}" ++ std.fs.path.sep_str ++ "sec2-r7-hermana", .{project}, 0);
    defer std.testing.allocator.free(sibling);
    try std.testing.expect(da_set_workspace_root(handle, sibling.ptr) != 0);
    var after_buf: [4096]u8 = undefined;
