    defer std.testing.allocator.free(effective_before);
    try std.testing.expectEqualStrings(effective_before, workspace.effectiveRoot(&after_buf));
    // Subcarpeta de la efectiva: estrechar si se admite.
    const inside = try std.fmt.allocPrintSentinel(std.testing.allocator, "{s}" ++ std.fs.path.sep_str ++ "{s}" ++ std.fs.path.sep_str ++ "sec2-r7-estrecha", .{ project, workspace.WORKSPACE_ROOT }, 0);
    defer std.testing.allocator.free(inside);
    try std.testing.expectEqual(@as(c_int, 0), da_set_workspace_root(handle, inside.ptr));
}

