test "PRICING C ABI revalidator errors map to failure and Spanish last error" {
    // La exportada usa este catch exacto. Sin clave no alcanza SQL en revalidate;
    // se prueba el seam del canal de error sin añadir inyección a la ABI pública.
    for ([_]anyerror{ error.PrepareFailed, error.StepFailed, error.PricingRollbackFailed, error.OutOfMemory }) |failure| {
        const code = pricingRevalidationError(failure);
        try std.testing.expectEqual(@intFromEnum(if (failure == error.OutOfMemory) DaResult.oom else DaResult.internal), code);
        try std.testing.expect(code != 0);
        try std.testing.expect(std.mem.indexOf(u8, last_error_buf[0..last_error_len], "falló la revalidación de precios") != null);
        try std.testing.expect(std.mem.indexOf(u8, last_error_buf[0..last_error_len], @errorName(failure)) != null);
    }
}

// browser.v1 uses a transport lane independent of dispatch and UI. Operation
// failures are JSON for out_json exports; malformed ABI calls use DaResult.
fn browserOperationError(out_json: *?[*:0]const u8, failure: anyerror) c_int {
    out_json.* = null;
    if (failure == error.OutOfMemory) return @intFromEnum(err(.oom, "browser.v1: OOM"));
    const raw = std.json.Stringify.valueAlloc(std.heap.c_allocator, .{ .schema = browser_service.SCHEMA, .ok = false, .@"error" = .{ .code = browser_service.errorCode(failure), .effect_status = "not_started" } }, .{}) catch return @intFromEnum(err(.oom, "browser.v1: OOM"));
    defer std.heap.c_allocator.free(raw);
    out_json.* = ownedCStr(raw) orelse return @intFromEnum(err(.oom, "browser.v1: OOM"));
    return @intFromEnum(ok());
}

fn browserJsonOutput(out_json: *?[*:0]const u8, raw: []u8) c_int {
    defer std.heap.c_allocator.free(raw);
    out_json.* = ownedCStr(raw) orelse return @intFromEnum(err(.oom, "browser.v1: OOM"));
    return @intFromEnum(ok());
}

fn browserOrderSpaceId(st: *CoreState, order_id: i64) !i64 {
    const stmt = try st.db_conn.prepare("SELECT COALESCE(space_id, 0) FROM orders WHERE id = ?");
    defer st.db_conn.finalize(stmt);
    try db.bindInt(stmt, 1, order_id);
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) return error.OrderMismatch;
    return db.c.sqlite3_column_int64(stmt, 0);
}

fn browserAttach(st: *CoreState, raw: []const u8) ![]u8 {
    if (st.mcp_surface) return error.PermissionRequired;
    const a = std.heap.c_allocator;
    var parsed = try browser_service.parseObject(a, raw);
    defer parsed.deinit();
    const config = parsed.value;
    try browser_service.requireSchema(config);
    const order_id = try browser_service.integerField(config, "order_id");
    const root = try browser_service.stringField(config, "workspace_root");
    const instance = try browser_service.stringField(config, "host_instance");
    if (order_id <= 0 or root.len == 0 or root.len > 4096) return error.InvalidArguments;
    var space_id = try browserOrderSpaceId(st, order_id);
    var root_buf: [4096]u8 = undefined;
    var trusted_root = orderWorktree(st, order_id, &root_buf);
    if (!std.mem.eql(u8, root, trusted_root)) return error.OrderMismatch;
    var prepared_buf: [4096]u8 = undefined;
    var direct_buf: [4096]u8 = undefined;
    const is_direct = directOrderRoot(st, order_id, &direct_buf) != null;
    if (!is_direct and orderSpacePath(st.db_conn, order_id, &prepared_buf) == null and spaces.isGitRepo(a, trusted_root)) {
        const rec = findOrder(st, order_id) orelse return error.OrderMismatch;
        var diag: worktree_prepare.Diag = .{};
        trusted_root = (try ensureOrderSpace(st, st.db_conn, rec, trusted_root, &prepared_buf, &diag)) orelse return error.InvalidContext;
    }
    // Dispatch can win the preparation race after initial root validation.
    trusted_root = orderWorktree(st, order_id, &root_buf);
    space_id = try browserOrderSpaceId(st, order_id);
    const service = try st.browser_registry.acquire(st.arena.child_allocator, .{ .order_id = order_id, .space_id = space_id, .workspace_root = trusted_root });
    defer service.release();
    return service.attachHost(a, instance);
}

pub export fn da_browser_host_attach_v1(handle: ?*anyopaque, config_json: ?[*:0]const u8, out_json: *?[*:0]const u8) callconv(.c) c_int {
    out_json.* = null;
    const st: *CoreState = @ptrCast(@alignCast(handle orelse return @intFromEnum(err(.invalid_arg, "browser.v1: null handle"))));
    const raw = std.mem.span(config_json orelse return @intFromEnum(err(.invalid_arg, "browser.v1: null config")));
    const response = browserAttach(st, raw) catch |failure| return browserOperationError(out_json, failure);
    return browserJsonOutput(out_json, response);
}

pub export fn da_browser_host_poll_v1(handle: ?*anyopaque, host_capability: ?[*:0]const u8, out_json: *?[*:0]const u8) callconv(.c) c_int {
    out_json.* = null;
    const st: *CoreState = @ptrCast(@alignCast(handle orelse return @intFromEnum(err(.invalid_arg, "browser.v1: null handle"))));
    const capability = std.mem.span(host_capability orelse return @intFromEnum(err(.invalid_arg, "browser.v1: null capability")));
    const service = st.browser_registry.forCapability(capability) catch |failure| return browserOperationError(out_json, failure);
    defer service.release();
    const response = service.pollHost(std.heap.c_allocator, capability) catch |failure| return browserOperationError(out_json, failure);
    return browserJsonOutput(out_json, response);
}

pub export fn da_browser_host_complete_v1(handle: ?*anyopaque, host_capability: ?[*:0]const u8, completion_json: ?[*:0]const u8) callconv(.c) c_int {
    const st: *CoreState = @ptrCast(@alignCast(handle orelse return @intFromEnum(err(.invalid_arg, "browser.v1: null handle"))));
    const capability = std.mem.span(host_capability orelse return @intFromEnum(err(.invalid_arg, "browser.v1: null capability")));
    const raw = std.mem.span(completion_json orelse return @intFromEnum(err(.invalid_arg, "browser.v1: null completion")));
    const service = st.browser_registry.forCapability(capability) catch |failure| return @intFromEnum(err(.invalid_state, @errorName(failure)));
    defer service.release();
    service.completeHost(capability, raw) catch |failure| return @intFromEnum(err(if (failure == error.OutOfMemory) .oom else .invalid_state, @errorName(failure)));
    return @intFromEnum(ok());
}

pub export fn da_process_control_v1(handle: ?*anyopaque, control_json: ?[*:0]const u8, out_json: *?[*:0]const u8) callconv(.c) c_int {
    out_json.* = null;
    const st: *CoreState = @ptrCast(@alignCast(handle orelse return @intFromEnum(err(.invalid_arg, "process: null handle"))));
    if (st.mcp_surface) return @intFromEnum(err(.invalid_state, "El control humano del proceso requiere la cabina."));
    const raw = std.mem.span(control_json orelse return @intFromEnum(err(.invalid_arg, "process: falta la acción")));
    const a = std.heap.c_allocator;
    var parsed = browser_service.parseObject(a, raw) catch return @intFromEnum(err(.invalid_arg, "Solicitud de proceso inválida."));
    defer parsed.deinit();
    const action = browser_service.stringField(parsed.value, "action") catch return @intFromEnum(err(.invalid_arg, "Falta la acción del proceso."));
    const tool = if (std.mem.eql(u8, action, "stop")) governed_tool_executor.PROCESS_STOP_TOOL_NAME else if (std.mem.eql(u8, action, "logs")) governed_tool_executor.PROCESS_LOGS_TOOL_NAME else return @intFromEnum(err(.invalid_arg, "Acción de proceso desconocida."));
    const response = governed_tool_executor.GovernedToolExecutor.processControl(a, &st.browser_registry.background_commands, tool, raw, null) catch |failure| {
        return @intFromEnum(err(.invalid_state, if (failure == error.ProcessNotFound) "El proceso ya no está en el registro de esta sesión de DevAgents." else @errorName(failure)));
    };
    return browserJsonOutput(out_json, response);
}

fn browserControl(st: *CoreState, raw: []const u8) ![]u8 {
    if (st.mcp_surface) return error.PermissionRequired;
    var parsed = try browser_service.parseObject(std.heap.c_allocator, raw);
    defer parsed.deinit();
    const value = parsed.value;
    try browser_service.requireSchema(value);
    const capability = try browser_service.stringField(value, "host_capability");
    const action = try browser_service.stringField(value, "action");
    const tab = if (value.object.contains("tab_id")) try browser_service.stringField(value, "tab_id") else null;
    const service = try st.browser_registry.forCapability(capability);
    defer service.release();
    return service.controlHost(std.heap.c_allocator, capability, action, tab);
}

pub export fn da_browser_control_v1(handle: ?*anyopaque, trusted_control_json: ?[*:0]const u8, out_json: *?[*:0]const u8) callconv(.c) c_int {
    out_json.* = null;
    const st: *CoreState = @ptrCast(@alignCast(handle orelse return @intFromEnum(err(.invalid_arg, "browser.v1: null handle"))));
    const raw = std.mem.span(trusted_control_json orelse return @intFromEnum(err(.invalid_arg, "browser.v1: null control")));
    const response = browserControl(st, raw) catch |failure| return browserOperationError(out_json, failure);
    return browserJsonOutput(out_json, response);
}

const E2P2AbiHost = struct {
    handle: ?*anyopaque,
    capability: [*:0]const u8,
    failure: ?anyerror = null,
    completion: ?[:0]u8 = null,
    fn run(self: *E2P2AbiHost) void {
        self.transport() catch |failure| {
            self.failure = failure;
        };
    }
    fn transport(self: *E2P2AbiHost) !void {
        const a = std.heap.page_allocator;
        for (0..1000) |_| {
            var out: ?[*:0]const u8 = null;
            if (da_browser_host_poll_v1(self.handle, self.capability, &out) != 0) return error.PollFailed;
            defer if (out) |text| da_string_free(@constCast(text));
            var parsed = try browser_service.parseObject(a, std.mem.span(out.?));
            defer parsed.deinit();
            if (!parsed.value.object.get("ok").?.bool) return error.HostRejected;
            const requests = parsed.value.object.get("requests").?.array.items;
            if (requests.len > 0) {
                const request = requests[0];
                const raw = try std.json.Stringify.valueAlloc(a, .{ .schema = browser_service.SCHEMA, .request_id = try browser_service.stringField(request, "request_id"), .order_id = try browser_service.integerField(request, "order_id"), .host_generation = try browser_service.integerField(request, "host_generation"), .control_epoch = try browser_service.integerField(request, "control_epoch"), .ok = true, .result = .{ .tabs = .{.{ .id = "abi-host-tab", .title = "C ABI actual host fixture title", .active = true }} } }, .{});
                defer a.free(raw);
                self.completion = try a.dupeZ(u8, raw);
                if (da_browser_host_complete_v1(self.handle, self.capability, self.completion.?) != 0) return error.CompleteFailed;
                return;
            }
            Sleep(1);
        }
        return error.Timeout;
    }
};

fn e2p2AttachFixture(handle: ?*anyopaque, order_id: i64, root: []const u8) !std.json.Parsed(std.json.Value) {
    const a = std.testing.allocator;
    const raw = try std.json.Stringify.valueAlloc(a, .{ .schema = browser_service.SCHEMA, .order_id = order_id, .workspace_root = root, .host_instance = "abi-fixture-host" }, .{});
    defer a.free(raw);
    const z = try a.dupeZ(u8, raw);
    defer a.free(z);
    var out: ?[*:0]const u8 = null;
    try std.testing.expectEqual(@as(c_int, 0), da_browser_host_attach_v1(handle, z, &out));
    defer da_string_free(@constCast(out.?));
    return browser_service.parseObject(a, std.mem.span(out.?));
}

test "E2P2 C ABI trusted host attaches before executor dispatch and isolates order B and handles" {
    const a = std.testing.allocator;
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    try st.db_conn.exec("INSERT INTO orders (id,project_id,user_prompt,status,created_at) VALUES (41,'fixture','A','running',1),(42,'fixture','B','running',1)");
    var root_buf: [4096]u8 = undefined;
    const root = workspace.effectiveRoot(&root_buf);
    var attached_a = try e2p2AttachFixture(handle, 41, root);
    defer attached_a.deinit();
    var attached_b = try e2p2AttachFixture(handle, 42, root);
    defer attached_b.deinit();
    const cap_a = try a.dupeZ(u8, try browser_service.stringField(attached_a.value, "host_capability"));
    defer a.free(cap_a);
    const cap_b = try a.dupeZ(u8, try browser_service.stringField(attached_b.value, "host_capability"));
    defer a.free(cap_b);
    const service = try st.browser_registry.acquire(st.arena.child_allocator, .{ .order_id = 41, .space_id = 0, .workspace_root = root });
    defer service.release();
    try std.testing.expectEqualStrings(try browser_service.stringField(attached_a.value, "session_id"), service.session_id);
    const args = try std.json.Stringify.valueAlloc(a, .{ .session_id = service.session_id, .action = "list" }, .{});
    defer a.free(args);
    var tool: @import("governed_tool_executor.zig").GovernedToolExecutor = .{ .allocator = a, .plan_approved = true, .browser = service, .browser_identity = service.identity("abi-worker", 1) };
    defer tool.deinitState(a);
    var host: E2P2AbiHost = .{ .handle = handle, .capability = cap_a };
    defer if (host.completion) |text| std.heap.page_allocator.free(text);
    const raw = blk: {
        const thread = try std.Thread.spawn(.{}, E2P2AbiHost.run, .{&host});
        defer thread.join();
        break :blk try @import("governed_tool_executor.zig").GovernedToolExecutor.execute(&tool, "browser_tabs", args);
    };
    try std.testing.expect(host.failure == null);
    var result = try browser_service.parseObject(a, raw);
    defer result.deinit();
    try std.testing.expect(result.value.object.get("ok").?.bool);
    try std.testing.expectEqualStrings("C ABI actual host fixture title", result.value.object.get("result").?.object.get("tabs").?.array.items[0].object.get("title").?.string);
    try std.testing.expect(da_browser_host_complete_v1(handle, cap_a, host.completion.?) != 0);
    try std.testing.expect(da_browser_host_complete_v1(handle, cap_b, host.completion.?) != 0);
    var out: ?[*:0]const u8 = null;
    try std.testing.expectEqual(@as(c_int, 0), da_browser_host_poll_v1(handle, cap_b, &out));
    defer da_string_free(@constCast(out.?));
    var b_poll = try browser_service.parseObject(a, std.mem.span(out.?));
    defer b_poll.deinit();
    try std.testing.expectEqual(@as(usize, 0), b_poll.value.object.get("requests").?.array.items.len);
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(out.?), cap_a) == null);
    var second: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&second, ":memory:"));
    defer _ = da_core_shutdown(second);
    var foreign_out: ?[*:0]const u8 = null;
    try std.testing.expectEqual(@as(c_int, 0), da_browser_host_poll_v1(second, cap_a, &foreign_out));
    defer da_string_free(@constCast(foreign_out.?));
    var foreign = try browser_service.parseObject(a, std.mem.span(foreign_out.?));
    defer foreign.deinit();
    try std.testing.expect(!foreign.value.object.get("ok").?.bool);
    try std.testing.expectEqualStrings("order_mismatch", foreign.value.object.get("error").?.object.get("code").?.string);
    std.debug.print("E2P2 ABI title=C ABI actual host fixture title executor=real order_B=empty foreign_completion=rejected duplicate=rejected handles=isolated capability_in_poll=false\n", .{});
}

