test "E2P2 attach before git dispatch prepares authoritative worktree without approving order" {
    const a = std.testing.allocator;
    var threaded = std.Io.Threaded.init(a, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const project = try isolatedTestPath(&tmp, "browser-git-project");
    defer a.free(project);
    const base = try std.fmt.allocPrint(a, "{s}" ++ std.fs.path.sep_str ++ "devagents-workspace", .{project});
    defer a.free(base);
    try std.Io.Dir.cwd().createDirPath(io, base);
    try e2p2GitFixtureCommand(&.{ "git", "-c", "init.templateDir=", "init", project });
    try e2p2GitFixtureCommand(&.{ "git", "-C", project, "-c", "core.hooksPath=NUL", "-c", "commit.gpgsign=false", "-c", "user.name=Browser Fixture", "-c", "user.email=browser-fixture@invalid", "commit", "--allow-empty", "-m", "browser fixture" });
    var handle: ?*anyopaque = null;
