    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    const rec = findOrder(st, orderHandleToId(order).?).?;
    const order_id = rec.db_id orelse rec.id;
    const original_status = rec.status;
    var before_buf: [4096]u8 = undefined;
    const before_root = orderWorktree(st, order_id, &before_buf);
    var attached = try e2p2AttachFixture(handle, order_id, before_root);
    defer attached.deinit();
    try std.testing.expect(attached.value.object.get("ok").?.bool);
    const authoritative = try browser_service.stringField(attached.value, "workspace_root");
    try std.testing.expect(!std.mem.eql(u8, before_root, authoritative));
    var after_buf: [4096]u8 = undefined;
    const after_root = orderSpacePath(st.db_conn, order_id, &after_buf) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings(after_root, authoritative);
    const service = try st.browser_registry.acquire(st.arena.child_allocator, .{ .order_id = order_id, .space_id = try browserOrderSpaceId(st, order_id), .workspace_root = after_root });
    defer service.release();
    try std.testing.expectEqualStrings(service.owner.workspace_root, authoritative);
    try std.testing.expectEqual(original_status, rec.status);
    try std.testing.expect(!st.dispatch_registry.snapshot(order_id).found);
    std.debug.print("E2P2 PRE_DISPATCH git_worktree=prepared registry_root=authoritative approval=unchanged dispatched=false\n", .{});
}

