    try std.testing.expect(std.mem.indexOf(u8, text, "\"last_provider\":\"Gemini\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, text, "\"last_model\":\"gemini-2.5-pro\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, text, "\"total_prompt\":122200") != null);
}

// additive JSON contract order_progress.v1. Returned strings use
// da_string_free; on failure output is null and da_last_error has the diagnostic.
fn progressJson(out_json: *?[*:0]u8, value: anytype) c_int {
    const raw = std.json.Stringify.valueAlloc(std.heap.c_allocator, value, .{}) catch
        return @intFromEnum(err(.oom, "order_progress: OOM"));
    defer std.heap.c_allocator.free(raw);
    out_json.* = ownedCStr(raw) orelse return @intFromEnum(err(.oom, "order_progress: OOM output"));
    return @intFromEnum(ok());
}

fn progressFailure(failure: order_progress.ProgressError, stale_seq: i64) c_int {
    var buf: [160]u8 = undefined;
    const message = if (failure == error.StaleProgress)
        std.fmt.bufPrint(&buf, "{{\"error\":\"StaleProgress\",\"seq\":{d}}}", .{stale_seq}) catch unreachable
    else
        std.fmt.bufPrint(&buf, "{{\"error\":\"{s}\"}}", .{@errorName(failure)}) catch unreachable;
    return @intFromEnum(err(switch (failure) {
        error.StaleProgress, error.HumanNoteProtected => .invalid_state,
        error.OrderNotFound => .not_found,
        error.OutOfMemory => .oom,
        error.DbUnavailable => .internal,
        else => .invalid_arg,
    }, message));
}

pub export fn da_order_progress_get(handle: ?*anyopaque, request_json: [*:0]const u8, out_json: ?*?[*:0]u8) callconv(.c) c_int {
    if (out_json) |out| out.* = null;
    if (handle == null or out_json == null) return @intFromEnum(err(.invalid_arg, "order_progress: null handle/output"));
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    const raw = std.mem.span(request_json);
    if (raw.len > 65536) return @intFromEnum(err(.invalid_arg, "order_progress: request too large"));
    const request = std.json.parseFromSlice(std.json.Value, st.arena.child_allocator, raw, .{}) catch
        return @intFromEnum(err(.invalid_arg, "order_progress: invalid JSON/order_id"));
    defer request.deinit();
    if (request.value != .object or request.value.object.count() != 1)
        return @intFromEnum(err(.invalid_arg, "order_progress: get requires only order_id"));
    const field = request.value.object.get("order_id") orelse return @intFromEnum(err(.invalid_arg, "order_progress: missing order_id"));
    if (field != .integer or field.integer <= 0) return @intFromEnum(err(.invalid_arg, "order_progress: order_id must be positive integer"));
    const oid = field.integer;
    var progress = order_progress.readProgress(st.arena.child_allocator, st.db_conn, oid) catch |failure|
        return progressFailure(failure, 0);
    defer if (progress) |*p| p.deinit();
    if (progress) |p| return progressJson(out_json.?, .{
        .schema = "order_progress.v1",
        .found = true,
        .order_id = p.order_id,
        .state = p.state,
        .note = p.note,
        .author = p.author,
        .seq = p.seq,
        .updated_at = p.updated_at,
    });
    return progressJson(out_json.?, .{ .schema = "order_progress.v1", .found = false, .order_id = oid, .seq = @as(i64, 0) });
}

pub export fn da_order_progress_set(handle: ?*anyopaque, request_json: [*:0]const u8, out_json: ?*?[*:0]u8) callconv(.c) c_int {
    if (out_json) |out| out.* = null;
    if (handle == null or out_json == null) return @intFromEnum(err(.invalid_arg, "order_progress: null handle/output"));
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    const raw = std.mem.span(request_json);
    if (raw.len > 65536) return @intFromEnum(err(.invalid_arg, "order_progress: request too large"));
    const request = std.json.parseFromSlice(std.json.Value, st.arena.child_allocator, raw, .{}) catch
        return @intFromEnum(err(.invalid_arg, "order_progress: invalid JSON"));
    defer request.deinit();
    if (request.value != .object or request.value.object.count() != 5)
        return @intFromEnum(err(.invalid_arg, "order_progress: set requires order_id, expected_seq, state, note, author"));
    const fields = request.value.object;
    inline for (.{ "order_id", "expected_seq", "state", "note", "author" }) |name| {
        const field = fields.get(name) orelse return @intFromEnum(err(.invalid_arg, "order_progress: missing " ++ name));
        const integer = comptime std.mem.eql(u8, name, "order_id") or std.mem.eql(u8, name, "expected_seq");
        if (integer) {
            if (field != .integer) return @intFromEnum(err(.invalid_arg, "order_progress: integer required for " ++ name));
        } else {
            if (field != .string) return @intFromEnum(err(.invalid_arg, "order_progress: string required for " ++ name));
        }
    }
    const r = .{ .order_id = fields.get("order_id").?.integer, .expected_seq = fields.get("expected_seq").?.integer, .state = fields.get("state").?.string, .note = fields.get("note").?.string, .author = fields.get("author").?.string };
    if (r.order_id <= 0) return @intFromEnum(err(.invalid_arg, "order_progress: order_id must be positive"));
    if (st.mcp_surface and !std.mem.eql(u8, r.author, "agent"))
        return @intFromEnum(err(.invalid_arg, "order_progress: MCP author must be agent"));
    var stale: i64 = 0;
    const seq = order_progress.writeProgress(st.arena.child_allocator, st.db_conn, r.order_id, r.expected_seq, r.state, r.note, r.author, &stale) catch |failure|
        return progressFailure(failure, stale);
    return progressJson(out_json.?, .{ .schema = "order_progress.v1", .ok = true, .order_id = r.order_id, .seq = seq });
}

test "CK-COMP-015 c_api JSON roundtrip, stale seq and human note protection" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    try st.db_conn.exec("INSERT INTO orders (id,project_id,user_prompt,status,created_at) VALUES (501,'p','progress','running',1)");
    var out: ?[*:0]u8 = null;
    try std.testing.expectEqual(@as(c_int, 0), da_order_progress_get(handle, "{\"order_id\":501}", &out));
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(out.?), "\"found\":false") != null);
    da_string_free(out.?);
    const human = "{\"order_id\":501,\"expected_seq\":0,\"state\":\"todo\",\"note\":\"humano \\n \\u00e1\",\"author\":\"human\"}";
    try std.testing.expectEqual(@as(c_int, 0), da_order_progress_set(handle, human, &out));
    da_string_free(out.?);
    try std.testing.expect(da_order_progress_set(handle, human, &out) != 0);
    try std.testing.expect(out == null);
    var message: [*:0]u8 = undefined;
    _ = da_last_error(&message);
    defer da_string_free(message);
    try std.testing.expectEqualStrings("{\"error\":\"StaleProgress\",\"seq\":1}", std.mem.span(message));
    try std.testing.expect(da_order_progress_set(handle, "{\"order_id\":501,\"expected_seq\":1,\"state\":\"done\",\"note\":\"agente\",\"author\":\"agent\"}", &out) != 0);
    try std.testing.expectEqual(@as(c_int, 0), da_order_progress_get(handle, "{\"order_id\":501}", &out));
    defer da_string_free(out.?);
    const parsed = try std.json.parseFromSlice(std.json.Value, std.testing.allocator, std.mem.span(out.?), .{});
    defer parsed.deinit();
    try std.testing.expectEqualStrings("humano \n á", parsed.value.object.get("note").?.string);
    try std.testing.expectEqualStrings("human", parsed.value.object.get("author").?.string);
    try std.testing.expectEqual(@as(i64, 1), parsed.value.object.get("seq").?.integer);
}

