}

/// additive v1 selection metadata; never probes providers.
pub export fn da_models_selection_v1_json(handle: ?*anyopaque, out_json: ?*?[*:0]const u8) callconv(.c) c_int {
    const st: *CoreState = @ptrCast(@alignCast(handle orelse return @intFromEnum(err(.invalid_arg, "null core"))));
    const out = out_json orelse return @intFromEnum(err(.invalid_arg, "null out"));
    const a = st.arena.child_allocator;
    const external = (external_registry.lastKnown(a, st.catalog.db, health.nowSeconds(st.catalog.db)) catch |e| return @intFromEnum(err(.internal, @errorName(e)))) orelse (a.dupe(u8, "[]") catch return @intFromEnum(err(.oom, "OOM")));
    defer a.free(external);
    const body = @import("model_selection.zig").list(a, st.catalog.db, external) catch |e| return @intFromEnum(err(.internal, @errorName(e)));
    defer a.free(body);
    out.* = ownedCStr(body) orelse return @intFromEnum(err(.oom, "OOM"));
    return @intFromEnum(ok());
}

/// atomic v1 preference update with the resulting preflight.
pub export fn da_model_preferences_set_v1_json(handle: ?*anyopaque, request: ?[*:0]const u8, out_json: ?*?[*:0]const u8) callconv(.c) c_int {
    const st: *CoreState = @ptrCast(@alignCast(handle orelse return @intFromEnum(err(.invalid_arg, "null core"))));
    const out = out_json orelse return @intFromEnum(err(.invalid_arg, "null out"));
    const raw = std.mem.span(request orelse return @intFromEnum(err(.invalid_arg, "null preferences")));
    if (raw.len > 8192) return @intFromEnum(err(.invalid_arg, "preferences too large"));
    const a = st.arena.child_allocator;
    const parsed = std.json.parseFromSlice(std.json.Value, a, raw, .{}) catch return @intFromEnum(err(.invalid_arg, "invalid preferences JSON"));
    defer parsed.deinit();
    if (parsed.value != .object) return @intFromEnum(err(.invalid_arg, "preferences must be an object"));
    const provider = parsed.value.object.get("provider") orelse return @intFromEnum(err(.invalid_arg, "missing provider"));
    const model = parsed.value.object.get("model") orelse return @intFromEnum(err(.invalid_arg, "missing model"));
    const show = parsed.value.object.get("show_in_selectors") orelse return @intFromEnum(err(.invalid_arg, "missing show_in_selectors"));
    const allow = parsed.value.object.get("allow_automatic") orelse return @intFromEnum(err(.invalid_arg, "missing allow_automatic"));
    if (provider != .string or model != .string or show != .bool or allow != .bool) return @intFromEnum(err(.invalid_arg, "invalid preference types"));
    const external = (external_registry.lastKnown(a, st.catalog.db, health.nowSeconds(st.catalog.db)) catch |e| return @intFromEnum(err(.internal, @errorName(e)))) orelse (a.dupe(u8, "[]") catch return @intFromEnum(err(.oom, "OOM")));
    defer a.free(external);
    st.catalog.db.exec("BEGIN IMMEDIATE") catch |e| return @intFromEnum(err(.internal, @errorName(e)));
    var committed = false;
    defer if (!committed) st.catalog.db.exec("ROLLBACK") catch |e| std.log.err("model preferences rollback: {s}", .{@errorName(e)});
    @import("model_selection.zig").set(a, st.catalog.db, external, provider.string, model.string, .{ .show_in_selectors = show.bool, .allow_automatic = allow.bool }) catch |e|
        return @intFromEnum(err(if (e == error.InvalidModel or e == error.UnknownModel) .invalid_arg else .internal, @errorName(e)));
    const body = configurationJson(st, a) catch |e| return @intFromEnum(err(.internal, @errorName(e)));
    defer a.free(body);
    const owned = ownedCStr(body) orelse return @intFromEnum(err(.oom, "OOM"));
    st.catalog.db.exec("COMMIT") catch |e| {
        da_string_free(owned);
        return @intFromEnum(err(.internal, @errorName(e)));
    };
    committed = true;
    out.* = owned;
    return @intFromEnum(ok());
}

