test "CK-PRV-004 r2-1 preference warning allows preflight and submission gate" {
    const a = std.testing.allocator;
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    try st.catalog.db.exec("UPDATE models SET available=0");
    try st.catalog.db.exec("UPDATE providers SET enabled=1 WHERE name IN ('Cohere','Google AI Studio')");
    try st.catalog.db.exec("INSERT INTO api_keys(provider_id,label,key_ciphertext,status) SELECT id,'synthetic',X'00','active' FROM providers WHERE name IN ('Cohere','Google AI Studio')");
    try st.catalog.db.exec("INSERT INTO models(provider_id,model_name,is_free,available) SELECT id,CASE name WHEN 'Cohere' THEN 'command-a' ELSE 'gemini-flash' END,1,1 FROM providers WHERE name IN ('Cohere','Google AI Studio')");
    try std.testing.expectEqual(@as(c_int, 0), da_exec_set_model(handle, "Cohere", "command-a"));
    try st.catalog.db.exec("INSERT INTO model_preferences VALUES('Google AI Studio','gemini-flash',1,0)");
    const body = try configurationJson(st, a);
    defer a.free(body);
    const parsed = try std.json.parseFromSlice(std.json.Value, a, body, .{});
    defer parsed.deinit();
    const issue = parsed.value.object.get("issues").?.array.items[0].object;
    try std.testing.expectEqualStrings("audit_unavailable_by_preferences", issue.get("cause").?.string);
    try std.testing.expect(parsed.value.object.get("allowed").?.bool);
    try std.testing.expectEqualStrings("warn", issue.get("severity").?.string);
    try std.testing.expectEqual(@as(?c_int, null), rejectInvalidConfiguration(st));
    // Both real submission paths reach argument validation, past the shared gate.
    var order: ?*anyopaque = null;
    try std.testing.expectEqual(@intFromEnum(DaResult.invalid_arg), da_order_submit(handle, "", "fixture", null, &order));
    try std.testing.expectEqual(@intFromEnum(DaResult.invalid_arg), da_order_submit_async(handle, "", "fixture", null, &order));
    // Python uses the existing local planner short circuit: real order creation,
    // no provider call, no dispatch and no audit verdict fabricated by this test.
    try std.testing.expectEqual(@as(c_int, 0), da_order_submit(handle, "crea hola.py en Python", "fixture", null, &order));
    try std.testing.expect(order != null);
    try st.catalog.db.exec("DELETE FROM api_keys WHERE provider_id=(SELECT id FROM providers WHERE name='Cohere')");
    try std.testing.expect(rejectInvalidConfiguration(st) != null);
    const blocked_body = try configurationJson(st, a);
    defer a.free(blocked_body);
    const blocked = try std.json.parseFromSlice(std.json.Value, a, blocked_body, .{});
    defer blocked.deinit();
    try std.testing.expect(!blocked.value.object.get("allowed").?.bool);
    try std.testing.expectEqualStrings("missing_key", blocked.value.object.get("issues").?.array.items[0].object.get("cause").?.string);
}

