/// additive pins for specialist roles; same provider/model as the
/// existing executor/auditor setters. Stored in catalog settings, frozen per order.
pub export fn da_role_set_model(handle: ?*anyopaque, role_ptr: ?[*:0]const u8, provider_ptr: ?[*:0]const u8, model_ptr: ?[*:0]const u8) callconv(.c) c_int {
    const h = handle orelse return @intFromEnum(err(.invalid_arg, "da_role_set_model: null handle"));
    const role = if (role_ptr) |p| std.mem.span(p) else return @intFromEnum(err(.invalid_arg, "da_role_set_model: null role"));
    const provider = if (provider_ptr) |p| std.mem.span(p) else "";
    const model = if (model_ptr) |p| std.mem.span(p) else "";
    const st: *CoreState = @ptrCast(@alignCast(h));
    const a = st.arena.child_allocator;
    const roles = @import("composer_roles.zig");
    if (!roles.validRole(role) or (provider.len == 0) != (model.len == 0) or provider.len > 256 or model.len > 1024 or
        !std.unicode.utf8ValidateSlice(provider) or !std.unicode.utf8ValidateSlice(model))
        return @intFromEnum(err(.invalid_arg, "rol o pin incompleto"));
    st.external_mutex.lock();
    defer st.external_mutex.unlock();
    if (provider.len > 0) {
        const external = (external_registry.lastKnown(a, st.catalog.db, health.nowSeconds(st.catalog.db)) catch
            return @intFromEnum(err(.internal, "catalogo CLI no disponible"))) orelse (a.dupe(u8, "[]") catch return @intFromEnum(err(.oom, "OOM")));
        defer a.free(external);
        const chat = if (external_agents.isAgentProvider(provider))
            (@import("model_selection.zig").externalEligibility(a, external, provider, model) catch return @intFromEnum(err(.invalid_arg, "capacidad CLI desconocida"))).chat
        else
            @import("model_selection.zig").catalogTextGeneration(st.catalog.db, provider, model) catch return @intFromEnum(err(.internal, "capacidad no disponible"));
        if (!chat) return @intFromEnum(err(.invalid_arg, "el rol requiere un modelo de chat"));
        const mode = external_registry.readSetting(a, st.catalog.db, "governance_mode") catch return @intFromEnum(err(.internal, "gobernanza no disponible"));
        defer a.free(mode);
        const requested = [_]@import("order_preflight.zig").Role{.{ .role = if (std.mem.eql(u8, role, "second_audit")) "auditor" else "ejecutor", .provider = provider, .model = model }};
        const conflicts = @import("order_preflight.zig").check(a, st.catalog.db, model_router.GovernanceMode.parse(mode), &requested, external, st.db_conn) catch
            return @intFromEnum(err(.internal, "no se pudo comprobar el pin"));
        defer a.free(conflicts);
        if (!@import("order_preflight.zig").allowed(conflicts)) return @intFromEnum(err(.invalid_arg, "modelo bloqueado: revisa capacidad, disponibilidad y gobernanza"));
    }
    roles.set(a, st.catalog.db, role, provider, model) catch |e| return @intFromEnum(err(.invalid_arg, @errorName(e)));
    return @intFromEnum(ok());
}

pub export fn da_role_models_json(handle: ?*anyopaque, out_json: ?*?[*:0]const u8) callconv(.c) c_int {
    const h = handle orelse return @intFromEnum(err(.invalid_arg, "da_role_models_json: null handle"));
    const out = out_json orelse return @intFromEnum(err(.invalid_arg, "da_role_models_json: null output"));
    const st: *CoreState = @ptrCast(@alignCast(h));
    const a = st.arena.child_allocator;
