    try st.catalog.db.exec("INSERT INTO providers(name,base_url,api_style,is_free_tier,is_local) VALUES('prv003-local','fixture','openai',1,1)");
    try st.catalog.db.exec("INSERT INTO models(provider_id,model_name,context_window,is_free,is_generative,available) SELECT id,'chat-fixture',128000,1,1,1 FROM providers WHERE name='prv003-local'");
    try std.testing.expectEqual(@as(c_int, 0), da_role_set_model(h, "programmer", "prv003-local", "chat-fixture"));
    var stored: ?[*:0]const u8 = null;
    try std.testing.expectEqual(@as(c_int, 0), da_role_models_json(h, &stored));
    defer da_string_free(@constCast(stored.?));
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(stored.?), "chat-fixture") != null);
    try std.testing.expect(da_role_set_model(h, "sidekick", "prv003-local", "embedding-fixture") != 0);
    var enabled: c_int = 0;
    try std.testing.expectEqual(@as(c_int, 0), da_swarm_set_enabled(h, 0));
    try std.testing.expectEqual(@as(c_int, 0), da_swarm_get_enabled(h, &enabled));
    try std.testing.expectEqual(@as(c_int, 0), enabled);
    try std.testing.expectEqual(@as(c_int, 0), da_swarm_set_enabled(h, 1));
    try std.testing.expectEqual(@as(c_int, 0), da_swarm_get_enabled(h, &enabled));
    try std.testing.expectEqual(@as(c_int, 1), enabled);
    try std.testing.expect(da_role_set_model(h, "unknown", "", "") != 0);
    try std.testing.expect(da_role_set_model(h, "programmer", "p", "") != 0);
    try std.testing.expectEqual(@as(c_int, 0), da_role_set_model(h, "programmer", "", ""));
    var json: ?[*:0]const u8 = null;
    try std.testing.expectEqual(@as(c_int, 0), da_role_models_json(h, &json));
    defer da_string_free(@constCast(json.?));
    try std.testing.expectEqualStrings("[]", std.mem.span(json.?));
}

pub export fn da_swarm_set_enabled(handle: ?*anyopaque, enabled: c_int) callconv(.c) c_int {
    const h = handle orelse return @intFromEnum(err(.invalid_arg, "da_swarm_set_enabled: null handle"));
    const st: *CoreState = @ptrCast(@alignCast(h));
    st.external_mutex.lock();
    defer st.external_mutex.unlock();
    @import("composer_roles.zig").setSwarmEnabled(st.catalog.db, enabled != 0) catch return @intFromEnum(err(.internal, "no se pudo cambiar el enjambre"));
    return @intFromEnum(ok());
}

pub export fn da_swarm_get_enabled(handle: ?*anyopaque, out_enabled: ?*c_int) callconv(.c) c_int {
    const h = handle orelse return @intFromEnum(err(.invalid_arg, "da_swarm_get_enabled: null handle"));
    const out = out_enabled orelse return @intFromEnum(err(.invalid_arg, "da_swarm_get_enabled: null output"));
    const st: *CoreState = @ptrCast(@alignCast(h));
    st.external_mutex.lock();
    defer st.external_mutex.unlock();
    out.* = @intFromBool(@import("composer_roles.zig").swarmEnabled(st.catalog.db) catch return @intFromEnum(err(.internal, "no se pudo leer el enjambre")));
    return @intFromEnum(ok());
}

pub export fn da_composer_review_json(handle: ?*anyopaque, out_json: ?*?[*:0]const u8) callconv(.c) c_int {
    const h = handle orelse return @intFromEnum(err(.invalid_arg, "da_composer_review_json: null handle"));
    const out = out_json orelse return @intFromEnum(err(.invalid_arg, "da_composer_review_json: null output"));
    _ = h;
    // The composer has no routed order. Its pins are not effective models.
    out.* = ownedCStr("{\"mode\":\"undecided\",\"label\":\"Revisión por decidir\",\"pending_verdict\":true}") orelse return @intFromEnum(err(.oom, "OOM"));
    return @intFromEnum(ok());
}

// H7 r5 (auditoría el segundo auditor lote AH, P2): mcpLimitHardens(0, 0) debe
// ser true — un eje ya ilimitado que no cambia no impide endurecer otro eje,
// como prometía el comentario de da_external_limits_set.
test "CK-SEG-012 H7 r5 an unchanged unlimited axis does not block hardening another axis" {
    try std.testing.expect(mcpLimitHardens(u64, 0, 5));
    try std.testing.expect(mcpLimitHardens(u64, 5, 5));
    try std.testing.expect(mcpLimitHardens(u64, 5, 1));
    try std.testing.expect(!mcpLimitHardens(u64, 5, 10));
    try std.testing.expect(!mcpLimitHardens(u64, 5, 0));
    try std.testing.expect(mcpLimitHardens(u64, 0, 0));
    // Sobre la superficie real: la cabina pone task_timeout_ms a 0 (sin tope);
    // después un cliente MCP bajando task_max_turns no debe tropezar con ese
    // eje ilimitado intacto, y sigue sin poder subir ningún tope.
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    try std.testing.expectEqual(@as(c_int, 0), da_external_limits_set(handle, "{\"task_timeout_ms\":0}"));
    try std.testing.expectEqual(@as(c_int, 0), da_set_mcp_surface(handle));
    try std.testing.expectEqual(@as(c_int, 0), da_external_limits_set(handle, "{\"task_max_turns\":5}"));
    try std.testing.expect(da_external_limits_set(handle, "{\"task_max_turns\":99}") != 0);
    try seg012ExpectCabinaError();
    // Quitar un tope vigente (poner 0) sigue exigiendo la cabina.
    try std.testing.expect(da_external_limits_set(handle, "{\"task_max_turns\":0}") != 0);
    try seg012ExpectCabinaError();
}

// H13 r5 (auditoría el segundo auditor lote AH, P1-b): lo que se reanuda tras
// aprobar es el exe y el argv ORIGINALES byte a byte — no el texto saneado de
// la tarjeta (renderCommandLine escapa saltos, bidi y barras inversas).
var r5_resume_exe: ?[]u8 = null;
var r5_resume_args: std.ArrayList([]const u8) = .empty;

fn r5ApprovalResumeCapture(_: std.mem.Allocator, exe: []const u8, args: []const []const u8, _: []const u8, _: u32, _: usize, _: ?executor.StreamSink, _: ?*anyopaque, _: []const u8) executor.ExecutorError!executor.RunResult {
    // El mock copia con testing.allocator (el caller del spawn es el arena del
    // estado; liberarlo con otro allocator corrompería el cierre del core).
    const a = std.testing.allocator;
    r5_resume_exe = a.dupe(u8, exe) catch null;
    for (args) |arg| {
        const copy = a.dupe(u8, arg) catch break;
        r5_resume_args.append(a, copy) catch {
            a.free(copy);
            break;
        };
    }
    return .{ .exit_code = 0, .stdout = &.{}, .stderr = &.{} };
}

test "CK-SEG-012 H13 r5 approval resume relaunches the exact original exe and args, never the card text" {
    const allocator = std.testing.allocator;
    const argv = [_][]const u8{
        "-c",
        "print('x')\nprint(2)",
        "literal\\ntext",
        "bidi\u{202E}tail",
        "C:\\path\\file.txt",
        "\u{206A}ignorable",
    };
    const json = try std.json.Stringify.valueAlloc(allocator, .{ .exe = "python", .args = argv[0..] }, .{});
    defer allocator.free(json);
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle));
    // Toda la cadena de aprobación (description, payload, worker_outputs) se
    // allocará y liberará con el arena del estado, como en producción.
    const aa = st.arena.child_allocator;
    const res = try shellRunJson(aa, json, null, st);
    defer res.deinit(aa);
    try std.testing.expect(res.approval_id != null);
    // La tarjeta publicada muestra el texto saneado (saltos y bidi escapados).
    var pending: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_approval_pending_json(handle, &pending));
    defer da_string_free(pending);
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(pending), "\\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(pending), "\\u{202E}") != null);
    // La reanudación entrega el argv original byte a byte.
    if (r5_resume_exe) |e| allocator.free(e);
    for (r5_resume_args.items) |arg| allocator.free(arg);
    r5_resume_args.clearRetainingCapacity();
    // El caller de producción pasa el arena del estado; hay que imitarlo para
    // que los worker_outputs que registra la reanudación se liberen con el
    // allocator correcto en da_core_shutdown.
    try resumeExecutionApproval(st, st.arena.child_allocator, res.approval_id.?, r5ApprovalResumeCapture);
    defer {
        if (r5_resume_exe) |e| allocator.free(e);
        for (r5_resume_args.items) |arg| allocator.free(arg);
        r5_resume_args.deinit(allocator);
        r5_resume_args = .empty;
    }
    try std.testing.expect(r5_resume_exe != null);
    try std.testing.expectEqualStrings("python", r5_resume_exe.?);
    try std.testing.expectEqual(@as(usize, argv.len), r5_resume_args.items.len);
    for (argv, 0..) |expected, i| {
        try std.testing.expectEqualStrings(expected, r5_resume_args.items[i]);
    }
}

test "CK-MCP-004 C-ABI credential helper failures never expose secrets in output or last_error" {
    const Fixture = struct {
        const secret = "mcp004-r2-synthetic-secret";
        const Mode = enum { approve_failed, approve_error, fill_failed, fill_error, mismatch, stored };
        var mode: Mode = .approve_failed;
        var calls: usize = 0;

        fn capture(a: std.mem.Allocator, argv: []const []const u8, cwd: ?[]const u8) !providers.github.CmdCapture {
            try std.testing.expect(cwd == null);
            try std.testing.expectEqual(@as(usize, 3), argv.len);
            try std.testing.expectEqualStrings("git", argv[0]);
            try std.testing.expectEqualStrings("credential", argv[1]);
            for (argv) |arg| try std.testing.expect(std.mem.indexOf(u8, arg, secret) == null);
            calls += 1;
            const approve = std.mem.eql(u8, argv[2], "approve");
            try std.testing.expect(approve or std.mem.eql(u8, argv[2], "fill"));
            try std.testing.expectEqual(if (approve) @as(usize, 1) else 2, calls);
            if ((approve and mode == .approve_error) or (!approve and mode == .fill_error)) return error.FixtureHelperUnavailable;
            const failed = (approve and mode == .approve_failed) or (!approve and mode == .fill_failed);
            const stdout = if (failed) "helper stdout: " ++ secret else if (approve) "" else if (mode == .mismatch) "password=other-synthetic-value\n" else "username=fixture\npassword=" ++ secret ++ "\n";
            const out = try a.dupe(u8, stdout);
            errdefer a.free(out);
            return .{
                .exit_code = if (failed) 37 else 0,
                .stdout = out,
                .stderr = try a.dupe(u8, "helper stderr: " ++ secret),
            };
        }
    };

    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    const st: *CoreState = @ptrCast(@alignCast(handle.?));
    st.gh_capture_fn = Fixture.capture;
    const request = "{\"host\":\"forge.invalid\",\"username\":\"fixture\",\"password\":\"" ++ Fixture.secret ++ "\"}";

    for (std.enums.values(Fixture.Mode)) |mode| {
        Fixture.mode = mode;
        Fixture.calls = 0;
        // A failed call must leave the caller's output untouched.
        var sentinel = [_:0]u8{0};
        var output: [*:0]u8 = &sentinel;
        const result = da_git_store_credential(handle, request, &output);
        const failed = mode == .approve_failed or mode == .approve_error or mode == .fill_error;
        defer if (!failed) da_string_free(output);
        try std.testing.expectEqual(if (failed) @intFromEnum(DaResult.internal) else @as(c_int, 0), result);
        if (failed) {
            try std.testing.expect(output == &sentinel);
        } else {
            try std.testing.expect(std.mem.indexOf(u8, std.mem.span(output), Fixture.secret) == null);
            try std.testing.expectEqualStrings(if (mode == .stored) "{\"stored\":true,\"host\":\"forge.invalid\"}" else "{\"stored\":false,\"host\":\"forge.invalid\"}", std.mem.span(output));
        }
        try std.testing.expect(std.mem.indexOf(u8, std.mem.span(output), Fixture.secret) == null);
        try std.testing.expect(std.mem.indexOf(u8, last_error_buf[0..last_error_len], Fixture.secret) == null);
        var last: [*:0]u8 = undefined;
        try std.testing.expectEqual(@as(c_int, 0), da_last_error(&last));
        defer da_string_free(last);
        const message = std.mem.span(last);
        try std.testing.expect(std.mem.indexOf(u8, message, Fixture.secret) == null);
        try std.testing.expect(std.mem.indexOf(u8, message, "helper stdout") == null);
        try std.testing.expect(std.mem.indexOf(u8, message, "helper stderr") == null);
        if (mode == .approve_failed) try std.testing.expectEqualStrings("git credential approve salio 37; no se pudo guardar la credencial", message);
        if (mode == .approve_error) try std.testing.expect(std.mem.indexOf(u8, message, "git credential approve:") != null);
        if (mode == .fill_error) try std.testing.expect(std.mem.indexOf(u8, message, "git credential fill:") != null);
        if (!failed) try std.testing.expectEqual(@as(usize, 0), message.len);
        try std.testing.expectEqual(if (mode == .approve_failed or mode == .approve_error) @as(usize, 1) else 2, Fixture.calls);
    }

    // Invalid input is rejected before calling the helper; diagnostics never echo it.
    for ([_][*:0]const u8{
        "{\"password\":\"" ++ Fixture.secret ++ "\",",
        "\"" ++ Fixture.secret ++ "\"",
        "{\"host\":\"forge.invalid/path\",\"username\":\"fixture\",\"password\":\"" ++ Fixture.secret ++ "\"}",
        "{\"host\":\"forge.invalid\",\"username\":\"fixture\",\"password\":\"" ++ Fixture.secret ++ "\\nextra=value\"}",
    }) |invalid| {
        Fixture.calls = 0;
        var sentinel = [_:0]u8{0};
        var output: [*:0]u8 = &sentinel;
        try std.testing.expectEqual(@intFromEnum(DaResult.invalid_arg), da_git_store_credential(handle, invalid, &output));
        try std.testing.expect(output == &sentinel);
        try std.testing.expectEqual(@as(usize, 0), Fixture.calls);
        try std.testing.expect(std.mem.indexOf(u8, last_error_buf[0..last_error_len], Fixture.secret) == null);
        var last: [*:0]u8 = undefined;
        try std.testing.expectEqual(@as(c_int, 0), da_last_error(&last));
        defer da_string_free(last);
        try std.testing.expect(std.mem.indexOf(u8, std.mem.span(last), Fixture.secret) == null);
        try std.testing.expect(std.mem.span(last).len > 0);
    }
}

test "T7 cuentas C-ABI: la cabina lista y elige; un núcleo MCP no toca cuentas" {
    var handle: ?*anyopaque = null;
    try std.testing.expectEqual(@as(c_int, 0), da_core_init(&handle, ":memory:"));
    defer _ = da_core_shutdown(handle);
    var out: [*:0]u8 = undefined;
    try std.testing.expectEqual(@as(c_int, 0), da_cli_accounts_json(handle, &out));
    const listed = std.mem.span(out);
    try std.testing.expect(std.mem.indexOf(u8, listed, "\"CODEX_HOME\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, listed, "\"CLAUDE_CONFIG_DIR\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, listed, "\"opencode\"") != null);
    da_string_free(out);
    // Sin carpeta de datos (base en memoria) no se crean carpetas de cuenta.
    try std.testing.expect(da_cli_account_add(handle, "{\"cli\":\"codex\",\"label\":\"Trabajo\"}") != 0);
    try std.testing.expect(da_cli_account_select(handle, "{\"cli\":\"codex\",\"id\":\"codex-9\"}") != 0);
    try std.testing.expectEqual(@as(c_int, 0), da_cli_account_select(handle, "{\"cli\":\"codex\",\"id\":null}"));
    try std.testing.expectEqual(@as(c_int, 0), da_set_mcp_surface(handle));
    try std.testing.expect(da_cli_accounts_json(handle, &out) != 0);
    try std.testing.expect(da_cli_account_select(handle, "{\"cli\":\"codex\",\"id\":null}") != 0);
    try std.testing.expect(da_project_rules_set(handle, "{\"reset\":true}") != 0);
}
